class _TransportStormLogFilter(logging.Filter):
    """Keep useful transport warnings without allowing per-request log floods."""
    def __init__(self) -> None:
        super().__init__()
        self._last_allowed: Dict[str, float] = {}

    def filter(self, record: logging.LogRecord) -> bool:
        try:
            message = record.getMessage()
        except Exception:
            return True
        lower = message.lower()

        # SPlusthon can dump one line per pending RPC when a websocket closes.
        # A single disconnect previously produced millions of PingRequest lines.
        if "pending msg " in lower:
            return False

        key = ""
        interval = 0.0
        if "wrong session id" in lower:
            key, interval = "wrong-session", 30.0
        elif "connection closed while receiving data" in lower:
            key, interval = "connection-closed", 10.0
        elif "websocket closed while reading" in lower:
            key, interval = "websocket-closed", 10.0
        elif "chat admin privileges are required" in lower and "rpc error for msg" in lower:
            key, interval = "rpc-admin-required", 3.0
        elif "you can't write in this chat" in lower and "rpc error for msg" in lower:
            key, interval = "rpc-write-forbidden", 3.0
        elif "the channel specified is private" in lower and "rpc error for msg" in lower:
            key, interval = "rpc-channel-private", 5.0
        elif "manual moderation permission denied" in lower:
            match = re.search(r"group=([^ ]+)", lower)
            key, interval = f"mod-permission:{match.group(1) if match else '?'}", 10.0
        elif "pending auto activation wait" in lower:
            match = re.search(r"group=([^ ]+).*reason=([^ ]+)", lower)
            key, interval = f"activation-wait:{match.group(1)}:{match.group(2)}" if match else "activation-wait", 15.0
        elif "group send-access probe failed" in lower:
            match = re.search(r"group=([^ ]+)", lower)
            key, interval = f"send-probe:{match.group(1) if match else '?'}", 12.0

        if not key:
            return True
        now = time.monotonic()
        previous = float(self._last_allowed.get(key, 0.0) or 0.0)
        if previous and now - previous < interval:
            return False
        self._last_allowed[key] = now
        return True

_transport_storm_filter = _TransportStormLogFilter()
for _handler in logging.getLogger().handlers:
    _handler.addFilter(_transport_storm_filter)

