def _is_group_hard_unavailable_error(exc: BaseException) -> bool:
    text = f"{type(exc).__name__}: {exc}".upper()
    return any(token in text for token in (
        "CHANNELPRIVATE",
        "CHATWRITEFORBIDDEN",
        "YOU CAN'T WRITE IN THIS CHAT",
        "PRIVATE AND YOU LACK PERMISSION",
        "YOU WERE BANNED",
        "CHAT_WRITE_FORBIDDEN",
    ))


def _group_send_hard_backoff_active(group: Any) -> bool:
    gid = canonical_anti_spam_group_id(
        safe_int(getattr(group, "id", None))
        or safe_int(getattr(group, "channel_id", None))
        or safe_int(getattr(group, "chat_id", None))
        or (int(group) if isinstance(group, int) else None)
    )
    if gid is None:
        return False
    return time.monotonic() < float(_group_send_probe_retry_after.get(int(gid), 0.0) or 0.0)


def _mark_group_send_hard_backoff(group: Any, seconds: float = 300.0) -> None:
    gid = canonical_anti_spam_group_id(
        safe_int(getattr(group, "id", None))
        or safe_int(getattr(group, "channel_id", None))
        or safe_int(getattr(group, "chat_id", None))
        or (int(group) if isinstance(group, int) else None)
    )
    if gid is not None:
        _group_send_probe_retry_after[int(gid)] = time.monotonic() + max(30.0, float(seconds))


