# 96.53 subscription-aware response scheduling. No tier receives an artificial
# idle delay: the difference is applied only when handlers or transport sends
# compete. Stable sequence numbers preserve FIFO order inside one tier.
TIER_RESPONSE_PRIORITY = {
    premium.PLAN_DIAMOND: 0,
    premium.PLAN_GOLD: 1,
    premium.PLAN_SILVER: 2,
    premium.PLAN_FREE: 3,
}
TIER_RESPONSE_NAMES = {0: "diamond", 1: "gold", 2: "silver", 3: "free"}
_tier_response_sequence = itertools.count()


def group_response_priority(group_id: Any) -> int:
    gid = canonical_anti_spam_group_id(safe_int(group_id))
    if gid is None:
        return TIER_RESPONSE_PRIORITY[premium.PLAN_FREE]
    try:
        plan = premium.normalize_plan(premium.plan_for_group(int(gid))) or premium.PLAN_FREE
    except Exception as exc:
        log.debug("tier response lookup failed | group=%s | %s: %s", gid, type(exc).__name__, exc)
        plan = premium.PLAN_FREE
    return int(TIER_RESPONSE_PRIORITY.get(plan, TIER_RESPONSE_PRIORITY[premium.PLAN_FREE]))


def group_response_priority_for_event(event: Any) -> int:
    return group_response_priority(getattr(event, "chat_id", None))


def tier_response_eager_limit(priority: int) -> int:
    rank = max(0, min(3, int(priority)))
    if rank == 0:
        return PRIORITY_EAGER_TASK_HARD_LIMIT
    if rank == 1:
        return PRIORITY_EAGER_TASK_SOFT_LIMIT
    if rank == 2:
        return max(24, (PRIORITY_EAGER_TASK_SOFT_LIMIT * 2) // 3)
    return max(16, PRIORITY_EAGER_TASK_SOFT_LIMIT // 3)


def tier_response_queue_item(event: Any, priority: Optional[int] = None) -> Tuple[int, int, Any]:
    rank = group_response_priority_for_event(event) if priority is None else max(0, min(3, int(priority)))
    return (rank, next(_tier_response_sequence), event)


def tier_response_queue_event(item: Any) -> Any:
    if isinstance(item, tuple) and len(item) == 3 and isinstance(item[0], int) and isinstance(item[1], int):
        return item[2]
    return item


def replace_worst_tier_queue_item(queue: Any, item: Tuple[int, int, Any]) -> bool:
    """Replace a queued lower-tier event without changing unfinished-task count."""
    heap = getattr(queue, "_queue", None)
    if not isinstance(heap, list) or not heap:
        return False
    worst_index = max(range(len(heap)), key=lambda index: (int(heap[index][0]), int(heap[index][1])))
    worst = heap[worst_index]
    if (int(item[0]), int(item[1])) >= (int(worst[0]), int(worst[1])):
        return False
    heap[worst_index] = item
    heapq.heapify(heap)
    return True

