class _ZivoSQLiteConnection(sqlite3.Connection):
    """Connection whose context manager also closes the file descriptor.

    sqlite3.Connection.__exit__ commits/rolls back but intentionally leaves the
    connection open. ZIVO uses short `with db_connect()` blocks throughout the
    realtime router, so leaving those handles open leaks one database FD per
    operation until SQLite and network sockets can no longer be opened.
    """

    def __exit__(self, exc_type, exc_value, traceback):
        try:
            return super().__exit__(exc_type, exc_value, traceback)
        finally:
            self.close()


def db_connect() -> sqlite3.Connection:
    con = sqlite3.connect(
        DB_PATH,
        timeout=5.0,
        cached_statements=512,
        factory=_ZivoSQLiteConnection,
    )
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA busy_timeout = 5000")
    con.execute("PRAGMA synchronous = NORMAL")
    con.execute("PRAGMA temp_store = MEMORY")
    con.execute("PRAGMA mmap_size = 134217728")
    return con


def global_profile_db_connect() -> sqlite3.Connection:
    """Bounded shared identity connection used only for manual profile state.

    The multi-account control DB is also used by join routing.  96.13 executed
    PRAGMA journal_mode=WAL on every profile connection and mirrored observed
    names into this DB continuously.  Under three live accounts that can turn a
    harmless profile read into a synchronous SQLite writer/lock and stall the
    foreground command lane.  WAL is initialized once by the control DB setup;
    ordinary profile connections stay read/write but never renegotiate journal
    mode and never wait several seconds in a live handler.
    """
    con = sqlite3.connect(
        MULTI_ACCOUNT_DB,
        timeout=0.75,
        cached_statements=256,
        factory=_ZivoSQLiteConnection,
    )
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA busy_timeout = 750")
    con.execute("PRAGMA synchronous = NORMAL")
    return con


def init_shared_global_identity_store() -> None:
    now_iso = datetime.now(timezone.utc).isoformat()
    with global_profile_db_connect() as shared:
        shared.execute(
            """
            CREATE TABLE IF NOT EXISTS global_user_profiles (
                user_id INTEGER PRIMARY KEY,
                preferred_name TEXT NOT NULL DEFAULT '',
                nickname TEXT NOT NULL DEFAULT '',
                observed_name TEXT NOT NULL DEFAULT '',
                username TEXT NOT NULL DEFAULT '',
                age INTEGER NOT NULL DEFAULT 0,
                origin TEXT NOT NULL DEFAULT '',
                first_seen_at TEXT NOT NULL,
                last_seen_at TEXT NOT NULL,
                updated_at TEXT NOT NULL
            )
            """
        )
        shared.execute(
            "CREATE INDEX IF NOT EXISTS idx_global_user_profiles_seen ON global_user_profiles(last_seen_at DESC)"
        )
        shared.execute(
            """
            CREATE TABLE IF NOT EXISTS global_origin_registration (
                user_id INTEGER PRIMARY KEY,
                stage TEXT NOT NULL,
                preferred_name TEXT NOT NULL DEFAULT '',
                nickname TEXT NOT NULL DEFAULT '',
                age INTEGER NOT NULL DEFAULT 0,
                origin TEXT NOT NULL DEFAULT '',
                context_kind TEXT NOT NULL DEFAULT 'private',
                context_id INTEGER NOT NULL DEFAULT 0,
                updated_at TEXT NOT NULL
            )
            """
        )
        shared.execute(
            "CREATE INDEX IF NOT EXISTS idx_global_origin_registration_updated ON global_origin_registration(updated_at DESC)"
        )
        shared.commit()

    # Historical per-account identity rows are intentionally NOT bulk-copied at
    # startup. 96.13 looped through every profile for main/acc2/acc3 before the
    # service became ready, which can delay READY markers and contend with join
    # routing. get_global_user_profile() performs a bounded lazy seed only when a
    # legacy manual profile is actually requested.



