def get_group_backup_settings(group_id: int) -> Dict[str, Any]:
    with db_connect() as con:
        row = con.execute(
            """
            SELECT enabled, interval_minutes, keep_count,
                   last_backup_at, last_backup_file,
                   last_backup_rows, last_backup_sha256
            FROM group_backup_settings
            WHERE group_id = ?
            """,
            (int(group_id),),
        ).fetchone()

    if row is None:
        return {
            "enabled": True,
            "interval_minutes": 60,
            "keep_count": 12,
            "last_backup_at": None,
            "last_backup_file": "",
            "last_backup_rows": 0,
            "last_backup_sha256": "",
        }

    return {
        "enabled": bool(int(row["enabled"] or 0)),
        "interval_minutes": max(5, min(1440, int(row["interval_minutes"] or 60))),
        "keep_count": max(5, min(500, int(row["keep_count"] or 12))),
        "last_backup_at": row["last_backup_at"],
        "last_backup_file": row["last_backup_file"] or "",
        "last_backup_rows": int(row["last_backup_rows"] or 0),
        "last_backup_sha256": row["last_backup_sha256"] or "",
    }


def refresh_role_membership_cache(group_id: int) -> None:
    gid = int(group_id)
    with db_connect() as con:
        admin_ids = {int(row[0]) for row in con.execute("SELECT user_id FROM bot_admins WHERE group_id = ?", (gid,)).fetchall()}
        special_ids = {int(row[0]) for row in con.execute("SELECT user_id FROM bot_specials WHERE group_id = ?", (gid,)).fetchall()}
        exempt_ids = {int(row[0]) for row in con.execute("SELECT user_id FROM bot_exemptions WHERE group_id = ?", (gid,)).fetchall()}
    _bot_admin_member_hot[gid] = admin_ids
    _bot_special_member_hot[gid] = special_ids
    _bot_exempt_member_hot[gid] = exempt_ids
    _role_membership_cache_ready.add(gid)


def prime_hot_runtime_state() -> Dict[str, int]:
    now = time.monotonic()
    now_iso = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        installations = con.execute("SELECT * FROM installations").fetchall()
        installed_ids = {int(row["group_id"]) for row in installations}
        for row in installations:
            _installation_hot_cache[int(row["group_id"])] = (now, dict(row))

        admin_map: Dict[int, set[int]] = {gid: set() for gid in installed_ids}
        for row in con.execute("SELECT group_id, user_id FROM bot_admins").fetchall():
            admin_map.setdefault(int(row["group_id"]), set()).add(int(row["user_id"]))
        special_map: Dict[int, set[int]] = {gid: set() for gid in installed_ids}
        for row in con.execute("SELECT group_id, user_id FROM bot_specials").fetchall():
            special_map.setdefault(int(row["group_id"]), set()).add(int(row["user_id"]))
        exempt_map: Dict[int, set[int]] = {gid: set() for gid in installed_ids}
        for row in con.execute("SELECT group_id, user_id FROM bot_exemptions").fetchall():
            exempt_map.setdefault(int(row["group_id"]), set()).add(int(row["user_id"]))

        special_default_map = {
            (int(row["group_id"]), str(row["lock_name"])): bool(int(row["bypass_enabled"] or 0))
            for row in con.execute(
                "SELECT group_id, lock_name, bypass_enabled FROM special_lock_defaults"
            ).fetchall()
        }
        special_override_map = {
            (int(row["group_id"]), int(row["user_id"]), str(row["lock_name"])): bool(int(row["bypass_enabled"] or 0))
            for row in con.execute(
                "SELECT group_id, user_id, lock_name, bypass_enabled FROM special_lock_overrides"
            ).fetchall()
        }

        lock_map: Dict[int, Dict[str, sqlite3.Row]] = {gid: {} for gid in installed_ids}
        for row in con.execute("SELECT * FROM group_locks").fetchall():
            lock_map.setdefault(int(row["group_id"]), {})[str(row["lock_name"])] = row

        power_rows = {int(row["group_id"]): row for row in con.execute("SELECT * FROM group_bot_power").fetchall()}

        phrase_map: Dict[int, List[Tuple[str, str, str]]] = {gid: [] for gid in installed_ids}
        for row in con.execute(
            "SELECT group_id, phrase_norm, phrase_display FROM filtered_phrases ORDER BY group_id, LENGTH(phrase_norm) DESC, phrase_norm ASC"
        ).fetchall():
            phrase_norm = str(row["phrase_norm"])
            phrase_map.setdefault(int(row["group_id"]), []).append((
                phrase_norm,
                str(row["phrase_display"]),
                normalize_filter_abuse_text(phrase_norm)[1],
            ))

        flood_rows = {int(row["group_id"]): row for row in con.execute(
            "SELECT group_id, enabled, burst_limit, window_seconds, consecutive_limit, cleanup_scan_limit FROM flood_guard_settings"
        ).fetchall()}

        close_manual = {int(row["group_id"]): bool(int(row["manual_closed"] or 0)) for row in con.execute(
            "SELECT group_id, manual_closed FROM group_close_state"
        ).fetchall()}
        active_schedule_ids = {int(row["group_id"]) for row in con.execute(
            "SELECT DISTINCT group_id FROM group_close_schedules WHERE start_at <= ? AND end_at > ?",
            (now_iso, now_iso),
        ).fetchall()}
    try:
        with global_profile_db_connect() as shared_identity:
            origin_registration_rows = shared_identity.execute(
                "SELECT user_id, context_kind, context_id FROM global_origin_registration"
            ).fetchall()
    except Exception:
        origin_registration_rows = []

    _global_origin_registration_pending.clear()
    _global_origin_registration_pending.update({
        int(row["user_id"]): (str(row["context_kind"] or "private"), int(row["context_id"] or 0))
        for row in origin_registration_rows
        if int(row["user_id"] or 0) > 0
    })
    _bot_admin_member_hot.clear(); _bot_admin_member_hot.update(admin_map)
    _bot_special_member_hot.clear(); _bot_special_member_hot.update(special_map)
    _bot_exempt_member_hot.clear(); _bot_exempt_member_hot.update(exempt_map)
    _role_membership_cache_ready.clear(); _role_membership_cache_ready.update(installed_ids)
    _special_lock_default_hot.clear(); _special_lock_default_hot.update(special_default_map)
    _special_lock_override_hot.clear(); _special_lock_override_hot.update(special_override_map)
    _special_lock_override_absent_hot.clear()

    for gid in installed_ids:
        _group_lock_rows_hot_cache[int(gid)] = (now, dict(lock_map.get(gid, {})))
        _filtered_phrase_cache[int(gid)] = (now, tuple(phrase_map.get(gid, [])))
        _group_close_block_hot_cache[int(gid)] = (now, bool(close_manual.get(gid, False) or gid in active_schedule_ids))
        _group_activity_touch_cache[int(gid)] = now

        flood_row = flood_rows.get(gid)
        if flood_row is None:
            flood_state = dict(FLOOD_GUARD_DEFAULTS)
        else:
            flood_state = {
                "enabled": 1 if int(flood_row["enabled"] or 0) else 0,
                "burst_limit": max(6, min(50, int(flood_row["burst_limit"] or 10))),
                "window_seconds": max(3, min(60, int(flood_row["window_seconds"] or 10))),
                "consecutive_limit": max(5, min(30, int(flood_row["consecutive_limit"] or 7))),
                "cleanup_scan_limit": 0 if int(flood_row["cleanup_scan_limit"] or 0) == 0 else max(200, min(10000, int(flood_row["cleanup_scan_limit"]))),
            }
        _flood_guard_settings_hot_cache[int(gid)] = (now, flood_state)

        row = power_rows.get(gid)
        if row is None:
            state = {"enabled": True, "expires_at": None, "expire_to_enabled": None, "peer_kind": "channel", "group_access_hash": 0, "updated_by": 0, "updated_at": ""}
        else:
            state = {
                "enabled": bool(int(row["enabled"] or 0)),
                "expires_at": row["expires_at"],
                "expire_to_enabled": None if row["expire_to_enabled"] is None else bool(int(row["expire_to_enabled"] or 0)),
                "peer_kind": row["peer_kind"] or "channel",
                "group_access_hash": int(row["group_access_hash"] or 0),
                "updated_by": int(row["updated_by"] or 0),
                "updated_at": row["updated_at"] or "",
            }
        _group_power_hot_cache[int(gid)] = (now, state)

    return {
        "groups": len(installed_ids),
        "admins": sum(len(v) for v in admin_map.values()),
        "specials": sum(len(v) for v in special_map.values()),
        "exempts": sum(len(v) for v in exempt_map.values()),
        "locks": sum(len(v) for v in lock_map.values()),
        "phrases": sum(len(v) for v in phrase_map.values()),
        "flood": len(flood_rows),
        "closed": sum(1 for gid in installed_ids if close_manual.get(gid, False) or gid in active_schedule_ids),
    }


def invalidate_group_hot_caches(group_id: int) -> None:
    gid = int(group_id)
    _installation_hot_cache.pop(gid, None)
    _pending_group_activation_hot_cache.pop(gid, None)
    _group_power_hot_cache.pop(gid, None)
    _group_lock_rows_hot_cache.pop(gid, None)
    _group_enabled_lock_names_hot_cache.pop(gid, None)
    _group_close_block_hot_cache.pop(gid, None)
    _flood_guard_settings_hot_cache.pop(gid, None)
    _bot_message_cleanup_settings_hot_cache.pop(gid, None)
    _tag_cleanup_settings_hot_cache.pop(gid, None)
    _manual_warning_settings_hot_cache.pop(gid, None)
    _exact_content_filter_count_hot_cache.pop(gid, None)
    for cache in (_base_role_hot_cache, _exempt_hot_cache, _warning_repeat_level_hot_cache, _manual_warning_count_hot_cache):
        for key in [key for key in cache.keys() if int(key[0]) == gid]:
            cache.pop(key, None)
    # Special-lock defaults/overrides have no TTL.  Any bulk restore or
    # settings-copy must evict the group's old values immediately.
    for key in [key for key in _special_lock_default_hot if int(key[0]) == gid]:
        _special_lock_default_hot.pop(key, None)
    for key in [key for key in _special_lock_override_hot if int(key[0]) == gid]:
        _special_lock_override_hot.pop(key, None)
    for key in [key for key in _special_lock_override_absent_hot if int(key[0]) == gid]:
        _special_lock_override_absent_hot.discard(key)


def mark_group_backup_dirty(group_id: int, invalidate_hot: bool = True) -> None:
    if int(group_id) > 0:
        gid = int(group_id)
        if invalidate_hot:
            invalidate_group_hot_caches(gid)
        _group_backup_dirty[gid] = time.monotonic()


def set_group_backup_settings(
    group_id: int,
    actor_id: int,
    enabled: Optional[bool] = None,
    interval_minutes: Optional[int] = None,
    keep_count: Optional[int] = None,
) -> Dict[str, Any]:
    current = get_group_backup_settings(group_id)
    if enabled is not None:
        current["enabled"] = bool(enabled)
    if interval_minutes is not None:
        current["interval_minutes"] = max(5, min(1440, int(interval_minutes)))
    if keep_count is not None:
        current["keep_count"] = max(5, min(500, int(keep_count)))

    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO group_backup_settings (
                group_id, enabled, interval_minutes, keep_count,
                last_backup_at, last_backup_file, last_backup_rows,
                last_backup_sha256, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                enabled = excluded.enabled,
                interval_minutes = excluded.interval_minutes,
                keep_count = excluded.keep_count,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id), 1 if current["enabled"] else 0,
                int(current["interval_minutes"]), int(current["keep_count"]),
                current.get("last_backup_at"), current.get("last_backup_file", ""),
                int(current.get("last_backup_rows", 0)), current.get("last_backup_sha256", ""),
                int(actor_id), now,
            ),
        )
        con.commit()

    mark_group_backup_dirty(group_id)
    return get_group_backup_settings(group_id)


def record_moderation_audit(
    group_id: int,
    target_user_id: int,
    actor_user_id: int,
    action: str,
    source: str,
    success: bool,
    detail: str = "",
) -> None:
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO moderation_audit_log (
                group_id, target_user_id, actor_user_id,
                action, source, success, detail, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(group_id), int(target_user_id or 0), int(actor_user_id or 0),
                str(action or "")[:64], str(source or "")[:64],
                1 if success else 0, str(detail or "")[:1000], now,
            ),
        )
        con.commit()
    mark_group_backup_dirty(group_id, invalidate_hot=False)


def recent_moderation_audit(
    group_id: int,
    target_user_id: Optional[int] = None,
    limit: int = 10,
) -> List[sqlite3.Row]:
    limit = max(1, min(50, int(limit)))
    with db_connect() as con:
        if target_user_id is None:
            return con.execute(
                "SELECT * FROM moderation_audit_log WHERE group_id = ? ORDER BY audit_id DESC LIMIT ?",
                (int(group_id), limit),
            ).fetchall()
        return con.execute(
            "SELECT * FROM moderation_audit_log WHERE group_id = ? AND target_user_id = ? ORDER BY audit_id DESC LIMIT ?",
            (int(group_id), int(target_user_id), limit),
        ).fetchall()


def _backup_json_value(value: Any) -> Any:
    if isinstance(value, bytes):
        return {"__bytes_hex__": value.hex()}
    if isinstance(value, (str, int, float, bool)) or value is None:
        return value
    return str(value)


def _group_snapshot_payload(group_id: int, reason: str) -> Tuple[Dict[str, Any], int]:
    tables: Dict[str, Any] = {}
    row_total = 0
    with db_connect() as con:
        con.execute("BEGIN")
        table_rows = con.execute(
            "SELECT name, sql FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name"
        ).fetchall()
        for table_row in table_rows:
            table_name = str(table_row["name"])
            columns = con.execute(f'PRAGMA table_info("{table_name}")').fetchall()
            column_names = [str(row["name"]) for row in columns]
            if "group_id" not in column_names:
                continue
            rows = con.execute(
                f'SELECT * FROM "{table_name}" WHERE group_id = ?',
                (int(group_id),),
            ).fetchall()
            serialized = [
                {key: _backup_json_value(row[key]) for key in row.keys()}
                for row in rows
            ]
            row_total += len(serialized)
            tables[table_name] = {
                "schema": table_row["sql"] or "",
                "columns": column_names,
                "rows": serialized,
                "row_count": len(serialized),
            }
    return {
        "format": "zivo-group-backup-v1",
        "zivo_version": VERSION,
        "group_id": int(group_id),
        "created_at_utc": datetime.now(timezone.utc).isoformat(),
        "reason": str(reason or "automatic")[:100],
        "table_count": len(tables),
        "row_count": row_total,
        "tables": tables,
    }, row_total


def _prune_group_backups(group_dir: Path, keep_count: int) -> int:
    files = sorted(
        [path for path in group_dir.glob("snapshot_*.json") if path.is_file()],
        key=lambda path: path.name,
        reverse=True,
    )
    removed = 0
    for old in files[max(5, int(keep_count)):]:
        try:
            old.unlink(missing_ok=True)
            old.with_suffix(old.suffix + ".sha256").unlink(missing_ok=True)
            removed += 1
        except Exception:
            pass
    return removed


async def group_backup_retention_sweep_worker() -> None:
    """One paced startup sweep so historical default-72 snapshots stop consuming gigabytes."""
    await asyncio.sleep(45.0)
    total_removed = 0
    groups = 0
    try:
        dirs = [path for path in GROUP_BACKUP_ROOT.iterdir() if path.is_dir() and path.name.isdigit()]
    except Exception:
        dirs = []
    for group_dir in dirs:
        try:
            if _transport_pending_request_count(client) >= TRANSPORT_PENDING_WARN:
                await asyncio.sleep(2.0)
                continue
            gid = int(group_dir.name)
            settings = await asyncio.to_thread(get_group_backup_settings, gid)
            removed = await asyncio.to_thread(_prune_group_backups, group_dir, int(settings["keep_count"]))
            total_removed += int(removed or 0)
            groups += 1
            if groups % 8 == 0:
                await _yield_background_to_realtime(1.0)
                await asyncio.sleep(0.15)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.debug("group backup retention skipped | dir=%s | %s: %s", group_dir, type(exc).__name__, exc)
    log.info("group backup retention sweep PASS | groups=%s snapshots_removed=%s default_keep=12", groups, total_removed)


def export_group_snapshot(
    group_id: int,
    reason: str = "automatic",
    actor_id: int = 0,
) -> Dict[str, Any]:
    group_id = int(group_id)
    settings = get_group_backup_settings(group_id)
    now_seed = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT OR IGNORE INTO group_backup_settings (
                group_id, enabled, interval_minutes, keep_count,
                last_backup_at, last_backup_file, last_backup_rows,
                last_backup_sha256, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, NULL, '', 0, '', ?, ?)
            """,
            (
                group_id,
                1 if settings["enabled"] else 0,
                int(settings["interval_minutes"]),
                int(settings["keep_count"]),
                int(actor_id or 0),
                now_seed,
            ),
        )
        con.commit()
    payload, row_total = _group_snapshot_payload(group_id, reason)
    stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%S_%fZ")
    group_dir = GROUP_BACKUP_ROOT / str(group_id)
    group_dir.mkdir(parents=True, exist_ok=True)
    try:
        group_dir.chmod(0o700)
    except Exception:
        pass
    final_path = group_dir / f"snapshot_{stamp}.json"
    temp_path = group_dir / f".snapshot_{stamp}.tmp"

    # Preserve group-specific welcome media beside JSON snapshots. Assets are
    # content-addressed, so an older snapshot never loses the GIF it referenced.
    assets: List[Dict[str, Any]] = []
    try:
        welcome = get_welcome_settings(group_id)
        welcome_path = Path(str(welcome.get("gif_local_path") or ""))
        if welcome_path.is_file():
            asset_raw = welcome_path.read_bytes()
            asset_sha = hashlib.sha256(asset_raw).hexdigest()
            suffix = welcome_path.suffix[:12] if welcome_path.suffix else ".bin"
            assets_dir = group_dir / "assets"
            assets_dir.mkdir(parents=True, exist_ok=True)
            try:
                assets_dir.chmod(0o700)
            except Exception:
                pass
            asset_path = assets_dir / f"welcome_{asset_sha}{suffix}"
            if not asset_path.exists():
                temp_asset = assets_dir / f".{asset_path.name}.tmp"
                temp_asset.write_bytes(asset_raw)
                os.replace(temp_asset, asset_path)
                try:
                    asset_path.chmod(0o600)
                except Exception:
                    pass
            assets.append({
                "kind": "welcome_gif",
                "sha256": asset_sha,
                "size_bytes": len(asset_raw),
                "backup_path": str(asset_path),
                "source_path": str(welcome_path),
            })
    except Exception as exc:
        log.warning("group snapshot welcome asset skipped | group=%s | %s: %s", group_id, type(exc).__name__, exc)
    payload["assets"] = assets
    payload["asset_count"] = len(assets)

    raw = json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True).encode("utf-8")
    digest = hashlib.sha256(raw).hexdigest()
    temp_path.write_bytes(raw)
    os.replace(temp_path, final_path)
    try:
        final_path.chmod(0o600)
    except Exception:
        pass
    sha_path = final_path.with_suffix(final_path.suffix + ".sha256")
    sha_path.write_text(
        digest + "  " + final_path.name + "\n", encoding="utf-8"
    )
    try:
        sha_path.chmod(0o600)
    except Exception:
        pass
    latest_tmp = group_dir / ".latest.tmp"
    latest_tmp.write_bytes(raw)
    latest_path = group_dir / "latest.json"
    os.replace(latest_tmp, latest_path)
    try:
        latest_path.chmod(0o600)
    except Exception:
        pass

    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO group_backup_settings (
                group_id, enabled, interval_minutes, keep_count,
                last_backup_at, last_backup_file, last_backup_rows,
                last_backup_sha256, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                last_backup_at = excluded.last_backup_at,
                last_backup_file = excluded.last_backup_file,
                last_backup_rows = excluded.last_backup_rows,
                last_backup_sha256 = excluded.last_backup_sha256,
                updated_at = excluded.updated_at
            """,
            (
                group_id, 1 if settings["enabled"] else 0,
                int(settings["interval_minutes"]), int(settings["keep_count"]),
                now, str(final_path), int(row_total), digest, int(actor_id or 0), now,
            ),
        )
        con.commit()
    _prune_group_backups(group_dir, settings["keep_count"])
    _group_backup_dirty.pop(group_id, None)
    log.info(
        "group snapshot created | group=%s rows=%s tables=%s reason=%s sha=%s",
        group_id, row_total, payload["table_count"], reason, digest[:16],
    )
    return {
        "path": str(final_path), "rows": row_total,
        "tables": int(payload["table_count"]), "sha256": digest,
        "created_at": now,
    }


def installed_group_ids() -> List[int]:
    with db_connect() as con:
        rows = con.execute("SELECT group_id FROM installations ORDER BY group_id").fetchall()
    return [int(row["group_id"]) for row in rows]


def _backup_timestamp_due(last_backup_at: Optional[str], interval_minutes: int) -> bool:
    if not last_backup_at:
        return True
    try:
        last = datetime.fromisoformat(str(last_backup_at))
        if last.tzinfo is None:
            last = last.replace(tzinfo=timezone.utc)
    except Exception:
        return True
    return datetime.now(timezone.utc) >= last.astimezone(timezone.utc) + timedelta(
        minutes=max(5, int(interval_minutes))
    )


async def process_group_backups() -> None:
    global _group_backup_scan_cursor
    if _transport_pending_request_count(client) >= TRANSPORT_PENDING_WARN:
        log.debug("group backup cycle deferred | transport_pending=%s", _transport_pending_request_count(client))
        return
    now_mono = time.monotonic()
    all_groups = installed_group_ids()
    if not all_groups:
        return

    dirty_due = [
        int(gid)
        for gid, dirty_since in list(_group_backup_dirty.items())
        if now_mono - float(dirty_since) >= GROUP_BACKUP_DIRTY_DELAY
    ]

    total = len(all_groups)
    start_index = _group_backup_scan_cursor % total
    scan_count = min(total, GROUP_BACKUP_SCAN_PER_CYCLE)
    scheduled_slice = [all_groups[(start_index + offset) % total] for offset in range(scan_count)]
    _group_backup_scan_cursor = (start_index + scan_count) % total

    candidates: List[int] = []
    seen: set[int] = set()
    for gid in dirty_due + scheduled_slice:
        if gid in seen:
            continue
        seen.add(gid)
        candidates.append(gid)

    processed = 0
    for group_id in candidates:
        if processed >= GROUP_BACKUP_MAX_PER_CYCLE:
            break
        settings = get_group_backup_settings(group_id)
        if not settings["enabled"]:
            continue
        # Automatic snapshots are a Diamond entitlement. A downgrade keeps old
        # backups intact but pauses future automatic snapshots immediately.
        if not premium.feature_allowed(int(group_id), "auto_backup"):
            continue
        dirty_since = _group_backup_dirty.get(group_id)
        dirty_is_due = dirty_since is not None and now_mono - float(dirty_since) >= GROUP_BACKUP_DIRTY_DELAY
        interval_due = _backup_timestamp_due(
            settings.get("last_backup_at"), int(settings["interval_minutes"])
        )
        if not dirty_is_due and not interval_due:
            continue
        lock = _group_backup_locks.setdefault(group_id, asyncio.Lock())
        if lock.locked():
            continue
        async with lock:
            try:
                await _yield_background_to_realtime(1.5)
                await asyncio.to_thread(
                    export_group_snapshot, group_id,
                    "state-change" if dirty_is_due else "scheduled", 0,
                )
                processed += 1
            except Exception:
                log.exception("group backup failed | group=%s", group_id)

    if processed:
        log.info(
            "group backup cycle | processed=%s scanned=%s total_groups=%s dirty_due=%s",
            processed, len(candidates), total, len(dirty_due),
        )


async def group_backup_worker() -> None:
    await asyncio.sleep(60.0)
    while True:
        try:
            await _yield_background_to_realtime(2.0)
            await process_group_backups()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("group backup worker error")
        await asyncio.sleep(120.0)



