def _normalize_settings_command_text(text: str) -> str:
    normalized = normalize_moderation_digits(normalize_group_command(text))
    for codepoint in (0x2010, 0x2011, 0x2012, 0x2013, 0x2014, 0x2212, 0xFE63, 0xFF0D):
        normalized = normalized.replace(chr(codepoint), "-")
    if normalized:
        normalized = "".join(
            ch for ch in normalized
            if ord(ch) not in {0x200B, 0x2060, 0xFEFF}
        )
    return normalized


def parse_settings_copy_command(text: str) -> Optional[Dict[str, Any]]:
    normalized = _normalize_settings_command_text(text)
    if not normalized:
        return None

    if normalized in {"وضعیت ستینگ", "وضعیت تنظیمات", "خلاصه ستینگ", "خلاصه تنظیمات"}:
        return {"action": "status"}

    if normalized in {"ستینگ", "تنظیمات", "مرکز ستینگ", "مرکز تنظیمات", "لیست ستینگ", "لیست تنظیمات"}:
        return {"action": "center"}

    if normalized in {"وارد کردن ستینگ", "واردکردن ستینگ", "ایمپورت ستینگ", "اعمال ستینگ"}:
        return {"action": "import_help"}

    if normalized in {"تایید ستینگ", "تأیید ستینگ", "تایید تنظیمات", "تأیید تنظیمات"}:
        return {"action": "confirm"}

    if normalized in {"لغو ستینگ", "لغو تنظیمات", "انصراف ستینگ"}:
        return {"action": "cancel"}

    upper = normalized.upper()
    if SETTINGS_TOKEN_RE.fullmatch(upper):
        return {"action": "prepare_apply", "token": upper}

    # Accept a copied token wrapped in a small amount of UI punctuation/label
    # noise while keeping the token grammar itself strict.
    token_match = re.search(r"ZIVOSET-[A-F0-9]{4}-[A-F0-9]{4}-[A-F0-9]{4}", upper)
    if token_match is not None and (len(upper) - len(token_match.group(0))) <= 20:
        return {"action": "prepare_apply", "token": token_match.group(0)}

    apply_match = re.fullmatch(r"(?:اعمال|وارد کردن|واردکردن|ایمپورت)\s+(?:ستینگ|تنظیمات)\s+(ZIVOSET-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4}-[A-Fa-f0-9]{4})", normalized, re.IGNORECASE)
    if apply_match:
        return {"action": "prepare_apply", "token": apply_match.group(1).upper()}

    export_match = re.fullmatch(r"(?:کپی|بکاپ)\s+(?:ستینگ|تنظیمات)(?:\s+(.+))?", normalized)
    if export_match:
        raw_section = (export_match.group(1) or "").strip()
        section = normalize_settings_section(raw_section)
        if section is None:
            return {"action": "invalid_section", "raw_section": raw_section}
        return {"action": "export", "section": section}

    return None


def _settings_copy_sections_for(section_key: str) -> Tuple[str, ...]:
    if section_key == "all":
        return SETTINGS_COPY_SECTION_ORDER
    if section_key in SETTINGS_COPY_SECTION_ORDER:
        return (section_key,)
    return tuple()


def _settings_copy_make_token() -> str:
    raw = os.urandom(6).hex().upper()
    return f"ZIVOSET-{raw[:4]}-{raw[4:8]}-{raw[8:12]}"


def _settings_copy_export_payload(group_id: int, section_key: str) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    group_id = int(group_id)
    section_keys = _settings_copy_sections_for(section_key)
    if not section_keys:
        raise ValueError("INVALID_SETTINGS_SECTION")

    ensure_group_lock_settings(group_id)
    payload_sections: Dict[str, Any] = {}
    summary: Dict[str, Any] = {"sections": {}, "total_rows": 0}

    with db_connect() as con:
        for key in section_keys:
            table_map = SETTINGS_COPY_TABLE_FIELDS[key]
            section_tables: Dict[str, Any] = {}
            section_rows = 0
            for table_name, fields in table_map.items():
                columns = ", ".join(f'"{field}"' for field in fields)
                rows = con.execute(
                    f'SELECT {columns} FROM "{table_name}" WHERE group_id = ?',
                    (group_id,),
                ).fetchall()
                serialized: List[Dict[str, Any]] = []
                for row in rows:
                    item = {field: _backup_json_value(row[field]) for field in fields}
                    if table_name == "welcome_settings":
                        local_path = str(item.get("gif_local_path") or "")
                        if not local_path or not Path(local_path).is_file():
                            item["gif_local_path"] = ""
                            item["gif_fingerprint"] = ""
                    serialized.append(item)
                section_tables[table_name] = serialized
                section_rows += len(serialized)
            payload_sections[key] = section_tables
            summary["sections"][key] = section_rows
            summary["total_rows"] += section_rows

    payload = {
        "format": "zivo-settings-copy-v1",
        "zivo_version": VERSION,
        "source_group_id": group_id,
        "section_key": section_key,
        "created_at_utc": datetime.now(timezone.utc).isoformat(),
        "sections": payload_sections,
    }
    canonical = json.dumps(payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    payload["sha256"] = hashlib.sha256(canonical).hexdigest()
    return payload, summary


def create_settings_copy_snapshot(group_id: int, section_key: str, actor_id: int) -> Dict[str, Any]:
    payload, summary = _settings_copy_export_payload(group_id, section_key)
    now = datetime.now(timezone.utc)
    expires = now + timedelta(days=SETTINGS_COPY_TTL_DAYS)
    token = ""
    with db_connect() as con:
        con.execute("DELETE FROM settings_copy_snapshots WHERE expires_at < ?", (now.isoformat(),))
        for _ in range(10):
            candidate = _settings_copy_make_token()
            try:
                con.execute(
                    """
                    INSERT INTO settings_copy_snapshots (
                        token, source_group_id, section_key, payload_json, summary_json,
                        created_by, created_at, expires_at, use_count, last_used_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0, NULL)
                    """,
                    (
                        candidate, int(group_id), section_key,
                        json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
                        json.dumps(summary, ensure_ascii=False, separators=(",", ":")),
                        int(actor_id), now.isoformat(), expires.isoformat(),
                    ),
                )
                token = candidate
                break
            except sqlite3.IntegrityError:
                continue
        if not token:
            raise RuntimeError("SETTINGS_TOKEN_COLLISION")
        con.commit()
    try:
        multi_put_settings_snapshot(
            MULTI_ACCOUNT_DB,
            token=token,
            source_account=ACCOUNT_KEY,
            source_group_id=int(group_id),
            section_key=section_key,
            payload_json=json.dumps(payload, ensure_ascii=False, separators=(",", ":")),
            summary_json=json.dumps(summary, ensure_ascii=False, separators=(",", ":")),
            created_by=int(actor_id),
            created_at=now.isoformat(),
            expires_at=expires.isoformat(),
        )
        log.info("settings copy shared mirror PASS | account=%s group=%s token=%s", ACCOUNT_KEY, group_id, token)
    except Exception as exc:
        log.warning("settings copy shared mirror deferred | account=%s group=%s token=%s | %s: %s", ACCOUNT_KEY, group_id, token, type(exc).__name__, exc)
    return {"token": token, "payload": payload, "summary": summary, "expires_at": expires.isoformat()}


def get_settings_copy_snapshot(token: str) -> Optional[Dict[str, Any]]:
    token = _normalize_settings_command_text(str(token or "")).upper().strip()
    if not SETTINGS_TOKEN_RE.fullmatch(token):
        return None

    row: Optional[Any] = None
    source_account = ACCOUNT_KEY
    with db_connect() as con:
        row = con.execute("SELECT * FROM settings_copy_snapshots WHERE token = ?", (token,)).fetchone()

    if row is None:
        try:
            shared = multi_get_settings_snapshot(MULTI_ACCOUNT_DB, token)
        except Exception as exc:
            shared = None
            log.warning("settings shared lookup deferred | account=%s token=%s | %s: %s", ACCOUNT_KEY, token, type(exc).__name__, exc)
        if shared is None:
            try:
                recovered = multi_recover_settings_snapshot_from_accounts(MULTI_ACCOUNT_DB, token)
            except Exception as exc:
                recovered = None
                log.warning("settings legacy cross-account lookup deferred | account=%s token=%s | %s: %s", ACCOUNT_KEY, token, type(exc).__name__, exc)
            if recovered is not None:
                row = recovered
                source_account = str(recovered.get("source_account") or "")
                log.info("settings legacy cross-account token recovered | account=%s source=%s token=%s", ACCOUNT_KEY, source_account, token)
        else:
            row = shared
            try:
                source_account = str(shared["source_account"] or "")
            except Exception:
                source_account = ""
            log.info("settings shared token lookup PASS | account=%s source=%s token=%s", ACCOUNT_KEY, source_account, token)

    if row is None:
        return None
    try:
        expiry = datetime.fromisoformat(str(row["expires_at"]))
        if expiry.tzinfo is None:
            expiry = expiry.replace(tzinfo=timezone.utc)
        if datetime.now(timezone.utc) > expiry.astimezone(timezone.utc):
            return None
        payload = json.loads(str(row["payload_json"] or "{}"))
        summary = json.loads(str(row["summary_json"] or "{}"))
    except Exception:
        return None
    if payload.get("format") != "zivo-settings-copy-v1":
        return None
    return {
        "token": token,
        "source_group_id": int(row["source_group_id"]),
        "section_key": str(row["section_key"] or "all"),
        "payload": payload,
        "summary": summary,
        "expires_at": str(row["expires_at"]),
        "source_account": source_account,
    }


def _settings_copy_safe_row(table_name: str, raw_row: Dict[str, Any]) -> Dict[str, Any]:
    allowed: Tuple[str, ...] = tuple()
    for table_map in SETTINGS_COPY_TABLE_FIELDS.values():
        if table_name in table_map:
            allowed = table_map[table_name]
            break
    clean = {key: raw_row.get(key) for key in allowed if key in raw_row}
    if table_name == "welcome_settings":
        local_path = str(clean.get("gif_local_path") or "")
        if not local_path or not Path(local_path).is_file():
            clean["gif_local_path"] = ""
            clean["gif_fingerprint"] = ""
    return clean


def apply_settings_copy_snapshot(group_id: int, actor_id: int, snapshot: Dict[str, Any]) -> Dict[str, Any]:
    group_id = int(group_id)
    actor_id = int(actor_id)
    payload = snapshot.get("payload") or {}
    sections = payload.get("sections") or {}
    applied_sections: List[str] = []
    applied_rows = 0
    now = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        con.execute("BEGIN IMMEDIATE")
        try:
            for section_key in SETTINGS_COPY_SECTION_ORDER:
                section_payload = sections.get(section_key)
                if not isinstance(section_payload, dict):
                    continue
                table_map = SETTINGS_COPY_TABLE_FIELDS[section_key]
                for table_name, allowed_fields in table_map.items():
                    con.execute(f'DELETE FROM "{table_name}" WHERE group_id = ?', (group_id,))
                    raw_rows = section_payload.get(table_name) or []
                    if not isinstance(raw_rows, list):
                        raw_rows = []
                    table_columns = {str(row["name"]) for row in con.execute(f'PRAGMA table_info("{table_name}")').fetchall()}
                    for raw_row in raw_rows:
                        if not isinstance(raw_row, dict):
                            continue
                        clean = _settings_copy_safe_row(table_name, raw_row)
                        values: Dict[str, Any] = {"group_id": group_id}
                        for field in allowed_fields:
                            if field in clean and field in table_columns:
                                values[field] = clean[field]
                        if "updated_by" in table_columns:
                            values["updated_by"] = actor_id
                        if "updated_at" in table_columns:
                            values["updated_at"] = now
                        if "created_by" in table_columns:
                            values["created_by"] = actor_id
                        if "created_at" in table_columns:
                            values["created_at"] = now
                        keys = list(values.keys())
                        placeholders = ", ".join("?" for _ in keys)
                        quoted = ", ".join(f'"{key}"' for key in keys)
                        con.execute(
                            f'INSERT INTO "{table_name}" ({quoted}) VALUES ({placeholders})',
                            tuple(values[key] for key in keys),
                        )
                        applied_rows += 1
                applied_sections.append(section_key)
            con.execute(
                "UPDATE settings_copy_snapshots SET use_count = use_count + 1, last_used_at = ? WHERE token = ?",
                (now, str(snapshot.get("token") or "")),
            )
            con.commit()
        except Exception:
            con.rollback()
            raise

    try:
        multi_mark_settings_snapshot_used(MULTI_ACCOUNT_DB, str(snapshot.get("token") or ""))
    except Exception as exc:
        log.debug("settings shared use counter deferred | token=%s | %s: %s", str(snapshot.get("token") or ""), type(exc).__name__, exc)

    if "locks" in applied_sections:
        ensure_group_lock_settings(group_id)
    if "filters" in applied_sections:
        invalidate_filtered_phrase_cache(group_id)
    if "spam" in applied_sections:
        _anti_spam_settings_cache.pop(group_id, None)
        invalidate_message_rate_settings_cache(group_id)
        for key in [key for key in _message_rate_last_accepted if key[0] == group_id]:
            _message_rate_last_accepted.pop(key, None)
        for key in [key for key in _message_rate_native_until if key[0] == group_id]:
            _message_rate_native_until.pop(key, None)
        _flood_guard_last_sender.pop(group_id, None)
        for key in [key for key in _flood_guard_event_times if key[0] == group_id]:
            _flood_guard_event_times.pop(key, None)
        for key in [key for key in _flood_guard_action_until if key[0] == group_id]:
            _flood_guard_action_until.pop(key, None)
    if "voice" in applied_sections:
        _tts_voice_settings_hot.pop(group_id, None)
    mark_group_backup_dirty(group_id)
    return {"sections": applied_sections, "rows": applied_rows}


def settings_copy_summary_text(snapshot: Dict[str, Any]) -> str:
    summary = snapshot.get("summary") or {}
    section_counts = summary.get("sections") or {}
    parts: List[str] = []
    for key in SETTINGS_COPY_SECTION_ORDER:
        if key not in section_counts:
            continue
        parts.append(f"▫️ {SETTINGS_COPY_SECTION_LABELS[key]}: {stats_num(int(section_counts.get(key) or 0))} رکورد")
    return "\n".join(parts) if parts else "▫️ تنظیمات پیش‌فرض این بخش ثبت شده است."


def settings_overview_text(group_id: int) -> str:
    ensure_group_lock_settings(group_id)
    lock_rows = group_lock_rows(group_id)
    enabled_locks = [str(row["lock_name"]) for row in lock_rows if int(row["enabled"] or 0) == 1]
    flood = get_flood_guard_settings(group_id)
    message_rate = get_message_rate_limit_settings(group_id)
    welcome = get_welcome_settings(group_id)
    rules = get_group_rules_settings(group_id)
    warning = get_manual_warning_settings(group_id)
    cleanup = get_bot_message_cleanup_settings(group_id)
    tag_cleanup = get_tag_cleanup_settings(group_id)
    auto_stats = auto_stats_setting(group_id)
    backup = get_group_backup_settings(group_id)
    with db_connect() as con:
        exact_count_row = con.execute("SELECT COUNT(*) AS c FROM exact_content_filters WHERE group_id = ?", (int(group_id),)).fetchone()
        special_count_row = con.execute("SELECT COUNT(*) AS c FROM special_lock_defaults WHERE group_id = ?", (int(group_id),)).fetchone()
        pin_row = con.execute("SELECT delete_after_expiry FROM pin_settings WHERE group_id = ?", (int(group_id),)).fetchone()
    exact_count = int(exact_count_row["c"] or 0) if exact_count_row else 0
    special_count = int(special_count_row["c"] or 0) if special_count_row else 0
    pin_delete = bool(int(pin_row["delete_after_expiry"] or 0)) if pin_row else False
    locks_text = "، ".join(enabled_locks[:12]) if enabled_locks else "هیچ‌کدام"
    if len(enabled_locks) > 12:
        locks_text += f" +{stats_num(len(enabled_locks) - 12)}"
    return (
        "⚙️ ZIVO | وضعیت ستینگ\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"🔐 قفل‌های فعال: {stats_num(len(enabled_locks))} | {locks_text}\n"
        f"🚫 کلمات فیلترشده: {stats_num(filtered_phrase_count(group_id))}\n"
        f"🧬 فیلتر محتوای دقیق: {stats_num(exact_count)}\n"
        f"🛡 محافظ اسپم: {'فعال' if flood['enabled'] else 'خاموش'} | {stats_num(flood['burst_limit'])} پیام/{stats_num(flood['window_seconds'])} ثانیه | پشت سرهم {stats_num(flood['consecutive_limit'])}\n"
        f"⏱ محدودیت پیام: {'فعال' if message_rate['enabled'] else 'خاموش'} | هر {stats_num(message_rate['interval_seconds'])} ثانیه یک پیام\n"
        f"👋 خوشامد: {'فعال' if welcome['enabled'] else 'خاموش'} | {'متن سفارشی' if welcome['custom_text'] else 'متن پیش‌فرض'} | {'گیف دارد' if welcome['gif_local_path'] or welcome['gif_source_message_id'] else 'بدون گیف'}\n"
        f"📜 قوانین: {'تنظیم شده' if rules['rules_text'] else 'تنظیم نشده'} | زیر خوشامد {'فعال' if rules['show_in_welcome'] else 'خاموش'}\n"
        f"⚠️ اخطار دستی: سقف {stats_num(warning['max_warnings'])} | مجازات {warning['action_mode']}\n"
        f"💠 پیش‌فرض دسترسی ویژه: {stats_num(special_count)} قفل سفارشی\n"
        f"🧹 حذف پیام‌های زیوو: {'فعال' if cleanup['enabled'] else 'خاموش'} | اخطار {stats_num(cleanup['warning_seconds'])}ث | خوشامد {stats_num(cleanup['welcome_seconds'])}ث\n"
        f"📣 حذف تگ: {'فعال' if tag_cleanup['enabled'] else 'خاموش'} | {stats_num(int(tag_cleanup['delay_seconds']) // 60)} دقیقه\n"
        f"📊 آمار خودکار: {'فعال' if auto_stats['enabled'] else 'خاموش'} | {stats_num(auto_stats['send_hour'])}:{int(auto_stats['send_minute']):02d}\n"
        f"📌 حذف پیام بعد از پایان پین: {'فعال' if pin_delete else 'خاموش'}\n"
        f"💾 بکاپ خودکار: {'فعال' if backup['enabled'] else 'خاموش'} | هر {stats_num(backup['interval_minutes'])} دقیقه | نگهداری {stats_num(backup['keep_count'])} نسخه\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "📦 برای گرفتن کد کامل بنویس: کپی ستینگ\n"
        "⚡ ZIVO | SETTINGS STATUS"
    )


async def command_settings_copy(event: Any, group: Any, group_id: int, parsed: Dict[str, Any]) -> None:
    action = str(parsed.get("action") or "")
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return

    if action == "center":
        text, commands = settings_center_text(private_mode=False)
        await send_copyable_command_text(group, text, commands)
        return

    if action == "status":
        await send_copyable_command_text(group, settings_overview_text(group_id), ["کپی ستینگ"])
        return

    role = base_bot_role(group_id, actor_id)
    if role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ کپی یا اعمال ستینگ فقط برای مالک و ادمین زیوو مجازه.")
        return

    if action == "invalid_section":
        await send_group_text(group, "⚠️ این بخش ستینگ شناخته نشد. بنویس «ستینگ» تا فهرست بخش‌ها را ببینی.")
        return

    if action == "import_help":
        await send_group_text(
            group,
            "📥 ZIVO | وارد کردن ستینگ\n━━━━━━━━━━━━━━━━━━\n"
            "کد ZIVOSET را همینجا بفرست یا بنویس:\n"
            "اعمال ستینگ ZIVOSET-XXXX-XXXX-XXXX\n\n"
            "بعد از پیش‌نمایش بنویس: تایید ستینگ\n"
            "━━━━━━━━━━━━━━━━━━\n⚡ ZIVO | SETTINGS IMPORT",
        )
        return

    if action == "export":
        section_key = str(parsed.get("section") or "all")
        try:
            result = create_settings_copy_snapshot(group_id, section_key, actor_id)
        except Exception as exc:
            log.exception("settings copy export failed | group=%s section=%s", group_id, section_key)
            await send_group_text(group, f"❌ ساخت کپی ستینگ ناموفق بود: {type(exc).__name__}")
            return
        token = result["token"]
        snapshot = {"summary": result["summary"]}
        await send_copyable_command_text(
            group,
            (
                "📦 ZIVO | کپی ستینگ\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎖 اجراکننده: {role}\n"
                f"🧩 بخش: {settings_section_display(section_key)}\n"
                f"📚 رکوردها: {stats_num(int(result['summary'].get('total_rows') or 0))}\n"
                f"🗓 اعتبار کد: {stats_num(SETTINGS_COPY_TTL_DAYS)} روز\n\n"
                "🔑 کد قابل کپی:\n"
                f"{token}\n\n"
                "📥 در گروه مقصد بنویس:\n"
                f"اعمال ستینگ {token}\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | SETTINGS COPY"
            ),
            [token, f"اعمال ستینگ {token}"],
        )
        log.info("settings copy token created | group=%s actor=%s section=%s token=%s", group_id, actor_id, section_key, token)
        return

    if action == "prepare_apply":
        token = str(parsed.get("token") or "").upper()
        snapshot = get_settings_copy_snapshot(token)
        if snapshot is None:
            await send_group_text(group, "❌ این کد ستینگ پیدا نشد یا اعتبارش تمام شده.")
            return
        _settings_apply_sessions[group_id] = {
            "actor_id": actor_id,
            "token": token,
            "expires_at": time.monotonic() + SETTINGS_APPLY_SESSION_TTL_SECONDS,
        }
        await send_copyable_command_text(
            group,
            (
                "⚠️ ZIVO | پیش‌نمایش اعمال ستینگ\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🧩 بخش: {settings_section_display(snapshot['section_key'])}\n"
                f"📦 گروه مبدا: {stats_num(snapshot['source_group_id'])}\n"
                f"📚 مجموع رکوردها: {stats_num(int((snapshot.get('summary') or {}).get('total_rows') or 0))}\n\n"
                f"{settings_copy_summary_text(snapshot)}\n\n"
                "🔐 مقام‌ها، مالکیت، کاربران ویژه/معاف، آمار شخصی و بن‌های فعال تغییر نمی‌کنند.\n"
                "⚠️ تنظیمات همان بخش در گروه مقصد جایگزین می‌شود.\n\n"
                "برای انجام نهایی:\n"
                "تایید ستینگ\n"
                "برای لغو:\n"
                "لغو ستینگ\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | SETTINGS PREVIEW"
            ),
            ["تایید ستینگ", "لغو ستینگ"],
        )
        log.info("settings apply prepared | group=%s actor=%s token=%s source=%s section=%s", group_id, actor_id, token, snapshot['source_group_id'], snapshot['section_key'])
        return

    if action == "cancel":
        session = _settings_apply_sessions.get(group_id)
        if session and int(session.get("actor_id") or 0) == actor_id:
            _settings_apply_sessions.pop(group_id, None)
            await send_group_text(group, "✅ درخواست اعمال ستینگ لغو شد.")
        else:
            await send_group_text(group, "ℹ️ درخواست ستینگ بازی برای حساب تو وجود نداره.")
        return

    if action == "confirm":
        session = _settings_apply_sessions.get(group_id)
        if not session or int(session.get("actor_id") or 0) != actor_id:
            await send_group_text(group, "ℹ️ اول کد ستینگ را بفرست تا پیش‌نمایش ساخته شود.")
            return
        if time.monotonic() > float(session.get("expires_at") or 0):
            _settings_apply_sessions.pop(group_id, None)
            await send_group_text(group, "⌛ مهلت تایید ستینگ تمام شد؛ کد را دوباره بفرست.")
            return
        token = str(session.get("token") or "")
        snapshot = get_settings_copy_snapshot(token)
        if snapshot is None:
            _settings_apply_sessions.pop(group_id, None)
            await send_group_text(group, "❌ کد ستینگ دیگر معتبر نیست.")
            return
        try:
            result = await asyncio.to_thread(apply_settings_copy_snapshot, group_id, actor_id, snapshot)
        except Exception as exc:
            log.exception("settings apply failed | group=%s actor=%s token=%s", group_id, actor_id, token)
            await send_group_text(group, f"❌ اعمال ستینگ ناموفق بود: {type(exc).__name__}")
            return
        _settings_apply_sessions.pop(group_id, None)
        labels = "، ".join(SETTINGS_COPY_SECTION_LABELS.get(k, k) for k in result["sections"]) or "تنظیمات"
        await send_group_text(
            group,
            "✅ ZIVO | ستینگ اعمال شد\n━━━━━━━━━━━━━━━━━━\n"
            f"🧩 بخش‌ها: {labels}\n"
            f"📚 رکوردهای اعمال‌شده: {stats_num(result['rows'])}\n"
            "💾 وضعیت جدید برای بکاپ گروه علامت‌گذاری شد.\n"
            "━━━━━━━━━━━━━━━━━━\n⚡ ZIVO | SETTINGS APPLIED",
        )
        log.info("settings apply PASS | group=%s actor=%s token=%s sections=%s rows=%s", group_id, actor_id, token, ','.join(result['sections']), result['rows'])
        return

def parse_group_backup_command(text: str) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(text)
    if text in {"بکاپ گپ", "بکاپ گروه", "بکاپ الان"}:
        return {"action": "backup_now"}
    if text in {"وضعیت بکاپ", "وضعیت بکاپ گپ", "وضعیت بکاپ گروه"}:
        return {"action": "backup_status"}
    if text in {"بکاپ خودکار فعال", "بکاپ خودکار روشن"}:
        return {"action": "backup_toggle", "enabled": True}
    if text in {"بکاپ خودکار خاموش", "بکاپ خودکار غیرفعال"}:
        return {"action": "backup_toggle", "enabled": False}
    match = re.fullmatch(r"(?:تنظیم فاصله بکاپ|فاصله بکاپ)\s+(\d{1,4})", text)
    if match:
        return {"action": "backup_interval", "minutes": int(match.group(1))}
    match = re.fullmatch(r"(?:تعداد بکاپ|نگهداری بکاپ)\s+(\d{1,3})", text)
    if match:
        return {"action": "backup_keep", "count": int(match.group(1))}
    return None


async def command_group_backup(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    actor_role = base_bot_role(group_id, actor_id)
    if actor_role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ تنظیم و اجرای بکاپ گپ فقط برای مالک و ادمین زیوو فعاله.")
        return
    action = parsed.get("action")
    if action == "backup_now":
        try:
            result = await asyncio.to_thread(export_group_snapshot, group_id, "manual", actor_id)
        except Exception as exc:
            log.exception("manual group backup failed | group=%s", group_id)
            await send_group_text(group, f"❌ بکاپ گپ ساخته نشد: {type(exc).__name__}")
            return
        await send_group_text(
            group,
            "💾 ZIVO | GROUP BACKUP\n━━━━━━━━━━━━━━━━━━\n"
            f"✅ بکاپ دقیق گپ ساخته شد.\n🗃 جدول‌ها: {stats_num(result['tables'])}\n"
            f"📦 رکوردها: {stats_num(result['rows'])}\n🔐 SHA256: {result['sha256'][:16]}…\n"
            "📍 نسخه latest.json هم به‌روزرسانی شد.\n━━━━━━━━━━━━━━━━━━\n⚡ ZIVO | SAFE STATE",
        )
        return
    if action == "backup_toggle":
        settings = set_group_backup_settings(group_id, actor_id, enabled=bool(parsed["enabled"]))
        await send_group_text(group, f"💾 بکاپ خودکار گپ {'فعال ✅' if settings['enabled'] else 'خاموش ⏸'} شد.")
        return
    if action == "backup_interval":
        minutes = int(parsed["minutes"])
        if minutes < 5 or minutes > 1440:
            await send_group_text(group, "⚠️ فاصله بکاپ باید بین 5 تا 1440 دقیقه باشه.")
            return
        settings = set_group_backup_settings(group_id, actor_id, interval_minutes=minutes)
        await send_group_text(group, f"⏱ فاصله بکاپ خودکار روی {settings['interval_minutes']} دقیقه ذخیره شد.")
        return
    if action == "backup_keep":
        count = int(parsed["count"])
        if count < 5 or count > 500:
            await send_group_text(group, "⚠️ تعداد نگهداری بکاپ باید بین 5 تا 500 باشه.")
            return
        settings = set_group_backup_settings(group_id, actor_id, keep_count=count)
        await send_group_text(group, f"🗂 تعداد نسخه‌های نگهداری‌شده روی {settings['keep_count']} تنظیم شد.")
        return
    settings = get_group_backup_settings(group_id)
    last = settings.get("last_backup_at") or "هنوز ساخته نشده"
    await send_group_text(
        group,
        "💾 ZIVO | BACKUP STATUS\n━━━━━━━━━━━━━━━━━━\n"
        f"🔘 خودکار: {'فعال' if settings['enabled'] else 'خاموش'}\n"
        f"⏱ فاصله: {settings['interval_minutes']} دقیقه\n🗂 نگهداری: {settings['keep_count']} نسخه\n"
        f"🕒 آخرین بکاپ: {last}\n📦 رکورد آخر: {settings['last_backup_rows']}\n"
        f"🔐 SHA: {(settings['last_backup_sha256'][:16] + '…') if settings['last_backup_sha256'] else 'ندارد'}\n"
        "━━━━━━━━━━━━━━━━━━\n⚡ ZIVO | SAFE STATE",
    )


def get_pin_settings(group_id: int) -> Dict[str, Any]:
    with db_connect() as con:
        row = con.execute(
            """
            SELECT delete_after_expiry
            FROM pin_settings
            WHERE group_id = ?
            """,
            (int(group_id),),
        ).fetchone()

    return {
        "delete_after_expiry": (
            bool(int(row["delete_after_expiry"] or 0))
            if row is not None
            else False
        )
    }


def set_pin_delete_after_expiry(
    group_id: int,
    enabled: bool,
    actor_id: int,
) -> Dict[str, Any]:
    now = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO pin_settings (
                group_id,
                delete_after_expiry,
                updated_by,
                updated_at
            ) VALUES (?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                delete_after_expiry = excluded.delete_after_expiry,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                1 if enabled else 0,
                int(actor_id),
                now,
            ),
        )
        con.commit()

    return get_pin_settings(group_id)


def upsert_pin_job(
    group_id: int,
    message_id: int,
    peer_kind: str,
    group_access_hash: int,
    expires_at: datetime,
    delete_message: bool,
    actor_id: int,
) -> None:
    now = datetime.now(timezone.utc).isoformat()
    expire_iso = expires_at.astimezone(timezone.utc).isoformat()

    peer_kind = (
        "chat"
        if peer_kind == "chat"
        else "channel"
    )

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO pin_jobs (
                group_id,
                message_id,
                peer_kind,
                group_access_hash,
                expires_at,
                delete_message,
                created_by,
                created_at,
                retry_count
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, 0)
            ON CONFLICT(group_id, message_id) DO UPDATE SET
                peer_kind = excluded.peer_kind,
                group_access_hash = excluded.group_access_hash,
                expires_at = excluded.expires_at,
                delete_message = excluded.delete_message,
                created_by = excluded.created_by,
                created_at = excluded.created_at,
                retry_count = 0
            """,
            (
                int(group_id),
                int(message_id),
                peer_kind,
                int(group_access_hash or 0),
                expire_iso,
                1 if delete_message else 0,
                int(actor_id),
                now,
            ),
        )
        con.commit()


def cancel_pin_job(
    group_id: int,
    message_id: int,
) -> None:
    with db_connect() as con:
        con.execute(
            """
            DELETE FROM pin_jobs
            WHERE group_id = ? AND message_id = ?
            """,
            (
                int(group_id),
                int(message_id),
            ),
        )
        con.commit()


def active_pin_job_count(group_id: int) -> int:
    with db_connect() as con:
        row = con.execute(
            """
            SELECT COUNT(*) AS c
            FROM pin_jobs
            WHERE group_id = ?
            """,
            (int(group_id),),
        ).fetchone()

    return int(row["c"] or 0) if row else 0


def due_pin_jobs(limit: int = 25) -> List[sqlite3.Row]:
    now = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        return con.execute(
            """
            SELECT
                group_id,
                message_id,
                peer_kind,
                group_access_hash,
                expires_at,
                delete_message,
                created_by,
                retry_count
            FROM pin_jobs
            WHERE expires_at <= ?
            ORDER BY expires_at ASC
            LIMIT ?
            """,
            (
                now,
                int(limit),
            ),
        ).fetchall()


def increment_pin_job_retry(
    group_id: int,
    message_id: int,
) -> int:
    with db_connect() as con:
        con.execute(
            """
            UPDATE pin_jobs
            SET retry_count = retry_count + 1
            WHERE group_id = ? AND message_id = ?
            """,
            (
                int(group_id),
                int(message_id),
            ),
        )

        row = con.execute(
            """
            SELECT retry_count
            FROM pin_jobs
            WHERE group_id = ? AND message_id = ?
            """,
            (
                int(group_id),
                int(message_id),
            ),
        ).fetchone()

        con.commit()

    return int(row["retry_count"] or 0) if row else 0


def normalize_lock_name(
    value: str,
) -> Optional[str]:
    text = normalize_group_command(
        value
    )

    if text.startswith("قفل "):
        text = text[4:].strip()

    aliases = {
        "تبلیغ": "تبلیغات",
        "اسپم": "تبلیغات",
        "لینک ها": "لینک",
        "لینک‌ها": "لینک",
        "ایدی": "آیدی",
        "ای دی": "آیدی",
        "عکس ها": "عکس",
        "عکس‌ها": "عکس",
        "ویدئو": "ویدیو",
        "وویس": "ویس",
        "فایل بزرگ": "فایل حجیم",
        "فایل سنگین": "فایل حجیم",
        "گيف": "گیف",
        "موزیک": "آهنگ",
        "اهنگ": "آهنگ",
        "فحاشی": "فحش",
        "پیام فیلترشده": "پیام‌های فیلترشده",
        "پیام فیلتر شده": "پیام‌های فیلترشده",
        "پیام های فیلترشده": "پیام‌های فیلترشده",
        "پیام های فیلتر شده": "پیام‌های فیلترشده",
        "پیام‌های فیلتر شده": "پیام‌های فیلترشده",
        "انگلیسی": "متن انگلیسی",
        "ریپ": "ریپلای",
        "فورواردها": "فوروارد",
        "ادیت": "ویرایش",
        "ایموجی ها": "ایموجی",
        "ایموجی‌ها": "ایموجی",
        "کد هنگ": "کد هنگی",
        "نظر سنجی": "نظرسنجی",
        "شماره": "شماره تلفن",
        "شماره موبایل": "شماره تلفن",
        "اعداد": "عدد",
        "هشتگ ها": "هشتگ",
        "هشتگ‌ها": "هشتگ",
    }

    text = aliases.get(
        text,
        text,
    )

    if text in LOCK_CATALOG:
        return text

    return None


def legacy_enabled_lock_names(
    group_id: int,
) -> set[str]:
    installation = get_installation(
        group_id
    )

    if installation is None:
        return set()

    raw = installation[
        "default_locks_json"
    ]

    try:
        values = json.loads(
            raw or "[]"
        )
    except Exception:
        values = []

    result: set[str] = set()

    for value in values or []:
        normalized = normalize_lock_name(
            str(value)
        )
        if normalized:
            result.add(
                normalized
            )

    return result


def ensure_group_lock_settings(
    group_id: int,
) -> None:
    now = datetime.now(
        timezone.utc
    ).isoformat()

    legacy_enabled = legacy_enabled_lock_names(
        group_id
    )

    with db_connect() as con:
        existing = {
            row["lock_name"]
            for row in con.execute(
                """
                SELECT lock_name
                FROM group_locks
                WHERE group_id = ?
                """,
                (int(group_id),),
            ).fetchall()
        }

        for lock_name in LOCK_CATALOG:
            if lock_name in existing:
                continue

            con.execute(
                """
                INSERT INTO group_locks (
                    group_id,
                    lock_name,
                    enabled,
                    max_warnings,
                    auto_ban,
                    direct_action,
                    final_action,
                    updated_by,
                    updated_at
                ) VALUES (?, ?, ?, ?, ?, 'warning', 'ban', 0, ?)
                """,
                (
                    int(group_id),
                    lock_name,
                    1 if lock_name in legacy_enabled else 0,
                    LOCK_DEFAULT_MAX_WARNINGS,
                    1 if LOCK_DEFAULT_AUTO_BAN.get(lock_name, False) else 0,
                    now,
                ),
            )

        con.commit()


def activate_default_install_locks(
    group_id: int,
    actor_id: int = 0,
) -> None:
    group_id = int(group_id)
    actor_id = int(actor_id or 0)
    ensure_group_lock_settings(group_id)
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        for lock_name in DEFAULT_LOCK_NAMES:
            con.execute(
                """
                UPDATE group_locks
                SET enabled = 1, updated_by = ?, updated_at = ?
                WHERE group_id = ? AND lock_name = ?
                """,
                (actor_id, now, group_id, lock_name),
            )
        con.execute(
            "UPDATE installations SET default_locks_json = ? WHERE group_id = ?",
            (json.dumps(DEFAULT_LOCKS, ensure_ascii=False), group_id),
        )
        con.commit()
    mark_group_backup_dirty(group_id)


def classic_default_lock_block(group_id: int) -> str:
    activate_default_install_locks(group_id)
    rows = group_lock_rows(group_id)
    return "\n".join(
        f"✅ قفل {lock_name}"
        for lock_name in DEFAULT_LOCK_NAMES
        if lock_name in rows and bool(int(rows[lock_name]["enabled"] or 0))
    )


def group_lock_rows(
    group_id: int,
) -> Dict[str, sqlite3.Row]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _group_lock_rows_hot_cache.get(gid)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        # Internal callers treat this mapping as read-only. Returning the cached
        # mapping directly avoids allocating/copying ~30 lock entries per group
        # message on the hottest moderation path.
        return cached[1]
    ensure_group_lock_settings(gid)
    with db_connect() as con:
        rows = con.execute("SELECT * FROM group_locks WHERE group_id = ?", (gid,)).fetchall()
    result = {row["lock_name"]: row for row in rows}
    _group_lock_rows_hot_cache[gid] = (now, result)
    _group_enabled_lock_names_hot_cache[gid] = (
        now,
        frozenset(
            name for name, row in result.items()
            if bool(int(row["enabled"] or 0))
        ),
    )
    return result


def enabled_group_lock_names(
    group_id: int,
    rows: Optional[Dict[str, sqlite3.Row]] = None,
) -> frozenset[str]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _group_enabled_lock_names_hot_cache.get(gid)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return cached[1]
    lock_rows = rows if rows is not None else group_lock_rows(gid)
    enabled = frozenset(
        name for name, row in lock_rows.items()
        if bool(int(row["enabled"] or 0))
    )
    _group_enabled_lock_names_hot_cache[gid] = (now, enabled)
    return enabled


def group_lock_row(
    group_id: int,
    lock_name: str,
) -> Optional[sqlite3.Row]:
    return group_lock_rows(int(group_id)).get(lock_name)


