def lock_action_label(
    value: str,
) -> str:
    mapping = {
        "delete": "حذف بی‌صدا",
        "notice": "هشدار",
        "warning": "اخطار",
        "mute": "سکوت",
        "ban": "بن",
    }
    return mapping.get(
        (value or "").strip().lower(),
        "اخطار",
    )


def normalize_lock_action(
    value: str,
) -> str:
    mapping = {
        "حذف": "delete",
        "حذف بی صدا": "delete",
        "حذف بی‌صدا": "delete",
        "هشدار": "notice",
        "اخطار": "warning",
        "سکوت": "mute",
        "بن": "ban",
        "delete": "delete",
        "notice": "notice",
        "warning": "warning",
        "mute": "mute",
        "ban": "ban",
    }
    normalized = mapping.get(
        (value or "").strip().lower()
    )
    if normalized is None:
        raise ValueError(
            "INVALID_LOCK_ACTION"
        )
    return normalized


