def lock_user_is_exempt(
    group_id: int,
    user_id: int,
) -> bool:
    if base_bot_role(
        group_id,
        user_id,
    ) in {
        "مالک",
        "ادمین",
        "ویژه",
    }:
        return True

    return is_bot_exempt(
        group_id,
        user_id,
    )



def lock_user_is_always_exempt(
    group_id: int,
    user_id: int,
) -> bool:
    """Owner/admin and explicit exemptions always bypass group locks.

    Specials are intentionally NOT handled here because zivo60.9 lets their
    access be controlled per lock and, optionally, per individual special.
    """
    if base_bot_role(group_id, user_id) in {"مالک", "ادمین"}:
        return True
    return is_bot_exempt(group_id, user_id)


def special_lock_default_bypass(
    group_id: int,
    lock_name: str,
) -> bool:
    canonical = normalize_lock_name(lock_name)
    if canonical is None:
        return True
    key = (int(group_id), canonical)
    if key in _special_lock_default_hot:
        return bool(_special_lock_default_hot[key])
    with db_connect() as con:
        row = con.execute(
            "SELECT bypass_enabled FROM special_lock_defaults WHERE group_id = ? AND lock_name = ?",
            (int(group_id), canonical),
        ).fetchone()
    # Backward compatibility: before this feature all specials bypassed locks.
    result = True if row is None else bool(int(row["bypass_enabled"] or 0))
    _special_lock_default_hot[key] = result
    return result


def special_lock_user_override(
    group_id: int,
    user_id: int,
    lock_name: str,
) -> Optional[bool]:
    canonical = normalize_lock_name(lock_name)
    if canonical is None:
        return None
    key = (int(group_id), int(user_id), canonical)
    if key in _special_lock_override_hot:
        return bool(_special_lock_override_hot[key])
    if key in _special_lock_override_absent_hot:
        return None
    with db_connect() as con:
        row = con.execute(
            "SELECT bypass_enabled FROM special_lock_overrides WHERE group_id = ? AND user_id = ? AND lock_name = ?",
            (int(group_id), int(user_id), canonical),
        ).fetchone()
    if row is None:
        _special_lock_override_absent_hot.add(key)
        return None
    result = bool(int(row["bypass_enabled"] or 0))
    _special_lock_override_hot[key] = result
    return result


def special_user_bypasses_lock(
    group_id: int,
    user_id: int,
    lock_name: str,
) -> bool:
    if lock_user_is_always_exempt(group_id, user_id):
        return True
    if base_bot_role(group_id, user_id) != "ویژه":
        return False
    override = special_lock_user_override(group_id, user_id, lock_name)
    if override is not None:
        return override
    return special_lock_default_bypass(group_id, lock_name)


def set_special_lock_default(
    group_id: int,
    lock_name: str,
    bypass_enabled: bool,
    actor_id: int,
) -> None:
    canonical = normalize_lock_name(lock_name)
    if canonical is None:
        raise ValueError("UNKNOWN_LOCK")
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO special_lock_defaults (
                group_id, lock_name, bypass_enabled, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(group_id, lock_name) DO UPDATE SET
                bypass_enabled = excluded.bypass_enabled,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (int(group_id), canonical, 1 if bypass_enabled else 0, int(actor_id or 0), now),
        )
        con.commit()
    _special_lock_default_hot[(int(group_id), canonical)] = bool(bypass_enabled)
    mark_group_backup_dirty(group_id)


def set_special_lock_override(
    group_id: int,
    user_id: int,
    lock_name: str,
    bypass_enabled: bool,
    actor_id: int,
) -> None:
    canonical = normalize_lock_name(lock_name)
    if canonical is None:
        raise ValueError("UNKNOWN_LOCK")
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO special_lock_overrides (
                group_id, user_id, lock_name, bypass_enabled, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id, user_id, lock_name) DO UPDATE SET
                bypass_enabled = excluded.bypass_enabled,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (int(group_id), int(user_id), canonical, 1 if bypass_enabled else 0, int(actor_id or 0), now),
        )
        con.commit()
    cache_key = (int(group_id), int(user_id), canonical)
    _special_lock_override_hot[cache_key] = bool(bypass_enabled)
    _special_lock_override_absent_hot.discard(cache_key)
    mark_group_backup_dirty(group_id)


def reset_special_lock_override(
    group_id: int,
    user_id: int,
    lock_name: Optional[str] = None,
) -> int:
    with db_connect() as con:
        if lock_name is None:
            cur = con.execute(
                "DELETE FROM special_lock_overrides WHERE group_id = ? AND user_id = ?",
                (int(group_id), int(user_id)),
            )
        else:
            canonical = normalize_lock_name(lock_name)
            if canonical is None:
                return 0
            cur = con.execute(
                "DELETE FROM special_lock_overrides WHERE group_id = ? AND user_id = ? AND lock_name = ?",
                (int(group_id), int(user_id), canonical),
            )
        con.commit()
    if lock_name is None:
        prefix = (int(group_id), int(user_id))
        for key in [item for item in _special_lock_override_hot if item[:2] == prefix]:
            _special_lock_override_hot.pop(key, None)
        for canonical_name in LOCK_CATALOG:
            _special_lock_override_absent_hot.add((prefix[0], prefix[1], canonical_name))
    else:
        cache_key = (int(group_id), int(user_id), canonical)
        _special_lock_override_hot.pop(cache_key, None)
        _special_lock_override_absent_hot.add(cache_key)
    if cur.rowcount:
        mark_group_backup_dirty(group_id)
    return int(cur.rowcount or 0)


def set_all_special_lock_defaults(
    group_id: int,
    bypass_enabled: bool,
    actor_id: int,
) -> None:
    for lock_name in LOCK_CATALOG:
        set_special_lock_default(group_id, lock_name, bypass_enabled, actor_id)


def parse_special_access_command(text: str) -> Optional[Dict[str, Any]]:
    normalized = normalize_group_command(text)
    if normalized in {"دسترسی ویژه", "وضعیت دسترسی ویژه", "دسترسی های ویژه", "دسترسی‌های ویژه"}:
        return {"action": "status"}
    if normalized in {"ریست دسترسی ویژه", "بازنشانی دسترسی ویژه"}:
        return {"action": "reset_user"}

    match = re.fullmatch(r"دسترسی ویژه\s+(.+?)\s+(فعال|خاموش)", normalized)
    if match:
        raw_lock, mode = match.groups()
        if raw_lock.strip() in {"همه", "تمام", "همه قفل ها", "همه قفل‌ها"}:
            return {"action": "set_all", "enabled": mode == "فعال"}
        lock_name = normalize_lock_name(raw_lock)
        if lock_name is not None:
            return {"action": "set_one", "lock_name": lock_name, "enabled": mode == "فعال"}

    match = re.fullmatch(r"ریست دسترسی ویژه\s+(.+)", normalized)
    if match:
        lock_name = normalize_lock_name(match.group(1))
        if lock_name is not None:
            return {"action": "reset_one", "lock_name": lock_name}

    return None


def special_access_matrix_text(
    group_id: int,
    user_id: Optional[int] = None,
) -> str:
    lines = [
        "💠 ZIVO | دسترسی ویژه‌ها",
        "━━━━━━━━━━━━━━━━━━",
    ]
    if user_id is None:
        lines.append("📌 حالت پیش‌فرض همه کاربران ویژه:")
        for lock_name in LOCK_CATALOG:
            allowed = special_lock_default_bypass(group_id, lock_name)
            lines.append(f"{'✅' if allowed else '🔒'} {lock_name}: {'عبور از قفل' if allowed else 'تابع قفل'}")
        lines.extend([
            "",
            "💡 بدون ریپلای: تنظیم پیش‌فرض همه ویژه‌ها",
            "💡 با ریپلای روی یک ویژه: تنظیم اختصاصی همان کاربر",
        ])
    else:
        lines.append(f"👤 ویژه: {int(user_id)}")
        for lock_name in LOCK_CATALOG:
            override = special_lock_user_override(group_id, user_id, lock_name)
            effective = special_user_bypasses_lock(group_id, user_id, lock_name)
            source = "اختصاصی" if override is not None else "پیش‌فرض"
            lines.append(f"{'✅' if effective else '🔒'} {lock_name}: {'عبور' if effective else 'تابع قفل'} ({source})")
    return "\n".join(lines)[:3900]


async def command_special_access(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    actor_role = base_bot_role(group_id, actor_id)
    if actor_role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ تنظیم دسترسی ویژه‌ها فقط برای مالک و ادمین زیوو فعاله.")
        return

    target_id: Optional[int] = None
    if bool(getattr(event, "is_reply", False)):
        target_id, _target_hash, _target_username = await replied_user_target(event)
        if target_id is not None and base_bot_role(group_id, target_id) != "ویژه":
            await send_group_text(group, "⚠️ کاربر ریپلای‌شده باید مقام «ویژه» داشته باشه.")
            return

    action = parsed.get("action")
    if action == "status":
        await send_group_text(group, special_access_matrix_text(group_id, target_id))
        return

    if action == "set_all":
        if target_id is not None:
            for lock_name in LOCK_CATALOG:
                set_special_lock_override(group_id, target_id, lock_name, bool(parsed["enabled"]), actor_id)
            await send_group_text(
                group,
                f"✅ دسترسی تمام قفل‌ها برای این ویژه روی «{'عبور از قفل' if parsed['enabled'] else 'تابع قفل'}» تنظیم شد.",
            )
        else:
            set_all_special_lock_defaults(group_id, bool(parsed["enabled"]), actor_id)
            await send_group_text(
                group,
                f"✅ پیش‌فرض تمام ویژه‌ها برای همه قفل‌ها روی «{'عبور از قفل' if parsed['enabled'] else 'تابع قفل'}» تنظیم شد.",
            )
        return

    if action == "set_one":
        lock_name = str(parsed["lock_name"])
        enabled = bool(parsed["enabled"])
        if target_id is not None:
            set_special_lock_override(group_id, target_id, lock_name, enabled, actor_id)
            await send_group_text(
                group,
                f"✅ دسترسی اختصاصی این ویژه برای «{lock_name}» روی «{'مجاز به عبور' if enabled else 'تابع قفل'}» تنظیم شد.",
            )
        else:
            set_special_lock_default(group_id, lock_name, enabled, actor_id)
            await send_group_text(
                group,
                f"✅ پیش‌فرض همه ویژه‌ها برای «{lock_name}» روی «{'مجاز به عبور' if enabled else 'تابع قفل'}» تنظیم شد.",
            )
        return

    if action == "reset_one":
        if target_id is None:
            await send_group_text(group, "↩️ برای ریست اختصاصی، روی پیام همان کاربر ویژه ریپلای کن.")
            return
        removed = reset_special_lock_override(group_id, target_id, str(parsed["lock_name"]))
        await send_group_text(group, "✅ تنظیم اختصاصی حذف شد و این ویژه دوباره از پیش‌فرض گروه پیروی می‌کند." if removed else "ℹ️ برای این قفل تنظیم اختصاصی ثبت نشده بود.")
        return

    if action == "reset_user":
        if target_id is None:
            await send_group_text(group, "↩️ روی پیام کاربر ویژه ریپلای کن و بنویس: ریست دسترسی ویژه")
            return
        removed = reset_special_lock_override(group_id, target_id, None)
        await send_group_text(group, f"✅ {stats_num(removed)} تنظیم اختصاصی این ویژه حذف شد؛ از این به بعد از پیش‌فرض گروه پیروی می‌کند.")
        return


def lock_status_text(
    row: sqlite3.Row,
) -> str:
    enabled = bool(
        int(row["enabled"] or 0)
    )

    if not enabled:
        return "خاموش"

    maximum = stats_num(
        int(
            row["max_warnings"]
            or LOCK_DEFAULT_MAX_WARNINGS
        )
    )
    auto_ban = bool(
        int(row["auto_ban"] or 0)
    )

    punishment = lock_action_label(
        row["direct_action"]
        or "warning"
    )

    return (
        f"روشن  |  اخطار {maximum}  |  "
        f"بن {'روشن' if auto_ban else 'خاموش'}  |  "
        f"مجازات {punishment}"
    )


def group_lock_list_text(
    group_id: int,
) -> str:
    rows = group_lock_rows(
        group_id
    )

    items = [
        {
            "name": lock_name,
            "enabled": bool(int(rows[lock_name]["enabled"] or 0)),
            "max_warnings": int(rows[lock_name]["max_warnings"] or LOCK_DEFAULT_MAX_WARNINGS),
            "auto_ban": bool(int(rows[lock_name]["auto_ban"] or 0)),
            "punishment": lock_action_label(rows[lock_name]["direct_action"] or "warning"),
        }
        for lock_name in LOCK_CATALOG
    ]
    return lock_center_text(items)

    active_count = sum(
        1
        for lock_name in LOCK_CATALOG
        if bool(
            int(
                rows[lock_name]["enabled"]
                or 0
            )
        )
    )

    lines = [
        "🔐 ZIVO | LOCK MATRIX",
        "━━━━━━━━━━━━━━━━━━",
        f"فعال: {stats_num(active_count)}  |  کل: {stats_num(len(LOCK_CATALOG))}",
        "",
    ]

    for lock_name in LOCK_CATALOG:
        row = rows[lock_name]
        enabled = bool(
            int(row["enabled"] or 0)
        )

        if enabled:
            maximum = stats_num(
                int(
                    row["max_warnings"]
                    or LOCK_DEFAULT_MAX_WARNINGS
                )
            )
            auto_ban = bool(
                int(row["auto_ban"] or 0)
            )
            punishment = lock_action_label(
                row["direct_action"]
                or "warning"
            )
            state = (
                f"✅ {lock_name}\n"
                f"   اخطار {maximum}  ·  بن {'روشن' if auto_ban else 'خاموش'}"
                f"  ·  مجازات {punishment}"
            )
        else:
            state = f"❌ {lock_name}"

        lines.append(state)

    lines.extend(
        (
            "",
            "━━━━━━━━━━━━━━━━━━",
            "⚡ ZIVO | LOCK CONTROL",
        )
    )

    return "\n".join(lines)


