def get_group_pro_entitlement(
    group_id: int,
) -> Dict[str, Any]:
    if int(group_id) in PRO_GROUP_IDS:
        return {
            "active": True,
            "expires_at": None,
            "source": "environment",
        }

    with db_connect() as con:
        row = con.execute(
            """
            SELECT active, expires_at, source
            FROM pro_entitlements
            WHERE group_id = ?
            """,
            (int(group_id),),
        ).fetchone()

    if row is None:
        return {
            "active": False,
            "expires_at": None,
            "source": "",
        }

    active = bool(int(row["active"] or 0))
    expires_at = row["expires_at"]

    if active and expires_at:
        try:
            expiry = datetime.fromisoformat(expires_at)
            if expiry.tzinfo is None:
                expiry = expiry.replace(tzinfo=timezone.utc)

            if expiry.astimezone(timezone.utc) <= datetime.now(timezone.utc):
                active = False
        except Exception:
            active = False

    return {
        "active": active,
        "expires_at": expires_at,
        "source": row["source"] or "",
    }


def is_group_pro_active(
    group_id: int,
) -> bool:
    return bool(
        get_group_pro_entitlement(
            group_id
        )["active"]
    )


def is_group_pro_active_for_actor(
    group_id: int,
    actor_id: int,
) -> bool:
    # Owner access is never paywalled. This covers both the configured global
    # owner and the live/internal ZIVO owner of the group.
    try:
        if int(actor_id) == int(GLOBAL_BOT_OWNER_ID):
            return True
    except Exception:
        pass
    try:
        if base_bot_role(int(group_id), int(actor_id)) == "مالک":
            return True
    except Exception:
        pass
    return is_group_pro_active(group_id)

def upsert_group_pro_entitlement(
    group_id: int,
    active: bool,
    expires_at: Optional[datetime] = None,
    source: str = "operator",
) -> None:
    """
    Internal/operator hook. There is intentionally no group chat command that
    can grant Pro access to itself.
    """
    expiry_text = None

    if expires_at is not None:
        if expires_at.tzinfo is None:
            expires_at = expires_at.replace(tzinfo=timezone.utc)

        expiry_text = expires_at.astimezone(
            timezone.utc
        ).isoformat()

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO pro_entitlements (
                group_id,
                active,
                expires_at,
                source,
                updated_at
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                active = excluded.active,
                expires_at = excluded.expires_at,
                source = excluded.source,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                1 if active else 0,
                expiry_text,
                source or "operator",
                datetime.now(timezone.utc).isoformat(),
            ),
        )
        con.commit()




