def _premium_duration_from_text(text: str) -> int:
    raw = str(text or "").translate(PERSIAN_ARABIC_TO_ASCII)
    match = re.search(r"(?<!\d)(1|2|3)\s*ماه", raw)
    if not match:
        return 0
    return {"1": 30, "2": 60, "3": 90}.get(match.group(1), 0)


def _premium_plan_from_text(text: str) -> str:
    low = str(text or "").replace("‌", " ").lower()
    if "نقره" in low or "silver" in low:
        return premium.PLAN_SILVER
    if "طل" in low or "gold" in low:
        return premium.PLAN_GOLD
    if "الماس" in low or "diamond" in low:
        return premium.PLAN_DIAMOND
    return ""


def parse_premium_group_command(raw_text: Any) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(str(raw_text or ""))
    low = text.replace("‌", " ").strip()
    if low in {"پلن ها", "پلن‌ها", "پلنها", "اشتراک"}:
        return {"action": "plans"}
    if low in {"پلن من", "اشتراک من", "وضعیت اشتراک"}:
        return {"action": "status"}
    if low == "خرید اشتراک":
        return {"action": "buy_menu"}
    if low.startswith("خرید "):
        plan = _premium_plan_from_text(low)
        days = _premium_duration_from_text(low)
        if plan and days:
            return {"action": "create_order", "plan": plan, "duration_days": days}
    return None


def _premium_discount_saving(plan: str, days: int, amount: int) -> int:
    one = premium.get_price(plan, 30) or 0
    months = {30: 1, 60: 2, 90: 3}.get(int(days), 0)
    if months <= 1 or one <= 0:
        return 0
    return max(0, int(one) * months - int(amount))


def _premium_prices_text(group_title: str = "") -> Tuple[str, List[str]]:
    rows = premium.all_prices()
    by_plan: Dict[str, Dict[int, int]] = {}
    for row in rows:
        if int(row.get("enabled") or 0) and int(row.get("amount_rial") or 0) > 0:
            by_plan.setdefault(str(row.get("plan") or ""), {})[int(row.get("duration_days") or 0)] = int(row.get("amount_rial") or 0)
    lines = [
        "ZIVO | خرید اشتراک",
        "━━━━━━━━━━━━━━━━━━",
    ]
    if group_title:
        lines.extend([f"گروه انتخاب‌شده: {group_title}", ""])
    lines.extend([
        "🆓 رایگان — اولویت پاسخ پایه",
        "🥈 نقره‌ای — اولویت پاسخ نقره‌ای",
        "🥇 طلایی — اولویت پاسخ سریع",
        "💎 الماس — بالاترین اولویت پاسخ",
        "",
        "قیمت‌ها:",
    ])
    commands: List[str] = []
    plan_names = {
        premium.PLAN_SILVER: "نقره‌ای",
        premium.PLAN_GOLD: "طلایی",
        premium.PLAN_DIAMOND: "الماس",
    }
    for plan in (premium.PLAN_SILVER, premium.PLAN_GOLD, premium.PLAN_DIAMOND):
        prices = by_plan.get(plan, {})
        lines.append(f"\n{premium.plan_label(plan)}")
        for days in premium.DURATION_ORDER:
            amount = prices.get(days)
            if not amount:
                continue
            months = {30: 1, 60: 2, 90: 3}[days]
            saving = _premium_discount_saving(plan, days, amount)
            line = f"• {months} ماه: {premium.money_rial(amount)} ({premium.money_toman(amount)})"
            if saving > 0:
                line += f" | {premium.money_toman(saving)} تخفیف"
            lines.append(line)
            commands.append(f"خرید {plan_names[plan]} {months} ماهه")
    lines.extend([
        "",
        "برای خرید یکی از فرمان‌های زیر را بفرست:",
    ])
    lines.extend(commands)
    return "\n".join(lines), commands


def _premium_remaining_text(state: Dict[str, Any]) -> str:
    expiry = state.get("expires_at")
    if not expiry:
        return "دائمی"
    try:
        end = datetime.fromisoformat(str(expiry))
        if end.tzinfo is None:
            end = end.replace(tzinfo=timezone.utc)
        delta = end.astimezone(timezone.utc) - datetime.now(timezone.utc)
        total = max(0, int(delta.total_seconds()))
        days, rem = divmod(total, 86400)
        hours = rem // 3600
        if days > 0:
            return f"{days} روز و {hours} ساعت"
        minutes = max(0, rem % 3600 // 60)
        return f"{hours} ساعت و {minutes} دقیقه"
    except Exception:
        return "نامشخص"


def _premium_status_text(group_id: int) -> str:
    state = premium.get_subscription(int(group_id), use_cache=False)
    plan = str(state.get("plan") or premium.PLAN_FREE)
    lines = [
        "ZIVO | وضعیت اشتراک",
        "━━━━━━━━━━━━━━━━━━",
        f"پلن: {premium.plan_label(plan)}",
        f"اولویت پاسخ: { {premium.PLAN_DIAMOND: 'بالاترین', premium.PLAN_GOLD: 'سریع', premium.PLAN_SILVER: 'نقره‌ای', premium.PLAN_FREE: 'پایه'}.get(plan, 'پایه') }",
        f"وضعیت: {state.get('status') or 'active'}",
        f"زمان باقی‌مانده: {_premium_remaining_text(state)}",
    ]
    expiry = state.get("expires_at")
    if expiry:
        try:
            dt = datetime.fromisoformat(str(expiry)).astimezone(IRAN_TZ)
            lines.append(f"فعال تا: {dt.strftime('%Y-%m-%d %H:%M')} ایران")
        except Exception:
            lines.append(f"فعال تا: {expiry}")
    else:
        lines.append("فعال تا: دائمی")
    if int(state.get("order_id") or 0) > 0:
        order = premium.get_order(int(state.get("order_id") or 0))
        if order:
            lines.append(f"کد آخرین خرید: {order.get('order_code') or '—'}")
    return "\n".join(lines)


def _premium_group_actor_can_buy(group_id: int, actor_id: int) -> bool:
    # Any real member may sponsor Premium for the current installed group.
    # Administrative authority is still required for management actions, not payment.
    return int(group_id or 0) > 0 and int(actor_id or 0) > 0


async def command_premium_group(event: Any, group: Any, group_id: int, parsed: Dict[str, Any]) -> None:
    action = str(parsed.get("action") or "")
    title = str(getattr(group, "title", None) or getattr(event, "chat_title", None) or f"گروه {int(group_id)}")
    if action in {"plans", "buy_menu"}:
        text, commands = _premium_prices_text(title)
        await send_copyable_command_text(group, text, commands)
        return
    if action == "status":
        await send_group_text(group, _premium_status_text(int(group_id)))
        return
    if action != "create_order":
        return
    actor_id = int(safe_int(getattr(event, "sender_id", None)) or 0)
    if not _premium_group_actor_can_buy(int(group_id), actor_id):
        await send_group_text(group, "خرید اشتراک برای این پیام قابل شروع نیست.")
        return
    plan = str(parsed.get("plan") or "")
    days = int(parsed.get("duration_days") or 0)
    amount = premium.get_price(plan, days)
    if amount is None:
        await send_group_text(group, "این پلن یا مدت در حال حاضر برای خرید فعال نیست.")
        return
    order = await asyncio.to_thread(premium.create_order, actor_id, int(group_id), title, plan, days)
    code = str(order.get("order_code") or "")
    await asyncio.to_thread(premium.set_checkout_session, actor_id, int(group_id), title, int(order.get("order_id") or 0), "order-created", 180)
    command = f"پرداخت {code}"
    text = (
        "ZIVO | سفارش ساخته شد\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"کد سفارش: {code}\n"
        f"گروه: {title}\n"
        f"پلن: {premium.plan_label(plan)}\n"
        f"مدت: {premium.duration_label(days)}\n"
        f"مبلغ: {premium.money_rial(amount)} ({premium.money_toman(amount)})\n\n"
        "برای حفظ اطلاعات مالی، پرداخت در پیوی ZIVO انجام می‌شود.\n"
        f"در پیوی بفرست: {command}"
    )
    await send_copyable_command_text(group, text, [code, command])
    try:
        await asyncio.to_thread(
            social_games.queue_notification,
            actor_id,
            f"سفارش {code} برای گروه «{title}» ساخته شد. برای ادامه در پیوی بفرست: {command}",
        )
    except Exception:
        pass


def parse_premium_private_command(raw_text: Any) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(str(raw_text or ""))
    low = text.replace("‌", " ").strip()
    if low in {"پلن ها", "پلن‌ها", "پلنها", "اشتراک"}:
        return {"action": "plans"}
    if low in {"خرید اشتراک", "اشتراک بخر", "خرید پرمیوم"}:
        return {"action": "start_purchase"}
    if low in {"اشتراک من", "اشتراک های من", "اشتراک‌های من", "پلن من"}:
        return {"action": "my_subscriptions"}
    if low in {"خریدهای من", "تراکنش های من", "تراکنش‌های من", "سفارش های من", "سفارش‌های من"}:
        return {"action": "history"}
    if low in {"کیف پول", "موجودی کیف پول", "موجودی"}:
        return {"action": "wallet_balance"}
    if low in {"شارژ کیف پول", "افزایش موجودی"}:
        return {"action": "wallet_topup_start"}
    if low in {"لغو خرید", "لغو سفارش", "انصراف"}:
        return {"action": "cancel_checkout"}
    if low.startswith("خرید "):
        plan = _premium_plan_from_text(low)
        days = _premium_duration_from_text(low)
        if plan and days:
            return {"action": "create_order", "plan": plan, "duration_days": days}
    order_ref_pattern = r"([A-Za-z0-9\-]{3,40}|[0-9۰-۹٠-٩]+)"
    match = re.fullmatch(rf"(?:پرداخت|وضعیت سفارش|سفارش)\s+{order_ref_pattern}", low, re.I)
    if match:
        return {"action": "payment_menu", "order_ref": match.group(1)}
    match = re.fullmatch(rf"(?:کیف پول|پرداخت کیف پول)\s+{order_ref_pattern}", low, re.I)
    if match:
        return {"action": "wallet_pay", "order_ref": match.group(1)}
    match = re.fullmatch(rf"(?:درگاه|زیبال|پرداخت آنلاین)\s+{order_ref_pattern}", low, re.I)
    if match:
        return {"action": "zibal", "order_ref": match.group(1)}
    match = re.fullmatch(rf"(?:کارت|کارت به کارت|کارت‌به‌کارت)\s+{order_ref_pattern}", low, re.I)
    if match:
        return {"action": "card", "order_ref": match.group(1)}
    return None


def _premium_order_for_user(order_ref: Any, user_id: int) -> Optional[Dict[str, Any]]:
    raw = str(order_ref or "").strip()
    order: Optional[Dict[str, Any]] = None
    ascii_raw = raw.translate(PERSIAN_ARABIC_TO_ASCII)
    if ascii_raw.isdigit():
        order = premium.get_order(int(ascii_raw))
    else:
        order = premium.get_order_by_code(raw)
    if order is None or int(order.get("buyer_user_id") or 0) != int(user_id):
        return None
    return order


def _premium_group_install_info(group_id: int) -> Optional[Dict[str, Any]]:
    gid = int(group_id or 0)
    if gid <= 0:
        return None
    local = get_installation(gid)
    if local is not None:
        return {"group_id": gid, "group_title": str(local.get("group_title") or f"گروه {gid}"), "account_key": ACCOUNT_KEY}
    try:
        claim = multi_lookup_group_claim(MULTI_ACCOUNT_DB, group_id=gid)
    except Exception:
        claim = None
    if claim is not None and str(claim["status"] or "") == "active":
        return {
            "group_id": gid,
            "group_title": str(claim["group_title"] or f"گروه {gid}"),
            "account_key": str(claim["account_key"] or ""),
        }
    try:
        sources = _legacy_group_account_sources(gid)
    except Exception:
        sources = []
    if sources:
        return {"group_id": gid, "group_title": f"گروه {gid}", "account_key": str(sources[0][0] or "")}
    return None


async def _premium_resolve_installed_group_link(raw_text: str) -> Tuple[Optional[Dict[str, Any]], str]:
    connection = parse_group_connection_target(raw_text)
    if not connection:
        return None, "INVALID_GROUP_LINK"
    kind, value = connection
    claim = None
    try:
        if kind == "invite":
            claim = multi_lookup_group_claim(MULTI_ACCOUNT_DB, invite_fingerprint=_multi_invite_fingerprint(value))
        else:
            claim = multi_lookup_group_claim(MULTI_ACCOUNT_DB, public_username=value)
    except Exception:
        claim = None
    if claim is not None and int(claim["group_id"] or 0) > 0 and str(claim["status"] or "") == "active":
        gid = int(claim["group_id"] or 0)
        return {
            "group_id": gid,
            "group_title": str(claim["group_title"] or f"گروه {gid}"),
            "account_key": str(claim["account_key"] or ""),
            "link_kind": kind,
        }, ""
    # Read-only fallback: resolve an entity only when already visible to this
    # account. Never join a group as part of checkout.
    gid = 0
    title = ""
    try:
        if kind == "public":
            group = await resolve_public_group(value)
            gid = int(safe_int(getattr(group, "id", None)) or 0)
            title = str(getattr(group, "title", None) or "")
        else:
            checked = await asyncio.wait_for(check_invite(value), timeout=6)
            if isinstance(checked, types.ChatInviteAlready):
                group = checked.chat
                gid = int(safe_int(getattr(group, "id", None)) or 0)
                title = str(getattr(group, "title", None) or "")
    except Exception:
        pass
    if gid > 0:
        info = _premium_group_install_info(gid)
        if info is not None:
            if title and not str(info.get("group_title") or "").strip():
                info["group_title"] = title
            info["link_kind"] = kind
            return info, ""
    return None, "BOT_NOT_INSTALLED"


def _premium_payment_menu_text(order: Dict[str, Any], user_id: int = 0) -> Tuple[str, List[str]]:
    settings = premium.payment_settings()
    code = str(order.get("order_code") or f"#{int(order.get('order_id') or 0)}")
    kind = str(order.get("order_kind") or "subscription")
    lines = [
        "ZIVO | انتخاب روش پرداخت",
        "━━━━━━━━━━━━━━━━━━",
        f"کد سفارش: {code}",
    ]
    if kind == "wallet_topup":
        lines.extend(["نوع: شارژ کیف پول ZIVO", f"مبلغ: {premium.money_rial(order.get('amount_rial'))} ({premium.money_toman(order.get('amount_rial'))})", ""])
    elif kind == "meow_purchase":
        lines.extend([
            "نوع: خرید Meow",
            f"تعداد: {int(order.get('meow_amount') or 0):,} Meow",
            f"گیرنده: {int(order.get('target_user_id') or 0)}",
            f"مبلغ: {premium.money_rial(order.get('amount_rial'))} ({premium.money_toman(order.get('amount_rial'))})",
            "",
        ])
    elif kind == "meow_gift_code":
        lines.extend([
            "نوع: کد هدیه Meow",
            f"مقدار: {int(order.get('meow_amount') or 0):,} Meow",
            f"مبلغ: {premium.money_rial(order.get('amount_rial'))} ({premium.money_toman(order.get('amount_rial'))})",
            "",
        ])
    else:
        lines.extend([
            f"گروه: {order.get('group_title') or order.get('group_id')}",
            f"پلن: {premium.plan_label(order.get('plan'))}",
            f"مدت: {premium.duration_label(order.get('duration_days'))}",
            f"مبلغ: {premium.money_rial(order.get('amount_rial'))} ({premium.money_toman(order.get('amount_rial'))})",
            "",
        ])
    commands: List[str] = []
    if kind != "wallet_topup":
        wallet = premium.wallet_balance(int(user_id or order.get("buyer_user_id") or 0))
        wallet_cmd = f"کیف پول {code}"
        lines.append(f"کیف پول: {premium.money_rial(wallet)}")
        if wallet >= int(order.get("amount_rial") or 0):
            lines.append(f"• پرداخت از کیف پول: {wallet_cmd}")
        else:
            lines.append(f"• کسری کیف پول: {premium.money_rial(max(0, int(order.get('amount_rial') or 0) - wallet))}")
        commands.append(wallet_cmd)
    if settings.get("zibal_enabled") and settings.get("zibal_merchant") and settings.get("zibal_callback_url"):
        cmd = f"درگاه {code}"
        lines.append(f"• پرداخت آنلاین زیبال: {cmd}")
        commands.append(cmd)
    if settings.get("card_enabled") and settings.get("card_number"):
        cmd = f"کارت {code}"
        lines.append(f"• کارت‌به‌کارت: {cmd}")
        commands.append(cmd)
    if not commands:
        lines.append("در حال حاضر روش پرداخت فعالی تنظیم نشده است.")
    return "\n".join(lines), commands


async def _premium_send_private_code_values(event: Any, target: Any, text: str, values: List[str]) -> None:
    message = getattr(event, "message", None) if event is not None else None
    entities = command_code_entities(text, [str(v) for v in values if str(v)])
    if message is not None:
        responder = getattr(message, "respond", None)
        if callable(responder):
            try:
                await responder(text, parse_mode=None, formatting_entities=entities, link_preview=False)
                return
            except Exception:
                pass
    try:
        await client.send_message(target, text, parse_mode=None, formatting_entities=entities, link_preview=False)
    except Exception:
        await send_private_from_event(event, target, text)


async def _zibal_request_for_order(order: Dict[str, Any]) -> Tuple[bool, str]:
    settings = premium.payment_settings()
    if not settings.get("zibal_enabled"):
        return False, "درگاه زیبال از پنل مدیریت غیرفعال است."
    merchant = str(settings.get("zibal_merchant") or "").strip()
    callback_url = str(settings.get("zibal_callback_url") or "").strip()
    if not merchant or not callback_url.startswith(("http://", "https://")):
        return False, "Merchant یا Callback زیبال هنوز کامل تنظیم نشده است."
    existing_track = int(order.get("zibal_track_id") or 0)
    if existing_track > 0 and str(order.get("status") or "") in {"gateway_pending", "activated"}:
        return True, f"https://gateway.zibal.ir/start/{existing_track}"
    code = str(order.get("order_code") or order.get("order_id") or "")
    kind = str(order.get("order_kind") or "subscription")
    description = f"ZIVO wallet top-up {code}" if kind == "wallet_topup" else f"ZIVO {premium.PLAN_LABEL_EN.get(str(order.get('plan')), str(order.get('plan')).upper())} {code}"
    payload = {
        "merchant": merchant,
        "amount": int(order.get("amount_rial") or 0),
        "callbackUrl": callback_url,
        "description": description,
        "orderId": int(order.get("order_id") or 0),
    }
    timeout = aiohttp.ClientTimeout(total=15)
    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post("https://gateway.zibal.ir/v1/request", json=payload) as response:
                data = await response.json(content_type=None)
    except Exception as exc:
        premium.record_event(int(order.get("order_id") or 0), "zibal_request_error", "", {"error": f"{type(exc).__name__}:{exc}"})
        return False, f"خطا در اتصال به زیبال: {type(exc).__name__}"
    result = int(data.get("result") or 0)
    track_id = int(data.get("trackId") or 0)
    premium.record_event(int(order.get("order_id") or 0), "zibal_request", track_id, data)
    if result != 100 or track_id <= 0:
        premium.update_order(int(order.get("order_id") or 0), zibal_result=result)
        return False, str(data.get("message") or data.get("statusMessage") or f"ZIBAL_RESULT_{result}")
    premium.attach_zibal_track(int(order.get("order_id") or 0), track_id, result)
    return True, f"https://gateway.zibal.ir/start/{track_id}"


