async def _premium_grant_activation_benefits(order: Dict[str, Any]) -> Dict[str, Any]:
    """Grant one-time plan activation benefits idempotently.

    Diamond's 100 Meow is tied to group activation, not every renewal. The
    premium DB is the anti-abuse source of truth; social DB credit happens only
    after the claim row is atomically reserved.
    """
    if str(order.get("order_kind") or "subscription") != "subscription":
        return {"granted": False, "reason": "not-subscription"}
    gid = int(order.get("group_id") or 0)
    uid = int(order.get("buyer_user_id") or 0)
    oid = int(order.get("order_id") or 0)
    plan = premium.normalize_plan(order.get("plan"))
    if gid <= 0 or uid <= 0 or plan != premium.PLAN_DIAMOND:
        return {"granted": False, "reason": "not-diamond"}
    amount = int(premium.entitlement(gid, "diamond_activation_meow", 0) or 0)
    if amount <= 0:
        return {"granted": False, "reason": "no-bonus"}
    reserved = await asyncio.to_thread(
        premium.reserve_bonus_once, gid, uid, "diamond-activation-meow", amount, oid
    )
    if not reserved:
        return {"granted": False, "reason": "already-claimed"}
    try:
        result = await asyncio.to_thread(
            social_games.admin_adjust_meow_users, [uid], amount,
            created_by=int(GLOBAL_BOT_OWNER_ID), scope="premium-diamond", target_ref=f"group:{gid}:order:{oid}",
        )
    except Exception as exc:
        # Release reservation on a failed credit so a later retry can recover.
        await asyncio.to_thread(premium.release_bonus_reservation, gid, "diamond-activation-meow", oid)
        log.warning("diamond activation meow credit failed | group=%s user=%s order=%s | %s: %s", gid, uid, oid, type(exc).__name__, exc)
        return {"granted": False, "reason": "credit-failed"}
    return {"granted": bool(int(result.get("actual_delta") or 0) > 0), "amount": amount}


async def _premium_queue_activation_announcements(order: Dict[str, Any], *, notify_private: bool = True) -> None:
    benefits = await _premium_grant_activation_benefits(order)
    uid = int(order.get("buyer_user_id") or 0)
    if notify_private and uid > 0:
        try:
            await asyncio.to_thread(social_games.queue_notification, uid, _premium_activation_receipt_text(order))
        except Exception:
            pass
    if str(order.get("order_kind") or "subscription") == "subscription":
        gid = int(order.get("group_id") or 0)
        if gid > 0:
            try:
                await asyncio.to_thread(
                    premium.queue_group_notification,
                    gid,
                    int(order.get("order_id") or 0),
                    _premium_group_activation_text(order) + (f"\n🎁 پاداش Diamond: {int(benefits.get('amount') or 0)} Meow" if benefits.get("granted") else ""),
                    "subscription-activated",
                )
            except Exception:
                pass


async def maybe_advance_premium_checkout(event: Any, target: Any, user_id: int, text: str) -> bool:
    session = await asyncio.to_thread(premium.get_checkout_session, int(user_id))
    if session is None:
        return False
    stage = str(session.get("stage") or "")
    low = normalize_group_command(str(text or "")).replace("‌", " ").strip()
    if low in {"لغو", "انصراف", "لغو خرید", "لغو سفارش"}:
        await asyncio.to_thread(premium.clear_checkout_session, int(user_id))
        await send_private_from_event(event, target, "خرید لغو شد. هر زمان خواستی دوباره بفرست: خرید اشتراک")
        return True
    if stage == "await-group-link":
        if not parse_group_connection_target(text):
            await send_private_from_event(
                event, target,
                "برای اینکه اشتراک دقیقاً روی همان گروه فعال شود، لینک گروه را بفرست.\n"
                "لینک عمومی splus.ir/... یا لینک خصوصی splus.ir/joingroup/... قابل قبول است."
            )
            return True
        info, reason = await _premium_resolve_installed_group_link(text)
        if info is None:
            if reason == "BOT_NOT_INSTALLED":
                await send_private_from_event(
                    event, target,
                    "ZIVO را روی این گروه فعال پیدا نکردم.\n\n"
                    "اول یکی از اکانت‌های ZIVO را داخل همان گروه بیاور و نصب/فعال کن؛ بعد دوباره لینک گروه را همینجا بفرست."
                )
            else:
                await send_private_from_event(event, target, "لینک گروه معتبر نیست. لینک عمومی یا joingroup همان گروه را بفرست.")
            return True
        gid = int(info.get("group_id") or 0)
        title = str(info.get("group_title") or f"گروه {gid}")
        await asyncio.to_thread(premium.set_checkout_session, int(user_id), gid, title, 0, "group-selected", 180)
        price_text, commands = _premium_prices_text(title)
        await send_private_copyable_from_event(event, target, "گروه تأیید شد و ZIVO روی آن فعال است.\n\n" + price_text, commands)
        return True
    if stage == "await-wallet-topup-amount":
        normalized = normalize_moderation_digits(low).replace(",", "").replace("٬", "").strip()
        if not normalized.isdigit():
            await send_private_from_event(event, target, "مبلغ شارژ را فقط به ریال بفرست. مثال: 500000")
            return True
        amount = int(normalized)
        try:
            order = await asyncio.to_thread(premium.create_wallet_topup_order, int(user_id), amount)
        except ValueError:
            await send_private_from_event(event, target, "مبلغ شارژ باید بین 100,000 تا 500,000,000 ریال باشد.")
            return True
        await asyncio.to_thread(premium.set_checkout_session, int(user_id), 0, "کیف پول ZIVO", int(order.get("order_id") or 0), "wallet-topup-created", 180)
        menu, commands = _premium_payment_menu_text(order, int(user_id))
        await send_private_copyable_from_event(event, target, menu, [str(order.get("order_code") or ""), *commands])
        return True
    return False


async def command_premium_private(event: Any, target: Any, user_id: int, parsed: Dict[str, Any]) -> bool:
    action = str(parsed.get("action") or "")
    if action == "plans":
        text, commands = _premium_prices_text()
        await send_private_copyable_from_event(event, target, text + "\n\nبرای شروع خرید بفرست: خرید اشتراک", [*commands, "خرید اشتراک"])
        return True
    if action == "start_purchase":
        await asyncio.to_thread(premium.set_checkout_session, int(user_id), 0, "", 0, "await-group-link", 180)
        await send_private_from_event(
            event, target,
            "ZIVO | خرید اشتراک\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "اول لینک گروهی را بفرست که می‌خواهی اشتراک فقط برای همان گروه فعال شود.\n\n"
            "ZIVO بررسی می‌کند که ربات واقعاً روی همان گروه نصب باشد؛ اگر نباشد خرید برای آن گروه شروع نمی‌شود."
        )
        return True
    if action == "my_subscriptions":
        await send_private_from_event(event, target, _premium_my_subscriptions_text(int(user_id)))
        return True
    if action == "history":
        await send_private_from_event(event, target, _premium_history_text(int(user_id)))
        return True
    if action == "wallet_balance":
        balance = await asyncio.to_thread(premium.wallet_balance, int(user_id))
        ledger = await asyncio.to_thread(premium.wallet_ledger, int(user_id), 5)
        lines = [
            "ZIVO | کیف پول",
            "━━━━━━━━━━━━━━━━━━",
            f"موجودی: {premium.money_rial(balance)} ({premium.money_toman(balance)})",
            "",
            "برای شارژ بفرست: شارژ کیف پول",
        ]
        if ledger:
            lines.extend(["", "آخرین گردش‌ها:"])
            for row in ledger:
                delta = int(row.get("delta_rial") or 0)
                lines.append(f"• {delta:+,} ریال | مانده {int(row.get('balance_after') or 0):,}")
        await send_private_copyable_from_event(event, target, "\n".join(lines), ["شارژ کیف پول"])
        return True
    if action == "wallet_topup_start":
        await asyncio.to_thread(premium.set_checkout_session, int(user_id), 0, "کیف پول ZIVO", 0, "await-wallet-topup-amount", 60)
        await send_private_from_event(event, target, "مبلغی که می‌خواهی کیف پول را شارژ کنی فقط به ریال بفرست.\nمثال: 500000")
        return True
    if action == "cancel_checkout":
        await asyncio.to_thread(premium.clear_checkout_session, int(user_id))
        await send_private_from_event(event, target, "خرید/پرداخت جاری لغو شد.")
        return True
    if action == "discount_set":
        if user_id != int(GLOBAL_BOT_OWNER_ID):
            return {"ok": False, "error": "FORBIDDEN", "account_key": ACCOUNT_KEY}
        try:
            row = premium.set_discount_code(payload.get("code"), safe_int(payload.get("percent")) or 0)
        except ValueError as exc:
            return {"ok": False, "error": str(exc), "account_key": ACCOUNT_KEY}
        return {"ok": True, "discount": row, "account_key": ACCOUNT_KEY}

    if action == "discount_remove":
        if user_id != int(GLOBAL_BOT_OWNER_ID):
            return {"ok": False, "error": "FORBIDDEN", "account_key": ACCOUNT_KEY}
        return {"ok": True, "removed": premium.remove_discount_code(payload.get("code")), "account_key": ACCOUNT_KEY}

    if action == "discount_list":
        if user_id != int(GLOBAL_BOT_OWNER_ID):
            return {"ok": False, "error": "FORBIDDEN", "account_key": ACCOUNT_KEY}
        return {"ok": True, "discounts": premium.list_discount_codes(), "account_key": ACCOUNT_KEY}

    if action == "discount_apply":
        order = _ipc_premium_order_for_user(payload.get("order_ref"), user_id)
        if order is None:
            return {"ok": False, "error": "PREMIUM_ORDER_NOT_FOUND", "account_key": ACCOUNT_KEY}
        try:
            updated = premium.apply_discount_code(int(order.get("order_id") or 0), user_id, payload.get("code"))
        except ValueError as exc:
            return {"ok": False, "error": str(exc), "order": order, "account_key": ACCOUNT_KEY}
        return {"ok": True, "order": updated, "wallet_balance": premium.wallet_balance(user_id), "account_key": ACCOUNT_KEY}

    if action == "cancel":
        order = _ipc_premium_order_for_user(payload.get("order_ref"), user_id)
        if order is None:
            return {"ok": False, "error": "PREMIUM_ORDER_NOT_FOUND", "account_key": ACCOUNT_KEY}
        try:
            updated = premium.cancel_order(int(order.get("order_id") or 0), user_id)
        except ValueError as exc:
            return {"ok": False, "error": str(exc), "order": order, "account_key": ACCOUNT_KEY}
        return {"ok": True, "order": updated, "cancelled": True, "account_key": ACCOUNT_KEY}

    if action == "check_payment":
        order = _ipc_premium_order_for_user(payload.get("order_ref"), user_id)
        if order is None:
            return {"ok": False, "error": "PREMIUM_ORDER_NOT_FOUND", "account_key": ACCOUNT_KEY}
        if str(order.get("status") or "") == "activated":
            return {"ok": True, "activated": True, "order": order, "subscription": premium.get_subscription(int(order.get("group_id") or 0), use_cache=False), "account_key": ACCOUNT_KEY}
        track_id = int(order.get("zibal_track_id") or 0)
        if track_id <= 0:
            return {"ok": True, "activated": False, "pending": True, "order": order, "message": "PAYMENT_NOT_STARTED", "account_key": ACCOUNT_KEY}
        ok, verify, message = await _zibal_verify_track(track_id)
        premium.record_event(int(order.get("order_id") or 0), "zibal_manual_check", track_id, verify or {"message": message})
        if not ok:
            return {"ok": True, "activated": False, "pending": True, "order": premium.get_order(int(order.get("order_id") or 0)) or order, "message": message, "account_key": ACCOUNT_KEY}
        verified_amount = int(verify.get("amount") or 0)
        expected_amount = int(order.get("amount_rial") or 0)
        if verified_amount != expected_amount:
            premium.update_order(int(order.get("order_id") or 0), status="amount_mismatch", zibal_result=int(verify.get("result") or 0))
            return {"ok": False, "error": "PAYMENT_AMOUNT_MISMATCH", "order": order, "account_key": ACCOUNT_KEY}
        ref_id = str(verify.get("refNumber") or verify.get("refId") or verify.get("cardNumber") or "")
        premium.update_order(
            int(order.get("order_id") or 0), paid_at=str(verify.get("paidAt") or datetime.now(timezone.utc).isoformat()),
            gateway_ref_id=ref_id, zibal_result=int(verify.get("result") or 100),
        )
        activated = premium.approve_order(int(order.get("order_id") or 0), "zibal-manual-check")
        await _premium_queue_activation_announcements(activated, notify_private=False)
        return {"ok": True, "activated": True, "order": activated, "subscription": premium.get_subscription(int(activated.get("group_id") or 0), use_cache=False), "account_key": ACCOUNT_KEY}

    if action == "create_order":
        session = await asyncio.to_thread(premium.get_checkout_session, int(user_id))
        gid = int((session or {}).get("group_id") or 0)
        title = str((session or {}).get("group_title") or "")
        if gid <= 0 or _premium_group_install_info(gid) is None:
            await asyncio.to_thread(premium.set_checkout_session, int(user_id), 0, "", 0, "await-group-link", 180)
            await send_private_from_event(event, target, "اول لینک گروهی را بفرست که ZIVO روی آن نصب است؛ بعد پلن را انتخاب کن.")
            return True
        plan = str(parsed.get("plan") or "")
        days = int(parsed.get("duration_days") or 0)
        try:
            order = await asyncio.to_thread(premium.create_order, int(user_id), gid, title or f"گروه {gid}", plan, days)
        except ValueError:
            await send_private_from_event(event, target, "این پلن/مدت در حال حاضر برای خرید فعال نیست.")
            return True
        await asyncio.to_thread(premium.set_checkout_session, int(user_id), gid, title, int(order.get("order_id") or 0), "order-created", 180)
        menu, commands = _premium_payment_menu_text(order, int(user_id))
        await send_private_copyable_from_event(event, target, "سفارش اختصاصی شما ساخته شد.\n\n" + menu, [str(order.get("order_code") or ""), *commands])
        return True

    order = _premium_order_for_user(parsed.get("order_ref"), int(user_id))
    if order is None:
        await send_private_from_event(event, target, "این کد سفارش پیدا نشد یا متعلق به این حساب نیست.")
        return True
    code = str(order.get("order_code") or f"#{int(order.get('order_id') or 0)}")
    status = str(order.get("status") or "")
    if status == "activated":
        await send_private_from_event(event, target, _premium_activation_receipt_text(order))
        return True
    if status in {"rejected", "cancelled"}:
        await send_private_from_event(event, target, f"سفارش {code} در وضعیت {status} است و قابل پرداخت نیست.")
        return True
    if action == "payment_menu":
        text, commands = _premium_payment_menu_text(order, int(user_id))
        await send_private_copyable_from_event(event, target, text, [code, *commands])
        return True
    if action == "wallet_pay":
        if str(order.get("order_kind") or "subscription") == "wallet_topup":
            await send_private_from_event(event, target, "برای شارژ کیف پول نمی‌توان از همان کیف پول پرداخت کرد؛ درگاه یا کارت‌به‌کارت را انتخاب کن.")
            return True
        try:
            result = await asyncio.to_thread(premium.pay_order_with_wallet, int(order.get("order_id") or 0), int(user_id))
        except ValueError as exc:
            if str(exc) == "INSUFFICIENT_WALLET_BALANCE":
                balance = await asyncio.to_thread(premium.wallet_balance, int(user_id))
                missing = max(0, int(order.get("amount_rial") or 0) - int(balance))
                await send_private_from_event(
                    event, target,
                    "موجودی کیف پول کافی نیست.\n"
                    f"موجودی: {premium.money_rial(balance)}\n"
                    f"مبلغ سفارش: {premium.money_rial(order.get('amount_rial'))}\n"
                    f"کسری: {premium.money_rial(missing)}\n\n"
                    "برای شارژ بفرست: شارژ کیف پول"
                )
                return True
            await send_private_from_event(event, target, f"پرداخت کیف پول انجام نشد: {str(exc)}")
            return True
        # The wallet path already has a live PM event, so send the receipt here
        # and queue only the cross-account group activation notice. This avoids
        # a duplicate PM receipt from the shared notification worker.
        if str(result.get("order_kind") or "subscription") == "subscription":
            await _premium_queue_activation_announcements(result, notify_private=False)
        await send_private_from_event(event, target, _premium_activation_receipt_text(result))
        try:
            kind = str(result.get("order_kind") or "subscription")
            if kind == "subscription":
                subject = (
                    f"گروه: {result.get('group_title') or result.get('group_id')} ({int(result.get('group_id') or 0)})\n"
                    f"پلن: {premium.plan_label(result.get('plan'))}\n"
                    f"مدت: {premium.duration_label(result.get('duration_days'))}"
                )
            elif kind == "meow_purchase":
                subject = f"محصول: {int(result.get('meow_amount') or 0):,} Meow برای کاربر {int(result.get('target_user_id') or 0)}"
            else:
                subject = f"محصول: کد هدیه {int(result.get('meow_amount') or 0):,} Meow\nکد: {result.get('gift_code') or '—'}"
            await tg_send_text(
                TELEGRAM_ADMIN_ID,
                "✅ پرداخت کیف پول ZIVO\n\n"
                f"کد: {result.get('order_code') or code}\n"
                f"کاربر: {int(user_id)}\n"
                f"{subject}\n"
                f"مبلغ: {premium.money_rial(result.get('amount_rial'))}"
            )
        except Exception:
            pass
        return True
    if action == "zibal":
        ok, result = await _zibal_request_for_order(order)
        if not ok:
            await send_private_from_event(event, target, f"ایجاد پرداخت ناموفق بود.\n{result}")
            return True
        await send_private_from_event(
            event, target,
            "ZIVO | درگاه زیبال آماده است\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"کد سفارش: {code}\n"
            f"مبلغ دقیق: {premium.money_rial(order.get('amount_rial'))}\n\n"
            f"لینک پرداخت:\n{result}\n\n"
            "بعد از پرداخت، ZIVO تراکنش را Verify می‌کند و نتیجه داخل همین پیوی اعلام می‌شود."
        )
        return True
    if action == "card":
        settings = premium.payment_settings()
        card = premium.normalize_card_number(settings.get("card_number"))
        if not settings.get("card_enabled") or not card:
            await send_private_from_event(event, target, "کارت‌به‌کارت در حال حاضر غیرفعال یا تنظیم‌نشده است.")
            return True
        premium.mark_card_waiting(int(order.get("order_id") or 0))
        await asyncio.to_thread(
            premium.set_checkout_session,
            int(user_id), int(order.get("group_id") or 0), str(order.get("group_title") or ""),
            int(order.get("order_id") or 0), "awaiting-receipt", 180,
        )
        amount_text = f"{int(order.get('amount_rial') or 0):,}"
        subject = "شارژ کیف پول" if str(order.get("order_kind") or "subscription") == "wallet_topup" else f"{premium.plan_label(order.get('plan'))} | {premium.duration_label(order.get('duration_days'))}"
        text = (
            "ZIVO | کارت‌به‌کارت\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"کد سفارش: {code}\n"
            f"خرید: {subject}\n\n"
            "شماره کارت:\n"
            f"{card}\n\n"
            f"به نام: {settings.get('card_holder') or '—'}\n\n"
            "مبلغ دقیق به ریال:\n"
            f"{amount_text}\n\n"
            "بعد از واریز، عکس رسید را همینجا بفرست. رسید برای ادمین ZIVO می‌رود و پس از تأیید، اشتراک/کیف پول خودکار فعال می‌شود."
        )
        await _premium_send_private_code_values(event, target, text, [code, card, amount_text])
        return True
    return False




def _premium_event_has_receipt_media(event: Any) -> bool:
    message = getattr(event, "message", None) or event
    if message is None:
        return False
    if getattr(message, "photo", None) is not None:
        return True
    document = getattr(message, "document", None)
    if document is not None:
        mime = str(getattr(document, "mime_type", "") or "").lower()
        return not mime or mime.startswith("image/")
    media = getattr(message, "media", None)
    return media is not None and not str(getattr(event, "raw_text", None) or "").strip()


async def _premium_download_receipt(event: Any, order_id: int) -> str:
    PREMIUM_RECEIPT_DIR.mkdir(parents=True, exist_ok=True)
    message = getattr(event, "message", None) or event
    file_obj = getattr(message, "file", None)
    ext = str(getattr(file_obj, "ext", "") or "")
    if ext and not ext.startswith("."):
        ext = "." + ext
    if not ext:
        document = getattr(message, "document", None)
        mime = str(getattr(document, "mime_type", "") or "").lower() if document is not None else ""
        ext = ".png" if "png" in mime else ".jpg"
    target = PREMIUM_RECEIPT_DIR / f"receipt_{int(order_id)}_{int(time.time())}{ext}"
    candidates: List[Tuple[str, Any]] = []
    downloader = getattr(message, "download_media", None)
    if callable(downloader):
        candidates.append(("message", downloader))
    client_downloader = getattr(client, "download_media", None)
    if callable(client_downloader):
        candidates.append(("client", client_downloader))
    last_error: Optional[BaseException] = None
    for kind, fn in candidates:
        try:
            if kind == "message":
                result = await asyncio.wait_for(fn(file=str(target)), timeout=90)
            else:
                result = await asyncio.wait_for(fn(message, file=str(target)), timeout=90)
            path = Path(str(result or target))
            if path.is_file() and path.stat().st_size > 0:
                try:
                    path.chmod(0o600)
                except Exception:
                    pass
                return str(path)
        except Exception as exc:
            last_error = exc
    if last_error is not None:
        raise last_error
    raise RuntimeError("RECEIPT_MEDIA_DOWNLOAD_UNAVAILABLE")


async def maybe_handle_premium_receipt(event: Any, target: Any, user_id: int, message_id: int) -> bool:
    if not _premium_event_has_receipt_media(event):
        return False
    order = await asyncio.to_thread(premium.pending_receipt_order, int(user_id))
    if order is None:
        return False
    oid = int(order.get("order_id") or 0)
    try:
        path = await _premium_download_receipt(event, oid)
    except Exception as exc:
        await send_private_from_event(event, target, f"⛔ دریافت عکس رسید ناموفق بود. دوباره عکس را ارسال کن.\n{type(exc).__name__}")
        return True
    caption = str(getattr(event, "raw_text", None) or "").strip()
    updated = await asyncio.to_thread(premium.attach_card_receipt, oid, path, int(message_id or 0), caption)
    await send_private_from_event(
        event, target,
        f"✅ رسید سفارش {updated.get('order_code') or '#'+str(oid)} دریافت شد و برای بررسی ادمین ارسال شد.\n"
        "بعد از تأیید، نتیجه پرداخت و وضعیت اشتراک/کیف پول همینجا اعلام می‌شود."
    )
    try:
        await telegram_notify_card_receipt(updated, int(user_id), path)
    except Exception as exc:
        log.warning("premium receipt telegram notify failed | order=%s | %s: %s", oid, type(exc).__name__, exc)
    return True


async def _zibal_verify_track(track_id: int) -> Tuple[bool, Dict[str, Any], str]:
    settings = premium.payment_settings()
    merchant = str(settings.get("zibal_merchant") or "").strip()
    if not merchant:
        return False, {}, "MERCHANT_MISSING"
    timeout = aiohttp.ClientTimeout(total=15)
    try:
        async with aiohttp.ClientSession(timeout=timeout) as session:
            async with session.post(
                "https://gateway.zibal.ir/v1/verify",
                json={"merchant": merchant, "trackId": int(track_id)},
            ) as response:
                data = await response.json(content_type=None)
    except Exception as exc:
        return False, {}, f"{type(exc).__name__}:{exc}"
    result = int(data.get("result") or 0)
    return result in {100, 201}, dict(data), str(data.get("message") or data.get("statusMessage") or result)


async def _handle_zibal_callback_request(request: Any) -> Any:
    from aiohttp import web
    params = dict(request.query)
    track_raw = params.get("trackId") or params.get("trackid") or "0"
    try:
        track_id = int(str(track_raw))
    except Exception:
        track_id = 0
    if track_id <= 0:
        return web.Response(text="ZIVO: invalid trackId", content_type="text/plain", status=400)
    order = await asyncio.to_thread(premium.get_order_by_track, track_id)
    if order is None:
        return web.Response(text="ZIVO: order not found", content_type="text/plain", status=404)
    oid = int(order.get("order_id") or 0)
    code = str(order.get("order_code") or f"#{oid}")
    await asyncio.to_thread(premium.record_event, oid, "zibal_callback", track_id, params)
    if str(order.get("status") or "") == "activated":
        return web.Response(text="پرداخت قبلاً تایید شده است.", content_type="text/plain")
    success_flag = str(params.get("success") or "").strip().lower()
    status_flag = str(params.get("status") or "").strip()
    if success_flag not in {"1", "true"} and status_flag not in {"2"}:
        await asyncio.to_thread(premium.update_order, oid, status="gateway_returned")
        return web.Response(text="پرداخت تکمیل نشد. به ZIVO برگردید و دوباره تلاش کنید.", content_type="text/plain")
    ok, verify, message = await _zibal_verify_track(track_id)
    await asyncio.to_thread(premium.record_event, oid, "zibal_verify", track_id, verify or {"message": message})
    if not ok:
        await asyncio.to_thread(premium.update_order, oid, zibal_result=int(verify.get("result") or 0), status="verify_failed")
        return web.Response(text="تایید پرداخت ناموفق بود؛ هیچ اشتراک یا موجودی فعال نشد.", content_type="text/plain", status=400)
    verified_amount = int(verify.get("amount") or 0)
    expected_amount = int(order.get("amount_rial") or 0)
    if verified_amount != expected_amount:
        await asyncio.to_thread(premium.update_order, oid, status="amount_mismatch", zibal_result=int(verify.get("result") or 0))
        return web.Response(text="مبلغ پرداخت با سفارش یکسان نیست؛ عملیات فعال نشد.", content_type="text/plain", status=400)
    ref_id = str(verify.get("refNumber") or verify.get("refId") or verify.get("cardNumber") or "")
    await asyncio.to_thread(
        premium.update_order, oid,
        paid_at=str(verify.get("paidAt") or datetime.now(timezone.utc).isoformat()),
        gateway_ref_id=ref_id, zibal_result=int(verify.get("result") or 100),
    )
    activated = await asyncio.to_thread(premium.approve_order, oid, "zibal-verify")
    await _premium_queue_activation_announcements(activated)
    try:
        profile = await asyncio.to_thread(get_global_user_profile, int(activated.get("buyer_user_id") or 0))
        name = str(profile.get("nickname") or profile.get("preferred_name") or profile.get("name") or "کاربر")
        username = str(profile.get("username") or "").strip().lstrip("@")
        kind = str(activated.get("order_kind") or "subscription")
        lines = [
            "✅ پرداخت آنلاین ZIVO تایید شد", "",
            f"کد سفارش: {code}",
            f"نام: {name}",
            f"Username: @{username if username else '—'}",
            f"User ID: {int(activated.get('buyer_user_id') or 0)}",
            f"مبلغ: {premium.money_rial(activated.get('amount_rial'))}",
            f"TrackId: {track_id}",
            f"Ref: {ref_id or '—'}",
        ]
        if kind == "wallet_topup":
            lines.append(f"نوع: شارژ کیف پول | موجودی جدید: {premium.money_rial(premium.wallet_balance(int(activated.get('buyer_user_id') or 0)))}")
        else:
            lines.extend([
                f"گروه: {activated.get('group_title') or activated.get('group_id')} ({int(activated.get('group_id') or 0)})",
                f"پلن: {premium.plan_label(activated.get('plan'))}",
                f"مدت: {premium.duration_label(activated.get('duration_days'))}",
            ])
        await tg_send_text(TELEGRAM_ADMIN_ID, "\n".join(lines))
    except Exception:
        pass
    return web.Response(text=f"پرداخت {code} با موفقیت تایید شد. نتیجه داخل ZIVO ثبت شده است؛ می‌توانید این صفحه را ببندید.", content_type="text/plain")


async def zibal_callback_worker() -> None:
    if not ACCOUNT_IS_CONTROLLER:
        return
    from aiohttp import web
    app = web.Application()
    async def _payment_health(_request: Any) -> Any:
        return web.Response(text="ZIVO PAYMENT OK", content_type="text/plain")
    app.router.add_get("/zivo/payment/health", _payment_health)
    app.router.add_get("/zivo/zibal/callback", _handle_zibal_callback_request)
    app.router.add_post("/zivo/zibal/callback", _handle_zibal_callback_request)
    runner = web.AppRunner(app)
    await runner.setup()
    site = web.TCPSite(runner, PAYMENT_CALLBACK_HOST, PAYMENT_CALLBACK_PORT)
    try:
        await site.start()
        log.info("premium callback server started | host=%s port=%s path=/zivo/zibal/callback", PAYMENT_CALLBACK_HOST, PAYMENT_CALLBACK_PORT)
        while True:
            await asyncio.sleep(3600)
    except asyncio.CancelledError:
        raise
    except OSError as exc:
        log.error("premium callback server bind failed | host=%s port=%s | %s: %s", PAYMENT_CALLBACK_HOST, PAYMENT_CALLBACK_PORT, type(exc).__name__, exc)
    finally:
        await runner.cleanup()


def get_group_bot_power_state(
    group_id: int,
) -> Dict[str, Any]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _group_power_hot_cache.get(gid)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return dict(cached[1])
    with db_connect() as con:
        row = con.execute(
            """SELECT enabled, expires_at, expire_to_enabled, peer_kind,
                      group_access_hash, updated_by, updated_at
               FROM group_bot_power WHERE group_id = ?""",
            (gid,),
        ).fetchone()
    if row is None:
        result = {"enabled": True, "expires_at": None, "expire_to_enabled": None,
                  "peer_kind": "channel", "group_access_hash": 0,
                  "updated_by": 0, "updated_at": ""}
    else:
        result = {
            "enabled": bool(int(row["enabled"] or 0)),
            "expires_at": row["expires_at"],
            "expire_to_enabled": None if row["expire_to_enabled"] is None else bool(int(row["expire_to_enabled"] or 0)),
            "peer_kind": row["peer_kind"] or "channel",
            "group_access_hash": int(row["group_access_hash"] or 0),
            "updated_by": int(row["updated_by"] or 0),
            "updated_at": row["updated_at"] or "",
        }
    _group_power_hot_cache[gid] = (now, dict(result))
    return result


def is_group_bot_enabled(
    group_id: int,
) -> bool:
    return bool(
        get_group_bot_power_state(
            group_id
        )["enabled"]
    )


def set_group_bot_power_state(
    group_id: int,
    enabled: bool,
    actor_id: int,
    peer_kind: str,
    group_access_hash: int,
    duration_seconds: Optional[int] = None,
) -> Dict[str, Any]:
    now = datetime.now(timezone.utc)

    expires_at: Optional[str] = None
    expire_to_enabled: Optional[int] = None

    if duration_seconds is not None:
        duration_seconds = max(
            1,
            int(duration_seconds),
        )
        expires_at = (
            now
            + timedelta(
                seconds=duration_seconds
            )
        ).isoformat()
        expire_to_enabled = (
            0 if enabled else 1
        )

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO group_bot_power (
                group_id,
                enabled,
                expires_at,
                expire_to_enabled,
                peer_kind,
                group_access_hash,
                updated_by,
                updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                enabled = excluded.enabled,
                expires_at = excluded.expires_at,
                expire_to_enabled = excluded.expire_to_enabled,
                peer_kind = excluded.peer_kind,
                group_access_hash = CASE
                    WHEN excluded.group_access_hash != 0
                    THEN excluded.group_access_hash
                    ELSE group_bot_power.group_access_hash
                END,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                1 if enabled else 0,
                expires_at,
                expire_to_enabled,
                "chat" if peer_kind == "chat" else "channel",
                int(group_access_hash or 0),
                int(actor_id),
                now.isoformat(),
            ),
        )
        con.commit()

    return get_group_bot_power_state(
        group_id
    )


def due_group_bot_power_rows(
    limit: int = 50,
) -> List[sqlite3.Row]:
    now = datetime.now(
        timezone.utc
    ).isoformat()

    with db_connect() as con:
        return con.execute(
            """
            SELECT
                group_id,
                enabled,
                expires_at,
                expire_to_enabled,
                peer_kind,
                group_access_hash
            FROM group_bot_power
            WHERE expires_at IS NOT NULL
              AND expires_at <= ?
              AND expire_to_enabled IS NOT NULL
            ORDER BY expires_at ASC
            LIMIT ?
            """,
            (
                now,
                int(limit),
            ),
        ).fetchall()


def complete_group_bot_power_timer(
    group_id: int,
) -> Optional[bool]:
    now = datetime.now(
        timezone.utc
    ).isoformat()

    with db_connect() as con:
        row = con.execute(
            """
            SELECT
                expires_at,
                expire_to_enabled
            FROM group_bot_power
            WHERE group_id = ?
            """,
            (int(group_id),),
        ).fetchone()

        if (
            row is None
            or row["expires_at"] is None
            or row["expire_to_enabled"] is None
            or row["expires_at"] > now
        ):
            return None

        next_enabled = bool(
            int(
                row["expire_to_enabled"]
                or 0
            )
        )

        con.execute(
            """
            UPDATE group_bot_power
            SET enabled = ?,
                expires_at = NULL,
                expire_to_enabled = NULL,
                updated_at = ?
            WHERE group_id = ?
            """,
            (
                1 if next_enabled else 0,
                now,
                int(group_id),
            ),
        )
        con.commit()

    return next_enabled


def get_group_close_state(group_id: int) -> Dict[str, Any]:
    with db_connect() as con:
        row = con.execute(
            """
            SELECT
                peer_kind,
                group_access_hash,
                manual_closed,
                effective_closed,
                native_verified,
                baseline_rights_json,
                updated_by,
                updated_at
            FROM group_close_state
            WHERE group_id = ?
            """,
            (int(group_id),),
        ).fetchone()

    if row is None:
        return {
            "peer_kind": "channel",
            "group_access_hash": 0,
            "manual_closed": False,
            "effective_closed": False,
            "native_verified": False,
            "baseline_rights_json": None,
            "updated_by": 0,
            "updated_at": "",
        }

    return {
        "peer_kind": row["peer_kind"] or "channel",
        "group_access_hash": int(row["group_access_hash"] or 0),
        "manual_closed": bool(int(row["manual_closed"] or 0)),
        "effective_closed": bool(int(row["effective_closed"] or 0)),
        "native_verified": bool(int(row["native_verified"] or 0)),
        "baseline_rights_json": row["baseline_rights_json"],
        "updated_by": int(row["updated_by"] or 0),
        "updated_at": row["updated_at"] or "",
    }


def upsert_group_close_state(
    group_id: int,
    peer_kind: str,
    group_access_hash: int,
    actor_id: int = 0,
    manual_closed: Optional[bool] = None,
    effective_closed: Optional[bool] = None,
    native_verified: Optional[bool] = None,
    baseline_rights_json: Optional[str] = None,
    replace_baseline: bool = False,
) -> Dict[str, Any]:
    current = get_group_close_state(group_id)
    now = datetime.now(timezone.utc).isoformat()

    next_manual = (
        bool(manual_closed)
        if manual_closed is not None
        else bool(current["manual_closed"])
    )
    next_effective = (
        bool(effective_closed)
        if effective_closed is not None
        else bool(current["effective_closed"])
    )
    next_native_verified = (
        bool(native_verified)
        if native_verified is not None
        else bool(current["native_verified"])
    )
    next_baseline = (
        baseline_rights_json
        if replace_baseline
        else (
            current["baseline_rights_json"]
            if current["baseline_rights_json"] is not None
            else baseline_rights_json
        )
    )

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO group_close_state (
                group_id,
                peer_kind,
                group_access_hash,
                manual_closed,
                effective_closed,
                native_verified,
                baseline_rights_json,
                updated_by,
                updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                peer_kind = excluded.peer_kind,
                group_access_hash = CASE
                    WHEN excluded.group_access_hash != 0
                    THEN excluded.group_access_hash
                    ELSE group_close_state.group_access_hash
                END,
                manual_closed = excluded.manual_closed,
                effective_closed = excluded.effective_closed,
                native_verified = excluded.native_verified,
                baseline_rights_json = excluded.baseline_rights_json,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                "chat" if peer_kind == "chat" else "channel",
                int(group_access_hash or 0),
                1 if next_manual else 0,
                1 if next_effective else 0,
                1 if next_native_verified else 0,
                next_baseline,
                int(actor_id or current["updated_by"] or 0),
                now,
            ),
        )
        con.commit()

    _group_close_block_hot_cache.pop(int(group_id), None)

    return get_group_close_state(group_id)


def create_group_close_schedule(
    group_id: int,
    peer_kind: str,
    group_access_hash: int,
    start_at: datetime,
    end_at: datetime,
    label: str,
    actor_id: int,
) -> int:
    with db_connect() as con:
        cur = con.execute(
            """
            INSERT INTO group_close_schedules (
                group_id,
                peer_kind,
                group_access_hash,
                start_at,
                end_at,
                label,
                created_by,
                created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(group_id),
                "chat" if peer_kind == "chat" else "channel",
                int(group_access_hash or 0),
                start_at.astimezone(timezone.utc).isoformat(),
                end_at.astimezone(timezone.utc).isoformat(),
                label or "",
                int(actor_id),
                datetime.now(timezone.utc).isoformat(),
            ),
        )
        schedule_id = int(cur.lastrowid)
        con.commit()

    _group_close_block_hot_cache.pop(int(group_id), None)

    return schedule_id


