def delete_group_close_schedules_by_local_date(
    group_id: int,
    local_date: datetime,
) -> int:
    start_local = local_date.astimezone(IRAN_TZ).replace(
        hour=0, minute=0, second=0, microsecond=0
    )
    end_local = start_local + timedelta(days=1)

    start_iso = start_local.astimezone(timezone.utc).isoformat()
    end_iso = end_local.astimezone(timezone.utc).isoformat()

    with db_connect() as con:
        cur = con.execute(
            """
            DELETE FROM group_close_schedules
            WHERE group_id = ?
              AND start_at >= ?
              AND start_at < ?
            """,
            (int(group_id), start_iso, end_iso),
        )
        con.commit()

    _group_close_block_hot_cache.pop(int(group_id), None)

    return int(cur.rowcount or 0)


