def group_ids_needing_close_reconcile() -> List[int]:
    now = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        rows = con.execute(
            """
            SELECT group_id
            FROM group_close_state
            WHERE manual_closed = 1
               OR effective_closed = 1

            UNION

            SELECT group_id
            FROM group_close_schedules
            WHERE start_at <= ?
            """,
            (now,),
        ).fetchall()

    return [int(row["group_id"]) for row in rows]


def get_manual_warning_settings(group_id: int) -> Dict[str, Any]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _manual_warning_settings_hot_cache.get(gid)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return dict(cached[1])

    with db_connect() as con:
        row = con.execute(
            """
            SELECT
                max_warnings,
                auto_ban,
                action_mode,
                ban_seconds,
                escalation_enabled,
                warning_step,
                ban_increment_seconds
            FROM manual_warning_settings
            WHERE group_id = ?
            """,
            (gid,),
        ).fetchone()

    if row is None:
        result = {
            "max_warnings": 3,
            "auto_ban": False,
            "action_mode": "none",
            "ban_seconds": None,
            "escalation_enabled": False,
            "warning_step": 1,
            "ban_increment_seconds": 3600,
        }
    else:
        mode = (row["action_mode"] or "").strip().lower()
        if mode not in {"none", "ban", "delete"}:
            mode = "ban" if int(row["auto_ban"] or 0) else "none"

        raw_seconds = row["ban_seconds"]
        ban_seconds = (
            int(raw_seconds)
            if raw_seconds is not None and int(raw_seconds) > 0
            else None
        )
        result = {
            "max_warnings": max(1, int(row["max_warnings"] or 3)),
            "auto_ban": mode == "ban",
            "action_mode": mode,
            "ban_seconds": ban_seconds,
            "escalation_enabled": bool(int(row["escalation_enabled"] or 0)),
            "warning_step": max(1, int(row["warning_step"] or 1)),
            "ban_increment_seconds": max(
                60,
                int(row["ban_increment_seconds"] or 3600),
            ),
        }

    _manual_warning_settings_hot_cache[gid] = (now, dict(result))
    return dict(result)


def set_manual_warning_max(
    group_id: int,
    max_warnings: int,
    actor_id: int,
) -> Dict[str, Any]:
    max_warnings = int(max_warnings)
    now = datetime.now(timezone.utc).isoformat()
    current = get_manual_warning_settings(group_id)

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO manual_warning_settings (
                group_id, max_warnings, auto_ban, action_mode, ban_seconds,
                escalation_enabled, warning_step, ban_increment_seconds,
                updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                max_warnings = excluded.max_warnings,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                max_warnings,
                1 if current["action_mode"] == "ban" else 0,
                current["action_mode"],
                current["ban_seconds"],
                1 if current["escalation_enabled"] else 0,
                int(current["warning_step"]),
                int(current["ban_increment_seconds"]),
                int(actor_id),
                now,
            ),
        )
        con.commit()

    _manual_warning_settings_hot_cache.pop(int(group_id), None)
    return get_manual_warning_settings(group_id)


def set_manual_warning_action(
    group_id: int,
    mode: str,
    actor_id: int,
    ban_seconds: Optional[int] = None,
) -> Dict[str, Any]:
    mode = (mode or "").strip().lower()
    if mode not in {"none", "ban", "delete"}:
        raise ValueError("INVALID_WARNING_ACTION_MODE")

    if mode != "ban":
        ban_seconds = None
    elif ban_seconds is not None:
        ban_seconds = max(1, int(ban_seconds))

    now = datetime.now(timezone.utc).isoformat()
    current = get_manual_warning_settings(group_id)

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO manual_warning_settings (
                group_id, max_warnings, auto_ban, action_mode, ban_seconds,
                escalation_enabled, warning_step, ban_increment_seconds,
                updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                auto_ban = excluded.auto_ban,
                action_mode = excluded.action_mode,
                ban_seconds = excluded.ban_seconds,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                int(current["max_warnings"]),
                1 if mode == "ban" else 0,
                mode,
                ban_seconds,
                1 if current["escalation_enabled"] else 0,
                int(current["warning_step"]),
                int(current["ban_increment_seconds"]),
                int(actor_id),
                now,
            ),
        )
        con.commit()

    _manual_warning_settings_hot_cache.pop(int(group_id), None)
    return get_manual_warning_settings(group_id)


