def set_warning_escalation_ban_increment(
    group_id: int,
    seconds: int,
    actor_id: int,
) -> Dict[str, Any]:
    seconds = max(60, min(365 * 86400, int(seconds)))
    now = datetime.now(timezone.utc).isoformat()
    current = get_manual_warning_settings(group_id)

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO manual_warning_settings (
                group_id, max_warnings, auto_ban, action_mode, ban_seconds,
                escalation_enabled, warning_step, ban_increment_seconds,
                updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                ban_increment_seconds = excluded.ban_increment_seconds,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                int(current["max_warnings"]),
                1 if current["action_mode"] == "ban" else 0,
                current["action_mode"],
                current["ban_seconds"],
                1 if current["escalation_enabled"] else 0,
                int(current["warning_step"]),
                seconds,
                int(actor_id),
                now,
            ),
        )
        con.commit()

    _manual_warning_settings_hot_cache.pop(int(group_id), None)
    return get_manual_warning_settings(group_id)


def warning_repeat_level(
    group_id: int,
    user_id: int,
) -> int:
    key = (int(group_id), int(user_id))
    now = time.monotonic()
    cached = _warning_repeat_level_hot_cache.get(key)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return int(cached[1])

    with db_connect() as con:
        row = con.execute(
            """
            SELECT repeat_level
            FROM manual_warning_history
            WHERE group_id = ? AND user_id = ?
            """,
            key,
        ).fetchone()

    value = max(0, int(row["repeat_level"] or 0)) if row else 0
    _warning_repeat_level_hot_cache[key] = (now, value)
    return value


def increment_warning_repeat_level(
    group_id: int,
    user_id: int,
) -> int:
    now = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO manual_warning_history (
                group_id, user_id, repeat_level, last_completed_at
            ) VALUES (?, ?, 1, ?)
            ON CONFLICT(group_id, user_id) DO UPDATE SET
                repeat_level = repeat_level + 1,
                last_completed_at = excluded.last_completed_at
            """,
            (int(group_id), int(user_id), now),
        )
        row = con.execute(
            """
            SELECT repeat_level
            FROM manual_warning_history
            WHERE group_id = ? AND user_id = ?
            """,
            (int(group_id), int(user_id)),
        ).fetchone()
        con.commit()

    value = max(0, int(row["repeat_level"] or 0)) if row else 0
    _warning_repeat_level_hot_cache[(int(group_id), int(user_id))] = (time.monotonic(), value)
    return value


def reset_warning_repeat_level(
    group_id: int,
    user_id: int,
) -> None:
    with db_connect() as con:
        con.execute(
            """
            DELETE FROM manual_warning_history
            WHERE group_id = ? AND user_id = ?
            """,
            (int(group_id), int(user_id)),
        )
        con.commit()
    _warning_repeat_level_hot_cache.pop((int(group_id), int(user_id)), None)


def effective_warning_policy(
    group_id: int,
    user_id: int,
) -> Dict[str, Any]:
    settings = get_manual_warning_settings(group_id)
    level = warning_repeat_level(group_id, user_id)

    effective_max = int(settings["max_warnings"])
    effective_ban_seconds = settings["ban_seconds"]

    if settings["escalation_enabled"] and level > 0:
        effective_max = max(
            1,
            effective_max - (
                level * int(settings["warning_step"])
            ),
        )

        if (
            settings["action_mode"] == "ban"
            and effective_ban_seconds is not None
        ):
            effective_ban_seconds = min(
                365 * 86400,
                int(effective_ban_seconds)
                + (
                    level
                    * int(settings["ban_increment_seconds"])
                ),
            )

    return {
        **settings,
        "repeat_level": level,
        "effective_max_warnings": effective_max,
        "effective_ban_seconds": effective_ban_seconds,
    }


def warning_duration_label(seconds: Optional[int]) -> str:
    if seconds is None:
        return "دائمی"

    seconds = int(seconds)
    if seconds % 86400 == 0:
        return f"{seconds // 86400} روز"
    if seconds % 3600 == 0:
        return f"{seconds // 3600} ساعت"
    if seconds % 60 == 0:
        return f"{seconds // 60} دقیقه"
    return f"{seconds} ثانیه"


def warning_action_label(settings: Dict[str, Any]) -> str:
    mode = settings.get("action_mode", "none")
    if mode == "delete":
        return "حذف خودکار هر پیام"
    if mode == "ban":
        seconds = settings.get(
            "effective_ban_seconds",
            settings.get("ban_seconds"),
        )
        if seconds is None:
            return "بن دائمی زیوو"
        return f"بن {warning_duration_label(int(seconds))}"
    return "خاموش"



