def set_manual_ban_state(
    group_id: int,
    user_id: int,
    username: str,
    access_hash: int,
    actor_id: int,
    ban_until: Optional[datetime],
    group_access_hash: int = 0,
    ban_source: str = "manual",
) -> None:
    now = datetime.now(timezone.utc).isoformat()
    until_iso = (
        ban_until.astimezone(timezone.utc).isoformat()
        if ban_until is not None
        else None
    )

    ban_source = (ban_source or "manual").strip().lower()
    if ban_source not in {"manual", "warning", "lock", "flood", "anti_spam"}:
        ban_source = "manual"

    if not int(access_hash or 0):
        access_hash = int(stats_access_hash(group_id, user_id) or 0)

    with db_connect() as con:
        con.execute(
            """
            INSERT INTO manual_moderation (
                group_id, user_id, username, access_hash,
                muted, mute_until, banned, ban_until,
                group_access_hash, ban_release_pending, ban_source,
                updated_by, updated_at
            ) VALUES (?, ?, ?, ?, 0, NULL, 1, ?, ?, 0, ?, ?, ?)
            ON CONFLICT(group_id, user_id) DO UPDATE SET
                username = CASE
                    WHEN excluded.username != '' THEN excluded.username
                    ELSE manual_moderation.username
                END,
                access_hash = CASE
                    WHEN excluded.access_hash != 0 THEN excluded.access_hash
                    ELSE manual_moderation.access_hash
                END,
                muted = 0,
                mute_until = NULL,
                banned = 1,
                ban_until = excluded.ban_until,
                group_access_hash = CASE
                    WHEN excluded.group_access_hash != 0
                    THEN excluded.group_access_hash
                    ELSE manual_moderation.group_access_hash
                END,
                ban_release_pending = 0,
                ban_source = excluded.ban_source,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id),
                int(user_id),
                username or "",
                int(access_hash or 0),
                until_iso,
                int(group_access_hash or 0),
                ban_source,
                int(actor_id),
                now,
            ),
        )
        con.commit()



