def prepare_due_ban_releases() -> int:
    """
    Queue expired timed bans for a real platform-side release.

    zivo60.4 deliberately keeps `banned = 1` until the platform accepts
    EditBannedRequest(clear rights). This prevents local DB state from saying
    "unbanned" while the user is still restricted in the actual group.
    Warning counters/escalation are changed only after that RPC succeeds.
    """
    now_iso = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        cur = con.execute(
            """
            UPDATE manual_moderation
            SET ban_release_pending = 1
            WHERE banned = 1
              AND ban_until IS NOT NULL
              AND ban_until <= ?
              AND ban_release_pending = 0
            """,
            (now_iso,),
        )
        con.commit()
        queued = int(cur.rowcount or 0)

    return queued



def touch_ban_release_retry(
    group_id: int,
    user_id: int,
    delay_seconds: int = 30,
) -> None:
    # `updated_at` doubles as the next-attempt watermark for pending timed
    # releases. A future timestamp is deliberate: pending_ban_release_rows()
    # only selects rows older than its retry cutoff, so inaccessible groups do
    # not trigger EditBannedRequest every few seconds.
    retry_at = datetime.now(timezone.utc) + timedelta(seconds=max(5, int(delay_seconds)))
    with db_connect() as con:
        con.execute(
            """
            UPDATE manual_moderation
            SET updated_at = ?
            WHERE group_id = ?
              AND user_id = ?
              AND ban_release_pending = 1
            """,
            (
                retry_at.isoformat(),
                int(group_id),
                int(user_id),
            ),
        )
        con.commit()



def pending_ban_release_rows(
    limit: int = 25,
    retry_after_seconds: int = 20,
) -> List[sqlite3.Row]:
    cutoff = (
        datetime.now(timezone.utc)
        - timedelta(seconds=max(5, int(retry_after_seconds)))
    ).isoformat()
    with db_connect() as con:
        return con.execute(
            """
            SELECT
                group_id,
                user_id,
                username,
                access_hash,
                group_access_hash,
                ban_source,
                ban_until
            FROM manual_moderation
            WHERE ban_release_pending = 1
              AND banned = 1
              AND updated_at <= ?
            ORDER BY updated_at ASC
            LIMIT ?
            """,
            (cutoff, int(limit)),
        ).fetchall()


