def get_installation(group_id: int) -> Optional[sqlite3.Row]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _installation_hot_cache.get(gid)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return cached[1]  # type: ignore[return-value]
    with db_connect() as con:
        row = con.execute("SELECT * FROM installations WHERE group_id = ?", (gid,)).fetchone()
    value = dict(row) if row is not None else None
    _installation_hot_cache[gid] = (now, value)
    return value  # type: ignore[return-value]


def is_bot_admin(group_id: int, user_id: int) -> bool:
    gid, uid = int(group_id), int(user_id)
    if gid in _role_membership_cache_ready:
        return uid in _bot_admin_member_hot.get(gid, set())
    with db_connect() as con:
        row = con.execute(
            "SELECT 1 FROM bot_admins WHERE group_id = ? AND user_id = ?",
            (gid, uid),
        ).fetchone()
    return row is not None


def is_bot_special(group_id: int, user_id: int) -> bool:
    gid, uid = int(group_id), int(user_id)
    if gid in _role_membership_cache_ready:
        return uid in _bot_special_member_hot.get(gid, set())
    with db_connect() as con:
        row = con.execute(
            "SELECT 1 FROM bot_specials WHERE group_id = ? AND user_id = ?",
            (gid, uid),
        ).fetchone()
    return row is not None


def is_bot_exempt(group_id: int, user_id: int) -> bool:
    gid, uid = int(group_id), int(user_id)
    if gid in _role_membership_cache_ready:
        return uid in _bot_exempt_member_hot.get(gid, set())
    key = (gid, uid)
    now = time.monotonic()
    cached = _exempt_hot_cache.get(key)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return bool(cached[1])
    with db_connect() as con:
        row = con.execute("SELECT 1 FROM bot_exemptions WHERE group_id = ? AND user_id = ?", key).fetchone()
    result = row is not None
    _exempt_hot_cache[key] = (now, result)
    return result


def base_bot_role(group_id: int, user_id: int) -> str:
    if int(user_id) == GLOBAL_BOT_OWNER_ID:
        return "مالک"
    key = (int(group_id), int(user_id))
    now = time.monotonic()
    cached = _base_role_hot_cache.get(key)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return cached[1]
    installation = get_installation(group_id)
    if installation and int(installation["owner_user_id"]) == int(user_id):
        result = "مالک"
    elif is_bot_admin(group_id, user_id):
        result = "ادمین"
    elif is_bot_special(group_id, user_id):
        result = "ویژه"
    else:
        result = "کاربر عادی"
    _base_role_hot_cache[key] = (now, result)
    return result


def bot_role(group_id: int, user_id: int) -> str:
    base_role = base_bot_role(group_id, user_id)
    exempt = is_bot_exempt(group_id, user_id)

    if exempt and base_role == "کاربر عادی":
        return "معاف"

    if exempt:
        return f"{base_role} + معاف"

    return base_role


def role_level(role: str) -> int:
    return {
        "مالک": 3,
        "ادمین": 2,
        "ویژه": 1,
        "کاربر عادی": 0,
    }.get(role, 0)


def invalidate_special_override_member_cache(group_id: int, user_id: int) -> None:
    prefix = (int(group_id), int(user_id))
    for key in [item for item in _special_lock_override_hot if item[:2] == prefix]:
        _special_lock_override_hot.pop(key, None)
    for lock_name in LOCK_CATALOG:
        _special_lock_override_absent_hot.add((prefix[0], prefix[1], lock_name))


def upsert_bot_admin(
    group_id: int,
    user_id: int,
    username: str = "",
    access_hash: int = 0,
    added_by: int = 0,
    source: str = "manual",
) -> None:
    now = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        con.execute("BEGIN IMMEDIATE")

        # Main rank is exclusive: admin replaces special.
        con.execute(
            "DELETE FROM bot_specials WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(user_id)),
        )
        con.execute(
            "DELETE FROM special_lock_overrides WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(user_id)),
        )

        con.execute(
            """
            INSERT INTO bot_admins (
                group_id, user_id, username, access_hash, added_by, added_at, source
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id, user_id) DO UPDATE SET
                username = excluded.username,
                access_hash = CASE
                    WHEN excluded.access_hash != 0 THEN excluded.access_hash
                    ELSE bot_admins.access_hash
                END,
                added_by = excluded.added_by,
                added_at = excluded.added_at,
                source = CASE
                    WHEN bot_admins.source = 'manual' AND excluded.source = 'native'
                    THEN 'manual'
                    ELSE excluded.source
                END
            """,
            (
                int(group_id),
                int(user_id),
                username or "",
                int(access_hash or 0),
                int(added_by or 0),
                now,
                "native" if source == "native" else "manual",
            ),
        )

        con.commit()
    gid, uid = int(group_id), int(user_id)
    if gid in _role_membership_cache_ready:
        _bot_admin_member_hot.setdefault(gid, set()).add(uid)
        _bot_special_member_hot.setdefault(gid, set()).discard(uid)
    _base_role_hot_cache.pop((gid, uid), None)
    invalidate_special_override_member_cache(gid, uid)
    mark_group_backup_dirty(gid, invalidate_hot=False)


