def store_message_stat(
    group_id: int,
    message_id: int,
    user_id: int,
    sent_at: datetime,
    category: str,
    is_forward: bool,
) -> bool:
    sent_utc = sent_at
    if sent_utc.tzinfo is None:
        sent_utc = sent_utc.replace(tzinfo=timezone.utc)
    sent_utc = sent_utc.astimezone(timezone.utc)

    local = sent_utc.astimezone(IRAN_TZ)
    local_day = local.strftime("%Y-%m-%d")
    jmonth = jalali_month_key(local)

    with db_connect() as con:
        cur = con.execute(
            """
            INSERT OR IGNORE INTO message_stats (
                group_id, message_id, user_id, sent_ts,
                local_day, jalali_month, category, is_forward
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(group_id),
                int(message_id),
                int(user_id),
                int(sent_utc.timestamp()),
                local_day,
                jmonth,
                category if category in STATS_CATEGORIES else "other",
                1 if is_forward else 0,
            ),
        )
        con.commit()
        return cur.rowcount > 0


def _flush_stats_batch_sync(batch: List[Tuple[int, int, int, float, str, int, str, int]]) -> None:
    if not batch:
        return
    message_rows: List[Tuple[Any, ...]] = []
    member_latest: Dict[Tuple[int, int], Tuple[Any, ...]] = {}
    for group_id, message_id, user_id, sent_ts, category, is_forward, username, access_hash in batch:
        sent_utc = datetime.fromtimestamp(float(sent_ts), tz=timezone.utc)
        local = sent_utc.astimezone(IRAN_TZ)
        local_day = local.strftime("%Y-%m-%d")
        jmonth = jalali_month_key(local)
        message_rows.append((
            int(group_id), int(message_id), int(user_id), int(sent_ts),
            local_day, jmonth,
            category if category in STATS_CATEGORIES else "other",
            int(is_forward),
        ))
        seen_iso = sent_utc.isoformat()
        member_latest[(int(group_id), int(user_id))] = (
            int(group_id), int(user_id), username or "", int(access_hash or 0), seen_iso, seen_iso,
        )
    with db_connect() as con:
        con.executemany(
            """
            INSERT OR IGNORE INTO message_stats (
                group_id, message_id, user_id, sent_ts,
                local_day, jalali_month, category, is_forward
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            message_rows,
        )
        con.executemany(
            """
            INSERT INTO stats_members (
                group_id, user_id, username, access_hash,
                first_seen_at, last_seen_at, warning_total
            ) VALUES (?, ?, ?, ?, ?, ?, 0)
            ON CONFLICT(group_id, user_id) DO UPDATE SET
                username = CASE WHEN excluded.username != '' THEN excluded.username ELSE stats_members.username END,
                access_hash = CASE WHEN excluded.access_hash != 0 THEN excluded.access_hash ELSE stats_members.access_hash END,
                last_seen_at = excluded.last_seen_at
            """,
            list(member_latest.values()),
        )
        con.commit()


async def stats_write_worker() -> None:
    await asyncio.sleep(1.0)
    while True:
        try:
            if not _stats_write_queue:
                await asyncio.sleep(STATS_WRITE_INTERVAL_SECONDS)
                continue
            batch: List[Tuple[int, int, int, float, str, int, str, int]] = []
            while _stats_write_queue and len(batch) < STATS_WRITE_BATCH_MAX:
                batch.append(_stats_write_queue.popleft())
            await asyncio.to_thread(_flush_stats_batch_sync, batch)
        except asyncio.CancelledError:
            if _stats_write_queue:
                remaining = list(_stats_write_queue)
                _stats_write_queue.clear()
                try:
                    await asyncio.to_thread(_flush_stats_batch_sync, remaining)
                except Exception:
                    pass
            raise
        except Exception:
            log.exception("stats batch writer error")
            await asyncio.sleep(0.5)


async def record_group_message_stats(event: Any) -> None:
    if bool(getattr(event, "is_private", False)):
        return
    message = getattr(event, "message", None) or event
    if getattr(message, "action", None) is not None:
        return
    sender_id = safe_int(getattr(event, "sender_id", None))
    message_id = safe_int(getattr(message, "id", None) or getattr(event, "id", None))
    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if sender_id is None or message_id is None or group_id is None:
        return
    if sender_id == SELF_USER_ID or sender_id in SYSTEM_USER_IDS:
        return
    if get_installation(group_id) is None:
        return
    sent_at = getattr(message, "date", None)
    if not isinstance(sent_at, datetime):
        sent_at = datetime.now(timezone.utc)
    elif sent_at.tzinfo is None:
        sent_at = sent_at.replace(tzinfo=timezone.utc)
    sent_at = sent_at.astimezone(timezone.utc)
    category = message_stats_category(message)
    is_forward = 1 if message_is_forwarded(message) else 0
    input_sender = getattr(event, "input_sender", None)
    access_hash = input_peer_access_hash(input_sender)
    username = input_peer_username(input_sender)
    sender_obj = getattr(event, "sender", None)
    if not username and sender_obj is not None:
        username = getattr(sender_obj, "username", None) or ""
    _stats_write_queue.append((
        int(group_id), int(message_id), int(sender_id), float(sent_at.timestamp()),
        category, int(is_forward), username or "", int(access_hash or 0),
    ))
    if len(_stats_write_queue) == STATS_WRITE_QUEUE_WARN:
        log.warning("stats write queue high-water | queued=%s", len(_stats_write_queue))


def stats_scope_sql(
    group_id: int,
    user_id: Optional[int] = None,
    role_table: Optional[str] = None,
) -> Tuple[str, List[Any]]:
    where = ["ms.group_id = ?"]
    params: List[Any] = [int(group_id)]

    if user_id is not None:
        where.append("ms.user_id = ?")
        params.append(int(user_id))

    if role_table is not None:
        if role_table not in set(STATS_ROLE_TABLES.values()):
            raise ValueError("INVALID_STATS_ROLE_TABLE")
        where.append(
            f"ms.user_id IN (SELECT user_id FROM {role_table} WHERE group_id = ?)"
        )
        params.append(int(group_id))

    return " AND ".join(where), params


def empty_aggregate_stats() -> Dict[str, int]:
    result = {"total": 0, "forward": 0}
    for key in STATS_CATEGORIES:
        result[key] = 0
    return result


def aggregate_message_stats(
    group_id: int,
    user_id: Optional[int] = None,
    role_table: Optional[str] = None,
) -> Dict[str, int]:
    where, params = stats_scope_sql(group_id, user_id, role_table)

    category_columns = ",\n".join(
        f"SUM(CASE WHEN ms.category = '{category}' THEN 1 ELSE 0 END) AS {category}"
        for category in STATS_CATEGORIES
    )

    sql = f"""
        SELECT
            COUNT(*) AS total,
            SUM(CASE WHEN ms.is_forward = 1 THEN 1 ELSE 0 END) AS forward,
            {category_columns}
        FROM message_stats ms
        WHERE {where}
    """

    with db_connect() as con:
        row = con.execute(sql, params).fetchone()

    result = empty_aggregate_stats()
    if row is None:
        return result

    for key in result:
        result[key] = int(row[key] or 0)

    return result


def current_period_keys() -> Tuple[str, str, str, str]:
    local = iran_datetime()
    today = local.date()
    yesterday = today - timedelta(days=1)

    # Iranian week starts on Saturday. Python Monday=0 ... Sunday=6.
    days_since_saturday = (today.weekday() - 5) % 7
    week_start = today - timedelta(days=days_since_saturday)

    return (
        today.isoformat(),
        yesterday.isoformat(),
        week_start.isoformat(),
        jalali_month_key(local),
    )


def period_message_counts(
    group_id: int,
    user_id: Optional[int] = None,
    role_table: Optional[str] = None,
) -> Dict[str, int]:
    where, params = stats_scope_sql(group_id, user_id, role_table)
    today, yesterday, week_start, jmonth = current_period_keys()

    sql = f"""
        SELECT
            SUM(CASE WHEN ms.local_day = ? THEN 1 ELSE 0 END) AS today,
            SUM(CASE WHEN ms.local_day = ? THEN 1 ELSE 0 END) AS yesterday,
            SUM(CASE WHEN ms.local_day >= ? AND ms.local_day <= ? THEN 1 ELSE 0 END) AS week,
            SUM(CASE WHEN ms.jalali_month = ? THEN 1 ELSE 0 END) AS month
        FROM message_stats ms
        WHERE {where}
    """

    query_params = [today, yesterday, week_start, today, jmonth] + params

    with db_connect() as con:
        row = con.execute(sql, query_params).fetchone()

    return {
        "today": int((row["today"] if row else 0) or 0),
        "yesterday": int((row["yesterday"] if row else 0) or 0),
        "week": int((row["week"] if row else 0) or 0),
        "month": int((row["month"] if row else 0) or 0),
    }


def stats_member_row(group_id: int, user_id: int) -> Optional[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            """
            SELECT * FROM stats_members
            WHERE group_id = ? AND user_id = ?
            """,
            (int(group_id), int(user_id)),
        ).fetchone()


def stats_access_hash(group_id: int, user_id: int) -> int:
    row = stats_member_row(group_id, user_id)
    if row is not None and int(row["access_hash"] or 0):
        return int(row["access_hash"])

    installation = get_installation(group_id)
    if (
        installation is not None
        and int(installation["owner_user_id"]) == int(user_id)
        and int(installation["owner_access_hash"] or 0)
    ):
        return int(installation["owner_access_hash"])

    for table in ("bot_admins", "bot_specials", "bot_exemptions"):
        with db_connect() as con:
            role_row = con.execute(
                f"SELECT access_hash FROM {table} WHERE group_id = ? AND user_id = ?",
                (int(group_id), int(user_id)),
            ).fetchone()

        if role_row is not None and int(role_row["access_hash"] or 0):
            return int(role_row["access_hash"])

    return 0


def user_message_rank(group_id: int, user_id: int) -> Tuple[Optional[int], int]:
    with db_connect() as con:
        rows = con.execute(
            """
            SELECT user_id, COUNT(*) AS total
            FROM message_stats
            WHERE group_id = ?
            GROUP BY user_id
            ORDER BY total DESC, user_id ASC
            """,
            (int(group_id),),
        ).fetchall()

    for index, row in enumerate(rows, start=1):
        if int(row["user_id"]) == int(user_id):
            return index, len(rows)

    return None, len(rows)


def top_users_today(
    group_id: int,
    limit: int = 20,
    role_table: Optional[str] = None,
) -> List[sqlite3.Row]:
    today, _, _, _ = current_period_keys()
    where, params = stats_scope_sql(group_id, None, role_table)
    where += " AND ms.local_day = ?"
    params.append(today)

    sql = f"""
        SELECT ms.user_id, COUNT(*) AS total
        FROM message_stats ms
        WHERE {where}
        GROUP BY ms.user_id
        ORDER BY total DESC, ms.user_id ASC
        LIMIT ?
    """
    params.append(int(limit))

    with db_connect() as con:
        return con.execute(sql, params).fetchall()


def role_member_count(group_id: int, role_table: str) -> int:
    if role_table not in set(STATS_ROLE_TABLES.values()):
        raise ValueError("INVALID_STATS_ROLE_TABLE")

    with db_connect() as con:
        row = con.execute(
            f"SELECT COUNT(*) AS c FROM {role_table} WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()

    return int(row["c"] or 0)


def group_role_counts(group_id: int) -> Dict[str, int]:
    installation = get_installation(group_id)
    owner_id = int(installation["owner_user_id"]) if installation else 0

    with db_connect() as con:
        admins = int(
            con.execute(
                "SELECT COUNT(*) AS c FROM bot_admins WHERE group_id = ?",
                (int(group_id),),
            ).fetchone()["c"]
            or 0
        )
        specials = int(
            con.execute(
                "SELECT COUNT(*) AS c FROM bot_specials WHERE group_id = ?",
                (int(group_id),),
            ).fetchone()["c"]
            or 0
        )
        exempt = int(
            con.execute(
                "SELECT COUNT(*) AS c FROM bot_exemptions WHERE group_id = ?",
                (int(group_id),),
            ).fetchone()["c"]
            or 0
        )
        tracked = int(
            con.execute(
                "SELECT COUNT(*) AS c FROM stats_members WHERE group_id = ?",
                (int(group_id),),
            ).fetchone()["c"]
            or 0
        )

        ordinary = int(
            con.execute(
                """
                SELECT COUNT(*) AS c
                FROM stats_members sm
                WHERE sm.group_id = ?
                  AND sm.user_id != ?
                  AND NOT EXISTS (
                      SELECT 1 FROM bot_admins a
                      WHERE a.group_id = sm.group_id AND a.user_id = sm.user_id
                  )
                  AND NOT EXISTS (
                      SELECT 1 FROM bot_specials s
                      WHERE s.group_id = sm.group_id AND s.user_id = sm.user_id
                  )
                """,
                (int(group_id), owner_id),
            ).fetchone()["c"]
            or 0
        )

    return {
        "owner": 1 if installation else 0,
        "admin": admins,
        "special": specials,
        "exempt": exempt,
        "ordinary": ordinary,
        "tracked": tracked,
    }


