def format_activity_breakdown(stats: Dict[str, int]) -> str:
    lines = [
        f"📨 ردپای پیام‌ها: {stats_num(stats['total'])}",
        f"├ متن: {stats_num(stats['text'])}",
        f"├ فوروارد: {stats_num(stats['forward'])}",
        f"├ ویدیو: {stats_num(stats['video'])}",
        f"├ ویدیوی گرد: {stats_num(stats['video_note'])}",
        f"├ آهنگ: {stats_num(stats['audio'])}",
        f"├ ویس: {stats_num(stats['voice'])}",
        f"├ عکس: {stats_num(stats['photo'])}",
        f"├ گیف: {stats_num(stats['gif'])}",
        f"├ استیکر: {stats_num(stats['sticker'])}",
        f"├ استیکر متحرک: {stats_num(stats['animated_sticker'])}",
    ]

    # Show files/other only when they actually exist, keeping normal reports tidy.
    if int(stats.get("file", 0) or 0) > 0:
        lines.append(f"├ فایل: {stats_num(stats['file'])}")

    if int(stats.get("other", 0) or 0) > 0:
        lines.append(f"├ سایر: {stats_num(stats['other'])}")

    lines.append(f"└ نظرسنجی: {stats_num(stats['poll'])}")

    return "\n".join(lines)


def format_period_breakdown(periods: Dict[str, int]) -> str:
    return "\n".join(
        (
            "🗓 ریتم فعالیت:",
            f"● امروز: {stats_num(periods['today'])}",
            f"● دیروز: {stats_num(periods['yesterday'])}",
            f"● این هفته: {stats_num(periods['week'])}",
            f"● این ماه: {stats_num(periods['month'])}",
        )
    )


def stats_top_lines(
    group_id: int,
    rows: List[sqlite3.Row],
) -> Tuple[str, List[Tuple[str, int, int]]]:
    if not rows:
        return "└ امروز هنوز پیامی ثبت نشده است.", []

    medals = ("🥇", "🥈", "🥉")
    lines: List[str] = []
    mentions: List[Tuple[str, int, int]] = []

    for index, row in enumerate(rows, start=1):
        user_id = int(row["user_id"])
        count = int(row["total"] or 0)
        label = "﹝مشاهده نمایه﹞"

        if index <= 3:
            prefix = medals[index - 1]
        else:
            prefix = f"{stats_num(index)}."

        lines.append(
            f"{prefix} {label}  ┋  {stats_num(count)} پیام ثبت‌شده"
        )
        mentions.append(
            (
                label,
                user_id,
                stats_access_hash(group_id, user_id),
            )
        )

    return "\n".join(lines), mentions


