def save_real_owner_recovery_cache(
    group_id: int,
    real_owner_id: int,
    username: str = "",
    access_hash: int = 0,
) -> None:
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO owner_recovery_cache (
                group_id, real_owner_id, username, access_hash, detected_at
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                real_owner_id = excluded.real_owner_id,
                username = excluded.username,
                access_hash = CASE
                    WHEN excluded.access_hash != 0 THEN excluded.access_hash
                    ELSE owner_recovery_cache.access_hash
                END,
                detected_at = excluded.detected_at
            """,
            (
                int(group_id),
                int(real_owner_id),
                username or "",
                int(access_hash or 0),
                now,
            ),
        )
        con.commit()


