def reclaim_bot_ownership_for_real_group_owner(
    group_id: int,
    real_owner_id: int,
    real_owner_username: str = "",
    real_owner_access_hash: int = 0,
) -> Tuple[sqlite3.Row, int]:
    """
    Restore ZIVO ownership to the real Soroush group owner.

    Important: this is a recovery path, not an intentional transfer.
    The previous ZIVO owner is NOT promoted to internal ZIVO admin.
    """
    with db_connect() as con:
        con.execute("BEGIN IMMEDIATE")

        installation = con.execute(
            "SELECT * FROM installations WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()

        if installation is None:
            raise ValueError("GROUP_NOT_INSTALLED")

        previous_owner_id = int(installation["owner_user_id"])

        # The restored real owner must have only one internal role: owner.
        con.execute(
            "DELETE FROM bot_admins WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(real_owner_id)),
        )
        con.execute(
            "DELETE FROM bot_specials WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(real_owner_id)),
        )
        con.execute(
            "DELETE FROM special_lock_overrides WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(real_owner_id)),
        )

        con.execute(
            """
            UPDATE installations
            SET owner_user_id = ?,
                owner_username = ?,
                owner_access_hash = ?,
                native_owner_user_id = ?,
                native_owner_username = ?,
                native_owner_access_hash = ?,
                owner_mode = 'native'
            WHERE group_id = ?
            """,
            (
                int(real_owner_id),
                real_owner_username or "",
                int(real_owner_access_hash or 0),
                int(real_owner_id),
                real_owner_username or "",
                int(real_owner_access_hash or 0),
                int(group_id),
            ),
        )

        updated = con.execute(
            "SELECT * FROM installations WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()

        con.commit()

    if updated is None:
        raise RuntimeError("REAL_OWNER_RECLAIM_FAILED")
    invalidate_group_hot_caches(group_id)
    refresh_role_membership_cache(group_id)
    return updated, previous_owner_id


def transfer_bot_ownership(
    group_id: int,
    current_owner_id: int,
    new_owner_id: int,
    new_owner_username: str = "",
    new_owner_access_hash: int = 0,
) -> sqlite3.Row:
    """
    Atomically:
      1) validates current owner,
      2) promotes old owner to internal ZIVO admin,
      3) removes new owner from bot_admins if present,
      4) writes the new owner to installations.
    """
    now = datetime.now(timezone.utc).isoformat()

    with db_connect() as con:
        con.execute("BEGIN IMMEDIATE")

        installation = con.execute(
            "SELECT * FROM installations WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()

        if installation is None:
            raise ValueError("GROUP_NOT_INSTALLED")

        stored_owner_id = int(installation["owner_user_id"])
        if stored_owner_id != int(current_owner_id):
            raise PermissionError("OWNER_ONLY")

        if int(new_owner_id) == stored_owner_id:
            raise ValueError("SAME_OWNER")

        old_owner_username = installation["owner_username"] or ""
        old_owner_access_hash = int(installation["owner_access_hash"] or 0)

        con.execute(
            "DELETE FROM bot_specials WHERE group_id = ? AND user_id = ?",
            (int(group_id), stored_owner_id),
        )
        con.execute(
            "DELETE FROM special_lock_overrides WHERE group_id = ? AND user_id = ?",
            (int(group_id), stored_owner_id),
        )

        con.execute(
            """
            INSERT INTO bot_admins (
                group_id, user_id, username, access_hash, added_by, added_at
            ) VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id, user_id) DO UPDATE SET
                username = excluded.username,
                access_hash = CASE
                    WHEN excluded.access_hash != 0 THEN excluded.access_hash
                    ELSE bot_admins.access_hash
                END,
                added_by = excluded.added_by,
                added_at = excluded.added_at
            """,
            (
                int(group_id),
                stored_owner_id,
                old_owner_username,
                old_owner_access_hash,
                stored_owner_id,
                now,
            ),
        )

        # The new owner must have only one ZIVO role: owner.
        con.execute(
            "DELETE FROM bot_admins WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(new_owner_id)),
        )
        con.execute(
            "DELETE FROM bot_specials WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(new_owner_id)),
        )
        con.execute(
            "DELETE FROM special_lock_overrides WHERE group_id = ? AND user_id = ?",
            (int(group_id), int(new_owner_id)),
        )

        con.execute(
            """
            UPDATE installations
            SET owner_user_id = ?,
                owner_username = ?,
                owner_access_hash = ?
            WHERE group_id = ?
            """,
            (
                int(new_owner_id),
                new_owner_username or "",
                int(new_owner_access_hash or 0),
                int(group_id),
            ),
        )

        updated = con.execute(
            "SELECT * FROM installations WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()

        con.commit()

    if updated is None:
        raise RuntimeError("TRANSFER_UPDATE_FAILED")
    invalidate_group_hot_caches(group_id)
    refresh_role_membership_cache(group_id)
    return updated


def _group_lifecycle_upsert_in_connection(
    con: sqlite3.Connection,
    group_id: int,
    group_title: str,
    peer_kind: str,
    group_access_hash: int,
    *,
    now: Optional[str] = None,
) -> None:
    stamp = str(now or datetime.now(timezone.utc).isoformat())
    normalized_peer_kind = "chat" if str(peer_kind or "").strip().lower() == "chat" else "channel"
    con.execute(
        """
        INSERT INTO group_lifecycle (
            group_id, group_title, peer_kind, group_access_hash,
            activated_at, last_activity_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?)
        ON CONFLICT(group_id) DO UPDATE SET
            group_title = excluded.group_title,
            peer_kind = excluded.peer_kind,
            group_access_hash = CASE
                WHEN excluded.group_access_hash != 0 THEN excluded.group_access_hash
                ELSE group_lifecycle.group_access_hash
            END,
            activated_at = excluded.activated_at,
            last_activity_at = excluded.last_activity_at,
            updated_at = excluded.updated_at
        """,
        (
            int(group_id), str(group_title or ""), normalized_peer_kind,
            int(group_access_hash or 0), stamp, stamp, stamp,
        ),
    )


def register_installation(
    group_id: int,
    group_title: str,
    owner_user_id: int,
    owner_username: str = "",
    owner_access_hash: int = 0,
    invite_hash: str = "",
    install_source: str = "invite",
    native_owner_user_id: int = 0,
    native_owner_username: str = "",
    native_owner_access_hash: int = 0,
    owner_mode: str = "native",
    introduced_by_user_id: int = 0,
    introduced_by_username: str = "",
    activation_card: Optional[Dict[str, Any]] = None,
) -> sqlite3.Row:
    now = datetime.now(timezone.utc).isoformat()
    locks_json = json.dumps(DEFAULT_LOCKS, ensure_ascii=False)

    with db_connect() as con:
        con.execute(
            """
            INSERT OR IGNORE INTO installations (
                group_id, group_title, owner_user_id, owner_username,
                owner_access_hash, invite_hash, install_source,
                default_locks_json, installed_at, native_owner_user_id,
                native_owner_username, native_owner_access_hash, owner_mode
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(group_id),
                group_title or "",
                int(owner_user_id),
                owner_username or "",
                int(owner_access_hash or 0),
                invite_hash or "",
                install_source,
                locks_json,
                now,
                int(native_owner_user_id or 0),
                native_owner_username or "",
                int(native_owner_access_hash or 0),
                owner_mode or "native",
            ),
        )
        con.execute(
            """
            UPDATE installations
            SET group_title = ?,
                owner_access_hash = CASE
                    WHEN owner_access_hash = 0 AND ? != 0 THEN ?
                    ELSE owner_access_hash
                END,
                native_owner_user_id = CASE
                    WHEN native_owner_user_id = 0 AND ? != 0 THEN ?
                    ELSE native_owner_user_id
                END,
                native_owner_username = CASE
                    WHEN native_owner_username = '' AND ? != '' THEN ?
                    ELSE native_owner_username
                END,
                native_owner_access_hash = CASE
                    WHEN native_owner_access_hash = 0 AND ? != 0 THEN ?
                    ELSE native_owner_access_hash
                END,
                owner_mode = CASE
                    WHEN ? != '' THEN ?
                    ELSE owner_mode
                END
            WHERE group_id = ?
            """,
            (
                group_title or "",
                int(owner_access_hash or 0),
                int(owner_access_hash or 0),
                int(native_owner_user_id or 0),
                int(native_owner_user_id or 0),
                native_owner_username or "",
                native_owner_username or "",
                int(native_owner_access_hash or 0),
                int(native_owner_access_hash or 0),
                owner_mode or "",
                owner_mode or "",
                int(group_id),
            ),
        )
        # Preserve who actually introduced this ZIVO installation when the
        # migrated columns are available. Keeping this as a compatibility
        # UPDATE (instead of widening the core INSERT) lets historical tools
        # with the minimal installations schema continue to call this helper.
        try:
            install_columns = {
                str(row[1]) for row in con.execute("PRAGMA table_info(installations)").fetchall()
            }
            if {"introduced_by_user_id", "introduced_by_username"}.issubset(install_columns):
                con.execute(
                    """
                    UPDATE installations
                    SET introduced_by_user_id = CASE
                            WHEN introduced_by_user_id = 0 AND ? != 0 THEN ?
                            ELSE introduced_by_user_id
                        END,
                        introduced_by_username = CASE
                            WHEN introduced_by_username = '' AND ? != '' THEN ?
                            ELSE introduced_by_username
                        END
                    WHERE group_id = ?
                    """,
                    (
                        int(introduced_by_user_id or 0), int(introduced_by_user_id or 0),
                        introduced_by_username or "", introduced_by_username or "",
                        int(group_id),
                    ),
                )
        except sqlite3.Error:
            pass
        if activation_card is not None:
            _activation_card_job_upsert_in_connection(
                con,
                int(group_id),
                int(activation_card.get("owner_id") or owner_user_id),
                int(activation_card.get("owner_access_hash") or owner_access_hash or 0),
                int(activation_card.get("native_owner_id") or native_owner_user_id or 0),
                bool(activation_card.get("native_owner_available")),
                str(activation_card.get("owner_mode") or owner_mode or "native"),
                bool(activation_card.get("probe_already_sent")),
                now=now,
            )
            _group_lifecycle_upsert_in_connection(
                con,
                int(group_id),
                str(activation_card.get("group_title") or group_title or ""),
                str(activation_card.get("peer_kind") or "channel"),
                int(activation_card.get("group_access_hash") or 0),
                now=now,
            )
            con.execute(
                """
                UPDATE pending_group_activations
                SET group_notice_sent = 1,
                    group_notice_sent_at = ?,
                    group_notice_last_error = '',
                    updated_at = ?
                WHERE group_id = ?
                """,
                (now, now, int(group_id)),
            )
        con.commit()
        row = con.execute(
            "SELECT * FROM installations WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()

    activate_default_install_locks(group_id, owner_user_id)
    if row is None:
        raise RuntimeError("INSTALLATION_REGISTER_FAILED")
    invalidate_group_hot_caches(group_id)
    refresh_role_membership_cache(group_id)
    return row


def get_pending_group_activation(group_id: int) -> Optional[sqlite3.Row]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _pending_group_activation_hot_cache.get(gid)
    if cached is not None and now - cached[0] < PENDING_GROUP_ACTIVATION_CACHE_TTL:
        return cached[1]  # type: ignore[return-value]
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM pending_group_activations WHERE group_id = ?",
            (gid,),
        ).fetchone()
    value = dict(row) if row is not None else None
    _pending_group_activation_hot_cache[gid] = (now, value)
    return value  # type: ignore[return-value]


def register_pending_group_activation(
    group: Any,
    group_title: str,
    requester_user_id: int = 0,
    requester_access_hash: int = 0,
    install_source: str = "",
    invite_ref: str = "",
) -> sqlite3.Row:
    group_id = int(getattr(group, "id"))
    now = datetime.now(timezone.utc)
    now_iso = now.isoformat()
    deadline_iso = (now + timedelta(seconds=GROUP_ACTIVATION_GRACE_SECONDS)).isoformat()
    peer_kind = "chat" if isinstance(group, types.Chat) else "channel"
    group_access_hash = int(getattr(group, "access_hash", 0) or 0)

    with db_connect() as con:
        existing = con.execute(
            "SELECT * FROM pending_group_activations WHERE group_id = ?",
            (group_id,),
        ).fetchone()
        if existing is None:
            con.execute(
                """
                INSERT INTO pending_group_activations (
                    group_id, group_title, requester_user_id,
                    requester_access_hash, install_source, invite_ref,
                    peer_kind, group_access_hash, joined_at,
                    activation_deadline, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    group_id,
                    group_title or "",
                    int(requester_user_id or 0),
                    int(requester_access_hash or 0),
                    install_source or "",
                    invite_ref or "",
                    peer_kind,
                    group_access_hash,
                    now_iso,
                    deadline_iso,
                    now_iso,
                ),
            )
        else:
            con.execute(
                """
                UPDATE pending_group_activations
                SET group_title = ?,
                    requester_user_id = CASE
                        WHEN requester_user_id = 0 AND ? != 0 THEN ?
                        ELSE requester_user_id
                    END,
                    requester_access_hash = CASE
                        WHEN requester_access_hash = 0 AND ? != 0 THEN ?
                        ELSE requester_access_hash
                    END,
                    install_source = CASE
                        WHEN install_source = '' AND ? != '' THEN ?
                        ELSE install_source
                    END,
                    invite_ref = CASE
                        WHEN invite_ref = '' AND ? != '' THEN ?
                        ELSE invite_ref
                    END,
                    peer_kind = ?,
                    group_access_hash = CASE
                        WHEN ? != 0 THEN ?
                        ELSE group_access_hash
                    END,
                    activation_attempt_count = 0,
                    activation_next_attempt_at = ?,
                    activation_last_error = '',
                    updated_at = ?
                WHERE group_id = ?
                """,
                (
                    group_title or "",
                    int(requester_user_id or 0), int(requester_user_id or 0),
                    int(requester_access_hash or 0), int(requester_access_hash or 0),
                    install_source or "", install_source or "",
                    invite_ref or "", invite_ref or "",
                    peer_kind,
                    group_access_hash, group_access_hash,
                    now_iso,
                    now_iso,
                    group_id,
                ),
            )
        con.commit()
        row = con.execute(
            "SELECT * FROM pending_group_activations WHERE group_id = ?",
            (group_id,),
        ).fetchone()
    value = dict(row) if row is not None else None
    _pending_group_activation_hot_cache[int(group_id)] = (time.monotonic(), value)
    return value  # type: ignore[return-value]


def clear_pending_group_activation(group_id: int) -> None:
    with db_connect() as con:
        con.execute(
            "DELETE FROM pending_group_activations WHERE group_id = ?",
            (int(group_id),),
        )
        con.commit()
    _pending_group_activation_hot_cache.pop(int(group_id), None)


