def _group_join_notice_defer(group_id: int, attempt_count: int, error: BaseException | str) -> None:
    attempt = max(0, int(attempt_count)) + 1
    error_text_upper = str(error).upper()
    if "GROUP_ENTITY_UNRESOLVED" in error_text_upper:
        steps = (8, 20, 60, 180, 300, 600, 900, 1200)
        delay = float(steps[min(attempt - 1, len(steps) - 1)])
    elif "GROUP_SEND_ACCESS_NOT_CONFIRMED" in error_text_upper or "CHATWRITEFORBIDDEN" in error_text_upper or "YOU CAN'T WRITE" in error_text_upper:
        steps = (5, 15, 45, 120, 300, 600, 900, 1200)
        delay = float(steps[min(attempt - 1, len(steps) - 1)])
    else:
        delay = min(JOIN_NOTICE_RETRY_MAX_SECONDS, JOIN_NOTICE_RETRY_BASE_SECONDS * (2 ** min(attempt - 1, 5)))
    now = datetime.now(timezone.utc)
    next_at = (now + timedelta(seconds=delay)).isoformat()
    error_text = str(error)[:500]
    with db_connect() as con:
        con.execute(
            """
            UPDATE pending_group_activations
            SET group_notice_attempt_count = ?,
                group_notice_next_attempt_at = ?,
                group_notice_last_error = ?,
                updated_at = ?
            WHERE group_id = ?
            """,
            (attempt, next_at, error_text, now.isoformat(), int(group_id)),
        )
        con.commit()
    _pending_group_activation_hot_cache.pop(int(group_id), None)


async def _resolve_group_join_notice_entity(row: Dict[str, Any]) -> Optional[Any]:
    gid = int(row["group_id"])
    cached = _join_notice_entity_cache.get(gid) or _pending_dialog_entity_cache.get(gid)
    if cached is not None and is_group_entity(cached):
        return cached
    try:
        with db_connect() as con:
            fresh = con.execute(
                "SELECT * FROM pending_group_activations WHERE group_id = ?",
                (gid,),
            ).fetchone()
        if fresh is None:
            return None
        return await resolve_pending_group_entity(fresh, allow_dialog_scan=False)
    except Exception:
        return None


async def _process_group_join_notice_job(row: Dict[str, Any]) -> None:
    gid = int(row["group_id"])
    if gid in _join_notice_inflight:
        return
    _join_notice_inflight.add(gid)
    try:
        group = await _resolve_group_join_notice_entity(row)
        if group is None:
            raise RuntimeError("GROUP_ENTITY_UNRESOLVED")

        probe_sent = bool(int(row.get("group_notice_probe_sent") or 0))
        if not probe_sent:
            # A short-lived write-forbidden result immediately after joining must
            # not impose the generic 45s group backoff on the install receipt.
            _group_send_probe_retry_after.pop(gid, None)
            if not await probe_group_send_access(group, marker="👀"):
                raise RuntimeError("GROUP_SEND_ACCESS_NOT_CONFIRMED")
            await asyncio.to_thread(_group_join_notice_mark_probe, gid)
            row["group_notice_probe_sent"] = 1
            await asyncio.sleep(0.15)

        # Activate only after the proven write gate.  Do not complete this job
        # until activation succeeds: owner resolution can be temporarily
        # unavailable and must stay eligible for a durable retry.
        fresh = get_pending_group_activation(gid)
        if fresh is None:
            if get_installation(gid) is None:
                raise RuntimeError("PENDING_GROUP_ROW_MISSING_AFTER_WRITE_PROBE")
        else:
            activated = await try_auto_activate_pending_group(
                fresh,
                group_override=group,
                trigger="join-active-card",
                deliver_card_inline=True,
            )
            if not activated:
                raise RuntimeError("PENDING_ACTIVATION_NOT_READY")
        await asyncio.to_thread(_group_join_notice_complete, gid)
        log.info("group join write+active-card attempted | group=%s durable=1", gid)
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        await asyncio.to_thread(
            _group_join_notice_defer,
            gid,
            int(row.get("group_notice_attempt_count") or 0),
            exc,
        )
        log.info(
            "group join notice deferred | group=%s attempt=%s | %s: %s",
            gid, int(row.get("group_notice_attempt_count") or 0) + 1,
            type(exc).__name__, exc,
        )
    finally:
        _join_notice_inflight.discard(gid)


async def group_join_notice_worker(worker_id: int) -> None:
    while True:
        try:
            rows = await asyncio.to_thread(_group_join_notice_jobs_due, JOIN_NOTICE_BATCH_MAX)
            pending_pressure = _transport_pending_request_count(client)
            startup_quiet = _routine_background_quiet_period_active()
            chosen = next((
                row for row in rows
                if int(row["group_id"]) not in _join_notice_inflight
                and (
                    int(row.get("group_notice_attempt_count") or 0) <= 2
                    or (not startup_quiet and not _priority_traffic_is_hot() and pending_pressure < FOREGROUND_BACKGROUND_PENDING_SOFT)
                )
            ), None)
            if chosen is not None:
                await _process_group_join_notice_job(chosen)
                continue
            wake = _join_notice_wakeup
            if wake is None:
                await asyncio.sleep(1.0)
                continue
            try:
                await asyncio.wait_for(wake.wait(), timeout=1.5)
            except asyncio.TimeoutError:
                pass
            wake.clear()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("group join notice worker error | worker=%s", worker_id)
            await asyncio.sleep(1.5)


async def _background_try_auto_activate(pending_group_id: int, group: Any, trigger: str) -> None:
    try:
        # Give the write-only join receipt first priority. Owner/admin discovery is
        # deliberately delayed so link handling and the visible install message
        # stay fast even when participant RPCs are slow.
        for _ in range(12):
            row = get_pending_group_activation(int(pending_group_id))
            if row is None:
                return
            if int(row["group_notice_probe_sent"] or 0) == 1:
                break
            await asyncio.sleep(0.35)
        else:
            return
        await asyncio.sleep(1.5)
        await _yield_background_to_realtime(0.8)
        row = get_pending_group_activation(int(pending_group_id))
        if row is None:
            return
        activated = await try_auto_activate_pending_group(row, group_override=group, trigger=trigger)
        if activated:
            await asyncio.to_thread(_group_join_notice_complete, int(pending_group_id))
    except Exception as exc:
        log.info(
            "background pending activation deferred | group=%s trigger=%s | %s: %s",
            int(pending_group_id), trigger, type(exc).__name__, exc,
        )


async def _post_activation_card_task(
    group: Any,
    group_id: int,
    owner_id: int,
    owner_access_hash: int,
    native_owner_id: int,
    native_owner_available: bool,
    owner_mode: str,
    probe_already_sent: bool = False,
    deliver_inline: bool = False,
    already_persisted: bool = False,
) -> bool:
    """Return true once the card is durably queued or directly delivered."""
    gid = int(group_id)
    if group is not None:
        _activation_card_entity_cache[gid] = group
    durable = bool(already_persisted)
    try:
        if not durable:
            await asyncio.to_thread(
                _activation_card_job_upsert,
                gid, int(owner_id), int(owner_access_hash or 0),
                int(native_owner_id or 0), bool(native_owner_available), str(owner_mode or "native"),
                bool(probe_already_sent),
            )
            durable = True
        if _activation_card_wakeup is not None:
            _activation_card_wakeup.set()
        log.info("activation card queued | group=%s durable=1", gid)
        if deliver_inline:
            job = await asyncio.to_thread(_activation_card_job_row, gid)
            if job is not None:
                await _process_activation_card_job(job)
        return True
    except Exception as exc:
        if durable:
            log.warning(
                "activation card inline delivery deferred but durable | group=%s | %s: %s",
                gid, type(exc).__name__, exc,
            )
            if _activation_card_wakeup is not None:
                _activation_card_wakeup.set()
            return True
        # A persistence problem must not silently lose the visible card. Keep a
        # direct fallback, while reporting total queue+send failure as false.
        log.warning(
            "activation card queue persistence failed | group=%s | %s: %s",
            gid, type(exc).__name__, exc,
        )
        try:
            write_ready = bool(probe_already_sent)
            if not write_ready:
                write_ready = await probe_group_send_access(group, marker="👀")
            if write_ready:
                await send_default_join_message(
                    group, int(owner_id), int(owner_access_hash or 0),
                    native_owner_id=int(native_owner_id or 0),
                    native_owner_available=bool(native_owner_available),
                    owner_mode=str(owner_mode or "native"),
                    probe_already_sent=True,
                )
                try:
                    await asyncio.to_thread(_activation_card_complete, gid)
                except Exception:
                    pass
                return True
        except Exception as fallback_exc:
            log.warning(
                "activation card direct fallback deferred | group=%s | %s: %s",
                gid, type(fallback_exc).__name__, fallback_exc,
            )
        return False


async def _activation_card_resolve_group(group_id: int) -> Optional[Any]:
    gid = int(group_id)
    cached = _activation_card_entity_cache.get(gid)
    if cached is not None and is_group_entity(cached):
        return cached
    try:
        with db_connect() as con:
            row = con.execute(
                "SELECT group_id, peer_kind, group_access_hash FROM group_lifecycle WHERE group_id = ?",
                (gid,),
            ).fetchone()
        if row is None:
            return None
        target = await resolve_group_lifecycle_target(row)
        if target is None:
            return None
        if is_group_entity(target):
            _activation_card_entity_cache[gid] = target
            return target
        try:
            entity = await asyncio.wait_for(client.get_entity(target), timeout=7)
        except Exception:
            return None
        if is_group_entity(entity):
            _activation_card_entity_cache[gid] = entity
            return entity
    except Exception as exc:
        log.debug("activation card group resolve skipped | group=%s | %s: %s", gid, type(exc).__name__, exc)
    return None


async def _process_activation_card_job(job: Dict[str, Any]) -> None:
    gid = int(job["group_id"])
    if gid in _activation_card_inflight:
        return
    _activation_card_inflight.add(gid)
    try:
        group = await _activation_card_resolve_group(gid)
        if group is None:
            raise RuntimeError("GROUP_ENTITY_UNRESOLVED")

        probe_sent = bool(int(job.get("probe_sent") or 0))
        if not probe_sent:
            send_confirmed = await probe_group_send_access(group, marker="👀")
            if not send_confirmed:
                raise RuntimeError("GROUP_SEND_ACCESS_NOT_CONFIRMED")
            await asyncio.to_thread(_activation_card_mark_probe_sent, gid)
            job["probe_sent"] = 1
            log.info("activation join probe sent | group=%s marker=eyes", gid)
            await asyncio.sleep(0.15)

        await send_default_join_message(
            group,
            int(job.get("owner_id") or 0),
            int(job.get("owner_access_hash") or 0),
            native_owner_id=int(job.get("native_owner_id") or 0),
            native_owner_available=bool(int(job.get("native_owner_available") or 0)),
            owner_mode=str(job.get("owner_mode") or "native"),
            probe_already_sent=True,
        )
        await asyncio.to_thread(_activation_card_complete, gid)
        _activation_card_entity_cache.pop(gid, None)
        log.info("activation card delivery PASS | group=%s attempts=%s", gid, int(job.get("attempt_count") or 0))
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        await asyncio.to_thread(
            _activation_card_defer,
            gid,
            int(job.get("attempt_count") or 0),
            exc,
        )
        log.warning(
            "activation card delivery deferred | group=%s attempt=%s | %s: %s",
            gid, int(job.get("attempt_count") or 0) + 1, type(exc).__name__, exc,
        )
    finally:
        _activation_card_inflight.discard(gid)


async def activation_card_delivery_worker(worker_id: int) -> None:
    while True:
        try:
            jobs = await asyncio.to_thread(_activation_card_jobs_due, ACTIVATION_CARD_BATCH_MAX)
            chosen: Optional[Dict[str, Any]] = None
            pending_pressure = _transport_pending_request_count(client)
            for job in jobs:
                if int(job["group_id"]) in _activation_card_inflight:
                    continue
                if int(job.get("attempt_count") or 0) > 0 and (
                    _routine_background_quiet_period_active() or _priority_traffic_is_hot() or pending_pressure >= FOREGROUND_BACKGROUND_PENDING_SOFT
                ):
                    continue
                chosen = job
                break
            if chosen is not None:
                await _process_activation_card_job(chosen)
                continue
            wake = _activation_card_wakeup
            if wake is None:
                await asyncio.sleep(1.0)
                continue
            try:
                await asyncio.wait_for(wake.wait(), timeout=2.0)
            except asyncio.TimeoutError:
                pass
            wake.clear()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("activation card delivery worker error | worker=%s", worker_id)
            await asyncio.sleep(2.0)


async def _post_activation_admin_sync_task(group: Any, group_id: int) -> None:
    global _activation_admin_sync_sem
    try:
        # The visible join card and realtime commands are more important than an
        # immediate second participant scan. Defer and bound this background RPC.
        await asyncio.sleep(8.0)
        await _yield_background_to_realtime(3.0)
        if _activation_admin_sync_sem is None:
            _activation_admin_sync_sem = asyncio.Semaphore(2)
        async with _activation_admin_sync_sem:
            await sync_native_group_admins(group, int(group_id), force=True)
    except Exception as exc:
        log.warning(
            "post-activation admin sync deferred | group=%s | %s: %s",
            int(group_id), type(exc).__name__, exc,
        )


async def try_auto_activate_pending_group(
    row: sqlite3.Row,
    group_override: Optional[Any] = None,
    trigger: str = "worker",
    deliver_card_inline: bool = False,
) -> bool:
    group_id = int(row["group_id"])
    installation = get_installation(group_id)
    if installation is not None:
        try:
            fresh_pending = get_pending_group_activation(group_id)
            if fresh_pending is not None:
                notice_complete = bool(int(fresh_pending["group_notice_sent"] or 0))
                card_state = await asyncio.to_thread(
                    _activation_card_ensure_job_from_installation,
                    group_id,
                    not notice_complete,
                )
                if card_state == "missing" or (card_state == "legacy" and not notice_complete):
                    return False
                if card_state == "queued":
                    card_ready = await _post_activation_card_task(
                        group_override,
                        group_id,
                        int(installation["owner_user_id"] or 0),
                        int(installation["owner_access_hash"] or 0),
                        int(installation["native_owner_user_id"] or 0),
                        bool(int(installation["native_owner_user_id"] or 0)),
                        str(installation["owner_mode"] or "native"),
                        probe_already_sent=True,
                        deliver_inline=bool(deliver_card_inline),
                        already_persisted=True,
                    )
                    if not card_ready:
                        return False
                if not notice_complete:
                    await asyncio.to_thread(_group_join_notice_complete, group_id)
                    fresh_pending = get_pending_group_activation(group_id)
            if fresh_pending is None or int(fresh_pending["join_notice_sent"] or 0) == 1:
                clear_pending_group_activation(group_id)
            else:
                log.info(
                    "pending activation retained for private ACK | group=%s",
                    group_id,
                )
            return True
        except Exception as exc:
            log.info(
                "installed activation card recovery deferred | group=%s trigger=%s | %s: %s",
                group_id, trigger, type(exc).__name__, exc,
            )
            return False
    if group_id in _pending_auto_activation_inflight:
        return False

    _pending_auto_activation_inflight.add(group_id)
    try:
        group = await resolve_pending_group_entity(
            row,
            group_override=group_override,
            allow_dialog_scan=(trigger != "fast-activation-worker"),
        )
        if group is None:
            log.info(
                "pending auto activation WAIT | group=%s trigger=%s reason=group_unresolved",
                group_id, trigger,
            )
            return False

        # The installation gate is write access only. Admin-role propagation is
        # not required for the join receipt or for local ZIVO registration.
        fresh_row = get_pending_group_activation(group_id)
        if fresh_row is None or int(fresh_row["group_notice_probe_sent"] or 0) != 1:
            log.info(
                "pending auto activation WAIT | group=%s trigger=%s reason=write_access_not_confirmed",
                group_id, trigger,
            )
            return False
        row = fresh_row

        owner_entity, owner_source, native_owner_entity, native_owner_available = await resolve_pending_activation_owner(group, row)
        owner_id = safe_int(getattr(owner_entity, "id", None)) if owner_entity is not None else None
        if owner_id is None or int(owner_id) <= 0:
            log.info(
                "pending auto activation WAIT | group=%s trigger=%s reason=owner_unresolved",
                group_id, trigger,
            )
            return False

        owner_username = getattr(owner_entity, "username", None) or ""
        owner_access_hash = safe_int(getattr(owner_entity, "access_hash", None)) or 0
        native_owner_id = safe_int(getattr(native_owner_entity, "id", None)) if native_owner_entity is not None else 0
        native_owner_username = (
            (getattr(native_owner_entity, "username", None) or "")
            if native_owner_entity is not None else ""
        )
        native_owner_access_hash = (
            (safe_int(getattr(native_owner_entity, "access_hash", None)) or 0)
            if native_owner_entity is not None else 0
        )
        owner_mode = "native" if owner_source == "native_creator" else "executive"
        group_title = str(getattr(group, "title", None) or row["group_title"] or "بدون نام")

        # Commit installation, notice completion and the card job atomically.
        # After this transaction either nothing exists or the ACTIVE card has a
        # restart-safe delivery record; there is no installed-without-card gap.
        installation = register_installation(
            group_id=group_id,
            group_title=group_title,
            owner_user_id=int(owner_id),
            owner_username=owner_username,
            owner_access_hash=int(owner_access_hash),
            invite_hash=str(row["invite_ref"] or ""),
            install_source=f"auto_access_ready:{owner_source}:{str(row['install_source'] or '')}",
            native_owner_user_id=int(native_owner_id or 0),
            native_owner_username=native_owner_username,
            native_owner_access_hash=int(native_owner_access_hash or 0),
            owner_mode=owner_mode,
            introduced_by_user_id=int(row["requester_user_id"] or 0),
            activation_card={
                "owner_id": int(owner_id),
                "owner_access_hash": int(owner_access_hash),
                "native_owner_id": int(native_owner_id or 0),
                "native_owner_available": bool(native_owner_available),
                "owner_mode": owner_mode,
                "probe_already_sent": True,
                "group_title": group_title,
                "peer_kind": "chat" if isinstance(group, types.Chat) else "channel",
                "group_access_hash": int(getattr(group, "access_hash", 0) or 0),
            },
        )
        mark_group_activated(group, group_id, group_title)
        try:
            multi_set_group_claim_status(
                MULTI_ACCOUNT_DB, group_id=int(group_id), account_key=ACCOUNT_KEY,
                status="active", group_title=group_title,
            )
        except Exception as exc:
            log.warning("shared group claim activate skipped | group=%s account=%s | %s: %s", group_id, ACCOUNT_KEY, type(exc).__name__, exc)
        card_ready = await _post_activation_card_task(
            group, group_id, int(owner_id), int(owner_access_hash),
            int(native_owner_id or 0), bool(native_owner_available), owner_mode,
            probe_already_sent=True,
            deliver_inline=bool(deliver_card_inline),
            already_persisted=True,
        )
        if not card_ready:
            return False
        asyncio.create_task(
            _post_activation_admin_sync_task(group, group_id),
            name=f"zivo-activation-admin-sync-{group_id}",
        )
        fresh_pending = get_pending_group_activation(group_id)
        if fresh_pending is None or int(fresh_pending["join_notice_sent"] or 0) == 1:
            clear_pending_group_activation(group_id)
        else:
            log.info(
                "pending activation installed but private ACK still queued | group=%s user=%s",
                group_id, int(fresh_pending["requester_user_id"] or 0),
            )
        log.info(
            "pending auto activation PASS | group=%s owner=%s trigger=%s activation_gate=write_confirmed",
            group_id, owner_id, trigger,
        )
        return installation is not None
    except Exception as exc:
        log.info(
            "pending auto activation deferred | group=%s trigger=%s | %s: %s",
            group_id, trigger, type(exc).__name__, exc,
        )
        return False
    finally:
        _pending_auto_activation_inflight.discard(group_id)


async def maybe_auto_activate_pending_from_event(event: Any) -> bool:
    if bool(getattr(event, "is_private", False)):
        return False
    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if group_id is None:
        return False
    if get_installation(group_id) is not None:
        return False
    pending = get_pending_group_activation(group_id)
    if pending is None:
        return False
    try:
        group = await event.get_chat()
    except Exception:
        return False
    if not is_group_entity(group):
        return False
    return await try_auto_activate_pending_group(
        pending, group_override=group, trigger="group-event"
    )


def mark_group_activated(group: Any, group_id: int, group_title: str = "") -> None:
    now = datetime.now(timezone.utc).isoformat()
    peer_kind = "chat" if isinstance(group, types.Chat) else "channel"
    group_access_hash = int(getattr(group, "access_hash", 0) or 0)
    with db_connect() as con:
        _group_lifecycle_upsert_in_connection(
            con, int(group_id), group_title or "", peer_kind,
            group_access_hash, now=now,
        )
        # Pending activation is intentionally retained until the private join
        # acknowledgement is confirmed. The lifecycle worker clears it after
        # join_notice_sent=1, so group readiness never depends on private ACK.
        con.commit()
    _group_activity_touch_cache[int(group_id)] = time.monotonic()


def _event_activity_datetime(event: Any) -> datetime:
    message = getattr(event, "message", None) or event
    value = getattr(message, "date", None)
    if isinstance(value, datetime):
        if value.tzinfo is None:
            value = value.replace(tzinfo=timezone.utc)
        value = value.astimezone(timezone.utc)
        now = datetime.now(timezone.utc)
        if value > now + timedelta(minutes=5):
            return now
        return value
    return datetime.now(timezone.utc)


async def touch_installed_group_activity(event: Any, installation: Optional[Any] = None) -> None:
    if bool(getattr(event, "is_private", False)):
        return
    sender_id = safe_int(getattr(event, "sender_id", None))
    if sender_id is not None and sender_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        return
    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if group_id is None:
        return
    if installation is None:
        installation = get_installation(group_id)
    if installation is None:
        return
    now_mono = time.monotonic()
    previous = _group_activity_touch_cache.get(int(group_id), 0.0)
    if now_mono - previous < GROUP_ACTIVITY_PERSIST_INTERVAL_SECONDS:
        return
    activity_at = _event_activity_datetime(event).isoformat()
    updated_at = datetime.now(timezone.utc).isoformat()
    group_title = str(installation["group_title"] or "") if "group_title" in installation.keys() else ""
    with db_connect() as con:
        row = con.execute(
            "SELECT peer_kind, group_access_hash FROM group_lifecycle WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()
        peer_kind = str(row["peer_kind"] or "channel") if row is not None else "channel"
        access_hash = int(row["group_access_hash"] or 0) if row is not None else 0
        con.execute(
            """
            INSERT INTO group_lifecycle (
                group_id, group_title, peer_kind, group_access_hash,
                activated_at, last_activity_at, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                last_activity_at = CASE
                    WHEN excluded.last_activity_at > group_lifecycle.last_activity_at
                    THEN excluded.last_activity_at ELSE group_lifecycle.last_activity_at END,
                updated_at = excluded.updated_at
            """,
            (int(group_id), group_title, peer_kind, access_hash,
             activity_at, activity_at, updated_at),
        )
        con.commit()
    _group_activity_touch_cache[int(group_id)] = now_mono


def pending_group_activation_rows_due() -> List[sqlite3.Row]:
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        return con.execute(
            """
            SELECT * FROM pending_group_activations
            WHERE activation_deadline <= ?
            ORDER BY activation_deadline ASC
            """,
            (now,),
        ).fetchall()


def inactive_group_lifecycle_rows_due() -> List[sqlite3.Row]:
    # Installed groups are durable by default.  The historical 2-day inactivity
    # auto-leave silently removed old groups and their local installation state.
    # Keep the capability opt-in via env, but never depart an installed group
    # unless an operator explicitly configured a positive threshold.
    if int(GROUP_INACTIVITY_LEAVE_SECONDS or 0) <= 0:
        return []
    cutoff = (datetime.now(timezone.utc) - timedelta(seconds=GROUP_INACTIVITY_LEAVE_SECONDS)).isoformat()
    with db_connect() as con:
        return con.execute(
            """
            SELECT gl.*
            FROM group_lifecycle gl
            INNER JOIN installations i ON i.group_id = gl.group_id
            WHERE gl.last_activity_at <= ?
            ORDER BY gl.last_activity_at ASC
            """,
            (cutoff,),
        ).fetchall()


def remove_installation_after_departure(group_id: int) -> None:
    try:
        multi_release_group_claim(MULTI_ACCOUNT_DB, group_id=int(group_id), account_key=ACCOUNT_KEY)
    except Exception as exc:
        log.warning("shared group claim release skipped | group=%s account=%s | %s: %s", group_id, ACCOUNT_KEY, type(exc).__name__, exc)
    with db_connect() as con:
        con.execute("DELETE FROM installations WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM pending_group_activations WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM activation_card_jobs WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM group_lifecycle WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM group_bot_power WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM bot_admins WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM bot_specials WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM bot_exemptions WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM special_lock_overrides WHERE group_id = ?", (int(group_id),))
        con.commit()
    _installation_hot_cache.pop(int(group_id), None)
    _group_activity_touch_cache.pop(int(group_id), None)
    _activation_card_entity_cache.pop(int(group_id), None)
    _pending_activation_fast_retry_after.pop(int(group_id), None)


async def resolve_group_lifecycle_target(row: sqlite3.Row) -> Optional[Any]:
    group_id = int(row["group_id"])
    peer_kind = str(row["peer_kind"] or "channel")
    access_hash = int(row["group_access_hash"] or 0)

    if peer_kind == "channel" and access_hash:
        try:
            return types.InputPeerChannel(group_id, access_hash)
        except Exception:
            pass
    if peer_kind == "chat":
        try:
            return types.InputPeerChat(group_id)
        except Exception:
            pass

    try:
        return await asyncio.wait_for(client.get_input_entity(group_id), timeout=6)
    except Exception:
        pass

    global _pending_dialog_cache_refreshed_at, _pending_dialog_entity_cache
    now_mono = time.monotonic()
    cached = _pending_dialog_entity_cache.get(group_id)
    if cached is not None:
        try:
            return utils.get_input_peer(cached)
        except Exception:
            return cached

    if (now_mono - _pending_dialog_cache_refreshed_at) >= PENDING_DIALOG_CACHE_TTL_SECONDS:
        try:
            dialogs = await asyncio.wait_for(client.get_dialogs(limit=200), timeout=10)
            fresh: Dict[int, Any] = {}
            for dialog in dialogs or []:
                entity = getattr(dialog, "entity", None)
                entity_id = safe_int(getattr(entity, "id", None))
                if entity_id is not None and is_group_entity(entity):
                    fresh[int(entity_id)] = entity
            _pending_dialog_entity_cache = fresh
            _pending_dialog_cache_refreshed_at = time.monotonic()
        except Exception as exc:
            _pending_dialog_cache_refreshed_at = time.monotonic()
            log.debug("lifecycle dialog cache refresh skipped | %s: %s", type(exc).__name__, exc)

    cached = _pending_dialog_entity_cache.get(group_id)
    if cached is not None:
        try:
            return utils.get_input_peer(cached)
        except Exception:
            return cached
    return None


async def leave_group_target(target: Any, group_id: int, peer_kind: str) -> bool:
    errors_seen: List[str] = []
    if peer_kind != "chat":
        try:
            channel = utils.get_input_channel(target)
            await asyncio.wait_for(
                client(functions.channels.LeaveChannelRequest(channel=channel)),
                timeout=15,
            )
            return True
        except Exception as exc:
            errors_seen.append(f"channel:{type(exc).__name__}:{exc}")

    try:
        await asyncio.wait_for(
            client(
                functions.messages.DeleteChatUserRequest(
                    chat_id=int(group_id),
                    user_id=types.InputUserSelf(),
                    revoke_history=False,
                )
            ),
            timeout=15,
        )
        return True
    except Exception as exc:
        errors_seen.append(f"chat:{type(exc).__name__}:{exc}")

    log.warning(
        "group lifecycle leave RPC failed | group=%s kind=%s errors=%s",
        group_id,
        peer_kind,
        " | ".join(errors_seen[-2:]),
    )
    return False


async def _lifecycle_goodbye_and_leave(row: sqlite3.Row, reason: str) -> bool:
    group_id = int(row["group_id"])
    peer_kind = str(row["peer_kind"] or "channel")
    target = await resolve_group_lifecycle_target(row)
    if target is None:
        log.warning("group lifecycle target unresolved | group=%s reason=%s", group_id, reason)
        return False

    if reason == "activation_timeout":
        goodbye = (
            "👋 خداحافظ\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "⏳ ۳ ساعت از عضویت زیوو گذشت و فعال سازی انجام نشد.\n"
            "زیوو از گروه خارج می شه.\n\n"
            "برای استفاده دوباره، لینک گروه رو در پیوی زیوو بفرست؛ بعد از آماده شدن دسترسی، زیوو خودش فعال می شه.\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "🤖 ZIVO | AUTO LEAVE"
        )
    else:
        goodbye = (
            "👋 خداحافظ\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "⏳ در ۲ روز گذشته فعالیتی از این گروه برای زیوو ثبت نشد.\n"
            "برای آزاد موندن ظرفیت، زیوو از گروه خارج می شه.\n\n"
            "هر وقت دوباره نیاز داشتی، لینک گروه رو در پیوی زیوو بفرست.\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "🤖 ZIVO | AUTO LEAVE"
        )

    try:
        await asyncio.wait_for(send_group_text(target, goodbye), timeout=12)
    except Exception as exc:
        log.warning(
            "group lifecycle goodbye send failed | group=%s reason=%s | %s: %s",
            group_id,
            reason,
            type(exc).__name__,
            exc,
        )
        if _is_group_inaccessible_error(exc):
            log.info(
                "group lifecycle inaccessible cleanup | group=%s reason=%s action=local-clear-no-extra-rpc",
                group_id, reason,
            )
            return True

    await asyncio.sleep(0.25)
    left = await leave_group_target(target, group_id, peer_kind)
    if left:
        log.info("group lifecycle leave PASS | group=%s reason=%s", group_id, reason)
    return left


async def process_group_lifecycle() -> None:
    # User traffic always has priority over maintenance RPCs.
    if _realtime_traffic_is_hot(1.0):
        return
    now_mono = time.monotonic()

    for row in pending_join_notice_rows():
        group_id = int(row["group_id"])
        requester_id = int(row["requester_user_id"] or 0)
        if requester_id <= 0:
            mark_pending_join_notice_sent(group_id)
            continue
        retry_key = ("pending_private_ack", group_id)
        if group_id in _pending_private_join_notice_inflight:
            continue
        if now_mono < _group_lifecycle_retry_after.get(retry_key, 0.0):
            continue
        try:
            private_target = await resolve_private_target(None, requester_id)
            if private_target is None:
                raise RuntimeError("PENDING_PRIVATE_TARGET_UNRESOLVED")
            retry_member_count: Optional[int] = None
            retry_title = str(row["group_title"] or "بدون نام")
            try:
                retry_group = await resolve_pending_group_entity(row)
                if retry_group is not None:
                    retry_meta = await get_group_metadata(retry_group)
                    retry_title = retry_meta.get("title") or retry_title
                    retry_member_count = retry_meta.get("member_count")
            except Exception as meta_exc:
                log.debug(
                    "pending group-info retry metadata skipped | group=%s | %s: %s",
                    group_id, type(meta_exc).__name__, meta_exc,
                )
            ack_text = pending_group_info_text(
                group_id=group_id,
                group_title=retry_title,
                member_count=retry_member_count,
                install_source=str(row["install_source"] or ""),
            )
            delivered = await safe_private_reply(None, private_target, ack_text, label="joined-pending-retry")
            if delivered:
                mark_pending_join_notice_sent(group_id)
                _group_lifecycle_retry_after.pop(retry_key, None)
                log.info("pending activation private ACK retry PASS | group=%s user=%s", group_id, requester_id)
            else:
                _group_lifecycle_retry_after[retry_key] = time.monotonic() + 30.0
        except Exception as exc:
            _group_lifecycle_retry_after[retry_key] = time.monotonic() + 30.0
            log.info(
                "pending activation private ACK retry deferred | group=%s user=%s | %s: %s",
                group_id, requester_id, type(exc).__name__, exc,
            )

    for row in pending_group_activation_rows_active():
        group_id = int(row["group_id"])
        if get_installation(group_id) is not None:
            fresh_pending = get_pending_group_activation(group_id)
            if fresh_pending is None or int(fresh_pending["join_notice_sent"] or 0) == 1:
                clear_pending_group_activation(group_id)
            continue
        retry_key = ("auto_activate", group_id)
        if now_mono < _group_lifecycle_retry_after.get(retry_key, 0.0):
            continue
        activated = await try_auto_activate_pending_group(row, trigger="lifecycle-worker")
        if activated:
            _group_lifecycle_retry_after.pop(retry_key, None)
            await asyncio.to_thread(_pending_activation_fast_clear_db, group_id)
        else:
            current_attempt = int(row["activation_attempt_count"] or 0) if "activation_attempt_count" in row.keys() else 0
            last_error = (
                str(row["activation_last_error"] or "") if "activation_last_error" in row.keys() else ""
            ) or (str(row["group_notice_last_error"] or "") if "group_notice_last_error" in row.keys() else "") or "GROUP_ENTITY_UNRESOLVED"
            _, delay = await asyncio.to_thread(
                _pending_activation_fast_defer_db, group_id, current_attempt, last_error
            )
            _group_lifecycle_retry_after[retry_key] = time.monotonic() + max(
                PENDING_AUTO_ACTIVATION_RETRY_SECONDS, float(delay)
            )

    for row in pending_group_activation_rows_due():
        group_id = int(row["group_id"])
        if get_installation(group_id) is not None:
            fresh_pending = get_pending_group_activation(group_id)
            if fresh_pending is None or int(fresh_pending["join_notice_sent"] or 0) == 1:
                clear_pending_group_activation(group_id)
            continue
        retry_key = ("pending", group_id)
        if now_mono < _group_lifecycle_retry_after.get(retry_key, 0.0):
            continue
        try:
            left = await _lifecycle_goodbye_and_leave(row, "activation_timeout")
            if left:
                clear_pending_group_activation(group_id)
            else:
                _group_lifecycle_retry_after[retry_key] = time.monotonic() + 900.0
        except Exception:
            _group_lifecycle_retry_after[retry_key] = time.monotonic() + 900.0
            log.exception("pending activation auto-leave failed | group=%s", group_id)

    for row in inactive_group_lifecycle_rows_due():
        group_id = int(row["group_id"])
        retry_key = ("inactive", group_id)
        if now_mono < _group_lifecycle_retry_after.get(retry_key, 0.0):
            continue
        try:
            try:
                export_group_snapshot(group_id, reason="auto-leave-inactive", actor_id=0)
            except Exception as exc:
                log.warning(
                    "pre-leave group snapshot failed | group=%s | %s: %s",
                    group_id,
                    type(exc).__name__,
                    exc,
                )
            left = await _lifecycle_goodbye_and_leave(row, "inactive_2d")
            if left:
                remove_installation_after_departure(group_id)
            else:
                _group_lifecycle_retry_after[retry_key] = time.monotonic() + 900.0
        except Exception:
            _group_lifecycle_retry_after[retry_key] = time.monotonic() + 900.0
            log.exception("inactive group auto-leave failed | group=%s", group_id)


async def group_lifecycle_worker() -> None:
    while True:
        try:
            await _yield_background_to_realtime(2.0)
            if _routine_background_quiet_period_active() or _priority_traffic_is_hot() or _transport_pending_request_count(client) >= FOREGROUND_BACKGROUND_PENDING_SOFT:
                await asyncio.sleep(GROUP_LIFECYCLE_WORKER_INTERVAL_SECONDS)
                continue
            await process_group_lifecycle()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("group lifecycle worker error")
        await asyncio.sleep(GROUP_LIFECYCLE_WORKER_INTERVAL_SECONDS)


async def pending_activation_fast_worker() -> None:
    """Low-pressure retry lane with restart-persistent backoff for pending group activation."""
    global _pending_activation_fast_cursor
    semaphore = asyncio.Semaphore(PENDING_ACTIVATION_FAST_CONCURRENCY)
    await asyncio.sleep(max(60.0, STARTUP_BACKGROUND_QUIET_SECONDS))
    while True:
        try:
            if _routine_background_quiet_period_active() or _priority_traffic_is_hot():
                await asyncio.sleep(PENDING_ACTIVATION_FAST_INTERVAL_SECONDS)
                continue
            pending_transport = _transport_pending_request_count(client)
            if pending_transport >= FOREGROUND_BACKGROUND_PENDING_SOFT:
                await asyncio.sleep(PENDING_ACTIVATION_FAST_INTERVAL_SECONDS)
                continue
            rows = await asyncio.to_thread(pending_group_activation_rows_active)
            if rows:
                total = len(rows)
                start_index = _pending_activation_fast_cursor % total
                ordered = [rows[(start_index + offset) % total] for offset in range(total)]
                selected: List[Any] = []
                for row in ordered:
                    gid = int(row["group_id"])
                    if get_installation(gid) is not None or gid in _pending_auto_activation_inflight:
                        continue
                    selected.append(row)
                    if len(selected) >= PENDING_ACTIVATION_FAST_BATCH:
                        break
                if selected:
                    _pending_activation_fast_cursor = (start_index + len(selected)) % max(1, total)

                    async def attempt(row: Any) -> None:
                        gid = int(row["group_id"])
                        async with semaphore:
                            ok = await try_auto_activate_pending_group(row, trigger="fast-activation-worker")
                        if ok:
                            await asyncio.to_thread(_pending_activation_fast_clear_db, gid)
                            _pending_activation_fast_retry_after.pop(gid, None)
                            _pending_activation_fast_failures.pop(gid, None)
                            return
                        err = str(row["activation_last_error"] or "GROUP_ENTITY_UNRESOLVED") if "activation_last_error" in row.keys() else "GROUP_ENTITY_UNRESOLVED"
                        current_attempt = int(row["activation_attempt_count"] or 0) if "activation_attempt_count" in row.keys() else 0
                        persisted_attempt, delay = await asyncio.to_thread(
                            _pending_activation_fast_defer_db, gid, current_attempt, err
                        )
                        if persisted_attempt in {1, 2, 4, 6, 8}:
                            log.info(
                                "pending activation persistent backoff | group=%s failures=%s retry_in=%ss",
                                gid, persisted_attempt, int(delay),
                            )

                    await asyncio.gather(*(attempt(row) for row in selected))
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("pending activation fast worker error")
        await asyncio.sleep(PENDING_ACTIVATION_FAST_INTERVAL_SECONDS)


def display_name(entity: Any) -> str:
    try:
        value = utils.get_display_name(entity)
        if value:
            return str(value)
    except Exception:
        pass

    for key in ("title", "first_name", "username"):
        value = getattr(entity, key, None)
        if value:
            return str(value)
    return "بدون نام"


def safe_int(value: Any) -> Optional[int]:
    try:
        return int(value)
    except Exception:
        return None


def is_group_entity(entity: Any) -> bool:
    if entity is None:
        return False
    if isinstance(entity, types.Chat):
        return True
    if isinstance(entity, types.Channel):
        return not bool(getattr(entity, "broadcast", False))
    if bool(getattr(entity, "broadcast", False)):
        return False
    if bool(getattr(entity, "megagroup", False)):
        return True
    return entity.__class__.__name__.lower() in {"chat", "channel"}


def event_is_private_inbound(
    event: Any,
) -> bool:
    try:
        if bool(
            getattr(
                event,
                "is_private",
                False,
            )
        ):
            return True
    except Exception:
        pass

    message = getattr(
        event,
        "message",
        None,
    ) or event

    peer = getattr(
        message,
        "peer_id",
        None,
    ) or getattr(
        event,
        "_chat_peer",
        None,
    )

    if isinstance(
        peer,
        types.PeerUser,
    ):
        return True

    input_chat = getattr(
        event,
        "input_chat",
        None,
    )

    if isinstance(
        input_chat,
        (
            types.InputPeerUser,
            types.InputPeerSelf,
        ),
    ):
        return True

    sender_id = safe_int(
        getattr(
            event,
            "sender_id",
            None,
        )
    )
    chat_id = safe_int(
        getattr(
            event,
            "chat_id",
            None,
        )
    )

    if (
        sender_id is not None
        and chat_id is not None
        and sender_id == chat_id
        and sender_id > 0
    ):
        return True

    return False


def private_sender_id_from_event(
    event: Any,
) -> Optional[int]:
    sender_id = safe_int(
        getattr(
            event,
            "sender_id",
            None,
        )
    )

    if sender_id is not None:
        return sender_id

    message = getattr(
        event,
        "message",
        None,
    ) or event

    from_id = getattr(
        message,
        "from_id",
        None,
    )

    if isinstance(
        from_id,
        types.PeerUser,
    ):
        return int(
            from_id.user_id
        )

    peer_id = getattr(
        message,
        "peer_id",
        None,
    )

    if isinstance(
        peer_id,
        types.PeerUser,
    ):
        return int(
            peer_id.user_id
        )

    chat_id = safe_int(
        getattr(
            event,
            "chat_id",
            None,
        )
    )

    if (
        chat_id is not None
        and chat_id > 0
    ):
        return chat_id

    return None


async def resolve_private_target(
    event: Optional[Any],
    sender_id: int,
) -> Optional[Any]:
    sender_id = int(sender_id)

    if event is not None:
        for attr in ("input_chat", "input_sender"):
            try:
                candidate = getattr(event, attr, None)
            except Exception:
                candidate = None
            if isinstance(candidate, types.InputPeerUser):
                _private_peer_cache[sender_id] = candidate
                return candidate
            if isinstance(candidate, types.InputPeerSelf):
                return candidate

    cached = _private_peer_cache.get(sender_id)
    if isinstance(cached, types.InputPeerUser):
        return cached

    if event is not None:
        for getter_name in ("get_input_sender", "get_input_chat"):
            getter = getattr(event, getter_name, None)
            if not callable(getter):
                continue
            try:
                candidate = await asyncio.wait_for(getter(), timeout=1.5)
                if isinstance(candidate, types.InputPeerUser):
                    _private_peer_cache[sender_id] = candidate
                    return candidate
                if isinstance(candidate, types.InputPeerSelf):
                    return candidate
            except Exception as exc:
                log.debug(
                    "private %s fallback failed | user=%s | %s: %s",
                    getter_name, sender_id, type(exc).__name__, exc,
                )

        if sender_id <= 0:
            return None
        direct = types.InputPeerUser(sender_id, 0)
        _private_peer_cache[sender_id] = direct
        return direct

    try:
        async for dialog in client.iter_dialogs(40):
            dialog_id = safe_int(getattr(dialog, "id", None))
            if dialog_id != sender_id:
                continue
            candidate = getattr(dialog, "input_entity", None)
            if isinstance(candidate, types.InputPeerUser):
                _private_peer_cache[sender_id] = candidate
                return candidate
    except Exception as exc:
        log.debug(
            "private dialog target lookup failed | user=%s | %s: %s",
            sender_id, type(exc).__name__, exc,
        )

    if sender_id <= 0:
        return None
    return types.InputPeerUser(sender_id, 0)


def cleanup_private_runtime_state(now: Optional[float] = None) -> None:
    global _private_state_cleanup_last
    current = float(now if now is not None else time.monotonic())
    if current - float(_private_state_cleanup_last) < 30.0:
        return
    _private_state_cleanup_last = current

    for key, seen_at in list(_private_message_seen.items()):
        if current - float(seen_at) > 120.0:
            _private_message_seen.pop(key, None)

    for uid, until in list(_private_rate_until.items()):
        if float(until or 0.0) <= current:
            _private_rate_until.pop(uid, None)

    for uid, times in list(_private_rate_times.items()):
        while times and current - float(times[0]) > PRIVATE_RATE_WINDOW_SECONDS:
            times.popleft()
        last_seen = float(_last_private_reply.get(int(uid), 0.0) or 0.0)
        if not times and (not last_seen or current - last_seen > PRIVATE_STATE_TTL_SECONDS):
            _private_rate_times.pop(uid, None)

    active_private_users = {int(uid) for uid, _mid in _private_live_inflight}
    active_private_users.update(int(uid) for uid, _mid in _private_raw_rescue_tasks.keys())
    active_private_users.update(int(uid) for uid, _mid in _private_link_tasks.keys())

    for uid, last_seen in list(_last_private_reply.items()):
        uid = int(uid)
        if current - float(last_seen) <= PRIVATE_STATE_TTL_SECONDS:
            continue
        if uid in active_private_users or uid in _private_contact_pending:
            continue
        lock = _user_locks.get(uid)
        if lock is not None and int(getattr(lock, "_value", 0)) != int(PRIVATE_USER_CONCURRENCY):
            continue
        _last_private_reply.pop(uid, None)
        _private_peer_cache.pop(uid, None)
        _private_rate_times.pop(uid, None)
        _private_rate_until.pop(uid, None)
        _private_watchdog_last_message.pop(uid, None)
        _user_locks.pop(uid, None)


def private_message_is_duplicate(
    sender_id: int,
    message_id: int,
) -> bool:
    now = time.monotonic()
    cleanup_private_runtime_state(now)
    key = (
        int(sender_id),
        int(message_id),
    )

    if key in _private_message_seen:
        return True

    _private_message_seen[key] = now
    return False


def private_rate_limited(user_id: int) -> bool:
    now = time.monotonic()
    user_id = int(user_id)
    until = float(_private_rate_until.get(user_id, 0.0) or 0.0)
    if until > now:
        return True
    if until:
        _private_rate_until.pop(user_id, None)

    times = _private_rate_times.setdefault(user_id, deque())
    while times and now - float(times[0]) > PRIVATE_RATE_WINDOW_SECONDS:
        times.popleft()
    times.append(now)

    if len(times) > PRIVATE_RATE_LIMIT:
        _private_rate_until[user_id] = now + PRIVATE_RATE_COOLDOWN_SECONDS
        times.clear()
        log.warning(
            "private temporary rate cooldown | user=%s seconds=%.1f limit=%s/%ss",
            user_id, PRIVATE_RATE_COOLDOWN_SECONDS, PRIVATE_RATE_LIMIT,
            int(PRIVATE_RATE_WINDOW_SECONDS),
        )
        return True
    return False


def raw_private_payload(
    update: Any,
) -> Optional[Tuple[int, int, str]]:
    if isinstance(
        update,
        types.UpdateShortMessage,
    ):
        if bool(
            getattr(
                update,
                "out",
                False,
            )
        ):
            return None

        user_id = safe_int(
            getattr(
                update,
                "user_id",
                None,
            )
        )
        message_id = safe_int(
            getattr(
                update,
                "id",
                None,
            )
        )

        if (
            user_id is None
            or message_id is None
        ):
            return None

        return (
            user_id,
            message_id,
            getattr(
                update,
                "message",
                None,
            )
            or "",
        )

    if isinstance(
        update,
        types.UpdateNewMessage,
    ):
        message = getattr(
            update,
            "message",
            None,
        )

        if (
            message is None
            or bool(
                getattr(
                    message,
                    "out",
                    False,
                )
            )
        ):
            return None

        peer_id = getattr(
            message,
            "peer_id",
            None,
        )

        if not isinstance(
            peer_id,
            types.PeerUser,
        ):
            return None

        from_id = getattr(
            message,
            "from_id",
            None,
        )

        if isinstance(
            from_id,
            types.PeerUser,
        ):
            user_id = int(
                from_id.user_id
            )
        else:
            user_id = int(
                peer_id.user_id
            )

        message_id = safe_int(
            getattr(
                message,
                "id",
                None,
            )
        )

        if message_id is None:
            return None

        return (
            user_id,
            message_id,
            getattr(
                message,
                "message",
                None,
            )
            or "",
        )

    return None


def raw_private_payloads(update: Any) -> List[Tuple[int, int, str]]:
    """Bounded shape-based extraction for private messages from Soroush wrappers."""
    payloads: List[Tuple[int, int, str]] = []
    seen_payloads: set[Tuple[int, int]] = set()
    seen_objects: set[int] = set()
    stack: List[Any] = [update]
    inspected = 0
    wrapper_attrs = (
        "update", "updates", "new_message", "new_messages", "message_update",
        "event", "events", "result", "body", "payload",
    )
    while stack and inspected < 64:
        current = stack.pop()
        if current is None or isinstance(current, (str, bytes, int, float, bool)):
            continue
        oid = id(current)
        if oid in seen_objects:
            continue
        seen_objects.add(oid)
        inspected += 1
        if isinstance(current, (list, tuple)):
            stack.extend(list(current)[:32])
            continue

        payload = raw_private_payload(current)
        if payload is not None:
            key = (int(payload[0]), int(payload[1]))
            if key not in seen_payloads:
                seen_payloads.add(key)
                payloads.append(payload)

        message = getattr(current, "message", None)
        if message is not None and not isinstance(message, (str, bytes)) and not bool(getattr(message, "out", False)):
            peer_id = getattr(message, "peer_id", None)
            from_id = getattr(message, "from_id", None)
            if isinstance(peer_id, types.PeerUser):
                user_id = safe_int(getattr(from_id, "user_id", None)) if isinstance(from_id, types.PeerUser) else safe_int(getattr(peer_id, "user_id", None))
                message_id = safe_int(getattr(message, "id", None))
                if user_id is not None and message_id is not None:
                    key = (int(user_id), int(message_id))
                    if key not in seen_payloads:
                        seen_payloads.add(key)
                        payloads.append((int(user_id), int(message_id), str(getattr(message, "message", None) or "")))

        for attr in wrapper_attrs:
            try:
                child = getattr(current, attr, None)
            except Exception:
                child = None
            if child is not None and child is not current:
                stack.append(child)
    return payloads


def _service_message_group_id(message: Any) -> Optional[int]:
    peer = getattr(message, "peer_id", None)
    if isinstance(peer, types.PeerChannel):
        return safe_int(getattr(peer, "channel_id", None))
    if isinstance(peer, types.PeerChat):
        return safe_int(getattr(peer, "chat_id", None))
    # Soroush wrapper compatibility without trusting PeerUser as a group.
    peer_name = type(peer).__name__.lower() if peer is not None else ""
    if "user" not in peer_name:
        for attr in ("channel_id", "chat_id", "group_id"):
            gid = safe_int(getattr(peer, attr, None)) if peer is not None else None
            if gid is not None and gid > 0:
                return int(gid)
    for attr in ("chat_id", "group_id", "channel_id"):
        gid = safe_int(getattr(message, attr, None))
        if gid is not None and gid > 0:
            return int(gid)
    return None


def raw_group_join_payloads(update: Any) -> List[Tuple[int, Any]]:
    """Extract join service messages from direct raw messages and wrapped updates."""
    payloads: List[Tuple[int, Any]] = []
    seen: set[Tuple[int, int]] = set()
    graph_fn = globals().get("_join_object_graph")
    if callable(graph_fn):
        objects = graph_fn(update)
    else:
        objects = [update]
        child = getattr(update, "message", None)
        if child is not None and not isinstance(child, (str, bytes, bytearray, int, float, bool)):
            objects.append(child)
    for current in objects:
        candidates: List[Any] = [current]
        child = getattr(current, "message", None)
        if child is not None and not isinstance(child, (str, bytes, bytearray, int, float, bool)):
            candidates.append(child)
        for message in candidates:
            if getattr(message, "action", None) is None:
                continue
            mid = safe_int(getattr(message, "id", None))
            gid_fn = globals().get("_service_message_group_id")
            if callable(gid_fn):
                gid = gid_fn(message)
            else:
                peer = getattr(message, "peer_id", None)
                gid = None
                if isinstance(peer, types.PeerChannel):
                    gid = safe_int(getattr(peer, "channel_id", None))
                elif isinstance(peer, types.PeerChat):
                    gid = safe_int(getattr(peer, "chat_id", None))
            if mid is None or gid is None:
                continue
            proxy = SimpleNamespace(
                message=message,
                sender_id=(
                    safe_int(getattr(message, "sender_id", None))
                    or safe_int(getattr(getattr(message, "from_id", None), "user_id", None))
                ),
            )
            if not _joined_user_ids_from_event(proxy):
                continue
            key = (int(gid), int(mid))
            if key in seen:
                continue
            seen.add(key)
            payloads.append((int(gid), message))
    return payloads


async def _raw_group_join_welcome_rescue(group_id: int, message: Any) -> None:
    peer = getattr(message, "peer_id", None)
    group: Any = None
    try:
        group = await asyncio.wait_for(
            client.get_entity(peer if peer is not None else int(group_id)),
            timeout=2.5,
        )
    except Exception as exc:
        # Do not kill welcome just because entity resolution is unavailable.
        group = peer if peer is not None else int(group_id)
        log.info("raw welcome group resolve fallback | group=%s | %s: %s", group_id, type(exc).__name__, exc)

    class _RawJoinEvent:
        is_private = False
        def __init__(self, raw_message: Any, chat: Any, gid: int) -> None:
            self.message = raw_message
            self.id = safe_int(getattr(raw_message, "id", None)) or 0
            self.chat_id = int(gid)
            self.sender_id = (
                safe_int(getattr(raw_message, "sender_id", None))
                or safe_int(getattr(getattr(raw_message, "from_id", None), "user_id", None))
            )
            self.sender = None
            self._chat = chat
            self.input_chat = chat
            self._entities = getattr(raw_message, "_entities", None)
        async def get_chat(self) -> Any:
            if self._chat is None:
                raise RuntimeError("RAW_GROUP_ENTITY_UNAVAILABLE")
            return self._chat

    event = _RawJoinEvent(message, group, int(group_id))
    if await maybe_handle_group_join_welcome(event, hinted_group_id=int(group_id), hinted_group=group):
        _perf_counters["welcome_raw_rescue"] += 1
        log.info("raw welcome rescue handled | group=%s message=%s", group_id, event.id)


def get_group_rules_settings(group_id: int) -> Dict[str, Any]:
    with db_connect() as con:
        row = con.execute(
            "SELECT * FROM group_rules_settings WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()
    if row is None:
        return {
            "rules_text": "",
            "show_in_welcome": True,
        }
    return {
        "rules_text": str(row["rules_text"] or ""),
        "show_in_welcome": bool(int(row["show_in_welcome"] or 0)),
    }


def upsert_group_rules_settings(
    group_id: int,
    actor_id: int,
    *,
    rules_text: Optional[str] = None,
    show_in_welcome: Optional[bool] = None,
) -> Dict[str, Any]:
    current = get_group_rules_settings(group_id)
    if rules_text is not None:
        current["rules_text"] = str(rules_text)
    if show_in_welcome is not None:
        current["show_in_welcome"] = bool(show_in_welcome)
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO group_rules_settings (
                group_id, rules_text, show_in_welcome, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                rules_text = excluded.rules_text,
                show_in_welcome = excluded.show_in_welcome,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id), current["rules_text"],
                1 if current["show_in_welcome"] else 0,
                int(actor_id or 0), now,
            ),
        )
        con.commit()
    mark_group_backup_dirty(group_id)
    return get_group_rules_settings(group_id)


