async def send_rules_message(
    group: Any,
    group_id: int,
    *,
    cleanup_category: str = "general",
    reply_to: Optional[int] = None,
) -> Any:
    text = rules_message_text(group_id)
    kwargs: Dict[str, Any] = {
        "parse_mode": None,
        "formatting_entities": [],
        "link_preview": False,
    }
    if reply_to:
        kwargs["reply_to"] = int(reply_to)
    sent = await client.send_message(
        group,
        text,
        **kwargs,
    )
    schedule_bot_message_cleanup(group, sent, cleanup_category)
    return sent


async def command_rules(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    action = parsed.get("action")
    if action == "show":
        await send_rules_message(group, group_id, cleanup_category="general")
        return

    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    role = base_bot_role(group_id, actor_id)
    if role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ تنظیم قوانین فقط برای مالک و ادمین زیوو فعاله.")
        return

    if action == "status":
        settings = get_group_rules_settings(group_id)
        await send_group_text(
            group,
            "📜 ZIVO | وضعیت قوانین\n━━━━━━━━━━━━━━━━━━\n"
            f"📝 متن قوانین: {'تنظیم شده' if settings['rules_text'] else 'تنظیم نشده'}\n"
            f"👋 نمایش زیر خوشامد: {'فعال' if settings['show_in_welcome'] else 'خاموش'}\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "📚 راهنما قوانین",
        )
        return

    if action == "welcome_on":
        upsert_group_rules_settings(group_id, actor_id, show_in_welcome=True)
        await send_group_text(group, "✅ قوانین زیر پیام خوشامد اعضای جدید نمایش داده می‌شه.")
        return

    if action == "welcome_off":
        upsert_group_rules_settings(group_id, actor_id, show_in_welcome=False)
        await send_group_text(group, "🔕 نمایش قوانین زیر خوشامد خاموش شد؛ کاربران همچنان با «قانون» یا «قوانین» می‌تونن متن رو ببینن.")
        return

    if action == "delete":
        upsert_group_rules_settings(group_id, actor_id, rules_text="")
        await send_group_text(group, "✅ متن قوانین گروه حذف شد.")
        return

    if action == "set":
        if not bool(getattr(event, "is_reply", False)):
            await send_group_text(group, "↩️ روی متن قوانین ریپلای کن و بنویس: تنظیم قوانین")
            return
        reply = await event.get_reply_message()
        raw = (
            getattr(reply, "raw_text", None)
            or getattr(reply, "message", None)
            or ""
        ).strip() if reply is not None else ""
        if not raw:
            await send_group_text(group, "❌ پیام ریپلای‌شده متن قابل ذخیره نداره.")
            return
        if len(raw) > 2800:
            await send_group_text(group, "❌ متن قوانین حداکثر 2800 نویسه می‌تونه باشه.")
            return
        settings = upsert_group_rules_settings(group_id, actor_id, rules_text=raw)
        await send_group_text(
            group,
            "✅ قوانین گروه ذخیره شد.\n"
            f"👋 نمایش زیر خوشامد: {'فعال' if settings['show_in_welcome'] else 'خاموش'}\n"
            "👥 کاربران با نوشتن «قانون» یا «قوانین» هم می‌تونن اون رو ببینن.",
        )
        return


