def upsert_welcome_settings(
    group_id: int,
    actor_id: int,
    *,
    enabled: Optional[bool] = None,
    custom_text: Optional[str] = None,
    gif_source_message_id: Optional[int] = None,
    gif_local_path: Optional[str] = None,
    gif_fingerprint: Optional[str] = None,
) -> Dict[str, Any]:
    current = get_welcome_settings(group_id)
    if enabled is not None:
        current["enabled"] = bool(enabled)
    if custom_text is not None:
        current["custom_text"] = str(custom_text)
    if gif_source_message_id is not None:
        current["gif_source_message_id"] = int(gif_source_message_id or 0)
    if gif_local_path is not None:
        current["gif_local_path"] = str(gif_local_path or "")
    if gif_fingerprint is not None:
        current["gif_fingerprint"] = str(gif_fingerprint or "")
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO welcome_settings (
                group_id, enabled, custom_text, gif_source_message_id,
                gif_local_path, gif_fingerprint, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                enabled = excluded.enabled,
                custom_text = excluded.custom_text,
                gif_source_message_id = excluded.gif_source_message_id,
                gif_local_path = excluded.gif_local_path,
                gif_fingerprint = excluded.gif_fingerprint,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id), 1 if current["enabled"] else 0,
                current["custom_text"], int(current["gif_source_message_id"]),
                current["gif_local_path"], current["gif_fingerprint"],
                int(actor_id or 0), now,
            ),
        )
        con.commit()
    mark_group_backup_dirty(group_id)
    return get_welcome_settings(group_id)


