def render_welcome_text(template: str, values: Dict[str, str]) -> str:
    result = template or default_group_welcome_template()
    aliases = {
        "{نام}": values.get("name", "کاربر جدید"),
        "{آیدی}": values.get("username", "ندارد"),
        "{آیدی_عددی}": values.get("user_id", "نامعلوم"),
        "{بیو}": values.get("bio", "دریافت نشد"),
        "{گروه}": values.get("group", "گروه"),
        "{ساعت}": values.get("time", "--:--"),
        "{تاریخ}": values.get("date", "نامعلوم"),
        "{نمایه}": values.get("profile", "﹝مشاهده نمایه﹞"),
        "{name}": values.get("name", "کاربر جدید"),
        "{username}": values.get("username", "ندارد"),
        "{user_id}": values.get("user_id", "نامعلوم"),
        "{bio}": values.get("bio", "دریافت نشد"),
        "{group}": values.get("group", "گروه"),
        "{time}": values.get("time", "--:--"),
        "{date}": values.get("date", "نامعلوم"),
        "{profile}": values.get("profile", "﹝مشاهده نمایه﹞"),
    }
    for key, value in aliases.items():
        result = result.replace(key, str(value))
    return result[:3900]


def record_welcome_join(
    group_id: int,
    user_id: int,
    profile: Dict[str, Any],
    service_message_id: int,
    joined_at: datetime,
) -> None:
    with db_connect() as con:
        con.execute(
            """
            INSERT OR IGNORE INTO welcome_join_history (
                group_id, user_id, access_hash, username, display_name, bio,
                service_message_id, joined_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(group_id), int(user_id), int(profile.get("access_hash") or 0),
                str(profile.get("username") or ""), str(profile.get("name") or "کاربر جدید"),
                str(profile.get("bio") or ""), int(service_message_id or 0),
                joined_at.astimezone(timezone.utc).isoformat(),
            ),
        )
        con.execute(
            "DELETE FROM welcome_join_history WHERE group_id = ? AND entry_id NOT IN "
            "(SELECT entry_id FROM welcome_join_history WHERE group_id = ? ORDER BY entry_id DESC LIMIT 500)",
            (int(group_id), int(group_id)),
        )
        con.commit()
    mark_group_backup_dirty(group_id)


def recent_welcome_joins(group_id: int, limit: int = 10) -> List[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            "SELECT * FROM welcome_join_history WHERE group_id = ? ORDER BY entry_id DESC LIMIT ?",
            (int(group_id), max(1, min(50, int(limit)))),
        ).fetchall()


async def send_recent_welcome_joins(group: Any, group_id: int, limit: int = 10) -> None:
    rows = recent_welcome_joins(group_id, limit)
    if not rows:
        await send_group_text(group, "📭 هنوز ورودی جدیدی برای این گروه ثبت نشده.")
        return
    lines = ["👥 ZIVO | ورودی‌های اخیر", "━━━━━━━━━━━━━━━━━━"]
    mentions: List[Tuple[str, int, int]] = []
    for index, row in enumerate(rows, 1):
        label = f"﹝نمایه {index}﹞"
        username = ("@" + str(row["username"])) if row["username"] else "بدون آیدی"
        joined_raw = parse_iso_datetime(row["joined_at"])
        joined_text = iran_datetime(joined_raw).strftime("%m/%d %H:%M") if joined_raw else "نامعلوم"
        name = str(row["display_name"] or "کاربر")
        lines.append(f"{index}) {name} | {username} | {joined_text} | {label}")
        mentions.append((label, int(row["user_id"]), int(row["access_hash"] or 0)))
    lines.extend(("━━━━━━━━━━━━━━━━━━", "⚡ ZIVO | JOIN LOG"))
    await send_group_text_with_mentions(group, "\n".join(lines), mentions)


def _welcome_event_already_sent(group_id: int, message_id: int, user_id: int) -> bool:
    with db_connect() as con:
        row = con.execute(
            "SELECT 1 FROM welcome_sent_events WHERE group_id = ? AND service_message_id = ? AND user_id = ?",
            (int(group_id), int(message_id), int(user_id)),
        ).fetchone()
    return row is not None


def _mark_welcome_event_sent(group_id: int, message_id: int, user_id: int) -> None:
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            "INSERT OR IGNORE INTO welcome_sent_events (group_id, service_message_id, user_id, sent_at) VALUES (?, ?, ?, ?)",
            (int(group_id), int(message_id), int(user_id), now),
        )
        con.execute(
            "DELETE FROM welcome_sent_events WHERE group_id = ? AND sent_at < ?",
            (int(group_id), (datetime.now(timezone.utc) - timedelta(days=30)).isoformat()),
        )
        con.commit()



def _speaker_invalidate(group_id: int) -> None:
    gid = int(group_id)
    _speaker_settings_hot.pop(gid, None)
    _speaker_ai_settings_hot.pop(gid, None)
    _speaker_triggers_hot.pop(gid, None)
    for key in [key for key in _speaker_defaults_hot if key[0] == gid]:
        _speaker_defaults_hot.pop(key, None)


def get_speaker_settings(group_id: int) -> Dict[str, Any]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _speaker_settings_hot.get(gid)
    if cached is not None and now - cached[0] < SPEAKER_CACHE_TTL:
        return dict(cached[1])
    with db_connect() as con:
        row = con.execute(
            "SELECT enabled, mode, updated_by, updated_at FROM speaker_settings WHERE group_id = ?",
            (gid,),
        ).fetchone()
    settings = {
        "enabled": bool(int(row["enabled"] or 0)) if row is not None else False,
        "mode": str(row["mode"] or "normal") if row is not None else "normal",
        "updated_by": int(row["updated_by"] or 0) if row is not None else 0,
        "updated_at": str(row["updated_at"] or "") if row is not None else "",
    }
    if settings["mode"] not in SPEAKER_MODE_LABELS:
        settings["mode"] = "normal"
    _speaker_settings_hot[gid] = (now, dict(settings))
    return settings


def upsert_speaker_settings(group_id: int, actor_id: int, *, enabled: Optional[bool] = None, mode: Optional[str] = None) -> Dict[str, Any]:
    current = get_speaker_settings(group_id)
    next_enabled = current["enabled"] if enabled is None else bool(enabled)
    next_mode = current["mode"] if not mode else str(mode)
    if next_mode not in SPEAKER_MODE_LABELS:
        next_mode = "normal"
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO speaker_settings (group_id, enabled, mode, updated_by, updated_at)
            VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                enabled = excluded.enabled,
                mode = excluded.mode,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (int(group_id), 1 if next_enabled else 0, next_mode, int(actor_id), now),
        )
        con.commit()
    _speaker_settings_hot.pop(int(group_id), None)
    mark_group_backup_dirty(int(group_id))
    return get_speaker_settings(group_id)


def get_tts_voice_settings(group_id: int) -> Dict[str, Any]:
    gid = int(group_id)
    now_mono = time.monotonic()
    cached = _tts_voice_settings_hot.get(gid)
    if cached is not None and now_mono - cached[0] < SPEAKER_CACHE_TTL:
        return dict(cached[1])
    with db_connect() as con:
        row = con.execute(
            "SELECT gender, style, speed, updated_by, updated_at "
            "FROM tts_voice_settings WHERE group_id = ?",
            (gid,),
        ).fetchone()
    profile = {
        "gender": str(row["gender"] or "auto") if row is not None else "auto",
        "style": str(row["style"] or "normal") if row is not None else "normal",
        "speed": str(row["speed"] or "normal") if row is not None else "normal",
        "updated_by": int(row["updated_by"] or 0) if row is not None else 0,
        "updated_at": str(row["updated_at"] or "") if row is not None else "",
    }
    if profile["gender"] not in {"auto", "female", "male"}:
        profile["gender"] = "auto"
    if profile["style"] not in {"normal", "calm", "energetic", "formal"}:
        profile["style"] = "normal"
    if profile["speed"] not in {"slow", "normal", "fast"}:
        profile["speed"] = "normal"
    _tts_voice_settings_hot[gid] = (now_mono, dict(profile))
    return profile


def upsert_tts_voice_settings(
    group_id: int,
    actor_id: int,
    *,
    gender: Optional[str] = None,
    style: Optional[str] = None,
    speed: Optional[str] = None,
) -> Dict[str, Any]:
    next_gender = str(gender) if gender is not None and str(gender) in {"auto", "female", "male"} else None
    next_style = str(style) if style is not None and str(style) in {"normal", "calm", "energetic", "formal"} else None
    next_speed = str(speed) if speed is not None and str(speed) in {"slow", "normal", "fast"} else None
    now_iso = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO tts_voice_settings
                (group_id, gender, style, speed, updated_by, updated_at)
            VALUES (?, COALESCE(?, 'auto'), COALESCE(?, 'normal'), COALESCE(?, 'normal'), ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                gender = COALESCE(?, tts_voice_settings.gender),
                style = COALESCE(?, tts_voice_settings.style),
                speed = COALESCE(?, tts_voice_settings.speed),
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                int(group_id), next_gender, next_style, next_speed, int(actor_id), now_iso,
                next_gender, next_style, next_speed,
            ),
        )
        con.commit()
    _tts_voice_settings_hot.pop(int(group_id), None)
    mark_group_backup_dirty(int(group_id))
    return get_tts_voice_settings(group_id)


def reset_tts_voice_settings(group_id: int) -> Dict[str, Any]:
    with db_connect() as con:
        con.execute("DELETE FROM tts_voice_settings WHERE group_id = ?", (int(group_id),))
        con.commit()
    _tts_voice_settings_hot.pop(int(group_id), None)
    mark_group_backup_dirty(int(group_id))
    return get_tts_voice_settings(group_id)


def get_speaker_ai_enabled(group_id: int) -> bool:
    gid = int(group_id)
    now_mono = time.monotonic()
    cached = _speaker_ai_settings_hot.get(gid)
    if cached is not None and now_mono - cached[0] < SPEAKER_CACHE_TTL:
        return bool(cached[1])
    with db_connect() as con:
        row = con.execute(
            "SELECT enabled FROM speaker_ai_settings WHERE group_id = ?",
            (gid,),
        ).fetchone()
    enabled = bool(int(row["enabled"] or 0)) if row is not None else False
    _speaker_ai_settings_hot[gid] = (now_mono, enabled)
    return enabled


def set_speaker_ai_enabled(group_id: int, actor_id: int, enabled: bool) -> bool:
    now_iso = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO speaker_ai_settings (group_id, enabled, updated_by, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                enabled = excluded.enabled,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (int(group_id), 1 if enabled else 0, int(actor_id), now_iso),
        )
        con.commit()
    _speaker_ai_settings_hot.pop(int(group_id), None)
    mark_group_backup_dirty(int(group_id))
    return bool(enabled)


def speaker_triggers(group_id: int) -> Tuple[Tuple[str, str], ...]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _speaker_triggers_hot.get(gid)
    if cached is not None and now - cached[0] < SPEAKER_CACHE_TTL:
        return cached[1]
    with db_connect() as con:
        rows = con.execute(
            "SELECT trigger_norm, response_text FROM speaker_triggers WHERE group_id = ? ORDER BY LENGTH(trigger_norm) DESC, trigger_norm ASC",
            (gid,),
        ).fetchall()
    result = tuple((str(row["trigger_norm"] or ""), str(row["response_text"] or "")) for row in rows if str(row["trigger_norm"] or ""))
    _speaker_triggers_hot[gid] = (now, result)
    return result


def speaker_trigger_rows(group_id: int) -> List[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            "SELECT trigger_display, response_text FROM speaker_triggers WHERE group_id = ? ORDER BY updated_at DESC, trigger_norm ASC",
            (int(group_id),),
        ).fetchall()


