def _compile_content_profanity_pattern(term: str) -> re.Pattern[str]:
    compact = re.sub(r"[\s\u200c\u200d\u0640]+", "", str(term or "").lower())
    # Allow whitespace, punctuation, emoji, zero-width marks and tatweel between
    # characters. Repeated characters are accepted so stretched profanity is
    # caught. A small ASCII leetspeak map catches k0s / b1tch / s3x-style
    # bypasses without turning the whole message into a lossy transliteration.
    separator = r"(?:[\W_]|[\u200c\u200d\u0640])*"
    leet = {
        "a": r"[a@4]",
        "e": r"[e3]",
        "i": r"[i1!|]",
        "o": r"[o0]",
        "s": r"[s5$]",
        "t": r"[t7]",
    }
    pieces = []
    for ch in compact:
        atom = leet.get(ch, re.escape(ch))
        pieces.append(f"(?:{atom})+")
    body = separator.join(pieces)
    # Unicode boundaries keep short terms from matching inside ordinary words;
    # e.g. «کون» must not match «تکون» or «کونیاک».
    return re.compile(rf"(?<!\w){body}(?!\w)", re.IGNORECASE)


CONTENT_PROFANITY_PATTERNS: Tuple[re.Pattern[str], ...] = tuple(
    _compile_content_profanity_pattern(term) for term in CONTENT_PROFANITY_TERMS
)


def content_has_profanity(value: str) -> bool:
    normalized = normalize_group_command(str(value or "")).lower()
    if not normalized:
        return False
    normalized = normalized.replace("ـ", "").replace("ى", "ی").replace("ة", "ه").replace("ۀ", "ه")
    normalized = re.sub(r"[\u064b-\u065f\u0670\u06d6-\u06ed]", "", normalized)
    # A single cached alternation is materially faster than hundreds of Python
    # re.search calls per message while preserving CONTENT_PROFANITY_PATTERNS
    # for regression compatibility and inspection.
    combined = getattr(content_has_profanity, "_combined_pattern", None)
    if combined is None:
        combined = re.compile(
            "|".join(f"(?:{pattern.pattern})" for pattern in CONTENT_PROFANITY_PATTERNS),
            re.IGNORECASE,
        )
        setattr(content_has_profanity, "_combined_pattern", combined)
    return bool(combined.search(normalized))


def speaker_learning_has_profanity(value: str) -> bool:
    # Reuse the same detector as the group profanity lock so teaching and
    # moderation cannot drift into two conflicting profanity systems.
    return content_has_profanity(value)


def upsert_speaker_trigger(group_id: int, actor_id: int, trigger: str, response: str) -> Tuple[bool, int]:
    trigger_display = " ".join(str(trigger or "").split())[:80]
    trigger_norm = normalize_speaker_text(trigger_display)
    response_text = str(response or "").strip()[:1200]
    if len(trigger_norm) < 1 or not response_text:
        raise ValueError("SPEAKER_TRIGGER_EMPTY")
    if speaker_learning_has_profanity(trigger_display) or speaker_learning_has_profanity(response_text):
        raise ValueError("SPEAKER_PROFANITY_BLOCKED")
    with db_connect() as con:
        count = int(con.execute("SELECT COUNT(*) FROM speaker_triggers WHERE group_id = ?", (int(group_id),)).fetchone()[0])
        existed = con.execute(
            "SELECT 1 FROM speaker_triggers WHERE group_id = ? AND trigger_norm = ?",
            (int(group_id), trigger_norm),
        ).fetchone() is not None
        if not existed and count >= SPEAKER_MAX_TRIGGERS:
            raise RuntimeError("SPEAKER_TRIGGER_LIMIT")
        con.execute(
            """
            INSERT INTO speaker_triggers (group_id, trigger_norm, trigger_display, response_text, updated_by, updated_at)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id, trigger_norm) DO UPDATE SET
                trigger_display = excluded.trigger_display,
                response_text = excluded.response_text,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (int(group_id), trigger_norm, trigger_display, response_text, int(actor_id), datetime.now(timezone.utc).isoformat()),
        )
        con.commit()
    _speaker_triggers_hot.pop(int(group_id), None)
    mark_group_backup_dirty(int(group_id))
    return existed, count if existed else count + 1


def delete_speaker_trigger(group_id: int, trigger: str) -> bool:
    trigger_norm = normalize_speaker_text(trigger)
    with db_connect() as con:
        cur = con.execute(
            "DELETE FROM speaker_triggers WHERE group_id = ? AND trigger_norm = ?",
            (int(group_id), trigger_norm),
        )
        con.commit()
    _speaker_triggers_hot.pop(int(group_id), None)
    if cur.rowcount:
        mark_group_backup_dirty(int(group_id))
    return bool(cur.rowcount)


def speaker_default_overrides(group_id: int, mode: str) -> Dict[str, str]:
    key = (int(group_id), str(mode))
    now = time.monotonic()
    cached = _speaker_defaults_hot.get(key)
    if cached is not None and now - cached[0] < SPEAKER_CACHE_TTL:
        return dict(cached[1])
    with db_connect() as con:
        rows = con.execute(
            "SELECT event_key, response_text FROM speaker_default_overrides WHERE group_id = ? AND mode = ?",
            (int(group_id), str(mode)),
        ).fetchall()
    result = {str(row["event_key"]): str(row["response_text"] or "") for row in rows}
    _speaker_defaults_hot[key] = (now, dict(result))
    return result


def set_speaker_default_override(group_id: int, actor_id: int, mode: str, event_key: str, response: str) -> None:
    if mode not in SPEAKER_MODE_LABELS or event_key not in SPEAKER_EVENT_LABELS:
        raise ValueError("SPEAKER_DEFAULT_INVALID")
    response_text = str(response or "").strip()[:1200]
    if not response_text:
        raise ValueError("SPEAKER_DEFAULT_EMPTY")
    if speaker_learning_has_profanity(response_text):
        raise ValueError("SPEAKER_PROFANITY_BLOCKED")
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO speaker_default_overrides (group_id, mode, event_key, response_text, updated_by, updated_at)
            VALUES (?, ?, ?, ?, ?, ?)
            ON CONFLICT(group_id, mode, event_key) DO UPDATE SET
                response_text = excluded.response_text,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (int(group_id), str(mode), str(event_key), response_text, int(actor_id), datetime.now(timezone.utc).isoformat()),
        )
        con.commit()
    _speaker_defaults_hot.pop((int(group_id), str(mode)), None)
    mark_group_backup_dirty(int(group_id))


def reset_speaker_default_override(group_id: int, mode: str, event_key: str) -> int:
    with db_connect() as con:
        if event_key == "*":
            if mode:
                cur = con.execute(
                    "DELETE FROM speaker_default_overrides WHERE group_id = ? AND mode = ?",
                    (int(group_id), str(mode)),
                )
            else:
                cur = con.execute(
                    "DELETE FROM speaker_default_overrides WHERE group_id = ?",
                    (int(group_id),),
                )
        elif mode:
            cur = con.execute(
                "DELETE FROM speaker_default_overrides WHERE group_id = ? AND mode = ? AND event_key = ?",
                (int(group_id), str(mode), str(event_key)),
            )
        else:
            cur = con.execute(
                "DELETE FROM speaker_default_overrides WHERE group_id = ? AND event_key = ?",
                (int(group_id), str(event_key)),
            )
        con.commit()
    _speaker_invalidate(int(group_id))
    if cur.rowcount:
        mark_group_backup_dirty(int(group_id))
    return int(cur.rowcount or 0)


def _speaker_user_name(event: Any, group_id: int, user_id: int) -> str:
    message = getattr(event, "message", None) or event
    sender = getattr(message, "sender", None) or getattr(event, "sender", None)
    if sender is not None:
        clean = " ".join(str(display_name(sender) or "").split())
        if clean:
            return clean[:32]
        username = " ".join(str(getattr(sender, "username", None) or "").split())
        if username:
            return username[:32]
    try:
        with db_connect() as con:
            row = con.execute(
                "SELECT display_name, username FROM welcome_join_history WHERE group_id = ? AND user_id = ? ORDER BY entry_id DESC LIMIT 1",
                (int(group_id), int(user_id)),
            ).fetchone()
        if row is not None:
            clean = " ".join(str(row["display_name"] or row["username"] or "").split())
            if clean:
                return clean[:32]
    except Exception:
        pass
    try:
        row = stats_member_row(int(group_id), int(user_id))
        if row is not None:
            clean = " ".join(str(row["username"] or "").split())
            if clean:
                return clean[:32]
    except Exception:
        pass
    return "رفیق"


def _speaker_group_title(event: Any, group_id: int) -> str:
    chat = getattr(event, "chat", None)
    title = " ".join(str(getattr(chat, "title", None) or "").split())
    if title:
        return title[:80]
    try:
        row = get_installation(int(group_id))
        if row is not None:
            title = " ".join(str(row["group_title"] or "").split())
            if title:
                return title[:80]
    except Exception:
        pass
    return "گروه"


def _speaker_touch_affinity(group_id: int, user_id: int, amount: int = 1) -> int:
    key = (int(group_id), int(user_id))
    now = time.monotonic()
    score, touched = _speaker_affinity.get(key, (0, now))
    if now - touched > 1800:
        score = max(0, int(score) // 2)
    score = max(0, min(20, int(score) + int(amount)))
    _speaker_affinity[key] = (score, now)
    if len(_speaker_affinity) > 20000:
        cutoff = now - 3600
        for stale_key, (_score, stamp) in list(_speaker_affinity.items())[:4000]:
            if stamp < cutoff:
                _speaker_affinity.pop(stale_key, None)
    return score


def _speaker_affinity_score(group_id: int, user_id: int) -> int:
    score, touched = _speaker_affinity.get((int(group_id), int(user_id)), (0, 0.0))
    if touched and time.monotonic() - touched > 3600:
        return max(0, int(score) // 2)
    return int(score)


async def speaker_ai_queue_worker(worker_id: int) -> None:
    queue = _speaker_ai_queue
    if queue is None:
        return
    while True:
        job = await queue.get()
        try:
            loop = asyncio.get_running_loop()
            executor = _speaker_ai_executor
            if executor is None:
                raise RuntimeError("SPEAKER_AI_EXECUTOR_NOT_READY")
            started = time.monotonic()
            queued_at = float(job.get("queued_at") or started)
            if started - queued_at > SPEAKER_AI_JOB_MAX_AGE_SECONDS:
                result = {"ok": False, "reason": "stale", "status": 0, "latency": 0.0}
            else:
                result = await loop.run_in_executor(
                    executor,
                    lambda: generate_ai_speaker_reply(
                        group_id=int(job["group_id"]),
                        user_id=int(job["user_id"]),
                        user_text=str(job["user_text"]),
                        mode=str(job["mode"]),
                        display_name=str(job["display_name"]),
                        nickname=str(job.get("nickname") or ""),
                        group_title=str(job["group_title"]),
                        event_key=str(job.get("event_key") or ""),
                    ),
                )
            text = str(result.get("text") or "").strip() if result.get("ok") else ""
            used_fallback = False
            if not text:
                text = str(job.get("fallback") or "").strip()
                used_fallback = bool(text)
            if text:
                try:
                    await send_group_text(
                        job["target"], text,
                        reply_to=safe_int(job.get("source_message_id")),
                    )
                except Exception as exc:
                    log.debug(
                        "speaker ai send skipped | group=%s user=%s | %s: %s",
                        job.get("group_id"), job.get("user_id"), type(exc).__name__, exc,
                    )
                else:
                    _speaker_touch_affinity(
                        int(job["group_id"]), int(job["user_id"]),
                        2 if str(job.get("event_key") or "") in {"friendly", "call", "conversation"} else 1,
                    )
            elapsed = time.monotonic() - started
            log.info(
                "speaker ai result | group=%s user=%s mode=%s ok=%s fallback=%s provider=%s model=%s api_latency=%.2fs total=%.2fs queue=%s",
                job.get("group_id"), job.get("user_id"), job.get("mode"), bool(result.get("ok")),
                used_fallback, str(result.get("provider") or "local"), str(result.get("model") or "internal-bank"),
                float(result.get("latency") or 0.0), elapsed, queue.qsize(),
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            fallback = str(job.get("fallback") or "").strip()
            if fallback:
                try:
                    await send_group_text(
                        job["target"], fallback,
                        reply_to=safe_int(job.get("source_message_id")),
                    )
                except Exception:
                    pass
            log.warning(
                "speaker ai worker recovered | worker=%s group=%s user=%s | %s: %s",
                worker_id, job.get("group_id"), job.get("user_id"), type(exc).__name__, exc,
            )
        finally:
            queue.task_done()


def _speaker_ai_submit(job: Dict[str, Any]) -> bool:
    queue = _speaker_ai_queue
    if queue is None:
        return False
    # Never let a slow external API create a long conversational backlog.
    # Once the soft limit is reached, use the internal speaker bank immediately.
    if queue.qsize() >= SPEAKER_AI_QUEUE_SOFT_LIMIT:
        log.info(
            "speaker ai backlog fallback | group=%s user=%s size=%s soft=%s",
            job.get("group_id"), job.get("user_id"), queue.qsize(), SPEAKER_AI_QUEUE_SOFT_LIMIT,
        )
        return False
    try:
        job["queued_at"] = time.monotonic()
        queue.put_nowait(job)
        return True
    except asyncio.QueueFull:
        log.warning(
            "speaker ai queue full | group=%s user=%s size=%s/%s",
            job.get("group_id"), job.get("user_id"), queue.qsize(), SPEAKER_AI_QUEUE_MAX,
        )
        return False


async def maybe_handle_speaker_message(
    event: Any,
    group_id: int,
    *,
    force_event: Optional[str] = None,
    target_override: Any = None,
) -> bool:
    gid = int(group_id or 0)
    if gid <= 0:
        return False
    settings = get_speaker_settings(gid)
    if not settings.get("enabled"):
        return False
    sender_id = safe_int(getattr(event, "sender_id", None))
    if sender_id is None or int(sender_id) in SYSTEM_USER_IDS or int(sender_id) == SELF_USER_ID:
        return False
    raw_text = str(getattr(event, "raw_text", None) or "").strip()
    source_message_id = safe_int(getattr(event, "id", None))
    if not raw_text and not force_event:
        return False

    ai_enabled = get_speaker_ai_enabled(gid) and premium.feature_allowed(gid, "ai_speaker")
    if ai_enabled and raw_text:
        # Local-only bounded context capture. No API/DB/network work is done here.
        # It lets the next AI reply understand what other people in the group
        # were talking about without touching the Soroush receive path.
        ai_speaker_observe_group_message(gid, int(sender_id), raw_text)
    response_template = ""
    matched_custom = False
    for trigger, response in speaker_triggers(gid):
        if trigger_matches(trigger, raw_text):
            response_template = response
            matched_custom = True
            break

    event_key = force_event or classify_speaker_event(raw_text, bot_called=False)
    if not response_template and not event_key and ai_enabled:
        if ai_speaker_has_recent_dialogue(gid, int(sender_id), SPEAKER_AI_DIALOGUE_SECONDS):
            event_key = "conversation"
    if not response_template and not event_key:
        return False

    now = time.monotonic()
    user_key = (gid, int(sender_id))
    group_key = (gid, 0)
    user_cooldown = 1.4 if force_event or matched_custom else SPEAKER_REPLY_COOLDOWN_SECONDS
    if event_key == "conversation":
        user_cooldown = 1.8
    group_cooldown = 0.45 if force_event or matched_custom else 1.1
    if now - float(_speaker_last_reply.get(user_key, 0.0)) < user_cooldown:
        return False
    if now - float(_speaker_last_reply.get(group_key, 0.0)) < group_cooldown:
        return False

    mode = str(settings.get("mode") or "normal")
    allowed_profiles = premium.entitlement(gid, "speaker_profiles", ["normal"]) or ["normal"]
    if mode not in set(str(x) for x in allowed_profiles):
        mode = "normal"
    affinity = _speaker_affinity_score(gid, int(sender_id))
    if event_key and not matched_custom and event_key not in {"call", "join", "conversation"}:
        chance = {"normal": 0.58, "chatty": 0.92, "rude": 0.78}.get(mode, 0.58)
        if affinity >= 4:
            chance = min(1.0, chance + 0.12)
        if random.random() > chance:
            return False
    if event_key == "call" and affinity >= 5 and random.random() < 0.30 and not ai_enabled:
        event_key = "friendly"

    # Explicit custom triggers always keep the owner's exact configured text.
    if response_template:
        name = _speaker_user_name(event, gid, int(sender_id))
        group_title = _speaker_group_title(event, gid)
        response = render_speaker_response(response_template, name=name, group=group_title)
        if not response:
            return False
        target = target_override or fast_event_group_target(event)
        if target is None:
            try:
                target = await event.get_chat()
            except Exception:
                return False
        try:
            await send_group_text(target, response, reply_to=source_message_id)
        except Exception as exc:
            log.debug("speaker send skipped | group=%s user=%s | %s: %s", gid, sender_id, type(exc).__name__, exc)
            return False
        _speaker_last_reply[user_key] = now
        _speaker_last_reply[group_key] = now
        _speaker_touch_affinity(gid, int(sender_id), 2 if event_key in {"friendly", "call"} else 1)
        log.info("speaker response | group=%s user=%s mode=%s event=%s custom=1 ai=0", gid, sender_id, mode, event_key or "trigger")
        return True

    overrides = speaker_default_overrides(gid, mode)
    fallback_event = "friendly" if event_key == "conversation" else str(event_key)
    fallback_template = choose_default_response(mode, fallback_event, overrides.get(fallback_event, ""))
    name = _speaker_user_name(event, gid, int(sender_id))
    group_title = _speaker_group_title(event, gid)
    fallback = render_speaker_response(fallback_template, name=name, group=group_title) if fallback_template else ""

    target = target_override or fast_event_group_target(event)
    if target is None:
        try:
            target = await event.get_chat()
        except Exception:
            return False

    if ai_enabled:
        quota = premium.consume_ai_daily_quota(gid)
        if not quota.get("allowed"):
            ai_enabled = False
        profile = get_global_user_profile(int(sender_id)) if ai_enabled else {}
        nickname = str(profile.get("nickname") or profile.get("preferred_name") or "").strip()
        job = {
            "group_id": gid,
            "user_id": int(sender_id),
            "user_text": raw_text,
            "mode": mode,
            "display_name": name,
            "nickname": nickname,
            "group_title": group_title,
            "event_key": str(event_key or ""),
            "fallback": fallback,
            "target": target,
            "source_message_id": int(source_message_id or 0),
        }
        if ai_enabled and _speaker_ai_submit(job):
            # Reserve cooldown immediately so a fast burst cannot enqueue dozens of API calls.
            _speaker_last_reply[user_key] = now
            _speaker_last_reply[group_key] = now
            log.info(
                "speaker ai queued | group=%s user=%s mode=%s event=%s queue=%s/%s",
                gid, sender_id, mode, event_key or "conversation",
                _speaker_ai_queue.qsize() if _speaker_ai_queue is not None else 0, SPEAKER_AI_QUEUE_MAX,
            )
            return True

    if not fallback:
        return False
    try:
        await send_group_text(target, fallback, reply_to=source_message_id)
    except Exception as exc:
        log.debug("speaker send skipped | group=%s user=%s | %s: %s", gid, sender_id, type(exc).__name__, exc)
        return False
    _speaker_last_reply[user_key] = now
    _speaker_last_reply[group_key] = now
    _speaker_touch_affinity(gid, int(sender_id), 2 if event_key in {"friendly", "call"} else 1)
    log.info("speaker response | group=%s user=%s mode=%s event=%s custom=0 ai=0", gid, sender_id, mode, event_key or "trigger")
    return True


async def maybe_speaker_join(group: Any, group_id: int, profile: Dict[str, Any]) -> bool:
    settings = get_speaker_settings(int(group_id))
    if not settings.get("enabled"):
        return False
    mode = str(settings.get("mode") or "normal")
    overrides = speaker_default_overrides(int(group_id), mode)
    template = choose_default_response(mode, "join", overrides.get("join", ""))
    if not template:
        return False
    name = str(profile.get("name") or "تازه وارد")
    group_title = str(getattr(group, "title", None) or "گروه")
    text = render_speaker_response(template, name=name, group=group_title)
    if not text:
        return False
    try:
        await send_group_text(group, text)
        return True
    except Exception as exc:
        log.debug("speaker join send skipped | group=%s user=%s | %s: %s", group_id, profile.get("id"), type(exc).__name__, exc)
        return False


async def command_speaker(event: Any, group: Any, group_id: int, parsed: Dict[str, str]) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None)) or 0
    role = base_bot_role(int(group_id), int(actor_id))
    if role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ تنظیمات سخنگو فقط برای مالک و ادمین زیوو فعاله.")
        return
    action = str(parsed.get("action") or "")
    settings = get_speaker_settings(int(group_id))

    if action == "ai_status":
        ai_enabled = get_speaker_ai_enabled(int(group_id))
        await send_group_text(
            group,
            "🧠 ZIVO | سخنگوی هوشمند\n━━━━━━━━━━━━━━━━━━\n"
            f"🔘 وضعیت: {'روشن' if ai_enabled else 'خاموش'}\n"
            "⚡ پردازش AI از مسیر پیام‌های اصلی جداست و در صورت خطا به بانک داخلی زیوو برمی‌گردد.\n"
            "━━━━━━━━━━━━━━━━━━\nبرای فعال‌سازی: سخنگو هوشمند روشن",
        )
        return
    if action == "ai_enabled":
        ai_enabled = str(parsed.get("value") or "0") == "1"
        set_speaker_ai_enabled(int(group_id), int(actor_id), ai_enabled)
        await send_group_text(
            group,
            f"{'🧠✅' if ai_enabled else '🧠🔕'} سخنگوی هوشمند {'روشن' if ai_enabled else 'خاموش'} شد.\n"
            "💡 خود سخنگو هم باید روشن باشد: سخنگو روشن",
        )
        return

    if action == "status":
        trigger_count = len(speaker_triggers(int(group_id)))
        mode = str(settings.get("mode") or "normal")
        override_count = len(speaker_default_overrides(int(group_id), mode))
        await send_group_text(
            group,
            "🗣 ZIVO | سخنگو\n━━━━━━━━━━━━━━━━━━\n"
            f"🔘 وضعیت: {'روشن' if settings.get('enabled') else 'خاموش'}\n"
            f"🎭 شخصیت: {SPEAKER_MODE_LABELS.get(mode, mode)}\n"
            f"💬 پاسخ سفارشی: {trigger_count}\n"
            f"✏️ پیش فرض های تغییرکرده در این شخصیت: {override_count}\n"
            "━━━━━━━━━━━━━━━━━━\n📚 راهنما سخنگو",
        )
        return
    if action == "enabled":
        enabled = str(parsed.get("value") or "0") == "1"
        updated = upsert_speaker_settings(int(group_id), int(actor_id), enabled=enabled)
        await send_group_text(group, f"{'✅' if enabled else '🔕'} سخنگو {'روشن' if enabled else 'خاموش'} شد.\n🎭 شخصیت: {SPEAKER_MODE_LABELS.get(str(updated['mode']), str(updated['mode']))}")
        return
    if action == "mode":
        mode = str(parsed.get("mode") or "normal")
        updated = upsert_speaker_settings(int(group_id), int(actor_id), mode=mode)
        await send_group_text(group, f"🎭 شخصیت سخنگو روی «{SPEAKER_MODE_LABELS.get(str(updated['mode']), str(updated['mode']))}» تنظیم شد.\n💡 اگر خاموشه: سخنگو روشن")
        return
    if action == "upsert_trigger":
        try:
            existed, count = upsert_speaker_trigger(int(group_id), int(actor_id), parsed.get("trigger", ""), parsed.get("response", ""))
        except RuntimeError:
            await send_group_text(group, f"⚠️ سقف پاسخ های سفارشی این گروه {SPEAKER_MAX_TRIGGERS} مورده. یکی رو حذف کن و دوباره امتحان کن.")
            return
        except ValueError as exc:
            if str(exc) == "SPEAKER_PROFANITY_BLOCKED":
                await send_group_text(group, "⛔ این آموزش ثبت نشد. زیوو ناسزا و محتوای جنسی/توهین‌آمیز را به‌عنوان پاسخ سفارشی یاد نمی‌گیرد.")
                return
            await send_group_text(group, "⚠️ قالب درست:\nافزودن سخنگو سلام | سلام {name} جان 👋")
            return
        await send_group_text(group, f"{'✏️ پاسخ قبلی ویرایش شد' if existed else '✅ پاسخ جدید ثبت شد'}\n🔑 تریگر: {parsed.get('trigger','')}\n💬 جواب: {parsed.get('response','')[:500]}\n📚 تعداد پاسخ های سفارشی: {count}")
        return
    if action == "delete_trigger":
        removed = delete_speaker_trigger(int(group_id), parsed.get("trigger", ""))
        await send_group_text(group, "✅ پاسخ سفارشی حذف شد." if removed else "⚠️ چنین تریگری پیدا نشد.")
        return
    if action == "list":
        rows = speaker_trigger_rows(int(group_id))
        if not rows:
            await send_group_text(group, "📭 هنوز پاسخ سفارشی برای سخنگو ثبت نشده.\n\nنمونه:\nافزودن سخنگو سلام | سلام {name} جان 👋")
            return
        lines = ["🗣 ZIVO | پاسخ های سفارشی", "━━━━━━━━━━━━━━━━━━"]
        for index, row in enumerate(rows[:40], 1):
            preview = " ".join(str(row["response_text"] or "").split())[:90]
            lines.append(f"{index}) {row['trigger_display']} → {preview}")
        if len(rows) > 40:
            lines.append(f"… و {len(rows) - 40} مورد دیگر")
        lines.extend(("━━━━━━━━━━━━━━━━━━", "برای حذف: حذف سخنگو + تریگر"))
        await send_group_text(group, "\n".join(lines))
        return
    if action == "set_default":
        mode = str(parsed.get("mode") or settings.get("mode") or "normal")
        event_key = str(parsed.get("event") or "")
        try:
            set_speaker_default_override(int(group_id), int(actor_id), mode, event_key, parsed.get("response", ""))
        except ValueError as exc:
            if str(exc) == "SPEAKER_PROFANITY_BLOCKED":
                await send_group_text(group, "⛔ این جواب پیش‌فرض ذخیره نشد. زیوو ناسزا و محتوای جنسی/توهین‌آمیز را یاد نمی‌گیرد.")
                return
            await send_group_text(group, "⚠️ رویداد یا متن معتبر نیست.\n📚 راهنما سخنگو")
            return
        await send_group_text(group, f"✅ جواب پیش فرض «{SPEAKER_EVENT_LABELS.get(event_key, event_key)}» برای شخصیت «{SPEAKER_MODE_LABELS.get(mode, mode)}» تغییر کرد.\n💬 {parsed.get('response','')[:600]}")
        return
    if action == "reset_defaults":
        mode = str(parsed.get("mode") or "")
        event_key = str(parsed.get("event") or "*")
        count = reset_speaker_default_override(int(group_id), mode, event_key)
        await send_group_text(group, f"♻️ {count} تغییر پیش فرض پاک شد و بانک اصلی زیوو دوباره فعال شد.")
        return
    if action == "invalid_trigger":
        await send_group_text(group, "⚠️ قالب درست:\nافزودن سخنگو کلمه یا عبارت | جواب ربات\n\nنمونه:\nافزودن سخنگو سلام بچه ها | سلام {name} جان 👋")
        return
    if action == "invalid_default":
        await send_group_text(group, "⚠️ قالب درست:\nتنظیم پیش فرض سخنگو صدا | جانم {name}؟\nیا:\nتنظیم پیش فرض سخنگو بی ادب عضو جدید | به به {name} هم رسید 😂")
        return


def _join_object_graph(root: Any, *, limit: int = 96) -> List[Any]:
    """Bounded object walk for SPlusThon/Soroush service-event wrapper variants."""
    out: List[Any] = []
    stack: List[Any] = [root]
    seen: set[int] = set()
    attrs = (
        "message", "action", "update", "updates", "new_message", "new_messages",
        "message_update", "original_update", "raw_update", "event", "events",
        "result", "body", "payload", "data", "object", "obj",
    )
    while stack and len(out) < max(8, int(limit)):
        current = stack.pop()
        if current is None or isinstance(current, (str, bytes, bytearray, int, float, bool)):
            continue
        oid = id(current)
        if oid in seen:
            continue
        seen.add(oid)
        out.append(current)
        if isinstance(current, (list, tuple, set)):
            stack.extend(list(current)[:32])
            continue
        for attr in attrs:
            try:
                child = getattr(current, attr, None)
            except Exception:
                child = None
            if child is not None and child is not current and not isinstance(child, (str, bytes, bytearray, int, float, bool)):
                stack.append(child)
    return out


def _action_join_signature(action: Any) -> bool:
    if action is None:
        return False
    name = type(action).__name__.lower().replace("_", "")
    reject = (
        "deleteuser", "removeuser", "participantdelete", "participantremove",
        "memberremove", "userleft", "participantleft", "leave", "left", "kick",
        "ban", "migrate", "create", "title", "photo", "pin", "historyclear",
    )
    if any(token in name for token in reject):
        return False
    accept = (
        "adduser", "joined", "joinby", "participantjoin", "chatadduser",
        "chatjoined", "userjoined", "memberjoin", "participantadd", "memberadd",
        "useradd", "inviteuser", "inviteduser", "addmember",
    )
    if any(token in name for token in accept):
        return True
    # Some Soroush wrappers expose a generic action class but explicit flags.
    for flag in ("joined", "is_join", "member_joined", "participant_joined", "user_joined"):
        try:
            if bool(getattr(action, flag, False)):
                return True
        except Exception:
            pass
    return False


def _joined_user_ids_from_event(event: Any) -> List[int]:
    # legacy detector tokens: adduser joined chatadduser chatjoined memberjoin participantadd
    ids: List[int] = []
    sender_candidates: List[int] = []
    found_join_action = False
    graph_fn = globals().get("_join_object_graph")
    if callable(graph_fn):
        objects = graph_fn(event)
    else:
        objects = [event]
        message = getattr(event, "message", None)
        if message is not None and not isinstance(message, (str, bytes, bytearray, int, float, bool)):
            objects.append(message)
        action = getattr(message if message is not None else event, "action", None)
        if action is not None:
            objects.append(action)
    sig_fn = globals().get("_action_join_signature")
    def _local_sig(value: Any) -> bool:
        if callable(sig_fn):
            return bool(sig_fn(value))
        if value is None:
            return False
        name = type(value).__name__.lower().replace("_", "")
        if any(t in name for t in ("deleteuser", "removeuser", "left", "leave", "kick", "ban", "migrate")):
            return False
        return any(t in name for t in ("adduser", "joined", "joinby", "participantjoin", "chatadduser", "chatjoined", "userjoined", "memberjoin", "participantadd", "memberadd", "useradd"))
    for obj in objects:
        sender = safe_int(getattr(obj, "sender_id", None))
        if sender is None:
            from_id = getattr(obj, "from_id", None)
            sender = safe_int(getattr(from_id, "user_id", None))
        if sender is not None:
            sender_candidates.append(int(sender))

        action = getattr(obj, "action", None)
        if action is None and _local_sig(obj):
            action = obj
        if not _local_sig(action):
            continue
        found_join_action = True
        for attr in (
            "users", "user_ids", "participants", "participant_ids", "members",
            "member_ids", "added_users", "added_user_ids", "invited_users",
        ):
            values = getattr(action, attr, None)
            if not values:
                continue
            if not isinstance(values, (list, tuple, set)):
                values = [values]
            for value in list(values)[:32]:
                uid = (
                    safe_int(getattr(value, "user_id", None))
                    or safe_int(getattr(value, "id", None))
                    or safe_int(value)
                )
                if uid is not None:
                    ids.append(int(uid))
        for attr in (
            "user_id", "joined_user_id", "participant_id", "member_id",
            "added_user_id", "invited_user_id",
        ):
            uid = safe_int(getattr(action, attr, None))
            if uid is not None:
                ids.append(int(uid))

    # Join-by-link/self-join service actions frequently carry no explicit user id.
    if found_join_action and not ids:
        ids.extend(sender_candidates[:1])

    bot_ids: set[int] = {int(SELF_USER_ID or 0)} | {int(v) for v in SYSTEM_USER_IDS}
    try:
        list_accounts_fn = globals().get("multi_list_accounts")
        control_db = globals().get("MULTI_ACCOUNT_DB")
        if callable(list_accounts_fn) and control_db is not None:
            for row in list_accounts_fn(control_db):
                keys = row.keys() if hasattr(row, "keys") else ()
                uid = safe_int(row["self_id"] if "self_id" in keys else None)
                if uid:
                    bot_ids.add(int(uid))
    except Exception:
        pass

    result: List[int] = []
    seen: set[int] = set()
    for uid in ids:
        if uid <= 0 or uid in seen or uid in bot_ids:
            continue
        seen.add(uid)
        result.append(uid)
        if len(result) >= 25:
            break
    return result


def _cached_event_user_entity(event: Any, user_id: int) -> Optional[Any]:
    message = getattr(event, "message", None) or event
    for source in (getattr(message, "_entities", None), getattr(event, "_entities", None)):
        if isinstance(source, dict):
            for key in (int(user_id), types.PeerUser(int(user_id))):
                try:
                    entity = source.get(key)
                except Exception:
                    entity = None
                if entity is not None and safe_int(getattr(entity, "id", None)) == int(user_id):
                    return entity
    sender = getattr(event, "sender", None)
    if sender is not None and safe_int(getattr(sender, "id", None)) == int(user_id):
        return sender
    return None


async def _resolve_welcome_profile(event: Any, group: Any, group_id: int, user_id: int) -> Dict[str, Any]:
    entity = _cached_event_user_entity(event, user_id)
    # Never scan hundreds of participants on the welcome hot path. Under real
    # join bursts that 15s RPC blocked the small service-worker pool and made
    # later welcomes appear "dead". Prefer event/session cache and a bounded
    # direct entity lookup; durable observed identity is the zero-RPC fallback.
    if entity is None:
        try:
            entity = await asyncio.wait_for(
                client.get_entity(types.PeerUser(int(user_id))),
                timeout=WELCOME_PROFILE_RPC_TIMEOUT_SECONDS,
            )
        except Exception as exc:
            log.debug("welcome direct profile resolve skipped | group=%s user=%s | %s", group_id, user_id, exc)
            entity = None
    access_hash = safe_int(getattr(entity, "access_hash", None)) if entity is not None else None
    access_hash = int(access_hash or stats_access_hash(group_id, user_id) or 0)
    username = (getattr(entity, "username", None) or "") if entity is not None else ""
    name = display_name(entity) if entity is not None else ""
    if not name or name == "بدون نام":
        try:
            observed = get_global_user_profile(int(user_id))
        except Exception:
            observed = {}
        username = username or str(observed.get("username") or "")
        name = str(
            observed.get("preferred_name")
            or observed.get("nickname")
            or observed.get("observed_name")
            or ""
        ).strip()
    if not name:
        name = f"کاربر {int(user_id)}"
    bio = "دریافت نشد"
    if access_hash:
        try:
            full = await asyncio.wait_for(
                client(functions.users.GetFullUserRequest(id=types.InputUser(user_id=int(user_id), access_hash=int(access_hash)))),
                timeout=12,
            )
            for candidate in list(getattr(full, "users", None) or []):
                if safe_int(getattr(candidate, "id", None)) == int(user_id):
                    entity = candidate
                    username = getattr(candidate, "username", None) or username
                    name = display_name(candidate)
                    break
            full_user = getattr(full, "full_user", None)
            raw_about = getattr(full_user, "about", None) if full_user is not None else None
            bio = raw_about.strip() if isinstance(raw_about, str) and raw_about.strip() else "تنظیم نشده"
        except Exception as exc:
            log.debug("welcome full profile unavailable | group=%s user=%s | %s", group_id, user_id, exc)
    return {
        "id": int(user_id), "access_hash": access_hash,
        "username": username, "name": name, "bio": bio,
    }


async def _cache_welcome_gif(reply: Any, group_id: int) -> str:
    WELCOME_MEDIA_DIR.mkdir(parents=True, exist_ok=True)
    for old_path in WELCOME_MEDIA_DIR.glob(f"welcome_{int(group_id)}_*"):
        try:
            old_path.unlink(missing_ok=True)
        except Exception:
            pass

    stamp = int(time.time())
    candidates = []
    file_obj = getattr(reply, "file", None)
    ext = str(getattr(file_obj, "ext", "") or "")
    if ext and not ext.startswith("."):
        ext = "." + ext
    target = WELCOME_MEDIA_DIR / f"welcome_{int(group_id)}_{stamp}{ext or '.gif'}"

    message_downloader = getattr(reply, "download_media", None)
    if callable(message_downloader):
        candidates.append(("message", message_downloader))
    client_downloader = getattr(client, "download_media", None)
    if callable(client_downloader):
        candidates.append(("client", client_downloader))

    last_error: Optional[Exception] = None
    for kind, downloader in candidates:
        try:
            if kind == "message":
                downloaded = await asyncio.wait_for(downloader(file=str(target)), timeout=120)
            else:
                downloaded = await asyncio.wait_for(downloader(reply, file=str(target)), timeout=120)
            path = Path(str(downloaded or target))
            if path.is_file() and path.stat().st_size > 0:
                try:
                    path.chmod(0o600)
                except Exception:
                    pass
                return str(path)
        except Exception as exc:
            last_error = exc
            log.warning("welcome gif download method failed | group=%s method=%s | %s: %s", group_id, kind, type(exc).__name__, exc)

    if last_error is not None:
        raise last_error
    return ""


async def _send_welcome_gif(group: Any, settings: Dict[str, Any], group_id: int) -> bool:
    def schedule_sent(sent: Any) -> None:
        if isinstance(sent, (list, tuple)):
            for item in sent:
                schedule_bot_message_cleanup(group, item, "welcome")
            return
        schedule_bot_message_cleanup(group, sent, "welcome")

    # Prefer the original Soroush media whenever it is still available. This
    # preserves the platform's native animation/document metadata exactly.
    source_id = int(settings.get("gif_source_message_id") or 0)
    if source_id:
        try:
            source = await client.get_messages(group, ids=source_id)
            if isinstance(source, (list, tuple)):
                source = source[0] if source else None
            media = getattr(source, "media", None) if source is not None else None
            forwarder = getattr(client, "forward_messages", None)
            if callable(forwarder) and source is not None:
                try:
                    sent = await forwarder(group, source)
                    schedule_sent(sent)
                    log.info("welcome gif sent by source forward | group=%s source=%s", group_id, source_id)
                    return True
                except Exception as exc:
                    log.warning("welcome gif source forward failed | group=%s source=%s | %s: %s", group_id, source_id, type(exc).__name__, exc)
            if media is not None:
                try:
                    sent = await client.send_file(group, media, parse_mode=None)
                    schedule_sent(sent)
                    log.info("welcome gif sent by media reference | group=%s source=%s", group_id, source_id)
                    return True
                except Exception as exc:
                    log.warning("welcome source media send failed | group=%s source=%s | %s: %s", group_id, source_id, type(exc).__name__, exc)
        except Exception as exc:
            log.warning("welcome source gif resolve failed | group=%s source=%s | %s: %s", group_id, source_id, type(exc).__name__, exc)

    # The cached file is the durable fallback if the original source message is
    # deleted later or history access is temporarily unavailable.
    local_path = str(settings.get("gif_local_path") or "")
    if local_path and Path(local_path).is_file():
        last_error: Optional[Exception] = None
        for kwargs in (
            {"parse_mode": None, "force_document": False, "supports_streaming": True},
            {"parse_mode": None, "force_document": False},
            {"parse_mode": None},
            {},
        ):
            try:
                sent = await send_file_resilient(group, Path(local_path), **kwargs)
                schedule_sent(sent)
                return True
            except TypeError as exc:
                last_error = exc
                continue
            except Exception as exc:
                last_error = exc
                log.warning("welcome local gif send method failed | group=%s | %s: %s", group_id, type(exc).__name__, exc)
                continue
        if last_error is not None:
            log.warning("welcome cached gif exhausted all send methods | group=%s | %s: %s", group_id, type(last_error).__name__, last_error)
    return False


async def _send_welcome_text_reply(
    group: Any,
    text: str,
    service_message_id: int,
    profile: Dict[str, Any],
    *,
    reply_to_service: bool = True,
) -> Any:
    profile_label = "﹝مشاهده نمایه﹞"
    mentions = [
        (profile["name"], int(profile["id"]), int(profile.get("access_hash") or 0)),
        (profile_label, int(profile["id"]), int(profile.get("access_hash") or 0)),
    ]
    if reply_to_service:
        try:
            sent = await client.send_message(
                group, text, reply_to=int(service_message_id), parse_mode=None,
                formatting_entities=rich_mention_entities(text, mentions), link_preview=False,
            )
            schedule_bot_message_cleanup(group, sent, "welcome")
            return sent
        except Exception as exc:
            log.debug("welcome reply send fallback | group=%s | %s: %s", getattr(group, "id", "?"), type(exc).__name__, exc)
    try:
        sent = await client.send_message(group, text, parse_mode=None, formatting_entities=rich_mention_entities(text, mentions), link_preview=False)
        schedule_bot_message_cleanup(group, sent, "welcome")
        return sent
    except Exception:
        sent = await client.send_message(group, text, parse_mode=None, formatting_entities=[], link_preview=False)
        schedule_bot_message_cleanup(group, sent, "welcome")
        return sent


def _welcome_state_from_db(db_path: str, group_id: int) -> Dict[str, Any]:
    result: Dict[str, Any] = {"exists": False, "updated_epoch": 0.0, "updated_at": ""}
    path = Path(str(db_path))
    if not path.is_file():
        return result
    con = sqlite3.connect(str(path), timeout=0.25)
    con.row_factory = sqlite3.Row
    try:
        con.execute("PRAGMA busy_timeout=250")
        row = con.execute("SELECT * FROM welcome_settings WHERE group_id = ?", (int(group_id),)).fetchone()
        if row is None:
            return result
        result = dict(row)
        result["exists"] = True
        result["updated_at"] = str(row["updated_at"] or "") if "updated_at" in row.keys() else ""
        result["updated_epoch"] = _legacy_iso_epoch(result["updated_at"])
        return result
    except sqlite3.Error:
        return result
    finally:
        con.close()


def reconcile_welcome_settings_from_accounts(group_id: int) -> Dict[str, Any]:
    """Use newest durable welcome config across main/acc2/acc3 for live join events."""
    gid = int(group_id)
    local = _welcome_state_from_db(str(DB_PATH), gid)
    local_epoch = float(local.get("updated_epoch") or 0.0)
    best: Optional[Tuple[float, str, str, Dict[str, Any]]] = None
    for key, db_path in _legacy_group_account_sources(gid):
        if key == ACCOUNT_KEY or str(Path(db_path).resolve()) == str(DB_PATH.resolve()):
            continue
        state = _welcome_state_from_db(db_path, gid)
        if not state.get("exists"):
            continue
        epoch = float(state.get("updated_epoch") or 0.0)
        # Legacy rows without timestamps can seed only when local row is absent.
        if local.get("exists") and epoch <= local_epoch:
            continue
        rank = epoch if epoch > 0 else 0.000001
        if best is None or rank > best[0]:
            best = (rank, key, db_path, state)
    if best is not None:
        _, key, db_path, _state = best
        try:
            copied = _copy_legacy_group_state_from_db(gid, db_path)
            if copied:
                log.info("welcome settings reconciled | group=%s source_account=%s rows=%s", gid, key, copied)
        except Exception as exc:
            log.debug("welcome settings reconcile skipped | group=%s source=%s | %s: %s", gid, key, type(exc).__name__, exc)
    return get_welcome_settings(gid)


def _welcome_public_group(group: Any, installation: Any) -> bool:
    if isinstance(group, types.Channel):
        if bool(getattr(group, "username", None) or getattr(group, "usernames", None)):
            return True
    ref = str(installation["invite_hash"] or "") if installation is not None and "invite_hash" in installation.keys() else ""
    return ref.startswith("public:")


async def maybe_handle_group_join_welcome(
    event: Any,
    *,
    hinted_group_id: Optional[int] = None,
    hinted_group: Any = None,
) -> bool:
    if bool(getattr(event, "is_private", False)):
        return False
    joined_ids = _joined_user_ids_from_event(event)
    if not joined_ids:
        return False

    message = getattr(event, "message", None) or event
    peer = getattr(message, "peer_id", None)
    group_id = safe_int(hinted_group_id) or canonical_anti_spam_group_id(getattr(event, "chat_id", None)) or _service_message_group_id(message)
    service_message_id = safe_int(getattr(event, "id", None)) or safe_int(getattr(message, "id", None))
    if group_id is None or service_message_id is None:
        log.warning("welcome join dropped missing ids | group=%s message=%s users=%s", group_id, service_message_id, joined_ids)
        return True

    installation = get_installation(int(group_id))
    if installation is None:
        recovered, _, _ = recover_legacy_group_installation(int(group_id))
        installation = get_installation(int(group_id)) if recovered else None
    if installation is None:
        log.info("welcome join deferred no installation | group=%s users=%s", group_id, joined_ids)
        return True
    if not is_group_bot_enabled(int(group_id)):
        log.info("welcome join skipped bot disabled | group=%s users=%s", group_id, joined_ids)
        return True

    group = hinted_group
    if group is None:
        try:
            group = await asyncio.wait_for(event.get_chat(), timeout=2.5)
        except Exception as exc:
            group = getattr(event, "input_chat", None) or peer or int(group_id)
            log.info("welcome group target fallback | group=%s | %s: %s", group_id, type(exc).__name__, exc)
    if group is None:
        group = peer or int(group_id)

    settings = reconcile_welcome_settings_from_accounts(int(group_id))
    group_title = str(getattr(group, "title", None) or installation["group_title"] or "گروه")
    joined_at = datetime.now(IRAN_TZ)
    try:
        jy, jm, jd = jalali_parts(joined_at)
        jdate = f"{jy:04d}/{jm:02d}/{jd:02d}"
    except Exception:
        jdate = joined_at.strftime("%Y/%m/%d")

    handled_any = False
    for user_id in joined_ids:
        if _welcome_event_already_sent(int(group_id), int(service_message_id), int(user_id)):
            continue
        handled_any = True
        profile = await _resolve_welcome_profile(event, group, int(group_id), int(user_id))
        record_welcome_join(int(group_id), int(user_id), profile, int(service_message_id), joined_at)
        if not settings["enabled"]:
            await maybe_speaker_join(group, int(group_id), profile)
            log.info("welcome join recorded while disabled | group=%s user=%s", group_id, user_id)
            continue

        values = {
            "name": profile["name"],
            "username": ("@" + profile["username"]) if profile["username"] else "ندارد",
            "user_id": str(user_id),
            "bio": profile["bio"],
            "group": group_title,
            "time": joined_at.strftime("%H:%M"),
            "date": jdate,
            "profile": "﹝مشاهده نمایه﹞",
        }
        text = render_welcome_text(settings["custom_text"], values)
        gif_ok = True
        if settings.get("gif_local_path") or settings.get("gif_source_message_id"):
            gif_ok = await _send_welcome_gif(group, settings, int(group_id))
            await asyncio.sleep(0.15)

        is_public_group = _welcome_public_group(group, installation)
        try:
            welcome_sent = await _send_welcome_text_reply(
                group, text, int(service_message_id), profile,
                reply_to_service=not is_public_group,
            )
        except Exception as exc:
            log.warning("welcome text send failed | group=%s user=%s | %s: %s", group_id, user_id, type(exc).__name__, exc)
            # Keep event unmarked so raw/next duplicate delivery can retry.
            continue

        rules_settings = get_group_rules_settings(int(group_id))
        if rules_settings.get("rules_text") and rules_settings.get("show_in_welcome"):
            welcome_message_id = safe_int(getattr(welcome_sent, "id", None))
            try:
                await send_rules_message(
                    group, int(group_id), cleanup_category="welcome", reply_to=welcome_message_id
                )
            except Exception as exc:
                log.warning(
                    "welcome rules send failed | group=%s user=%s | %s: %s",
                    group_id, user_id, type(exc).__name__, exc,
                )
        await maybe_speaker_join(group, int(group_id), profile)
        _mark_welcome_event_sent(int(group_id), int(service_message_id), int(user_id))
        log.info(
            "welcome sent | group=%s user=%s public=%s reply_to_service=%s gif_configured=%s gif_sent=%s",
            group_id, user_id, int(is_public_group), int(not is_public_group),
            bool(settings.get("gif_local_path") or settings.get("gif_source_message_id")), gif_ok,
        )
    return bool(handled_any or joined_ids)


async def command_welcome(event: Any, group: Any, group_id: int, parsed: Dict[str, Any]) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    role = base_bot_role(group_id, actor_id)
    if role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ تنظیمات خوش آمدگویی فقط برای مالک و ادمین زیوو فعاله.")
        return
    action = parsed["action"]
    if action == "enable":
        upsert_welcome_settings(group_id, actor_id, enabled=True)
        await send_group_text(group, "✅ خوش آمدگویی کاربران جدید فعال شد.\nبرای مشاهده تنظیمات: وضعیت خوشامد")
        return
    if action == "disable":
        upsert_welcome_settings(group_id, actor_id, enabled=False)
        await send_group_text(group, "🔕 خوش آمدگویی کاربران جدید خاموش شد.")
        return
    if action == "status":
        settings = get_welcome_settings(group_id)
        rules_settings = get_group_rules_settings(group_id)
        await send_group_text(
            group,
            "👋 ZIVO | وضعیت خوش آمدگویی\n━━━━━━━━━━━━━━━━━━\n"
            f"🔘 وضعیت: {'فعال' if settings['enabled'] else 'خاموش'}\n"
            f"📝 متن: {'سفارشی' if settings['custom_text'] else 'پیش فرض حرفه ای زیوو'}\n"
            f"🎞 گیف: {'تنظیم شده' if settings['gif_local_path'] or settings['gif_source_message_id'] else 'ندارد'}\n"
            f"📜 متن قوانین: {'تنظیم شده' if rules_settings['rules_text'] else 'تنظیم نشده'}\n"
            f"👋 قوانین زیر خوشامد: {'فعال' if rules_settings['show_in_welcome'] else 'خاموش'}\n"
            "━━━━━━━━━━━━━━━━━━\n📚 راهنما خوشامد",
        )
        return
    if action == "recent_joins":
        await send_recent_welcome_joins(group, group_id, 10)
        return
    if action == "last_join":
        await send_recent_welcome_joins(group, group_id, 1)
        return
    if action == "test_welcome":
        settings = reconcile_welcome_settings_from_accounts(group_id)
        now = datetime.now(IRAN_TZ)
        actor_profile = await _resolve_welcome_profile(event, group, group_id, actor_id)
        values = {
            "name": actor_profile["name"],
            "username": ("@" + actor_profile["username"]) if actor_profile.get("username") else "ندارد",
            "user_id": str(actor_id), "bio": actor_profile.get("bio") or "دریافت نشد",
            "group": str(getattr(group, "title", None) or "گروه شما"),
            "time": now.strftime("%H:%M"),
            "date": (lambda parts: f"{parts[0]:04d}/{parts[1]:02d}/{parts[2]:02d}")(jalali_parts(now)),
            "profile": "﹝مشاهده نمایه﹞",
        }
        gif_ok = True
        if settings.get("gif_local_path") or settings.get("gif_source_message_id"):
            gif_ok = await _send_welcome_gif(group, settings, group_id)
        sent = await _send_welcome_text_reply(group, render_welcome_text(settings["custom_text"], values), 0, actor_profile, reply_to_service=False)
        await send_group_text(group, f"✅ تست مسیر خوشامد موفق بود.{' گیف هم ارسال شد.' if gif_ok else ' متن ارسال شد ولی گیف تست نشد.'}")
        return

    if action == "test_gif":
        settings = get_welcome_settings(group_id)
        if not (settings.get("gif_local_path") or settings.get("gif_source_message_id")):
            await send_group_text(group, "🎞 هنوز گیف خوشامد تنظیم نشده.")
            return
        ok = await _send_welcome_gif(group, settings, group_id)
        await send_group_text(group, "✅ تست گیف خوشامد موفق بود." if ok else "❌ گیف ذخیره شده ارسال نشد؛ دوباره روی گیف ریپلای کن و «تنظیم گیف خوشامد» بزن.")
        return

    if action == "preview":
        settings = get_welcome_settings(group_id)
        now = datetime.now(IRAN_TZ)
        values = {
            "name": "کاربر نمونه", "username": "@sample", "user_id": "12345678",
            "bio": "این یک پیش نمایش از بیو است.",
            "group": str(getattr(group, "title", None) or "گروه شما"),
            "time": now.strftime("%H:%M"),
            "date": (lambda parts: f"{parts[0]:04d}/{parts[1]:02d}/{parts[2]:02d}")(jalali_parts(now)),
            "profile": "﹝مشاهده نمایه﹞",
        }
        await send_group_text(group, render_welcome_text(settings["custom_text"], values))
        rules_settings = get_group_rules_settings(group_id)
        if rules_settings.get("rules_text") and rules_settings.get("show_in_welcome"):
            await send_rules_message(group, group_id, cleanup_category="general")
        return
    if action == "reset_text":
        upsert_welcome_settings(group_id, actor_id, custom_text="")
        await send_group_text(group, "✅ متن سفارشی حذف شد؛ قالب حرفه ای پیش فرض زیوو برگشت.")
        return
    if action == "remove_gif":
        old = get_welcome_settings(group_id)
        old_path = str(old.get("gif_local_path") or "")
        upsert_welcome_settings(group_id, actor_id, gif_source_message_id=0, gif_local_path="", gif_fingerprint="")
        if old_path:
            try:
                Path(old_path).unlink(missing_ok=True)
            except Exception:
                pass
        await send_group_text(group, "✅ گیف خوش آمد حذف شد؛ از این به بعد فقط متن ارسال می شود.")
        return
    if action == "set_text":
        if not bool(getattr(event, "is_reply", False)):
            await send_group_text(group, "↩️ روی متن دلخواه ریپلای کن و بنویس: تنظیم متن خوشامد")
            return
        reply = await event.get_reply_message()
        raw = (getattr(reply, "raw_text", None) or getattr(reply, "message", None) or "").strip() if reply is not None else ""
        if not raw:
            await send_group_text(group, "❌ پیام ریپلای شده متن قابل ذخیره ندارد.")
            return
        if len(raw) > 3500:
            await send_group_text(group, "❌ متن خوش آمد حداکثر 3500 نویسه می تواند باشد.")
            return
        upsert_welcome_settings(group_id, actor_id, custom_text=raw)
        await send_group_text(group, "✅ متن خوش آمد ذخیره شد.\nبرای دیدنش بنویس: پیش نمایش خوشامد")
        return
    if action == "set_gif":
        if not bool(getattr(event, "is_reply", False)):
            await send_group_text(group, "↩️ روی گیف مورد نظر ریپلای کن و بنویس: تنظیم گیف خوشامد")
            return
        reply = await event.get_reply_message()
        if reply is None or robust_message_category(reply) != "gif":
            await send_group_text(group, "❌ پیام ریپلای شده باید یک گیف قابل تشخیص باشد.")
            return
        source_id = safe_int(getattr(reply, "id", None)) or 0
        descriptor = exact_content_descriptor(reply) or {}
        local_path = ""
        if os.getenv("ZIVO_WELCOME_MEDIA_CACHE", "0").strip() == "1":
            try:
                local_path = await _cache_welcome_gif(reply, group_id)
            except Exception as exc:
                log.info("welcome gif local cache unavailable; source reference kept | group=%s | %s: %s", group_id, type(exc).__name__, exc)
        settings = upsert_welcome_settings(
            group_id, actor_id,
            gif_source_message_id=int(source_id),
            gif_local_path=local_path,
            gif_fingerprint=str(descriptor.get("fingerprint") or ""),
        )
        test_ok = await _send_welcome_gif(group, settings, group_id)
        if test_ok:
            await send_group_text(group, "✅ گیف خوشامد ذخیره شد و تست ارسال هم موفق بود.\nاز این به بعد اول گیف و بعد متن خوشامد ارسال می‌شود.")
        else:
            await send_group_text(group, "⚠️ گیف ثبت شد ولی تست ارسال ناموفق بود. دوباره روی همان گیف ریپلای کن و «تنظیم گیف خوشامد» را بزن.")
        return


def _clear_emergency_install(group_id: int) -> None:
    with db_connect() as con:
        con.execute("DELETE FROM emergency_install_approvals WHERE group_id = ?", (int(group_id),))
        con.execute("DELETE FROM emergency_install_requests WHERE group_id = ?", (int(group_id),))
        con.commit()


def _get_emergency_install(group_id: int) -> Optional[sqlite3.Row]:
    with db_connect() as con:
        return con.execute("SELECT * FROM emergency_install_requests WHERE group_id = ?", (int(group_id),)).fetchone()


def _emergency_approval_count(group_id: int) -> int:
    with db_connect() as con:
        row = con.execute("SELECT COUNT(*) AS c FROM emergency_install_approvals WHERE group_id = ?", (int(group_id),)).fetchone()
    return int(row["c"] or 0) if row else 0


async def _native_admin_for_user(group: Any, user_id: int) -> Optional[Any]:
    admins = await get_admins(group)
    for user in admins:
        if safe_int(getattr(user, "id", None)) == int(user_id):
            return user
    return None


async def handle_emergency_install_command(event: Any, group: Any, group_id: int, text: str) -> bool:
    if text not in (EMERGENCY_INSTALL_START_COMMANDS | EMERGENCY_INSTALL_CONFIRM_COMMANDS | EMERGENCY_INSTALL_CANCEL_COMMANDS):
        return False
    sender_id = safe_int(getattr(event, "sender_id", None))
    if sender_id is None:
        return True
    native_admin = await _native_admin_for_user(group, sender_id)
    if native_admin is None:
        await send_group_text(group, "⛔ نصب اضطراری فقط توسط ادمین واقعی خود گروه قابل انجام است.")
        return True
    participant = getattr(native_admin, "participant", None)
    is_creator = isinstance(participant, (types.ChannelParticipantCreator, types.ChatParticipantCreator))
    if not is_creator:
        rights = getattr(participant, "admin_rights", None)
        if rights is not None and not admin_rights_are_active(rights):
            await send_group_text(group, "⛔ دسترسی مدیریتی این ادمین برای نصب اضطراری کافی نیست.")
            return True

    if text in EMERGENCY_INSTALL_CANCEL_COMMANDS:
        req = _get_emergency_install(group_id)
        if req is None:
            await send_group_text(group, "ℹ️ درخواست نصب اضطراری فعالی وجود ندارد.")
            return True
        creator = await find_group_creator(group)
        creator_id = safe_int(getattr(creator, "id", None)) if creator is not None else None
        if sender_id not in {int(req["initiator_user_id"]), int(creator_id or 0)}:
            await send_group_text(group, "⛔ فقط درخواست کننده یا مالک واقعی گروه می تواند درخواست اضطراری را لغو کند.")
            return True
        _clear_emergency_install(group_id)
        await send_group_text(group, "✅ درخواست نصب اضطراری لغو شد.")
        return True

    if text in EMERGENCY_INSTALL_START_COMMANDS:
        existing = get_installation(group_id)
        creator = await find_group_creator(group)
        creator_id = safe_int(getattr(creator, "id", None)) if creator is not None else 0
        now = datetime.now(timezone.utc)
        expires = now + timedelta(seconds=EMERGENCY_INSTALL_TTL_SECONDS)
        _clear_emergency_install(group_id)
        with db_connect() as con:
            con.execute(
                """
                INSERT INTO emergency_install_requests (
                    group_id, initiator_user_id, initiator_username, initiator_access_hash,
                    previous_owner_user_id, real_creator_user_id, expires_at, created_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                """,
                (
                    int(group_id), int(sender_id), getattr(native_admin, "username", None) or "",
                    int(safe_int(getattr(native_admin, "access_hash", None)) or 0),
                    int(existing["owner_user_id"]) if existing is not None else 0,
                    int(creator_id or 0), expires.isoformat(), now.isoformat(),
                ),
            )
            con.execute(
                "INSERT INTO emergency_install_approvals (group_id, user_id, username, access_hash, approved_at) VALUES (?, ?, ?, ?, ?)",
                (int(group_id), int(sender_id), getattr(native_admin, "username", None) or "", int(safe_int(getattr(native_admin, "access_hash", None)) or 0), now.isoformat()),
            )
            con.commit()
        await send_group_text(
            group,
            "🚨 ZIVO | درخواست نصب اضطراری\n━━━━━━━━━━━━━━━━━━\n"
            "✅ امضای ادمین اول ثبت شد: 1/2\n"
            "👥 برای امنیت، یک ادمین واقعی و متفاوت دیگر باید ظرف 10 دقیقه بنویسد:\n"
            "تایید نصب اضطراری\n\n"
            "⚠️ این مسیر فقط برای زمانی است که مالک اصلی گروه در دسترس نیست.\n"
            "🛑 مالک واقعی یا درخواست کننده می تواند بنویسد: لغو نصب اضطراری\n"
            "━━━━━━━━━━━━━━━━━━\n🔐 ZIVO | TWO-ADMIN SAFE INSTALL",
        )
        return True

    req = _get_emergency_install(group_id)
    if req is None:
        await send_group_text(group, "ℹ️ اول یک ادمین واقعی باید بنویسد: نصب اضطراری")
        return True
    try:
        expires_at = datetime.fromisoformat(str(req["expires_at"]))
        if expires_at.tzinfo is None:
            expires_at = expires_at.replace(tzinfo=timezone.utc)
    except Exception:
        expires_at = datetime.now(timezone.utc) - timedelta(seconds=1)
    if datetime.now(timezone.utc) > expires_at:
        _clear_emergency_install(group_id)
        await send_group_text(group, "⌛ درخواست نصب اضطراری منقضی شد. دوباره «نصب اضطراری» را شروع کنید.")
        return True
    if sender_id == int(req["initiator_user_id"]):
        await send_group_text(group, "⛔ ادمین دوم باید یک شخص متفاوت باشد؛ یک نفر نمی تواند هر دو تایید را انجام دهد.")
        return True
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            "INSERT OR IGNORE INTO emergency_install_approvals (group_id, user_id, username, access_hash, approved_at) VALUES (?, ?, ?, ?, ?)",
            (int(group_id), int(sender_id), getattr(native_admin, "username", None) or "", int(safe_int(getattr(native_admin, "access_hash", None)) or 0), now),
        )
        con.commit()
    if _emergency_approval_count(group_id) < 2:
        await send_group_text(group, "✅ تایید ثبت شد؛ هنوز دو امضای متفاوت کامل نشده است.")
        return True

    initiator_id = int(req["initiator_user_id"])
    initiator_username = str(req["initiator_username"] or "")
    initiator_hash = int(req["initiator_access_hash"] or 0)
    existing = get_installation(group_id)
    meta = await get_group_metadata(group)
    real_creator_id = int(req["real_creator_user_id"] or 0)
    emergency_card = {
        "owner_id": initiator_id,
        "owner_access_hash": initiator_hash,
        "native_owner_id": real_creator_id,
        "native_owner_available": bool(real_creator_id),
        "owner_mode": "executive",
        "probe_already_sent": False,
        "group_title": str(meta["title"] or ""),
        "peer_kind": "chat" if isinstance(group, types.Chat) else "channel",
        "group_access_hash": int(getattr(group, "access_hash", 0) or 0),
    }
    if existing is None:
        installation = register_installation(
            group_id=group_id, group_title=meta["title"], owner_user_id=initiator_id,
            owner_username=initiator_username, owner_access_hash=initiator_hash,
            install_source="emergency_two_admin_quorum",
            native_owner_user_id=real_creator_id,
            owner_mode="executive",
            introduced_by_user_id=initiator_id,
            introduced_by_username=initiator_username,
            activation_card=emergency_card,
        )
    else:
        with db_connect() as con:
            con.execute(
                "UPDATE installations SET owner_user_id = ?, owner_username = ?, owner_access_hash = ?, native_owner_user_id = ?, owner_mode = 'executive', install_source = ? WHERE group_id = ?",
                (initiator_id, initiator_username, initiator_hash, real_creator_id, "emergency_two_admin_takeover", int(group_id)),
            )
            _activation_card_job_upsert_in_connection(
                con, int(group_id), initiator_id, initiator_hash,
                real_creator_id, bool(real_creator_id), "executive", False,
            )
            _group_lifecycle_upsert_in_connection(
                con,
                int(group_id),
                str(emergency_card["group_title"] or ""),
                str(emergency_card["peer_kind"] or "channel"),
                int(emergency_card["group_access_hash"] or 0),
                now=now,
            )
            card_queued_at = datetime.now(timezone.utc).isoformat()
            con.execute(
                """
                UPDATE pending_group_activations
                SET group_notice_sent = 1, group_notice_sent_at = ?,
                    group_notice_last_error = '', updated_at = ?
                WHERE group_id = ?
                """,
                (card_queued_at, card_queued_at, int(group_id)),
            )
            con.commit()
        _installation_hot_cache.pop(int(group_id), None)
        installation = get_installation(group_id)
    mark_group_activated(group, group_id, str(meta["title"] or ""))
    if real_creator_id and real_creator_id != initiator_id:
        with db_connect() as con:
            con.execute(
                """
                INSERT INTO owner_recovery_cache (group_id, real_owner_id, username, access_hash, detected_at)
                VALUES (?, ?, '', 0, ?)
                ON CONFLICT(group_id) DO UPDATE SET real_owner_id = excluded.real_owner_id, detected_at = excluded.detected_at
                """,
                (int(group_id), real_creator_id, datetime.now(timezone.utc).isoformat()),
            )
            con.commit()
    _clear_emergency_install(group_id)
    await sync_native_group_admins(group, group_id, force=True)
    mark_group_backup_dirty(group_id)
    await _post_activation_card_task(
        group, int(group_id), initiator_id, initiator_hash,
        real_creator_id, bool(real_creator_id), "executive",
        probe_already_sent=False,
        deliver_inline=True,
        already_persisted=True,
    )
    await send_group_text(
        group,
        "✅ ZIVO | نصب اضطراری با دو تایید انجام شد\n━━━━━━━━━━━━━━━━━━\n"
        "🛡 ادمین آغازکننده به عنوان مالک اجرایی زیوو ثبت شد.\n"
        "👑 مالک اصلی گروه در رکورد مالکیت حفظ شد.\n"
        "🔁 اگر مالک اصلی دوباره قابل استفاده شود، زیوو مالکیت را خودکار به او برمی گرداند.\n"
        "━━━━━━━━━━━━━━━━━━\n🔐 ZIVO | RECOVERY INSTALL",
    )
    return True


