def _private_message_text(message: Any) -> str:
    return str(
        getattr(message, "raw_text", None)
        or getattr(message, "message", None)
        or ""
    )


def _private_message_id(message: Any) -> Optional[int]:
    if message is None:
        return None
    if isinstance(message, (list, tuple)):
        for item in message:
            mid = safe_int(getattr(item, "id", None))
            if mid is not None:
                return int(mid)
        return None
    mid = safe_int(getattr(message, "id", None))
    return int(mid) if mid is not None else None


def _private_history_items(value: Any) -> List[Any]:
    if value is None:
        return []
    if isinstance(value, (list, tuple)):
        return list(value)
    try:
        if not isinstance(value, (str, bytes, dict)):
            return list(value)
    except Exception:
        pass
    return [value]


async def verify_private_delivery(
    target: Any,
    text: str,
    sent: Optional[Any] = None,
    *,
    user_id: Optional[int] = None,
    path: str = "direct",
) -> Tuple[bool, Optional[int]]:
    """Verify that the outgoing private message is actually visible in server history."""
    expected = str(text or "").replace("\r\n", "\n").strip()
    sent_id = _private_message_id(sent)

    for attempt in range(1, PRIVATE_DELIVERY_VERIFY_ATTEMPTS + 1):
        if attempt > 1:
            await asyncio.sleep(PRIVATE_DELIVERY_VERIFY_DELAY * attempt)

        if sent_id is not None:
            try:
                fetched = await asyncio.wait_for(
                    client.get_messages(target, ids=int(sent_id)),
                    timeout=10,
                )
                for message in _private_history_items(fetched):
                    if message is None:
                        continue
                    body = _private_message_text(message).replace("\r\n", "\n").strip()
                    if body == expected and bool(getattr(message, "out", True)):
                        log.info(
                            "private delivery readback PASS | user=%s path=%s message=%s attempt=%s",
                            user_id, path, sent_id, attempt,
                        )
                        return True, int(sent_id)
            except Exception as exc:
                log.debug(
                    "private delivery id readback failed | user=%s path=%s message=%s attempt=%s | %s: %s",
                    user_id, path, sent_id, attempt, type(exc).__name__, exc,
                )

        try:
            history = await asyncio.wait_for(
                client.get_messages(target, limit=12),
                timeout=12,
            )
            for message in _private_history_items(history):
                if message is None or not bool(getattr(message, "out", False)):
                    continue
                body = _private_message_text(message).replace("\r\n", "\n").strip()
                if body != expected:
                    continue
                mid = safe_int(getattr(message, "id", None))
                if sent_id is not None and mid is not None and int(mid) != int(sent_id):
                    continue
                message_date = getattr(message, "date", None)
                if sent_id is None and isinstance(message_date, datetime):
                    if message_date.tzinfo is None:
                        message_date = message_date.replace(tzinfo=timezone.utc)
                    age = (datetime.now(timezone.utc) - message_date.astimezone(timezone.utc)).total_seconds()
                    if age < -5 or age > 30:
                        continue
                log.info(
                    "private delivery readback PASS | user=%s path=%s message=%s attempt=%s source=history",
                    user_id, path, mid, attempt,
                )
                return True, int(mid) if mid is not None else sent_id
        except Exception as exc:
            log.debug(
                "private delivery history readback failed | user=%s path=%s attempt=%s | %s: %s",
                user_id, path, attempt, type(exc).__name__, exc,
            )

    log.warning(
        "private delivery readback FAIL | user=%s path=%s sent_id=%s chars=%s",
        user_id, path, sent_id, len(expected),
    )
    return False, sent_id


async def send_private(target: Any, text: str, verify_delivery: bool = False) -> Any:
    """Fast private send; critical flows can request server-history verification."""
    if OFFICIAL_CONTROL_ONLY:
        # 96.41: account sessions are execution workers only. All user-facing
        # private communication belongs to the official bot control plane.
        return SimpleNamespace(id=0, official_control_only=True)
    user_id = safe_int(getattr(target, "user_id", None))
    if _private_not_found_cooldown_active(user_id):
        raise RuntimeError(f"PRIVATE_TARGET_NOT_FOUND_COOLDOWN:{int(user_id or 0)}")
    log.debug(
        "private send attempt | user=%s path=direct target=%s chars=%s",
        user_id, type(target).__name__, len(str(text or "")),
    )
    first_error: Optional[BaseException] = None
    first_sent: Optional[Any] = None
    try:
        first_sent = await client.send_message(
            target,
            text,
            parse_mode=None,
            link_preview=False,
        )
        if not verify_delivery:
            return first_sent
        ok, _ = await verify_private_delivery(
            target, text, first_sent, user_id=user_id, path="direct"
        )
        if ok:
            return first_sent
        first_error = RuntimeError("PRIVATE_READBACK_FAILED:direct")
    except Exception as exc:
        first_error = exc
        log.warning(
            "private send direct failed | user=%s | %s: %s",
            user_id, type(exc).__name__, exc,
        )
        # A first 404 may still be a stale cached peer. Keep the existing one-time
        # fresh-peer recovery; only a confirmed retry 404 enters cooldown below.

    if user_id is None or user_id <= 0:
        if first_error is not None:
            raise first_error
        raise RuntimeError("PRIVATE_SEND_FAILED")

    _private_peer_cache.pop(int(user_id), None)
    fresh = await resolve_private_target(None, int(user_id))
    if fresh is None:
        if first_error is not None:
            raise first_error
        raise RuntimeError("PRIVATE_TARGET_REFRESH_FAILED")

    if first_sent is not None and verify_delivery:
        already_ok, _ = await verify_private_delivery(
            fresh, text, first_sent, user_id=int(user_id), path="fresh-readback"
        )
        if already_ok:
            _private_peer_cache[int(user_id)] = fresh
            return first_sent

    log.debug(
        "private send attempt | user=%s path=fresh-peer target=%s chars=%s",
        user_id, type(fresh).__name__, len(str(text or "")),
    )
    try:
        sent = await client.send_message(
            fresh,
            text,
            parse_mode=None,
            link_preview=False,
        )
        if not verify_delivery:
            _private_peer_cache[int(user_id)] = fresh
            return sent
        ok, _ = await verify_private_delivery(
            fresh, text, sent, user_id=int(user_id), path="fresh-peer"
        )
        if ok:
            _private_peer_cache[int(user_id)] = fresh
            log.info("private send recovered after peer refresh | user=%s", user_id)
            return sent
        raise RuntimeError("PRIVATE_READBACK_FAILED:fresh-peer")
    except Exception as exc:
        if _is_private_not_found_error(exc):
            _mark_private_not_found_cooldown(user_id)
            log.info(
                "private target 404 cooldown | user=%s seconds=%s future-retries=skipped",
                user_id, int(PRIVATE_NOT_FOUND_COOLDOWN_SECONDS),
            )
        log.warning(
            "private send retry failed | user=%s first=%s: %s retry=%s: %s",
            user_id,
            type(first_error).__name__ if first_error is not None else "None",
            first_error,
            type(exc).__name__, exc,
        )
        raise


async def send_private_from_event(event: Optional[Any], target: Any, text: str, verify_delivery: bool = False) -> Any:
    """Priority private send. Live inbound events answer through event.respond first.

    This avoids an InputPeer/access-hash lookup on the critical private-message path.
    Direct peer sending remains the recovery path for watchdog/raw/private jobs.
    """
    if OFFICIAL_CONTROL_ONLY:
        return SimpleNamespace(id=0, official_control_only=True)
    primary_error: Optional[BaseException] = None
    event_user_id = safe_int(getattr(event, "sender_id", None)) if event is not None else None

    if event is not None:
        responder = getattr(event, "respond", None)
        if callable(responder):
            try:
                sent = await asyncio.wait_for(
                    responder(text, parse_mode=None, link_preview=False),
                    timeout=4.0,
                )
                if event_user_id is not None and event_user_id > 0:
                    event_target = private_target_from_event(event)
                    if isinstance(event_target, types.InputPeerUser):
                        _private_peer_cache[int(event_user_id)] = event_target
                if not verify_delivery:
                    return sent
                verify_target = target
                if event_user_id is not None and event_user_id > 0:
                    try:
                        verify_target = private_target_from_event(event)
                    except Exception:
                        pass
                ok, _ = await verify_private_delivery(
                    verify_target,
                    text,
                    sent,
                    user_id=event_user_id,
                    path="event-respond",
                )
                if ok:
                    return sent
                primary_error = RuntimeError("PRIVATE_READBACK_FAILED:event-respond")
            except Exception as exc:
                primary_error = exc
                log.debug(
                    "private event-respond fallback | user=%s | %s: %s",
                    event_user_id, type(exc).__name__, exc,
                )

    try:
        return await send_private(target, text, verify_delivery=verify_delivery)
    except Exception as exc:
        if primary_error is None:
            primary_error = exc
        log.warning(
            "private direct-send recovery | user=%s | %s: %s",
            event_user_id if event_user_id is not None else safe_int(getattr(target, "user_id", None)),
            type(exc).__name__,
            exc,
        )

    if event is not None:
        replier = getattr(event, "reply", None)
        if callable(replier):
            try:
                sent = await asyncio.wait_for(
                    replier(text, parse_mode=None, link_preview=False),
                    timeout=4.0,
                )
                if not verify_delivery:
                    return sent
                verify_target = target
                ok, _ = await verify_private_delivery(
                    verify_target, text, sent, user_id=event_user_id, path="event-reply"
                )
                if ok:
                    return sent
                raise RuntimeError("PRIVATE_READBACK_FAILED:event-reply")
            except Exception as exc:
                log.warning(
                    "private event-reply recovery failed | user=%s | %s: %s",
                    event_user_id, type(exc).__name__, exc,
                )

    if primary_error is not None:
        raise primary_error
    raise RuntimeError("PRIVATE_SEND_FAILED")


async def send_private_copyable_from_event(
    event: Optional[Any],
    target: Any,
    text: str,
    commands: List[str],
) -> Any:
    # In a live private event, reliability and latency beat formatting metadata.
    # The command text itself remains fully copyable as plain text.
    if event is not None:
        return await send_private_from_event(event, target, text, verify_delivery=False)
    await send_copyable_command_text(target, text, commands)
    return None


async def safe_private_reply(
    event: Optional[Any],
    target: Any,
    text: str,
    *,
    label: str = "reply",
) -> bool:
    try:
        await send_private_from_event(event, target, text, verify_delivery=True)
        log.info(
            "private UX delivery PASS | label=%s user=%s",
            label,
            safe_int(getattr(event, "sender_id", None)) if event is not None else safe_int(getattr(target, "user_id", None)),
        )
        return True
    except Exception as exc:
        log.warning(
            "private UX delivery FAIL | label=%s user=%s | %s: %s",
            label,
            safe_int(getattr(event, "sender_id", None)) if event is not None else safe_int(getattr(target, "user_id", None)),
            type(exc).__name__, exc,
        )
        return False


def private_target_from_event(event: Any) -> Any:
    """
    Prefer peers carried/cached by the incoming update. If SPlusthon did not
    expose one, use access_hash=0 for the user who just messaged us, avoiding
    users.GetUsersRequest entirely.
    """
    target = getattr(event, "input_chat", None) or getattr(event, "input_sender", None)
    if target is not None:
        return target

    uid = safe_int(getattr(event, "sender_id", None)) or safe_int(getattr(event, "chat_id", None))
    if uid is None:
        raise RuntimeError("PRIVATE_TARGET_MISSING")
    return types.InputPeerUser(uid, 0)


async def resolve_required_channel(channel_name: str) -> Any:
    cached = REQUIRED_CHANNEL_INPUTS.get(channel_name)
    if cached is not None:
        return cached

    # Username resolution uses contacts.ResolveUsernameRequest, not GetUsersRequest.
    resolved = await client(functions.contacts.ResolveUsernameRequest(channel_name.lstrip("@")))
    channel = None
    for chat in getattr(resolved, "chats", []) or []:
        if isinstance(chat, types.Channel):
            channel = utils.get_input_channel(chat)
            break

    if channel is None:
        raise RuntimeError(f"REQUIRED_CHANNEL_NOT_FOUND:{channel_name}")

    REQUIRED_CHANNEL_INPUTS[channel_name] = channel
    return channel


def participant_user_id(participant: Any) -> Optional[int]:
    if participant is None:
        return None

    uid = safe_int(getattr(participant, "user_id", None))
    if uid is not None:
        return uid

    peer = getattr(participant, "peer", None)
    uid = safe_int(getattr(peer, "user_id", None))
    if uid is not None:
        return uid

    return None


def admin_event_subject_and_state(event: Any) -> Tuple[Optional[int], Optional[bool]]:
    """
    Return (subject_user_id, is_member_after_event) for membership-changing
    admin-log events.

    For direct join/leave actions, original.user_id is the affected user.
    For ParticipantInvite, the actor may be the inviter, so the invited
    participant inside the action is used instead.
    """
    action = getattr(event, "action", None)

    if isinstance(action, types.ChannelAdminLogEventActionParticipantLeave):
        return safe_int(getattr(event, "user_id", None)), False

    if isinstance(
        action,
        (
            types.ChannelAdminLogEventActionParticipantJoin,
            types.ChannelAdminLogEventActionParticipantJoinByInvite,
            types.ChannelAdminLogEventActionParticipantJoinByRequest,
        ),
    ):
        return safe_int(getattr(event, "user_id", None)), True

    if isinstance(action, types.ChannelAdminLogEventActionParticipantInvite):
        participant = (
            getattr(action, "participant", None)
            or getattr(event, "new", None)
        )
        return participant_user_id(participant), True

    # Ban/kick may also mean the user is no longer a member.
    if isinstance(action, types.ChannelAdminLogEventActionParticipantToggleBan):
        new_participant = getattr(action, "new_participant", None)
        uid = participant_user_id(new_participant)
        if isinstance(new_participant, types.ChannelParticipantBanned):
            left = bool(getattr(new_participant, "left", False))
            kicked = bool(getattr(new_participant, "kicked_by", None))
            if left or kicked:
                return uid, False

    return None, None


async def membership_from_admin_log(
    channel_name: str,
    channel_input: Any,
    user_id: int,
) -> Optional[bool]:
    """
    Soroush limits participant enumeration, even for admins. The channel admin
    log is a second signal: the newest join/leave/invite event for a user gives
    the latest observable membership state.

    Returns:
        True  -> newest observed event says joined
        False -> newest observed event says left/kicked
        None  -> no usable event was found
    """
    try:
        events = await client.get_admin_log(
            channel_input,
            limit=MEMBERSHIP_ADMIN_LOG_LIMIT,
            join=True,
            leave=True,
            invite=True,
            restrict=True,
            unrestrict=True,
            ban=True,
            unban=True,
        )
    except Exception as exc:
        log.warning(
            "membership admin-log failed | channel=%s user=%s | %s: %s",
            channel_name,
            user_id,
            type(exc).__name__,
            exc,
        )
        return None

    log.info(
        "membership admin-log fetched | channel=%s user=%s events=%s",
        channel_name,
        user_id,
        len(events),
    )

    # get_admin_log is newest -> oldest. First matching state is authoritative.
    for event in events:
        subject_id, state = tag_admin_event_subject_and_state(event)
        if subject_id == int(user_id) and state is not None:
            log.info(
                "membership admin-log | channel=%s user=%s found=%s event=%s",
                channel_name,
                user_id,
                state,
                type(getattr(event, "action", None)).__name__,
            )
            return state

    log.info(
        "membership admin-log | channel=%s user=%s found=unknown events=%s",
        channel_name,
        user_id,
        len(events),
    )
    return None


async def direct_channel_participant_state(
    channel_name: str,
    channel_input: Any,
    user_id: int,
    participant_peer: Optional[Any] = None,
) -> Optional[bool]:
    """Ask Soroush for one exact channel/user membership relation.

    SPlusthon exposes channels.GetParticipantRequest for this purpose. A
    concrete ChannelParticipant response is a much stronger signal than
    enumerating a possibly truncated participant list. Only explicit
    non-participant errors are converted to False; transport/permission
    failures stay None so the legacy scan/admin-log path can be used.
    """
    peer = participant_peer
    if peer is None:
        peer = types.InputPeerUser(int(user_id), 0)

    try:
        result = await asyncio.wait_for(
            client(
                functions.channels.GetParticipantRequest(
                    channel=channel_input,
                    participant=peer,
                )
            ),
            timeout=PRIVATE_MEMBERSHIP_DIRECT_TIMEOUT_SECONDS,
        )
    except asyncio.TimeoutError:
        log.info(
            "membership direct inconclusive | channel=%s user=%s reason=timeout",
            channel_name, user_id,
        )
        return None
    except Exception as exc:
        marker = f"{type(exc).__name__}: {exc}".upper().replace("-", "_")
        if any(token in marker for token in (
            "USER_NOT_PARTICIPANT",
            "USERNOTPARTICIPANT",
            "NOT_PARTICIPANT",
            "NOT PARTICIPANT",
        )):
            log.info(
                "membership FAIL | channel=%s user=%s source=direct error=%s",
                channel_name, user_id, type(exc).__name__,
            )
            return False
        log.info(
            "membership direct inconclusive | channel=%s user=%s error=%s",
            channel_name, user_id, type(exc).__name__,
        )
        return None

    participant = getattr(result, "participant", None)
    if participant is None:
        log.info(
            "membership direct inconclusive | channel=%s user=%s reason=no-participant",
            channel_name, user_id,
        )
        return None

    kind = type(participant).__name__.upper()
    if "CHANNELPARTICIPANTLEFT" in kind:
        log.info(
            "membership FAIL | channel=%s user=%s source=direct kind=%s",
            channel_name, user_id, kind,
        )
        return False

    if "CHANNELPARTICIPANTBANNED" in kind:
        left = bool(getattr(participant, "left", False))
        kicked = safe_int(getattr(participant, "kicked_by", None)) or 0
        state = not (left or kicked)
        log.info(
            "membership %s | channel=%s user=%s source=direct kind=%s",
            "PASS" if state else "FAIL", channel_name, user_id, kind,
        )
        return state

    if "CHANNELPARTICIPANT" in kind:
        log.info(
            "membership PASS | channel=%s user=%s source=direct kind=%s",
            channel_name, user_id, kind,
        )
        return True

    log.info(
        "membership direct inconclusive | channel=%s user=%s kind=%s",
        channel_name, user_id, kind,
    )
    return None


async def check_channel_membership(
    channel_name: str,
    user_id: int,
    participant_peer: Optional[Any] = None,
) -> Optional[bool]:
    """Hybrid membership check, direct-first.

    1) GetParticipantRequest asks Soroush for the exact channel/user relation.
    2) Only if that is inconclusive, keep the existing bounded participant scan.
    3) Admin-log history remains the final fallback.
    """
    cache_key = (channel_name, int(user_id))
    now = time.monotonic()
    cached = MEMBERSHIP_CACHE.get(cache_key)
    if cached and now - cached[0] <= MEMBERSHIP_CACHE_TTL:
        return cached[1]

    channel_input = await resolve_required_channel(channel_name)

    direct_state = await direct_channel_participant_state(
        channel_name,
        channel_input,
        int(user_id),
        participant_peer=participant_peer,
    )
    if direct_state is not None:
        MEMBERSHIP_CACHE[cache_key] = (time.monotonic(), direct_state)
        return direct_state

    offset = 0
    scanned = 0
    visible_count = None

    while scanned < MEMBERSHIP_SCAN_MAX:
        limit = min(MEMBERSHIP_SCAN_PAGE, MEMBERSHIP_SCAN_MAX - scanned)

        result = await client(
            functions.channels.GetParticipantsRequest(
                channel=channel_input,
                filter=types.ChannelParticipantsSearch(""),
                offset=offset,
                limit=limit,
                hash=0,
            )
        )

        users = list(getattr(result, "users", []) or [])
        participants = list(getattr(result, "participants", []) or [])
        visible_count = safe_int(getattr(result, "count", None))

        for user in users:
            if safe_int(getattr(user, "id", None)) == int(user_id):
                MEMBERSHIP_CACHE[cache_key] = (time.monotonic(), True)
                log.info(
                    "membership PASS | channel=%s user=%s source=participant_scan scanned=%s count=%s",
                    channel_name,
                    user_id,
                    scanned + len(users),
                    visible_count,
                )
                return True

        batch_size = max(len(users), len(participants))
        scanned += batch_size

        if batch_size == 0:
            break

        offset += batch_size

        if visible_count is not None and offset >= visible_count:
            break

        if batch_size < limit:
            break

    log.info(
        "membership participant-scan inconclusive | channel=%s user=%s scanned=%s count=%s",
        channel_name,
        user_id,
        scanned,
        visible_count,
    )

    admin_state = await membership_from_admin_log(
        channel_name,
        channel_input,
        user_id,
    )

    if admin_state is not None:
        MEMBERSHIP_CACHE[cache_key] = (time.monotonic(), admin_state)
        return admin_state

    MEMBERSHIP_CACHE[cache_key] = (time.monotonic() - MEMBERSHIP_CACHE_TTL + 5.0, None)
    return None


async def check_required_membership(
    user_id: int,
    participant_peer: Optional[Any] = None,
) -> Tuple[bool, List[str], List[str]]:
    missing: List[str] = []
    unknown: List[str] = []

    for channel_name in REQUIRED_CHANNELS:
        try:
            state = await check_channel_membership(
                channel_name,
                user_id,
                participant_peer=participant_peer,
            )

            if state is True:
                continue

            if state is False:
                missing.append(channel_name)
                log.info(
                    "membership FAIL | channel=%s user=%s",
                    channel_name,
                    user_id,
                )
            else:
                unknown.append(channel_name)
                log.info(
                    "membership UNKNOWN | channel=%s user=%s",
                    channel_name,
                    user_id,
                )

        except Exception as exc:
            log.warning(
                "membership check failed | channel=%s user=%s | %s: %s",
                channel_name,
                user_id,
                type(exc).__name__,
                exc,
            )
            unknown.append(channel_name)

    allowed = not missing and not unknown
    return allowed, missing, unknown



_private_channel_notice_v83_memory: set[int] = set()


def _private_channel_notice_v83_seen(user_id: int) -> bool:
    uid = int(user_id)
    if uid in _private_channel_notice_v83_memory:
        return True
    try:
        with db_connect() as con:
            row = con.execute(
                "SELECT user_id FROM private_channel_notice_v83 WHERE user_id = ?",
                (uid,),
            ).fetchone()
        if row is not None:
            _private_channel_notice_v83_memory.add(uid)
            return True
    except Exception as exc:
        log.debug(
            "private channel notice read skipped | user=%s | %s: %s",
            uid, type(exc).__name__, exc,
        )
    return False


def _mark_private_channel_notice_v83(user_id: int) -> None:
    uid = int(user_id)
    _private_channel_notice_v83_memory.add(uid)
    now = datetime.now(timezone.utc).isoformat()
    try:
        with db_connect() as con:
            con.execute(
                """
                INSERT INTO private_channel_notice_v83 (user_id, notice_sent_at, source)
                VALUES (?, ?, 'private-first-message')
                ON CONFLICT(user_id) DO UPDATE SET
                    notice_sent_at = excluded.notice_sent_at,
                    source = excluded.source
                """,
                (uid, now),
            )
            con.commit()
    except Exception as exc:
        log.warning(
            "private channel notice write failed | user=%s | %s: %s",
            uid, type(exc).__name__, exc,
        )


def _private_membership_onboarding_row(user_id: int) -> Optional[sqlite3.Row]:
    try:
        with db_connect() as con:
            return con.execute(
                "SELECT user_id, checked_at, result, notice_sent FROM private_membership_onboarding WHERE user_id = ?",
                (int(user_id),),
            ).fetchone()
    except Exception as exc:
        log.debug(
            "private membership onboarding read skipped | user=%s | %s: %s",
            user_id, type(exc).__name__, exc,
        )
        return None


def _mark_private_membership_onboarding(user_id: int, result: str, notice_sent: bool) -> None:
    now = datetime.now(timezone.utc).isoformat()
    try:
        with db_connect() as con:
            con.execute(
                """
                INSERT INTO private_membership_onboarding (user_id, checked_at, result, notice_sent)
                VALUES (?, ?, ?, ?)
                ON CONFLICT(user_id) DO UPDATE SET
                    checked_at = excluded.checked_at,
                    result = excluded.result,
                    notice_sent = MAX(private_membership_onboarding.notice_sent, excluded.notice_sent)
                """,
                (int(user_id), now, str(result or "")[:80], 1 if notice_sent else 0),
            )
            con.commit()
    except Exception as exc:
        log.warning(
            "private membership onboarding write failed | user=%s | %s: %s",
            user_id, type(exc).__name__, exc,
        )


def _private_membership_row_age_seconds(row: Optional[Any]) -> float:
    if row is None:
        return float("inf")
    try:
        value = row["checked_at"]
    except Exception:
        try:
            value = getattr(row, "checked_at", None)
        except Exception:
            value = None
    if not value:
        return float("inf")
    try:
        stamp = datetime.fromisoformat(str(value))
        if stamp.tzinfo is None:
            stamp = stamp.replace(tzinfo=timezone.utc)
        return max(0.0, (datetime.now(timezone.utc) - stamp.astimezone(timezone.utc)).total_seconds())
    except Exception:
        return float("inf")


def _clear_membership_cache_for_user(user_id: int) -> None:
    uid = int(user_id)
    for channel_name in REQUIRED_CHANNELS:
        MEMBERSHIP_CACHE.pop((channel_name, uid), None)


