def private_question_help_key(text: str) -> Optional[str]:
    normalized = normalize_group_command(text).lower()
    if not normalized:
        return None
    question_markers = ("چیه", "چی هست", "چیست", "چطوری", "چجوری", "چگونه", "چیکار", "چه کار", "کارایی", "راهنمای", "توضیح", "دستور")
    if not any(marker in normalized for marker in question_markers):
        return None
    keyword_map = (
        (("اسپم", "ضداسپم", "فلود"), "anti_spam"),
        (("محدودیت پیام", "فاصله پیام"), "message_rate_limit"),
        (("تگ", "فراخوان"), "mass_tag"),
        (("ستینگ", "تنظیمات", "کپی ستینگ"), "settings_copy"),
        (("قفل",), "locks"),
        (("فیلتر",), "word_filter"),
        (("خوشامد", "خوش آمد"), "welcome"),
        (("قانون", "قوانین"), "rules"),
        (("بن", "سکوت", "مجازات"), "moderation"),
        (("اخطار", "خطا"), "manual_warning"),
        (("بکاپ", "پشتیبان"), "group_backup"),
        (("نصب", "فعال سازی", "فعال‌سازی"), "install"),
        (("مشخصات", "پروفایل", "نمایه", "لقب", "اسم"), "user_profile"),
        (("فونت", "استایل متن"), "font_styles"),
    )
    for words, key in keyword_map:
        if any(word in normalized for word in words):
            return key
    if "دستور" in normalized or "چه کار" in normalized or "چیکار" in normalized or "کارایی" in normalized:
        return "__command_list__"
    return None


async def replied_user_target(event: Any) -> Tuple[Optional[int], int, str]:
    """
    Return (user_id, access_hash, username) for the message being replied to.
    Uses SPlusthon Message.get_reply_message() and cached input_sender data.
    """
    if not bool(getattr(event, "is_reply", False)):
        return None, 0, ""

    reply = await event.get_reply_message()
    if reply is None:
        return None, 0, ""

    target_id = safe_int(getattr(reply, "sender_id", None))
    if target_id is None:
        return None, 0, ""

    input_sender = getattr(reply, "input_sender", None)
    access_hash = input_peer_access_hash(input_sender)

    sender_obj = getattr(reply, "sender", None)
    username = getattr(sender_obj, "username", None) or ""

    return target_id, access_hash, username


def event_reply_message_id(event: Any) -> Optional[int]:
    value = safe_int(getattr(event, "reply_to_msg_id", None))
    if value is not None:
        return int(value)
    message = getattr(event, "message", None) or event
    value = safe_int(getattr(message, "reply_to_msg_id", None))
    if value is not None:
        return int(value)
    reply_meta = getattr(message, "reply_to", None)
    value = safe_int(getattr(reply_meta, "reply_to_msg_id", None))
    if value is not None:
        return int(value)
    return None


def stats_reply_target(group_id: int, message_id: int) -> Optional[Tuple[int, int, str]]:
    try:
        with db_connect() as con:
            row = con.execute(
                "SELECT user_id FROM message_stats WHERE group_id = ? AND message_id = ? LIMIT 1",
                (int(group_id), int(message_id)),
            ).fetchone()
        if row is None:
            return None
        user_id = int(row["user_id"])
        member = stats_member_row(int(group_id), user_id)
        access_hash = int(member["access_hash"] or 0) if member is not None else 0
        username = str(member["username"] or "") if member is not None else ""
        return user_id, access_hash, username
    except Exception:
        return None


async def role_target_group_membership_proven(
    group: Any,
    group_id: int,
    user_id: int,
    access_hash: int = 0,
    participant_peer: Optional[Any] = None,
) -> bool:
    """Return True only when the explicit target is proven in this group."""
    if group is None or int(group_id) <= 0 or int(user_id) <= 0:
        return False
    try:
        group_input = utils.get_input_channel(group)
    except Exception:
        group_input = None
    peer = participant_peer
    if peer is None:
        try:
            peer = types.InputPeerUser(int(user_id), int(access_hash or 0))
        except Exception:
            peer = None
    state: Optional[bool] = None
    if group_input is not None:
        try:
            state = await direct_channel_participant_state(
                f"group:{int(group_id)}",
                group_input,
                int(user_id),
                participant_peer=peer,
            )
        except Exception as exc:
            log.debug(
                "role target direct membership deferred | group=%s target=%s | %s: %s",
                group_id, user_id, type(exc).__name__, exc,
            )
    if state is not None:
        return bool(state)

    # Basic chats do not support channels.GetParticipantRequest. A bounded
    # participant enumeration is the only safe fallback: absence/transport
    # uncertainty must never be treated as proof for a privileged mutation.
    try:
        members = await asyncio.wait_for(
            client.get_participants(group, limit=1000),
            timeout=10.0,
        )
    except Exception as exc:
        log.info(
            "role target membership unproven | group=%s target=%s | %s: %s",
            group_id, user_id, type(exc).__name__, exc,
        )
        return False
    return any(
        (safe_int(getattr(member, "id", None)) or 0) == int(user_id)
        for member in list(members or [])
    )


async def resolve_moderation_target_spec(
    group_id: int,
    spec: str,
    *,
    group: Any = None,
    strict_group_member: bool = False,
) -> Optional[Tuple[int, int, str]]:
    value = normalize_group_command(spec).strip()
    ascii_value = normalize_moderation_digits(value)
    if re.fullmatch(r"[0-9]{5,20}", ascii_value):
        uid = int(ascii_value)
        if uid <= 0 or uid > ((1 << 63) - 1) or uid in {SELF_USER_ID, *SYSTEM_USER_IDS}:
            return None
        state = manual_moderation_row(int(group_id), uid)
        member = stats_member_row(int(group_id), uid)
        username = str((state["username"] if state is not None else "") or (member["username"] if member is not None else "") or "")
        access_hash = int((state["access_hash"] if state is not None else 0) or (member["access_hash"] if member is not None else 0) or stats_access_hash(int(group_id), uid) or 0)
        if strict_group_member and not await role_target_group_membership_proven(
            group, int(group_id), uid, access_hash
        ):
            return None
        return uid, access_hash, username

    username = value.lstrip("@").lower()
    if not re.fullmatch(r"[a-zA-Z0-9_.]{3,64}", username):
        return None
    if strict_group_member:
        try:
            entity = await asyncio.wait_for(client.get_entity("@" + username), timeout=3.0)
        except Exception:
            return None
        uid = safe_int(getattr(entity, "id", None)) or 0
        if uid <= 0 or uid > ((1 << 63) - 1) or uid in {SELF_USER_ID, *SYSTEM_USER_IDS}:
            return None
        access_hash = int(safe_int(getattr(entity, "access_hash", None)) or 0)
        try:
            participant_peer = utils.get_input_peer(entity)
        except Exception:
            participant_peer = None
        if not await role_target_group_membership_proven(
            group,
            int(group_id),
            int(uid),
            access_hash,
            participant_peer=participant_peer,
        ):
            return None
        return int(uid), access_hash, str(getattr(entity, "username", None) or username)

    with db_connect() as con:
        row = con.execute(
            """
            SELECT user_id, username, access_hash FROM manual_moderation
            WHERE group_id = ? AND LOWER(username) = ?
            UNION ALL
            SELECT user_id, username, access_hash FROM stats_members
            WHERE group_id = ? AND LOWER(username) = ?
            LIMIT 1
            """,
            (int(group_id), username, int(group_id), username),
        ).fetchone()
    if row is not None:
        return int(row["user_id"]), int(row["access_hash"] or 0), str(row["username"] or username)
    try:
        entity = await asyncio.wait_for(client.get_entity("@" + username), timeout=3.0)
    except Exception:
        return None
    uid = safe_int(getattr(entity, "id", None)) or 0
    if uid <= 0 or uid in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        return None
    return int(uid), int(safe_int(getattr(entity, "access_hash", None)) or 0), str(getattr(entity, "username", None) or username)


async def moderation_reply_target(
    event: Any,
    group: Any,
    group_id: int,
    usage_command: str,
) -> Optional[Tuple[int, int, str]]:
    if not bool(getattr(event, "is_reply", False)):
        await send_group_text(
            group,
            "⚠️ روی پیام خود کاربر یا روی پیامی که فقط آیدی عددی کاربر داخلشه ریپلای کن.\n\n"
            f"دستور: {usage_command}",
        )
        return None

    actor_id = safe_int(getattr(event, "sender_id", None)) or 0
    reply_message_id = event_reply_message_id(event)
    if reply_message_id is not None:
        cached_reply = _recent_message_sender_hot.get((int(group_id), int(reply_message_id)))
        if cached_reply is not None:
            reply_sender, cached_hash, cached_username, cached_text = cached_reply
            explicit_id = extract_explicit_user_id(cached_text)
            if explicit_id is not None and (
                int(reply_sender) in {int(actor_id), SELF_USER_ID}
                or re.fullmatch(r"[۰-۹٠-٩0-9]{5,20}", normalize_group_command(cached_text))
            ):
                if explicit_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
                    await send_group_text(group, "❌ این دستور روی حساب زیوو یا حساب سیستمی قابل اجرا نیست.")
                    return None
                row = stats_member_row(group_id, explicit_id)
                username = str(row["username"] or "") if row is not None else ""
                access_hash = int(
                    _moderation_access_hash_hot.get((int(group_id), int(explicit_id)), 0)
                    or stats_access_hash(group_id, explicit_id)
                    or 0
                )
                log.debug(
                    "moderation reply RAM target | group=%s actor=%s target=%s numeric=1",
                    group_id, actor_id, explicit_id,
                )
                return int(explicit_id), access_hash, username

            target_id = int(reply_sender or 0)
            if target_id > 0 and target_id not in {SELF_USER_ID, *SYSTEM_USER_IDS}:
                if int(cached_hash or 0):
                    _moderation_access_hash_hot[(int(group_id), target_id)] = int(cached_hash)
                log.debug(
                    "moderation reply RAM target | group=%s actor=%s target=%s hash=%s",
                    group_id, actor_id, target_id, bool(cached_hash),
                )
                return target_id, int(cached_hash or 0), str(cached_username or "")

        db_reply = stats_reply_target(int(group_id), int(reply_message_id))
        if db_reply is not None:
            target_id, target_hash, target_username = db_reply
            if target_id not in {SELF_USER_ID, *SYSTEM_USER_IDS}:
                if target_hash:
                    _moderation_access_hash_hot[(int(group_id), int(target_id))] = int(target_hash)
                log.debug(
                    "moderation reply DB target | group=%s actor=%s target=%s hash=%s",
                    group_id, actor_id, target_id, bool(target_hash),
                )
                return int(target_id), int(target_hash or 0), str(target_username or "")

    try:
        reply = await asyncio.wait_for(event.get_reply_message(), timeout=2.0)
    except Exception as exc:
        log.debug(
            "moderation reply network lookup failed | group=%s actor=%s | %s: %s",
            group_id, actor_id, type(exc).__name__, exc,
        )
        await send_group_text(group, "⚠️ پیام هدف سریع پیدا نشد؛ روی پیام جدیدتر کاربر ریپلای کن و دوباره دستور رو بفرست.")
        return None
    if reply is None:
        await send_group_text(group, "⚠️ پیام ریپلای‌شده پیدا نشد؛ دوباره ریپلای کن.")
        return None

    reply_sender = safe_int(getattr(reply, "sender_id", None)) or 0
    reply_text = str(getattr(reply, "raw_text", None) or getattr(reply, "message", None) or "")
    explicit_id = extract_explicit_user_id(reply_text)

    if explicit_id is not None and (reply_sender in {actor_id, SELF_USER_ID} or re.fullmatch(r"[۰-۹٠-٩0-9]{5,20}", normalize_group_command(reply_text))):
        if explicit_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
            await send_group_text(group, "❌ این دستور روی حساب زیوو یا حساب سیستمی قابل اجرا نیست.")
            return None
        row = stats_member_row(group_id, explicit_id)
        username = str(row["username"] or "") if row is not None else ""
        access_hash = int(stats_access_hash(group_id, explicit_id) or 0)
        log.info(
            "moderation numeric target resolved | group=%s actor=%s target=%s hash=%s",
            group_id, actor_id, explicit_id, bool(access_hash),
        )
        return int(explicit_id), access_hash, username

    # Reuse the reply already fetched above. Calling get_reply_message() a second
    # time added an avoidable Soroush round-trip on every moderation command.
    target_id = int(reply_sender or 0)
    if target_id <= 0:
        await send_group_text(
            group,
            "⚠️ کاربر هدف پیدا نشد. روی پیام خود کاربر ریپلای کن یا اول آیدی عددی اون رو بفرست و روی همون آیدی ریپلای کن.",
        )
        return None
    if target_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        await send_group_text(group, "❌ این دستور روی حساب زیوو یا حساب سیستمی قابل اجرا نیست.")
        return None

    input_sender = getattr(reply, "input_sender", None)
    target_hash = int(input_peer_access_hash(input_sender) or 0)
    sender_obj = getattr(reply, "sender", None)
    target_username = str(getattr(sender_obj, "username", None) or "")
    if target_hash:
        _moderation_access_hash_hot[(int(group_id), int(target_id))] = int(target_hash)
    return int(target_id), int(target_hash), target_username


