def normalize_help_lookup_text(command_text: str) -> str:
    normalized = normalize_group_command(command_text)
    return re.sub(r"[\?\!\.\,\:\;]+$", "", normalized).strip()


def find_help_feature(command_text: str) -> Optional[Dict[str, Any]]:
    normalized = normalize_help_lookup_text(command_text)

    for feature in ZIVO_CAPABILITY_REGISTRY:
        candidates = tuple(feature.get("help_aliases", ()) or ()) + (str(feature.get("help_command") or ""),)
        for alias in candidates:
            if normalized == normalize_help_lookup_text(str(alias)):
                return feature

    return None


def help_feature_visible_for_actor(feature: Optional[Dict[str, Any]], actor_id: Optional[int]) -> bool:
    return feature is not None


def find_help_category(command_text: str) -> Optional[Dict[str, Any]]:
    normalized = normalize_help_lookup_text(command_text)
    for category in ZIVO_HELP_CATEGORIES:
        for alias in (category.get("aliases", ()) or ()):
            if normalized == normalize_help_lookup_text(str(alias)):
                return category
    return None


def find_help_feature_fuzzy(command_text: str) -> Optional[Dict[str, Any]]:
    normalized = normalize_help_lookup_text(command_text)
    if not normalized.startswith("راهنما "):
        return None
    query = normalized[len("راهنما "):].strip()
    if not query:
        return None
    exact = find_help_feature(normalized)
    if exact is not None:
        return exact
    scored: List[Tuple[int, Dict[str, Any]]] = []
    for feature in ZIVO_CAPABILITY_REGISTRY:
        haystacks: List[str] = [
            str(feature.get("title") or ""),
            str(feature.get("description") or ""),
            str(feature.get("help_command") or ""),
            " ".join(str(x) for x in (feature.get("help_aliases", ()) or ())),
        ]
        for command, description in (feature.get("command_details", ()) or ()):
            haystacks.extend((str(command), str(description)))
        for _section_title, commands in (feature.get("help_sections", ()) or ()):
            for command, description in commands:
                haystacks.extend((str(command), str(description)))
        hay = normalize_group_command(" ".join(haystacks))
        score = 0
        if query == normalize_group_command(str(feature.get("title") or "")):
            score += 100
        if query in hay:
            score += 20
        for word in query.split():
            if len(word) >= 2 and word in hay:
                score += 3
        if score:
            scored.append((score, feature))
    if not scored:
        return None
    scored.sort(key=lambda item: item[0], reverse=True)
    if len(scored) > 1 and scored[0][0] == scored[1][0]:
        return None
    return scored[0][1]


