def capability_category_text(
    category: Dict[str, Any],
) -> Tuple[str, List[str]]:
    feature_keys = set(category.get("feature_keys", ()) or ())
    features = [
        feature for feature in ZIVO_CAPABILITY_REGISTRY
        if feature.get("key") in feature_keys
    ]
    lines: List[str] = [
        f"{category['icon']} ZIVO | {category['title']}",
        "━━━━━━━━━━━━━━━━━━",
        "برای دیدن دستورات کامل هر بخش، راهنمای همان بخش را بفرست:",
    ]
    commands: List[str] = []
    for feature in features:
        help_command = str(feature["help_command"])
        lines.extend((
            "", f"{feature['icon']} {feature['title']}",
            f"└ {feature['description']}", f"⌁ {help_command}",
        ))
        commands.append(help_command)
    lines.extend((
        "", "━━━━━━━━━━━━━━━━━━",
        "💡 همه فرمان‌ها: لیست دستورات",
        "↩️ بازگشت به مرکز: راهنما",
        "⚡ ZIVO | HELP CATEGORY",
    ))
    commands.extend(("لیست دستورات", "راهنما"))
    return "\n".join(lines), commands


def capability_topic_text(
    feature: Dict[str, Any],
) -> Tuple[str, List[str]]:
    lines: List[str] = [
        f"{feature['icon']} ZIVO | راهنمای {feature['title']}",
        "━━━━━━━━━━━━━━━━━━",
        feature["description"],
    ]

    copy_commands: List[str] = []

    help_sections = feature.get(
        "help_sections",
        (),
    ) or ()

    if help_sections:
        for section_title, section_commands in help_sections:
            lines.extend(
                (
                    "",
                    f"▣ {section_title}",
                )
            )

            for command, description in section_commands:
                lines.extend(
                    (
                        f"⌁ {command}",
                        f"└ {description}",
                    )
                )
                copy_commands.append(
                    command
                )

    else:
        command_details = feature.get(
            "command_details",
            (),
        ) or ()

        if command_details:
            lines.extend(
                (
                    "",
                    "⚡ فرمان‌های فعال این بخش:",
                )
            )

            for command, description in command_details:
                lines.extend(
                    (
                        "",
                        f"⌁ {command}",
                        f"└ {description}",
                    )
                )
                copy_commands.append(command)

    lines.extend(
        (
            "",
            "━━━━━━━━━━━━━━━━━━",
            "📚 کانال دستورات زیوو:",
            "@ZIVOCMD",
            "https://splus.ir/ZIVOCMD",
            "",
            "💡 برای دیدن همه فرمان‌ها: لیست دستورات",
            "↩️ مرکز راهنما: راهنما",
            "",
            "⚡ ZIVO | COMMAND FILE",
        )
    )

    return "\n".join(lines), copy_commands


