def iran_utc_offset_text(value: datetime) -> str:
    offset = value.utcoffset()
    if offset is None:
        return "UTC+03:30"

    total_minutes = int(offset.total_seconds() // 60)
    sign = "+" if total_minutes >= 0 else "-"
    total_minutes = abs(total_minutes)
    hours, minutes = divmod(total_minutes, 60)

    return f"UTC{sign}{hours:02d}:{minutes:02d}"


def iran_date_time_text(
    value: Optional[datetime] = None,
) -> str:
    local = iran_datetime(value)
    jy, jm, jd = jalali_parts(local)
    weekday = PERSIAN_WEEKDAYS[local.weekday()]
    month_name = JALALI_MONTH_NAMES[jm - 1]

    jalali_date = f"{weekday}، {jd} {month_name} {jy}"
    jalali_numeric = f"{jy:04d}/{jm:02d}/{jd:02d}"
    gregorian_date = local.strftime("%Y/%m/%d")
    clock = local.strftime("%H:%M:%S")
    offset = iran_utc_offset_text(local)

    return (
        "🕰 ZIVO | زمان ایران\n\n"
        "📅 تاریخ امروز\n"
        f"{jalali_date}\n"
        f"└ {jalali_numeric}\n\n"
        "⏱ ساعت رسمی ایران\n"
        f"{clock}\n\n"
        "🌐 زمان مرجع\n"
        f"Asia/Tehran  |  {offset}\n\n"
        "📆 تاریخ میلادی\n"
        f"{gregorian_date}\n\n"
        "⚡ ZIVO | IRAN TIME"
    )


