FONT_TEXT_MAX_CHARS = max(20, min(240, int(os.getenv("ZIVO_FONT_TEXT_MAX_CHARS", "120"))))


def _font_linear_map(upper_start: int, lower_start: int, digit_start: Optional[int] = None) -> Dict[int, str]:
    mapping: Dict[int, str] = {}
    for index, ch in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZ"):
        mapping[ord(ch)] = chr(upper_start + index)
    for index, ch in enumerate("abcdefghijklmnopqrstuvwxyz"):
        mapping[ord(ch)] = chr(lower_start + index)
    if digit_start is not None:
        for index, ch in enumerate("0123456789"):
            mapping[ord(ch)] = chr(digit_start + index)
    return mapping


FONT_STYLE_MAPS: Tuple[Dict[int, str], ...] = (
    _font_linear_map(0x1D400, 0x1D41A, 0x1D7CE),  # mathematical bold
    _font_linear_map(0x1D5A0, 0x1D5BA, 0x1D7E2),  # sans serif
    _font_linear_map(0x1D5D4, 0x1D5EE, 0x1D7EC),  # sans bold
    _font_linear_map(0x1D608, 0x1D622, None),     # sans italic
    _font_linear_map(0x1D63C, 0x1D656, None),     # sans bold italic
    _font_linear_map(0x1D670, 0x1D68A, 0x1D7F6),  # monospace
    _font_linear_map(0xFF21, 0xFF41, 0xFF10),     # fullwidth
)

FONT_STYLE_WRAPPERS: Tuple[Tuple[str, str], ...] = (
    ("𓆩 ", " 𓆪"),
    ("『 ", " 』"),
    ("꧁ ", " ꧂"),
    ("༺ ", " ༻"),
    ("✦ ", " ✦"),
    ("♛ ", " ♛"),
    ("⫷ ", " ⫸"),
)


def _font_circled(text: str) -> str:
    out: List[str] = []
    for ch in text:
        if "A" <= ch <= "Z":
            out.append(chr(0x24B6 + ord(ch) - ord("A")))
        elif "a" <= ch <= "z":
            out.append(chr(0x24D0 + ord(ch) - ord("a")))
        elif ch == "0":
            out.append("⓪")
        elif "1" <= ch <= "9":
            out.append(chr(0x2460 + ord(ch) - ord("1")))
        else:
            out.append(ch)
    return "".join(out)


def _font_combining(text: str, mark: str) -> str:
    return "".join(ch + mark if not ch.isspace() else ch for ch in text)


def font_style_variants(text: str) -> Tuple[str, ...]:
    value = str(text or "").strip()
    variants: List[str] = []
    for mapping, wrapper in zip(FONT_STYLE_MAPS, FONT_STYLE_WRAPPERS):
        styled = value.translate(mapping)
        variants.append(f"{wrapper[0]}{styled}{wrapper[1]}")
    variants.append(f"★彡 {_font_circled(value)} 彡★")
    variants.append(f"〆 {_font_combining(value, chr(0x0332))} 〆")
    variants.append(f"乂 {_font_combining(value, chr(0x0336))} 乂")
    variants.append("• " + "  •  ".join(list(value)) + " •")
    variants.append(f"☬ 【{value}】 ☬")
    return tuple(variants[:12])


def parse_font_command(command_text: str) -> Optional[Dict[str, Any]]:
    normalized = normalize_group_command(command_text)
    if not normalized:
        return None
    if normalized == "فونت":
        return {"text": "", "error": "missing"}
    if not normalized.startswith("فونت "):
        return None
    content = normalized[len("فونت "):].strip()
    if not content:
        return {"text": "", "error": "missing"}
    if len(content) > FONT_TEXT_MAX_CHARS:
        return {"text": content, "error": "too_long"}
    return {"text": content, "error": None}


