def social_display_name(user_id: int, event: Optional[Any] = None) -> str:
    uid = int(user_id)
    entity = None
    if event is not None and safe_int(getattr(event, "sender_id", None)) == uid:
        entity = getattr(event, "sender", None)
    if entity is not None:
        observed = display_name(entity)
        if observed and observed != "کاربر":
            queue_global_profile_observation(uid, entity=entity)
            return str(observed)[:50]
    profile = get_global_user_profile(uid)
    username = str(profile.get("username") or "").strip()
    chosen = str(
        profile.get("preferred_name")
        or profile.get("nickname")
        or profile.get("observed_name")
        or ("@" + username if username else "")
        or f"کاربر {uid}"
    )
    return chosen[:50]


def social_recent_active_users(group_id: int, limit: int = 100) -> List[Dict[str, Any]]:
    """Return distinct humans seen in the latest N stored group messages."""
    with db_connect() as con:
        rows = con.execute(
            """
            WITH recent AS (
                SELECT user_id, MAX(message_id) AS latest_message
                FROM (
                    SELECT user_id, message_id
                    FROM message_stats
                    WHERE group_id=?
                    ORDER BY message_id DESC
                    LIMIT ?
                )
                GROUP BY user_id
            )
            SELECT r.user_id, r.latest_message,
                   COALESCE(g.preferred_name, '') AS preferred_name,
                   COALESCE(g.nickname, '') AS nickname,
                   COALESCE(g.observed_name, '') AS observed_name,
                   COALESCE(NULLIF(g.username, ''), NULLIF(s.username, ''), '') AS username,
                   COALESCE(s.access_hash, 0) AS access_hash
            FROM recent r
            LEFT JOIN global_user_profiles g ON g.user_id=r.user_id
            LEFT JOIN stats_members s ON s.group_id=? AND s.user_id=r.user_id
            ORDER BY r.latest_message DESC
            """,
            (int(group_id), max(2, min(100, int(limit))), int(group_id)),
        ).fetchall()
    result: List[Dict[str, Any]] = []
    for row in rows:
        uid = int(row["user_id"] or 0)
        if uid <= 0 or uid in {SELF_USER_ID, *SYSTEM_USER_IDS}:
            continue
        username = str(row["username"] or "")
        name = str(
            row["preferred_name"]
            or row["nickname"]
            or row["observed_name"]
            or ("@" + username if username else "")
            or f"کاربر {uid}"
        )[:50]
        result.append({
            "user_id": uid,
            "name": name,
            "username": username,
            "access_hash": int(row["access_hash"] or 0),
        })
    return result


def forwarded_user_id_from_event(event: Any) -> Optional[int]:
    message = getattr(event, "message", None) or event
    candidates: List[Any] = []
    for source in (event, message):
        for attr in ("fwd_from", "forward", "forward_info", "forward_header"):
            value = getattr(source, attr, None)
            if value is not None:
                candidates.append(value)
    for item in candidates:
        for attr in ("from_id", "saved_from_peer", "peer", "sender_id", "user_id"):
            value = getattr(item, attr, None)
            uid = safe_int(getattr(value, "user_id", None)) if value is not None else None
            uid = uid or safe_int(value)
            if uid is not None and int(uid) > 0:
                return int(uid)
    return None


async def resolve_social_target_group(
    event: Any,
    group_id: int,
    raw_spec: str = "",
) -> Optional[Tuple[int, int, str]]:
    if bool(getattr(event, "is_reply", False)):
        target_id, target_hash, username = await replied_user_target(event)
        if target_id is not None:
            return int(target_id), int(target_hash or 0), str(username or "")
    spec = normalize_group_command(raw_spec).strip()
    if not spec:
        return None
    resolved = await resolve_moderation_target_spec(int(group_id), spec)
    if resolved is not None:
        return int(resolved[0]), int(resolved[1] or 0), str(resolved[2] or "")
    return None


async def resolve_social_target_private(event: Optional[Any], raw_spec: str = "") -> Optional[Tuple[int, int, str]]:
    if event is not None:
        forwarded_id = forwarded_user_id_from_event(event)
        if forwarded_id is not None:
            return int(forwarded_id), 0, ""
    spec = normalize_group_command(raw_spec).strip()
    if not spec:
        return None
    ascii_spec = normalize_moderation_digits(spec)
    if re.fullmatch(r"[0-9]{5,20}", ascii_spec):
        return int(ascii_spec), 0, ""
    username = spec.lstrip("@").strip()
    if not re.fullmatch(r"[A-Za-z0-9_.]{3,64}", username):
        return None
    try:
        entity = await asyncio.wait_for(client.get_entity("@" + username), timeout=4.0)
    except Exception:
        return None
    uid = safe_int(getattr(entity, "id", None))
    if uid is None or uid <= 0:
        return None
    queue_global_profile_observation(int(uid), entity=entity)
    return int(uid), int(safe_int(getattr(entity, "access_hash", None)) or 0), str(getattr(entity, "username", None) or username)


_MARKET_ASYNC_CACHE_SECONDS = 120.0
_MARKET_ASYNC_FAILURE_COOLDOWN_SECONDS = 15.0
_MARKET_ASYNC_OUTER_TIMEOUT_SECONDS = 12.0
_market_snapshot_async_task: Optional[asyncio.Task] = None
_market_snapshot_async_task_loop: Optional[asyncio.AbstractEventLoop] = None
_market_snapshot_async_cache: Tuple[float, Dict[str, Any]] = (0.0, {})
_market_snapshot_async_failure_until = 0.0
_market_snapshot_async_timeout_logged: Optional[asyncio.Task] = None


def _market_snapshot_task_done(task: asyncio.Task) -> None:
    """Publish one shared provider result and open/close its retry circuit."""

    global _market_snapshot_async_task, _market_snapshot_async_task_loop
    global _market_snapshot_async_cache, _market_snapshot_async_failure_until
    global _market_snapshot_async_timeout_logged
    if _market_snapshot_async_task is not task:
        return
    _market_snapshot_async_task = None
    _market_snapshot_async_task_loop = None
    if _market_snapshot_async_timeout_logged is task:
        _market_snapshot_async_timeout_logged = None
    now_mono = time.monotonic()
    try:
        snapshot = task.result()
    except asyncio.CancelledError:
        return
    except Exception as exc:
        _market_snapshot_async_failure_until = max(
            _market_snapshot_async_failure_until,
            now_mono + _MARKET_ASYNC_FAILURE_COOLDOWN_SECONDS,
        )
        log.warning("market snapshot provider failed | %s: %s", type(exc).__name__, exc)
        return
    if not isinstance(snapshot, dict) or not snapshot:
        _market_snapshot_async_failure_until = max(
            _market_snapshot_async_failure_until,
            now_mono + _MARKET_ASYNC_FAILURE_COOLDOWN_SECONDS,
        )
        return
    is_stale = bool(snapshot.get("stale"))
    ttl = (
        _MARKET_ASYNC_FAILURE_COOLDOWN_SECONDS
        if is_stale
        else _MARKET_ASYNC_CACHE_SECONDS
    )
    _market_snapshot_async_cache = (now_mono + ttl, deepcopy(snapshot))
    _market_snapshot_async_failure_until = (
        now_mono + _MARKET_ASYNC_FAILURE_COOLDOWN_SECONDS
        if is_stale
        else 0.0
    )


async def _market_snapshot_async() -> Dict[str, Any]:
    """Return one deep-copied snapshot while coalescing every concurrent miss."""

    global _market_snapshot_async_task, _market_snapshot_async_task_loop
    global _market_snapshot_async_timeout_logged
    now_mono = time.monotonic()
    cache_until, cached_snapshot = _market_snapshot_async_cache
    if cached_snapshot and now_mono < cache_until:
        return deepcopy(cached_snapshot)
    if now_mono < _market_snapshot_async_failure_until:
        return {}

    loop = asyncio.get_running_loop()
    task = _market_snapshot_async_task
    if task is not None and task.done():
        _market_snapshot_task_done(task)
        cache_until, cached_snapshot = _market_snapshot_async_cache
        now_mono = time.monotonic()
        if cached_snapshot and now_mono < cache_until:
            return deepcopy(cached_snapshot)
        if now_mono < _market_snapshot_async_failure_until:
            return {}
        task = None
    if task is not None and _market_snapshot_async_task_loop is not loop:
        # Runtime uses one event loop.  Refuse to duplicate a still-running
        # provider call if an embedding test temporarily swaps event loops.
        return {}
    if task is None:
        task = asyncio.create_task(
            asyncio.to_thread(social_games.market_snapshot_data),
            name="zivo-market-provider",
        )
        _market_snapshot_async_task = task
        _market_snapshot_async_task_loop = loop
        task.add_done_callback(_market_snapshot_task_done)

    try:
        snapshot = await asyncio.wait_for(
            asyncio.shield(task),
            timeout=_MARKET_ASYNC_OUTER_TIMEOUT_SECONDS,
        )
        return deepcopy(snapshot) if isinstance(snapshot, dict) else {}
    except asyncio.TimeoutError:
        # shield() keeps the single shared call alive for later waiters.  Log
        # once per provider task so a burst cannot create a warning storm.
        if _market_snapshot_async_timeout_logged is not task:
            _market_snapshot_async_timeout_logged = task
            log.warning("market snapshot provider timed out; shared task retained")
        return {}
    except Exception:
        # The task callback records the bounded negative-cache window and logs
        # the provider error exactly once for all coalesced callers.
        if task.done():
            _market_snapshot_task_done(task)
        return {}


async def command_market_utility(target: Any, parsed: Dict[str, Any]) -> None:
    action = str(parsed.get("action") or "")
    if action == "calculate":
        result = parsed.get("arithmetic")
        if result is not None:
            await send_group_text(target, result.response_text())
        return
    snapshot = await _market_snapshot_async()
    response = market_tools.conversion_text(str(parsed.get("text") or ""), snapshot)
    if response is None:
        response = market_tools.market_snapshot_text(snapshot)
    await send_group_text(target, response)


async def command_market_card(target: Any) -> None:
    snapshot = await _market_snapshot_async()
    market_dir = TMP_DIR / "market"
    output_path = market_dir / f"zivo_market_{time.time_ns()}.png"
    card = await asyncio.to_thread(market_tools.render_market_card, snapshot, output_path)
    try:
        if card.has_image and card.image_path is not None:
            try:
                await asyncio.wait_for(
                    send_file_resilient(
                        target,
                        card.image_path,
                        caption=card.text,
                        parse_mode=None,
                    ),
                    timeout=120,
                )
                return
            except Exception as exc:
                log.warning("market card send fallback | %s: %s", type(exc).__name__, exc)
        await send_group_text(target, card.text)
    finally:
        try:
            output_path.unlink(missing_ok=True)
        except Exception:
            pass


async def command_social_group(
    event: Any,
    target: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None or int(actor_id) <= 0:
        return
    uid = int(actor_id)
    actor_name = social_display_name(uid, event)
    action = str(parsed.get("action") or "")

    if action.startswith("ttt_"):
        ttt_action = action.removeprefix("ttt_")
        text = social_games.tic_tac_toe(
            int(group_id), uid, actor_name, ttt_action,
            int(parsed.get("cell") or 0),
        )
        await send_group_text(target, text)
        return
    if action == "ship":
        active = await asyncio.to_thread(social_recent_active_users, int(group_id), 100)
        result = await asyncio.to_thread(social_games.choose_ship, int(group_id), active)
        users = list(result.get("users") or [])
        mentions = [
            (str(item.get("name") or item.get("user_id")), int(item.get("user_id") or 0), int(item.get("access_hash") or 0))
            for item in users
        ]
        await send_group_text_with_mentions(target, str(result.get("text") or ""), mentions)
        return
    if action == "market":
        await command_market_card(target)
        return
    if action == "distance":
        text = await asyncio.to_thread(
            social_games.distance_text,
            str(parsed.get("origin") or ""), str(parsed.get("destination") or ""),
        )
        await send_group_text(target, text)
        return
    if action == "meow_claim":
        luck = premium.meow_luck_multiplier(int(group_id))
        await send_group_text(target, await asyncio.to_thread(social_games.claim_meow, uid, luck))
        return
    if action == "meow_profile":
        section = await asyncio.to_thread(social_games.profile_section, uid)
        await send_group_text(target, "🐾 ZIVO | دارایی من\n━━━━━━━━━━━━━━━━━━\n" + section)
        return
    if action == "transfer_prepare":
        resolved = await resolve_social_target_group(event, int(group_id), str(parsed.get("target") or ""))
        if resolved is None:
            await send_group_text(
                target,
                "↩️ روی پیام مقصد ریپلای کن و بنویس: انتقال میو 50\nیا مستقیم بنویس: انتقال میو 50 @username",
            )
            return
        recipient_id = int(resolved[0])
        text = await asyncio.to_thread(
            social_games.prepare_transfer, uid, recipient_id,
            int(parsed.get("amount") or 0), f"group:{group_id}",
        )
        await send_group_text(target, text)
        return
    if action == "transfer_confirm":
        await send_group_text(target, await asyncio.to_thread(social_games.confirm_transfer, uid, actor_name))
        return
    if action == "transfer_cancel":
        await send_group_text(target, await asyncio.to_thread(social_games.cancel_transfer, uid))
        return
    if action == "wager_start":
        text = await asyncio.to_thread(
            social_games.create_wager, int(group_id), uid,
            int(parsed.get("stake") or 0), actor_name,
        )
        await send_group_text(target, text)
        return
    if action == "wager_accept":
        info = await asyncio.to_thread(social_games.open_wager_info, int(group_id))
        creator_name = social_display_name(int(info.get("creator_id") or 0)) if info else "بازیکن اول"
        text = await asyncio.to_thread(
            social_games.accept_wager, int(group_id), uid, creator_name, actor_name,
        )
        await send_group_text(target, text)
        return
    if action == "wager_cancel":
        await send_group_text(target, await asyncio.to_thread(social_games.cancel_wager, int(group_id), uid))
        return

    basic_calls = {
        "pet_shop": (social_games.pet_shop_text, ()),
        "pet_buy": (social_games.buy_pet, (uid, str(parsed.get("spec") or ""), premium.pet_discount_percent(int(group_id)))),
        "pet_status": (social_games.pet_status, (uid,)),
        "pet_name": (social_games.name_pet, (uid, str(parsed.get("name") or ""))),
        "pet_feed": (social_games.feed_pet, (uid,)),
        "pet_play": (social_games.play_with_pet, (uid,)),
        "pet_call": (social_games.pet_call, (uid, str(parsed.get("call") or "name"))),
        "house_shop": (social_games.house_shop_text, ()),
        "house_mine": (social_games.my_houses_text, (uid,)),
        "house_market": (social_games.house_marketplace_text, ()),
        "house_buy": (social_games.buy_house, (uid, str(parsed.get("spec") or ""))),
        "house_sell_instant": (social_games.instant_sell_house, (uid, int(parsed.get("ownership_id") or 0))),
        "house_list": (social_games.list_house, (uid, int(parsed.get("ownership_id") or 0), int(parsed.get("price") or 0))),
        "house_cancel_listing": (social_games.cancel_house_listing, (uid, int(parsed.get("listing_id") or 0))),
        "house_buy_listing": (social_games.buy_listed_house, (uid, int(parsed.get("listing_id") or 0))),
    }
    call = basic_calls.get(action)
    if call is not None:
        await send_group_text(target, await asyncio.to_thread(call[0], *call[1]))
        return
    await send_group_text(target, social_games.social_help_text())


