async def maybe_handle_social_private_intent(
    event: Optional[Any], target: Any, sender_id: int, raw_text: str,
) -> bool:
    intent = await asyncio.to_thread(social_games.get_intent, int(sender_id))
    if not intent or str(intent.get("kind") or "") != "transfer_target":
        return False
    normalized = normalize_group_command(raw_text)
    if normalized in {"لغو", "لغو انتقال", "انصراف"}:
        await asyncio.to_thread(social_games.clear_intent, int(sender_id))
        await send_private_from_event(event, target, "✅ درخواست انتقال لغو شد.")
        return True
    resolved = await resolve_social_target_private(event, normalized)
    if resolved is None:
        await send_private_from_event(event, target, "❌ مقصد شناخته نشد؛ یک @username معتبر بفرست یا پیام کاربر را فوروارد کن.")
        return True
    amount = int((intent.get("payload") or {}).get("amount") or 0)
    await asyncio.to_thread(social_games.clear_intent, int(sender_id))
    text = await asyncio.to_thread(
        social_games.prepare_transfer, int(sender_id), int(resolved[0]), amount, "private",
    )
    await send_private_from_event(event, target, text)
    return True


