async def detect_and_cache_real_group_owner(
    event: Any,
    group: Any,
    group_id: int,
) -> Optional[sqlite3.Row]:
    real_owner = await find_group_creator(group)
    real_owner_id = safe_int(getattr(real_owner, "id", None)) if real_owner else None

    if real_owner_id is None:
        return get_real_owner_recovery_cache(group_id)

    event_sender_id = safe_int(getattr(event, "sender_id", None))
    input_sender = getattr(event, "input_sender", None)

    # If the command sender is the detected creator, the incoming event gives
    # us the best available access_hash for a clickable profile mention.
    access_hash = safe_int(getattr(real_owner, "access_hash", None)) or 0
    username = getattr(real_owner, "username", None) or ""

    if event_sender_id == real_owner_id:
        access_hash = input_peer_access_hash(input_sender) or access_hash
        username = input_peer_username(input_sender) or username

    save_real_owner_recovery_cache(
        group_id=group_id,
        real_owner_id=real_owner_id,
        username=username,
        access_hash=access_hash,
    )

    log.info(
        "real-owner recovery cached | group=%s owner=%s",
        group_id,
        real_owner_id,
    )

    return get_real_owner_recovery_cache(group_id)


async def wait_until_zivo_demoted(
    group: Any,
    attempts: int = 8,
    delay: float = 0.65,
) -> bool:
    """
    Soroush admin changes may propagate with a short delay.
    Re-check several times instead of immediately claiming ZIVO is still admin.
    """
    for attempt in range(1, attempts + 1):
        is_admin, is_creator = await bot_admin_state(group)
        if not is_admin and not is_creator:
            log.info(
                "bot demotion confirmed | group=%s attempt=%s",
                getattr(group, "id", "?"),
                attempt,
            )
            return True

        if attempt < attempts:
            await asyncio.sleep(delay)

    return False


async def command_check_real_owner(
    event: Any,
    group: Any,
    group_id: int,
    installation: sqlite3.Row,
) -> None:
    """
    Recovery when ZIVO ownership was mistakenly transferred to another admin.

    Important:
    the person to demote is the mistaken USER who currently owns ZIVO,
    not the ZIVO account itself.
    """
    sender_id = safe_int(getattr(event, "sender_id", None))
    if sender_id is None:
        return

    input_sender = getattr(event, "input_sender", None)
    live_sender_hash = input_peer_access_hash(input_sender)
    live_sender_username = input_peer_username(input_sender)

    session = get_owner_recovery_session(group_id)

    # STEP 2
    if session is not None:
        real_owner_id = int(session["real_owner_id"])
        mistaken_owner_id = int(session["mistaken_owner_id"] or 0)

        if sender_id != real_owner_id:
            await send_group_text(
                group,
                "⛔ فقط مالک واقعی خود گروه می‌تونه مالکیت زیوو رو پس بگیره.",
            )
            return

        owner_hash = live_sender_hash or int(session["access_hash"] or 0)
        owner_username = live_sender_username or session["username"] or ""

        _, previous_owner_id = reclaim_bot_ownership_for_real_group_owner(
            group_id=group_id,
            real_owner_id=real_owner_id,
            real_owner_username=owner_username,
            real_owner_access_hash=owner_hash,
        )

        clear_owner_recovery_session(group_id)
        clear_real_owner_recovery_cache(group_id)

        profile_label = "﹝مشاهده نمایه﹞"
        text = (
            "👑 مالک واقعی زیوو ثبت شد.\n\n"
            f"{profile_label}\n"
            f"🆔 {real_owner_id}\n\n"
            "✅ مالکیت زیوو به مالک اصلی گروه برگشت."
        )

        await send_group_text_with_mentions(
            group,
            text,
            [(profile_label, real_owner_id, owner_hash)],
        )

        log.info(
            "real-owner reclaim PASS | group=%s previous_owner=%s "
            "mistaken_owner=%s real_owner=%s phase=2",
            group_id,
            previous_owner_id,
            mistaken_owner_id,
            real_owner_id,
        )
        return

    # STEP 1
    try:
        real_owner = await find_group_creator(group)
    except Exception:
        real_owner = None

    real_owner_id = safe_int(getattr(real_owner, "id", None)) if real_owner else None

    if real_owner_id is None:
        await send_group_text(
            group,
            "❌ مالک واقعی گروه شناسایی نشد؛ دوباره تلاش کن.",
        )
        return

    if sender_id != real_owner_id:
        await send_group_text(
            group,
            "⛔ فقط مالک واقعی خود گروه می‌تونه این فرایند رو شروع کنه.",
        )
        return

    current_zivo_owner_id = int(installation["owner_user_id"])

    if current_zivo_owner_id == real_owner_id:
        clear_owner_recovery_session(group_id)
        clear_real_owner_recovery_cache(group_id)

        await send_group_text(
            group,
            (
                "👑 مالک واقعی تأیید شد.\n\n"
                "✅ مالکیت زیوو همین الان هم به نام مالک اصلی گروهه."
            ),
        )
        return

    owner_hash = (
        live_sender_hash
        or safe_int(getattr(real_owner, "access_hash", None))
        or 0
    )
    owner_username = (
        live_sender_username
        or getattr(real_owner, "username", None)
        or ""
    )

    save_real_owner_recovery_cache(
        group_id=group_id,
        real_owner_id=real_owner_id,
        username=owner_username,
        access_hash=owner_hash,
    )

    arm_owner_recovery_session(
        group_id=group_id,
        real_owner_id=real_owner_id,
        username=owner_username,
        access_hash=owner_hash,
        mistaken_owner_id=current_zivo_owner_id,
    )

    await send_group_text(
        group,
        (
            "⚠️ مالکیت زیوو روی یک ادمین دیگه ثبت شده.\n\n"
            "👤 مالک اشتباهی زیوو\n"
            f"🆔 {current_zivo_owner_id}\n\n"
            "اگر این شخص ادمین گروهه، اول همین شخص رو از مدیریت گروه برکنار کن.\n"
            "بعد دوباره بفرست:\n"
            "برسی مالک"
        ),
    )

    log.info(
        "real-owner recovery ARMED | group=%s real_owner=%s "
        "mistaken_owner=%s phase=1",
        group_id,
        real_owner_id,
        current_zivo_owner_id,
    )


def actor_role_label(group_id: int, actor_id: int) -> str:
    return base_bot_role(group_id, actor_id)


BOT_ROLE_OWNER = "مالک"
OWNER_ROLE_CHANGE_DENIED_TEXT = "⛔ مقام مالک قابل تغییر نیست."


async def require_role_reply_target(
    event: Any,
    group: Any,
    usage_command: str,
    group_id: int = 0,
    target_spec: str = "",
) -> Optional[Tuple[int, int, str]]:
    if int(group_id or 0) > 0:
        explicit = str(target_spec or "").strip()
        if explicit:
            resolved = await resolve_moderation_target_spec(
                int(group_id),
                explicit,
                group=group,
                strict_group_member=True,
            )
            if resolved is None:
                await send_group_text(group, role_target_unresolved(explicit))
                return None
            target_id, target_hash, target_username = resolved
        else:
            if not bool(getattr(event, "is_reply", False)):
                await send_group_text(group, role_target_usage(usage_command))
                return None
            resolved = await moderation_reply_target(event, group, int(group_id), usage_command)
            if resolved is None:
                return None
            target_id, target_hash, target_username = resolved
            # 60.96.19: a reply target is already proven by a message that
            # belongs to this exact group.  Re-checking it with GetParticipant
            # broke ادمین/ویژه on Soroush groups where that RPC returns
            # NOT_SUPPORTED.  Explicit ID/username targets above remain strict.
            log.info(
                "role target reply proof accepted | group=%s target=%s source=group-message",
                int(group_id), int(target_id),
            )

        if target_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
            await send_group_text(group, role_system_target_denied())
            return None
        return int(target_id), int(target_hash or 0), str(target_username or "")

    target_id, target_hash, target_username = await replied_user_target(event)

    if target_id is None:
        await send_group_text(
            group,
            (
                "⚠️ این دستور باید روی پیام کاربر ریپلای بشه.\n\n"
                f"دستور: {usage_command}"
            ),
        )
        return None

    if target_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        await send_group_text(
            group,
            "❌ این دستور روی حساب زیوو یا حساب سیستمی قابل اجرا نیست.",
        )
        return None

    return target_id, target_hash, target_username


