async def command_dismiss_rank(
    event: Any,
    group: Any,
    group_id: int,
    target_spec: str = "",
) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return

    actor_role = base_bot_role(group_id, actor_id)

    if actor_role not in {"مالک", "ادمین"}:
        await send_group_text(
            group,
            "⛔ فقط مالک یا ادمین زیوو می‌تونه از دستور عزل استفاده کنه.",
        )
        return

    target = await require_role_reply_target(event, group, "عزل", group_id, target_spec)
    if target is None:
        return

    target_id, target_hash, _ = target
    target_role = base_bot_role(group_id, target_id)

    if target_id == actor_id:
        await send_group_text(group, "⚠️ نمی‌تونی خودت رو عزل کنی.")
        return

    if target_role == "مالک":
        await send_group_text(group, "⛔ مالک با دستور عزل برکنار نمی‌شه.")
        return

    if target_role == "کاربر عادی":
        await send_group_text(group, "⚠️ این کاربر مقام ادمین یا ویژه نداره.")
        return

    # Owner can dismiss admin or special.
    # Admin can only dismiss special.
    if actor_role == "ادمین" and target_role != "ویژه":
        await send_group_text(
            group,
            "⛔ ادمین فقط می‌تونه کاربران ویژه رو عزل کنه.",
        )
        return

    dismiss_bot_rank(group_id, target_id)

    await send_role_change_result(
        group=group,
        target_id=target_id,
        target_hash=target_hash,
        headline="✅ مقام کاربر با موفقیت عزل شد.",
        detail="🎖 مقام جدید: کاربر عادی",
        actor_role=actor_role,
    )

    log.info(
        "role dismissed | group=%s actor=%s actor_role=%s "
        "target=%s old_role=%s",
        group_id,
        actor_id,
        actor_role,
        target_id,
        target_role,
    )


async def fetch_owner_full_profile(
    event: Any,
    group: Any,
    installation: sqlite3.Row,
) -> Dict[str, Any]:
    owner_id = int(installation["owner_user_id"])
    owner_username = installation["owner_username"] or ""
    group_id = int(installation["group_id"])
    owner_hash = (
        int(installation["owner_access_hash"] or 0)
        or stats_access_hash(group_id, owner_id)
    )

    sender_id = safe_int(getattr(event, "sender_id", None))
    if sender_id == owner_id:
        owner_hash = (
            input_peer_access_hash(getattr(event, "input_sender", None))
            or owner_hash
        )

    user_entity: Any = None
    about = "دریافت نشد"
    bio_loaded = False

    if owner_hash:
        try:
            full_result = await client(
                functions.users.GetFullUserRequest(
                    id=types.InputUser(
                        user_id=owner_id,
                        access_hash=owner_hash,
                    )
                )
            )

            for user in list(getattr(full_result, "users", None) or []):
                if safe_int(getattr(user, "id", None)) == owner_id:
                    user_entity = user
                    break

            full_user = getattr(full_result, "full_user", None)
            if full_user is not None:
                raw_about = getattr(full_user, "about", None)
                about = (
                    raw_about.strip()
                    if isinstance(raw_about, str) and raw_about.strip()
                    else "تنظیم نشده"
                )
                bio_loaded = True

        except Exception as exc:
            log.info(
                "owner full profile by access_hash failed | group=%s owner=%s | %s: %s",
                group_id,
                owner_id,
                type(exc).__name__,
                exc,
            )

    if user_entity is None and owner_username:
        try:
            candidate = await client.get_entity(owner_username)

            if safe_int(getattr(candidate, "id", None)) == owner_id:
                user_entity = candidate
                owner_hash = (
                    safe_int(getattr(candidate, "access_hash", None))
                    or owner_hash
                )

                if not bio_loaded and owner_hash:
                    try:
                        full_result = await client(
                            functions.users.GetFullUserRequest(
                                id=types.InputUser(
                                    user_id=owner_id,
                                    access_hash=owner_hash,
                                )
                            )
                        )
                        full_user = getattr(full_result, "full_user", None)
                        if full_user is not None:
                            raw_about = getattr(full_user, "about", None)
                            about = (
                                raw_about.strip()
                                if isinstance(raw_about, str) and raw_about.strip()
                                else "تنظیم نشده"
                            )
                            bio_loaded = True
                    except Exception:
                        pass

        except Exception as exc:
            log.info(
                "owner username resolve failed | group=%s owner=%s | %s: %s",
                group_id,
                owner_id,
                type(exc).__name__,
                exc,
            )

    if user_entity is None:
        try:
            candidate = await asyncio.wait_for(
                client.get_entity(types.PeerUser(int(owner_id))),
                timeout=3.0,
            )
            if safe_int(getattr(candidate, "id", None)) == owner_id:
                user_entity = candidate
                owner_hash = safe_int(getattr(candidate, "access_hash", None)) or owner_hash
                owner_username = getattr(candidate, "username", None) or owner_username
        except Exception as exc:
            log.debug(
                "owner session entity fallback unavailable | group=%s owner=%s | %s",
                group_id, owner_id, type(exc).__name__,
            )

    if user_entity is None and sender_id == owner_id:
        candidate = getattr(event, "sender", None)
        if candidate is not None and safe_int(getattr(candidate, "id", None)) == owner_id:
            user_entity = candidate
            owner_hash = (
                safe_int(getattr(candidate, "access_hash", None))
                or owner_hash
            )

    if user_entity is None:
        # Owner command must still show a useful identity when Soroush cannot
        # resolve access_hash at this moment. Reuse the durable observed profile
        # captured from normal traffic instead of displaying «ثبت نشده».
        try:
            cached_profile = get_global_user_profile(owner_id)
        except Exception:
            cached_profile = {}
        cached_username = str(cached_profile.get("username") or "").strip()
        cached_name = str(
            cached_profile.get("preferred_name")
            or cached_profile.get("nickname")
            or cached_profile.get("observed_name")
            or ""
        ).strip()
        if cached_username and not owner_username:
            owner_username = cached_username
        if not owner_hash:
            owner_hash = int(stats_access_hash(group_id, owner_id) or 0)
        fallback_name = cached_name or (f"@{owner_username}" if owner_username else f"کاربر {owner_id}")
    else:
        fallback_name = display_name(user_entity)

    resolved_username = (
        getattr(user_entity, "username", None)
        if user_entity is not None
        else None
    ) or owner_username

    return {
        "id": owner_id,
        "access_hash": int(owner_hash or 0),
        "username": resolved_username or "",
        "name": fallback_name,
        "bio": about,
        "bio_loaded": bio_loaded,
        "entity": user_entity,
    }


async def fetch_owner_latest_photo(
    owner_id: int,
    owner_access_hash: int,
    group_id: int,
) -> Optional[Any]:
    """
    Resolve exactly one newest profile Photo object and return its remote handle.
    No photo bytes are downloaded and profile history is never traversed.
    """
    if not owner_access_hash:
        log.info(
            "owner latest photo skipped: missing access_hash | group=%s owner=%s",
            group_id,
            owner_id,
        )
        return None

    try:
        result = await client(
            functions.photos.GetUserPhotosRequest(
                user_id=types.InputUser(
                    user_id=int(owner_id),
                    access_hash=int(owner_access_hash),
                ),
                offset=0,
                max_id=0,
                limit=1,
            )
        )

        photos = list(getattr(result, "photos", None) or [])
        if not photos:
            log.info(
                "owner has no profile photo | group=%s owner=%s",
                group_id,
                owner_id,
            )
            return None

        latest_photo = photos[0]

        log.info(
            "owner latest remote photo ready | group=%s owner=%s photo_id=%s",
            group_id,
            owner_id,
            getattr(latest_photo, "id", None),
        )

        return latest_photo

    except Exception as exc:
        log.info(
            "owner latest remote photo lookup failed | group=%s owner=%s | %s: %s",
            group_id,
            owner_id,
            type(exc).__name__,
            exc,
        )
        return None


def internal_role_lines(
    group_id: int,
    table_name: str,
    role_label: str,
    role_icon: str,
    limit: int = 8,
) -> Tuple[str, List[Tuple[str, int, int]]]:
    rows, total = list_internal_role_rows(group_id, table_name, limit=limit)

    if not rows:
        return f"{role_icon} {role_label} (0)\n└ کسی ثبت نشده.", []

    lines: List[str] = [f"{role_icon} {role_label} ({total})"]
    mentions: List[Tuple[str, int, int]] = []

    for index, row in enumerate(rows, start=1):
        user_id = int(row["user_id"])
        username = row["username"] or ""
        access_hash = int(row["access_hash"] or 0)
        profile_label = f"﹝نمایه {index}﹞"
        username_text = f"@{username}" if username else "بدون آیدی"
        branch = "└" if index == len(rows) and total == len(rows) else "├"

        lines.append(
            f"{branch} {profile_label}  |  {username_text}  |  ID: {user_id}"
        )
        mentions.append(
            (
                profile_label,
                user_id,
                access_hash or stats_access_hash(group_id, user_id),
            )
        )

    if total > len(rows):
        lines.append(f"└ +{total - len(rows)} نفر دیگر")

    return "\n".join(lines), mentions


def owner_card_text(
    group_id: int,
    profile: Dict[str, Any],
    native_owner_id: int = 0,
    owner_mode: str = "native",
) -> Tuple[str, List[Tuple[str, int, int]]]:
    owner_id = int(profile["id"])
    owner_hash = int(profile["access_hash"] or 0)
    username = profile["username"] or ""
    username_text = f"@{username}" if username else "تنظیم نشده"
    profile_label = "﹝مشاهده نمایه مالک﹞"

    admin_text, admin_mentions = internal_role_lines(
        group_id,
        "bot_admins",
        "ادمین‌های زیوو",
        "🛡",
    )
    special_text, special_mentions = internal_role_lines(
        group_id,
        "bot_specials",
        "ویژه‌های زیوو",
        "💠",
    )

    bio = profile["bio"]
    if not profile.get("bio_loaded", False) and bio == "دریافت نشد":
        bio = "در این لحظه از سروش دریافت نشد."

    if owner_mode == "executive" and native_owner_id and int(native_owner_id) != owner_id:
        ownership_header = (
            "👑 ZIVO | مالکیت گروه\n"
            "━━━━━━━━━━━━━━━━━━\n\n"
            "👑 مالک اصلی گروه\n"
            "├ وضعیت: اکانت فعلاً در دسترس نیست\n"
            f"└ آیدی عددی: {int(native_owner_id)}\n\n"
            "🛡 مالک اجرایی زیوو\n"
        )
    else:
        ownership_header = (
            "👑 ZIVO | مالک ثبت‌شده\n"
            "━━━━━━━━━━━━━━━━━━\n\n"
            "👤 هویت مالک\n"
        )

    executive_mode = owner_mode == "executive" and native_owner_id and int(native_owner_id) != owner_id
    bio_label = "📝 بیو مالک اجرایی\n" if executive_mode else "📝 بیو مالک\n"
    text = (
        f"{ownership_header}"
        f"├ نام: {profile['name']}\n"
        f"├ آیدی: {username_text}\n"
        f"├ آیدی عددی: {owner_id}\n"
        f"└ {profile_label}\n\n"
        f"{bio_label}"
    ) + (
        f"{bio}\n\n"
        f"{admin_text}\n\n"
        f"{special_text}\n\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "⚡ ZIVO | OWNER CORE"
    )

    mentions: List[Tuple[str, int, int]] = [
        (profile_label, owner_id, owner_hash)
    ]
    mentions.extend(admin_mentions)
    mentions.extend(special_mentions)

    return text, mentions


async def send_owner_profile_card(
    group: Any,
    group_id: int,
    profile: Dict[str, Any],
    installation: Optional[sqlite3.Row] = None,
) -> None:
    native_owner_id = 0
    owner_mode = "native"
    if installation is not None:
        if "native_owner_user_id" in installation.keys():
            native_owner_id = int(installation["native_owner_user_id"] or 0)
        if "owner_mode" in installation.keys():
            owner_mode = str(installation["owner_mode"] or "native")
    text, mentions = owner_card_text(
        group_id, profile, native_owner_id=native_owner_id, owner_mode=owner_mode,
    )

    latest_photo = await fetch_owner_latest_photo(
        int(profile["id"]),
        int(profile.get("access_hash") or 0),
        group_id,
    )

    if latest_photo is not None:
        try:
            await client.send_file(
                group,
                latest_photo,
                caption=text,
                reply_to=active_group_command_reply_id(),
                parse_mode=None,
                formatting_entities=rich_mention_entities(
                    text,
                    mentions,
                ),
            )

            log.info(
                "owner card sent with remote latest photo | group=%s owner=%s photo_id=%s",
                group_id,
                profile["id"],
                getattr(latest_photo, "id", None),
            )
            return

        except Exception as exc:
            log.warning(
                "owner remote photo send failed | group=%s owner=%s | %s: %s",
                group_id,
                profile["id"],
                type(exc).__name__,
                exc,
            )

            try:
                await client.send_file(
                    group,
                    latest_photo,
                    caption=text,
                    reply_to=active_group_command_reply_id(),
                    parse_mode=None,
                    formatting_entities=[],
                )

                log.info(
                    "owner card sent with remote latest photo, plain caption | group=%s owner=%s photo_id=%s",
                    group_id,
                    profile["id"],
                    getattr(latest_photo, "id", None),
                )
                return

            except Exception as retry_exc:
                log.warning(
                    "owner remote photo plain-caption retry failed | group=%s owner=%s | %s: %s",
                    group_id,
                    profile["id"],
                    type(retry_exc).__name__,
                    retry_exc,
                )

    # Final fallback: text only. Never use an older profile photo.
    await send_group_text_with_mentions(
        group,
        text,
        mentions,
    )



def legacy_cross_account_owner_hint(group_id: int) -> Optional[Dict[str, Any]]:
    """Return the strongest durable owner proof from another configured account DB.

    Multi-account legacy groups can have a safe local placeholder row (owner=0)
    while another ZIVO account still owns a complete historical installation row.
    The old recovery path only copied state when the local row was missing, so
    those placeholders could never heal. Prefer persisted native-owner proof;
    fall back to an effective owner only when that donor row is native-mode.
    """
    gid = int(group_id)
    best: Optional[Dict[str, Any]] = None
    try:
        sources = _legacy_group_account_sources(gid)
    except Exception:
        sources = []
    current_path = str(DB_PATH.resolve())
    for account_key, raw_path in sources:
        try:
            path = Path(str(raw_path)).resolve()
            if str(path) == current_path or not path.is_file():
                continue
            con = sqlite3.connect(str(path), timeout=0.35)
            con.row_factory = sqlite3.Row
            try:
                con.execute("PRAGMA busy_timeout=350")
                cols = {str(row[1]) for row in con.execute("PRAGMA table_info(installations)").fetchall()}
                wanted = [
                    name for name in (
                        "owner_user_id", "owner_username", "owner_access_hash", "owner_mode",
                        "native_owner_user_id", "native_owner_username", "native_owner_access_hash",
                    ) if name in cols
                ]
                if "owner_user_id" not in wanted:
                    continue
                row = con.execute(
                    f"SELECT {', '.join(wanted)} FROM installations WHERE group_id = ? LIMIT 1",
                    (gid,),
                ).fetchone()
            finally:
                con.close()
            if row is None:
                continue
            keys = set(row.keys())
            native_id = int(row["native_owner_user_id"] or 0) if "native_owner_user_id" in keys else 0
            owner_id = int(row["owner_user_id"] or 0)
            owner_mode = str(row["owner_mode"] or "native") if "owner_mode" in keys else "native"
            if native_id > 0:
                candidate = {
                    "owner_id": native_id,
                    "username": str(row["native_owner_username"] or "") if "native_owner_username" in keys else "",
                    "access_hash": int(row["native_owner_access_hash"] or 0) if "native_owner_access_hash" in keys else 0,
                    "source_account": str(account_key),
                    "proof": "native_owner",
                    "score": 2,
                }
            elif owner_id > 0 and owner_mode in {"", "native"}:
                candidate = {
                    "owner_id": owner_id,
                    "username": str(row["owner_username"] or "") if "owner_username" in keys else "",
                    "access_hash": int(row["owner_access_hash"] or 0) if "owner_access_hash" in keys else 0,
                    "source_account": str(account_key),
                    "proof": "native_effective_owner",
                    "score": 1,
                }
            else:
                continue
            if best is None or int(candidate["score"]) > int(best["score"]):
                best = candidate
        except Exception as exc:
            log.debug(
                "legacy owner hint probe skipped | group=%s account=%s | %s: %s",
                gid, account_key, type(exc).__name__, exc,
            )
    return best


async def recover_owner_placeholder_for_display(
    event: Any,
    group: Any,
    group_id: int,
    installation: sqlite3.Row,
) -> sqlite3.Row:
    """Repair runtime-bootstrap installations whose owner is still the safe zero placeholder.

    The owner command is read-only for users, but it must never render user id 0.
    Recovery order deliberately trusts only previously proven native-owner metadata or
    a live Soroush creator/admin scan; the command sender is never promoted blindly.
    """
    current_owner_id = int(installation["owner_user_id"] or 0)
    if current_owner_id > 0:
        return installation

    # A local placeholder must not hide durable owner proof that exists in a
    # sibling main/acc2/acc3 DB. This is common in legacy groups after account
    # failover where the current account bootstrapped owner=0 locally.
    try:
        hint_resolver = globals().get("legacy_cross_account_owner_hint")
        cross_hint = hint_resolver(int(group_id)) if callable(hint_resolver) else None
    except Exception:
        cross_hint = None
    if cross_hint is not None and int(cross_hint.get("owner_id") or 0) > 0:
        cross_owner_id = int(cross_hint["owner_id"])
        try:
            updated, _ = reclaim_bot_ownership_for_real_group_owner(
                int(group_id),
                cross_owner_id,
                str(cross_hint.get("username") or ""),
                int(cross_hint.get("access_hash") or 0),
            )
            log.warning(
                "owner zero placeholder repaired | group=%s owner=%s source=cross_account_%s donor=%s",
                group_id,
                cross_owner_id,
                str(cross_hint.get("proof") or "legacy"),
                str(cross_hint.get("source_account") or "?"),
            )
            return updated
        except Exception as exc:
            log.warning(
                "owner cross-account repair failed | group=%s owner=%s | %s: %s",
                group_id, cross_owner_id, type(exc).__name__, exc,
            )

    native_owner_id = (
        int(installation["native_owner_user_id"] or 0)
        if "native_owner_user_id" in installation.keys()
        else 0
    )
    native_username = (
        str(installation["native_owner_username"] or "")
        if "native_owner_username" in installation.keys()
        else ""
    )
    native_hash = (
        int(installation["native_owner_access_hash"] or 0)
        if "native_owner_access_hash" in installation.keys()
        else 0
    )

    # Native owner metadata was persisted only after Soroush proof. Reuse it
    # immediately instead of paying another participant RPC on every owner card.
    if native_owner_id > 0:
        try:
            updated, _ = reclaim_bot_ownership_for_real_group_owner(
                int(group_id), int(native_owner_id), native_username, int(native_hash or 0),
            )
            log.warning(
                "owner zero placeholder repaired | group=%s owner=%s source=native_metadata",
                group_id, native_owner_id,
            )
            return updated
        except Exception as exc:
            log.warning(
                "owner native metadata repair failed | group=%s owner=%s | %s: %s",
                group_id, native_owner_id, type(exc).__name__, exc,
            )

    # A previous explicit owner-recovery probe may already have durable proof.
    try:
        cached = get_real_owner_recovery_cache(int(group_id))
    except Exception:
        cached = None
    if cached is not None:
        cached_owner_id = int(cached["real_owner_id"] or 0)
        if cached_owner_id > 0:
            try:
                updated, _ = reclaim_bot_ownership_for_real_group_owner(
                    int(group_id), cached_owner_id,
                    str(cached["username"] or ""), int(cached["access_hash"] or 0),
                )
                log.warning(
                    "owner zero placeholder repaired | group=%s owner=%s source=recovery_cache",
                    group_id, cached_owner_id,
                )
                return updated
            except Exception as exc:
                log.warning(
                    "owner recovery-cache repair failed | group=%s owner=%s | %s: %s",
                    group_id, cached_owner_id, type(exc).__name__, exc,
                )

    # Last trusted path: ask Soroush for the real creator. Bound the whole probe
    # so a degraded participant endpoint cannot make the public owner command hang.
    try:
        creator = await asyncio.wait_for(find_group_creator(group), timeout=9.5)
    except Exception as exc:
        creator = None
        log.warning(
            "owner zero placeholder live recovery failed | group=%s | %s: %s",
            group_id, type(exc).__name__, exc,
        )

    creator_id = safe_int(getattr(creator, "id", None)) if creator is not None else None
    if creator_id is not None and int(creator_id) > 0:
        creator_username = str(getattr(creator, "username", None) or "")
        creator_hash = int(safe_int(getattr(creator, "access_hash", None)) or 0)
        try:
            queue_global_profile_observation(int(creator_id), entity=creator)
        except Exception:
            pass
        updated, _ = reclaim_bot_ownership_for_real_group_owner(
            int(group_id), int(creator_id), creator_username, creator_hash,
        )
        log.warning(
            "owner zero placeholder repaired | group=%s owner=%s source=live_creator",
            group_id, creator_id,
        )
        return updated

    return get_installation(int(group_id)) or installation


async def command_show_owner(
    event: Any,
    group: Any,
    group_id: int,
    installation: sqlite3.Row,
) -> None:
    installation = await recover_owner_placeholder_for_display(
        event, group, group_id, installation,
    )
    owner_id = int(installation["owner_user_id"] or 0)
    if owner_id <= 0:
        await send_group_text(
            group,
            (
                "⚠️ ZIVO | مالک گروه هنوز از سروش قابل بازیابی نیست.\n"
                "دادهٔ اشتباه نمایش داده نمی‌شه؛ چند لحظه بعد دوباره «مالک» رو بفرست."
            ),
        )
        log.warning("owner card blocked zero placeholder | group=%s", group_id)
        return
    profile = await fetch_owner_full_profile(event, group, installation)
    await send_owner_profile_card(group, group_id, profile, installation=installation)

    log.info(
        "owner card sent | group=%s owner=%s profile_entity=%s bio_loaded=%s",
        group_id,
        profile["id"],
        bool(profile.get("entity")),
        bool(profile.get("bio_loaded")),
    )


async def command_owner(
    event: Any,
    group: Any,
    group_id: int,
    installation: sqlite3.Row,
) -> None:
    if bool(getattr(event, "is_reply", False)):
        await command_transfer_ownership(event, group, group_id, installation)
        return

    await command_show_owner(event, group, group_id, installation)


async def command_transfer_ownership(
    event: Any,
    group: Any,
    group_id: int,
    installation: sqlite3.Row,
) -> None:
    sender_id = safe_int(getattr(event, "sender_id", None))
    if sender_id is None:
        return

    current_owner_id = int(installation["owner_user_id"])
    current_owner_hash = int(installation["owner_access_hash"] or 0)

    if sender_id != current_owner_id:
        await send_group_text(
            group,
            "⛔ این دستور فقط برای مالک زیوو در این گروه قابل استفاده است.",
            reply_to=safe_int(getattr(event, "id", None)),
        )
        log.info(
            "ownership transfer denied | group=%s sender=%s owner=%s",
            group_id,
            sender_id,
            current_owner_id,
        )
        return

    target_id, target_hash, target_username = await replied_user_target(event)

    if target_id is None:
        await send_group_text(
            group,
            (
                "✏️ انتقال مالکیت زیوو\n\n"
                "روی پیام کاربری که می‌خوای مالک جدید بشه ریپلای کن و بنویس:\n"
                "انتقال مالکیت"
            ),
            reply_to=safe_int(getattr(event, "id", None)),
        )
        return

    if target_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        await send_group_text(
            group,
            "❌ این کاربر نمی‌تونه مالک زیوو بشه.",
            reply_to=safe_int(getattr(event, "id", None)),
        )
        return

    if target_id == current_owner_id:
        await send_group_text(
            group,
            "⚠️ این کاربر همین الان مالک زیووئه.",
            reply_to=safe_int(getattr(event, "id", None)),
        )
        return

    transfer_bot_ownership(
        group_id=group_id,
        current_owner_id=current_owner_id,
        new_owner_id=target_id,
        new_owner_username=target_username,
        new_owner_access_hash=target_hash,
    )

    new_label = "﹝مشاهده نمایه مالک جدید﹞"
    old_label = "﹝مشاهده نمایه مالک قبلی﹞"

    text = (
        "✏️ انتقال مالکیت زیوو انجام شد.\n\n"
        "👑 مالک جدید\n"
        f"{new_label}\n"
        f"🆔 {target_id}\n\n"
        "🛡 مالک قبلی\n"
        f"{old_label}\n"
        f"🆔 {current_owner_id}\n"
        "✅ به ادمین زیوو تبدیل شد."
    )

    await send_group_text_with_mentions(
        group,
        text,
        [
            (new_label, target_id, target_hash),
            (old_label, current_owner_id, current_owner_hash),
        ],
        reply_to=safe_int(getattr(event, "id", None)),
    )

    log.info(
        "ownership transferred | group=%s old_owner=%s new_owner=%s",
        group_id,
        current_owner_id,
        target_id,
    )



# ---------------------------------------------------------------------------
# User profile card + controlled group mention/tag workflow
# ---------------------------------------------------------------------------

def parse_profile_card_command(text: str) -> bool:
    return normalize_group_command(text) in {
        "مشخصات", "مشخصاتش", "پروفایل", "پروفایلش", "نمایه", "نمایه اش", "نمایه‌اش"
    }


async def _resolve_replied_full_profile(
    event: Any,
    group: Any,
    group_id: int,
) -> Optional[Dict[str, Any]]:
    if not bool(getattr(event, "is_reply", False)):
        return None

    reply = await event.get_reply_message()
    if reply is None:
        return None

    user_id = safe_int(getattr(reply, "sender_id", None))
    if user_id is None:
        return None

    entity = getattr(reply, "sender", None)
    access_hash = input_peer_access_hash(getattr(reply, "input_sender", None))
    username = getattr(entity, "username", None) or "" if entity is not None else ""

    if not access_hash:
        access_hash = stats_access_hash(group_id, int(user_id))

    # If reply cache is thin after reconnect, resolve the user from live group members.
    if entity is None or not access_hash:
        try:
            users = await asyncio.wait_for(client.get_participants(group, limit=500), timeout=18)
            for candidate in users:
                if safe_int(getattr(candidate, "id", None)) == int(user_id):
                    entity = candidate
                    access_hash = safe_int(getattr(candidate, "access_hash", None)) or access_hash
                    username = getattr(candidate, "username", None) or username
                    break
        except Exception as exc:
            log.debug(
                "profile participant resolve skipped | group=%s user=%s | %s: %s",
                group_id, user_id, type(exc).__name__, exc,
            )

    name = display_name(entity) if entity is not None else "کاربر"
    bio = "دریافت نشد"
    bio_loaded = False

    if access_hash:
        try:
            full = await asyncio.wait_for(
                client(
                    functions.users.GetFullUserRequest(
                        id=types.InputUser(
                            user_id=int(user_id),
                            access_hash=int(access_hash),
                        )
                    )
                ),
                timeout=12,
            )
            for candidate in list(getattr(full, "users", None) or []):
                if safe_int(getattr(candidate, "id", None)) == int(user_id):
                    entity = candidate
                    name = display_name(candidate)
                    username = getattr(candidate, "username", None) or username
                    access_hash = safe_int(getattr(candidate, "access_hash", None)) or access_hash
                    break
            full_user = getattr(full, "full_user", None)
            raw_about = getattr(full_user, "about", None) if full_user is not None else None
            bio = raw_about.strip() if isinstance(raw_about, str) and raw_about.strip() else "تنظیم نشده"
            bio_loaded = True
        except Exception as exc:
            log.debug(
                "profile full-user unavailable | group=%s user=%s | %s: %s",
                group_id, user_id, type(exc).__name__, exc,
            )

    return {
        "id": int(user_id),
        "access_hash": int(access_hash or 0),
        "username": str(username or ""),
        "name": str(name or "کاربر"),
        "bio": str(bio or "دریافت نشد"),
        "bio_loaded": bool(bio_loaded),
        "role": bot_role(group_id, int(user_id)),
        "entity": entity,
    }


async def _fetch_user_latest_photo(user_id: int, access_hash: int) -> Optional[Any]:
    if not access_hash:
        return None
    try:
        result = await asyncio.wait_for(
            client(
                functions.photos.GetUserPhotosRequest(
                    user_id=types.InputUser(
                        user_id=int(user_id),
                        access_hash=int(access_hash),
                    ),
                    offset=0,
                    max_id=0,
                    limit=1,
                )
            ),
            timeout=12,
        )
        photos = list(getattr(result, "photos", None) or [])
        return photos[0] if photos else None
    except Exception as exc:
        log.debug(
            "profile latest photo unavailable | user=%s | %s: %s",
            user_id, type(exc).__name__, exc,
        )
        return None


def _profile_card_text(profile: Dict[str, Any]) -> Tuple[str, List[Tuple[str, int, int]]]:
    user_id = int(profile["id"])
    access_hash = int(profile.get("access_hash") or 0)
    username = str(profile.get("username") or "")
    username_text = f"@{username}" if username else "ندارد"
    role = str(profile.get("role") or "کاربر عادی")
    profile_label = "﹝مشاهده نمایه﹞"
    bio = str(profile.get("bio") or "دریافت نشد")
    global_profile = get_global_user_profile(user_id)
    saved_nickname = str(global_profile.get("nickname") or "").strip()
    saved_name = str(global_profile.get("preferred_name") or "").strip()

    lines = [
        "👤 ZIVO | مشخصات کاربر",
        "━━━━━━━━━━━━━━━━━━",
        f"🪪 نام: {saved_name or profile.get('name') or 'کاربر'}",
        f"🔗 نام کاربری: {username_text}",
    ]
    if saved_nickname:
        lines.append(f"🏷 لقب سراسری: {saved_nickname}")
    if role != "کاربر عادی":
        lines.append(f"🏷 لقب / مقام زیوو: {role}")
    lines.extend(
        [
            f"🆔 آیدی عددی: {user_id}",
            f"📝 بیو: {bio}",
            f"👁 {profile_label}",
            "━━━━━━━━━━━━━━━━━━",
            "⚡ ZIVO | USER PROFILE",
        ]
    )
    return "\n".join(lines), [(profile_label, user_id, access_hash)]


async def command_profile_card(event: Any, group: Any, group_id: int) -> None:
    profile = await _resolve_replied_full_profile(event, group, group_id)
    if profile is None:
        await send_group_text(
            group,
            "👤 برای دیدن مشخصات، روی پیام کاربر ریپلای کن و بنویس: مشخصات",
            reply_to=safe_int(getattr(event, "id", None)),
        )
        return

    text, mentions = _profile_card_text(profile)
    photo = await _fetch_user_latest_photo(
        int(profile["id"]),
        int(profile.get("access_hash") or 0),
    )

    if photo is not None:
        try:
            sent = await client.send_file(
                group,
                photo,
                caption=text,
                reply_to=active_group_command_reply_id(),
                parse_mode=None,
                formatting_entities=rich_mention_entities(text, mentions),
            )
            schedule_bot_message_cleanup(group, sent, "general")
            return
        except Exception as exc:
            log.info(
                "profile card latest-photo send fallback | group=%s user=%s | %s: %s",
                group_id, profile["id"], type(exc).__name__, exc,
            )

    await send_group_text_with_mentions(group, text, mentions)


def parse_tag_command(text: str, allow_short: bool = False) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(text)
    if allow_short:
        if text in {"کل گروه", "همه", "همگی"}:
            return {"action": "all"}
        if text in {"تایید", "تأیید", "بله"}:
            return {"action": "confirm"}
        if text in {"لغو", "انصراف"}:
            return {"action": "cancel"}
        short_modes = {
            "قدیمی": "old", "قدیمی ها": "old", "قدیمی‌ها": "old",
            "جدید": "new", "جدید ها": "new", "جدیدها": "new",
            "آنلاین": "online", "انلاین": "online", "تصادفی": "random",
        }
        if text in short_modes:
            return {"action": "mode", "mode": short_modes[text]}
        if re.fullmatch(r"[0-9۰-۹٠-٩]+", text):
            return {"action": "count", "count": int(text.translate(PERSIAN_ARABIC_TO_ASCII))}
    if text == "تگ":
        return {"action": "start"}
    if text in {"لغو تگ", "انصراف تگ"}:
        return {"action": "cancel"}
    if text in {"وضعیت تگ", "وضعيت تگ"}:
        return {"action": "status"}
    if text in {"تایید تگ", "تأیید تگ"}:
        return {"action": "confirm"}
    if text in {"تگ کل گروه", "تگ همه", "تگ همگی"}:
        return {"action": "all"}
    m = re.fullmatch(r"تگ(?: تعداد)?\s+([0-9۰-۹٠-٩]+)", text)
    if m:
        raw = m.group(1).translate(PERSIAN_ARABIC_TO_ASCII)
        return {"action": "count", "count": int(raw)}
    mode_map = {
        "تگ قدیمی": "old",
        "تگ قدیمی ها": "old",
        "تگ قدیمی‌ها": "old",
        "تگ جدید": "new",
        "تگ جدید ها": "new",
        "تگ جدیدها": "new",
        "تگ آنلاین": "online",
        "تگ انلاین": "online",
        "تگ تصادفی": "random",
    }
    if text in mode_map:
        return {"action": "mode", "mode": mode_map[text]}
    return None


def _tag_session(group_id: int) -> Optional[Dict[str, Any]]:
    session = _tag_sessions.get(int(group_id))
    if not session:
        return None
    if time.monotonic() - float(session.get("created_mono") or 0.0) > TAG_SESSION_TTL_SECONDS:
        _tag_sessions.pop(int(group_id), None)
        return None
    return session


def _participant_date_map(participants: List[Any]) -> Dict[int, float]:
    result: Dict[int, float] = {}
    for participant in participants:
        uid = safe_int(getattr(participant, "user_id", None))
        if uid is None:
            peer = getattr(participant, "peer", None)
            uid = safe_int(getattr(peer, "user_id", None))
        if uid is None:
            continue
        dt = getattr(participant, "date", None)
        if isinstance(dt, datetime):
            try:
                result[int(uid)] = dt.timestamp()
            except Exception:
                pass
    return result


async def _fetch_tag_members(group: Any, group_id: int) -> List[Dict[str, Any]]:
    users: List[Any] = []
    joined_map: Dict[int, float] = {}
    seen_ids: set[int] = set()
    user_sources: Dict[int, str] = {}
    admin_states: Dict[int, bool] = {}
    expected_count: Optional[int] = None

    async def append_users(batch_users: List[Any], source: str = "participants") -> int:
        added = 0
        for user in batch_users:
            uid = safe_int(getattr(user, "id", None))
            if uid is None or int(uid) in seen_ids:
                continue
            seen_ids.add(int(uid))
            users.append(user)
            user_sources[int(uid)] = source
            added += 1
            if len(users) >= TAG_MAX_MEMBERS:
                break
        return added

    def tag_admin_event_subject_and_state(event: Any) -> Tuple[Optional[int], Optional[bool]]:
        action = getattr(event, "action", None)
        if isinstance(action, types.ChannelAdminLogEventActionParticipantToggleBan):
            new_participant = getattr(action, "new_participant", None) or getattr(event, "new", None)
            uid = participant_user_id(new_participant)
            if isinstance(new_participant, types.ChannelParticipantBanned):
                return uid, not bool(getattr(new_participant, "left", False))
            if uid is not None:
                return uid, True
        return admin_event_subject_and_state(event)

    def admin_event_entity(event: Any, uid: int) -> Optional[Any]:
        entities = getattr(event, "entities", None) or {}
        try:
            entity = entities.get(int(uid))
            if entity is not None:
                return entity
        except Exception:
            pass
        actor = getattr(event, "user", None)
        if safe_int(getattr(actor, "id", None)) == int(uid):
            return actor
        for entity in list(getattr(event, "entities", {}).values() if isinstance(getattr(event, "entities", None), dict) else []):
            if safe_int(getattr(entity, "id", None)) == int(uid):
                return entity
        return None

    async def scan_admin_log(channel_entity: Any) -> None:
        nonlocal expected_count
        scan_limit = min(TAG_ADMIN_LOG_LIMIT, max(5000, int((expected_count or 1500) * 12)))
        scanned = 0
        active_seen = 0

        async def consume() -> None:
            nonlocal scanned, active_seen
            iterator_factory = getattr(client, "iter_admin_log", None)
            if callable(iterator_factory):
                iterator = iterator_factory(
                    channel_entity,
                    limit=scan_limit,
                    join=True,
                    leave=True,
                    invite=True,
                    restrict=True,
                    unrestrict=True,
                    ban=True,
                    unban=True,
                )
                async for event in iterator:
                    scanned += 1
                    subject_id, state = tag_admin_event_subject_and_state(event)
                    if subject_id is None or state is None:
                        continue
                    uid = int(subject_id)
                    if uid in admin_states:
                        continue
                    admin_states[uid] = bool(state)
                    if state:
                        active_seen += 1
                        entity = admin_event_entity(event, uid)
                        if entity is not None:
                            await append_users([entity], source="adminlog")
                        event_date = getattr(event, "date", None)
                        if isinstance(event_date, datetime):
                            try:
                                joined_map.setdefault(uid, event_date.timestamp())
                            except Exception:
                                pass
                    if scanned % 100 == 0:
                        await _yield_background_to_realtime(0.6)
                        await asyncio.sleep(0)
                    if scanned % 250 == 0:
                        active_known = len({uid for uid, is_active in admin_states.items() if is_active} | seen_ids)
                        log.info(
                            "mass tag adminlog progress | group=%s events=%s states=%s active=%s entities=%s expected=%s",
                            group_id, scanned, len(admin_states), active_known, len(users), expected_count,
                        )
                    if expected_count and len({uid for uid, is_active in admin_states.items() if is_active} | seen_ids) >= int(expected_count):
                        break
            else:
                events = await client.get_admin_log(
                    channel_entity,
                    limit=scan_limit,
                    join=True,
                    leave=True,
                    invite=True,
                    restrict=True,
                    unrestrict=True,
                    ban=True,
                    unban=True,
                )
                for event in events:
                    scanned += 1
                    subject_id, state = admin_event_subject_and_state(event)
                    if subject_id is None or state is None:
                        continue
                    uid = int(subject_id)
                    if uid in admin_states:
                        continue
                    admin_states[uid] = bool(state)
                    if state:
                        active_seen += 1
                        entity = admin_event_entity(event, uid)
                        if entity is not None:
                            await append_users([entity], source="adminlog")
                        event_date = getattr(event, "date", None)
                        if isinstance(event_date, datetime):
                            try:
                                joined_map.setdefault(uid, event_date.timestamp())
                            except Exception:
                                pass
                    if scanned % 100 == 0:
                        await _yield_background_to_realtime(0.6)
                        await asyncio.sleep(0)
                    if expected_count and len({uid for uid, is_active in admin_states.items() if is_active} | seen_ids) >= int(expected_count):
                        break

        try:
            await asyncio.wait_for(consume(), timeout=TAG_ADMIN_LOG_TIMEOUT_SECONDS)
            log.info(
                "mass tag adminlog reconstruction PASS | group=%s events=%s states=%s active_states=%s users=%s expected=%s",
                group_id,
                scanned,
                len(admin_states),
                sum(1 for state in admin_states.values() if state),
                len(users),
                expected_count,
            )
        except asyncio.TimeoutError:
            log.warning(
                "mass tag adminlog reconstruction timeout | group=%s events=%s states=%s users=%s timeout=%ss expected=%s",
                group_id, scanned, len(admin_states), len(users), TAG_ADMIN_LOG_TIMEOUT_SECONDS, expected_count,
            )
        except Exception as exc:
            log.warning(
                "mass tag adminlog reconstruction failed | group=%s events=%s states=%s users=%s | %s: %s",
                group_id, scanned, len(admin_states), len(users), type(exc).__name__, exc,
            )

    if isinstance(group, types.Channel):
        access_hash = safe_int(getattr(group, "access_hash", None)) or 0
        channel_input: Any = group
        if access_hash:
            try:
                channel_input = types.InputChannel(
                    channel_id=int(group.id),
                    access_hash=int(access_hash),
                )
            except Exception:
                channel_input = group

        try:
            full = await asyncio.wait_for(
                client(functions.channels.GetFullChannelRequest(channel_input)),
                timeout=15,
            )
            expected_count = safe_int(getattr(getattr(full, "full_chat", None), "participants_count", None))
            log.info(
                "mass tag expected member count | group=%s expected=%s",
                group_id, expected_count,
            )
        except Exception as exc:
            log.warning(
                "mass tag expected member count unavailable | group=%s | %s: %s",
                group_id, type(exc).__name__, exc,
            )

        filters: List[Tuple[str, Any]] = []
        recent_cls = getattr(types, "ChannelParticipantsRecent", None)
        if recent_cls is not None:
            try:
                filters.append(("recent", recent_cls()))
            except Exception:
                pass
        try:
            filters.append(("search-empty", types.ChannelParticipantsSearch("")))
        except Exception:
            pass

        for filter_name, participant_filter in filters:
            offset = 0
            no_progress_pages = 0
            page_no = 0
            try:
                while len(users) < TAG_MAX_MEMBERS and page_no < 50:
                    page_no += 1
                    limit = min(200, TAG_MAX_MEMBERS - len(users))
                    await _wait_transport_background_slot(soft_limit=110, max_wait=3.0)
                    result = await asyncio.wait_for(
                        client(
                            functions.channels.GetParticipantsRequest(
                                channel=channel_input,
                                filter=participant_filter,
                                offset=offset,
                                limit=limit,
                                hash=0,
                            )
                        ),
                        timeout=18,
                    )
                    batch_users = list(getattr(result, "users", None) or [])
                    batch_parts = list(getattr(result, "participants", None) or [])
                    joined_map.update(_participant_date_map(batch_parts))
                    added = await append_users(batch_users, source="participants")
                    await _yield_background_to_realtime(0.5)
                    await asyncio.sleep(0)
                    raw_step = max(len(batch_parts), len(batch_users))
                    count_value = safe_int(getattr(result, "count", None))
                    log.info(
                        "mass tag member page | group=%s filter=%s page=%s offset=%s users=%s parts=%s added=%s count=%s total=%s",
                        group_id, filter_name, page_no, offset, len(batch_users), len(batch_parts), added, count_value, len(users),
                    )
                    if raw_step <= 0:
                        break
                    offset += raw_step
                    if added <= 0:
                        no_progress_pages += 1
                    else:
                        no_progress_pages = 0
                    if no_progress_pages >= 2:
                        break
                    if count_value is not None and count_value > 0 and offset >= int(count_value):
                        break
            except Exception as exc:
                log.warning(
                    "mass tag native participant fetch failed | group=%s filter=%s collected=%s | %s: %s",
                    group_id, filter_name, len(users), type(exc).__name__, exc,
                )

        # SPlusthon itself documents that Soroush Plus may cap participant
        # enumeration. The admin log is therefore used as a membership roster
        # reconstruction source, not merely as an error fallback.
        if expected_count is None or len(users) < min(int(expected_count or TAG_MAX_MEMBERS), TAG_MAX_MEMBERS):
            await scan_admin_log(channel_input)

        try:
            high_level = list(
                await asyncio.wait_for(
                    client.get_participants(
                        group,
                        limit=TAG_MAX_MEMBERS,
                        filter=(recent_cls() if recent_cls is not None else None),
                    ),
                    timeout=35,
                )
            )
            added = await append_users(high_level, source="participants")
            log.info(
                "mass tag participant high-level merge | group=%s returned=%s added=%s total=%s",
                group_id, len(high_level), added, len(users),
            )
        except Exception as exc:
            log.warning(
                "mass tag participant high-level fallback failed | group=%s | %s: %s",
                group_id, type(exc).__name__, exc,
            )

    elif isinstance(group, types.Chat):
        try:
            full = await asyncio.wait_for(
                client(functions.messages.GetFullChatRequest(chat_id=int(group.id))),
                timeout=20,
            )
            chat_users = list(getattr(full, "users", None) or [])[:TAG_MAX_MEMBERS]
            await append_users(chat_users, source="participants")
            participant_box = getattr(getattr(full, "full_chat", None), "participants", None)
            participants = list(getattr(participant_box, "participants", None) or [])
            joined_map.update(_participant_date_map(participants))
            expected_count = len(participants) if participants else len(chat_users)
            log.info(
                "mass tag basic-chat participant fetch PASS | group=%s users=%s expected=%s",
                group_id, len(users), expected_count,
            )
        except Exception as exc:
            log.warning(
                "mass tag basic-chat participant fetch failed | group=%s | %s: %s",
                group_id, type(exc).__name__, exc,
            )
    else:
        try:
            high_level = list(
                await asyncio.wait_for(
                    client.get_participants(group, limit=TAG_MAX_MEMBERS),
                    timeout=30,
                )
            )
            await append_users(high_level, source="participants")
        except Exception as exc:
            log.warning(
                "mass tag generic participant fetch failed | group=%s | %s: %s",
                group_id, type(exc).__name__, exc,
            )

    stats_rows: Dict[int, Dict[str, Any]] = {}
    reference_message_ids: Dict[int, int] = {}
    local_names: Dict[int, str] = {}
    try:
        with db_connect() as con:
            rows = con.execute(
                "SELECT user_id, username, access_hash, first_seen_at, last_seen_at FROM stats_members WHERE group_id = ? ORDER BY first_seen_at ASC",
                (int(group_id),),
            ).fetchall()
            message_rows = con.execute(
                "SELECT user_id, message_id, sent_ts FROM message_stats WHERE group_id = ? ORDER BY sent_ts DESC LIMIT ?",
                (int(group_id), max(10000, min(100000, int(TAG_MAX_MEMBERS) * 25))),
            ).fetchall()
            join_rows = con.execute(
                "SELECT user_id, access_hash, username, display_name, joined_at FROM welcome_join_history WHERE group_id = ? ORDER BY joined_at DESC LIMIT ?",
                (int(group_id), int(TAG_MAX_MEMBERS)),
            ).fetchall()
        for row in rows:
            uid = int(row["user_id"])
            dt = parse_iso_datetime(row["first_seen_at"])
            stats_rows[uid] = {
                "username": str(row["username"] or ""),
                "access_hash": int(row["access_hash"] or 0),
                "joined_ts": dt.timestamp() if dt is not None else float("inf"),
            }
        for row in join_rows:
            uid = int(row["user_id"])
            if admin_states.get(uid) is False:
                continue
            dt = parse_iso_datetime(row["joined_at"])
            existing = stats_rows.setdefault(uid, {})
            if not str(existing.get("username") or ""):
                existing["username"] = str(row["username"] or "")
            if not int(existing.get("access_hash") or 0):
                existing["access_hash"] = int(row["access_hash"] or 0)
            if not existing.get("joined_ts") or existing.get("joined_ts") == float("inf"):
                existing["joined_ts"] = dt.timestamp() if dt is not None else float("inf")
            if str(row["display_name"] or ""):
                local_names[uid] = str(row["display_name"])
        for row in message_rows:
            uid = int(row["user_id"])
            if uid not in reference_message_ids:
                reference_message_ids[uid] = int(row["message_id"])
    except Exception as exc:
        log.warning(
            "mass tag local member registry read failed | group=%s | %s: %s",
            group_id, type(exc).__name__, exc,
        )

    members_by_id: Dict[int, Dict[str, Any]] = {}
    for user in users:
        uid = safe_int(getattr(user, "id", None))
        if uid is None or int(uid) == SELF_USER_ID or int(uid) in SYSTEM_USER_IDS:
            continue
        if admin_states.get(int(uid)) is False:
            continue
        if bool(getattr(user, "deleted", False)) or bool(getattr(user, "bot", False)):
            continue
        cached = stats_rows.get(int(uid), {})
        username = str(getattr(user, "username", None) or cached.get("username") or "")
        name = display_name(user) or local_names.get(int(uid)) or (f"@{username}" if username else f"کاربر {uid}")
        access_hash = (
            safe_int(getattr(user, "access_hash", None))
            or int(cached.get("access_hash") or 0)
            or stats_access_hash(group_id, int(uid))
            or 0
        )
        status_name = type(getattr(user, "status", None)).__name__.lower()
        online = "userstatusonline" in status_name or status_name.endswith("statusonline")
        joined_ts = joined_map.get(int(uid), float(cached.get("joined_ts", float("inf"))))
        members_by_id[int(uid)] = {
            "id": int(uid),
            "access_hash": int(access_hash or 0),
            "username": username,
            "name": str(name),
            "online": bool(online),
            "joined_ts": float(joined_ts),
            "reference_message_id": int(reference_message_ids.get(int(uid), 0) or 0),
            "source": user_sources.get(int(uid), "participants"),
        }

    # Merge the durable per-group registry and join history. Users whose newest
    # admin-log membership event is leave/kick are explicitly excluded.
    for uid, cached in stats_rows.items():
        if uid == SELF_USER_ID or uid in SYSTEM_USER_IDS or admin_states.get(uid) is False:
            continue
        if uid not in members_by_id:
            username = str(cached.get("username") or "")
            members_by_id[uid] = {
                "id": int(uid),
                "access_hash": int(cached.get("access_hash") or 0),
                "username": username,
                "name": local_names.get(uid) or (f"@{username}" if username else f"کاربر {uid}"),
                "online": False,
                "joined_ts": float(cached.get("joined_ts", float("inf"))),
                "reference_message_id": int(reference_message_ids.get(uid, 0) or 0),
                "source": "registry",
            }

    for uid, message_id in reference_message_ids.items():
        if uid == SELF_USER_ID or uid in SYSTEM_USER_IDS or admin_states.get(uid) is False:
            continue
        member = members_by_id.get(uid)
        if member is None:
            members_by_id[uid] = {
                "id": int(uid),
                "access_hash": int(stats_access_hash(group_id, uid) or 0),
                "username": "",
                "name": local_names.get(uid) or f"کاربر {uid}",
                "online": False,
                "joined_ts": float("inf"),
                "reference_message_id": int(message_id),
                "source": "message-registry",
            }
        elif not int(member.get("reference_message_id") or 0):
            member["reference_message_id"] = int(message_id)

    members = list(members_by_id.values())[:TAG_MAX_MEMBERS]
    resolvable = sum(
        1 for member in members
        if int(member.get("access_hash") or 0)
        or str(member.get("username") or "")
        or int(member.get("reference_message_id") or 0)
    )
    participant_sources = sum(1 for m in members if m.get("source") == "participants")
    adminlog_sources = sum(1 for m in members if m.get("source") == "adminlog")
    registry_sources = len(members) - participant_sources - adminlog_sources
    coverage = None
    if expected_count and int(expected_count) > 0:
        coverage = round((len(members) / int(expected_count)) * 100.0, 1)
    log.info(
        "mass tag member registry ready | group=%s expected=%s participants=%s adminlog=%s registry=%s total=%s resolvable=%s coverage=%s%% inactive_filtered=%s",
        group_id,
        expected_count,
        participant_sources,
        adminlog_sources,
        registry_sources,
        len(members),
        resolvable,
        coverage if coverage is not None else "unknown",
        sum(1 for state in admin_states.values() if state is False),
    )
    return members

async def _enrich_tag_members_from_history(
    group: Any,
    group_id: int,
    members: List[Dict[str, Any]],
) -> None:
    missing = {
        int(member["id"]): member
        for member in members
        if not int(member.get("access_hash") or 0)
        and not str(member.get("username") or "")
    }
    if not missing:
        return

    history_limit = min(5000, max(500, len(missing) * 25))
    try:
        scanned_history = 0
        async for message in client.iter_messages(
            group,
            limit=history_limit,
            wait_time=0.25,
        ):
            scanned_history += 1
            if scanned_history % 50 == 0:
                await _yield_background_to_realtime(0.5)
                await asyncio.sleep(0)
            uid = safe_int(getattr(message, "sender_id", None))
            if uid is None or int(uid) not in missing:
                continue
            member = missing[int(uid)]
            message_id = safe_int(getattr(message, "id", None))
            if message_id:
                member["reference_message_id"] = int(message_id)

            input_sender = getattr(message, "input_sender", None)
            access_hash = input_peer_access_hash(input_sender)
            sender_obj = getattr(message, "sender", None)
            if not access_hash and sender_obj is not None:
                access_hash = safe_int(getattr(sender_obj, "access_hash", None)) or 0
            if access_hash:
                member["access_hash"] = int(access_hash)
                remember_moderation_access_hash(group_id, int(uid), int(access_hash))

            if sender_obj is not None:
                username = str(getattr(sender_obj, "username", None) or "")
                if username:
                    member["username"] = username
                name = display_name(sender_obj)
                if name:
                    member["name"] = str(name)

            if int(member.get("access_hash") or 0) or str(member.get("username") or "") or int(member.get("reference_message_id") or 0):
                missing.pop(int(uid), None)
                if not missing:
                    break
    except Exception as exc:
        log.debug(
            "tag history enrichment skipped | group=%s missing=%s | %s: %s",
            group_id, len(missing), type(exc).__name__, exc,
        )


def _tag_select_members(
    members: List[Dict[str, Any]],
    mode: str,
    count: Optional[int],
    actor_id: int,
) -> List[Dict[str, Any]]:
    pool = [m for m in members if int(m["id"]) != int(actor_id)]
    if mode == "online":
        pool = [m for m in pool if m.get("online")]
    elif mode == "old":
        pool.sort(key=lambda m: (float(m.get("joined_ts", float("inf"))), int(m["id"])))
    elif mode == "new":
        pool.sort(
            key=lambda m: (
                -1.0 if float(m.get("joined_ts", float("inf"))) == float("inf") else float(m.get("joined_ts", 0.0)),
                int(m["id"]),
            ),
            reverse=True,
        )
    elif mode == "random":
        random.shuffle(pool)

    if count is not None:
        return pool[: max(0, int(count))]
    return pool


def _tag_label(member: Dict[str, Any]) -> str:
    username = str(member.get("username") or "")
    if username:
        return f"@{username}"
    clean_name = " ".join(str(member.get("name") or "کاربر").split())[:24]
    return f"﹝{clean_name} · {member['id']}﹞"


async def _run_tag_job_inner(
    group: Any,
    group_id: int,
    actor_id: int,
    source_message_id: int,
    mode: str,
    count: Optional[int],
) -> None:
    try:
        log.info(
            "mass tag job START | group=%s actor=%s source=%s mode=%s count=%s",
            group_id, actor_id, source_message_id, mode, count,
        )
        await asyncio.wait_for(
            send_group_text(
                group,
                "📡 زیوو در حال آماده‌سازی فهرست اعضا برای تگ است…",
                reply_to=source_message_id,
            ),
            timeout=15,
        )
        log.info("mass tag stage | group=%s stage=fetch_members", group_id)
        members = await asyncio.wait_for(
            _fetch_tag_members(group, group_id),
            timeout=max(120, TAG_ADMIN_LOG_TIMEOUT_SECONDS + 30),
        )
        selected = _tag_select_members(members, mode, count, actor_id)
        log.info(
            "mass tag stage | group=%s stage=select members=%s selected=%s mode=%s",
            group_id, len(members), len(selected), mode,
        )
        await asyncio.wait_for(
            _enrich_tag_members_from_history(group, group_id, selected),
            timeout=35,
        )
        log.info(
            "mass tag stage | group=%s stage=enrich selected=%s",
            group_id, len(selected),
        )
        if not selected:
            await send_group_text(
                group,
                "⚠️ برای این انتخاب کاربر قابل تگی پیدا نشد. در حالت آنلاین، فقط وضعیت آنلاین قابل مشاهده برای زیوو حساب می‌شود.",
                reply_to=source_message_id,
            )
            return

        unmentionable = [
            member for member in selected
            if not int(member.get("access_hash") or 0)
            and not str(member.get("username") or "")
            and not int(member.get("reference_message_id") or 0)
        ]
        selected = [
            member for member in selected
            if int(member.get("access_hash") or 0)
            or str(member.get("username") or "")
            or int(member.get("reference_message_id") or 0)
        ]
        if not selected:
            await send_group_text(
                group,
                "⚠️ اعضا پیدا شدند اما سروش برای هیچ‌کدام شناسه منشن قابل اعتماد در اختیار زیوو نگذاشت.",
                reply_to=source_message_id,
            )
            return

        total = len(selected)
        batch_size = TAG_LARGE_BATCH_SIZE if total >= TAG_LARGE_THRESHOLD else (10 if total >= 40 else 5)
        stage_size = min(total, TAG_STAGE_SIZE) if total >= TAG_LARGE_THRESHOLD else total
        sent_count = 0
        failed = 0
        stage_total = max(1, (total + stage_size - 1) // stage_size)

        async def send_batch(start_index: int, batch: List[Dict[str, Any]]) -> Tuple[int, int]:
            labels = [_tag_label(member) for member in batch]
            body = "📣 " + "  ".join(labels)
            mentions = [
                (
                    label,
                    int(member["id"]),
                    int(member.get("access_hash") or 0),
                    int(member.get("reference_message_id") or 0),
                )
                for label, member in zip(labels, batch)
            ]
            try:
                await asyncio.wait_for(
                    send_group_text_with_mentions(
                        group, body, mentions, reply_to=int(source_message_id),
                        require_entities=True, cleanup_category="tag",
                    ),
                    timeout=TAG_SEND_TIMEOUT_SECONDS,
                )
                log.info(
                    "tag batch PASS | group=%s start=%s size=%s",
                    group_id, start_index, len(batch),
                )
                return len(batch), 0
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                wait_seconds = safe_int(getattr(exc, "seconds", None)) or 0
                log.warning(
                    "tag batch split retry | group=%s start=%s size=%s | %s: %s",
                    group_id, start_index, len(batch), type(exc).__name__, exc,
                )
                if wait_seconds > 0:
                    await asyncio.sleep(min(60, int(wait_seconds) + 1))
                if len(batch) > 5:
                    good = bad = 0
                    for sub_offset in range(0, len(batch), 5):
                        sub = batch[sub_offset:sub_offset + 5]
                        sub_good, sub_bad = await send_batch(start_index + sub_offset, sub)
                        good += sub_good
                        bad += sub_bad
                        await _yield_background_to_realtime(0.5)
                        await asyncio.sleep(0.15)
                    return good, bad

                good = bad = 0
                for label, member in zip(labels, batch):
                    try:
                        await asyncio.wait_for(
                            send_group_text_with_mentions(
                                group,
                                "📣 " + label,
                                [(label, int(member["id"]), int(member.get("access_hash") or 0), int(member.get("reference_message_id") or 0))],
                                reply_to=int(source_message_id),
                                require_entities=True,
                                cleanup_category="tag",
                            ),
                            timeout=TAG_SEND_TIMEOUT_SECONDS,
                        )
                        good += 1
                    except asyncio.CancelledError:
                        raise
                    except Exception as member_exc:
                        bad += 1
                        log.warning(
                            "tag member failed | group=%s user=%s | %s: %s",
                            group_id, member.get("id"), type(member_exc).__name__, member_exc,
                        )
                    await asyncio.sleep(0.12)
                return good, bad

        for stage_index, stage_start in enumerate(range(0, total, stage_size), start=1):
            stage_end = min(total, stage_start + stage_size)
            log.info(
                "mass tag send stage START | group=%s stage=%s/%s range=%s-%s batch=%s",
                group_id, stage_index, stage_total, stage_start, stage_end, batch_size,
            )
            for start in range(stage_start, stage_end, batch_size):
                batch = selected[start:min(stage_end, start + batch_size)]
                await _wait_transport_background_slot(soft_limit=130, max_wait=4.0)
                good, bad = await send_batch(start, batch)
                sent_count += good
                failed += bad
                await _yield_background_to_realtime(0.8)
                await asyncio.sleep(TAG_BATCH_DELAY_SECONDS)

            log.info(
                "mass tag send stage PASS | group=%s stage=%s/%s sent=%s failed=%s",
                group_id, stage_index, stage_total, sent_count, failed,
            )
            if stage_end < total:
                await _yield_background_to_realtime(1.5)
                await asyncio.sleep(TAG_STAGE_PAUSE_SECONDS)

        await send_group_text(
            group,
            (
                "✅ تگ گروهی تمام شد.\n"
                f"👥 درخواست‌شده/انتخاب‌شده: {total}\n"
                f"🔔 تگ ارسال‌شده: {sent_count}\n"
                f"⚠️ ناموفق: {failed}\n"
                f"🚫 بدون شناسه منشن قابل اعتماد: {len(unmentionable)}"
            ),
            reply_to=source_message_id,
        )
        log.info(
            "mass tag completed | group=%s actor=%s mode=%s selected=%s sent=%s failed=%s",
            group_id, actor_id, mode, total, sent_count, failed,
        )
    except asyncio.CancelledError:
        try:
            await send_group_text(group, "🛑 عملیات تگ متوقف شد.", reply_to=source_message_id)
        except Exception:
            pass
        raise
    except Exception as exc:
        log.exception("mass tag job failed | group=%s", group_id)
        try:
            await send_group_text(
                group,
                f"❌ عملیات تگ متوقف شد: {type(exc).__name__}",
                reply_to=source_message_id,
            )
        except Exception:
            pass
    finally:
        _tag_tasks.pop(int(group_id), None)
        _tag_sessions.pop(int(group_id), None)


async def _run_tag_job(
    group: Any,
    group_id: int,
    actor_id: int,
    source_message_id: int,
    mode: str,
    count: Optional[int],
) -> None:
    global _tag_global_sem
    if _tag_global_sem is None:
        _tag_global_sem = asyncio.Semaphore(TAG_GLOBAL_CONCURRENCY)
    try:
        async with _tag_global_sem:
            await _run_tag_job_inner(group, group_id, actor_id, source_message_id, mode, count)
    finally:
        _tag_tasks.pop(int(group_id), None)
        _tag_sessions.pop(int(group_id), None)


async def command_tag(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    actor_role = base_bot_role(group_id, int(actor_id))
    if actor_role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ قابلیت تگ گروهی فقط برای مالک یا ادمین زیوو است.")
        return

    action = str(parsed.get("action") or "")
    running = _tag_tasks.get(int(group_id))
    current_session = _tag_session(group_id)
    log.info(
        "mass tag flow | group=%s actor=%s action=%s stage=%s reply=%s",
        group_id, actor_id, action,
        current_session.get("stage") if current_session else "none",
        bool(getattr(event, "is_reply", False)),
    )

    if action == "cancel":
        _tag_sessions.pop(int(group_id), None)
        if running is not None and not running.done():
            running.cancel()
            await send_group_text(group, "🛑 درخواست توقف تگ ثبت شد.")
        else:
            await send_group_text(group, "✅ فرایند یا درخواست باز تگ لغو شد.")
        return

    if action == "status":
        session = _tag_session(group_id)
        if running is not None and not running.done():
            await send_group_text(group, "📡 یک عملیات تگ در این گروه در حال اجراست. برای توقف: لغو تگ")
        elif session:
            await send_group_text(group, f"🧭 درخواست تگ در مرحله «{session.get('stage')}» منتظر ادامه است. برای لغو: لغو تگ")
        else:
            await send_group_text(group, "📭 هیچ عملیات تگ فعالی در این گروه نیست.")
        return

    if running is not None and not running.done():
        await send_group_text(group, "⚠️ یک عملیات تگ از قبل در حال اجراست. اول «لغو تگ» بزن.")
        return

    if action == "start":
        if not bool(getattr(event, "is_reply", False)):
            await send_group_text(
                group,
                "📣 روی پیامی که می‌خواهی اعضا برای خواندنش تگ شوند ریپلای کن و بنویس: تگ",
            )
            return
        reply = await event.get_reply_message()
        source_id = safe_int(getattr(reply, "id", None)) if reply is not None else None
        if source_id is None:
            await send_group_text(group, "❌ پیام مرجع تگ پیدا نشد.")
            return
        _tag_sessions[int(group_id)] = {
            "actor_id": int(actor_id),
            "source_message_id": int(source_id),
            "stage": "choose_scope",
            "created_mono": time.monotonic(),
            "count": None,
            "mode": "all",
        }
        log.info(
            "mass tag flow | group=%s actor=%s stage=choose_scope source=%s",
            group_id, actor_id, source_id,
        )
        await send_group_text(
            group,
            (
                "📣 ZIVO | تگ گروهی\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "پیام مرجع ثبت شد. انتخاب کن:\n"
                "• کل گروه\n"
                "• 50   ← یا هر تعداد دلخواه\n"
                "(فرم کامل «تگ کل گروه» و «تگ تعداد 50» هم پشتیبانی می‌شود.)\n\n"
                "بعد از انتخاب، زیوو قبل از شروع دوباره تایید می‌گیرد.\n"
                "برای انصراف: لغو تگ"
            ),
            reply_to=int(source_id),
        )
        return

    session = _tag_session(group_id)
    if not session or int(session.get("actor_id") or 0) != int(actor_id):
        await send_group_text(group, "⚠️ اول روی پیام موردنظر ریپلای کن و بنویس: تگ")
        return

    if action == "all":
        session["count"] = None
        session["mode"] = "all"
        session["stage"] = "confirm"
        await send_group_text(
            group,
            (
                "⚠️ تگ تمام اعضای قابل دریافت گروه انتخاب شد.\n"
                "هر پیام تگ روی همان پیام مرجع ریپلای می‌شود و اعضا دسته‌ای تگ می‌شوند.\n\n"
                "اگر مطمئنی بزن: تایید\n"
                "انصراف: لغو"
            ),
            reply_to=int(session["source_message_id"]),
        )
        return

    if action == "count":
        count = max(1, min(TAG_MAX_MEMBERS, int(parsed.get("count") or 1)))
        session["count"] = count
        session["stage"] = "choose_mode"
        await send_group_text(
            group,
            (
                f"👥 تعداد انتخاب‌شده: {count}\n"
                "حالا نوع انتخاب اعضا را مشخص کن:\n"
                "• قدیمی\n"
                "• جدید\n"
                "• آنلاین\n"
                "• تصادفی\n"
                "(فرم‌های «تگ قدیمی/آنلاین/…» هم پشتیبانی می‌شوند.)\n\n"
                "برای انصراف: لغو تگ"
            ),
            reply_to=int(session["source_message_id"]),
        )
        return

    if action == "mode":
        if session.get("count") is None:
            await send_group_text(group, "⚠️ اول تعداد را با نمونه «تگ تعداد 50» مشخص کن.")
            return
        mode = str(parsed.get("mode") or "random")
        session["mode"] = mode
        session["stage"] = "confirm"
        names = {"old": "قدیمی‌ها", "new": "جدیدها", "online": "آنلاین‌ها", "random": "تصادفی"}
        await send_group_text(
            group,
            (
                f"✅ انتخاب: {session['count']} نفر از {names.get(mode, mode)}\n"
                "اگر مطمئنی بزن: تایید\n"
                "انصراف: لغو"
            ),
            reply_to=int(session["source_message_id"]),
        )
        return

    if action == "confirm":
        if session.get("stage") != "confirm":
            await send_group_text(group, "⚠️ انتخاب تگ هنوز کامل نشده.")
            return
        source_message_id = int(session["source_message_id"])
        mode = str(session.get("mode") or "all")
        count = session.get("count")
        _tag_sessions.pop(int(group_id), None)
        task = asyncio.create_task(
            _run_tag_job(
                group,
                int(group_id),
                int(actor_id),
                source_message_id,
                mode,
                int(count) if count is not None else None,
            )
        )
        _tag_tasks[int(group_id)] = task
        log.info(
            "mass tag task scheduled | group=%s actor=%s source=%s mode=%s count=%s task=%s",
            group_id, actor_id, source_message_id, mode, count, id(task),
        )

        def _tag_done(done_task: asyncio.Task) -> None:
            try:
                if done_task.cancelled():
                    log.info("mass tag task DONE | group=%s status=cancelled", group_id)
                    return
                exc = done_task.exception()
                if exc is not None:
                    log.error(
                        "mass tag task DONE | group=%s status=error | %s: %s",
                        group_id, type(exc).__name__, exc,
                    )
                else:
                    log.info("mass tag task DONE | group=%s status=ok", group_id)
            except Exception as callback_exc:
                log.warning(
                    "mass tag task callback failed | group=%s | %s: %s",
                    group_id, type(callback_exc).__name__, callback_exc,
                )

        task.add_done_callback(_tag_done)
        await asyncio.sleep(0)
        await asyncio.wait_for(
            send_group_text(
                group,
                "🚀 تگ شروع شد. برای توقف در هر لحظه: لغو تگ",
                reply_to=source_message_id,
            ),
            timeout=15,
        )
        return


