def parse_anti_spam_command(
    text: str,
) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(text)

    if text in {
        "تنظیمات اسپم",
        "تنظیمات ضداسپم",
        "وضعیت اسپم",
        "وضعیت ضداسپم",
        "وضعیت ضدفلود",
        "وضعیت فلود",
    }:
        return {"action": "show_anti_spam_settings"}

    if text in {
        "اسپم فعال", "محافظ اسپم فعال", "اسپم روشن",
        "ضدفلود فعال", "ضد فلود فعال",
        "ضدفلود روشن", "ضد فلود روشن",
    }:
        return {"action": "set_flood_guard", "enabled": True}

    if text in {
        "اسپم خاموش", "محافظ اسپم خاموش", "اسپم غیرفعال", "اسپم غیر فعال",
        "ضدفلود خاموش", "ضد فلود خاموش",
        "ضدفلود غیرفعال", "ضد فلود غیرفعال",
    }:
        return {"action": "set_flood_guard", "enabled": False}

    if text in {
        "پاکسازی اسپم کامل",
        "تنظیم پاکسازی اسپم کامل",
        "پاکسازی ضدفلود کامل",
        "پاکسازی ضد فلود کامل",
        "تنظیم پاکسازی ضدفلود کامل",
        "تنظیم پاکسازی ضد فلود کامل",
    }:
        return {
            "action": "set_flood_guard_value",
            "field": "cleanup_scan_limit",
            "value": 0,
            "minimum": 0,
            "maximum": 10000,
        }

    patterns = (
        (r"^(?:تنظیم\s+)?حد\s+(?:محافظ\s+)?اسپم\s+(\d+)$", "burst_limit", 6, 50),
        (r"^(?:تنظیم\s+)?زمان\s+(?:محافظ\s+)?اسپم\s+(\d+)$", "window_seconds", 3, 60),
        (r"^(?:تنظیم\s+)?پشت\s*سرهم\s+(?:محافظ\s+)?اسپم\s+(\d+)$", "consecutive_limit", 5, 30),
        (r"^(?:تنظیم\s+)?پاکسازی\s+(?:محافظ\s+)?اسپم\s+(\d+)$", "cleanup_scan_limit", 200, 10000),
        (r"^(?:تنظیم\s+)?حد\s+ضد ?فلود\s+(\d+)$", "burst_limit", 6, 50),
        (r"^(?:تنظیم\s+)?زمان\s+ضد ?فلود\s+(\d+)$", "window_seconds", 3, 60),
        (r"^(?:تنظیم\s+)?پشت\s*سرهم\s+ضد ?فلود\s+(\d+)$", "consecutive_limit", 5, 30),
        (r"^(?:تنظیم\s+)?پاکسازی\s+ضد ?فلود\s+(\d+)$", "cleanup_scan_limit", 200, 10000),
    )

    normalized_ascii = text.translate(PERSIAN_ARABIC_TO_ASCII)
    for pattern, field, minimum, maximum in patterns:
        match = re.match(pattern, normalized_ascii)
        if match:
            return {
                "action": "set_flood_guard_value",
                "field": field,
                "value": int(match.group(1)),
                "minimum": minimum,
                "maximum": maximum,
            }

    return None


async def command_anti_spam(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    action = parsed.get("action")

    if action == "show_anti_spam_settings":
        await send_group_text(group, anti_spam_settings_text(group_id))
        return

    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return

    role = base_bot_role(group_id, actor_id)
    if role not in {"مالک", "ادمین"}:
        await send_group_text(
            group,
            "⛔ تغییر تنظیمات اسپم فقط برای مالک و ادمین زیوو مجازه.",
        )
        return

    if action == "set_flood_guard":
        enabled = bool(parsed.get("enabled"))
        settings = update_flood_guard_settings(
            group_id, actor_id, enabled=1 if enabled else 0
        )
    elif action == "set_flood_guard_value":
        value = int(parsed.get("value") or 0)
        minimum = int(parsed.get("minimum") or 0)
        maximum = int(parsed.get("maximum") or 0)
        if value < minimum or value > maximum:
            await send_group_text(
                group,
                f"⛔ مقدار مجاز بین {stats_num(minimum)} تا {stats_num(maximum)} است.",
            )
            return
        field = str(parsed.get("field") or "")
        if field not in {
            "burst_limit", "window_seconds",
            "consecutive_limit", "cleanup_scan_limit",
        }:
            return
        settings = update_flood_guard_settings(
            group_id, actor_id, **{field: value}
        )
    else:
        return

    # Reset volatile counters after every setting change so old traffic cannot
    # immediately trip a newly configured threshold.
    _flood_guard_last_sender.pop(int(group_id), None)
    for key in [key for key in _flood_guard_event_times if key[0] == int(group_id)]:
        _flood_guard_event_times.pop(key, None)
    for key in [key for key in _flood_guard_action_until if key[0] == int(group_id)]:
        _flood_guard_action_until.pop(key, None)

    await send_group_text(
        group,
        (
            "🛡 ZIVO | SPAM GUARD\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"🎖 اجراکننده: {role}\n"
            f"🧹 وضعیت: {'روشن ✅' if settings['enabled'] else 'خاموش ⛔'}\n"
            f"📨 حد پیام: {stats_num(settings['burst_limit'])} در {stats_num(settings['window_seconds'])} ثانیه\n"
            f"🔁 پشت سرهم: {stats_num(settings['consecutive_limit'])} پیام\n"
            f"📚 پاکسازی زنده: {'تا ' + stats_num(FLOOD_GUARD_LIVE_DELETE_MAX) + ' پیام اخیر' if settings['cleanup_scan_limit'] == 0 else 'تا ' + stats_num(min(FLOOD_GUARD_LIVE_DELETE_MAX, settings['cleanup_scan_limit'])) + ' پیام اخیر'}\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "⚡ ZIVO | SPAM CONTROL"
        ),
    )


ANTI_SPAM_SETTINGS_CACHE_TTL = 300.0
ANTI_SPAM_CONTENT_WINDOW_MIN = 15.0
ANTI_SPAM_VIOLATION_WINDOW = 300.0
ANTI_SPAM_SOFT_COOLDOWN = 10.0
ANTI_SPAM_HARD_COOLDOWN = 60.0

def invalidate_message_rate_settings_cache(group_id: int) -> None:
    _message_rate_settings_cache.pop(int(group_id), None)


def get_message_rate_limit_settings(group_id: int) -> Dict[str, int]:
    gid = int(group_id)
    now = time.monotonic()
    cached = _message_rate_settings_cache.get(gid)
    if cached is not None and now - cached[0] < MESSAGE_RATE_SETTINGS_CACHE_TTL:
        return dict(cached[1])

    with db_connect() as con:
        row = con.execute(
            "SELECT enabled, interval_seconds FROM message_rate_limit_settings WHERE group_id = ?",
            (gid,),
        ).fetchone()

    settings = {
        "enabled": int(row["enabled"] or 0) if row is not None else 0,
        "interval_seconds": max(
            MESSAGE_RATE_MIN_SECONDS,
            min(MESSAGE_RATE_MAX_SECONDS, int(row["interval_seconds"] or 5) if row is not None else 5),
        ),
    }
    _message_rate_settings_cache[gid] = (now, dict(settings))
    return settings


def update_message_rate_limit_settings(
    group_id: int,
    actor_id: int,
    *,
    enabled: Optional[bool] = None,
    interval_seconds: Optional[int] = None,
) -> Dict[str, int]:
    gid = int(group_id)
    current = get_message_rate_limit_settings(gid)
    new_enabled = int(current["enabled"] if enabled is None else (1 if enabled else 0))
    new_interval = int(current["interval_seconds"] if interval_seconds is None else interval_seconds)
    new_interval = max(MESSAGE_RATE_MIN_SECONDS, min(MESSAGE_RATE_MAX_SECONDS, new_interval))
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO message_rate_limit_settings (
                group_id, enabled, interval_seconds, updated_by, updated_at
            ) VALUES (?, ?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                enabled = excluded.enabled,
                interval_seconds = excluded.interval_seconds,
                updated_by = excluded.updated_by,
                updated_at = excluded.updated_at
            """,
            (
                gid,
                new_enabled,
                new_interval,
                int(actor_id),
                datetime.now(timezone.utc).isoformat(),
            ),
        )
        con.commit()
    invalidate_message_rate_settings_cache(gid)
    mark_group_backup_dirty(gid)
    return get_message_rate_limit_settings(gid)


def parse_message_rate_limit_command(text: str) -> Optional[Dict[str, Any]]:
    normalized = normalize_group_command(text)
    if not normalized:
        return None
    normalized_ascii = normalized.translate(PERSIAN_ARABIC_TO_ASCII)

    if normalized in {"محدودیت پیام", "وضعیت محدودیت پیام", "فاصله پیام"}:
        return {"action": "status"}
    if normalized in {
        "محدودیت پیام خاموش", "محدودیت پیام غیرفعال", "محدودیت پیام غیر فعال",
        "فاصله پیام خاموش",
    }:
        return {"action": "enabled", "enabled": False}
    if normalized in {"محدودیت پیام روشن", "محدودیت پیام فعال", "فاصله پیام روشن"}:
        return {"action": "enabled", "enabled": True}

    match = re.fullmatch(r"(?:تنظیم\s+)?محدودیت\s+پیام\s+(\d+)(?:\s*ثانیه)?", normalized_ascii)
    if not match:
        match = re.fullmatch(r"(?:تنظیم\s+)?فاصله\s+پیام\s+(\d+)(?:\s*ثانیه)?", normalized_ascii)
    if match:
        return {"action": "set_interval", "seconds": int(match.group(1))}
    return None


async def command_message_rate_limit(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    actor_role = base_bot_role(group_id, actor_id)
    if actor_role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ تنظیم محدودیت پیام فقط برای مالک و ادمین زیوو مجازه.")
        return

    action = str(parsed.get("action") or "")
    if action == "status":
        settings = get_message_rate_limit_settings(group_id)
    elif action == "enabled":
        settings = update_message_rate_limit_settings(
            group_id, actor_id, enabled=bool(parsed.get("enabled"))
        )
        for key in [key for key in _message_rate_last_accepted if key[0] == int(group_id)]:
            _message_rate_last_accepted.pop(key, None)
        for key in [key for key in _message_rate_native_until if key[0] == int(group_id)]:
            _message_rate_native_until.pop(key, None)
        for key in [key for key in _message_rate_next_allowed if key[0] == int(group_id)]:
            _message_rate_next_allowed.pop(key, None)
            _message_rate_last_message_id.pop(key, None)
    elif action == "set_interval":
        seconds = int(parsed.get("seconds") or 0)
        if seconds < MESSAGE_RATE_MIN_SECONDS or seconds > MESSAGE_RATE_MAX_SECONDS:
            await send_group_text(
                group,
                f"⛔ فاصله پیام باید بین {MESSAGE_RATE_MIN_SECONDS} تا {MESSAGE_RATE_MAX_SECONDS} ثانیه باشه.",
            )
            return
        settings = update_message_rate_limit_settings(
            group_id, actor_id, enabled=True, interval_seconds=seconds
        )
        for key in [key for key in _message_rate_last_accepted if key[0] == int(group_id)]:
            _message_rate_last_accepted.pop(key, None)
        for key in [key for key in _message_rate_native_until if key[0] == int(group_id)]:
            _message_rate_native_until.pop(key, None)
        for key in [key for key in _message_rate_next_allowed if key[0] == int(group_id)]:
            _message_rate_next_allowed.pop(key, None)
            _message_rate_last_message_id.pop(key, None)
    else:
        return

    await send_group_text(
        group,
        (
            "⏱ ZIVO | MESSAGE LIMIT\n"
            "━━━━━━━━━━━━━━━━━━\n"
            f"🎖 اجراکننده: {actor_role}\n"
            f"🔘 وضعیت: {'روشن ✅' if settings['enabled'] else 'خاموش ⛔'}\n"
            f"⏳ فاصله هر کاربر: {stats_num(settings['interval_seconds'])} ثانیه\n"
            "🔇 پیام زودتر از موعد بی‌صدا حذف می‌شود و ربات اخطار تکراری داخل گروه نمی‌فرستد.\n"
            "🛡 مالک، ادمین و کاربران معاف مستثنا هستند.\n"
            "━━━━━━━━━━━━━━━━━━\n"
            "⚡ ZIVO | RATE GUARD"
        ),
    )


def cleanup_message_rate_runtime(now: Optional[float] = None) -> None:
    global _message_rate_cleanup_last
    current = time.monotonic() if now is None else float(now)
    if current - _message_rate_cleanup_last < 30.0:
        return
    _message_rate_cleanup_last = current
    stale_after = float(MESSAGE_RATE_MAX_SECONDS * 4)
    for key, seen_at in list(_message_rate_last_accepted.items()):
        if current - float(seen_at or 0.0) > stale_after:
            _message_rate_last_accepted.pop(key, None)
            _message_rate_next_allowed.pop(key, None)
            _message_rate_last_message_id.pop(key, None)
    for key, until in list(_message_rate_native_until.items()):
        if float(until or 0.0) <= current:
            _message_rate_native_until.pop(key, None)


LIVE_DELETE_DURABLE_MAX_RETRIES = 8


def queue_live_delete_retry(
    group_id: int,
    message_id: int,
    *,
    target_user_id: int = 0,
    reason: str = "moderation",
    error: str = "UNVERIFIED_DELETE",
) -> None:
    """Persist an unverified moderation delete so restart cannot lose it."""
    now = datetime.now(timezone.utc)
    due = (now + timedelta(seconds=1)).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO live_delete_retry_jobs (
                group_id, message_id, target_user_id, reason, status, due_at,
                retry_count, last_error, created_at, updated_at
            ) VALUES (?, ?, ?, ?, 'pending', ?, 0, ?, ?, ?)
            ON CONFLICT(group_id, message_id) DO UPDATE SET
                target_user_id=excluded.target_user_id,
                reason=excluded.reason,
                status='pending',
                due_at=excluded.due_at,
                last_error=excluded.last_error,
                updated_at=excluded.updated_at
            """,
            (
                int(group_id), int(message_id), int(target_user_id or 0),
                str(reason or "moderation")[:64], due, str(error or "")[:500],
                now.isoformat(), now.isoformat(),
            ),
        )
        con.commit()


def due_live_delete_retry_jobs(limit: int = 50) -> List[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            """
            SELECT * FROM live_delete_retry_jobs
            WHERE status='pending' AND due_at <= ?
            ORDER BY due_at ASC LIMIT ?
            """,
            (datetime.now(timezone.utc).isoformat(), max(1, min(200, int(limit)))),
        ).fetchall()


def _reschedule_live_delete_retry(row: sqlite3.Row, error: str) -> bool:
    retry = int(row["retry_count"] or 0) + 1
    gid = int(row["group_id"] or 0)
    mid = int(row["message_id"] or 0)
    now = datetime.now(timezone.utc)
    if retry >= LIVE_DELETE_DURABLE_MAX_RETRIES:
        with db_connect() as con:
            con.execute(
                """
                UPDATE live_delete_retry_jobs
                SET status='failed', retry_count=?, last_error=?, updated_at=?
                WHERE group_id=? AND message_id=?
                """,
                (retry, str(error or "")[:500], now.isoformat(), gid, mid),
            )
            con.commit()
        record_moderation_audit(
            gid, int(row["target_user_id"] or 0), 0,
            "delete_retry_failed", str(row["reason"] or "moderation"), False,
            f"message={mid} retries={retry} error={str(error or '')[:300]}",
        )
        return False
    delay = min(300, max(3, 3 * (2 ** min(retry - 1, 6))))
    with db_connect() as con:
        con.execute(
            """
            UPDATE live_delete_retry_jobs
            SET retry_count=?, due_at=?, last_error=?, updated_at=?
            WHERE group_id=? AND message_id=?
            """,
            (
                retry, (now + timedelta(seconds=delay)).isoformat(),
                str(error or "")[:500], now.isoformat(), gid, mid,
            ),
        )
        con.commit()
    return True


def _complete_live_delete_retry(row: sqlite3.Row, detail: str) -> None:
    gid = int(row["group_id"] or 0)
    mid = int(row["message_id"] or 0)
    with db_connect() as con:
        con.execute(
            "DELETE FROM live_delete_retry_jobs WHERE group_id=? AND message_id=?",
            (gid, mid),
        )
        con.commit()
    record_moderation_audit(
        gid, int(row["target_user_id"] or 0), 0,
        "delete_retry_verified", str(row["reason"] or "moderation"), True,
        f"message={mid} {str(detail or '')[:300]}",
    )


async def live_delete_retry_worker() -> None:
    """Durable retry lane for moderation deletes that were not verified live."""
    await asyncio.sleep(1.0)
    while True:
        try:
            await _yield_background_to_realtime(0.5)
            if live_delete_circuit_is_open() or _transport_pending_request_count(client) >= TRANSPORT_PENDING_WARN:
                await asyncio.sleep(1.5)
                continue
            for row in due_live_delete_retry_jobs():
                if live_delete_circuit_is_open() or _transport_pending_request_count(client) >= TRANSPORT_PENDING_WARN:
                    break
                gid = int(row["group_id"] or 0)
                mid = int(row["message_id"] or 0)
                state = get_group_bot_power_state(gid)
                target = build_stored_pin_peer(
                    gid, state.get("peer_kind", "channel"),
                    int(state.get("group_access_hash", 0) or 0),
                )
                if target is None:
                    try:
                        target = await asyncio.wait_for(client.get_input_entity(gid), timeout=6.0)
                    except Exception as exc:
                        target = None
                        _reschedule_live_delete_retry(row, f"TARGET:{type(exc).__name__}:{exc}")
                if target is None:
                    continue

                exists = await _filter_message_exists_strict(target, mid, timeout=3.0)
                if exists is False:
                    _complete_live_delete_retry(row, "already_absent=1")
                    log.info("live delete durable verified absent | group=%s message=%s", gid, mid)
                    continue
                try:
                    await governed_delete_messages(target, mid, timeout=10.0, lane="live-durable")
                except Exception as exc:
                    _reschedule_live_delete_retry(row, f"DELETE:{type(exc).__name__}:{exc}")
                    log.warning(
                        "live delete durable retry failed | group=%s message=%s retry=%s | %s: %s",
                        gid, mid, int(row["retry_count"] or 0) + 1, type(exc).__name__, exc,
                    )
                    continue
                await asyncio.sleep(0.10)
                verified = await _filter_message_exists_strict(target, mid, timeout=3.0)
                if verified is False:
                    increment_deleted_message_counter(gid, 1)
                    _complete_live_delete_retry(row, "delete_verified=1")
                    log.info("live delete durable PASS | group=%s message=%s", gid, mid)
                else:
                    _reschedule_live_delete_retry(row, f"VERIFY:{verified}")
                    log.warning(
                        "live delete durable unresolved | group=%s message=%s exists=%s retry=%s",
                        gid, mid, verified, int(row["retry_count"] or 0) + 1,
                    )
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("live delete durable worker error")
        await asyncio.sleep(1.5)


async def _retry_live_delete_worker(group: Any, gid: int, message_id: int) -> None:
    for attempt in range(1, 4):
        if live_delete_circuit_is_open():
            return
        await asyncio.sleep(0.25 * attempt)
        if live_delete_circuit_is_open():
            return
        try:
            await governed_delete_messages(
                group, int(message_id), timeout=6.0, lane="live-retry",
            )
            increment_deleted_message_counter(int(gid), 1)
            log.info(
                "live delete retry PASS | group=%s message=%s attempt=%s",
                gid, message_id, attempt,
            )
            return
        except Exception as exc:
            if arm_live_delete_circuit(exc):
                return
            if attempt == 3:
                log.warning(
                    "live delete retry failed | group=%s message=%s | %s: %s",
                    gid, message_id, type(exc).__name__, exc,
                )


async def _verify_live_delete_worker(group: Any, gid: int, message_id: int) -> None:
    # Forward deletes are verified out-of-band so the router stays fast while a
    # server-side no-op delete is still detected and retried. Rate-limit spam
    # intentionally does not use this extra read RPC on every violation.
    if live_delete_circuit_is_open():
        return
    await asyncio.sleep(0.18)
    for attempt in range(1, 3):
        if live_delete_circuit_is_open():
            return
        exists = await _filter_message_exists_strict(group, int(message_id))
        if exists is False:
            log.info(
                "live delete verified PASS | group=%s message=%s attempt=%s",
                gid, message_id, attempt,
            )
            return
        try:
            await governed_delete_messages(
                group, int(message_id), timeout=6.0, lane="live-verify",
            )
        except Exception as exc:
            if arm_live_delete_circuit(exc):
                return
            if attempt == 2:
                log.warning(
                    "live delete verify retry failed | group=%s message=%s exists=%s | %s: %s",
                    gid, message_id, exists, type(exc).__name__, exc,
                )
                return
        if attempt < 2:
            await asyncio.sleep(0.18)
    final_exists = await _filter_message_exists_strict(group, int(message_id))
    if final_exists is not False:
        log.warning(
            "live delete verify unresolved | group=%s message=%s exists=%s",
            gid, message_id, final_exists,
        )


async def delete_live_message_fast(
    group: Any,
    group_id: int,
    message_id: int,
    *,
    message: Optional[Any] = None,
    verify: bool = False,
) -> bool:
    target = message
    if target is not None and message_is_pinned(target):
        log.info("live delete skipped pinned | group=%s message=%s", group_id, message_id)
        return False
    if live_delete_circuit_is_open():
        _perf_counters["live_delete_circuit_skip"] += 1
        return False
    try:
        await governed_delete_messages(
            group, int(message_id), timeout=6.0, lane="live",
        )
    except Exception as exc:
        log.info(
            "live delete immediate deferred | group=%s message=%s | %s: %s",
            group_id, message_id, type(exc).__name__, exc,
        )
        if arm_live_delete_circuit(exc):
            return False
        asyncio.create_task(
            _retry_live_delete_worker(group, int(group_id), int(message_id)),
            name=f"zivo-live-delete-retry-{int(group_id)}-{int(message_id)}",
        )
        return False

    if not verify:
        increment_deleted_message_counter(int(group_id), 1)
        return True

    await asyncio.sleep(0.08)
    exists = await _filter_message_exists_strict(group, int(message_id), timeout=2.5)
    if exists is False:
        increment_deleted_message_counter(int(group_id), 1)
        return True
    if exists is True:
        try:
            await governed_delete_messages(
                group, int(message_id), timeout=6.0, lane="live-verify",
            )
        except Exception as exc:
            if arm_live_delete_circuit(exc):
                return False
        await asyncio.sleep(0.10)
        second = await _filter_message_exists_strict(group, int(message_id), timeout=2.5)
        if second is False:
            increment_deleted_message_counter(int(group_id), 1)
            return True
    asyncio.create_task(
        _verify_live_delete_worker(group, int(group_id), int(message_id)),
        name=f"zivo-live-delete-verify-{int(group_id)}-{int(message_id)}",
    )
    return False


async def _message_rate_native_lock_worker(
    group: Any,
    gid: int,
    sender_id: int,
    target_hash: int,
    remaining: float,
    key: Tuple[int, int],
) -> None:
    if not target_hash or remaining <= 0:
        return
    now = time.monotonic()
    if float(_message_rate_native_until.get(key, 0.0) or 0.0) >= now + remaining - 0.15:
        return
    moderation_state = manual_moderation_row(gid, sender_id)
    if moderation_state is not None and (
        int(moderation_state["muted"] or 0) == 1 or int(moderation_state["banned"] or 0) == 1
    ):
        return
    until_date = datetime.now(timezone.utc) + timedelta(seconds=max(1.0, remaining))
    try:
        native_applied, error_text = await asyncio.wait_for(
            apply_manual_banned_rights(
                group,
                sender_id,
                target_hash,
                mute_banned_rights(until_date),
            ),
            timeout=4.0,
        )
        if native_applied:
            _message_rate_native_until[key] = now + remaining
        else:
            log.debug(
                "message rate native unavailable | group=%s user=%s remain=%.2f error=%s",
                gid, sender_id, remaining, error_text,
            )
    except Exception as exc:
        log.debug(
            "message rate native async failed | group=%s user=%s remain=%.2f | %s: %s",
            gid, sender_id, remaining, type(exc).__name__, exc,
        )


async def maybe_enforce_message_rate_limit(event: Any, group_id: Optional[int] = None) -> bool:
    if bool(getattr(event, "is_private", False)):
        return False
    gid = int(group_id or canonical_anti_spam_group_id(getattr(event, "chat_id", None)) or 0)
    sender_id = safe_int(getattr(event, "sender_id", None))
    message_id = safe_int(getattr(event, "id", None))
    if gid <= 0 or sender_id is None or message_id is None:
        return False
    if sender_id == SELF_USER_ID or sender_id in SYSTEM_USER_IDS:
        return False
    message = getattr(event, "message", None) or event
    if getattr(message, "action", None) is not None:
        return False
    if get_installation(gid) is None or not is_group_bot_enabled(gid):
        return False

    settings = get_message_rate_limit_settings(gid)
    if not int(settings.get("enabled") or 0):
        return False
    if lock_user_is_always_exempt(gid, int(sender_id)):
        return False

    now = time.monotonic()
    cleanup_message_rate_runtime(now)
    key = (gid, int(sender_id))

    # Duplicate delivery of the exact same event must not turn the accepted
    # message into a violation on a second router path.
    if int(_message_rate_last_message_id.get(key, 0) or 0) == int(message_id):
        return False

    interval = float(max(MESSAGE_RATE_MIN_SECONDS, int(settings.get("interval_seconds") or 5)))
    deadline = float(_message_rate_next_allowed.get(key, 0.0) or 0.0)
    if deadline <= now:
        _message_rate_last_accepted[key] = now
        _message_rate_next_allowed[key] = now + interval
        _message_rate_last_message_id[key] = int(message_id)
        return False

    # Reserve the current violation immediately, before the first await. This is
    # the hot-path guarantee that two near-simultaneous messages cannot both pass.
    _message_rate_last_message_id[key] = int(message_id)
    remaining = max(0.05, deadline - now)
    group = fast_event_group_target(event)
    if group is None:
        try:
            group = await asyncio.wait_for(event.get_chat(), timeout=1.5)
        except Exception as exc:
            log.warning(
                "message rate resolve group failed | group=%s user=%s message=%s | %s: %s",
                gid, sender_id, message_id, type(exc).__name__, exc,
            )
            return True

    deleted = await delete_live_message_fast(group, gid, int(message_id), message=message)

    input_sender = getattr(event, "input_sender", None)
    target_hash = int(
        input_peer_access_hash(input_sender)
        or stats_access_hash(gid, int(sender_id))
        or 0
    )
    if target_hash:
        asyncio.create_task(
            _message_rate_native_lock_worker(
                group, gid, int(sender_id), target_hash, remaining, key
            ),
            name=f"zivo-rate-native-{gid}-{int(sender_id)}",
        )

    log.info(
        "message rate blocked immediate | group=%s user=%s message=%s interval=%s remaining=%.2f deleted=%s",
        gid, sender_id, message_id, int(interval), remaining, deleted,
    )
    return True


ANTI_SPAM_HARD_BURST_LIMIT = 10
ANTI_SPAM_HARD_BURST_WINDOW = 5.0
ANTI_SPAM_HARD_BURST_LOCAL_BLOCK = 3600.0
ANTI_SPAM_SEEN_TTL = 120.0
ANTI_SPAM_GROUP_DELETE_INTERVAL = 0.75
FLOOD_GUARD_SCAN_LIMIT = max(
    200,
    min(
        10000,
        int(
            os.getenv(
                "ZIVO_FLOOD_GUARD_SCAN_LIMIT",
                "10000",
            )
        ),
    ),
)
FLOOD_GUARD_DELETE_BATCH_SIZE = max(
    10,
    min(
        100,
        int(os.getenv("ZIVO_FLOOD_GUARD_DELETE_BATCH", "50")),
    ),
)
FLOOD_GUARD_TAIL_BATCH_DELAY = max(
    0.10,
    min(1.0, float(os.getenv("ZIVO_FLOOD_GUARD_TAIL_DELAY", "0.25"))),
)
FLOOD_GUARD_TAIL_QUIET_ROUNDS = max(1, min(5, int(os.getenv("ZIVO_FLOOD_GUARD_TAIL_QUIET_ROUNDS", "2"))))
FLOOD_GUARD_HISTORY_SCAN_CAP = max(200, min(5000, int(os.getenv("ZIVO_FLOOD_GUARD_HISTORY_SCAN_CAP", "1200"))))
FLOOD_GUARD_HISTORY_TASK_MAX = max(1, min(8, int(os.getenv("ZIVO_FLOOD_GUARD_HISTORY_TASK_MAX", "3"))))
EXACT_CONTENT_PURGE_SCAN_LIMIT = max(
    1,
    min(
        100,
        int(
            os.getenv(
                "ZIVO_CONTENT_FILTER_SCAN_LIMIT",
                "100",
            )
        ),
    ),
)


def effective_anti_spam_settings(
    group_id: Optional[int] = None,
) -> Dict[str, int]:
    if group_id is None:
        return dict(
            ANTI_SPAM_DEFAULTS
        )

    now = time.monotonic()
    cached = _anti_spam_settings_cache.get(
        int(group_id)
    )

    if (
        cached is not None
        and now - cached[0]
        < ANTI_SPAM_SETTINGS_CACHE_TTL
    ):
        return dict(
            cached[1]
        )

    settings = get_anti_spam_settings(
        int(group_id)
    )
    effective = {
        "enabled": 1,
        "max_warnings": max(
            1,
            min(
                1000,
                int(
                    settings[
                        "max_warnings"
                    ]
                    or ANTI_SPAM_DEFAULTS[
                        "max_warnings"
                    ]
                ),
            ),
        ),
        "message_limit": max(
            2,
            min(
                1000,
                int(
                    settings[
                        "message_limit"
                    ]
                    or ANTI_SPAM_DEFAULTS[
                        "message_limit"
                    ]
                ),
            ),
        ),
        "window_seconds": max(
            1,
            min(
                300,
                int(
                    settings[
                        "window_seconds"
                    ]
                    or ANTI_SPAM_DEFAULTS[
                        "window_seconds"
                    ]
                ),
            ),
        ),
        "repeat_content_limit": max(
            2,
            min(
                1000,
                int(
                    settings[
                        "repeat_content_limit"
                    ]
                    or ANTI_SPAM_DEFAULTS[
                        "repeat_content_limit"
                    ]
                ),
            ),
        ),
        "repeat_word_limit": max(
            2,
            min(
                1000,
                int(
                    settings[
                        "repeat_word_limit"
                    ]
                    or ANTI_SPAM_DEFAULTS[
                        "repeat_word_limit"
                    ]
                ),
            ),
        ),
    }

    _anti_spam_settings_cache[
        int(group_id)
    ] = (
        now,
        dict(
            effective
        ),
    )

    return effective


def anti_spam_cleanup_runtime(
    now: Optional[float] = None,
) -> None:
    global _anti_spam_cleanup_last
    now = time.monotonic() if now is None else float(now)
    if now - _anti_spam_cleanup_last < 2.0:
        return
    _anti_spam_cleanup_last = now

    stale_seen = [
        key
        for key, seen_at
        in _anti_spam_seen_messages.items()
        if now - seen_at
        > ANTI_SPAM_SEEN_TTL
    ]

    for key in stale_seen:
        _anti_spam_seen_messages.pop(
            key,
            None,
        )

    stale_hard = [
        key
        for key, queue
        in _anti_spam_hard_event_times.items()
        if (
            not queue
            or now - queue[-1]
            > max(
                ANTI_SPAM_HARD_BURST_WINDOW,
                ANTI_SPAM_SEEN_TTL,
            )
        )
    ]

    for key in stale_hard:
        _anti_spam_hard_event_times.pop(
            key,
            None,
        )

    stale_blocks = [
        key
        for key, until
        in _anti_spam_block_until.items()
        if until <= now
    ]

    for key in stale_blocks:
        _anti_spam_block_until.pop(
            key,
            None,
        )

    stale_deletes = [
        key
        for key, seen_at
        in _anti_spam_last_group_delete.items()
        if now - seen_at
        > ANTI_SPAM_SEEN_TTL
    ]

    for key in stale_deletes:
        _anti_spam_last_group_delete.pop(
            key,
            None,
        )


def anti_spam_text_fingerprint(
    text: str,
) -> str:
    normalized = normalize_group_command(
        text or ""
    )

    if not normalized:
        return ""

    return "text:" + hashlib.sha256(
        normalized.encode(
            "utf-8"
        )
    ).hexdigest()


def anti_spam_message_fingerprint(
    text: str,
    message: Optional[Any] = None,
) -> str:
    if message is not None:
        try:
            descriptor = exact_content_descriptor(
                message
            )

            if descriptor is not None:
                return descriptor[
                    "fingerprint"
                ]

        except Exception:
            pass

    return anti_spam_text_fingerprint(
        text
    )


def anti_spam_max_word_repeat(
    text: str,
) -> Tuple[int, str]:
    normalized = normalize_group_command(
        text or ""
    ).lower()

    if not normalized:
        return 0, ""

    words = re.findall(
        r"[0-9A-Za-z_\u0600-\u06FF]+",
        normalized,
    )

    if not words:
        return 0, ""

    counts = Counter(
        word
        for word in words
        if len(word) >= 2
    )

    if not counts:
        return 0, ""

    word, count = counts.most_common(
        1
    )[0]

    return int(count), word


def anti_spam_preflight(
    scope: str,
    scope_id: int,
    user_id: int,
    message_id: int,
    text: str = "",
    message: Optional[Any] = None,
    now: Optional[float] = None,
) -> Dict[str, Any]:
    """
    Mandatory emergency flood shield.

    Normal chatting is never cooled or blocked. Only the 11th+ inbound
    message from the same user inside the hard 5-second window triggers the
    destructive group/private action requested for ZIVO.
    """
    now = (
        time.monotonic()
        if now is None
        else float(now)
    )
    anti_spam_cleanup_runtime(
        now
    )

    scope = (
        "private"
        if scope == "private"
        else "group"
    )
    scope_id = int(
        scope_id
    )
    user_id = int(
        user_id
    )
    message_id = int(
        message_id
    )

    seen_key = (
        scope,
        scope_id,
        user_id,
        message_id,
    )

    if seen_key in _anti_spam_seen_messages:
        return {
            "blocked": False,
            "duplicate": True,
            "reason": "duplicate",
            "warnings": 0,
            "cooldown": 0.0,
            "hard_burst": False,
            "hard_burst_count": 0,
            "hard_action": False,
        }

    _anti_spam_seen_messages[
        seen_key
    ] = now

    key = (
        scope,
        scope_id,
        user_id,
    )

    blocked_until = float(
        _anti_spam_block_until.get(
            key,
            0.0,
        )
        or 0.0
    )

    if blocked_until > now:
        return {
            "blocked": True,
            "duplicate": False,
            "reason": "hard_burst_cooldown",
            "warnings": 1,
            "cooldown": max(
                0.0,
                blocked_until - now,
            ),
            "hard_burst": True,
            "hard_burst_count": ANTI_SPAM_HARD_BURST_LIMIT + 1,
            "hard_action": False,
        }

    hard_times = _anti_spam_hard_event_times.setdefault(
        key,
        deque(),
    )

    while (
        hard_times
        and now - hard_times[0]
        > ANTI_SPAM_HARD_BURST_WINDOW
    ):
        hard_times.popleft()

    hard_times.append(
        now
    )
    hard_burst_count = len(
        hard_times
    )

    if hard_burst_count > ANTI_SPAM_HARD_BURST_LIMIT:
        _anti_spam_block_until[
            key
        ] = now + ANTI_SPAM_HARD_BURST_LOCAL_BLOCK

        return {
            "blocked": True,
            "duplicate": False,
            "reason": "hard_burst",
            "warnings": 1,
            "cooldown": ANTI_SPAM_HARD_BURST_LOCAL_BLOCK,
            "hard_burst": True,
            "hard_burst_count": hard_burst_count,
            "hard_action": True,
        }

    # No soft burst/repeat-content/repeat-word punishment here. Those older
    # rules were too aggressive for command-heavy groups and could suppress
    # legitimate owner/admin traffic before the 11-message emergency limit.
    return {
        "blocked": False,
        "duplicate": False,
        "reason": "",
        "warnings": 0,
        "cooldown": 0.0,
        "hard_burst": False,
        "hard_burst_count": hard_burst_count,
        "hard_action": False,
    }


def anti_spam_private_blocked(
    user_id: int,
) -> bool:
    with db_connect() as con:
        row = con.execute(
            """
            SELECT 1
            FROM anti_spam_private_blocks
            WHERE user_id = ?
            LIMIT 1
            """,
            (
                int(user_id),
            ),
        ).fetchone()

    return row is not None


def record_anti_spam_private_block(
    user_id: int,
    reason: str = "hard_burst",
) -> None:
    with db_connect() as con:
        con.execute(
            """
            INSERT OR REPLACE INTO anti_spam_private_blocks (
                user_id,
                blocked_at,
                reason
            ) VALUES (?, ?, ?)
            """,
            (
                int(user_id),
                datetime.now(
                    timezone.utc
                ).isoformat(),
                reason or "hard_burst",
            ),
        )
        con.commit()


def user_owns_any_installed_group(
    user_id: int,
) -> bool:
    with db_connect() as con:
        row = con.execute(
            """
            SELECT 1
            FROM installations
            WHERE owner_user_id = ?
            LIMIT 1
            """,
            (
                int(user_id),
            ),
        ).fetchone()

    return row is not None


async def block_private_hard_spammer(
    event: Optional[Any],
    user_id: int,
) -> bool:
    if (
        int(user_id) == SELF_USER_ID
        or int(user_id) in SYSTEM_USER_IDS
    ):
        return False

    # Never platform-block a user who is registered as owner of an installed
    # ZIVO group. Their flood is still dropped locally by the mandatory shield.
    if user_owns_any_installed_group(
        user_id
    ):
        log.warning(
            "private hard-burst owner protected from platform block | user=%s",
            user_id,
        )
        return False

    if anti_spam_private_blocked(
        user_id
    ):
        return True

    target = await resolve_private_target(
        event,
        int(user_id),
    )

    if not isinstance(
        target,
        types.InputPeerUser,
    ):
        log.warning(
            "private hard-burst block target unresolved | user=%s",
            user_id,
        )
        return False

    try:
        await asyncio.wait_for(
            client(
                functions.contacts.BlockRequest(
                    id=target,
                )
            ),
            timeout=20,
        )

        record_anti_spam_private_block(
            user_id,
            reason="hard_burst",
        )

        log.warning(
            "mandatory anti-spam private user blocked | user=%s",
            user_id,
        )
        return True

    except Exception as exc:
        log.warning(
            "private hard-burst platform block failed | user=%s | %s: %s",
            user_id,
            type(exc).__name__,
            exc,
        )
        return False


def legacy_private_block_user_ids() -> List[int]:
    try:
        with db_connect() as con:
            rows = con.execute(
                "SELECT user_id FROM anti_spam_private_blocks ORDER BY blocked_at ASC"
            ).fetchall()
        return [int(row["user_id"]) for row in rows if safe_int(row["user_id"]) is not None]
    except Exception:
        return []


def clear_legacy_private_block_record(user_id: int) -> None:
    try:
        with db_connect() as con:
            con.execute(
                "DELETE FROM anti_spam_private_blocks WHERE user_id = ?",
                (int(user_id),),
            )
            con.commit()
    except Exception:
        pass


async def legacy_private_unblock_worker() -> None:
    request_cls = getattr(functions.contacts, "UnblockRequest", None)
    while True:
        await _yield_background_to_realtime(1.5)
        rows = legacy_private_block_user_ids()
        if not rows:
            await asyncio.sleep(600)
            continue

        for user_id in rows[:200]:
            if request_cls is None:
                clear_legacy_private_block_record(user_id)
                continue
            try:
                target = await resolve_private_target(None, int(user_id))
                if not isinstance(target, types.InputPeerUser):
                    target = types.InputPeerUser(int(user_id), 0)
                await asyncio.wait_for(
                    client(request_cls(id=target)),
                    timeout=20,
                )
                clear_legacy_private_block_record(user_id)
                log.info("legacy private platform block removed | user=%s", user_id)
            except Exception as exc:
                log.warning(
                    "legacy private unblock retry pending | user=%s | %s: %s",
                    user_id, type(exc).__name__, exc,
                )
            await asyncio.sleep(0.1)

        await asyncio.sleep(60)


def anti_spam_group_owner_id(
    group_id: int,
) -> int:
    installation = get_installation(
        group_id
    )

    if installation is None:
        return 0

    return int(
        safe_int(
            installation[
                "owner_user_id"
            ]
        )
        or 0
    )


async def ban_group_hard_spammer(
    event: Any,
    group: Any,
    group_id: int,
    user_id: int,
) -> bool:
    if int(user_id) == SELF_USER_ID or int(user_id) in SYSTEM_USER_IDS:
        return False
    if get_installation(group_id) is None:
        return False
    if anti_spam_group_owner_id(group_id) == int(user_id):
        log.warning(
            "group hard-burst owner protected from permanent ban | group=%s user=%s",
            group_id, user_id,
        )
        return False

    input_sender = getattr(event, "input_sender", None)
    target_hash = int(
        input_peer_access_hash(input_sender)
        or stats_access_hash(group_id, user_id)
        or 0
    )
    source = "flood"
    ok, error_text = await enforce_zivo_ban(
        group,
        group_id,
        user_id,
        target_hash,
        input_peer_username(input_sender),
        SELF_USER_ID,
        None,
        source=source,
    )
    if not ok:
        log.warning(
            "group hard-burst permanent ban failed | group=%s user=%s error=%s",
            group_id, user_id, error_text,
        )
        return False

    log.warning(
        "mandatory anti-spam permanent group ban applied | group=%s user=%s source=%s",
        group_id, user_id, source,
    )
    return True


async def maybe_apply_anti_spam_group_mute(
    event: Any,
    group: Any,
    group_id: int,
    user_id: int,
    warnings: int,
) -> bool:
    settings = effective_anti_spam_settings(
        group_id
    )

    if warnings < int(
        settings[
            "max_warnings"
        ]
    ):
        return False

    if get_installation(
        group_id
    ) is None:
        return False

    # The mandatory local shield has no role exemption, but native moderation
    # is kept away from ZIVO owner/admin/special/exempt accounts to avoid
    # destructive privilege conflicts. Their event processing is still cooled.
    if lock_user_is_exempt(
        group_id,
        user_id,
    ):
        return False

    state = manual_moderation_row(
        group_id,
        user_id,
    )

    if (
        state is not None
        and int(
            state[
                "banned"
            ]
            or 0
        )
        == 1
    ):
        return False

    input_sender = getattr(
        event,
        "input_sender",
        None,
    )
    target_hash = input_peer_access_hash(
        input_sender
    )

    if not target_hash:
        target_hash = stats_access_hash(
            group_id,
            user_id,
        )

    if not target_hash:
        return False

    mute_until = datetime.now(
        timezone.utc
    ) + timedelta(
        seconds=int(
            ANTI_SPAM_HARD_COOLDOWN
        )
    )

    ok, _error = await apply_manual_banned_rights(
        group,
        user_id,
        int(target_hash),
        mute_banned_rights(
            mute_until
        ),
    )

    if not ok:
        return False

    set_manual_mute_state(
        group_id,
        user_id,
        input_peer_username(
            input_sender
        ),
        int(target_hash),
        SELF_USER_ID,
        mute_until,
    )

    log.warning(
        "mandatory anti-spam native mute applied | group=%s user=%s seconds=%s warnings=%s",
        group_id,
        user_id,
        int(
            ANTI_SPAM_HARD_COOLDOWN
        ),
        warnings,
    )

    return True


def canonical_anti_spam_group_id(
    raw_group_id: Optional[int],
) -> Optional[int]:
    value = safe_int(
        raw_group_id
    )

    if value is None:
        return None

    if value <= -1000000000000:
        return (
            -int(value)
            - 1000000000000
        )

    return int(value)


def anti_spam_event_is_stale(
    event: Any,
    max_age_seconds: float = 15.0,
) -> bool:
    message = getattr(
        event,
        "message",
        None,
    ) or event

    value = getattr(
        message,
        "date",
        None,
    )

    if value is None:
        value = getattr(
            event,
            "date",
            None,
        )

    if value is None:
        return False

    try:
        if isinstance(
            value,
            datetime,
        ):
            dt = value

            if dt.tzinfo is None:
                dt = dt.replace(
                    tzinfo=timezone.utc
                )

            age = (
                datetime.now(
                    timezone.utc
                )
                - dt.astimezone(
                    timezone.utc
                )
            ).total_seconds()

        else:
            age = (
                time.time()
                - float(value)
            )

        return age > float(
            max_age_seconds
        )

    except Exception:
        return False


def flood_guard_cleanup_runtime(
    now: float,
) -> None:
    global _flood_guard_cleanup_last
    now = float(now)
    if now - _flood_guard_cleanup_last < 2.0:
        return
    _flood_guard_cleanup_last = now
    seen_cutoff = now - 120.0
    for key, stamp in list(_flood_guard_seen_messages.items()):
        if stamp < seen_cutoff:
            _flood_guard_seen_messages.pop(key, None)

    for key, until in list(_flood_guard_action_until.items()):
        if until <= now:
            _flood_guard_action_until.pop(key, None)

    for key, times in list(_flood_guard_event_times.items()):
        while times and now - times[0] > 60.0:
            times.popleft()
        if not times:
            _flood_guard_event_times.pop(key, None)

    for group_id, state in list(_flood_guard_last_sender.items()):
        if now - float(state[1]) > 60.0:
            _flood_guard_last_sender.pop(group_id, None)


async def purge_flood_spammer_messages(
    group: Any,
    group_id: int,
    user_id: int,
    input_sender: Optional[Any] = None,
    scan_limit: Optional[int] = None,
) -> Tuple[int, int, int, int]:
    requested_limit = int(scan_limit) if scan_limit is not None else 0
    live_limit = FLOOD_GUARD_LIVE_DELETE_MAX
    if requested_limit > 0:
        live_limit = min(live_limit, max(30, requested_limit))

    now = time.monotonic()
    matched_ids = [
        int(message_id)
        for (gid, uid, message_id), seen_at in list(_flood_guard_seen_messages.items())
        if int(gid) == int(group_id)
        and int(uid) == int(user_id)
        and now - float(seen_at) <= max(120.0, float(get_flood_guard_settings(group_id)["window_seconds"]) * 4.0)
    ]
    matched_ids = sorted(set(matched_ids))[-live_limit:]

    pending = _flood_guard_pending_delete_ids.get((int(group_id), int(user_id)))
    if pending:
        matched_ids = sorted(set(matched_ids).union(int(x) for x in pending))[-live_limit:]

    initial_matched = len(matched_ids)
    if not matched_ids:
        log.warning(
            "spam cleanup live-cache empty | group=%s user=%s",
            group_id, user_id,
        )
        return 0, 0, 0, 0

    deleted_total, failed_total = await delete_reliable_message_ids(group, matched_ids)
    if deleted_total:
        increment_deleted_message_counter(group_id, deleted_total)

    log.warning(
        "spam cleanup live-cache | group=%s user=%s matched=%s deleted=%s failed=%s cap=%s",
        group_id, user_id, initial_matched, deleted_total, failed_total, live_limit,
    )

    return initial_matched, initial_matched, deleted_total, failed_total


async def flood_guard_live_tail_delete_worker(
    action_key: Tuple[int, int],
) -> None:
    group_id, user_id = action_key
    quiet_rounds = 0
    deleted_total = 0
    failed_total = 0
    requested_total = 0

    try:
        while quiet_rounds < FLOOD_GUARD_TAIL_QUIET_ROUNDS:
            await asyncio.sleep(FLOOD_GUARD_TAIL_BATCH_DELAY)
            pending = _flood_guard_pending_delete_ids.get(action_key)
            ids = sorted(pending or [])
            if pending is not None:
                pending.clear()

            if not ids:
                quiet_rounds += 1
                continue

            quiet_rounds = 0
            requested_total += len(ids)
            group = _flood_guard_pending_delete_group.get(action_key)
            if group is None:
                failed_total += len(ids)
                continue

            deleted, failed = await delete_reliable_message_ids(group, ids)
            deleted_total += deleted
            failed_total += failed
            if deleted:
                increment_deleted_message_counter(group_id, deleted)

            log.warning(
                "spam live-tail batch | group=%s user=%s requested=%s deleted=%s failed=%s",
                group_id,
                user_id,
                len(ids),
                deleted,
                failed,
            )
    except asyncio.CancelledError:
        raise
    except Exception:
        log.exception(
            "spam live-tail worker failed | group=%s user=%s",
            group_id,
            user_id,
        )
    finally:
        # One last drain avoids losing ids queued during the final delete RPC.
        remaining = sorted(_flood_guard_pending_delete_ids.get(action_key) or [])
        if remaining:
            group = _flood_guard_pending_delete_group.get(action_key)
            if group is not None:
                try:
                    deleted, failed = await delete_reliable_message_ids(group, remaining)
                    requested_total += len(remaining)
                    deleted_total += deleted
                    failed_total += failed
                    if deleted:
                        increment_deleted_message_counter(group_id, deleted)
                except Exception:
                    failed_total += len(remaining)
            _flood_guard_pending_delete_ids.get(action_key, set()).clear()

        _flood_guard_pending_delete_tasks.pop(action_key, None)
        _flood_guard_pending_delete_ids.pop(action_key, None)
        _flood_guard_pending_delete_group.pop(action_key, None)
        log.warning(
            "spam live-tail DONE | group=%s user=%s requested=%s deleted=%s failed=%s",
            group_id,
            user_id,
            requested_total,
            deleted_total,
            failed_total,
        )


def queue_flood_guard_live_delete(
    group: Any,
    group_id: int,
    user_id: int,
    message_id: int,
) -> None:
    action_key = (int(group_id), int(user_id))
    pending = _flood_guard_pending_delete_ids.setdefault(action_key, set())
    pending.add(int(message_id))
    _flood_guard_pending_delete_group[action_key] = group

    task = _flood_guard_pending_delete_tasks.get(action_key)
    if task is None or task.done():
        _flood_guard_pending_delete_tasks[action_key] = asyncio.create_task(
            flood_guard_live_tail_delete_worker(action_key)
        )


def queue_flood_guard_cached_delete_ids(
    group: Any,
    group_id: int,
    user_id: int,
    message_ids: Iterable[int],
) -> int:
    action_key = (int(group_id), int(user_id))
    pending = _flood_guard_pending_delete_ids.setdefault(action_key, set())
    before = len(pending)
    for message_id in message_ids:
        parsed = safe_int(message_id)
        if parsed is not None and parsed > 0:
            pending.add(int(parsed))
    _flood_guard_pending_delete_group[action_key] = group
    task = _flood_guard_pending_delete_tasks.get(action_key)
    if pending and (task is None or task.done()):
        _flood_guard_pending_delete_tasks[action_key] = asyncio.create_task(
            flood_guard_live_tail_delete_worker(action_key),
            name=f"zivo-spam-tail-{group_id}-{user_id}",
        )
    return max(0, len(pending) - before)


async def flood_guard_history_cleanup_worker(
    action_key: Tuple[int, int],
    group: Any,
    scan_limit: int,
) -> None:
    group_id, user_id = action_key
    scanned = 0
    matched: List[int] = []
    try:
        await asyncio.sleep(0.8)
        cap = max(50, min(FLOOD_GUARD_HISTORY_SCAN_CAP, int(scan_limit or FLOOD_GUARD_HISTORY_SCAN_CAP)))
        async for message in client.iter_messages(group, limit=cap, wait_time=0):
            scanned += 1
            if safe_int(getattr(message, "sender_id", None)) == int(user_id):
                mid = safe_int(getattr(message, "id", None))
                if mid is not None and mid > 0:
                    matched.append(int(mid))
            if scanned % 100 == 0:
                await asyncio.sleep(0)
        matched = list(dict.fromkeys(matched))
        if not matched:
            log.info("spam history cleanup empty | group=%s user=%s scanned=%s", group_id, user_id, scanned)
            return
        deleted, failed = await delete_reliable_message_ids(group, matched)
        if deleted:
            increment_deleted_message_counter(group_id, deleted)
        level = log.warning if failed else log.info
        level(
            "spam history cleanup DONE | group=%s user=%s scanned=%s matched=%s deleted=%s failed=%s",
            group_id, user_id, scanned, len(matched), deleted, failed,
        )
    except asyncio.CancelledError:
        raise
    except Exception:
        log.exception("spam history cleanup failed | group=%s user=%s scanned=%s", group_id, user_id, scanned)
    finally:
        _flood_guard_history_cleanup_tasks.pop(action_key, None)


def schedule_flood_guard_history_cleanup(
    group: Any,
    group_id: int,
    user_id: int,
    scan_limit: int,
) -> bool:
    action_key = (int(group_id), int(user_id))
    current = _flood_guard_history_cleanup_tasks.get(action_key)
    if current is not None and not current.done():
        return False
    active = sum(1 for task in _flood_guard_history_cleanup_tasks.values() if not task.done())
    if active >= FLOOD_GUARD_HISTORY_TASK_MAX:
        log.info("spam history cleanup deferred by concurrency cap | group=%s user=%s active=%s", group_id, user_id, active)
        return False
    _flood_guard_history_cleanup_tasks[action_key] = asyncio.create_task(
        flood_guard_history_cleanup_worker(action_key, group, int(scan_limit or 0)),
        name=f"zivo-spam-history-{group_id}-{user_id}",
    )
    return True


async def consume_group_flood_guard_event(
    event: Any,
) -> bool:
    sender_id = safe_int(getattr(event, "sender_id", None))
    message_id = safe_int(getattr(event, "id", None))
    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))

    if (
        sender_id is None
        or message_id is None
        or group_id is None
        or sender_id == SELF_USER_ID
        or sender_id in SYSTEM_USER_IDS
        or anti_spam_event_is_stale(event)
    ):
        return False

    if get_installation(group_id) is None:
        return False

    settings = get_flood_guard_settings(group_id)
    if not settings["enabled"]:
        return False

    # Trusted roles are never auto-banned by this destructive layer.
    if lock_user_is_exempt(group_id, sender_id):
        _flood_guard_last_sender[group_id] = (sender_id, time.monotonic(), 0)
        return False

    now = time.monotonic()
    flood_guard_cleanup_runtime(now)

    seen_key = (group_id, sender_id, message_id)
    if seen_key in _flood_guard_seen_messages:
        return True
    _flood_guard_seen_messages[seen_key] = now

    action_key = (group_id, sender_id)
    if float(_flood_guard_action_until.get(action_key, 0.0) or 0.0) > now:
        # The spam action may have started on message 7/10 while dozens of
        # already-sent updates are still arriving. Previously these events were
        # only swallowed by the router, so the visible spam tail stayed in chat.
        # Queue every subsequent message for verified batched deletion.
        group_target = getattr(event, "input_chat", None)
        if group_target is None:
            try:
                group_target = await event.get_chat()
            except Exception:
                group_target = None
        if group_target is not None:
            queue_flood_guard_live_delete(
                group_target,
                group_id,
                sender_id,
                message_id,
            )
            log.debug(
                "spam live-tail queued | group=%s user=%s message=%s",
                group_id,
                sender_id,
                message_id,
            )
        return True

    window_seconds = float(settings["window_seconds"])
    times = _flood_guard_event_times.setdefault(action_key, deque())
    while times and now - times[0] > window_seconds:
        times.popleft()
    times.append(now)
    burst_count = len(times)

    previous = _flood_guard_last_sender.get(group_id)
    if (
        previous is not None
        and int(previous[0]) == sender_id
        and now - float(previous[1]) <= window_seconds
    ):
        consecutive_count = int(previous[2]) + 1
    else:
        consecutive_count = 1
    _flood_guard_last_sender[group_id] = (sender_id, now, consecutive_count)

    trigger_reason = ""
    if consecutive_count >= int(settings["consecutive_limit"]):
        trigger_reason = "consecutive"
    elif burst_count >= int(settings["burst_limit"]):
        trigger_reason = "rate"

    if not trigger_reason:
        return False

    # Prevent duplicate destructive jobs while queued updates are still arriving.
    _flood_guard_action_until[action_key] = now + 3600.0

    try:
        # Live moderation must not depend on an expensive/full entity resolve.
        # Soroush updates normally already carry an InputPeer target; use it first
        # and fall back to get_chat only when the update shape lacks one.
        fast_target_helper = globals().get("fast_event_group_target")
        group = fast_target_helper(event) if callable(fast_target_helper) else None
        if group is None:
            group = getattr(event, "input_chat", None)
        if group is None:
            group = await event.get_chat()
        actual_group_id = safe_int(getattr(group, "id", None)) or group_id

        # Re-check trusted state with the resolved/canonical group ID before moderation.
        if lock_user_is_exempt(actual_group_id, sender_id):
            _flood_guard_action_until.pop(action_key, None)
            return False

        banned = await ban_group_hard_spammer(
            event, group, actual_group_id, sender_id
        )

        now_seen = time.monotonic()
        live_ids = [
            int(mid)
            for (gid, uid, mid), seen_at in list(_flood_guard_seen_messages.items())
            if int(gid) == int(actual_group_id)
            and int(uid) == int(sender_id)
            and now_seen - float(seen_at) <= 120.0
        ]
        queue_cached = globals().get("queue_flood_guard_cached_delete_ids")
        schedule_history = globals().get("schedule_flood_guard_history_cleanup")
        if callable(queue_cached) and callable(schedule_history):
            queued_live = int(queue_cached(
                group, actual_group_id, sender_id, live_ids
            ) or 0)
            requested_scan = int(settings.get("cleanup_scan_limit", 0) or 0)
            history_scan = requested_scan if requested_scan > 0 else FLOOD_GUARD_HISTORY_SCAN_CAP
            history_scheduled = bool(schedule_history(
                group, actual_group_id, sender_id, history_scan
            ))
        else:
            # Regression-harness/legacy compatibility only. The production
            # module always has the background queue helpers above.
            legacy_purge = globals().get("purge_flood_spammer_messages")
            if callable(legacy_purge):
                _scanned, _matched, _deleted, _failed = await legacy_purge(
                    group, actual_group_id, sender_id, getattr(event, "input_sender", None),
                    scan_limit=int(settings.get("cleanup_scan_limit", 0) or 0),
                )
                queued_live = int(_deleted or 0)
            else:
                queued_live = 0
            history_scan = int(settings.get("cleanup_scan_limit", 0) or 0)
            history_scheduled = False

        try:
            await send_group_text(
                group,
                (
                    "🛡 ZIVO | SPAM GUARD\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    f"🚫 اسپم تشخیص داده شد: {'پیام های پشت سرهم' if trigger_reason == 'consecutive' else 'تعداد زیاد پیام در زمان کوتاه'}\n"
                    f"🔒 بن کاربر: {'انجام شد ✅' if banned else 'ناموفق/از قبل فعال ⚠️'}\n"
                    f"🧹 پاکسازی زنده در صف: {stats_num(queued_live)} پیام\n"
                    f"📚 پاکسازی سابقه: {'شروع شد ✅' if history_scheduled else 'در حال اجرا/صف پر'}\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "⚡ ZIVO | SPAM CONTROL"
                ),
            )
        except Exception:
            pass

        log.warning(
            "independent flood guard action | group=%s user=%s reason=%s "
            "burst=%s consecutive=%s banned=%s live_queued=%s history_scheduled=%s scan_cap=%s",
            actual_group_id, sender_id, trigger_reason, burst_count,
            consecutive_count, banned, queued_live, int(history_scheduled), history_scan,
        )

    except Exception:
        # Do not leave the user in a one-hour pseudo-block when the moderation
        # RPC never actually started/completed. Re-arm on the next live message.
        _flood_guard_action_until.pop(action_key, None)
        log.exception(
            "independent flood guard action failed | group=%s user=%s message=%s | retry_rearmed=1",
            group_id, sender_id, message_id,
        )
        return False

    return True


async def consume_group_anti_spam_event(
    event: Any,
) -> bool:
    sender_id = safe_int(
        getattr(
            event,
            "sender_id",
            None,
        )
    )
    message_id = safe_int(
        getattr(
            event,
            "id",
            None,
        )
    )
    group_id = canonical_anti_spam_group_id(
        getattr(
            event,
            "chat_id",
            None,
        )
    )

    if anti_spam_event_is_stale(
        event
    ):
        log.debug(
            "anti-spam stale group update ignored | group=%s user=%s message=%s",
            group_id,
            sender_id,
            message_id,
        )
        return False

    if (
        sender_id is None
        or message_id is None
        or group_id is None
        or sender_id == SELF_USER_ID
        or sender_id in SYSTEM_USER_IDS
    ):
        return False

    text = (
        getattr(
            event,
            "raw_text",
            None,
        )
        or ""
    )
    message = getattr(
        event,
        "message",
        None,
    ) or event

    result = anti_spam_preflight(
        "group",
        group_id,
        sender_id,
        message_id,
        text=text,
        message=message,
    )

    if result.get(
        "duplicate"
    ):
        log.debug(
            "anti-spam group duplicate suppressed | group=%s user=%s message=%s",
            group_id,
            sender_id,
            message_id,
        )
        return True

    if not result.get(
        "blocked"
    ):
        return False

    if result.get(
        "hard_burst"
    ):
        if not result.get(
            "hard_action"
        ):
            log.debug(
                "anti-spam hard-burst event dropped locally | group=%s user=%s message=%s",
                group_id,
                sender_id,
                message_id,
            )
            return True

        try:
            group = await event.get_chat()
            actual_group_id = safe_int(
                getattr(
                    group,
                    "id",
                    None,
                )
            )

            if actual_group_id is not None:
                log.warning(
                    "mandatory core anti-spam hard burst locally blocked | group=%s user=%s count=%s",
                    actual_group_id,
                    sender_id,
                    result.get("hard_burst_count"),
                )

        except Exception:
            log.exception(
                "hard-burst group action failed | group=%s user=%s message=%s",
                group_id,
                sender_id,
                message_id,
            )

        return True

    # Emergency preflight has no soft-block state in zivo55.
    return False


def consume_private_anti_spam_preflight(
    sender_id: int,
    message_id: int,
    text: str,
) -> Dict[str, Any]:
    result = anti_spam_preflight(
        "private",
        int(sender_id),
        int(sender_id),
        int(message_id),
        text=text,
        message=None,
    )

    if result.get(
        "blocked"
    ):
        log.warning(
            "mandatory anti-spam blocked private event | user=%s message=%s "
            "reason=%s warnings=%s cooldown=%.1fs",
            sender_id,
            message_id,
            result.get(
                "reason"
            ),
            result.get(
                "warnings"
            ),
            float(
                result.get(
                    "cooldown"
                )
                or 0.0
            ),
        )

    return result


def canonical_content_text(
    value: str,
) -> str:
    return normalize_group_command(
        value or ""
    )


def exact_content_descriptor(
    message: Any,
) -> Optional[Dict[str, Any]]:
    if message is None:
        return None

    category = robust_message_category(
        message
    )

    # Media first. If a photo/video has a caption, filtering the replied media
    # means the media itself, not every message that happens to share the caption.
    media_obj = None

    if category == "photo":
        media_obj = safe_message_property(
            message,
            "photo",
        )

    elif category in {
        "sticker",
        "gif",
        "voice",
        "video_note",
        "audio",
        "video",
        "file",
    }:
        # All of these are Document-backed in SPlusthon.
        media_obj = (
            safe_message_property(
                message,
                category,
            )
            if category
            not in {
                "file",
                "video_note",
            }
            else None
        )

        if media_obj is None:
            if category == "video_note":
                media_obj = safe_message_property(
                    message,
                    "video_note",
                )
            else:
                media_obj = safe_message_property(
                    message,
                    "document",
                )

    if media_obj is not None:
        stable_id = safe_int(
            getattr(
                media_obj,
                "id",
                None,
            )
        )

        if stable_id:
            fingerprint = (
                f"media:{category}:{stable_id}"
            )

            return {
                "fingerprint": fingerprint,
                "content_type": category,
                "preview": exact_content_preview(
                    category,
                    message,
                ),
            }

    if category == "poll":
        poll_media = safe_message_property(
            message,
            "poll",
        )
        poll_obj = getattr(
            poll_media,
            "poll",
            None,
        )

        poll_id = safe_int(
            getattr(
                poll_obj,
                "id",
                None,
            )
        )

        if poll_id:
            return {
                "fingerprint": f"poll:{poll_id}",
                "content_type": "poll",
                "preview": "نظرسنجی",
            }

    raw_text = (
        safe_message_property(
            message,
            "raw_text",
        )
        or safe_message_property(
            message,
            "message",
        )
        or ""
    )

    canonical = canonical_content_text(
        raw_text
    )

    if canonical:
        digest = hashlib.sha256(
            canonical.encode(
                "utf-8"
            )
        ).hexdigest()

        preview = canonical
        if len(preview) > 80:
            preview = (
                preview[:77]
                + "..."
            )

        return {
            "fingerprint": f"text:{digest}",
            "content_type": "text",
            "preview": preview,
        }

    return None


def exact_content_preview(
    category: str,
    message: Any,
) -> str:
    labels = {
        "sticker": "استیکر",
        "gif": "گیف",
        "voice": "ویس",
        "video_note": "ویدیوی دایره‌ای",
        "audio": "آهنگ",
        "video": "ویدیو",
        "photo": "عکس",
        "file": "فایل",
        "poll": "نظرسنجی",
    }

    label = labels.get(
        category,
        category,
    )

    file_obj = safe_message_property(
        message,
        "file",
    )

    if file_obj is not None:
        try:
            name = getattr(
                file_obj,
                "name",
                None,
            )
        except Exception:
            name = None

        if name:
            label = (
                f"{label}: {name}"
            )

    return label[:100]


def add_exact_content_filter(
    group_id: int,
    descriptor: Dict[str, Any],
    source_message_id: int,
    source_user_id: int,
    actor_id: int,
) -> bool:
    with db_connect() as con:
        cur = con.execute(
            """
            INSERT OR IGNORE INTO exact_content_filters (
                group_id,
                fingerprint,
                content_type,
                preview,
                source_message_id,
                source_user_id,
                created_by,
                created_at
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                int(group_id),
                descriptor[
                    "fingerprint"
                ],
                descriptor[
                    "content_type"
                ],
                descriptor.get(
                    "preview",
                    "",
                ),
                int(
                    source_message_id
                    or 0
                ),
                int(
                    source_user_id
                    or 0
                ),
                int(actor_id),
                datetime.now(
                    timezone.utc
                ).isoformat(),
            ),
        )
        con.commit()

    _exact_content_filter_count_hot_cache.pop(int(group_id), None)
    return cur.rowcount > 0


def remove_exact_content_filter(
    group_id: int,
    fingerprint: str,
) -> bool:
    with db_connect() as con:
        cur = con.execute(
            """
            DELETE FROM exact_content_filters
            WHERE group_id = ?
              AND fingerprint = ?
            """,
            (
                int(group_id),
                fingerprint,
            ),
        )
        con.commit()

    _exact_content_filter_count_hot_cache.pop(int(group_id), None)
    return cur.rowcount > 0


def exact_content_media_id_from_fingerprint(
    fingerprint: str,
) -> int:
    match = re.fullmatch(
        r"media:[^:]+:(\d+)",
        fingerprint or "",
    )

    if match is None:
        return 0

    return int(
        safe_int(
            match.group(1)
        )
        or 0
    )


def exact_content_fingerprints_match(
    left: str,
    right: str,
) -> bool:
    if left == right:
        return True

    left_media_id = exact_content_media_id_from_fingerprint(
        left
    )
    right_media_id = exact_content_media_id_from_fingerprint(
        right
    )

    return bool(
        left_media_id
        and right_media_id
        and left_media_id == right_media_id
    )


def exact_content_filter_row(
    group_id: int,
    fingerprint: str,
) -> Optional[sqlite3.Row]:
    media_id = exact_content_media_id_from_fingerprint(
        fingerprint
    )

    with db_connect() as con:
        row = con.execute(
            """
            SELECT *
            FROM exact_content_filters
            WHERE group_id = ?
              AND fingerprint = ?
            """,
            (
                int(group_id),
                fingerprint,
            ),
        ).fetchone()

        if row is not None or not media_id:
            return row

        return con.execute(
            """
            SELECT *
            FROM exact_content_filters
            WHERE group_id = ?
              AND fingerprint LIKE ?
            LIMIT 1
            """,
            (
                int(group_id),
                f"media:%:{media_id}",
            ),
        ).fetchone()


def exact_content_filter_count(
    group_id: int,
) -> int:
    gid = int(group_id)
    now = time.monotonic()
    cached = _exact_content_filter_count_hot_cache.get(gid)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return int(cached[1])
    with db_connect() as con:
        row = con.execute(
            """
            SELECT COUNT(*) AS c
            FROM exact_content_filters
            WHERE group_id = ?
            """,
            (gid,),
        ).fetchone()
    value = int(row["c"] or 0) if row else 0
    _exact_content_filter_count_hot_cache[gid] = (now, value)
    return value


def normalize_filtered_phrase(
    value: str,
) -> str:
    spaced, _compact = normalize_filter_abuse_text(value or "")
    return spaced


def filtered_phrase_valid(
    value: str,
) -> Tuple[bool, str]:
    normalized = normalize_filtered_phrase(
        value
    )

    if not normalized:
        return False, "empty"

    if len(
        normalized
    ) > 100:
        return False, "too_long"

    return True, normalized


def invalidate_filtered_phrase_cache(
    group_id: int,
) -> None:
    _filtered_phrase_cache.pop(
        int(group_id),
        None,
    )


def list_filtered_phrases_cached(
    group_id: int,
) -> Tuple[Tuple[str, str, str], ...]:
    group_id = int(
        group_id
    )
    now = time.monotonic()
    cached = _filtered_phrase_cache.get(
        group_id
    )

    if (
        isinstance(cached, tuple)
        and len(cached) >= 2
        and isinstance(cached[0], (int, float))
        and now - float(cached[0]) < FILTERED_PHRASE_CACHE_TTL
    ):
        raw_rows = cached[1] if isinstance(cached[1], (tuple, list)) else ()
        upgraded_rows: List[Tuple[str, str, str]] = []
        for item in raw_rows:
            # The old 60.93/60.94 startup cache contained (norm, display).
            # Never unpack its shape directly on the group router: malformed
            # cache data must self-heal, not make every group look offline.
            if not isinstance(item, (tuple, list)) or len(item) < 2:
                continue
            phrase_norm = str(item[0])
            phrase_display = str(item[1])
            phrase_compact = (
                str(item[2])
                if len(item) >= 3 and item[2] is not None
                else normalize_filter_abuse_text(phrase_norm)[1]
            )
            upgraded_rows.append((phrase_norm, phrase_display, phrase_compact))
        upgraded = tuple(upgraded_rows)
        if upgraded or not raw_rows:
            _filtered_phrase_cache[group_id] = (now, upgraded)
            return upgraded
        # The cache itself is malformed rather than merely legacy. Drop it and
        # rebuild from SQLite below so filtering stays active for this group.
        _filtered_phrase_cache.pop(group_id, None)

    with db_connect() as con:
        rows = con.execute(
            """
            SELECT phrase_norm, phrase_display
            FROM filtered_phrases
            WHERE group_id = ?
            ORDER BY LENGTH(phrase_norm) DESC, phrase_norm ASC
            """,
            (
                group_id,
            ),
        ).fetchall()

    result = tuple(
        (
            row["phrase_norm"],
            row["phrase_display"],
            normalize_filter_abuse_text(row["phrase_norm"])[1],
        )
        for row in rows
    )

    _filtered_phrase_cache[
        group_id
    ] = (
        now,
        result,
    )

    return result


def filtered_phrase_count(
    group_id: int,
) -> int:
    with db_connect() as con:
        row = con.execute(
            """
            SELECT COUNT(*) AS c
            FROM filtered_phrases
            WHERE group_id = ?
            """,
            (
                int(group_id),
            ),
        ).fetchone()

    return int(
        row["c"] or 0
    ) if row else 0


def add_filtered_phrase(
    group_id: int,
    phrase: str,
    actor_id: int,
) -> Tuple[bool, str]:
    valid, normalized_or_reason = filtered_phrase_valid(
        phrase
    )

    if not valid:
        raise ValueError(
            normalized_or_reason
        )

    normalized = normalized_or_reason
    display = normalize_group_command(
        phrase
    )

    with db_connect() as con:
        cur = con.execute(
            """
            INSERT OR IGNORE INTO filtered_phrases (
                group_id,
                phrase_norm,
                phrase_display,
                created_by,
                created_at
            ) VALUES (?, ?, ?, ?, ?)
            """,
            (
                int(group_id),
                normalized,
                display,
                int(actor_id),
                datetime.now(
                    timezone.utc
                ).isoformat(),
            ),
        )
        con.commit()

    invalidate_filtered_phrase_cache(
        group_id
    )

    return (
        cur.rowcount > 0,
        display,
    )


def remove_filtered_phrase(
    group_id: int,
    phrase: str,
) -> Tuple[bool, str]:
    valid, normalized_or_reason = filtered_phrase_valid(
        phrase
    )

    if not valid:
        raise ValueError(
            normalized_or_reason
        )

    normalized = normalized_or_reason
    display = normalize_group_command(
        phrase
    )

    with db_connect() as con:
        cur = con.execute(
            """
            DELETE FROM filtered_phrases
            WHERE group_id = ?
              AND phrase_norm = ?
            """,
            (
                int(group_id),
                normalized,
            ),
        )
        con.commit()

    invalidate_filtered_phrase_cache(
        group_id
    )

    return (
        cur.rowcount > 0,
        display,
    )


def reset_filtered_phrases(
    group_id: int,
) -> int:
    with db_connect() as con:
        cur = con.execute(
            """
            DELETE FROM filtered_phrases
            WHERE group_id = ?
            """,
            (
                int(group_id),
            ),
        )
        con.commit()

    invalidate_filtered_phrase_cache(
        group_id
    )

    return int(
        cur.rowcount or 0
    )


def filtered_phrase_word_char(
    char: str,
) -> bool:
    return bool(
        char
        and (
            char.isalnum()
            or char == "_"
        )
    )


def phrase_occurs_in_normalized_text(
    text: str,
    phrase: str,
) -> bool:
    if (
        not text
        or not phrase
    ):
        return False

    start = 0
    need_left_boundary = filtered_phrase_word_char(
        phrase[0]
    )
    need_right_boundary = filtered_phrase_word_char(
        phrase[-1]
    )

    while True:
        pos = text.find(
            phrase,
            start,
        )

        if pos < 0:
            return False

        end = pos + len(
            phrase
        )

        left_ok = (
            not need_left_boundary
            or pos == 0
            or not filtered_phrase_word_char(
                text[
                    pos - 1
                ]
            )
        )
        right_ok = (
            not need_right_boundary
            or end >= len(
                text
            )
            or not filtered_phrase_word_char(
                text[
                    end
                ]
            )
        )

        if (
            left_ok
            and right_ok
        ):
            return True

        start = pos + 1


def match_filtered_phrase_normalized(
    group_id: int,
    normalized_text: str,
    compact_text: str,
) -> Optional[str]:
    if not normalized_text and not compact_text:
        return None

    for cached_phrase in list_filtered_phrases_cached(group_id):
        # Final defensive boundary: legacy RAM cache data must never propagate
        # a ValueError through the group router, even during an in-flight reload.
        if not isinstance(cached_phrase, (tuple, list)) or len(cached_phrase) < 2:
            continue
        phrase_norm = str(cached_phrase[0])
        phrase_display = str(cached_phrase[1])
        phrase_compact = (
            str(cached_phrase[2])
            if len(cached_phrase) >= 3 and cached_phrase[2] is not None
            else ""
        )
        # Primary match is boundary-aware, so a short manager phrase cannot hit
        # merely because its letters appear inside an unrelated larger word.
        if phrase_occurs_in_normalized_text(normalized_text, phrase_norm):
            return phrase_display

        compact_len = len(phrase_compact)
        if compact_len <= 0:
            continue

        # Very short filters are intrinsically ambiguous. For 1-2 characters
        # require an exact whole-message match. For 3-5 characters use only the
        # boundary-aware path above. Compact/evasion matching is reserved for
        # 6+ character phrases, where separator tricks are meaningful and the
        # false-positive surface is much smaller.
        if compact_len <= 2:
            if compact_text == phrase_compact:
                return phrase_display
            continue
        if compact_len < 6:
            continue
        if phrase_compact in compact_text:
            return phrase_display
    return None


def match_filtered_phrase(
    group_id: int,
    text: str,
) -> Optional[str]:
    normalized_text, compact_text = normalize_filter_abuse_text(text)
    return match_filtered_phrase_normalized(group_id, normalized_text, compact_text)


def match_filtered_guard_text(
    group_id: int,
    text: str,
) -> Optional[str]:
    """Match the conservative built-in family and manager-added phrases once."""
    normalized_text, compact_text = normalize_filter_abuse_text(text)
    if not normalized_text and not compact_text:
        return None
    if lock_text_matches_builtin_filter_normalized(compact_text):
        return "بیوچک داخلی"
    return match_filtered_phrase_normalized(group_id, normalized_text, compact_text)


def parse_word_filter_command(
    text: str,
) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(
        text
    )

    # These exact commands belong to the separate exact-content filter.
    if text in {
        "فیلتر محتوا",
        "حذف فیلتر محتوا",
    }:
        return None

    if text in {
        "ریست کلمات فیلترشده",
        "ریست کلمات فیلتر شده",
    }:
        return {
            "action": "reset_word_filters",
        }

    remove_prefixes = (
        "حذف فیلتر کلمه ",
        "حذف فیلتر ",
    )

    for prefix in remove_prefixes:
        if text.startswith(
            prefix
        ):
            phrase = text[
                len(prefix):
            ].strip()

            valid, reason = filtered_phrase_valid(
                phrase
            )

            if not valid:
                return {
                    "action": "invalid_word_filter",
                    "reason": reason,
                }

            return {
                "action": "remove_word_filter",
                "phrase": phrase,
            }

    add_prefixes = (
        "فیلتر کلمه ",
        "فیلتر ",
    )

    for prefix in add_prefixes:
        if text.startswith(
            prefix
        ):
            phrase = text[
                len(prefix):
            ].strip()

            valid, reason = filtered_phrase_valid(
                phrase
            )

            if not valid:
                return {
                    "action": "invalid_word_filter",
                    "reason": reason,
                }

            return {
                "action": "add_word_filter",
                "phrase": phrase,
            }

    if text in {
        "فیلتر",
        "فیلتر کلمه",
        "حذف فیلتر",
        "حذف فیلتر کلمه",
    }:
        return {
            "action": "invalid_word_filter",
            "reason": "empty",
        }

    return None


def word_filter_actor_check(
    group_id: int,
    actor_id: int,
) -> Tuple[bool, str]:
    role = base_bot_role(
        group_id,
        actor_id,
    )

    if role not in {
        "مالک",
        "ادمین",
    }:
        return (
            False,
            "⛔ فیلتر کلمه فقط برای مالک و ادمین‌های زیوو فعاله.",
        )

    return True, role


async def purge_word_filter_history(
    group: Any,
    group_id: int,
    phrase: str,
    *,
    exclude_message_ids: Optional[set[int]] = None,
) -> Tuple[int, int, int, List[int]]:
    """Scan only the newest 100 messages and remove live phrase matches."""
    excluded = {int(x) for x in (exclude_message_ids or set())}
    valid, normalized_or_reason = filtered_phrase_valid(phrase)
    if not valid:
        return 0, 0, 0, []
    phrase_norm = normalized_or_reason
    try:
        history = await fetch_cleanup_history_page(group, offset_id=0, limit=100)
    except Exception as exc:
        log.warning(
            "word filter history fetch failed | group=%s phrase=%r | %s: %s",
            group_id, phrase[:80], type(exc).__name__, exc,
        )
        return 0, 0, 0, []

    scanned = 0
    matched_ids: List[int] = []
    pinned_ids: List[int] = []
    for message in history[:100]:
        message_id = safe_int(getattr(message, "id", None))
        if message_id is None:
            continue
        scanned += 1
        if int(message_id) in excluded:
            continue
        text = str(getattr(message, "raw_text", None) or getattr(message, "message", None) or "")
        normalized_text = normalize_filtered_phrase(text)
        if not phrase_occurs_in_normalized_text(normalized_text, phrase_norm):
            continue
        if message_is_pinned(message):
            pinned_ids.append(int(message_id))
        else:
            matched_ids.append(int(message_id))

    deleted_total, failed_total = await delete_filter_message_ids_verified(group, matched_ids)
    if deleted_total:
        increment_deleted_message_counter(group_id, deleted_total)
    return scanned, deleted_total, failed_total, list(dict.fromkeys(pinned_ids))


async def command_word_filter(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(
        getattr(
            event,
            "sender_id",
            None,
        )
    )

    if actor_id is None:
        return

    allowed, actor_role = word_filter_actor_check(
        group_id,
        actor_id,
    )

    if not allowed:
        await send_group_text(
            group,
            actor_role,
        )
        return

    action = parsed.get(
        "action"
    )

    if action == "invalid_word_filter":
        reason = parsed.get(
            "reason"
        )

        if reason == "too_long":
            message = "⚠️ کلمه یا عبارت فیلترشده نمی‌تونه بیشتر از 100 نویسه باشه."
        else:
            message = "⚠️ بعد از دستور فیلتر، کلمه یا عبارت موردنظر رو بنویس."

        await send_group_text(
            group,
            message,
        )
        return

    if action == "reset_word_filters":
        removed = reset_filtered_phrases(
            group_id
        )

        await send_group_text(
            group,
            (
                "🚫 ZIVO | WORD FILTER\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎖 اجراکننده: {actor_role}\n"
                f"🧹 فیلترهای پاک‌شده: {stats_num(removed)}\n"
                "✅ فهرست کلمات و عبارت‌های ممنوع این گروه ریست شد.\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | TEXT GUARD"
            ),
        )
        return

    phrase = parsed[
        "phrase"
    ]

    if action == "remove_word_filter":
        removed, display = remove_filtered_phrase(
            group_id,
            phrase,
        )

        await send_group_text(
            group,
            (
                "🚫 ZIVO | WORD FILTER\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎖 اجراکننده: {actor_role}\n"
                f"📝 عبارت: {display}\n"
                f"{'✅ از فهرست ممنوع حذف شد.' if removed else 'ℹ️ این عبارت داخل فهرست ممنوع نبود.'}\n"
                f"📚 تعداد فعلی: {stats_num(filtered_phrase_count(group_id))}\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | TEXT GUARD"
            ),
        )
        return

    if action == "add_word_filter":
        created, display = add_filtered_phrase(
            group_id,
            phrase,
            actor_id,
        )
        # A manager who says «فیلتر X» expects X to be blocked immediately.
        # Historically the phrase was stored but silently inert until a second
        # unrelated command enabled the filtered-message lock. Make the feature
        # self-contained while still allowing an explicit later lock-disable.
        lock_row_before = group_lock_row(group_id, "پیام‌های فیلترشده")
        if lock_row_before is None or not int(lock_row_before["enabled"] or 0):
            set_group_lock_enabled(group_id, "پیام‌های فیلترشده", True, actor_id)
        command_message_id = safe_int(getattr(event, "id", None))
        scanned, deleted, failed, pinned_ids = await purge_word_filter_history(
            group,
            group_id,
            phrase,
            exclude_message_ids={int(command_message_id)} if command_message_id is not None else set(),
        )
        pinned_count = save_cleanup_pin_confirmation(
            group_id, actor_id, pinned_ids, "word_filter_cleanup"
        )
        lock_row = group_lock_row(
            group_id,
            "پیام‌های فیلترشده",
        )
        lock_enabled = bool(
            lock_row is not None
            and int(
                lock_row[
                    "enabled"
                ]
                or 0
            )
        )

        await send_group_text(
            group,
            (
                "🚫 ZIVO | WORD FILTER\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎖 اجراکننده: {actor_role}\n"
                f"📝 عبارت: {display}\n"
                f"🧬 وضعیت: {'ثبت شد' if created else 'از قبل ثبت بود'}\n"
                f"📚 تعداد فعلی: {stats_num(filtered_phrase_count(group_id))}\n"
                f"🔎 پیام‌های بررسی‌شده: {stats_num(scanned)}\n"
                f"🧹 نمونه‌های پاک‌شده: {stats_num(deleted)}\n"
                f"⚠️ حذف‌نشده: {stats_num(failed)}\n"
                f"📌 پین‌های محافظت‌شده: {stats_num(pinned_count)}\n"
                f"🔐 قفل پیام‌های فیلترشده: {'روشن' if lock_enabled else 'خاموش'}\n"
                f"{'✅ از این لحظه ارسال این عبارت توسط کاربران کنترل می‌شود.' if lock_enabled else '⚠️ برای اجرای فیلتر، قفل پیام‌های فیلترشده را روشن کن.'}\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | TEXT GUARD"
            ),
        )
        return


def parse_exact_content_filter_command(
    text: str,
) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(
        text
    )

    if text == "فیلتر محتوا":
        return {
            "action": "add_exact_content_filter",
        }

    if text == "حذف فیلتر محتوا":
        return {
            "action": "remove_exact_content_filter",
        }

    return None


def exact_content_filter_actor_check(
    group_id: int,
    actor_id: int,
) -> Tuple[bool, str]:
    role = base_bot_role(
        group_id,
        actor_id,
    )

    if role not in {
        "مالک",
        "ادمین",
        "ویژه",
    }:
        return (
            False,
            "⛔ فیلتر محتوا فقط برای مالک، ادمین و ویژه زیوو فعاله.",
        )

    return True, role


async def replied_message_for_exact_filter(
    event: Any,
) -> Optional[Any]:
    if not bool(
        getattr(
            event,
            "is_reply",
            False,
        )
    ):
        return None

    try:
        return await event.get_reply_message()
    except Exception:
        return None



async def _filter_message_exists_strict(group: Any, message_id: int, timeout: float = 12.0) -> Optional[bool]:
    """Return True/False only when a single-id read gives a trustworthy answer."""
    try:
        result = await asyncio.wait_for(
            client.get_messages(group, ids=int(message_id)),
            timeout=max(0.8, float(timeout)),
        )
    except Exception as exc:
        log.warning(
            "filter delete verify single failed | group=%s message=%s | %s: %s",
            getattr(group, "id", "?"), message_id, type(exc).__name__, exc,
        )
        return None

    items = result if isinstance(result, (list, tuple)) else [result]
    real = [
        item for item in items
        if item is not None and type(item).__name__ != "MessageEmpty"
    ]
    if not real:
        return False
    for item in real:
        mid = safe_int(getattr(item, "id", None))
        if mid is not None and int(mid) == int(message_id):
            return True
    # A single-id request that returned only another object is ambiguous.
    return None


async def delete_filter_message_ids_verified(
    group: Any,
    message_ids: List[int],
) -> Tuple[int, int]:
    """Delete known-live filter matches and verify every id individually.

    Filter commands scan at most 100 recent messages, so bounded single-id
    verification is acceptable and prevents false "deleted" counts when a
    batched SPlusthon get_messages response is incomplete.
    """
    remaining = list(dict.fromkeys(int(x) for x in message_ids))
    if not remaining:
        return 0, 0

    verified_deleted: set[int] = set()
    verify_sem = asyncio.Semaphore(6)

    async def probe(mid: int) -> Tuple[int, Optional[bool]]:
        async with verify_sem:
            return mid, await _filter_message_exists_strict(group, mid)

    for attempt in range(1, 4):
        if not remaining:
            break
        # Keep delete RPC batches small to isolate partial server failures.
        for offset in range(0, len(remaining), FLOOD_GUARD_DELETE_BATCH_SIZE):
            batch = remaining[offset:offset + FLOOD_GUARD_DELETE_BATCH_SIZE]
            try:
                await governed_delete_messages(
                    group,
                    batch,
                    timeout=35,
                    lane="exact-filter",
                )
            except Exception as exc:
                log.warning(
                    "filter delete rpc failed | group=%s attempt=%s size=%s | %s: %s",
                    getattr(group, "id", "?"), attempt, len(batch), type(exc).__name__, exc,
                )
                if cleanup_error_is_permission(exc):
                    return len(verified_deleted), len(remaining)
        await asyncio.sleep(0.12)

        probe_rows = await asyncio.gather(*(probe(mid) for mid in remaining))
        still_live: List[int] = []
        unknown: List[int] = []
        for mid, exists in probe_rows:
            if exists is False:
                verified_deleted.add(int(mid))
            elif exists is True:
                still_live.append(int(mid))
            else:
                unknown.append(int(mid))

        log.info(
            "filter delete verified | group=%s attempt=%s verified=%s live=%s unknown=%s",
            getattr(group, "id", "?"), attempt, len(verified_deleted), len(still_live), len(unknown),
        )

        # Never report unknown verification as deleted. Retry it, then fail safe.
        remaining = list(dict.fromkeys(still_live + unknown))
        if remaining and attempt < 3:
            await asyncio.sleep(0.15 * attempt)

    return len(verified_deleted), len(remaining)


async def delete_reliable_message_ids(
    group: Any,
    message_ids: List[int],
) -> Tuple[int, int]:
    unique_ids = list(
        dict.fromkeys(
            int(message_id)
            for message_id in message_ids
        )
    )
    deleted_total = 0
    failed_total = 0

    for offset in range(
        0,
        len(unique_ids),
        FLOOD_GUARD_DELETE_BATCH_SIZE,
    ):
        batch = unique_ids[
            offset:offset + FLOOD_GUARD_DELETE_BATCH_SIZE
        ]

        deleted, failed = await delete_full_cleanup_batch(
            group,
            batch,
            max_attempts=3,
        )

        if failed and len(batch) > 1:
            deleted = 0
            failed = 0

            for message_id in batch:
                one_deleted, one_failed = await delete_full_cleanup_batch(
                    group,
                    [message_id],
                    max_attempts=2,
                )
                deleted += one_deleted
                failed += one_failed

        deleted_total += deleted
        failed_total += failed

        await asyncio.sleep(
            0.05
        )

    return deleted_total, failed_total


async def purge_exact_content_history(
    group: Any,
    group_id: int,
    fingerprint: str,
    *,
    source_message_id: int = 0,
    exclude_message_ids: Optional[set[int]] = None,
) -> Tuple[int, int, int, List[int]]:
    """Delete matching exact content from a deterministic newest-100 snapshot.

    96.42 deliberately uses one history snapshot instead of paginating a tiny
    bounded window. This guarantees that the replied source message is included
    whenever it is within the newest 100 reachable messages, and prevents live
    pagination drift while messages are arriving.
    """
    excluded = {int(x) for x in (exclude_message_ids or set())}
    scan_limit = int(EXACT_CONTENT_PURGE_SCAN_LIMIT)

    try:
        history = await fetch_cleanup_history_page(
            group,
            offset_id=0,
            limit=scan_limit,
        )
    except Exception as exc:
        log.warning(
            "exact content newest100 fetch failed | group=%s | %s: %s",
            group_id, type(exc).__name__, exc,
        )
        return 0, 0, 0, []

    snapshot = list(history or [])[:scan_limit]
    scanned = 0
    matched_ids: List[int] = []
    pinned_ids: List[int] = []
    snapshot_ids: set[int] = set()

    for message in snapshot:
        message_id = safe_int(getattr(message, "id", None))
        if message_id is None:
            continue
        mid = int(message_id)
        snapshot_ids.add(mid)
        scanned += 1
        if mid in excluded:
            continue

        descriptor = exact_content_descriptor(message)
        matched = bool(
            descriptor is not None
            and exact_content_fingerprints_match(descriptor["fingerprint"], fingerprint)
        )

        # The message explicitly replied to by the manager is authoritative for
        # this command, but only while it is still inside the newest-100 snapshot.
        if source_message_id and mid == int(source_message_id):
            matched = True

        if not matched:
            continue
        if message_is_pinned(message):
            pinned_ids.append(mid)
        else:
            matched_ids.append(mid)

    # Defensive visibility in logs: if the replied source is older than the
    # bounded window, leave it untouched rather than silently scanning deeper.
    if source_message_id and int(source_message_id) not in snapshot_ids:
        log.info(
            "exact content source outside newest100 | group=%s source=%s scanned=%s",
            group_id, int(source_message_id), scanned,
        )

    matched_ids = list(dict.fromkeys(matched_ids))
    deleted_total, failed_total = await delete_filter_message_ids_verified(group, matched_ids)

    if deleted_total:
        increment_deleted_message_counter(group_id, deleted_total)

    log.info(
        "exact content newest100 purge | group=%s scanned=%s matched=%s deleted=%s failed=%s source=%s",
        group_id, scanned, len(matched_ids), deleted_total, failed_total, int(source_message_id or 0),
    )
    return scanned, deleted_total, failed_total, list(dict.fromkeys(pinned_ids))


async def command_exact_content_filter(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(
        getattr(
            event,
            "sender_id",
            None,
        )
    )
    command_message_id = safe_int(
        getattr(
            event,
            "id",
            None,
        )
    )

    if (
        actor_id is None
        or command_message_id is None
    ):
        return

    allowed, actor_role = exact_content_filter_actor_check(
        group_id,
        actor_id,
    )

    if not allowed:
        await send_group_text(
            group,
            actor_role,
        )
        return

    reply = await replied_message_for_exact_filter(
        event
    )

    if reply is None:
        await send_group_text(
            group,
            "⚠️ روی متنی یا رسانه‌ای که می‌خوای فیلتر بشه ریپلای کن.",
        )
        return

    descriptor = exact_content_descriptor(
        reply
    )

    if descriptor is None:
        await send_group_text(
            group,
            "⚠️ این نوع محتوا برای فیلتر دقیق قابل شناسایی نیست.",
        )
        return

    action = parsed[
        "action"
    ]

    if action == "remove_exact_content_filter":
        removed = remove_exact_content_filter(
            group_id,
            descriptor[
                "fingerprint"
            ],
        )

        await send_group_text(
            group,
            (
                "🧿 ZIVO | CONTENT FILTER\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎖 اجراکننده: {actor_role}\n"
                f"🔎 محتوا: {descriptor['preview']}\n"
                f"{'✅ فیلتر این محتوا برداشته شد.' if removed else 'ℹ️ این محتوا از قبل فیلتر نبود.'}\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | CONTENT GUARD"
            ),
        )
        return

    active_command_id = group_cleanup_command_id(
        group_id
    )

    if (
        active_command_id is not None
        and active_command_id
        != int(
            command_message_id
        )
    ):
        return

    if active_command_id is None:
        _group_cleanup_active[
            int(group_id)
        ] = int(
            command_message_id
        )

    source_user_id = safe_int(
        getattr(
            reply,
            "sender_id",
            None,
        )
    ) or 0
    source_message_id = safe_int(
        getattr(
            reply,
            "id",
            None,
        )
    ) or 0

    created = False
    scanned = 0
    deleted = 0
    failed = 0

    try:
        created = add_exact_content_filter(
            group_id,
            descriptor,
            source_message_id,
            source_user_id,
            actor_id,
        )

        scanned, deleted, failed, pinned_ids = await purge_exact_content_history(
            group,
            group_id,
            descriptor[
                "fingerprint"
            ],
            source_message_id=int(source_message_id),
            exclude_message_ids={int(command_message_id)},
        )
        pinned_count = save_cleanup_pin_confirmation(group_id, actor_id, pinned_ids, "content_filter_cleanup")

        filtered_total = exact_content_filter_count(
            group_id
        )

        await send_group_text(
            group,
            (
                "🧿 ZIVO | CONTENT GUARD\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎖 اجراکننده: {actor_role}\n"
                f"🔎 محتوا: {descriptor['preview']}\n"
                f"🧬 وضعیت: {'ثبت شد' if created else 'از قبل ثبت بود'}\n"
                f"🔎 پیام‌های بررسی‌شده: {stats_num(scanned)}\n"
                f"🧹 مشابه‌های پاک‌شده: {stats_num(deleted)}\n"
                f"⚠️ حذف‌نشده: {stats_num(failed)}\n"
                f"📌 پین‌های محافظت‌شده: {stats_num(pinned_count)}\n"
                f"📚 فیلترهای دقیق گروه: {stats_num(filtered_total)}\n"
                "🔐 اجرای نمونه‌های بعدی: وابسته به قفل پیام‌های فیلترشده\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | CONTENT GUARD"
            ),
        )

        log.info(
            "exact content filter registered | group=%s actor=%s type=%s scanned=%s deleted=%s failed=%s fingerprint=%s",
            group_id,
            actor_id,
            descriptor[
                "content_type"
            ],
            scanned,
            deleted,
            failed,
            descriptor[
                "fingerprint"
            ][:80],
        )

    finally:
        _group_cleanup_active.pop(
            int(group_id),
            None,
        )


def log_media_classification(
    group_id: int,
    sender_id: int,
    message: Any,
    category: str,
    violations: set[str],
) -> None:
    media = safe_message_property(
        message,
        "media",
    )

    if media is None:
        return

    sig = document_runtime_signature(
        message
    )

    log.debug(
        "media classify | group=%s user=%s category=%s media=%s doc=%s mime=%s "
        "attrs=%s file=%r size=%s wh=%sx%s violations=%s",
        group_id,
        sender_id,
        category,
        type(media).__name__,
        type(
            sig["document"]
        ).__name__
        if sig["document"]
        is not None
        else "none",
        sig["mime"],
        ",".join(
            sig["attrs"]
        )
        or "none",
        sig["file_name"],
        sig["size"],
        sig["width"],
        sig["height"],
        ",".join(
            sorted(
                violations
            )
        )
        or "none",
    )


def detect_lock_violations(
    event: Any,
    edited: bool = False,
    enabled_locks: Optional[set[str]] = None,
) -> set[str]:
    """Detect only lock types that can actually act on this message.

    60.90 passes the enabled-lock set from the hot in-memory group cache. This
    avoids running every regex/content classifier for every ordinary message in
    busy groups while preserving the exact behavior of every enabled lock.
    """
    text = lock_message_text(event)
    category = lock_message_category(event)
    message = getattr(event, "message", None) or event
    violations: set[str] = set()

    def wanted(lock_name: str) -> bool:
        return enabled_locks is None or lock_name in enabled_locks

    if edited and wanted("ویرایش"):
        violations.add("ویرایش")

    if wanted("فوروارد") and message_is_forwarded(message):
        violations.add("فوروارد")

    if wanted("ریپلای") and bool(getattr(event, "is_reply", False)):
        violations.add("ریپلای")

    if text:
        if wanted("متن"):
            violations.add("متن")
        if wanted("لینک") and LOCK_LINK_RE.search(text):
            violations.add("لینک")
        if wanted("آیدی") and LOCK_USERNAME_RE.search(text):
            violations.add("آیدی")
        if wanted("شماره تلفن") and LOCK_PHONE_RE.search(text):
            violations.add("شماره تلفن")
        if wanted("هشتگ") and LOCK_HASHTAG_RE.search(text):
            violations.add("هشتگ")
        if wanted("عدد") and LOCK_NUMBER_RE.search(text):
            violations.add("عدد")
        if wanted("متن انگلیسی") and LOCK_ENGLISH_RE.search(text):
            violations.add("متن انگلیسی")
        if wanted("ایموجی") and LOCK_EMOJI_RE.search(text):
            violations.add("ایموجی")
        if wanted("فحش") and lock_text_has_profanity(text):
            violations.add("فحش")
        if wanted("تبلیغات") and lock_text_is_advertising(text):
            violations.add("تبلیغات")
        if wanted("کد هنگی") and lock_text_is_hang_code(text):
            violations.add("کد هنگی")
        # Filtered-message matching is intentionally handled once in
        # maybe_enforce_group_lock so built-in + manager phrases share one
        # normalization pass.

    category_map = {
        "sticker": "استیکر",
        "animated_sticker": "استیکر",
        "photo": "عکس",
        "video": "ویدیو",
        "video_note": "ویدیو",
        "voice": "ویس",
        "file": "فایل",
        "gif": "گیف",
        "audio": "آهنگ",
        "poll": "نظرسنجی",
    }
    mapped = category_map.get(category)
    if mapped and wanted(mapped):
        violations.add(mapped)

    if wanted("فایل حجیم") and lock_document_size(event) >= LOCK_LARGE_FILE_BYTES:
        violations.add("فایل حجیم")

    return violations


def first_enabled_lock_violation(
    group_id: int,
    violations: set[str],
    rows: Optional[Dict[str, sqlite3.Row]] = None,
) -> Optional[sqlite3.Row]:
    if not violations:
        return None

    lock_rows = rows if rows is not None else group_lock_rows(group_id)
    for lock_name in LOCK_PRIORITY:
        if lock_name not in violations:
            continue
        row = lock_rows.get(lock_name)
        if row is not None and bool(int(row["enabled"] or 0)):
            return row
    return None


async def delete_locked_message(
    group: Any,
    group_id: int,
    message_id: int,
    message: Optional[Any] = None,
) -> bool:
    target_message = message
    if target_message is None:
        target_message = await resolve_message_for_pin_check(group, message_id)
        if target_message is None:
            return False
    if message_is_pinned(target_message):
        log.info("lock delete skipped pinned | group=%s message=%s", group_id, message_id)
        return False
    if live_delete_circuit_is_open():
        _perf_counters["group_lock_delete_circuit_skip"] += 1
        return False
    for attempt in range(1, 3):
        try:
            await governed_delete_messages(
                group, int(message_id), timeout=LOCK_DELETE_FAST_TIMEOUT_SECONDS, lane="group-lock",
            )
        except Exception as exc:
            if arm_live_delete_circuit(exc):
                return False
            flood_wait = delete_rpc_flood_wait_seconds(exc)
            if flood_wait <= 0:
                log.warning(
                    "lock delete failed | group=%s message=%s attempt=%s | %s: %s",
                    group_id, message_id, attempt, type(exc).__name__, exc,
                )
            if attempt < 2:
                await asyncio.sleep(max(0.25, flood_wait))
                continue
            return False
        # Delete acknowledgement is sufficient for the foreground result.
        # Verification remains enabled, but is intentionally detached so a
        # congested GetMessages RPC cannot hold the group command worker.
        increment_deleted_message_counter(group_id, 1)
        asyncio.create_task(
            _verify_group_lock_delete_worker(group, int(group_id), int(message_id)),
            name=f"zivo-group-lock-verify-{int(group_id)}-{int(message_id)}",
        )
        return True
    return False


async def _verify_group_lock_delete_worker(group: Any, group_id: int, message_id: int) -> None:
    """Low-priority confirmation for a lock delete that already acknowledged."""
    await asyncio.sleep(0.20)
    if live_delete_circuit_is_open():
        return
    exists = await _filter_message_exists_strict(group, int(message_id), timeout=1.25)
    if exists is not True or live_delete_circuit_is_open():
        return
    try:
        await governed_delete_messages(
            group, int(message_id), timeout=LOCK_DELETE_FAST_TIMEOUT_SECONDS, lane="group-lock",
        )
    except Exception as exc:
        arm_live_delete_circuit(exc)


def lock_mute_until_after_strike(
    group_id: int,
    user_id: int,
    seconds: int = 600,
) -> datetime:
    now = datetime.now(
        timezone.utc
    )
    base = now

    state = manual_moderation_row(
        group_id,
        user_id,
    )

    if (
        state is not None
        and int(
            state["muted"]
            or 0
        )
        == 1
        and state["mute_until"]
    ):
        try:
            existing = datetime.fromisoformat(
                state["mute_until"]
            )

            if existing.tzinfo is None:
                existing = existing.replace(
                    tzinfo=timezone.utc
                )

            existing = existing.astimezone(
                timezone.utc
            )

            if existing > base:
                base = existing

        except Exception:
            pass

    return base + timedelta(
        seconds=max(
            60,
            int(seconds),
        )
    )


async def apply_group_lock_punishment(
    group: Any,
    group_id: int,
    sender_id: int,
    row: sqlite3.Row,
    input_sender: Any = None,
) -> Dict[str, Any]:
    lock_name = row[
        "lock_name"
    ]
    action_mode = (
        row["direct_action"]
        or "warning"
    ).strip().lower()

    if action_mode not in {
        "delete",
        "notice",
        "warning",
        "mute",
        "ban",
    }:
        action_mode = "warning"

    maximum = max(
        1,
        min(
            1000,
            int(
                row["max_warnings"]
                or LOCK_DEFAULT_MAX_WARNINGS
            ),
        ),
    )
    auto_ban = bool(
        int(
            row["auto_ban"]
            or 0
        )
    )

    # 60.93 smart-filter safety belt. Phrase/content filters are intentionally
    # conservative even if an old database row carried a direct-ban setting.
    # They may delete + warn, but permanent bans are left to stronger lock
    # families / independent anti-spam evidence.
    if lock_name == FILTERED_MESSAGE_LOCK_NAME:
        action_mode = "warning"
        auto_ban = False

    target_hash = input_peer_access_hash(
        input_sender
    )

    if not target_hash:
        target_hash = stats_access_hash(
            group_id,
            sender_id,
        )

    username = input_peer_username(
        input_sender
    )

    result: Dict[str, Any] = {
        "lock_name": lock_name,
        "mode": action_mode,
        "label": lock_action_label(
            action_mode
        ),
        "maximum": maximum,
        "auto_ban": auto_ban,
        "warning_count": None,
        "target_hash": int(
            target_hash
            or 0
        ),
        "banned_now": False,
        "muted_until": None,
        "success": True,
        "detail": "",
    }

    # حذف: delete only; no counter and no public violation notification.
    if action_mode == "delete":
        result["detail"] = "پیام بی‌صدا حذف شد."
        return result

    # هشدار: delete + notification only. No warning counter change.
    if action_mode == "notice":
        result[
            "detail"
        ] = (
            "هشدار ثبت شد؛ شمارنده اخطار کاربر تغییر نکرد."
        )
        return result

    # اخطار: use the user's global ZIVO warning counter.
    if action_mode == "warning":
        warning_count = increment_manual_warning_bounded(
            group_id,
            sender_id,
            maximum,
            username=username,
            access_hash=int(
                target_hash
                or 0
            ),
        )
        result[
            "warning_count"
        ] = warning_count

        if not auto_ban:
            result[
                "detail"
            ] = (
                "بن خودکار این قفل خاموشه."
            )
            return result

        if warning_count < maximum:
            result[
                "detail"
            ] = (
                f"تا بن نهایی {max(0, maximum - warning_count)} اخطار مونده."
            )
            return result

        ok, error_text = await enforce_zivo_ban(
            group,
            group_id,
            sender_id,
            int(target_hash or 0),
            username,
            SELF_USER_ID,
            None,
            source="lock",
        )

        if not ok:
            result[
                "success"
            ] = False
            result[
                "detail"
            ] = error_text
            return result

        result[
            "banned_now"
        ] = True
        result[
            "detail"
        ] = (
            "سقف اخطار پر شد و بن نهایی اجرا شد."
        )
        return result

    # سکوت: every violation adds another 10 minutes.
    if action_mode == "mute":
        if not target_hash:
            result[
                "success"
            ] = False
            result[
                "detail"
            ] = (
                "پیام حذف شد ولی اطلاعات دسترسی کاربر برای اجرای سکوت کامل نیست."
            )
            return result

        mute_until = lock_mute_until_after_strike(
            group_id,
            sender_id,
            seconds=600,
        )

        ok, error_text = await apply_manual_banned_rights(
            group,
            sender_id,
            int(target_hash),
            mute_banned_rights(
                mute_until
            ),
        )

        if not ok:
            result[
                "success"
            ] = False
            result[
                "detail"
            ] = error_text
            return result

        set_manual_mute_state(
            group_id,
            sender_id,
            username,
            int(target_hash),
            SELF_USER_ID,
            mute_until,
        )

        result[
            "muted_until"
        ] = mute_until
        result[
            "detail"
        ] = (
            "۱۰ دقیقه به سکوت کاربر اضافه شد."
        )
        return result

    # بن: direct permanent send-lock on the first violation.
    if action_mode == "ban":
        ok, error_text = await enforce_zivo_ban(
            group,
            group_id,
            sender_id,
            int(target_hash or 0),
            username,
            SELF_USER_ID,
            None,
            source="lock",
        )

        if not ok:
            result[
                "success"
            ] = False
            result[
                "detail"
            ] = error_text
            return result

        result[
            "banned_now"
        ] = True
        result[
            "detail"
        ] = (
            "بن مستقیم این قفل اجرا شد."
        )
        return result

    return result


async def send_lock_violation_result(
    group: Any,
    user_id: int,
    consequence: Dict[str, Any],
) -> None:
    profile_label = "﹝مشاهده نمایه﹞"
    mode = consequence[
        "mode"
    ]
    if mode == "delete":
        return
    lines = [
        "🚨 ZIVO | LOCK ALERT",
        "━━━━━━━━━━━━━━━━━━",
        f"🔐 {consequence['lock_name']}",
        f"👤 {profile_label}",
        f"🎯 مجازات: {consequence['label']}",
    ]

    if mode == "notice":
        lines.append(
            "⚠️ شمارنده اخطار: بدون تغییر"
        )

    elif mode == "warning":
        warning_count = int(
            consequence[
                "warning_count"
            ]
            or 0
        )
        maximum = int(
            consequence[
                "maximum"
            ]
        )
        lines.append(
            f"⚠️ اخطار کلی: {stats_num(warning_count)} از {stats_num(maximum)}"
        )
        lines.append(
            f"⛔ بن خودکار: {'روشن' if consequence['auto_ban'] else 'خاموش'}"
        )

    elif mode == "mute":
        mute_until = consequence.get(
            "muted_until"
        )

        if isinstance(
            mute_until,
            datetime,
        ):
            lines.append(
                f"🔇 سکوت تا: {moderation_until_text(mute_until)}"
            )

    elif mode == "ban":
        lines.append(
            "⛔ حالت: بن مستقیم"
        )

    lines.extend(
        (
            f"📍 {consequence['detail']}",
            "🧹 پیام خلاف قفل حذف شد.",
            "━━━━━━━━━━━━━━━━━━",
            "⚡ ZIVO | GUARD",
        )
    )

    await send_group_text_with_mentions(
        group,
        "\n".join(
            lines
        ),
        [
            (
                profile_label,
                int(user_id),
                int(
                    consequence.get(
                        "target_hash"
                    )
                    or 0
                ),
            )
        ],
    )


