async def maybe_enforce_exact_content_filter(
    event: Any,
) -> bool:
    if bool(
        getattr(
            event,
            "is_private",
            False,
        )
    ):
        return False

    sender_id = safe_int(
        getattr(
            event,
            "sender_id",
            None,
        )
    )
    message_id = safe_int(
        getattr(
            event,
            "id",
            None,
        )
    )

    if (
        sender_id is None
        or message_id is None
        or sender_id == SELF_USER_ID
        or sender_id in SYSTEM_USER_IDS
    ):
        return False

    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if (
        group_id is None
        or get_installation(group_id) is None
        or not is_group_bot_enabled(group_id)
    ):
        return False

    # Silver+ runtime gate: an expired/downgraded group must not keep
    # exact Content Filter enforcement active merely because old fingerprints
    # remain in SQLite. FREE truly has no Content Filter.
    if not premium.feature_allowed(int(group_id), "content_filter"):
        return False

    if lock_user_is_always_exempt(
        group_id,
        sender_id,
    ):
        return False

    if special_user_bypasses_lock(
        group_id,
        sender_id,
        "پیام‌های فیلترشده",
    ):
        return False

    filtered_lock = group_lock_row(
        group_id,
        "پیام‌های فیلترشده",
    )

    if (
        filtered_lock is None
        or not bool(
            int(
                filtered_lock[
                    "enabled"
                ]
                or 0
            )
        )
    ):
        return False

    # Most groups use the word filter but have no exact media/text fingerprints.
    # Avoid descriptor construction and a per-message lookup until one exists.
    if exact_content_filter_count(group_id) <= 0:
        return False

    message = getattr(
        event,
        "message",
        None,
    ) or event

    descriptor = exact_content_descriptor(
        message
    )

    if descriptor is None:
        return False

    filter_row = exact_content_filter_row(
        group_id,
        descriptor[
            "fingerprint"
        ],
    )

    if filter_row is None:
        return False

    # Lock enforcement is a realtime moderation lane. Soroush updates normally
    # already carry an InputPeer target, while event.get_chat() may block or be
    # unsupported for some legacy/group shapes. Use the zero-roundtrip target
    # first; resolve only as a last resort.
    group = fast_event_group_target(event)
    if group is None:
        try:
            group = await event.get_chat()
        except Exception:
            return False

    deleted = await delete_locked_message(
        group,
        group_id,
        message_id,
        message=message,
    )

    settings = filtered_lock

    input_sender = getattr(
        event,
        "input_sender",
        None,
    )

    consequence = await apply_group_lock_punishment(
        group,
        group_id,
        sender_id,
        settings,
        input_sender=input_sender,
    )

    preview = (
        filter_row[
            "preview"
        ]
        or descriptor[
            "preview"
        ]
    )

    try:
        await send_exact_content_violation_result(
            group,
            sender_id,
            preview,
            consequence,
        )
    except Exception as exc:
        upper = f"{type(exc).__name__}: {exc}".upper()
        if any(token in upper for token in (
            "CHATSENDPLAINFORBIDDEN",
            "CHATWRITEFORBIDDEN",
            "CHANNELPRIVATE",
            "YOU CANNOT SEND PLAIN",
            "YOU CAN'T WRITE IN THIS CHAT",
        )):
            log.info(
                "exact content notice skipped unavailable | group=%s user=%s error=%s",
                group_id, sender_id, type(exc).__name__,
            )
        else:
            log.exception(
                "exact content violation notice failed | group=%s user=%s",
                group_id,
                sender_id,
            )

    log.info(
        "exact content blocked | group=%s user=%s type=%s deleted=%s "
        "punishment=%s warning=%s/%s autoban=%s banned=%s fingerprint=%s",
        group_id,
        sender_id,
        descriptor[
            "content_type"
        ],
        deleted,
        consequence[
            "mode"
        ],
        consequence.get(
            "warning_count"
        ),
        consequence[
            "maximum"
        ],
        consequence[
            "auto_ban"
        ],
        consequence[
            "banned_now"
        ],
        descriptor[
            "fingerprint"
        ][:80],
    )

    return True


def _lock_burst_gate(
    cache: Dict[Tuple[int, int, str], float],
    group_id: int,
    user_id: int,
    lock_name: str,
    interval: float,
    *,
    force: bool = False,
) -> bool:
    now = time.monotonic()
    key = (int(group_id), int(user_id), str(lock_name or ""))
    last = float(cache.get(key, 0.0) or 0.0)
    if force or last <= 0.0 or now - last >= float(interval):
        cache[key] = now
        if len(cache) > 12000:
            cutoff = now - max(60.0, float(interval) * 20.0)
            for old_key, seen_at in list(cache.items())[:4000]:
                if float(seen_at or 0.0) < cutoff:
                    cache.pop(old_key, None)
        return True
    return False


def should_send_group_lock_notice(
    group_id: int,
    user_id: int,
    lock_name: str,
    consequence: Dict[str, Any],
) -> bool:
    force = bool(consequence.get("banned_now")) or not bool(consequence.get("success", True))
    return _lock_burst_gate(
        _group_lock_notice_hot, group_id, user_id, lock_name,
        GROUP_LOCK_NOTICE_INTERVAL_SECONDS, force=force,
    )


def should_log_group_lock_enforced(
    group_id: int,
    user_id: int,
    lock_name: str,
    consequence: Dict[str, Any],
) -> bool:
    force = bool(consequence.get("banned_now")) or not bool(consequence.get("success", True))
    return _lock_burst_gate(
        _group_lock_log_hot, group_id, user_id, lock_name,
        GROUP_LOCK_LOG_INTERVAL_SECONDS, force=force,
    )


async def maybe_enforce_group_lock(
    event: Any,
    edited: bool = False,
) -> bool:
    if bool(
        getattr(
            event,
            "is_private",
            False,
        )
    ):
        return False

    sender_id = safe_int(
        getattr(
            event,
            "sender_id",
            None,
        )
    )
    message_id = safe_int(
        getattr(
            event,
            "id",
            None,
        )
    )

    if (
        sender_id is None
        or message_id is None
        or sender_id == SELF_USER_ID
        or sender_id in SYSTEM_USER_IDS
    ):
        return False

    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if (
        group_id is None
        or get_installation(group_id) is None
        or not is_group_bot_enabled(group_id)
    ):
        return False

    if lock_user_is_always_exempt(
        group_id,
        sender_id,
    ):
        message = getattr(
            event,
            "message",
            None,
        ) or event

        if safe_message_property(
            message,
            "media",
        ) is not None:
            log.debug(
                "group lock bypass | group=%s user=%s role=%s reason=owner_admin_or_exemption",
                group_id,
                sender_id,
                base_bot_role(
                    group_id,
                    sender_id,
                ),
            )

        return False

    lock_rows = group_lock_rows(group_id)
    enabled_lock_names = enabled_group_lock_names(group_id, rows=lock_rows)

    # 96.42 mandatory Bio Guard: the built-in bio-check/biography family is a
    # safety invariant for installed groups. If a legacy group has the generic
    # filtered-message lock disabled, the first detected Bio Guard evasion
    # re-enables that lock before moderation so the message cannot slip through.
    builtin_bio_match = lock_text_matches_builtin_filter(lock_message_text(event))
    if builtin_bio_match and "پیام‌های فیلترشده" not in enabled_lock_names:
        try:
            set_group_lock_enabled(group_id, "پیام‌های فیلترشده", True, 0)
            lock_rows = group_lock_rows(group_id)
            enabled_lock_names = enabled_group_lock_names(group_id, rows=lock_rows)
            log.info("mandatory bio guard auto-enabled | group=%s user=%s", group_id, sender_id)
        except Exception as exc:
            log.warning(
                "mandatory bio guard enable failed | group=%s user=%s | %s: %s",
                group_id, sender_id, type(exc).__name__, exc,
            )

    if not enabled_lock_names:
        return False

    violations = detect_lock_violations(
        event,
        edited=edited,
        enabled_locks=enabled_lock_names,
    )

    filtered_phrase = None
    if "پیام‌های فیلترشده" in enabled_lock_names:
        filtered_phrase = match_filtered_guard_text(
            group_id,
            lock_message_text(event),
        )
        if filtered_phrase is not None:
            violations.add("پیام‌های فیلترشده")
            log.debug(
                "filtered phrase matched | group=%s user=%s phrase=%r",
                group_id, sender_id, filtered_phrase[:100],
            )

    if base_bot_role(group_id, sender_id) == "ویژه" and violations:
        special_message = getattr(event, "message", None) or event
        special_category = robust_message_category(special_message)
        bypassed = {
            lock_name
            for lock_name in violations
            if special_user_bypasses_lock(group_id, sender_id, lock_name)
        }
        # Soroush may expose the same animated document as gif+file/video and a
        # large-file violation at once. An explicit GIF permission must cover
        # those transport aliases too, otherwise the panel says "مجاز" while
        # the same GIF is still deleted by the secondary document label.
        if special_category == "gif" and special_user_bypasses_lock(group_id, sender_id, "گیف"):
            bypassed.update(violations.intersection({"گیف", "فایل", "ویدیو", "فایل حجیم"}))
        if bypassed:
            violations.difference_update(bypassed)
            log.info(
                "special lock access bypass | group=%s user=%s bypassed=%s remaining=%s",
                group_id, sender_id, sorted(bypassed), sorted(violations),
            )
        if not violations:
            return False

    message = getattr(
        event,
        "message",
        None,
    ) or event

    category = robust_message_category(
        message
    )

    log_media_classification(
        group_id,
        sender_id,
        message,
        category,
        violations,
    )

    row = first_enabled_lock_violation(
        group_id,
        violations,
        rows=lock_rows,
    )

    if row is None:
        return False

    # Lock enforcement is a realtime moderation lane. Soroush updates normally
    # already carry an InputPeer target, while event.get_chat() may block or be
    # unsupported for some legacy/group shapes. Use the zero-roundtrip target
    # first; resolve only as a last resort.
    group = fast_event_group_target(event)
    if group is None:
        try:
            group = await event.get_chat()
        except Exception:
            return False

    deleted = await delete_locked_message(
        group,
        group_id,
        message_id,
        message=message,
    )

    input_sender = getattr(
        event,
        "input_sender",
        None,
    )

    consequence = await apply_group_lock_punishment(
        group,
        group_id,
        sender_id,
        row,
        input_sender=input_sender,
    )

    lock_name = str(row["lock_name"] or "")
    if should_send_group_lock_notice(group_id, sender_id, lock_name, consequence):
        try:
            await send_lock_violation_result(
                group,
                sender_id,
                consequence,
            )
        except Exception as exc:
            upper = f"{type(exc).__name__}: {exc}".upper()
            if any(token in upper for token in (
                "CHATSENDPLAINFORBIDDEN",
                "CHATWRITEFORBIDDEN",
                "CHANNELPRIVATE",
                "YOU CANNOT SEND PLAIN",
                "YOU CAN'T WRITE IN THIS CHAT",
                "CHAT_WRITE_FORBIDDEN_BACKOFF",
            )):
                log.info(
                    "lock violation notice skipped unavailable | group=%s user=%s lock=%s error=%s",
                    group_id, sender_id, lock_name, type(exc).__name__,
                )
            else:
                log.exception(
                    "lock violation notice failed | group=%s user=%s lock=%s",
                    group_id, sender_id, lock_name,
                )

    try:
        if premium.feature_allowed(group_id, "watch_list") and premium.is_watched(group_id, sender_id):
            premium.record_watch_event(group_id, sender_id, "lock_violation", f"{lock_name} | punishment={consequence.get('mode')} | deleted={bool(deleted)}")
    except Exception:
        pass

    if should_log_group_lock_enforced(group_id, sender_id, lock_name, consequence):
        log.info(
            "group lock enforced | group=%s user=%s lock=%s deleted=%s punishment=%s "
            "warning=%s/%s autoban=%s banned=%s edited=%s",
            group_id,
            sender_id,
            lock_name,
            deleted,
            consequence[
                "mode"
            ],
            consequence.get(
                "warning_count"
            ),
            consequence[
                "maximum"
            ],
            consequence[
                "auto_ban"
            ],
            consequence[
                "banned_now"
            ],
            edited,
        )

    return True


def forward_lock_fast_lane_candidate(event: Any) -> bool:
    """Cheap synchronous admission test used before the ordinary group queue."""
    if bool(getattr(event, "is_private", False)):
        return False
    message = getattr(event, "message", None) or event
    if not message_is_forwarded(message):
        return False
    gid = int(canonical_anti_spam_group_id(getattr(event, "chat_id", None)) or 0)
    sender_id = safe_int(getattr(event, "sender_id", None))
    message_id = safe_int(getattr(event, "id", None))
    if gid <= 0 or sender_id is None or message_id is None:
        return False
    if int(sender_id) == int(SELF_USER_ID or 0) or int(sender_id) in SYSTEM_USER_IDS:
        return False
    if get_installation(gid) is None or not is_group_bot_enabled(gid):
        return False
    if lock_user_is_always_exempt(gid, int(sender_id)):
        return False
    row = group_lock_row(gid, "فوروارد")
    return bool(row is not None and int(row["enabled"] or 0))


async def _zivo_forward_priority_router_impl(event: Any) -> None:
    """Execute forward moderation before ordinary group chatter queues."""
    global _priority_router_inflight, _last_priority_event_at
    _priority_router_inflight += 1
    _last_priority_event_at = time.monotonic()
    started = time.monotonic()
    try:
        gid = int(canonical_anti_spam_group_id(getattr(event, "chat_id", None)) or 0)
        consumed = await maybe_enforce_forward_lock_fast(event, gid if gid > 0 else None)
        if consumed:
            _perf_counters["forward_priority_handled"] += 1
            log.info(
                "forward priority route handled | group=%s message=%s exec_ms=%.1f",
                gid, safe_int(getattr(event, "id", None)) or 0,
                (time.monotonic() - started) * 1000.0,
            )
            return
        # Candidate state can change between admission and execution. Never drop
        # the event; fall through to the normal router when that happens.
        await _zivo_router_impl(event)
    finally:
        _priority_router_inflight = max(0, int(_priority_router_inflight) - 1)


async def maybe_enforce_forward_lock_fast(event: Any, group_id: Optional[int] = None) -> bool:
    if bool(getattr(event, "is_private", False)):
        return False
    gid = int(group_id or canonical_anti_spam_group_id(getattr(event, "chat_id", None)) or 0)
    sender_id = safe_int(getattr(event, "sender_id", None))
    message_id = safe_int(getattr(event, "id", None))
    if gid <= 0 or sender_id is None or message_id is None:
        return False
    message = getattr(event, "message", None) or event
    if not message_is_forwarded(message):
        return False
    if sender_id == SELF_USER_ID or sender_id in SYSTEM_USER_IDS:
        return False
    if get_installation(gid) is None or not is_group_bot_enabled(gid):
        return False
    if lock_user_is_always_exempt(gid, int(sender_id)):
        return False
    row = group_lock_row(gid, "فوروارد")
    if row is None or not bool(int(row["enabled"] or 0)):
        return False
    group = fast_event_group_target(event)
    if group is None:
        try:
            group = await asyncio.wait_for(event.get_chat(), timeout=1.5)
        except Exception:
            return True
    deleted = await delete_live_message_fast(group, gid, int(message_id), message=message, verify=True)
    if not deleted:
        queue_live_delete_retry(
            gid, int(message_id), target_user_id=int(sender_id),
            reason="forward_lock", error="LIVE_VERIFY_PENDING",
        )
        record_moderation_audit(
            gid, int(sender_id), 0, "forward_delete_pending", "group_lock", False,
            f"message={int(message_id)} durable_retry=1",
        )
    consequence = await apply_group_lock_punishment(
        group, gid, int(sender_id), row, input_sender=getattr(event, "input_sender", None)
    )
    if str(row["direct_action"] or "warning").lower() not in {"delete"}:
        try:
            await send_lock_violation_result(group, int(sender_id), consequence)
        except Exception:
            pass
    if deleted:
        log.info(
            "forward lock fast enforced | group=%s user=%s message=%s deleted=1 punishment=%s",
            gid, sender_id, message_id, consequence.get("mode"),
        )
    else:
        log.warning(
            "forward lock fast pending-delete | group=%s user=%s message=%s durable=1 punishment=%s",
            gid, sender_id, message_id, consequence.get("mode"),
        )
    # True means the event was consumed by moderation; delete success is tracked
    # independently by `deleted` and the durable retry/audit state above.
    return True


