def group_has_manual_zivo_admins(group_id: int) -> bool:
    with db_connect() as con:
        row = con.execute(
            "SELECT 1 FROM bot_admins WHERE group_id = ? AND source = 'manual' LIMIT 1",
            (int(group_id),),
        ).fetchone()
    return row is not None


def group_close_actor_check(
    group_id: int,
    actor_id: int,
) -> Tuple[bool, str]:
    role = base_bot_role(
        group_id,
        actor_id,
    )

    if role not in {"مالک", "ادمین"}:
        return (
            False,
            "⛔ بستن و زمان‌بندی گروه فقط برای مالک و ادمین‌های زیوو فعاله.",
        )

    return True, role


def rights_datetime_to_text(value: Any) -> Optional[str]:
    if not isinstance(value, datetime):
        return None

    if value.tzinfo is None:
        value = value.replace(
            tzinfo=timezone.utc,
        )

    return value.astimezone(
        timezone.utc
    ).isoformat()


def chat_banned_rights_to_dict(
    rights: Any,
) -> Dict[str, Any]:
    data: Dict[str, Any] = {
        "until_date": rights_datetime_to_text(
            getattr(rights, "until_date", None)
        )
    }

    for field in GROUP_RIGHTS_FIELDS:
        data[field] = bool(
            getattr(rights, field, False)
        )

    return data


def chat_banned_rights_from_dict(
    data: Optional[Dict[str, Any]],
) -> Any:
    data = data or {}

    until_date: Optional[datetime] = None
    raw_until = data.get("until_date")

    if isinstance(raw_until, str) and raw_until:
        try:
            until_date = datetime.fromisoformat(
                raw_until
            )
        except Exception:
            until_date = None

    kwargs = {
        field: bool(data.get(field, False))
        for field in GROUP_RIGHTS_FIELDS
    }

    return types.ChatBannedRights(
        until_date=until_date,
        **kwargs,
    )


def closed_group_rights_from_baseline(
    baseline: Dict[str, Any],
) -> Any:
    locked = dict(baseline or {})

    for field in GROUP_SEND_RIGHTS_FIELDS:
        locked[field] = True

    # Closing the group must never remove the ability to read the group.
    locked["view_messages"] = bool(
        baseline.get("view_messages", False)
    )

    return chat_banned_rights_from_dict(
        locked
    )


def empty_group_default_rights() -> Any:
    return chat_banned_rights_from_dict(
        {}
    )


def group_close_peer_kind(group: Any) -> str:
    return (
        "chat"
        if isinstance(group, types.Chat)
        else "channel"
    )


def group_close_access_hash(group: Any) -> int:
    return int(
        getattr(group, "access_hash", 0) or 0
    )


async def resolve_group_close_target(
    group_id: int,
    target: Optional[Any] = None,
) -> Optional[Any]:
    if target is not None:
        return target

    state = get_group_close_state(
        group_id,
    )

    stored = build_stored_pin_peer(
        group_id,
        state["peer_kind"],
        state["group_access_hash"],
    )

    if stored is not None:
        return stored

    schedules = list_group_close_schedules(
        group_id,
        include_expired=True,
    )

    for row in schedules:
        stored = build_stored_pin_peer(
            group_id,
            row["peer_kind"] or "channel",
            int(row["group_access_hash"] or 0),
        )
        if stored is not None:
            return stored

    try:
        return await client.get_input_entity(
            group_id
        )
    except Exception:
        return None


async def resolve_group_entity_for_rights(
    target: Any,
) -> Optional[Any]:
    if isinstance(target, (types.Channel, types.Chat)):
        return target

    target_id = (
        safe_int(getattr(target, "channel_id", None))
        or safe_int(getattr(target, "chat_id", None))
        or safe_int(getattr(target, "id", None))
    )
    target_name = type(target).__name__

    if "Channel" in target_name:
        try:
            try:
                input_channel = utils.get_input_channel(target)
            except Exception:
                channel_id = safe_int(getattr(target, "channel_id", None))
                access_hash = safe_int(getattr(target, "access_hash", None)) or 0
                if channel_id is None:
                    raise
                input_channel = types.InputChannel(
                    channel_id=int(channel_id),
                    access_hash=int(access_hash),
                )
            full = await asyncio.wait_for(
                client(functions.channels.GetFullChannelRequest(input_channel)),
                timeout=15,
            )
            chats = list(getattr(full, "chats", None) or [])
            for chat in chats:
                if target_id is None or safe_int(getattr(chat, "id", None)) == int(target_id):
                    return chat
            if chats:
                return chats[0]
        except Exception as exc:
            log.debug(
                "group rights direct channel resolve failed | id=%s | %s: %s",
                target_id, type(exc).__name__, exc,
            )

    if "Chat" in target_name and "Channel" not in target_name and target_id is not None:
        try:
            full = await asyncio.wait_for(
                client(functions.messages.GetFullChatRequest(int(target_id))),
                timeout=15,
            )
            chats = list(getattr(full, "chats", None) or [])
            for chat in chats:
                if safe_int(getattr(chat, "id", None)) == int(target_id):
                    return chat
            if chats:
                return chats[0]
        except Exception as exc:
            log.debug(
                "group rights direct chat resolve failed | id=%s | %s: %s",
                target_id, type(exc).__name__, exc,
            )

    try:
        return await asyncio.wait_for(client.get_entity(target), timeout=12)
    except Exception as exc:
        try:
            dialogs = await asyncio.wait_for(client.get_dialogs(limit=500), timeout=20)
            for dialog in dialogs:
                entity = getattr(dialog, "entity", None)
                if entity is None:
                    continue
                entity_id = safe_int(getattr(entity, "id", None))
                if target_id is not None and entity_id == int(target_id):
                    return entity
        except Exception as refresh_exc:
            log.debug(
                "group rights dialog refresh failed | id=%s | %s: %s",
                target_id, type(refresh_exc).__name__, refresh_exc,
            )
        log.warning(
            "group rights entity resolve failed | id=%s target=%s | %s: %s",
            target_id, target_name, type(exc).__name__, exc,
        )
        return None


def group_send_rights_closed(rights: Any) -> bool:
    if rights is None:
        return False

    checked = 0
    for field in GROUP_SEND_RIGHTS_FIELDS:
        if not hasattr(rights, field):
            continue
        checked += 1
        if not bool(getattr(rights, field, False)):
            return False

    return checked > 0


async def verify_group_native_closed(target: Any) -> bool:
    # Fetch from the server directly. Do not trust the live event entity here:
    # its default_banned_rights can stay stale after a successful RPC.
    try:
        target_name = type(target).__name__
        target_id = (
            safe_int(getattr(target, "channel_id", None))
            or safe_int(getattr(target, "chat_id", None))
            or safe_int(getattr(target, "id", None))
        )

        entity: Optional[Any] = None

        if "Channel" in target_name and target_id is not None:
            access_hash = safe_int(getattr(target, "access_hash", None)) or 0
            input_channel = types.InputChannel(
                channel_id=int(target_id),
                access_hash=int(access_hash),
            )
            full = await asyncio.wait_for(
                client(functions.channels.GetFullChannelRequest(input_channel)),
                timeout=15,
            )
            chats = list(getattr(full, "chats", None) or [])
            for chat in chats:
                if safe_int(getattr(chat, "id", None)) == int(target_id):
                    entity = chat
                    break
            if entity is None and chats:
                entity = chats[0]

        elif "Chat" in target_name and target_id is not None:
            full = await asyncio.wait_for(
                client(functions.messages.GetFullChatRequest(int(target_id))),
                timeout=15,
            )
            chats = list(getattr(full, "chats", None) or [])
            for chat in chats:
                if safe_int(getattr(chat, "id", None)) == int(target_id):
                    entity = chat
                    break
            if entity is None and chats:
                entity = chats[0]

        if entity is None:
            entity = await asyncio.wait_for(client.get_entity(target), timeout=12)

        rights = getattr(entity, "default_banned_rights", None)
        result = group_send_rights_closed(rights)
        log.info(
            "group close verification readback | id=%s target=%s result=%s",
            target_id, target_name, result,
        )
        return result

    except Exception as exc:
        log.warning(
            "group close verification failed | %s: %s",
            type(exc).__name__, exc,
        )
        return False


def group_close_should_block_now(group_id: int) -> bool:
    gid = int(group_id)
    now = time.monotonic()
    cached = _group_close_block_hot_cache.get(gid)
    if cached is not None and now - cached[0] < HOT_STATE_CACHE_TTL:
        return bool(cached[1])
    state = get_group_close_state(gid)
    blocked = bool(state["manual_closed"]) or bool(active_group_close_schedules(gid))
    _group_close_block_hot_cache[gid] = (now, blocked)
    return blocked


async def apply_group_default_rights(
    target: Any,
    rights: Any,
) -> Tuple[bool, str]:
    try:
        await client(
            functions.messages.EditChatDefaultBannedRightsRequest(
                peer=target,
                banned_rights=rights,
            )
        )
        return True, ""

    except Exception as exc:
        error_text = (
            f"{type(exc).__name__}: {exc}"
        )
        upper = error_text.upper()

        log.warning(
            "group default rights edit failed | %s",
            error_text,
        )

        if (
            "ADMIN" in upper
            or "PRIVILEGE" in upper
            or "RIGHTS" in upper
        ):
            return (
                False,
                (
                    "⛔ ZIVO | دسترسی بستن گروه ناقصه\n"
                    "اکانت زیوو باید دسترسی واقعی مدیریت محدودیت‌های گروه رو داشته باشه."
                ),
            )

        return (
            False,
            "❌ سروش تغییر دسترسی پیش‌فرض گروه رو رد کرد؛ جزئیات داخل لاگ ثبت شد.",
        )


async def close_group_send_access(
    group_id: int,
    target: Any,
    actor_id: int = 0,
) -> Tuple[bool, str]:
    entity = await resolve_group_entity_for_rights(target)
    if entity is None:
        return (
            False,
            "❌ اطلاعات گروه برای ذخیره محدودیت‌های قبلی قابل دریافت نیست.",
        )

    state = get_group_close_state(group_id)
    baseline: Dict[str, Any] = {}

    # If a previous close attempt already saved the real baseline, keep it.
    # Never overwrite it with already-closed rights during a repair attempt.
    raw_baseline = state.get("baseline_rights_json")
    if raw_baseline:
        try:
            loaded = json.loads(raw_baseline)
            if isinstance(loaded, dict):
                baseline = loaded
        except Exception:
            baseline = {}

    if not baseline:
        baseline_rights = getattr(entity, "default_banned_rights", None)
        baseline = (
            chat_banned_rights_to_dict(baseline_rights)
            if baseline_rights is not None
            else chat_banned_rights_to_dict(empty_group_default_rights())
        )

    # Save the baseline before RPC so a failed/half-applied close can always
    # restore the group's original permissions later.
    upsert_group_close_state(
        group_id=group_id,
        peer_kind=group_close_peer_kind(entity),
        group_access_hash=group_close_access_hash(entity),
        actor_id=actor_id,
        effective_closed=False,
        native_verified=False,
        baseline_rights_json=json.dumps(baseline, ensure_ascii=False),
        replace_baseline=True,
    )

    closed_rights = closed_group_rights_from_baseline(baseline)
    if group_has_manual_zivo_admins(group_id):
        # Internal ZIVO admins are not necessarily native Soroush admins. A
        # native default ban would prevent their message from reaching ZIVO at
        # all, so groups with manual admins use the verified ZIVO soft lock:
        # restore the real baseline, then delete only ordinary-member traffic.
        baseline_rights = chat_banned_rights_from_dict(baseline)
        ok, error_text = await apply_group_default_rights(target, baseline_rights)
        if not ok:
            return False, error_text
        upsert_group_close_state(
            group_id=group_id,
            peer_kind=group_close_peer_kind(entity),
            group_access_hash=group_close_access_hash(entity),
            actor_id=actor_id,
            effective_closed=True,
            native_verified=False,
            baseline_rights_json=json.dumps(baseline, ensure_ascii=False),
            replace_baseline=True,
        )
        log.info("group close admin-safe soft mode | group=%s manual_admins=1", group_id)
        return True, ""
    ok, error_text = await apply_group_default_rights(target, closed_rights)
    if not ok:
        return False, error_text

    # RPC success alone is not enough on Soroush. Read the rights back and
    # only advertise a native close after the server confirms it.
    await asyncio.sleep(0.35)
    verified = await verify_group_native_closed(target)

    upsert_group_close_state(
        group_id=group_id,
        peer_kind=group_close_peer_kind(entity),
        group_access_hash=group_close_access_hash(entity),
        actor_id=actor_id,
        effective_closed=True,
        native_verified=verified,
        baseline_rights_json=json.dumps(baseline, ensure_ascii=False),
        replace_baseline=True,
    )

    if verified:
        log.info("group close native verification PASS | group=%s", group_id)
        return True, ""

    log.warning(
        "group close native verification FAILED | group=%s | soft-lock remains active",
        group_id,
    )
    return (
        False,
        "⚠️ سروش قفل واقعی گروه رو تایید نکرد؛ محافظ پشتیبان زیوو فعاله و پیام اعضای عادی حذف می‌شه. زیوو دوباره برای قفل واقعی تلاش می‌کنه.",
    )


async def open_group_send_access(
    group_id: int,
    target: Any,
    actor_id: int = 0,
) -> Tuple[bool, str]:
    state = get_group_close_state(
        group_id,
    )

    baseline: Dict[str, Any] = {}

    raw_baseline = state.get(
        "baseline_rights_json"
    )
    if raw_baseline:
        try:
            loaded = json.loads(
                raw_baseline
            )
            if isinstance(loaded, dict):
                baseline = loaded
        except Exception:
            baseline = {}

    rights = chat_banned_rights_from_dict(
        baseline
    )

    ok, error_text = await apply_group_default_rights(
        target,
        rights,
    )
    if not ok:
        return False, error_text

    upsert_group_close_state(
        group_id=group_id,
        peer_kind=state["peer_kind"],
        group_access_hash=state["group_access_hash"],
        actor_id=actor_id,
        effective_closed=False,
        native_verified=False,
        baseline_rights_json=None,
        replace_baseline=True,
    )

    return True, ""


def parse_group_clock(
    raw: str,
) -> Optional[Tuple[int, int]]:
    raw = normalize_moderation_digits(
        raw.strip()
    )

    match = re.fullmatch(
        r"([0-9]{1,2})(?::([0-9]{1,2}))?",
        raw,
    )
    if not match:
        return None

    hour = int(match.group(1))
    minute = int(
        match.group(2) or 0
    )

    if not (0 <= hour <= 23):
        return None
    if not (0 <= minute <= 59):
        return None

    return hour, minute


def local_date_midnight_from_token(
    token: str,
    now_local: Optional[datetime] = None,
) -> Optional[datetime]:
    now_local = (
        now_local.astimezone(IRAN_TZ)
        if now_local is not None
        else iran_datetime()
    )

    token = normalize_moderation_digits(
        token.strip()
    )

    today = now_local.replace(
        hour=0,
        minute=0,
        second=0,
        microsecond=0,
    )

    if token == "امروز":
        return today

    if token == "فردا":
        return today + timedelta(days=1)

    match = re.fullmatch(
        r"([0-9]{4})[/-]([0-9]{1,2})[/-]([0-9]{1,2})",
        token,
    )
    if not match:
        return None

    year = int(match.group(1))
    month = int(match.group(2))
    day = int(match.group(3))

    try:
        if year >= 1700:
            return datetime(
                year,
                month,
                day,
                tzinfo=IRAN_TZ,
            )

        if not (1 <= month <= 12):
            return None
        if not (1 <= day <= 31):
            return None

        gy, gm, gd = jalali_to_gregorian(
            year,
            month,
            day,
        )

        return datetime(
            gy,
            gm,
            gd,
            tzinfo=IRAN_TZ,
        )

    except Exception:
        return None


def format_close_local_datetime(
    value: datetime,
) -> str:
    local = iran_datetime(
        value
    )
    jy, jm, jd = gregorian_to_jalali(
        local.year,
        local.month,
        local.day,
    )

    return (
        f"{jy:04d}/{jm:02d}/{jd:02d} "
        f"{local.hour:02d}:{local.minute:02d}"
    )


def format_close_gregorian_date(
    value: datetime,
) -> str:
    local = iran_datetime(
        value
    )
    return local.strftime(
        "%Y/%m/%d"
    )


def human_remaining_text(
    target: datetime,
    now: Optional[datetime] = None,
) -> str:
    now = (
        now.astimezone(timezone.utc)
        if now is not None
        else datetime.now(timezone.utc)
    )
    target = (
        target.astimezone(timezone.utc)
        if target.tzinfo is not None
        else target.replace(tzinfo=timezone.utc)
    )

    seconds = max(
        0,
        int((target - now).total_seconds()),
    )

    if seconds < 60:
        return f"{seconds} ثانیه"

    minutes = seconds // 60
    days, rem_minutes = divmod(
        minutes,
        24 * 60,
    )
    hours, mins = divmod(
        rem_minutes,
        60,
    )

    parts: List[str] = []

    if days:
        parts.append(
            f"{days} روز"
        )
    if hours:
        parts.append(
            f"{hours} ساعت"
        )
    if mins and len(parts) < 2:
        parts.append(
            f"{mins} دقیقه"
        )

    return " و ".join(
        parts[:2]
    ) or "کمتر از یک دقیقه"


def parse_group_close_command(
    text: str,
    now_local: Optional[datetime] = None,
) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(
        text
    )
    now_local = (
        now_local.astimezone(IRAN_TZ)
        if now_local is not None
        else iran_datetime()
    )

    if text == "بستن گروه":
        return {
            "action": "close_manual",
        }

    if text == "بازکردن گروه":
        return {
            "action": "open_manual",
        }

    if text in {
        "لیست زمان بستن گروه",
        "لیست تایم بستن گروه",
        "لیست بستن گروه",
        "زمان های بستن گروه",
        "زمانهای بستن گروه",
    }:
        return {
            "action": "list_schedules",
        }

    if text == "وضعیت بستن گروه":
        return {
            "action": "close_status",
        }

    delete_match = re.fullmatch(
        (
            r"(?:حذف زمان بستن گروه|حذف بستن گروه)\s+"
            r"(.+)"
        ),
        text,
    )
    if delete_match:
        selector = normalize_moderation_digits(
            delete_match.group(1).strip()
        )

        if re.fullmatch(
            r"[0-9]+",
            selector,
        ):
            return {
                "action": "delete_schedule",
                "selector_type": "id",
                "schedule_id": int(selector),
            }

        local_day = local_date_midnight_from_token(
            selector,
            now_local=now_local,
        )
        if local_day is not None:
            return {
                "action": "delete_schedule",
                "selector_type": "date",
                "local_day": local_day,
                "selector_text": selector,
            }

        return {
            "action": "invalid_delete_schedule",
        }

    if text.startswith("بستن گروه "):
        normalized = normalize_moderation_digits(
            text
        )
        rest = normalized[
            len("بستن گروه "):
        ].strip()

        # Date/time window, with optional "از".
        window = re.fullmatch(
            (
                r"(?:(امروز|فردا|[0-9]{4}[/-][0-9]{1,2}[/-][0-9]{1,2})\s+)?"
                r"(?:از\s+)?"
                r"([0-9]{1,2}(?::[0-9]{1,2})?)"
                r"\s+تا\s+"
                r"([0-9]{1,2}(?::[0-9]{1,2})?)"
            ),
            rest,
        )

        if window:
            date_token = window.group(1)
            start_clock = parse_group_clock(
                window.group(2)
            )
            end_clock = parse_group_clock(
                window.group(3)
            )

            if (
                start_clock is None
                or end_clock is None
            ):
                return {
                    "action": "invalid_close_schedule",
                }

            explicit_date = date_token is not None

            if date_token is None:
                base_day = now_local.replace(
                    hour=0,
                    minute=0,
                    second=0,
                    microsecond=0,
                )
            else:
                base_day = local_date_midnight_from_token(
                    date_token,
                    now_local=now_local,
                )
                if base_day is None:
                    return {
                        "action": "invalid_close_schedule",
                    }

            start_local = base_day.replace(
                hour=start_clock[0],
                minute=start_clock[1],
            )
            end_local = base_day.replace(
                hour=end_clock[0],
                minute=end_clock[1],
            )

            if end_local <= start_local:
                end_local += timedelta(
                    days=1
                )

            if (
                not explicit_date
                and end_local <= now_local
            ):
                start_local += timedelta(
                    days=1
                )
                end_local += timedelta(
                    days=1
                )

            if end_local <= now_local:
                return {
                    "action": "close_schedule_past",
                }

            return {
                "action": "schedule_window",
                "start_local": start_local,
                "end_local": end_local,
                "date_token": date_token,
            }

        duration = parse_manual_duration(
            normalized,
            ("بستن گروه",),
        )

        if duration is not None:
            if duration.get("invalid"):
                return {
                    "action": "invalid_close_schedule",
                }

            if duration.get("too_long"):
                return {
                    "action": "close_too_long",
                }

            seconds = duration.get(
                "seconds"
            )
            if seconds is None:
                return {
                    "action": "close_manual",
                }

            return {
                "action": "close_duration",
                "seconds": int(seconds),
                "duration_text": duration[
                    "duration_text"
                ],
            }

        return {
            "action": "invalid_close_schedule",
        }

    return None


async def group_close_schedule_target(
    group_id: int,
    target: Optional[Any] = None,
) -> Optional[Any]:
    return await resolve_group_close_target(
        group_id,
        target,
    )


async def reconcile_group_close_state(
    group_id: int,
    target: Optional[Any] = None,
    actor_id: int = 0,
    announce: bool = True,
) -> Tuple[bool, str]:
    purge_expired_group_close_schedules(
        group_id
    )

    state = get_group_close_state(
        group_id
    )
    active = active_group_close_schedules(
        group_id
    )

    should_close = (
        bool(state["manual_closed"])
        or bool(active)
    )
    is_closed = bool(
        state["effective_closed"]
    )

    if should_close == is_closed:
        if not should_close:
            return True, ""

        # A local DB flag is not enough. Older versions could mark the group
        # closed even when Soroush had not persisted the restriction.
        if bool(state.get("native_verified")) or group_has_manual_zivo_admins(group_id):
            return True, ""

        target = await group_close_schedule_target(group_id, target)
        if target is None:
            return (
                False,
                "❌ زیوو نتونست مقصد گروه رو برای ترمیم قفل پیدا کنه.",
            )

        ok, error_text = await close_group_send_access(
            group_id, target, actor_id=actor_id
        )
        return ok, error_text

    target = await group_close_schedule_target(
        group_id,
        target,
    )
    if target is None:
        return (
            False,
            "❌ زیوو نتونست مقصد گروه رو برای اجرای زمان‌بندی پیدا کنه.",
        )

    if should_close:
        ok, error_text = await close_group_send_access(
            group_id,
            target,
            actor_id=actor_id,
        )
        if not ok:
            return False, error_text

        if announce:
            current_active = active_group_close_schedules(
                group_id
            )

            if current_active:
                nearest_end = min(
                    datetime.fromisoformat(
                        row["end_at"]
                    )
                    for row in current_active
                )

                reason = (
                    "⏱ یک بازه زمان‌بندی‌شده شروع شد.\n"
                    f"🔓 نزدیک‌ترین بازشدن: {format_close_local_datetime(nearest_end)}\n"
                    f"⌛ باقی‌مانده: {human_remaining_text(nearest_end)}"
                )
            else:
                reason = (
                    "🔐 قفل دستی فعاله و پایان خودکار نداره."
                )

            try:
                await send_group_text(
                    target,
                    (
                        "🔒 ZIVO | GROUP CLOSED\n"
                        "━━━━━━━━━━━━━━━━━━\n"
                        "🚫 ارسال پیام اعضای عادی بسته شد.\n"
                        f"{reason}\n"
                        "━━━━━━━━━━━━━━━━━━\n"
                        "⚡ ZIVO | GROUP CONTROL"
                    ),
                )
            except Exception:
                pass

        return True, ""

    ok, error_text = await open_group_send_access(
        group_id,
        target,
        actor_id=actor_id,
    )
    if not ok:
        return False, error_text

    if announce:
        try:
            await send_group_text(
                target,
                (
                    "🔓 ZIVO | GROUP OPEN\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "✅ زمان قفل تموم شد و ارسال پیام اعضا دوباره بازه.\n"
                    "🧩 محدودیت‌های پیش‌فرض قبلی گروه هم برگردونده شد.\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "⚡ ZIVO | GROUP CONTROL"
                ),
            )
        except Exception:
            pass

    return True, ""


def schedule_row_times(
    row: sqlite3.Row,
) -> Tuple[datetime, datetime]:
    return (
        datetime.fromisoformat(
            row["start_at"]
        ),
        datetime.fromisoformat(
            row["end_at"]
        ),
    )


def group_close_schedule_list_text(
    group_id: int,
) -> str:
    rows = list_group_close_schedules(
        group_id
    )
    state = get_group_close_state(
        group_id
    )
    now = datetime.now(
        timezone.utc
    )

    lines: List[str] = [
        "🗓 ZIVO | GROUP SCHEDULE",
        "━━━━━━━━━━━━━━━━━━",
        (
            "🔒 قفل دستی: فعال"
            if state["manual_closed"]
            else "🔓 قفل دستی: خاموش"
        ),
    ]

    if not rows:
        lines.extend(
            (
                "",
                "📭 هیچ زمان‌بندی فعال یا آینده‌ای ثبت نشده.",
                "━━━━━━━━━━━━━━━━━━",
                "⚡ ZIVO | GROUP CONTROL",
            )
        )
        return "\n".join(lines)

    lines.append("")
    lines.append(
        f"📌 زمان‌بندی‌ها: {len(rows)}"
    )

    for row in rows[:20]:
        start_at, end_at = schedule_row_times(
            row
        )
        schedule_id = int(
            row["schedule_id"]
        )

        if start_at <= now < end_at:
            status = (
                "🔒 فعال"
                f" | بازشدن تا {human_remaining_text(end_at, now)}"
            )
        else:
            status = (
                "⏳ آینده"
                f" | شروع تا {human_remaining_text(start_at, now)}"
            )

        lines.extend(
            (
                "",
                f"#{schedule_id}  {status}",
                f"├ بستن: {format_close_local_datetime(start_at)}",
                f"├ بازکردن: {format_close_local_datetime(end_at)}",
                f"└ میلادی شروع: {format_close_gregorian_date(start_at)}",
            )
        )

    if len(rows) > 20:
        lines.append(
            f"\n+{len(rows) - 20} زمان‌بندی دیگر"
        )

    lines.extend(
        (
            "",
            "━━━━━━━━━━━━━━━━━━",
            "⚡ ZIVO | GROUP CONTROL",
        )
    )

    return "\n".join(lines)


async def command_group_close(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(
        getattr(event, "sender_id", None)
    )
    if actor_id is None:
        return

    allowed, actor_role = group_close_actor_check(
        group_id,
        actor_id,
    )
    if not allowed:
        await send_group_text(
            group,
            actor_role,
        )
        return

    peer_kind = group_close_peer_kind(
        group
    )
    access_hash = group_close_access_hash(
        group
    )

    # Always refresh a usable peer reference when an authorized command arrives.
    upsert_group_close_state(
        group_id=group_id,
        peer_kind=peer_kind,
        group_access_hash=access_hash,
        actor_id=actor_id,
    )

    action = parsed.get(
        "action"
    )

    if action == "invalid_close_schedule":
        await send_group_text(
            group,
            (
                "⚠️ ZIVO | فرمت زمان‌بندی نامعتبره\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "نمونه‌های درست:\n"
                "بستن گروه\n"
                "بستن گروه 3 ساعت\n"
                "بستن گروه 23:00 تا 02:00\n"
                "بستن گروه فردا 22:00 تا 23:30\n"
                "بستن گروه 1405/05/26 22:00 تا 23:30\n"
                "بستن گروه 2026/08/17 22:00 تا 23:30\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | GROUP CONTROL"
            ),
        )
        return

    if action == "invalid_delete_schedule":
        await send_group_text(
            group,
            (
                "⚠️ برای حذف، شناسه یا تاریخ معتبر بفرست.\n"
                "مثال:\n"
                "حذف زمان بستن گروه 3\n"
                "حذف زمان بستن گروه فردا\n"
                "حذف زمان بستن گروه 1405/05/26"
            ),
        )
        return

    if action == "close_too_long":
        await send_group_text(
            group,
            "⛔ بستن زمان‌دار بیشتر از 365 روز پذیرفته نمی‌شه.",
        )
        return

    if action == "close_schedule_past":
        await send_group_text(
            group,
            "⛔ این بازه زمانی قبلاً تموم شده؛ تاریخ یا ساعت آینده بفرست.",
        )
        return

    if action == "list_schedules":
        await send_group_text(
            group,
            group_close_schedule_list_text(
                group_id
            ),
        )
        return

    if action == "close_status":
        state = get_group_close_state(
            group_id
        )
        active = active_group_close_schedules(
            group_id
        )
        future = list_group_close_schedules(
            group_id
        )

        lines = [
            "🔐 ZIVO | GROUP LOCK STATUS",
            "━━━━━━━━━━━━━━━━━━",
            (
                "🔒 وضعیت فعلی: بسته"
                if (state["manual_closed"] or bool(active))
                else "🔓 وضعیت فعلی: باز"
            ),
            (
                "✅ قفل واقعی سروش: تایید شده"
                if state.get("native_verified")
                else (
                    "🛡 محافظ پشتیبان زیوو: فعال"
                    if (state["manual_closed"] or bool(active))
                    else "ℹ️ قفل واقعی سروش: غیرفعال"
                )
            ),
            (
                "🧷 قفل دستی: فعال"
                if state["manual_closed"]
                else "🧷 قفل دستی: خاموش"
            ),
        ]

        if active:
            nearest_end = min(
                schedule_row_times(row)[1]
                for row in active
            )
            lines.append(
                f"⌛ بازشدن خودکار تا: {human_remaining_text(nearest_end)}"
            )
        else:
            upcoming = [
                row
                for row in future
                if schedule_row_times(row)[0]
                > datetime.now(timezone.utc)
            ]
            if upcoming:
                nearest_start = schedule_row_times(
                    upcoming[0]
                )[0]
                lines.append(
                    f"⏳ زمان تا بسته‌شدن بعدی: {human_remaining_text(nearest_start)}"
                )
            else:
                lines.append(
                    "📭 زمان‌بندی آینده‌ای وجود نداره."
                )

        lines.extend(
            (
                f"🗓 تعداد بازه‌های فعال/آینده: {len(future)}",
                "━━━━━━━━━━━━━━━━━━",
                "⚡ ZIVO | GROUP CONTROL",
            )
        )

        await send_group_text(
            group,
            "\n".join(lines),
        )
        return

    if action == "delete_schedule":
        if parsed["selector_type"] == "id":
            schedule_id = int(
                parsed["schedule_id"]
            )
            row = get_group_close_schedule(
                group_id,
                schedule_id,
            )

            if row is None:
                await send_group_text(
                    group,
                    f"⚠️ زمان‌بندی #{schedule_id} پیدا نشد.",
                )
                return

            deleted = (
                1
                if delete_group_close_schedule(
                    group_id,
                    schedule_id,
                )
                else 0
            )
            selector_label = (
                f"#{schedule_id}"
            )

        else:
            deleted = delete_group_close_schedules_by_local_date(
                group_id,
                parsed["local_day"],
            )
            selector_label = parsed.get(
                "selector_text",
                "تاریخ انتخاب‌شده",
            )

        ok, error_text = await reconcile_group_close_state(
            group_id,
            target=group,
            actor_id=actor_id,
            announce=True,
        )
        if not ok:
            await send_group_text(
                group,
                error_text,
            )

        await send_group_text(
            group,
            (
                "🗑 ZIVO | SCHEDULE REMOVED\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎯 انتخاب: {selector_label}\n"
                f"✅ تعداد حذف‌شده: {deleted}\n"
                "📌 زمان‌بندی‌های آینده دیگر دست‌نخورده موندن.\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | GROUP CONTROL"
            ),
        )
        return

    if action == "open_manual":
        upsert_group_close_state(
            group_id=group_id,
            peer_kind=peer_kind,
            group_access_hash=access_hash,
            actor_id=actor_id,
            manual_closed=False,
        )

        cancelled_active = delete_active_group_close_schedules(
            group_id
        )

        before = get_group_close_state(
            group_id
        )

        ok, error_text = await reconcile_group_close_state(
            group_id,
            target=group,
            actor_id=actor_id,
            announce=True,
        )

        if not ok:
            await send_group_text(
                group,
                error_text,
            )
            return

        after = get_group_close_state(
            group_id
        )

        if not before["effective_closed"] and not after["effective_closed"]:
            await send_group_text(
                group,
                (
                    "🔓 گروه از قبل باز بود.\n"
                    f"🗑 بازه فعال لغوشده: {cancelled_active}\n"
                    "زمان‌بندی‌های آینده باقی موندن."
                ),
            )

        return

    if action == "close_manual":
        upsert_group_close_state(
            group_id=group_id,
            peer_kind=peer_kind,
            group_access_hash=access_hash,
            actor_id=actor_id,
            manual_closed=True,
        )

        ok, error_text = await reconcile_group_close_state(
            group_id,
            target=group,
            actor_id=actor_id,
            announce=True,
        )

        if not ok:
            await send_group_text(
                group,
                error_text,
            )
            return

        if get_group_close_state(group_id)["effective_closed"]:
            await send_group_text(
                group,
                (
                    "🔐 ZIVO | MANUAL GROUP LOCK\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    f"🎖 اجراکننده: {actor_role}\n"
                    "⏳ پایان خودکار: ندارد\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "⚡ ZIVO | GROUP CONTROL"
                ),
            )
        return

    if action == "close_duration":
        now_local = iran_datetime()
        end_local = (
            now_local
            + timedelta(
                seconds=int(parsed["seconds"])
            )
        )

        schedule_id = create_group_close_schedule(
            group_id=group_id,
            peer_kind=peer_kind,
            group_access_hash=access_hash,
            start_at=now_local,
            end_at=end_local,
            label=f"مدت {parsed['duration_text']}",
            actor_id=actor_id,
        )

        ok, error_text = await reconcile_group_close_state(
            group_id,
            target=group,
            actor_id=actor_id,
            announce=True,
        )

        if not ok:
            await send_group_text(
                group,
                error_text,
            )
            return

        await send_group_text(
            group,
            (
                "⏱ ZIVO | TIMED GROUP LOCK\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🆔 زمان‌بندی: #{schedule_id}\n"
                f"🎖 اجراکننده: {actor_role}\n"
                f"⏳ مدت: {parsed['duration_text']}\n"
                f"🔓 بازشدن: {format_close_local_datetime(end_local)}\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | GROUP CONTROL"
            ),
        )
        return

    if action == "schedule_window":
        start_local = parsed[
            "start_local"
        ]
        end_local = parsed[
            "end_local"
        ]

        schedule_id = create_group_close_schedule(
            group_id=group_id,
            peer_kind=peer_kind,
            group_access_hash=access_hash,
            start_at=start_local,
            end_at=end_local,
            label="بازه ساعتی/تاریخی",
            actor_id=actor_id,
        )

        ok, error_text = await reconcile_group_close_state(
            group_id,
            target=group,
            actor_id=actor_id,
            announce=True,
        )
        if not ok:
            await send_group_text(
                group,
                error_text,
            )
            return

        now_utc = datetime.now(
            timezone.utc
        )
        start_utc = start_local.astimezone(
            timezone.utc
        )

        await send_group_text(
            group,
            (
                "🗓 ZIVO | GROUP SCHEDULE SAVED\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🆔 شناسه: #{schedule_id}\n"
                f"🎖 ثبت‌کننده: {actor_role}\n"
                f"🔒 بستن: {format_close_local_datetime(start_local)}\n"
                f"🔓 بازکردن: {format_close_local_datetime(end_local)}\n"
                + (
                    f"⏳ شروع تا: {human_remaining_text(start_utc, now_utc)}\n"
                    if start_utc > now_utc
                    else f"⌛ بازشدن تا: {human_remaining_text(end_local, now_utc)}\n"
                )
                + "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | GROUP CONTROL"
            ),
        )
        return


async def process_group_close_schedules() -> None:
    now_mono = time.monotonic()
    for group_id in group_ids_needing_close_reconcile():
        retry_at = float(GROUP_CLOSE_RETRY_AFTER.get(int(group_id), 0.0) or 0.0)
        if retry_at > now_mono:
            continue

        ok, error_text = await reconcile_group_close_state(
            group_id,
            target=None,
            actor_id=0,
            announce=True,
        )

        if ok:
            GROUP_CLOSE_RETRY_AFTER.pop(int(group_id), None)
            GROUP_CLOSE_LAST_FAILURE.pop(int(group_id), None)
            continue

        signature = str(error_text or "UNKNOWN_GROUP_CLOSE_ERROR")
        previous = GROUP_CLOSE_LAST_FAILURE.get(int(group_id))
        GROUP_CLOSE_LAST_FAILURE[int(group_id)] = signature
        permission_failure = any(token in signature.upper() for token in (
            "دسترسی", "ADMIN", "PRIVILEGE", "RIGHTS", "PRIVATE",
        ))
        retry_seconds = 600.0 if permission_failure else GROUP_CLOSE_FAILURE_BACKOFF_SECONDS
        GROUP_CLOSE_RETRY_AFTER[int(group_id)] = time.monotonic() + retry_seconds
        if previous != signature:
            log.warning(
                "group close reconcile deferred | group=%s retry_in=%ss | %s",
                group_id, int(retry_seconds), signature,
            )
        else:
            log.debug(
                "group close reconcile still unavailable | group=%s retry_in=%ss",
                group_id, int(GROUP_CLOSE_FAILURE_BACKOFF_SECONDS),
            )


async def group_close_worker() -> None:
    await asyncio.sleep(3.0)
    while True:
        try:
            await _yield_background_to_realtime(1.0)
            await process_group_close_schedules()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception(
                "group close worker error"
            )

        await asyncio.sleep(15.0)


def moderation_role_check(
    group_id: int,
    actor_id: int,
    target_id: int,
) -> Tuple[bool, str, str, str]:
    actor_role = base_bot_role(group_id, actor_id)
    target_role = base_bot_role(group_id, target_id)

    if actor_role not in {"مالک", "ادمین", "ویژه"}:
        return (
            False,
            actor_role,
            target_role,
            "⛔ این بخش فقط برای مالک، ادمین و ویژه‌های زیوو بازه.",
        )

    if actor_id == target_id:
        return (
            False,
            actor_role,
            target_role,
            "⛔ اجرای مجازات روی خودت مجاز نیست.",
        )

    if target_role == "مالک":
        return (
            False,
            actor_role,
            target_role,
            "👑 مالک زیوو با فرمان مجازات دستی هدف قرار نمی‌گیره.",
        )

    if actor_role == "ویژه" and target_role in {"ویژه", "ادمین"}:
        return (
            False,
            actor_role,
            target_role,
            "⛔ ویژه فقط روی کاربر عادی دسترسی مجازات داره.",
        )

    if actor_role == "ادمین" and target_role == "ادمین":
        return (
            False,
            actor_role,
            target_role,
            "⛔ ادمین نمی‌تونه ادمین دیگه رو مجازات کنه.",
        )

    return True, actor_role, target_role, ""


def manual_warning_role_check(
    group_id: int,
    actor_id: int,
    target_id: int,
) -> Tuple[bool, str, str, str]:
    actor_role = base_bot_role(group_id, actor_id)
    target_role = base_bot_role(group_id, target_id)

    if actor_role not in {"مالک", "ادمین", "ویژه"}:
        return False, actor_role, target_role, "⛔ این فرمان فقط برای مالک، ادمین و ویژه‌های زیوو فعاله."
    if actor_id == target_id:
        return False, actor_role, target_role, "⛔ نمی‌تونی برای خودت اخطار دستی ثبت کنی."
    if target_role == "مالک":
        return False, actor_role, target_role, "👑 مالک زیوو با اخطار دستی هدف قرار نمی‌گیره."
    if actor_role == "ادمین" and target_role == "ادمین":
        return False, actor_role, target_role, "⛔ ادمین نمی‌تونه به ادمین دیگه اخطار دستی بده."
    if actor_role == "ویژه" and target_role in {"ادمین", "ویژه"}:
        return False, actor_role, target_role, "⛔ ویژه فقط می‌تونه به کاربر عادی اخطار دستی بده."
    return True, actor_role, target_role, ""


def manual_warning_settings_actor_check(
    group_id: int,
    actor_id: int,
) -> Tuple[bool, str]:
    actor_role = base_bot_role(group_id, actor_id)
    if actor_role not in {"مالک", "ادمین", "ویژه"}:
        return False, "⛔ تنظیمات اخطار دستی فقط برای مالک، ادمین و ویژه‌های زیوو بازه."
    return True, actor_role


