_moderation_access_hash_hot: Dict[Tuple[int, int], int] = {}
_moderation_target_locks: Dict[Tuple[int, int], asyncio.Lock] = {}
# A missing member-management permission cannot be repaired by retrying
# EditBannedRequest for every violating message. Hold that expensive RPC per
# group for a few minutes, then retry automatically in case the owner fixed
# the permission meanwhile.
MODERATION_PERMISSION_RETRY_SECONDS = max(30.0, min(1800.0, float(os.getenv("ZIVO_MODERATION_PERMISSION_RETRY", "300.0"))))
_moderation_permission_retry_after: Dict[int, float] = {}


def remember_moderation_access_hash(
    group_id: int,
    user_id: int,
    access_hash: int,
) -> None:
    access_hash = int(access_hash or 0)
    if not access_hash:
        return
    _moderation_access_hash_hot[(int(group_id), int(user_id))] = access_hash
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO stats_members (
                group_id, user_id, username, access_hash,
                first_seen_at, last_seen_at, warning_total
            ) VALUES (?, ?, '', ?, ?, ?, 0)
            ON CONFLICT(group_id, user_id) DO UPDATE SET
                access_hash = excluded.access_hash,
                last_seen_at = excluded.last_seen_at
            """,
            (int(group_id), int(user_id), access_hash, now, now),
        )
        con.execute(
            """
            UPDATE manual_moderation
            SET access_hash = ?
            WHERE group_id = ? AND user_id = ?
            """,
            (access_hash, int(group_id), int(user_id)),
        )
        con.commit()


def _input_peer_user_hash(peer: Any, target_id: int) -> int:
    if peer is None:
        return 0
    peer_user_id = safe_int(
        getattr(peer, "user_id", None)
        or getattr(peer, "id", None)
    )
    if peer_user_id is not None and int(peer_user_id) != int(target_id):
        return 0
    return int(
        safe_int(getattr(peer, "access_hash", None))
        or 0
    )


async def moderation_peer_candidates(
    group: Any,
    target_id: int,
    target_hash: int = 0,
    history_limit: int = 80,
    *,
    resolve_network: bool = True,
) -> List[Any]:
    """Resolve moderation peers with a RAM/DB-first hot path.

    Reply moderation normally carries the user's access_hash already. In that
    common case this function performs no Soroush lookup at all. Network/entity
    history resolution is a bounded fallback only for old numeric-ID targets.
    """
    target_id = int(target_id)
    group_id = int(
        safe_int(getattr(group, "id", None))
        or safe_int(getattr(group, "channel_id", None))
        or 0
    )
    hashes: List[int] = []

    def add_hash(value: Any) -> None:
        parsed = int(safe_int(value) or 0)
        if parsed and parsed not in hashes:
            hashes.append(parsed)

    add_hash(target_hash)
    if group_id:
        add_hash(_moderation_access_hash_hot.get((group_id, target_id), 0))

    # The first moderation phase is truly zero-DB when the reply already carries
    # an access hash. DB/network fallback is only used after a failed hot RPC.
    if resolve_network:
        state = manual_moderation_row(group_id, target_id) if group_id else None
        if state is not None:
            add_hash(state["access_hash"])
        if group_id:
            add_hash(stats_access_hash(group_id, target_id))

    peers: List[Any] = []
    peer_keys: set[Tuple[int, int]] = set()

    def add_peer(peer: Any) -> None:
        if peer is None:
            return
        uid = int(safe_int(getattr(peer, "user_id", None)) or target_id)
        ah = int(safe_int(getattr(peer, "access_hash", None)) or 0)
        if uid != target_id or not ah:
            return
        key = (uid, ah)
        if key in peer_keys:
            return
        peer_keys.add(key)
        peers.append(types.InputPeerUser(user_id=uid, access_hash=ah))
        add_hash(ah)
        if group_id:
            _moderation_access_hash_hot[(group_id, target_id)] = ah

    for access_hash in hashes:
        add_peer(types.InputPeerUser(user_id=target_id, access_hash=int(access_hash)))

    # Hot-path phase never pays a network resolve. The fallback phase always
    # tries to add at least one fresh candidate, even if DB contained a stale hash.
    if not resolve_network:
        return peers

    peer_count_before_network = len(peers)
    try:
        resolved = await asyncio.wait_for(client.get_input_entity(target_id), timeout=1.25)
        add_peer(resolved)
    except Exception:
        pass
    if len(peers) > peer_count_before_network:
        return peers

    # Last-resort bounded history lookup. Old versions could scan hundreds of messages
    # with a per-page wait, making a single "بن" command feel frozen.
    if isinstance(group, (types.Channel, types.InputPeerChannel)):
        async def _history_lookup() -> None:
            async for message in client.iter_messages(
                group,
                limit=max(20, min(80, int(history_limit))),
                wait_time=0,
            ):
                if safe_int(getattr(message, "sender_id", None)) != target_id:
                    continue
                input_sender = getattr(message, "input_sender", None)
                history_hash = input_peer_access_hash(input_sender)
                if not history_hash:
                    sender_obj = getattr(message, "sender", None)
                    history_hash = safe_int(getattr(sender_obj, "access_hash", None)) or 0
                if history_hash:
                    add_peer(types.InputPeerUser(user_id=target_id, access_hash=int(history_hash)))
                    return
        try:
            await asyncio.wait_for(_history_lookup(), timeout=1.75)
        except Exception as exc:
            log.debug(
                "moderation history peer resolve bounded | group=%s target=%s | %s: %s",
                group_id, target_id, type(exc).__name__, exc,
            )

    if group_id:
        for peer in peers:
            access_hash = _input_peer_user_hash(peer, target_id)
            if access_hash:
                _moderation_access_hash_hot[(group_id, target_id)] = access_hash
                break

    return peers


async def apply_manual_banned_rights(
    group: Any,
    target_id: int,
    target_hash: int,
    rights: Any,
) -> Tuple[bool, str]:
    if not isinstance(group, (types.Channel, types.InputPeerChannel)):
        return (
            False,
            "⛔ این عملیات روی ساختار فعلی این گروه توسط API پشتیبانی نمی‌شه.",
        )

    channel_target: Any = group
    try:
        channel_target = utils.get_input_channel(group)
    except Exception:
        if isinstance(group, types.InputPeerChannel):
            try:
                channel_target = types.InputChannel(
                    channel_id=int(group.channel_id),
                    access_hash=int(group.access_hash),
                )
            except Exception:
                channel_target = group

    display_group_id = int(
        safe_int(getattr(group, "id", None))
        or safe_int(getattr(group, "channel_id", None))
        or 0
    )
    if display_group_id:
        retry_after = float(_moderation_permission_retry_after.get(display_group_id, 0.0) or 0.0)
        if time.monotonic() < retry_after:
            return (
                False,
                "MODERATION_PERMISSION_BACKOFF",
            )
    action_key = (display_group_id, int(target_id))
    target_lock = _moderation_target_locks.setdefault(action_key, asyncio.Lock())

    async with target_lock:
        tried: set[Tuple[int, int]] = set()
        last_error = ""

        async def _try_candidates(candidates: List[Any]) -> Tuple[bool, bool, str]:
            nonlocal last_error
            for participant in candidates:
                uid = int(safe_int(getattr(participant, "user_id", None)) or target_id)
                ah = int(safe_int(getattr(participant, "access_hash", None)) or 0)
                key = (uid, ah)
                if key in tried:
                    continue
                tried.add(key)
                try:
                    await asyncio.wait_for(
                        client(
                            functions.channels.EditBannedRequest(
                                channel=channel_target,
                                participant=participant,
                                banned_rights=rights,
                            )
                        ),
                        timeout=4.0,
                    )
                    if ah and display_group_id:
                        _moderation_access_hash_hot[(display_group_id, int(target_id))] = ah
                        # Persist after the RPC; the RAM hot cache is immediately usable.
                        try:
                            asyncio.create_task(
                                asyncio.to_thread(
                                    remember_moderation_access_hash,
                                    display_group_id,
                                    int(target_id),
                                    ah,
                                ),
                                name=f"zivo-modhash-{display_group_id}-{target_id}",
                            )
                        except Exception:
                            pass
                    if display_group_id:
                        _moderation_permission_retry_after.pop(display_group_id, None)
                    return True, False, ""
                except Exception as exc:
                    last_error = f"{type(exc).__name__}: {exc}"
                    upper = last_error.upper()
                    if (
                        "ADMIN" in upper
                        or "PRIVILEGE" in upper
                        or "RIGHTS" in upper
                        or "CHAT_ADMIN" in upper
                        or "CHANNELPRIVATE" in upper
                        or "CHANNEL_PRIVATE" in upper
                        or "YOU LACK PERMISSION" in upper
                    ):
                        if display_group_id:
                            _moderation_permission_retry_after[display_group_id] = (
                                time.monotonic() + MODERATION_PERMISSION_RETRY_SECONDS
                            )
                        log.warning(
                            "manual moderation permission denied | group=%s target=%s | %s",
                            display_group_id or "?", target_id, last_error,
                        )
                        return False, True, last_error
                    log.debug(
                        "manual moderation candidate rejected | group=%s target=%s | %s",
                        display_group_id or "?", target_id, last_error,
                    )
            return False, False, last_error

        # Phase 1: RAM/reply/DB only. This is the normal zero-lookup path.
        candidates = await moderation_peer_candidates(
            group,
            int(target_id),
            int(target_hash or 0),
            resolve_network=False,
        )
        ok, permission_denied, _ = await _try_candidates(candidates)
        if ok:
            return True, ""
        if permission_denied:
            return (
                False,
                (
                    "⛔ ZIVO | دسترسی اجرایی ناقص\n"
                    "زیوو مجوز واقعی محدودسازی اعضا رو در این گروه نداره.\n"
                    "دسترسی مدیریت/محدودسازی اعضا رو برای اکانت زیوو فعال کن."
                ),
            )

        # Phase 2: only when the peer hash was unavailable/stale. Bounded to a
        # couple of seconds instead of the old long history scan.
        fallback = await moderation_peer_candidates(
            group,
            int(target_id),
            int(target_hash or 0),
            history_limit=80,
            resolve_network=True,
        )
        ok, permission_denied, _ = await _try_candidates(fallback)
        if ok:
            return True, ""
        if permission_denied:
            return (
                False,
                (
                    "⛔ ZIVO | دسترسی اجرایی ناقص\n"
                    "زیوو مجوز واقعی محدودسازی اعضا رو در این گروه نداره.\n"
                    "دسترسی مدیریت/محدودسازی اعضا رو برای اکانت زیوو فعال کن."
                ),
            )

        if not tried:
            return (
                False,
                "⚠️ اطلاعات دسترسی کاربر پیدا نشد. روی پیام خود کاربر ریپلای کن و دوباره «بن» رو بفرست.",
            )

        return (
            False,
            (
                "❌ سروش اجرای عملیات بن/رفع بن را رد کرد. "
                "زیوو مسیر سریع و مسیر بازیابی کوتاه را امتحان کرد؛ جزئیات در Audit ثبت می‌شود."
            ),
        )


async def enforce_zivo_ban(
    group: Any,
    group_id: int,
    target_id: int,
    target_hash: int,
    username: str,
    actor_id: int,
    until_date: Optional[datetime],
    source: str,
) -> Tuple[bool, str]:
    ok, error_text = await apply_manual_banned_rights(
        group,
        int(target_id),
        int(target_hash or 0),
        ban_banned_rights(until_date),
    )

    if ok:
        resolved_hash = int(
            target_hash
            or _moderation_access_hash_hot.get((int(group_id), int(target_id)), 0)
            or stats_access_hash(group_id, target_id)
            or 0
        )
        set_manual_ban_state(
            group_id,
            target_id,
            username,
            resolved_hash,
            actor_id,
            until_date,
            int(getattr(group, "access_hash", 0) or 0),
            ban_source=source,
        )
        record_moderation_audit(
            group_id,
            target_id,
            actor_id,
            "ban",
            source,
            True,
            f"until={until_date.isoformat() if until_date else 'permanent'}",
        )
        return True, ""

    record_moderation_audit(
        group_id,
        target_id,
        actor_id,
        "ban",
        source,
        False,
        error_text,
    )
    return False, error_text


async def release_zivo_ban(
    group: Any,
    group_id: int,
    target_id: int,
    target_hash: int,
    actor_id: int,
    source: str = "manual",
) -> Tuple[bool, str]:
    stored_hash = 0
    if not int(target_hash or 0):
        state = manual_moderation_row(group_id, target_id)
        stored_hash = int(state["access_hash"] or 0) if state is not None else 0
    effective_hash = int(
        target_hash
        or _moderation_access_hash_hot.get((int(group_id), int(target_id)), 0)
        or stored_hash
        or stats_access_hash(group_id, target_id)
        or 0
    )

    ok, error_text = await apply_manual_banned_rights(
        group,
        int(target_id),
        effective_hash,
        clear_banned_rights(),
    )

    if ok:
        clear_manual_ban_state(
            group_id,
            target_id,
            actor_id,
        )
        cancel_ban_release_notice(
            group_id,
            target_id,
        )
        record_moderation_audit(
            group_id,
            target_id,
            actor_id,
            "unban",
            source,
            True,
            "platform rights cleared and local state cleared",
        )
        return True, ""

    record_moderation_audit(
        group_id,
        target_id,
        actor_id,
        "unban",
        source,
        False,
        error_text,
    )
    return False, error_text


def get_user_report_settings(group_id: int) -> Dict[str, int]:
    with db_connect() as con:
        row = con.execute(
            "SELECT enabled FROM user_report_settings WHERE group_id = ?",
            (int(group_id),),
        ).fetchone()
    return {"enabled": int(row["enabled"] or 0) if row is not None else 0}


def set_user_report_settings(group_id: int, enabled: bool, actor_id: int) -> Dict[str, int]:
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO user_report_settings(group_id, enabled, updated_by, updated_at)
            VALUES (?, ?, ?, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                enabled=excluded.enabled, updated_by=excluded.updated_by, updated_at=excluded.updated_at
            """,
            (int(group_id), 1 if enabled else 0, int(actor_id), datetime.now(timezone.utc).isoformat()),
        )
        con.commit()
    mark_group_backup_dirty(int(group_id))
    return get_user_report_settings(int(group_id))


def parse_user_report_command(text: str) -> Optional[Dict[str, Any]]:
    normalized = normalize_group_command(text)
    if normalized in {"گزارش فعال", "گزارش روشن", "فعال گزارش"}:
        return {"action": "report_enabled", "enabled": True}
    if normalized in {"گزارش خاموش", "گزارش غیرفعال", "گزارش غیر فعال"}:
        return {"action": "report_enabled", "enabled": False}
    if normalized in {"وضعیت گزارش", "گزارش وضعیت"}:
        return {"action": "report_status"}
    if normalized in {"لیست گزارش", "لیست گزارش ها", "گزارش های اخیر"}:
        return {"action": "report_list"}
    review_match = re.fullmatch(r"(?:تایید|تأیید|رد)\s+گزارش\s+#?(\d+)", normalized)
    if review_match:
        return {
            "action": "report_review",
            "report_id": int(review_match.group(1)),
            "decision": "approved" if normalized.startswith(("تایید", "تأیید")) else "rejected",
        }
    if normalized == "گزارش":
        return {"action": "report_submit", "reason": ""}
    if normalized.startswith("گزارش "):
        reason = normalized[len("گزارش "):].strip()[:180]
        return {"action": "report_submit", "reason": reason}
    return None


def create_user_report(
    group_id: int,
    reporter_user_id: int,
    target_user_id: int,
    target_message_id: int,
    reason: str,
    message_text: str,
) -> int:
    with db_connect() as con:
        cur = con.execute(
            """
            INSERT INTO user_reports(
                group_id, reporter_user_id, target_user_id, target_message_id,
                reason, message_text, status, created_at
            ) VALUES (?, ?, ?, ?, ?, ?, 'new', ?)
            """,
            (
                int(group_id), int(reporter_user_id), int(target_user_id), int(target_message_id),
                str(reason or "")[:180], str(message_text or "")[:1000],
                datetime.now(timezone.utc).isoformat(),
            ),
        )
        con.commit()
        rid = int(cur.lastrowid or 0)
    mark_group_backup_dirty(int(group_id))
    return rid


def recent_user_reports(group_id: int, limit: int = 15) -> List[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            """
            SELECT report_id, reporter_user_id, target_user_id, target_message_id,
                   reason, message_text, status, reviewed_by, reviewed_at, created_at
            FROM user_reports WHERE group_id = ? ORDER BY report_id DESC LIMIT ?
            """,
            (int(group_id), max(1, min(50, int(limit)))),
        ).fetchall()


def get_user_report_row(group_id: int, report_id: int) -> Optional[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            "SELECT * FROM user_reports WHERE group_id=? AND report_id=?",
            (int(group_id), int(report_id)),
        ).fetchone()


def review_user_report(group_id: int, report_id: int, decision: str, actor_id: int) -> Optional[sqlite3.Row]:
    if decision not in {"approved", "rejected"}:
        return None
    now = datetime.now(timezone.utc).isoformat()
    with db_connect() as con:
        changed = con.execute(
            """
            UPDATE user_reports
            SET status=?, reviewed_by=?, reviewed_at=?
            WHERE group_id=? AND report_id=?
            """,
            (str(decision), int(actor_id), now, int(group_id), int(report_id)),
        ).rowcount
        con.commit()
    if not changed:
        return None
    mark_group_backup_dirty(int(group_id))
    return get_user_report_row(int(group_id), int(report_id))


def user_report_manager_mentions(group_id: int) -> List[Tuple[str, int, int]]:
    installation = get_installation(int(group_id))
    items: List[Tuple[str, int, int]] = []
    seen: set[int] = set()
    if installation is not None:
        owner_id = int(installation["owner_user_id"] or 0)
        if owner_id > 0:
            label = str(installation["owner_username"] or "").strip().lstrip("@") or f"مالک-{owner_id}"
            items.append((label, owner_id, int(installation["owner_access_hash"] or 0)))
            seen.add(owner_id)
    with db_connect() as con:
        rows = con.execute(
            "SELECT user_id, username, access_hash FROM bot_admins WHERE group_id=? ORDER BY added_at ASC",
            (int(group_id),),
        ).fetchall()
    for row in rows:
        uid = int(row["user_id"] or 0)
        if uid <= 0 or uid in seen:
            continue
        label = str(row["username"] or "").strip().lstrip("@") or f"ادمین-{uid}"
        items.append((label, uid, int(row["access_hash"] or 0)))
        seen.add(uid)
    if GLOBAL_BOT_OWNER_ID > 0 and GLOBAL_BOT_OWNER_ID not in seen:
        items.append((f"مالک‌کل-{GLOBAL_BOT_OWNER_ID}", int(GLOBAL_BOT_OWNER_ID), 0))
    return items


async def _send_persistent_user_report_card(
    group: Any,
    group_id: int,
    report_id: int,
    reporter_id: int,
    target_id: int,
    target_message_id: int,
    reason: str,
    message_text: str,
) -> None:
    managers = user_report_manager_mentions(int(group_id))
    manager_line = "، ".join(f"{label} ({uid})" for label, uid, _ in managers) or "مالک/ادمین زیوو"
    safe_text = " ".join(str(message_text or "[بدون متن]").split())[:650]
    body = (
        f"🚨 ZIVO | گزارش جدید #{report_id}\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👤 گزارش‌دهنده: {reporter_id}\n"
        f"🎯 کاربر گزارش‌شده: {target_id}\n"
        f"🆔 پیام گزارش‌شده: {target_message_id}\n"
        f"📝 دلیل: {reason or 'بدون توضیح'}\n"
        f"💬 متن: {safe_text}\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👮 بررسی: {manager_line}\n"
        f"✅ تایید گزارش {report_id}\n"
        f"❌ رد گزارش {report_id}\n"
        "ℹ️ خود پیام گزارش‌شده با ثبت گزارش حذف نمی‌شود."
    )
    mention_specs = [(label, uid, access_hash) for label, uid, access_hash in managers]
    # Direct send on purpose: report review cards are persistent and must not be
    # picked up by the normal bot-message cleanup scheduler.
    try:
        entities = rich_mention_entities(body, mention_specs, mention_peer=utils.get_input_peer(group)) if mention_specs else []
    except Exception:
        entities = []
    await client.send_message(
        group, body, reply_to=int(target_message_id), parse_mode=None,
        formatting_entities=entities, link_preview=False,
    )


async def _notify_owner_of_user_report(
    group_id: int,
    group: Any,
    report_id: int,
    reporter_id: int,
    target_id: int,
    target_message_id: int,
    reason: str,
    message_text: str,
) -> None:
    installation = get_installation(int(group_id))
    if installation is None:
        return
    owner_id = int(installation["owner_user_id"] or 0)
    if owner_id <= 0:
        return
    target = await resolve_private_target(None, owner_id)
    if target is None:
        return
    group_title = str(getattr(group, "title", None) or installation["group_title"] or group_id)
    body = (
        f"🚨 ZIVO | گزارش جدید #{report_id}\n"
        f"گروه: {group_title}\n"
        f"گزارش‌دهنده: {reporter_id}\n"
        f"کاربر گزارش‌شده: {target_id}\n"
        f"پیام: {target_message_id}\n"
        f"دلیل: {reason or 'بدون توضیح'}\n"
        f"متن پیام: {(message_text or '[بدون متن]')[:700]}\n\n"
        f"✅ تایید گزارش {report_id}\n"
        f"❌ رد گزارش {report_id}"
    )
    try:
        await send_private(target, body, verify_delivery=False)
    except Exception as exc:
        log.info(
            "user report owner notify failed | group=%s report=%s owner=%s | %s: %s",
            group_id, report_id, owner_id, type(exc).__name__, exc,
        )


async def command_user_report(event: Any, group: Any, group_id: int, parsed: Dict[str, Any]) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    action = str(parsed.get("action") or "")
    role = base_bot_role(int(group_id), int(actor_id))

    if action in {"report_enabled", "report_status", "report_list", "report_review"}:
        if role not in {"مالک", "ادمین"}:
            await send_group_text(group, "⛔ تنظیمات و بررسی گزارش فقط برای مالک و ادمین زیوو بازه.")
            return
        if action == "report_enabled":
            settings = set_user_report_settings(int(group_id), bool(parsed.get("enabled")), int(actor_id))
            await send_group_text(
                group,
                f"🚨 قابلیت گزارش {'فعال شد ✅' if settings['enabled'] else 'خاموش شد ⛔'}",
            )
            return
        if action == "report_status":
            settings = get_user_report_settings(int(group_id))
            await send_group_text(group, f"🚨 گزارش کاربران: {'فعال ✅' if settings['enabled'] else 'خاموش ⛔'}")
            return
        if action == "report_review":
            report_id = int(parsed.get("report_id") or 0)
            decision = str(parsed.get("decision") or "")
            row = review_user_report(int(group_id), report_id, decision, int(actor_id))
            if row is None:
                await send_group_text(group, f"❌ گزارش #{report_id} پیدا نشد.")
                return
            state = "تایید شد ✅" if decision == "approved" else "رد شد ❌"
            # Review is intentionally non-destructive. Deletion/ban remains an
            # explicit moderation command so a mistaken report cannot punish a user.
            await client.send_message(
                group,
                f"🚨 گزارش #{report_id} {state}\n👮 بررسی‌کننده: {actor_id}\nℹ️ هیچ حذف یا بنی خودکار انجام نشد.",
                parse_mode=None, formatting_entities=[], link_preview=False,
            )
            return
        rows = recent_user_reports(int(group_id), 20)
        if not rows:
            await send_group_text(group, "📭 هنوز گزارشی برای این گروه ثبت نشده.")
            return
        labels = {"new": "جدید", "approved": "تایید", "rejected": "رد"}
        lines = ["🚨 ZIVO | گزارش‌های اخیر", "━━━━━━━━━━━━━━━━━━"]
        for row in rows:
            reason = str(row["reason"] or "بدون توضیح").replace("\n", " ")[:60]
            lines.append(
                f"#{row['report_id']} | {labels.get(str(row['status']), str(row['status']))} | "
                f"by={row['reporter_user_id']} | user={row['target_user_id']} | {reason}"
            )
        lines.extend(("━━━━━━━━━━━━━━━━━━", "⚡ ZIVO | REPORT CENTER"))
        await send_group_text(group, "\n".join(lines))
        return

    if action != "report_submit":
        return
    if not get_user_report_settings(int(group_id))["enabled"]:
        return
    if not bool(getattr(event, "is_reply", False)):
        await send_group_text(group, "⚠️ روی پیام موردنظر ریپلای کن و بنویس: گزارش")
        return
    try:
        reply = await asyncio.wait_for(event.get_reply_message(), timeout=2.0)
    except Exception:
        reply = None
    if reply is None:
        await send_group_text(group, "⚠️ پیام گزارش‌شده پیدا نشد؛ دوباره روی پیام ریپلای کن.")
        return
    target_id = safe_int(getattr(reply, "sender_id", None)) or 0
    target_message_id = safe_int(getattr(reply, "id", None)) or 0
    if target_id <= 0 or target_message_id <= 0 or target_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        await send_group_text(group, "⚠️ این پیام برای گزارش کاربر قابل استفاده نیست.")
        return
    message_text = str(getattr(reply, "raw_text", None) or getattr(reply, "message", None) or "")
    reason = str(parsed.get("reason") or "").strip()
    report_id = create_user_report(
        int(group_id), int(actor_id), int(target_id), int(target_message_id), reason, message_text
    )
    await send_group_text(group, f"✅ گزارش ثبت شد | کد #{report_id}")
    try:
        await _send_persistent_user_report_card(
            group, int(group_id), report_id, int(actor_id), int(target_id),
            int(target_message_id), reason, message_text,
        )
    except Exception as exc:
        log.warning(
            "user report card send failed | group=%s report=%s | %s: %s",
            group_id, report_id, type(exc).__name__, exc,
        )
    asyncio.create_task(
        _notify_owner_of_user_report(
            int(group_id), group, report_id, int(actor_id), int(target_id),
            int(target_message_id), reason, message_text,
        ),
        name=f"zivo-report-notify-{int(group_id)}-{report_id}",
    )


def parse_ban_audit_command(text: str) -> Optional[Dict[str, Any]]:
    text = normalize_group_command(text)
    if text in {"گزارش بن", "لاگ بن", "تاریخچه بن"}:
        return {"action": "ban_audit"}
    if text in {"لیست بن", "لیست بن ها", "بن های فعال"}:
        return {"action": "ban_list"}
    if text in {"ترمیم بن ها", "بازسازی بن ها", "بررسی بن ها"}:
        return {"action": "ban_repair"}
    if text in {
        "پاکسازی لیست بن ها", "پاکسازی لیست بن", "تمیز کردن لیست بن ها",
        "پاکسازی کامل لیست بن ها", "پاکسازی کامل بن ها", "پاکسازی همه بن ها",
    }:
        return {"action": "ban_cleanup"}
    return None


def active_ban_rows(group_id: int, limit: int = 30) -> List[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            """
            SELECT user_id, username, access_hash, ban_until, ban_source,
                   updated_by, updated_at
            FROM manual_moderation
            WHERE group_id = ? AND banned = 1
            ORDER BY updated_at DESC
            LIMIT ?
            """,
            (int(group_id), max(1, min(100, int(limit)))),
        ).fetchall()


def all_active_ban_rows(group_id: int) -> List[sqlite3.Row]:
    with db_connect() as con:
        return con.execute(
            """
            SELECT user_id, username, access_hash, ban_until, ban_source,
                   updated_by, updated_at
            FROM manual_moderation
            WHERE group_id = ? AND banned = 1
            ORDER BY updated_at DESC
            """,
            (int(group_id),),
        ).fetchall()


BAN_BULK_RELEASE_CONCURRENCY = max(1, min(8, int(os.getenv("ZIVO_BAN_BULK_RELEASE_CONCURRENCY", "4"))))


async def release_all_active_bans(
    group: Any,
    group_id: int,
    actor_id: int,
) -> Dict[str, int]:
    """Release every active ZIVO ban on-platform, then prune cleared rows.

    Failed platform releases deliberately remain active in SQLite so the ban
    list never claims a user is free while Soroush still restricts them.
    """
    rows = all_active_ban_rows(group_id)
    semaphore = asyncio.Semaphore(BAN_BULK_RELEASE_CONCURRENCY)

    async def release_one(row: sqlite3.Row) -> Tuple[bool, int]:
        target_id = int(row["user_id"] or 0)
        if target_id <= 0:
            return False, target_id
        target_hash = int(
            row["access_hash"]
            or _moderation_access_hash_hot.get((int(group_id), target_id), 0)
            or stats_access_hash(group_id, target_id)
            or 0
        )
        async with semaphore:
            ok, _error_text = await release_zivo_ban(
                group, int(group_id), target_id, target_hash, int(actor_id),
                source="bulk_cleanup",
            )
        if ok:
            reset_manual_warning(
                int(group_id), target_id,
                username=str(row["username"] or ""),
                access_hash=target_hash,
            )
        return bool(ok), target_id

    results: List[Tuple[bool, int]] = []
    if rows:
        gathered = await asyncio.gather(
            *(release_one(row) for row in rows),
            return_exceptions=True,
        )
        for item in gathered:
            if isinstance(item, Exception):
                log.warning(
                    "bulk ban cleanup item failed | group=%s | %s: %s",
                    group_id, type(item).__name__, item,
                )
                results.append((False, 0))
            else:
                results.append(item)

    released = sum(1 for ok, _target_id in results if ok)
    failed = max(0, len(rows) - released)
    with db_connect() as con:
        cur = con.execute(
            "DELETE FROM manual_moderation WHERE group_id = ? AND banned = 0 AND muted = 0",
            (int(group_id),),
        )
        pruned = int(cur.rowcount or 0)
        con.commit()
    mark_group_backup_dirty(int(group_id))
    return {
        "active": len(rows),
        "released": released,
        "failed": failed,
        "pruned": pruned,
    }


async def command_ban_audit(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return
    role = base_bot_role(group_id, actor_id)
    if role not in {"مالک", "ادمین"}:
        await send_group_text(group, "⛔ گزارش بن فقط برای مالک و ادمین زیوو بازه.")
        return

    if parsed.get("action") == "ban_cleanup":
        result = await release_all_active_bans(
            group, int(group_id), int(actor_id),
        )
        await send_group_text(
            group,
            (
                "🧹 ZIVO | پاکسازی کامل لیست بن\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"📋 بن فعال قبل از پاکسازی: {result['active']}\n"
                f"✅ رفع بن واقعی: {result['released']}\n"
                f"❌ رفع بن ناموفق: {result['failed']}\n"
                f"🗑 رکورد پاک‌شده: {result['pruned']}\n"
                f"📌 بن فعال باقی‌مانده: {result['failed']}\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | BAN CLEANUP"
            ),
        )
        return

    if parsed.get("action") == "ban_repair":
        rows = active_ban_rows(group_id, 100)
        if not rows:
            await send_group_text(
                group,
                "🟢 ZIVO | بن فعال ثبت‌شده‌ای برای ترمیم وجود نداره.",
            )
            return

        passed = 0
        failed = 0
        expired = 0
        now_utc = datetime.now(timezone.utc)
        for row in rows:
            target_id = int(row["user_id"])
            until_date: Optional[datetime] = None
            if row["ban_until"]:
                try:
                    until_date = datetime.fromisoformat(str(row["ban_until"]))
                    if until_date.tzinfo is None:
                        until_date = until_date.replace(tzinfo=timezone.utc)
                    until_date = until_date.astimezone(timezone.utc)
                except Exception:
                    until_date = None

            if until_date is not None and until_date <= now_utc:
                expired += 1
                continue

            ok, error_text = await apply_manual_banned_rights(
                group,
                target_id,
                int(row["access_hash"] or 0),
                ban_banned_rights(until_date),
            )
            source = (row["ban_source"] or "manual").strip().lower()
            record_moderation_audit(
                group_id,
                target_id,
                actor_id,
                "ban_repair",
                source,
                ok,
                "platform restriction re-applied" if ok else error_text,
            )
            if ok:
                passed += 1
            else:
                failed += 1

        await send_group_text(
            group,
            (
                "🛠 ZIVO | BAN REPAIR\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"✅ ترمیم واقعی: {passed}\n"
                f"❌ ناموفق: {failed}\n"
                f"⏳ منقضی/در انتظار رفع خودکار: {expired}\n"
                "📋 نتیجه هر مورد داخل Audit و بکاپ گپ ثبت شد.\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | MODERATION CORE"
            ),
        )
        return

    if parsed.get("action") == "ban_list":
        rows = active_ban_rows(group_id, 30)
        if not rows:
            await send_group_text(group, "🟢 ZIVO | هیچ بن فعال ثبت‌شده‌ای در این گپ وجود نداره.")
            return
        lines = [
            "⛔ ZIVO | ACTIVE BANS",
            "━━━━━━━━━━━━━━━━━━",
            f"📌 تعداد نمایش: {len(rows)}",
        ]
        for row in rows:
            until = row["ban_until"] or "دائمی"
            username = ("@" + str(row["username"]).lstrip("@")) if row["username"] else "بدون یوزرنیم"
            lines.append(
                f"• {username} | user={row['user_id']} | source={row['ban_source'] or 'manual'} | until={until}"
            )
        lines.extend(("━━━━━━━━━━━━━━━━━━", "⚡ ZIVO | MODERATION AUDIT"))
        await send_group_text(group, "\n".join(lines))
        return

    rows = recent_moderation_audit(group_id, None, 15)
    if not rows:
        await send_group_text(group, "📭 هنوز Audit بن/رفع بن برای این گپ ثبت نشده.")
        return
    lines = [
        "📋 ZIVO | BAN AUDIT",
        "━━━━━━━━━━━━━━━━━━",
    ]
    for row in rows:
        result = "✅" if int(row["success"] or 0) else "❌"
        lines.append(
            f"{result} {row['action']} | user={row['target_user_id']} | by={row['actor_user_id']} | {row['source']}"
        )
        if row["detail"]:
            detail = str(row["detail"]).replace("\n", " ")[:120]
            lines.append(f"   ↳ {detail}")
    lines.extend(("━━━━━━━━━━━━━━━━━━", "⚡ ZIVO | MODERATION AUDIT"))
    await send_group_text(group, "\n".join(lines))


def moderation_until_text(
    until_date: Optional[datetime],
) -> str:
    if until_date is None:
        return "بدون تاریخ پایان"

    local = iran_datetime(until_date)
    return local.strftime("%Y/%m/%d  %H:%M:%S")


async def send_moderation_result(
    group: Any,
    target_id: int,
    target_hash: int,
    title: str,
    status_line: str,
    actor_role: str,
    target_role: str,
    extra_lines: Optional[List[str]] = None,
) -> None:
    profile_label = "﹝مشاهده نمایه﹞"

    lines = [
        title,
        "━━━━━━━━━━━━━━━━━━",
        f"👤 هدف: {profile_label}",
        f"🎖 مقام هدف: {target_role}",
        f"⚔ اجراکننده: {actor_role}",
    ]

    if extra_lines:
        lines.extend(extra_lines)

    lines.extend(
        (
            status_line,
            "━━━━━━━━━━━━━━━━━━",
            "⚡ ZIVO | MODERATION CORE",
        )
    )

    await send_group_text_with_mentions(
        group,
        "\n".join(lines),
        [
            (
                profile_label,
                int(target_id),
                int(target_hash or 0),
            )
        ],
    )


async def command_manual_moderation(
    event: Any,
    group: Any,
    group_id: int,
    parsed: Dict[str, Any],
) -> None:
    action = parsed.get("action")

    if action == "invalid_mute":
        await send_group_text(
            group,
            (
                "⚠️ ZIVO | فرمت سکوت نامعتبره\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "نمونه‌های درست:\n"
                "سکوت\n"
                "سکوت 47 دقیقه\n"
                "سکوت 3 ساعت\n"
                "سکوت 3 روز\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | MODERATION CORE"
            ),
        )
        return

    if action == "mute_too_long":
        await send_group_text(
            group,
            "⛔ سکوت زمان‌دار بیشتر از 365 روز پذیرفته نمی‌شه.",
        )
        return

    if action == "invalid_ban":
        await send_group_text(
            group,
            (
                "⚠️ ZIVO | فرمت بن نامعتبره\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "نمونه‌های درست:\n"
                "بن\n"
                "بن 47 دقیقه\n"
                "بن 3 ساعت\n"
                "بن 3 روز\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | MODERATION CORE"
            ),
        )
        return

    if action == "ban_too_long":
        await send_group_text(
            group,
            "⛔ بن زمان‌دار بیشتر از 365 روز پذیرفته نمی‌شه.",
        )
        return

    if action == "invalid_warn_ban":
        await send_group_text(
            group,
            (
                "⚠️ ZIVO | فرمت مجازات اخطار نامعتبره\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "بن اخطار دستی 30 دقیقه\n"
                "بن اخطار دستی 1 ساعت\n"
                "بن اخطار دستی 2 روز\n"
                "حذف پیام اخطار دستی فعال\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | WARNING GRID"
            ),
        )
        return

    if action == "warn_ban_too_long":
        await send_group_text(group, "⛔ مدت بن اخطار دستی بیشتر از 365 روز پذیرفته نمی‌شه.")
        return

    if action == "invalid_warn_step":
        await send_group_text(
            group,
            "⚠️ فرمت درست: «کاهش سقف اخطار دستی 1» | مقدار مجاز 1 تا 99",
        )
        return

    if action == "invalid_warn_increment":
        await send_group_text(
            group,
            (
                "⚠️ فرمت درست افزایش زمان بن:\n"
                "افزایش زمان بن اخطار دستی 30 دقیقه\n"
                "افزایش زمان بن اخطار دستی 1 ساعت\n"
                "افزایش زمان بن اخطار دستی 1 روز"
            ),
        )
        return

    if action == "warn_increment_too_long":
        await send_group_text(
            group,
            "⛔ افزایش زمان بن بیشتر از 365 روز پذیرفته نمی‌شه.",
        )
        return

    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return

    if action == "invalid_warn_max":
        await send_group_text(
            group,
            (
                "⚠️ ZIVO | مقدار سقف اخطار نامعتبره\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "فرمت درست:\n"
                "تنظیم حداکثر اخطار دستی 5\n\n"
                "مقدار مجاز: 1 تا 100\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "⚡ ZIVO | WARNING GRID"
            ),
        )
        return

    if action in {
        "set_warn_max",
        "set_warn_autoban",
        "set_warn_action",
        "set_warn_escalation",
        "set_warn_step",
        "set_warn_ban_increment",
        "warn_escalation_status",
    }:
        allowed_settings, actor_role = manual_warning_settings_actor_check(
            group_id,
            actor_id,
        )
        if not allowed_settings:
            await send_group_text(group, actor_role)
            return

        if action == "set_warn_max":
            settings = set_manual_warning_max(
                group_id,
                int(parsed["value"]),
                actor_id,
            )
            await send_group_text(
                group,
                (
                    "⚙️ ZIVO | WARNING LIMIT\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    f"🎖 اجراکننده: {actor_role}\n"
                    f"📌 سقف پایه اخطار: {settings['max_warnings']}\n"
                    f"⚔ مجازات پایه: {warning_action_label(settings)}\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "✅ سقف پایه اخطار ذخیره شد.\n"
                    "⚡ ZIVO | WARNING GRID"
                ),
            )
            return

        if action == "set_warn_escalation":
            settings = set_warning_escalation_enabled(
                group_id,
                bool(parsed["enabled"]),
                actor_id,
            )
            await send_group_text(
                group,
                (
                    "🧠 ZIVO | REPEAT OFFENDER\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    f"🎖 اجراکننده: {actor_role}\n"
                    f"🔘 تصاعد اخطار: {'فعال' if settings['escalation_enabled'] else 'خاموش'}\n"
                    f"📉 کاهش سقف هر دوره: {settings['warning_step']}\n"
                    f"⏱ افزایش بن هر دوره: {warning_duration_label(settings['ban_increment_seconds'])}\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    + (
                        "⚠️ کاربر تکراری دور بعد با اخطار کمتر و بن طولانی‌تر روبه‌رو می‌شه."
                        if settings["escalation_enabled"]
                        else "✅ حساسیت افزایشی متوقف شد؛ سابقه کاربران پاک نشده."
                    )
                    + "\n⚡ ZIVO | WARNING GRID"
                ),
            )
            return

        if action == "set_warn_step":
            settings = set_warning_escalation_step(
                group_id,
                int(parsed["value"]),
                actor_id,
            )
            await send_group_text(
                group,
                (
                    "📉 ZIVO | WARNING STEP\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    f"📌 سقف پایه: {settings['max_warnings']}\n"
                    f"📉 کاهش در هر دوره تکرار: {settings['warning_step']}\n"
                    "🔻 حداقل سقف شخصی: 1 اخطار\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "⚡ ZIVO | WARNING GRID"
                ),
            )
            return

        if action == "set_warn_ban_increment":
            settings = set_warning_escalation_ban_increment(
                group_id,
                int(parsed["seconds"]),
                actor_id,
            )
            await send_group_text(
                group,
                (
                    "⏱ ZIVO | BAN GROWTH\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    f"⏱ افزایش بن در هر دوره: {warning_duration_label(settings['ban_increment_seconds'])}\n"
                    "🧱 سقف نهایی بن زمان‌دار: 365 روز\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "⚡ ZIVO | WARNING GRID"
                ),
            )
            return

        if action == "warn_escalation_status":
            settings = get_manual_warning_settings(group_id)
            await send_group_text(
                group,
                (
                    "🧠 ZIVO | ESCALATION STATUS\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    f"🔘 وضعیت: {'فعال' if settings['escalation_enabled'] else 'خاموش'}\n"
                    f"📌 سقف پایه: {settings['max_warnings']}\n"
                    f"📉 کاهش سقف هر دوره: {settings['warning_step']}\n"
                    f"⚔ مجازات پایه: {warning_action_label(settings)}\n"
                    f"⏱ افزایش بن هر دوره: {warning_duration_label(settings['ban_increment_seconds'])}\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "⚡ ZIVO | WARNING GRID"
                ),
            )
            return

        if action == "set_warn_autoban":
            settings = set_manual_warning_auto_ban(
                group_id,
                bool(parsed["enabled"]),
                actor_id,
            )
        else:
            settings = set_manual_warning_action(
                group_id,
                parsed["mode"],
                actor_id,
                parsed.get("seconds"),
            )

        if settings["action_mode"] == "ban":
            consequence_line = (
                f"🔒 با پر شدن سقف، {warning_action_label(settings)} روی کاربر اجرا می‌شه؛ "
                "کاربر از گروه حذف نمی‌شه."
            )
        elif settings["action_mode"] == "delete":
            consequence_line = (
                "🧹 با پر شدن سقف، هر پیام جدید کاربر بعد از ارسال توسط زیوو پاک می‌شه."
            )
        else:
            consequence_line = "✅ مجازات خودکار خاموش شد؛ اخطارها فقط ثبت می‌شن."

        await send_group_text(
            group,
            (
                "⚔️ ZIVO | WARNING CONSEQUENCE\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"🎖 اجراکننده: {actor_role}\n"
                f"📌 سقف پایه اخطار: {settings['max_warnings']}\n"
                f"⚙️ مجازات پایه: {warning_action_label(settings)}\n"
                "━━━━━━━━━━━━━━━━━━\n"
                f"{consequence_line}\n"
                "⚡ ZIVO | WARNING GRID"
            ),
        )
        return

    target_spec = str(parsed.get("target_spec") or "").strip()
    if target_spec:
        target = await resolve_moderation_target_spec(group_id, target_spec)
        if target is None:
            await send_group_text(group, "⚠️ کاربر با این آیدی/یوزرنیم پیدا نشد.")
            return
    else:
        target = await moderation_reply_target(
            event,
            group,
            group_id,
            normalize_group_command(getattr(event, "raw_text", None) or ""),
        )
        if target is None:
            return

    target_id, target_hash, target_username = target
    target_hash = int(
        target_hash
        or stats_access_hash(group_id, target_id)
        or 0
    )

    if action in {"warn", "reset_warn", "reset_warn_history"}:
        allowed, actor_role, target_role, deny_reason = manual_warning_role_check(
            group_id, actor_id, target_id,
        )
    else:
        allowed, actor_role, target_role, deny_reason = moderation_role_check(
            group_id, actor_id, target_id,
        )

    if not allowed:
        await send_group_text(group, deny_reason)
        return

    if action == "reset_warn_history":
        previous_level = warning_repeat_level(group_id, target_id)
        reset_warning_repeat_level(group_id, target_id)

        await send_moderation_result(
            group,
            target_id,
            target_hash,
            "🧹 ZIVO | ESCALATION RESET",
            "✅ وضعیت: سابقه حساسیت افزایشی این کاربر صفر شد.",
            actor_role,
            target_role,
            [
                f"📚 سابقه قبلی: {previous_level} دوره",
                "🧠 دور بعد با سقف و زمان پایه گروه محاسبه می‌شه.",
            ],
        )
        return

    if action == "warn":
        total = increment_manual_warning(
            group_id,
            target_id,
            username=target_username,
            access_hash=target_hash,
        )

        policy = effective_warning_policy(
            group_id,
            target_id,
        )

        maximum = int(policy["effective_max_warnings"])
        reached = total >= maximum
        action_mode = policy["action_mode"]

        if reached and action_mode == "ban":
            seconds = policy.get("effective_ban_seconds")
            until_date = (
                datetime.now(timezone.utc) + timedelta(seconds=int(seconds))
                if seconds is not None
                else None
            )

            ok, ban_error = await enforce_zivo_ban(
                group,
                group_id,
                target_id,
                target_hash,
                target_username,
                actor_id,
                until_date,
                source="warning",
            )

            if ok:
                consequence_status = (
                    f"⛔ سقف شخصی اخطار پر شد؛ {warning_action_label(policy)} اجرا شد. "
                    "محدودیت واقعی سروش هم دوباره تایید شد."
                )
            else:
                consequence_status = (
                    "⚠️ سقف اخطار پر شد، اما بن واقعی اجرا نشد:\n"
                    + ban_error
                )

        elif reached and action_mode == "delete":
            consequence_status = (
                "🧹 سقف شخصی اخطار پر شد؛ از این لحظه هر پیام جدید این کاربر "
                "بعد از ارسال توسط زیوو پاک می‌شه."
            )
        elif reached:
            consequence_status = (
                "🟠 سقف شخصی اخطار پر شده، اما مجازات خودکار خاموشه."
            )
        else:
            consequence_status = (
                f"⌛ تا سقف شخصی اخطار: {max(0, maximum - total)} اخطار"
            )

        escalation_line = (
            f"🧠 مرحله تکرار: {policy['repeat_level']}"
            if policy["escalation_enabled"]
            else "🧠 تصاعد: خاموش"
        )

        await send_moderation_result(
            group,
            target_id,
            target_hash,
            "⚠️ ZIVO | MANUAL STRIKE",
            "📍 وضعیت: اخطار دستی داخل پرونده کاربر ثبت شد.",
            actor_role,
            target_role,
            [
                f"📊 شمارنده: {warning_progress_text(total, maximum)}",
                f"⚔ مجازات این دور: {warning_action_label(policy)}",
                escalation_line,
                consequence_status,
            ],
        )
        return

    if action == "reset_warn":
        reset_manual_warning(
            group_id,
            target_id,
            username=target_username,
            access_hash=target_hash,
        )

        policy = effective_warning_policy(
            group_id,
            target_id,
        )

        await send_moderation_result(
            group,
            target_id,
            target_hash,
            "🧹 ZIVO | WARNING RESET",
            "✅ وضعیت: پرونده اخطار دستی پاک شد.",
            actor_role,
            target_role,
            [
                f"📊 شمارنده: 0/{policy['effective_max_warnings']}",
                f"⚔ مجازات این دور: {warning_action_label(policy)}",
                (
                    f"🧠 مرحله تکرار: {policy['repeat_level']}"
                    if policy["escalation_enabled"]
                    else "🧠 تصاعد: خاموش"
                ),
            ],
        )
        return

    if action == "mute":
        state = manual_moderation_row(group_id, target_id)
        if state is not None and int(state["banned"] or 0):
            await send_group_text(
                group,
                "⚠️ این کاربر الان بنه؛ اول «رفع بن» رو اجرا کن.",
            )
            return

        seconds = parsed.get("seconds")
        until_date = (
            datetime.now(timezone.utc) + timedelta(seconds=int(seconds))
            if seconds is not None
            else None
        )

        ok, error_text = await apply_manual_banned_rights(
            group,
            target_id,
            target_hash,
            mute_banned_rights(until_date),
        )
        if not ok:
            await send_group_text(group, error_text)
            return

        set_manual_mute_state(
            group_id,
            target_id,
            target_username,
            target_hash,
            actor_id,
            until_date,
        )

        quick_alias = parsed.get("quick_alias") or ""
        extras = [
            f"⏳ مدت: {parsed.get('duration_text', 'دائمی')}",
            f"🕒 پایان: {moderation_until_text(until_date)}",
        ]
        if quick_alias:
            extras.append("⚡ حالت اجرا: فرمان سریع")

        await send_moderation_result(
            group,
            target_id,
            target_hash,
            "🔇 ZIVO | SILENCE LOCK",
            "🔒 وضعیت: مسیر ارسال پیام کاربر قفل شد.",
            actor_role,
            target_role,
            extras,
        )
        log.info(
            "manual mute | group=%s actor=%s actor_role=%s target=%s seconds=%s alias=%s",
            group_id,
            actor_id,
            actor_role,
            target_id,
            seconds,
            quick_alias,
        )
        return

    if action == "unmute":
        state = manual_moderation_row(group_id, target_id)
        if (
            state is None
            or not int(state["muted"] or 0)
        ):
            await send_group_text(
                group,
                "⚠️ سکوت فعالی از طرف زیوو برای این کاربر ثبت نشده.",
            )
            return

        if int(state["banned"] or 0):
            await send_group_text(
                group,
                "⚠️ این کاربر بنه؛ «رفع سکوت» روی کاربر بن‌شده اجرا نمی‌شه.",
            )
            return

        ok, error_text = await apply_manual_banned_rights(
            group,
            target_id,
            target_hash,
            clear_banned_rights(),
        )
        if not ok:
            await send_group_text(group, error_text)
            return

        clear_manual_mute_state(
            group_id,
            target_id,
            actor_id,
        )

        await send_moderation_result(
            group,
            target_id,
            target_hash,
            "🔊 ZIVO | SILENCE RELEASE",
            "✅ وضعیت: قفل ارسال پیام برداشته شد.",
            actor_role,
            target_role,
        )
        log.info(
            "manual unmute | group=%s actor=%s target=%s",
            group_id,
            actor_id,
            target_id,
        )
        return

    if action == "ban":
        seconds = parsed.get("seconds")
        until_date = (
            datetime.now(timezone.utc) + timedelta(seconds=int(seconds))
            if seconds is not None
            else None
        )

        ok, error_text = await enforce_zivo_ban(
            group,
            group_id,
            target_id,
            target_hash,
            target_username,
            actor_id,
            until_date,
            source="manual",
        )
        if not ok:
            await send_group_text(group, error_text)
            return

        await send_moderation_result(
            group,
            target_id,
            target_hash,
            "⛔ ZIVO | ACCESS BAN",
            "🔒 وضعیت: ارسال پیام و محتوا برای کاربر قفل شد؛ عضویت کاربر در گروه حفظ شده.",
            actor_role,
            target_role,
            [
                f"⏳ مدت: {parsed.get('duration_text', 'دائمی')}",
                f"🕒 پایان: {moderation_until_text(until_date)}",
            ],
        )
        log.info(
            "manual ban | group=%s actor=%s actor_role=%s target=%s seconds=%s",
            group_id,
            actor_id,
            actor_role,
            target_id,
            seconds,
        )
        return

    if action == "unban":
        state = manual_moderation_row(group_id, target_id)
        ban_source = (
            (state["ban_source"] or "manual").strip().lower()
            if state is not None
            else "manual"
        )
        stored_hash = int(state["access_hash"] or 0) if state is not None else 0
        effective_hash = int(
            target_hash
            or stored_hash
            or stats_access_hash(group_id, target_id)
            or 0
        )

        ok, error_text = await release_zivo_ban(
            group,
            group_id,
            target_id,
            effective_hash,
            actor_id,
            source="manual",
        )
        if not ok:
            await send_group_text(group, error_text)
            return

        reset_manual_warning(
            group_id,
            target_id,
            username=target_username,
            access_hash=effective_hash,
        )

        if ban_source == "warning":
            increment_warning_repeat_level(
                group_id,
                target_id,
            )

        await send_ban_release_notice(
            group,
            target_id,
            effective_hash,
            automatic=False,
            group_id=group_id,
        )

        log.info(
            "manual unban | group=%s actor=%s target=%s warnings_reset=1 db_recovery=%s",
            group_id,
            actor_id,
            target_id,
            1 if state is None or not int(state["banned"] or 0) else 0,
        )
        return


def ban_release_text(
    automatic: bool,
    group_id: int,
    user_id: int,
) -> Tuple[str, str]:
    profile_label = "﹝مشاهده نمایه﹞"

    if automatic:
        reason_line = "⏱ زمان بن تموم شد و محدودیت ارسال برداشته شد."
    else:
        reason_line = "🟢 بن کاربر برداشته شد و ارسال پیام دوباره آزاده."

    policy = effective_warning_policy(
        group_id,
        user_id,
    )

    if policy["escalation_enabled"]:
        escalation_lines = (
            f"🧠 مرحله حساسیت بعدی: {policy['repeat_level']}\n"
            f"📉 سقف اخطار دور بعد: {policy['effective_max_warnings']}\n"
            f"⏱ مجازات دور بعد: {warning_action_label(policy)}\n"
        )
    else:
        escalation_lines = "🧠 تصاعد اخطار: خاموش\n"

    text = (
        "🟢 ZIVO | BAN RELEASE\n"
        "━━━━━━━━━━━━━━━━━━\n"
        f"👤 کاربر: {profile_label}\n"
        f"{reason_line}\n"
        "🧹 اخطارهای دستی: 0\n"
        f"{escalation_lines}"
        "⚠️ پرونده اخطار از صفر شروع شد؛ این بار جدی‌تر مراقب باش و دوباره خطا نکن.\n"
        "━━━━━━━━━━━━━━━━━━\n"
        "⚡ ZIVO | CLEAN RETURN"
    )

    return text, profile_label


async def send_ban_release_notice(
    group_target: Any,
    user_id: int,
    user_access_hash: int,
    automatic: bool,
    group_id: int,
) -> None:
    text, profile_label = ban_release_text(
        automatic,
        group_id,
        user_id,
    )

    await send_group_text_with_mentions(
        group_target,
        text,
        [
            (
                profile_label,
                int(user_id),
                int(user_access_hash or 0),
            )
        ],
    )


def stored_group_peer(
    group_id: int,
    group_access_hash: int,
) -> Optional[Any]:
    if not group_access_hash:
        return None

    try:
        return types.InputPeerChannel(
            channel_id=int(group_id),
            access_hash=int(group_access_hash),
        )
    except Exception:
        return None


async def process_pending_ban_release_notices() -> None:
    prepare_due_ban_releases()

    for row in pending_ban_release_rows():
        group_id = int(row["group_id"])
        user_id = int(row["user_id"])
        user_hash = int(row["access_hash"] or 0)
        group_hash = int(row["group_access_hash"] or 0)
        username = row["username"] or ""
        ban_source = (row["ban_source"] or "manual").strip().lower()

        target = stored_group_peer(
            group_id,
            group_hash,
        )

        if target is None:
            try:
                target = await client.get_input_entity(group_id)
            except Exception as exc:
                detail = f"group resolve failed: {type(exc).__name__}: {exc}"
                record_moderation_audit(
                    group_id, user_id, SELF_USER_ID,
                    "unban", "timer", False, detail,
                )
                touch_ban_release_retry(group_id, user_id, 1800)
                log.info(
                    "ban release group resolve deferred | group=%s user=%s retry=1800s | %s",
                    group_id, user_id, detail,
                )
                continue

        ok, error_text = await release_zivo_ban(
            target,
            group_id,
            user_id,
            user_hash,
            SELF_USER_ID,
            source="timer",
        )

        if not ok:
            # Timed releases are background maintenance, so one failed platform
            # attempt gets a five-minute quiet window instead of competing with
            # live group/private traffic every few seconds. Manual repair/cleanup
            # remains immediately available to managers.
            retry_delay = 300
            touch_ban_release_retry(group_id, user_id, retry_delay)
            log.info(
                "timed ban real release deferred | group=%s user=%s retry=%ss | %s",
                group_id, user_id, retry_delay, error_text,
            )
            continue

        reset_manual_warning(
            group_id,
            user_id,
            username=username,
            access_hash=user_hash,
        )

        if ban_source == "warning":
            increment_warning_repeat_level(
                group_id,
                user_id,
            )

        try:
            await send_ban_release_notice(
                target,
                user_id,
                user_hash,
                automatic=True,
                group_id=group_id,
            )
        except Exception as exc:
            log.warning(
                "timed ban release notice failed after successful release | group=%s user=%s | %s: %s",
                group_id, user_id, type(exc).__name__, exc,
            )

        log.info(
            "timed ban real release PASS | group=%s user=%s warnings_reset=1 source=%s",
            group_id, user_id, ban_source,
        )


async def timed_ban_release_worker() -> None:
    await asyncio.sleep(0.75)
    while True:
        try:
            await _yield_background_to_realtime(0.5)
            await process_pending_ban_release_notices()
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("timed ban release worker error")

        await asyncio.sleep(5.0)


def fast_event_group_target(event: Any) -> Optional[Any]:
    for attr in ("input_chat", "chat"):
        try:
            candidate = getattr(event, attr, None)
        except Exception:
            candidate = None
        if isinstance(candidate, (types.InputPeerChannel, types.InputPeerChat, types.Channel, types.Chat)):
            return candidate
    message = getattr(event, "message", None) or event
    peer = getattr(message, "peer_id", None)
    if isinstance(peer, types.PeerChat):
        return types.InputPeerChat(int(peer.chat_id))
    return None


async def handle_critical_moderation_fast(event: Any, group_id: int) -> bool:
    """Zero-wait moderation lane for ban/mute/warn/unban commands.

    It deliberately avoids event.get_chat() and the general per-group command
    lock. Role checks stay intact; only trusted ZIVO roles enter this lane.
    """
    text = normalize_group_command(getattr(event, "raw_text", None) or "")
    parsed = parse_manual_moderation_command(text)
    if parsed is None:
        return False

    actor_id = safe_int(getattr(event, "sender_id", None))
    if actor_id is None:
        return False
    actor_role = base_bot_role(int(group_id), int(actor_id))
    if actor_role not in {"مالک", "ادمین", "ویژه"}:
        return False

    target = fast_event_group_target(event)
    if target is None:
        return False

    started = time.perf_counter()
    await command_manual_moderation(event, target, int(group_id), parsed)
    elapsed_ms = (time.perf_counter() - started) * 1000.0
    log.info(
        "critical moderation fast-path | group=%s actor=%s role=%s action=%s exec_ms=%.1f",
        group_id, actor_id, actor_role, parsed.get("action"), elapsed_ms,
    )
    return True


