def _capability_priority_command_heads() -> frozenset[str]:
    heads = set(PRIORITY_GROUP_COMMAND_HEADS)
    for feature in ZIVO_CAPABILITY_REGISTRY:
        command = str(feature.get("help_command") or "").strip()
        if command:
            heads.add(command.split(" ", 1)[0])
        for alias in feature.get("help_aliases", ()) or ():
            value = str(alias or "").strip()
            if value:
                heads.add(value.split(" ", 1)[0])
        for item in feature.get("command_details", ()) or ():
            if item:
                value = str(item[0] or "").strip()
                if value:
                    heads.add(value.split(" ", 1)[0])
        for section in feature.get("help_sections", ()) or ():
            commands = section[1] if len(section) > 1 else ()
            for item in commands or ():
                if item:
                    value = str(item[0] or "").strip()
                    if value:
                        heads.add(value.split(" ", 1)[0])
    for category in ZIVO_HELP_CATEGORIES:
        value = str(category.get("command") or "").strip()
        if value:
            heads.add(value.split(" ", 1)[0])
        for alias in category.get("aliases", ()) or ():
            value = str(alias or "").strip()
            if value:
                heads.add(value.split(" ", 1)[0])
    return frozenset(heads)


PRIORITY_GROUP_COMMAND_HEADS = _capability_priority_command_heads() | EXTRA_COMMAND_HEADS


def parse_market_utility_command(raw_text: Any) -> Optional[Dict[str, Any]]:
    value = str(raw_text or "").strip()
    if not value:
        return None
    conversion = market_tools.parse_conversion_request(value)
    if conversion is not None:
        return {"action": "convert", "text": value, "conversion": conversion}
    has_operator = bool(re.search(r"[+\-*/×÷()]", value))
    has_operands = sum(1 for char in value if char.isdigit()) >= 2
    arithmetic = market_tools.try_calculate_expression(value) if has_operator and has_operands else None
    if arithmetic is not None:
        return {"action": "calculate", "text": value, "arithmetic": arithmetic}
    return None



def looks_like_priority_group_command(raw_text: Any, user_id: Optional[int] = None) -> bool:
    text = normalize_group_command(str(raw_text or ""))
    if not text or len(text) > 220:
        return False
    schedule_text = normalize_moderation_digits(text)
    if re.fullmatch(
        r"(?:هر\s+(?:[0-9]+|یک|یه)\s*(?:دقیقه|ساعت|روز)|روزانه|هر\s+شب).{0,45}پاکسازی(?:\s+.*)?",
        schedule_text,
    ):
        return True
    if (
        text in BOT_STATUS_COMMANDS
        or text in BOT_COMMAND_LIST_COMMANDS
        or text in BOT_HELP_COMMANDS
        or text in BOT_START_GUIDE_COMMANDS
        or text in BOT_HELP_CATEGORY_COMMANDS
        or text in BOT_HELP_DETAIL_COMMANDS
        or text in BOT_DATE_TIME_COMMANDS
        or text in ENTERTAINMENT_COMMANDS
        or social_games.parse_social_command(text, user_id=user_id) is not None
        or parse_market_utility_command(text) is not None
        or parse_role_assignment_command(text) is not None
        or parse_voice_settings_command(text) is not None
        or parse_quick_lock_command(text) is not None
        or is_bot_call_text(text)
    ):
        return True
    head = text.split(" ", 1)[0]
    return head in PRIORITY_GROUP_COMMAND_HEADS


def group_event_may_be_command(
    raw_text: Any,
    group_id: Optional[int] = None,
    sender_id: Optional[int] = None,
) -> bool:
    """Cheap command gate for the ordinary group-message hot path.

    All documented command heads are generated from the capability registry.
    The only intentionally headless case is a short answer inside an active mass
    tag wizard; that is checked only for the wizard owner.
    """
    text = normalize_group_command(str(raw_text or ""))
    if not text:
        return False
    if looks_like_priority_group_command(text, sender_id):
        return True
    if group_id is not None and sender_id is not None and global_origin_registration_context_matches(
        int(sender_id), "group", int(group_id)
    ):
        return True
    if group_id is None or sender_id is None or len(text) > 220:
        return False
    session = _tag_session(int(group_id))
    if not session or int(session.get("actor_id") or 0) != int(sender_id):
        return False
    try:
        return parse_tag_command(text, allow_short=True) is not None
    except Exception:
        return False


async def _handle_group_public_instant_command_impl(event: Any, group_id: int) -> bool:
    text = normalize_group_command(getattr(event, "raw_text", None) or "")
    if not text:
        return False
    target = fast_event_group_target(event)
    if target is None or get_installation(group_id) is None or not is_group_bot_enabled(group_id):
        return False
    bot_call = is_bot_call_text(text)
    global_identity_command = parse_global_identity_command(text)
    if global_identity_command is not None:
        await command_global_identity_group(event, target, global_identity_command)
        return True
    if bot_call and await maybe_handle_speaker_message(event, group_id, force_event="call", target_override=target):
        return True
    if text in BOT_STATUS_COMMANDS or bot_call:
        await command_bot_status(target)
        return True
    if text in BOT_COMMAND_LIST_COMMANDS:
        await command_direct_command_list(target)
        return True
    if text in BOT_HELP_COMMANDS:
        await command_help_center(target)
        return True
    if text in BOT_START_GUIDE_COMMANDS:
        await command_start_guide(target)
        return True
    if text in BOT_HELP_CATEGORY_COMMANDS:
        await command_help_category(target, text)
        return True
    if text in BOT_HELP_DETAIL_COMMANDS:
        await command_help_topic(target, text, safe_int(getattr(event, "sender_id", None)))
        return True
    if text.startswith("راهنما "):
        feature = find_help_feature_fuzzy(text)
        actor_id = safe_int(getattr(event, "sender_id", None))
        if help_feature_visible_for_actor(feature, actor_id):
            topic_text, topic_commands = capability_topic_text(feature)
            await send_copyable_command_text(target, topic_text, topic_commands)
        else:
            await command_help_center(target)
        return True
    if text in BOT_DATE_TIME_COMMANDS:
        await command_date_time(target)
        return True
    premium_command = parse_premium_group_command(text)
    if premium_command is not None:
        group = await event.get_chat()
        await command_premium_group(event, group, int(group_id), premium_command)
        return True
    font_command = parse_font_command(text)
    market_utility_command = parse_market_utility_command(text)
    if market_utility_command is not None:
        await command_market_utility(target, market_utility_command)
        return True
    if font_command is not None:
        await command_font(target, font_command)
        return True
    social_command = social_games.parse_social_command(
        text, user_id=safe_int(getattr(event, "sender_id", None))
    )
    if social_command is not None:
        await command_social_group(event, target, int(group_id), social_command)
        return True
    if text in ENTERTAINMENT_COMMANDS:
        await command_entertainment(target, text, f"group:{group_id}")
        return True
    return False


