def premium_requirement_for_command(text: str) -> tuple[Optional[str], str]:
    t = normalize_group_command(text)
    if not t:
        return None, premium.PLAN_FREE
    numeric_cleanup = re.fullmatch(r"(?:پاکسازی|حذف)\s+([0-9۰-۹٠-٩٬,]+)", t)
    if numeric_cleanup:
        raw_count = normalize_moderation_digits(numeric_cleanup.group(1)).replace(",", "").replace("٬", "")
        try:
            cleanup_count = int(raw_count)
        except ValueError:
            cleanup_count = 0
        if cleanup_count > 5000:
            return "cleanup_limit", premium.PLAN_DIAMOND
        if cleanup_count > 2000:
            return "cleanup_limit", premium.PLAN_GOLD
        if cleanup_count > 700:
            return "cleanup_limit", premium.PLAN_SILVER
    if t.startswith("فیلتر محتوا") or t in {"حذف فیلتر محتوا", "لیست فیلتر محتوا"}:
        return "content_filter", premium.PLAN_SILVER
    if t.startswith("پاکسازی زمان") or t.startswith("زمان پاکسازی") or t.startswith("پاکسازی خودکار"):
        return "scheduled_cleanup", premium.PLAN_SILVER
    if "سخنگو هوشمند" in t or "هوش مصنوعی" in t or "ai سخنگو" in t.casefold() or "سخنگو ai" in t.casefold():
        return "ai_speaker", premium.PLAN_GOLD
    if any(x in t for x in ("یادگیری سخنگو", "سخنگو یادگیری", "شخصیت سخنگو", "حالت سخنگو")):
        if any(x in t.casefold() for x in ("normal", "معمولی", "نرمال")) and "یادگیری" not in t:
            return None, premium.PLAN_FREE
        return "speaker_learning", premium.PLAN_SILVER
    if t in {"پاکسازی گپ", "پاکسازی کل گپ", "پاکسازی کامل گپ", "پاکسازی کامل", "پاکسازی کل"}:
        return "manual_backup", premium.PLAN_GOLD  # GOLD professional destructive lane
    if any(x in t for x in ("رسانه خوشامد", "گیف خوشامد", "عکس خوشامد", "استیکر خوشامد", "تنظیم رسانه خوشامد")):
        return "welcome_media", premium.PLAN_GOLD
    if t in {"گزارش امروز"}:
        return "daily_report", premium.PLAN_GOLD
    if t in {"پرونده", "پرونده‌اش", "پرونده اش"}:
        return "user_dossier", premium.PLAN_GOLD
    if t in {"گزارش ادمین", "گزارش ادمین‌ها", "گزارش ادمین ها"}:
        return "admin_audit", premium.PLAN_GOLD
    if t.startswith("بکاپ ") or t.startswith("وضعیت بکاپ"):
        if "خودکار" in t:
            return "auto_backup", premium.PLAN_DIAMOND
        return "manual_backup", premium.PLAN_GOLD
    if t.startswith("کپی ستینگ") or t.startswith("ستینگ کپی") or t.startswith("اعمال ستینگ"):
        return "copy_settings", premium.PLAN_GOLD
    if "ضد رید" in t or "آنتی رید" in t:
        return "anti_raid", premium.PLAN_GOLD
    if "هوش مصنوعی" in t or "ai سخنگو" in t.casefold() or "سخنگو ai" in t.casefold():
        return "ai_speaker", premium.PLAN_GOLD
    if t in {"گزارش هفتگی"}:
        return "weekly_report", premium.PLAN_DIAMOND
    if t.startswith("زیرنظر") or t.startswith("حذف زیرنظر") or t.startswith("گزارش زیرنظر") or t in {"وضعیت واچ لیست", "لیست زیرنظر"}:
        return "watch_list", premium.PLAN_DIAMOND
    if t == "سلامت گروه":
        return "group_health", premium.PLAN_DIAMOND
    if "مدیریت هوشمند" in t or "اتو مودریشن" in t or "auto moderation" in t.casefold():
        return "auto_moderation", premium.PLAN_DIAMOND
    return None, premium.PLAN_FREE


