async def handle_group_public_instant_command(event: Any, group_id: int) -> bool:
    """Run the public command lane with an isolated reply-to source id."""
    message_id = safe_int(getattr(event, "id", None))
    reply_context = (int(group_id), int(message_id)) if message_id else None
    token = _group_command_reply_to.set(reply_context)
    priority_token = _group_response_priority.set(group_response_priority(group_id))
    try:
        return await _handle_group_public_instant_command_impl(event, group_id)
    finally:
        _group_response_priority.reset(priority_token)
        _group_command_reply_to.reset(token)


async def handle_group_commands(event: Any) -> bool:
    """Run every group command so all produced messages reply to the command."""
    message_id = safe_int(getattr(event, "id", None))
    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    reply_context = (int(group_id), int(message_id)) if group_id is not None and message_id else None
    token = _group_command_reply_to.set(reply_context)
    priority_token = _group_response_priority.set(group_response_priority(group_id))
    try:
        return await _handle_group_commands_impl(event)
    finally:
        _group_response_priority.reset(priority_token)
        _group_command_reply_to.reset(token)


async def wait_for_group_creator(group: Any, attempts: int = 5) -> Optional[Any]:
    for attempt in range(max(1, int(attempts))):
        try:
            creator = await find_group_creator(group)
            if creator is not None and safe_int(getattr(creator, "id", None)):
                return creator
        except Exception as exc:
            log.debug(
                "group creator resolve retry | group=%s attempt=%s | %s: %s",
                getattr(group, "id", "?"), attempt + 1, type(exc).__name__, exc,
            )
        if attempt + 1 < attempts:
            await asyncio.sleep(0.8 + attempt * 0.25)
    return None


async def wait_for_group_admin_access(group: Any, attempts: int = 6) -> Dict[str, Any]:
    last: Dict[str, Any] = {}
    for attempt in range(max(1, int(attempts))):
        try:
            last = await activation_admin_state(group)
        except Exception as exc:
            last = {"admin": False, "creator": False, "rights_active": False, "source": f"error:{type(exc).__name__}"}
        if bool(last.get("admin")) or bool(last.get("creator")):
            return last
        if attempt + 1 < attempts:
            await asyncio.sleep(1.0 + (attempt * 0.25))
    return last


async def handle_group_install_command(event: Any) -> bool:
    """Handle explicit owner installation from inside a Soroush group."""
    if bool(getattr(event, "is_private", False)):
        return False

    text = normalize_group_command(getattr(event, "raw_text", None) or "")
    if text not in GROUP_INSTALL_ROUTER_COMMANDS:
        return False

    try:
        group = await event.get_chat()
    except Exception as exc:
        log.warning(
            "manual install chat resolve failed | %s: %s",
            type(exc).__name__,
            exc,
        )
        return True

    if not is_group_entity(group):
        return False

    group_id = safe_int(getattr(group, "id", None))
    sender_id = safe_int(getattr(event, "sender_id", None))
    if group_id is None or sender_id is None:
        log.warning(
            "manual install missing ids | group=%s sender=%s",
            group_id,
            sender_id,
        )
        return True

    existing_installation = get_installation(group_id)
    pending_activation = get_pending_group_activation(group_id)
    if text in PENDING_GROUP_ACTIVATION_COMMANDS and existing_installation is not None:
        return False

    # 60.96.18: native admin is no longer an installation prerequisite.
    # Installation/command routing is based on real group presence. If ZIVO is
    # admin, full destructive management is available; otherwise the group runs
    # in BASIC mode and non-destructive features remain usable.
    access = await runtime_group_access_state(group, force=True)
    log.info(
        "manual install runtime access | group=%s sender=%s mode=%s admin=%s creator=%s source=%s",
        group_id, sender_id, access.get("mode"), bool(access.get("admin")),
        bool(access.get("creator")), access.get("source"),
    )

    if text in (EMERGENCY_INSTALL_START_COMMANDS | EMERGENCY_INSTALL_CONFIRM_COMMANDS | EMERGENCY_INSTALL_CANCEL_COMMANDS):
        handled = await handle_emergency_install_command(
            event, group, int(group_id), text
        )
        if get_installation(group_id) is not None:
            meta = await get_group_metadata(group)
            mark_group_activated(group, group_id, meta["title"])
        return handled

    creator = await wait_for_group_creator(group)
    creator_id = safe_int(getattr(creator, "id", None)) if creator is not None else None

    if creator_id is None:
        await send_group_text(
            group,
            (
                "⚠️ ZIVO | مالک گروه تأیید نشد\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "زیوو نتونست مالک اصلی گروه رو از سروش تأیید کنه.\n"
                "زیوو چند لحظه بعد دوباره وضعیت مالک رو خودش بررسی می کنه.\n"
                "اگر ادامه داشت، دسترسی ادمین زیوو رو یک‌بار بررسی کن.\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "🤖 ZIVO | INSTALL"
            ),
        )
        log.warning(
            "manual install rejected | group=%s sender=%s reason=creator_unresolved",
            group_id,
            sender_id,
        )
        return True

    if sender_id != creator_id:
        await send_group_text(
            group,
            (
                "⛔ ZIVO | اجازه نصب نداری\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "فقط مالک اصلی همین گروه می‌تونه نصب اولیه زیوو رو انجام بده.\n"
                "━━━━━━━━━━━━━━━━━━\n"
                "🔐 ZIVO | SECURITY"
            ),
        )
        log.info(
            "manual install rejected | group=%s sender=%s creator=%s reason=not_creator",
            group_id,
            sender_id,
            creator_id,
        )
        return True

    existing = get_installation(group_id)
    if existing is not None:
        clear_pending_group_activation(group_id)
        meta = await get_group_metadata(group)
        mark_group_activated(group, group_id, meta["title"])
        await sync_native_group_admins(group, group_id, force=True)
        try:
            await send_activation_message(group, existing)
        except Exception:
            log.exception(
                "manual reinstall activation card failed | group=%s owner=%s",
                group_id,
                int(existing["owner_user_id"]),
            )
            await send_group_text(
                group,
                (
                    "✅ ZIVO | این گروه قبلاً نصب شده\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "ثبت گروه در دیتابیس زیوو فعاله.\n"
                    "برای دیدن وضعیت بنویس: ربات\n"
                    "━━━━━━━━━━━━━━━━━━\n"
                    "🤖 ZIVO | ACTIVE"
                ),
            )
        return True

    owner_username = getattr(creator, "username", None) or ""
    owner_access_hash = safe_int(getattr(creator, "access_hash", None)) or 0
    group_title = str(getattr(group, "title", None) or "")

    # Local readiness and the restart-safe activation card are one transaction.
    installation = register_installation(
        group_id=group_id,
        group_title=group_title,
        owner_user_id=creator_id,
        owner_username=owner_username,
        owner_access_hash=owner_access_hash,
        install_source="manual_owner_command",
        native_owner_user_id=creator_id,
        native_owner_username=owner_username,
        native_owner_access_hash=owner_access_hash,
        owner_mode="native",
        introduced_by_user_id=creator_id,
        introduced_by_username=owner_username,
        activation_card={
            "owner_id": int(creator_id),
            "owner_access_hash": int(owner_access_hash),
            "native_owner_id": int(creator_id),
            "native_owner_available": True,
            "owner_mode": "native",
            "probe_already_sent": False,
            "group_title": group_title,
            "peer_kind": "chat" if isinstance(group, types.Chat) else "channel",
            "group_access_hash": int(getattr(group, "access_hash", 0) or 0),
        },
    )
    mark_group_activated(group, group_id, group_title)
    clear_pending_group_activation(group_id)
    asyncio.create_task(
        _post_activation_card_task(
            group, int(group_id), int(creator_id), int(owner_access_hash),
            int(creator_id), True, "native",
            already_persisted=True,
        ),
        name=f"zivo-manual-activation-card-{group_id}",
    )
    asyncio.create_task(
        _post_activation_admin_sync_task(group, int(group_id)),
        name=f"zivo-manual-admin-sync-{group_id}",
    )

    log.info(
        "manual owner install completed | group=%s owner=%s source=manual_owner_command local_ready=1 card=background",
        group_id, creator_id,
    )
    return True


async def runtime_group_access_state(group: Any, force: bool = False) -> Dict[str, Any]:
    """Return the current account's native Soroush authority for one group.

    FULL means ZIVO is a native admin/creator and destructive moderation can be
    attempted. BASIC means ZIVO is only a normal member; public/internal ZIVO
    features continue to work, while delete/ban/pin actions require promotion.
    """
    gid = safe_int(getattr(group, "id", None))
    if gid is None:
        return {"mode": "basic", "admin": False, "creator": False, "rights_active": False, "source": "group_id_missing"}
    now = time.monotonic()
    cached = _runtime_group_access_hot.get(int(gid))
    if not force and cached is not None and (now - float(cached[0])) < RUNTIME_GROUP_ACCESS_TTL:
        return dict(cached[1])
    state: Dict[str, Any]
    try:
        state = await asyncio.wait_for(activation_admin_state(group), timeout=RUNTIME_GROUP_AUTHORITY_TIMEOUT)
    except Exception as exc:
        state = {
            "admin": False,
            "creator": False,
            "rights_active": False,
            "source": f"probe_error:{type(exc).__name__}",
        }
    state = dict(state or {})
    state["admin"] = bool(state.get("admin"))
    state["creator"] = bool(state.get("creator"))
    state["mode"] = "full" if state["admin"] or state["creator"] else "basic"
    _runtime_group_access_hot[int(gid)] = (now, dict(state))
    log.info(
        "runtime group access | group=%s account=%s mode=%s admin=%s creator=%s source=%s",
        int(gid), ACCOUNT_KEY, state["mode"], state["admin"], state["creator"], state.get("source", ""),
    )
    return state


async def ensure_runtime_actor_authority(event: Any, group: Any, group_id: int) -> str:
    """Lazily import a real Soroush creator/admin into ZIVO roles.

    This is intentionally used only on command traffic. It repairs wiped/local
    databases without trusting the command sender blindly: Soroush must prove
    creator/admin status first.
    """
    sender_id = safe_int(getattr(event, "sender_id", None))
    if sender_id is None or sender_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        return ""
    current = base_bot_role(int(group_id), int(sender_id))
    if role_level(current) >= 2:
        return current
    input_sender = getattr(event, "input_sender", None)
    access_hash = int(input_peer_access_hash(input_sender) or 0)
    try:
        verified, source, is_creator = await asyncio.wait_for(
            _verified_requester_admin_from_group(group, int(sender_id), access_hash),
            timeout=RUNTIME_GROUP_AUTHORITY_TIMEOUT + 2.0,
        )
    except Exception as exc:
        log.debug(
            "runtime actor direct authority probe skipped | group=%s user=%s | %s: %s",
            group_id, sender_id, type(exc).__name__, exc,
        )
        verified, source, is_creator = None, "direct_probe_error", False

    # 60.96.19: Soroush returns NOT_SUPPORTED for channels.GetParticipant
    # in a number of otherwise healthy groups.  Do not lose role-management
    # authority because of that endpoint.  Fall back to the native admin list,
    # which is the same authoritative source used by periodic admin sync.
    if verified is None:
        try:
            broad = await asyncio.wait_for(
                _native_admin_for_user(group, int(sender_id)),
                timeout=RUNTIME_GROUP_AUTHORITY_TIMEOUT + 5.0,
            )
        except Exception as exc:
            log.debug(
                "runtime actor admin-list fallback skipped | group=%s user=%s | %s: %s",
                group_id, sender_id, type(exc).__name__, exc,
            )
            broad = None
        if broad is not None:
            participant = getattr(broad, "participant", None)
            is_creator = isinstance(
                participant,
                (types.ChannelParticipantCreator, types.ChatParticipantCreator),
            )
            verified = broad
            source = "admin_list_creator" if is_creator else "admin_list_admin"
            log.info(
                "runtime actor authority fallback PASS | group=%s user=%s source=%s",
                group_id, sender_id, source,
            )

    if verified is None:
        return current
    username = str(getattr(verified, "username", None) or "")
    verified_hash = int(safe_int(getattr(verified, "access_hash", None)) or access_hash or 0)
    if is_creator:
        installation = get_installation(int(group_id))
        if installation is not None:
            stored_owner = int(installation["owner_user_id"] or 0)
            native_owner = int(installation["native_owner_user_id"] or 0) if "native_owner_user_id" in installation.keys() else 0
            owner_mode = str(installation["owner_mode"] or "") if "owner_mode" in installation.keys() else ""
            if stored_owner == 0 or native_owner in {0, int(sender_id)} or owner_mode in {"executive", "runtime"}:
                try:
                    reclaim_bot_ownership_for_real_group_owner(
                        int(group_id), int(sender_id), username, verified_hash,
                    )
                except Exception:
                    with db_connect() as con:
                        con.execute(
                            "UPDATE installations SET owner_user_id=?, owner_username=?, owner_access_hash=?, native_owner_user_id=?, native_owner_username=?, native_owner_access_hash=?, owner_mode='native' WHERE group_id=?",
                            (int(sender_id), username, verified_hash, int(sender_id), username, verified_hash, int(group_id)),
                        )
                        con.commit()
                    invalidate_group_hot_caches(int(group_id))
                    refresh_role_membership_cache(int(group_id))
                log.info("runtime creator authority restored | group=%s user=%s source=%s", group_id, sender_id, source)
                return base_bot_role(int(group_id), int(sender_id))
    upsert_bot_admin(
        int(group_id), int(sender_id), username, verified_hash,
        int(get_installation(int(group_id))["owner_user_id"] or 0) if get_installation(int(group_id)) is not None else 0,
        source="native",
    )
    log.info("runtime native admin imported | group=%s user=%s source=%s", group_id, sender_id, source)
    return base_bot_role(int(group_id), int(sender_id))


async def runtime_bootstrap_group_from_event(event: Any) -> Optional[Any]:
    """Create a safe local installation from a real inbound group command.

    The bootstrap itself performs no participant/admin RPC. This keeps the first
    public command fast. owner=0 grants nobody management authority; native
    creator/admin authority is recovered lazily and only after Soroush proof.
    """
    if not RUNTIME_GROUP_BOOTSTRAP_ENABLED or bool(getattr(event, "is_private", False)):
        return None
    gid = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if gid is None:
        return None
    existing = get_installation(int(gid))
    if existing is not None:
        return existing
    if int(gid) in _runtime_group_bootstrap_inflight:
        return None
    _runtime_group_bootstrap_inflight.add(int(gid))
    try:
        try:
            group = await event.get_chat()
        except Exception:
            return None
        if not is_group_entity(group) or bool(getattr(group, "broadcast", False)):
            return None
        group_title = str(getattr(group, "title", None) or "")
        now = datetime.now(timezone.utc).isoformat()
        peer_kind = "chat" if isinstance(group, types.Chat) else "channel"
        group_access_hash = int(getattr(group, "access_hash", 0) or 0)
        # Direct insertion intentionally avoids register_installation(), because
        # normal-member BASIC mode must not auto-enable destructive default locks.
        with db_connect() as con:
            con.execute(
                """
                INSERT OR IGNORE INTO installations(
                    group_id, group_title, owner_user_id, owner_username,
                    owner_access_hash, invite_hash, install_source,
                    default_locks_json, installed_at, native_owner_user_id,
                    native_owner_username, native_owner_access_hash, owner_mode
                ) VALUES (?, ?, 0, '', 0, '', ?, '[]', ?, 0, '', 0, 'executive')
                """,
                (int(gid), group_title, f"runtime-presence:{ACCOUNT_KEY}", now),
            )
            _group_lifecycle_upsert_in_connection(
                con, int(gid), group_title, peer_kind, group_access_hash, now=now,
            )
            con.commit()
        invalidate_group_hot_caches(int(gid))
        refresh_role_membership_cache(int(gid))
        clear_pending_group_activation(int(gid))
        try:
            multi_set_group_claim_status(
                MULTI_ACCOUNT_DB, group_id=int(gid), account_key=ACCOUNT_KEY,
                status="active", group_title=group_title,
            )
        except Exception:
            pass
        # Enrichment is asynchronous. A privileged command from a native
        # creator/admin also invokes ensure_runtime_actor_authority() before the
        # command handler, so management works on the first such command.
        asyncio.create_task(sync_native_group_admins(group, int(gid), force=True), name=f"zivo-runtime-admin-sync-{gid}")
        asyncio.create_task(reconcile_native_owner_authority(group, int(gid), force=True), name=f"zivo-runtime-owner-sync-{gid}")
        asyncio.create_task(runtime_group_access_state(group, force=True), name=f"zivo-runtime-access-{gid}")
        log.warning(
            "runtime group bootstrap PASS | group=%s account=%s owner=0 mode=pending-authority locks=off",
            gid, ACCOUNT_KEY,
        )
        return get_installation(int(gid))
    finally:
        _runtime_group_bootstrap_inflight.discard(int(gid))


async def require_native_admin_for_destructive_action(group: Any, action_label: str) -> bool:
    """Friendly guard for actions that Soroush only allows native admins."""
    state = await runtime_group_access_state(group, force=False)
    if str(state.get("mode")) == "full":
        return True
    if str(state.get("source") or "").startswith("probe_error:"):
        return True
    runtime_notice = bytes.fromhex("").decode("utf-8")
    await send_group_text(group, runtime_notice)
    return False


async def maybe_auto_install_admin_group(event: Any) -> None:
    """Legacy pending discovery for ordinary chatter; command traffic uses 96.18 runtime bootstrap."""
    if bool(getattr(event, "is_private", False)):
        return

    try:
        group = await event.get_chat()
    except Exception:
        return
    if not is_group_entity(group) or bool(getattr(group, "broadcast", False)):
        return

    group_id = safe_int(getattr(group, "id", None))
    if group_id is None or get_installation(group_id) is not None:
        return
    if get_pending_group_activation(group_id) is not None:
        return

    async with AUTO_GROUP_INSTALL_LOCK:
        if get_installation(group_id) is not None or get_pending_group_activation(group_id) is not None:
            return
        group_title = str(getattr(group, "title", None) or "بدون نام")
        pending = register_pending_group_activation(
            group=group,
            group_title=group_title,
            requester_user_id=0,
            requester_access_hash=0,
            install_source="observed_uninstalled_group",
            invite_ref="",
        )
        # Pending is not ACTIVE. Never show the classic activation card until
        # the real owner completes installation and admin/send access is proven.
        mark_pending_join_notice_sent(group_id)
        log.info(
            "pending activation auto-registered | group=%s deadline=%s",
            group_id,
            pending["activation_deadline"],
        )


def increment_deleted_message_counter(group_id: int, amount: int = 1) -> None:
    amount = max(0, int(amount))
    if amount == 0:
        return
    with db_connect() as con:
        con.execute(
            """
            INSERT INTO stats_group_counters (group_id, muted_users, deleted_messages)
            VALUES (?, 0, ?)
            ON CONFLICT(group_id) DO UPDATE SET
                deleted_messages = deleted_messages + excluded.deleted_messages
            """,
            (int(group_id), amount),
        )
        con.commit()


async def maybe_delete_warning_capped_message(event: Any) -> bool:
    if bool(getattr(event, "is_private", False)):
        return False
    sender_id = safe_int(getattr(event, "sender_id", None))
    message_id = safe_int(getattr(event, "id", None))
    if sender_id is None or message_id is None or sender_id in {SELF_USER_ID, *SYSTEM_USER_IDS}:
        return False

    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if group_id is None or get_installation(group_id) is None:
        return False

    # Command/control roles must never have their messages swallowed by the
    # legacy warning-cap cleanup gate. Lock exemptions already use the same rule.
    if lock_user_is_exempt(
        group_id,
        sender_id,
    ):
        return False

    policy = effective_warning_policy(
        group_id,
        sender_id,
    )
    if policy["action_mode"] != "delete":
        return False

    warnings = manual_warning_count(group_id, sender_id)
    maximum = int(policy["effective_max_warnings"])
    if warnings < maximum:
        return False

    try:
        group = await event.get_chat()
    except Exception:
        return False
    if not isinstance(group, types.Channel):
        return False

    try:
        await governed_delete_messages(
            group,
            int(message_id),
            timeout=12,
            lane="warning-cap",
        )
        increment_deleted_message_counter(group_id, 1)
        log.info(
            "warning-cap message deleted | group=%s user=%s message=%s warnings=%s max=%s",
            group_id, sender_id, message_id, warnings, maximum,
        )
        return True
    except Exception as exc:
        log.warning(
            "warning-cap delete failed | group=%s user=%s message=%s | %s: %s",
            group_id, sender_id, message_id, type(exc).__name__, exc,
        )
        return False


async def consume_disabled_group_event(
    event: Any,
) -> bool:
    """
    When ZIVO is off for an installed group, swallow the entire group pipeline.

    The only surviving paths are:
      - owner activation: فعال / ربات فعال (+ timed variants)
      - owner recovery: برسی مالک / بررسی مالک

    This runs before warning deletion, statistics and command routing so locks,
    stats and normal commands do not execute while the group core is off.
    """
    if bool(
        getattr(
            event,
            "is_private",
            False,
        )
    ):
        return False

    group_id = canonical_anti_spam_group_id(getattr(event, "chat_id", None))
    if group_id is None or get_installation(group_id) is None:
        return False
    if is_group_bot_enabled(group_id):
        return False

    try:
        group = await event.get_chat()
    except Exception:
        return True
    if not is_group_entity(group):
        return True

    text = normalize_group_command(
        getattr(
            event,
            "raw_text",
            None,
        )
        or ""
    )

    power = parse_bot_power_command(
        text
    )

    if (
        power is not None
        and is_bot_activation_text(text)
    ):
        await handle_group_commands(
            event
        )
        return True

    if is_bot_call_text(text) or text in BOT_STATUS_COMMANDS:
        await send_group_text(
            group,
            "🟠 زیوو در این گروه فعلاً خاموشه.\n\n"
            "👑 مالک گروه برای روشن کردن بنویسه: فعال\n\n"
            + ux_navigation_footer(),
        )
        return True

    if text in BOT_COMMAND_LIST_COMMANDS:
        await command_direct_command_list(group)
        return True

    if text in BOT_HELP_COMMANDS or text.startswith("راهنما "):
        if text.startswith("راهنما "):
            feature = find_help_feature_fuzzy(text)
            actor_id = safe_int(getattr(event, "sender_id", None))
            if help_feature_visible_for_actor(feature, actor_id):
                topic_text, topic_commands = capability_topic_text(feature)
                await send_copyable_command_text(group, topic_text, topic_commands)
            else:
                await command_help_center(group)
        else:
            await command_help_center(group)
        return True

    if text in {
        "برسی مالک",
        "بررسی مالک",
    }:
        await handle_group_commands(
            event
        )
        return True

    return True


async def _promote_pending_group_after_write(group: Any, group_id: int, trigger: str) -> bool:
    gid = int(group_id)
    row = get_pending_group_activation(gid)
    if row is None:
        return get_installation(gid) is not None
    _join_notice_entity_cache[gid] = group
    _pending_dialog_entity_cache[gid] = group
    _group_send_probe_retry_after.pop(gid, None)
    try:
        await asyncio.to_thread(_group_join_notice_mark_probe, gid)
        row = get_pending_group_activation(gid)
        if row is None:
            return get_installation(gid) is not None
        activated = await try_auto_activate_pending_group(
            row, group_override=group, trigger=trigger, deliver_card_inline=True
        )
        if activated and get_installation(gid) is not None:
            await asyncio.to_thread(_group_join_notice_complete, gid)
            log.info("pending command activation PASS | group=%s trigger=%s", gid, trigger)
            return True
    except Exception as exc:
        log.info("pending command activation deferred | group=%s trigger=%s | %s: %s", gid, trigger, type(exc).__name__, exc)
    return get_installation(gid) is not None


async def handle_pending_group_ux(event: Any) -> bool:
    if bool(getattr(event, "is_private", False)):
        return False
    text = normalize_group_command(getattr(event, "raw_text", None) or "")
    if not text:
        return False
    try:
        group = await event.get_chat()
    except Exception:
        return False
    if not is_group_entity(group):
        return False
    group_id = safe_int(getattr(group, "id", None))
    if group_id is None or get_installation(group_id) is not None:
        return False
    if get_pending_group_activation(group_id) is None:
        return False

    visible_reply_sent = False
    if is_bot_call_text(text):
        await send_group_text(
            group,
            "👀\n\n🤖 زیوو اینجاست و گروه رو می‌بینه.\n"
            "⚙️ وقتی دسترسی ادمین آماده بشه، زیوو خودش فعال می‌شه و کارت اصلی رو می‌فرسته.\n\n"
            + ux_navigation_footer(),
        )
        visible_reply_sent = True
    elif text in BOT_COMMAND_LIST_COMMANDS:
        await command_direct_command_list(group)
        visible_reply_sent = True
    elif text in BOT_HELP_COMMANDS:
        await command_help_center(group)
        visible_reply_sent = True
    elif text in BOT_START_GUIDE_COMMANDS:
        await command_start_guide(group)
        visible_reply_sent = True
    elif text.startswith("راهنما "):
        feature = find_help_feature_fuzzy(text)
        actor_id = safe_int(getattr(event, "sender_id", None))
        if help_feature_visible_for_actor(feature, actor_id):
            topic_text, topic_commands = capability_topic_text(feature)
            await send_copyable_command_text(group, topic_text, topic_commands)
        else:
            await command_help_center(group)
        visible_reply_sent = True

    if visible_reply_sent:
        # A successful visible reply is stronger evidence than the stale join
        # probe: this process can write to this exact group right now. Persist
        # that fact and immediately finish activation instead of leaving the
        # group in help-only pending mode.
        await _promote_pending_group_after_write(group, int(group_id), "pending-visible-reply")
        return True

    # Management commands in a freshly joined group used to be silently lost
    # while the durable write probe was in backoff. Give the first real command
    # one bounded foreground probe, activate locally, then execute that same
    # event through the normal role-checked router.
    command_candidate = looks_like_priority_group_command(text, safe_int(getattr(event, "sender_id", None)))
    if not command_candidate:
        try:
            command_candidate = private_command_requires_group(text)
        except Exception:
            command_candidate = False
    if not command_candidate and parse_speaker_command(text) is not None:
        command_candidate = True
    if not command_candidate:
        return False

    _group_send_probe_retry_after.pop(int(group_id), None)
    try:
        confirmed = await asyncio.wait_for(
            probe_group_send_access(group, marker="👀"),
            timeout=6.5,
        )
    except Exception as exc:
        log.info("pending command write probe deferred | group=%s | %s: %s", group_id, type(exc).__name__, exc)
        return False
    if not confirmed:
        return False
    if not await _promote_pending_group_after_write(group, int(group_id), "pending-command"):
        return False
    if await handle_group_commands(event):
        log.info("pending command replay PASS | group=%s text_head=%s", group_id, text.split(" ", 1)[0])
        return True
    return False


def private_command_requires_group(text: str) -> bool:
    normalized = normalize_group_command(text)
    if not normalized:
        return False
    if parse_auto_stats_command(normalized) is not None:
        return True

    if (
        parse_manual_moderation_command(normalized) is not None
        or parse_warning_view_command(normalized) is not None
        or parse_pin_command(normalized) is not None
        or parse_group_close_command(normalized) is not None
        or parse_bot_power_command(normalized) is not None
        or parse_cleanup_command(normalized) is not None
        or parse_full_cleanup_command(normalized) is not None
        or parse_cleanup_schedule_command(normalized) is not None
        or parse_group_lock_command(normalized) is not None
        or parse_exact_content_filter_command(normalized) is not None
        or parse_word_filter_command(normalized) is not None
        or parse_anti_spam_command(normalized) is not None
        or parse_group_backup_command(normalized) is not None
        or parse_settings_copy_command(normalized) is not None
        or parse_rules_command(normalized) is not None
        or parse_welcome_command(normalized) is not None
        or parse_special_access_command(normalized) is not None
        or parse_ban_audit_command(normalized) is not None
    ):
        return True

    group_only_exact = {
        "مقام", "مقامش", "عزل", "مالک", "انتقال مالکیت",
        "برسی مالک", "بررسی مالک", "ادمین", "تنظیم ادمین",
        "ویژه", "تنظیم ویژه", "معاف", "تنظیم معاف",
        "حذف معاف", "حذف معافیت",
        "آمار", "امار", "آمارش", "امارش",
        "آمار معاف ها", "امار معاف ها", "آمار معافان", "امار معافان",
        "آمار ویژه ها", "امار ویژه ها", "آمار ادمین ها", "امار ادمین ها",
        "آمار ادمینها", "امار ادمینها", "آمار گپ", "امار گپ",
        "آمار خودکار", "امار خودکار", "آمار خودکار فعال", "امار خودکار فعال",
        "آمار خودکار خاموش", "امار خودکار خاموش", "وضعیت آمار خودکار", "وضعیت امار خودکار",
        "تست ویس", "همگام سازی ادمین ها", "همگام‌سازی ادمین ها",
        "آمار گروه", "امار گروه", "رتبه بندی آمار", "رتبه بندی امار",
        *GROUP_INSTALL_COMMANDS,
        *EMERGENCY_INSTALL_START_COMMANDS,
        *EMERGENCY_INSTALL_CONFIRM_COMMANDS,
        *EMERGENCY_INSTALL_CANCEL_COMMANDS,
    }
    return normalized in group_only_exact


def _private_link_content_key(sender_id: int, link_kind: str, link_value: str) -> Tuple[int, str, str]:
    kind = str(link_kind or "").strip().lower()
    value = str(link_value or "").strip()
    if kind == "public":
        value = value.lower().lstrip("@")
    return (int(sender_id), kind, value)


LEGACY_PRIVATE_JOIN_FALSE_FAILURE_TEXT = (
    "❌ عضویت گروه کامل تأیید نشد. لینک گروه رو دوباره بررسی کن و یک بار دیگه بفرست."
)


def _legacy_join_notice_already_sent(user_id: int) -> bool:
    try:
        with db_connect() as con:
            row = con.execute(
                "SELECT 1 FROM private_join_legacy_notice_v89 WHERE user_id=? LIMIT 1",
                (int(user_id),),
            ).fetchone()
        return row is not None
    except Exception:
        return False


def _mark_legacy_join_notice_sent(user_id: int, source_message_id: int, group_id: int) -> None:
    try:
        with db_connect() as con:
            con.execute(
                """
                INSERT OR IGNORE INTO private_join_legacy_notice_v89
                    (user_id, source_message_id, group_id, sent_at)
                VALUES (?, ?, ?, ?)
                """,
                (
                    int(user_id), int(source_message_id or 0), int(group_id or 0),
                    datetime.now(timezone.utc).isoformat(),
                ),
            )
            con.commit()
    except Exception:
        pass


def _legacy_join_error_text_matches(text: str) -> bool:
    left = " ".join(str(text or "").replace("\u200c", " ").replace("ي", "ی").replace("ك", "ک").split())
    right = " ".join(LEGACY_PRIVATE_JOIN_FALSE_FAILURE_TEXT.replace("\u200c", " ").split())
    return left == right


def _legacy_join_probe_status(user_id: int, source_message_id: int) -> str:
    try:
        with db_connect() as con:
            row = con.execute(
                "SELECT status FROM private_join_legacy_probe_v91 WHERE user_id=? AND source_message_id=? LIMIT 1",
                (int(user_id), int(source_message_id)),
            ).fetchone()
        return str(row["status"] or "") if row is not None else ""
    except Exception:
        return ""


def _mark_legacy_join_probe(
    user_id: int, source_message_id: int, status: str, error_text: str = "",
) -> None:
    try:
        with db_connect() as con:
            con.execute(
                """
                INSERT INTO private_join_legacy_probe_v91
                    (user_id, source_message_id, status, last_error, checked_at)
                VALUES (?, ?, ?, ?, ?)
                ON CONFLICT(user_id, source_message_id) DO UPDATE SET
                    status=excluded.status, last_error=excluded.last_error, checked_at=excluded.checked_at
                """,
                (
                    int(user_id), int(source_message_id), str(status or "")[:40],
                    str(error_text or "")[:500], datetime.now(timezone.utc).isoformat(),
                ),
            )
            con.commit()
    except Exception:
        pass


async def _legacy_false_failure_was_actually_sent(
    target: Any, user_id: int, source_message_id: int,
) -> bool:
    """Only legacy recipients of the exact false-failure reply are repair targets."""
    if _legacy_join_notice_already_sent(int(user_id)):
        return False
    probe_status = _legacy_join_probe_status(int(user_id), int(source_message_id))
    if probe_status == "matched":
        return True
    if probe_status in {"unavailable", "checked_no_match"}:
        return False
    batches: List[Any] = []
    try:
        if int(source_message_id or 0) > 0:
            try:
                around = await asyncio.wait_for(
                    client.get_messages(
                        target, limit=40, min_id=max(0, int(source_message_id) - 1)
                    ),
                    timeout=5.0,
                )
                batches.extend(list(around or []))
            except (TypeError, ValueError):
                pass
        if not batches:
            recent = await asyncio.wait_for(client.get_messages(target, limit=40), timeout=5.0)
            batches.extend(list(recent or []))
    except Exception as exc:
        detail = f"{type(exc).__name__}: {exc}"
        upper = detail.upper()
        terminal = any(token in upper for token in (
            "NOT_FOUND", "CHANNELPRIVATE", "CHANNEL_PRIVATE",
            "PEER_ID_INVALID", "USER_DEACTIVATED", "AUTH_KEY_UNREGISTERED",
        ))
        if terminal:
            _mark_legacy_join_probe(user_id, source_message_id, "unavailable", detail)
        log.info(
            "legacy false-failure evidence unavailable | user=%s message=%s terminal=%s | %s",
            user_id, source_message_id, int(terminal), detail,
        )
        return False
    for msg in batches:
        msg_id = safe_int(getattr(msg, "id", None)) or 0
        if int(source_message_id or 0) > 0 and msg_id and msg_id < int(source_message_id):
            continue
        outgoing = bool(getattr(msg, "out", False)) or safe_int(getattr(msg, "sender_id", None)) == SELF_USER_ID
        if not outgoing:
            continue
        raw = str(getattr(msg, "raw_text", None) or getattr(msg, "message", None) or "")
        if _legacy_join_error_text_matches(raw):
            _mark_legacy_join_probe(user_id, source_message_id, "matched")
            log.info(
                "legacy false-failure evidence PASS | user=%s source_message=%s error_message=%s",
                user_id, source_message_id, msg_id,
            )
            return True
    _mark_legacy_join_probe(user_id, source_message_id, "checked_no_match")
    return False


def _private_join_apology_already_sent(user_id: int, message_id: int) -> bool:
    try:
        with db_connect() as con:
            row = con.execute(
                "SELECT 1 FROM private_join_apology_v87 WHERE user_id=? AND message_id=? LIMIT 1",
                (int(user_id), int(message_id)),
            ).fetchone()
        return row is not None
    except Exception:
        return False


def _mark_private_join_apology_sent(
    user_id: int, message_id: int, link_kind: str, link_value: str
) -> None:
    try:
        with db_connect() as con:
            con.execute(
                """
                INSERT OR REPLACE INTO private_join_apology_v87
                    (user_id, message_id, link_kind, link_value, sent_at)
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    int(user_id), int(message_id), str(link_kind or ''),
                    str(link_value or '')[:500], datetime.now(timezone.utc).isoformat(),
                ),
            )
            con.commit()
    except Exception:
        pass


