def multi_account_db_counts(row: sqlite3.Row) -> Dict[str, int]:
    result = {"groups": 0, "private_total": 0, "private_enabled": 0}
    db_path = Path(str(row["db_path"] or ""))
    if not db_path.is_file():
        return result
    try:
        con = sqlite3.connect(db_path, timeout=2.0)
        try:
            group_ids = [int(r[0]) for r in con.execute("SELECT group_id FROM installations WHERE group_id>0").fetchall()]
            account_key = str(row["account_key"] or "").strip().lower() if "account_key" in row.keys() else ""
            owner_map = _shared_group_claim_owner_map(group_ids)
            result["groups"] = sum(1 for gid in group_ids if not owner_map.get(gid) or owner_map.get(gid) == account_key)
            result["private_total"] = int(con.execute("SELECT COUNT(*) FROM private_contacts").fetchone()[0] or 0)
            result["private_enabled"] = int(con.execute("SELECT COUNT(*) FROM private_contacts WHERE can_broadcast = 1").fetchone()[0] or 0)
        finally:
            con.close()
    except Exception:
        pass
    return result


def multi_selected_account_rows(target: str, *, active_only: bool = True) -> List[sqlite3.Row]:
    rows = multi_account_rows()
    if target == "all":
        return [row for row in rows if (not active_only or bool(int(row["enabled"] or 0)))]
    return [row for row in rows if str(row["account_key"]) == str(target) and (not active_only or bool(int(row["enabled"] or 0)))]


def multi_campaign_target_count(target: str, scope: str) -> int:
    total = 0
    for row in multi_selected_account_rows(target):
        counts = multi_account_db_counts(row)
        if scope in {"groups", "both"}:
            total += counts["groups"]
        if scope in {"private", "both"}:
            total += counts["private_enabled"]
    return total


