def premium_wallet_user_text(user_id: int) -> str:
    uid = int(user_id or 0)
    detail = premium.wallet_account_detail(uid, 8) or {}
    user = dict(detail.get("user") or premium.official_user_state(uid))
    balance = int(detail.get("balance_rial") or premium.wallet_balance(uid))
    rows = list(detail.get("ledger") or premium.wallet_ledger(uid, 8))
    first_name = str(user.get("first_name") or "").strip() or "—"
    username = str(user.get("username") or "").strip().lstrip("@")
    lines = [
        "💼 کیف پول کاربر",
        "",
        f"User ID: {uid}",
        f"نام: {first_name}",
        f"Username: @{username}" if username else "Username: —",
        f"عضویت/شروع بات: {'بله' if user.get('seen') else 'خیر'}",
        f"موجودی: {premium.money_rial(balance)}",
    ]
    if rows:
        lines.extend(["", "آخرین گردش‌ها:"])
        for row in rows:
            delta = int(row.get("delta_rial") or 0)
            sign = "+" if delta > 0 else ""
            lines.append(
                f"• {sign}{delta:,} ریال | مانده {int(row.get('balance_after') or 0):,} | {row.get('reason') or row.get('source') or '—'}"
            )
    else:
        lines.extend(["", "هنوز گردش مالی ثبت نشده است."])
    return "\n".join(lines)

