def premium_prices_admin_text(plan: str = "") -> str:
    rows = premium.all_prices()
    lines = ["💰 قیمت پلن‌های ZIVO", "", "تمام مبلغ‌ها به ریال هستند."]
    for p in (premium.PLAN_SILVER, premium.PLAN_GOLD, premium.PLAN_DIAMOND):
        if plan and p != plan:
            continue
        lines.append(f"\n{premium.plan_label(p)}")
        for row in rows:
            if str(row.get("plan") or "") != p or int(row.get("duration_days") or 0) not in premium.DURATION_ORDER:
                continue
            state = "فعال" if int(row.get("enabled") or 0) else "خاموش"
            lines.append(
                f"• {premium.duration_label(row.get('duration_days'))}: "
                f"{premium.money_rial(row.get('amount_rial'))} ({premium.money_toman(row.get('amount_rial'))}) | {state}"
            )
    lines.append("\nبرای تغییر مبلغ، پلن و مدت را انتخاب کن و مبلغ جدید را فقط به ریال بفرست.")
    return "\n".join(lines)


