async def tg_api(method: str, payload: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    global _tg_http_session
    if not TELEGRAM_ADMIN_BOT_TOKEN:
        raise RuntimeError("TELEGRAM_TOKEN_MISSING")
    if _tg_http_session is None or _tg_http_session.closed:
        _tg_http_session = aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=45))
    url = f"https://api.telegram.org/bot{TELEGRAM_ADMIN_BOT_TOKEN}/{method}"
    async with _tg_http_session.post(url, json=payload or {}) as response:
        data = await response.json(content_type=None)
        if not bool(data.get("ok")):
            raise RuntimeError(f"TELEGRAM_API_{method}:{data.get('description') or response.status}")
        return data


async def tg_send_text(chat_id: int, text: str, keyboard: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    payload: Dict[str, Any] = {"chat_id": int(chat_id), "text": str(text)}
    if keyboard is not None:
        payload["reply_markup"] = keyboard
    data = await tg_api("sendMessage", payload)
    return dict(data.get("result") or {})



async def tg_send_photo_file(
    chat_id: int,
    file_path: str,
    caption: str = "",
    keyboard: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    global _tg_http_session
    path = Path(str(file_path))
    if not path.is_file():
        raise FileNotFoundError(str(path))
    if _tg_http_session is None or _tg_http_session.closed:
        _tg_http_session = aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=90))
    url = f"https://api.telegram.org/bot{TELEGRAM_ADMIN_BOT_TOKEN}/sendPhoto"
    form = aiohttp.FormData()
    form.add_field("chat_id", str(int(chat_id)))
    if caption:
        form.add_field("caption", str(caption)[:1024])
    if keyboard is not None:
        form.add_field("reply_markup", json.dumps(keyboard, ensure_ascii=False))
    with path.open("rb") as handle:
        form.add_field(
            "photo", handle,
            filename=path.name,
            content_type="image/jpeg" if path.suffix.lower() in {".jpg", ".jpeg"} else "application/octet-stream",
        )
        async with _tg_http_session.post(url, data=form) as response:
            data = await response.json(content_type=None)
    if not bool(data.get("ok")):
        raise RuntimeError(f"TELEGRAM_API_sendPhoto:{data.get('description') or 'unknown'}")
    return dict(data.get("result") or {})


async def telegram_notify_card_receipt(order: Dict[str, Any], user_id: int, path: str) -> None:
    profile = await asyncio.to_thread(get_global_user_profile, int(user_id))
    name = str(profile.get("nickname") or profile.get("preferred_name") or profile.get("name") or "کاربر").strip()
    username = str(profile.get("username") or "").strip().lstrip("@")
    oid = int(order.get("order_id") or 0)
    code = str(order.get("order_code") or f"#{oid}")
    kind = str(order.get("order_kind") or "subscription")
    lines = [
        "🧾 رسید کارت‌به‌کارت ZIVO",
        "",
        f"کد سفارش: {code}",
        f"نام: {name}",
        f"Username: @{username if username else '—'}",
        f"User ID: {int(user_id)}",
    ]
    if kind == "wallet_topup":
        lines.extend([
            "نوع: شارژ کیف پول ZIVO",
            f"مبلغ: {premium.money_rial(order.get('amount_rial'))}",
        ])
    else:
        lines.extend([
            f"گروه: {order.get('group_title') or order.get('group_id')}",
            f"Group ID: {int(order.get('group_id') or 0)}",
            f"پلن: {premium.plan_label(order.get('plan'))}",
            f"مدت: {premium.duration_label(order.get('duration_days'))}",
            f"مبلغ: {premium.money_rial(order.get('amount_rial'))}",
        ])
    lines.append("وضعیت: منتظر تأیید دستی")
    caption = "\n".join(lines)
    keyboard = {
        "inline_keyboard": [
            [tg_button("✅ تأیید", f"z:payapprove:{oid}", "success")],
            [tg_button("❌ رد رسید", f"z:payreject:{oid}", "danger")],
            [tg_button("💎 پنل پرمیوم", "z:premium", "primary")],
        ]
    }
    try:
        await tg_send_photo_file(TELEGRAM_ADMIN_ID, path, caption, keyboard)
    except Exception as exc:
        await tg_send_text(
            TELEGRAM_ADMIN_ID,
            caption + f"\n\n⚠️ ارسال عکس ناموفق بود: {type(exc).__name__}",
            keyboard,
        )


async def tg_edit_text(chat_id: int, message_id: int, text: str, keyboard: Optional[Dict[str, Any]] = None) -> None:
    payload: Dict[str, Any] = {"chat_id": int(chat_id), "message_id": int(message_id), "text": str(text)}
    if keyboard is not None:
        payload["reply_markup"] = keyboard
    try:
        await tg_api("editMessageText", payload)
    except Exception as exc:
        if "message is not modified" in str(exc).lower():
            return
        # An edit failure must not make an inline button look dead. Send the
        # same panel as a fresh message; no user-facing panel text is changed.
        log.warning("telegram edit fallback send | %s: %s", type(exc).__name__, exc)
        await tg_send_text(chat_id, text, keyboard)


async def tg_answer_callback(callback_id: str, text: str = "") -> None:
    payload: Dict[str, Any] = {"callback_query_id": str(callback_id)}
    if text:
        payload["text"] = str(text)[:180]
    try:
        await tg_api("answerCallbackQuery", payload)
    except Exception:
        pass


async def tg_show_home(chat_id: int, message_id: Optional[int] = None) -> None:
    text = tg_home_text()
    keyboard = tg_main_keyboard()
    if message_id:
        await tg_edit_text(chat_id, message_id, text, keyboard)
    else:
        await tg_send_text(chat_id, text, keyboard)


async def tg_download_content(message: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    content_type = ""
    file_id = ""
    original_name = ""
    if message.get("photo"):
        content_type = "photo"
        file_id = str((message.get("photo") or [])[-1].get("file_id") or "")
        original_name = "photo.jpg"
    elif message.get("voice"):
        content_type = "voice"
        voice = dict(message.get("voice") or {})
        file_id = str(voice.get("file_id") or "")
        original_name = str(voice.get("file_name") or "voice.ogg")
    elif message.get("video"):
        content_type = "video"
        video = dict(message.get("video") or {})
        file_id = str(video.get("file_id") or "")
        original_name = str(video.get("file_name") or "video.mp4")
    elif message.get("document"):
        content_type = "document"
        document = dict(message.get("document") or {})
        file_id = str(document.get("file_id") or "")
        original_name = str(document.get("file_name") or "document.bin")
    elif str(message.get("text") or "").strip():
        return {"type": "text", "text": str(message.get("text") or "").strip(), "path": ""}
    else:
        return None

    if not file_id:
        return None
    info = await tg_api("getFile", {"file_id": file_id})
    file_path = str((info.get("result") or {}).get("file_path") or "")
    if not file_path:
        raise RuntimeError("TELEGRAM_FILE_PATH_MISSING")
    suffix = Path(file_path).suffix or Path(original_name).suffix or ".bin"
    safe_base = re.sub(r"[^A-Za-z0-9_.-]+", "_", Path(original_name).stem)[:60] or content_type
    local_path = TELEGRAM_MEDIA_DIR / f"{int(time.time()*1000)}_{safe_base}{suffix}"
    global _tg_http_session
    if _tg_http_session is None or _tg_http_session.closed:
        _tg_http_session = aiohttp.ClientSession(timeout=aiohttp.ClientTimeout(total=90))
    download_url = f"https://api.telegram.org/file/bot{TELEGRAM_ADMIN_BOT_TOKEN}/{file_path}"
    async with _tg_http_session.get(download_url) as response:
        response.raise_for_status()
        with local_path.open("wb") as handle:
            async for chunk in response.content.iter_chunked(262144):
                handle.write(chunk)
    try:
        local_path.chmod(0o600)
    except Exception:
        pass
    file_size = local_path.stat().st_size if local_path.is_file() else 0
    if file_size <= 0:
        raise RuntimeError("TELEGRAM_MEDIA_EMPTY")
    log.info(
        "telegram campaign media downloaded | type=%s bytes=%s file=%s",
        content_type, file_size, local_path.name,
    )
    return {
        "type": content_type,
        "text": str(message.get("caption") or "").strip(),
        "path": str(local_path),
    }


async def discover_private_contacts_from_dialogs(limit: Optional[int] = None) -> int:
    found = 0
    dialogs = await asyncio.wait_for(
        client.get_dialogs(limit=int(limit or TELEGRAM_PRIVATE_DISCOVERY_LIMIT)),
        timeout=25,
    )
    for dialog in dialogs or []:
        entity = getattr(dialog, "entity", None)
        if not isinstance(entity, types.User):
            continue
        uid = safe_int(getattr(entity, "id", None))
        if uid is None or uid <= 0 or uid in SYSTEM_USER_IDS or uid == SELF_USER_ID:
            continue
        try:
            target = utils.get_input_peer(entity)
        except Exception:
            continue
        # Strict historical discovery: only register a dialog if recent history
        # contains at least one inbound user message. This avoids turning arbitrary
        # outgoing-only dialogs into advertising recipients.
        inbound_message_id = 0
        try:
            history = await asyncio.wait_for(client.get_messages(target, limit=6), timeout=8)
            for item in _private_history_items(history):
                if item is None or bool(getattr(item, "out", False)):
                    continue
                sender = safe_int(getattr(item, "sender_id", None))
                if sender is not None and int(sender) != int(uid):
                    continue
                inbound_message_id = max(inbound_message_id, safe_int(getattr(item, "id", None)) or 0)
        except Exception as exc:
            log.debug("private history discovery skipped | user=%s | %s: %s", uid, type(exc).__name__, exc)
            continue
        if inbound_message_id <= 0:
            continue
        register_private_contact(int(uid), int(inbound_message_id), target, source="history")
        found += 1
        await asyncio.sleep(0.03)
    return found


def coordination_private_user_ids() -> set[int]:
    """Durable PV users tied to a ZIVO group-link/coordination flow.

    These users are safe to retain for the admin panel even when the latest PV
    history is outgoing-only, because the durable join/activation records prove
    that this private chat participated in a ZIVO group coordination workflow.
    """
    ids: set[int] = set()
    try:
        with db_connect() as con:
            for sql in (
                "SELECT requester_user_id FROM pending_group_activations WHERE requester_user_id>0",
                "SELECT owner_id FROM activation_card_jobs WHERE owner_id>0",
                "SELECT user_id FROM private_contacts WHERE user_id>0",
            ):
                try:
                    ids.update(int(row[0]) for row in con.execute(sql).fetchall() if safe_int(row[0]) and int(row[0]) > 0)
                except Exception:
                    pass
    except Exception:
        pass
    try:
        con = sqlite3.connect(str(MULTI_ACCOUNT_DB), timeout=3.0)
        try:
            for sql in (
                "SELECT requester_user_id FROM join_jobs WHERE requester_user_id>0",
                "SELECT user_id FROM social_private_starts WHERE user_id>0",
            ):
                try:
                    ids.update(int(row[0]) for row in con.execute(sql).fetchall() if safe_int(row[0]) and int(row[0]) > 0)
                except Exception:
                    pass
        finally:
            con.close()
    except Exception:
        pass
    ids.difference_update({int(x) for x in SYSTEM_USER_IDS})
    ids.discard(int(SELF_USER_ID or 0))
    try:
        for row in multi_account_rows():
            sid = safe_int(row["self_id"])
            if sid is not None and int(sid) > 0:
                ids.discard(int(sid))
    except Exception:
        pass
    return {int(x) for x in ids if int(x) > 0}


def _shared_group_claim_owner_map(group_ids: Iterable[int]) -> Dict[int, str]:
    gids = sorted({int(g) for g in group_ids if int(g) > 0})
    if not gids or not MULTI_ACCOUNT_DB.is_file():
        return {}
    result: Dict[int, str] = {}
    try:
        con = sqlite3.connect(str(MULTI_ACCOUNT_DB), timeout=5.0)
        con.row_factory = sqlite3.Row
        try:
            for offset in range(0, len(gids), 700):
                chunk = gids[offset:offset + 700]
                marks = ",".join("?" for _ in chunk)
                rows = con.execute(
                    f"SELECT group_id, account_key FROM group_claims WHERE group_id IN ({marks})",
                    chunk,
                ).fetchall()
                for row in rows:
                    result[int(row["group_id"])] = str(row["account_key"] or "").strip().lower()
        finally:
            con.close()
    except Exception as exc:
        log.debug("full inventory claim-map read skipped | %s: %s", type(exc).__name__, exc)
    return result


def _persist_full_dialog_groups(group_rows: List[Dict[str, Any]]) -> Dict[str, int]:
    if not group_rows:
        return {"owned": 0, "conflicts": 0, "created": 0, "updated": 0}
    seed_rows = [
        {
            "group_id": int(item["group_id"]),
            "group_title": str(item.get("group_title") or ""),
            "public_username": str(item.get("public_username") or ""),
            "invite_fingerprint": "",
        }
        for item in group_rows
    ]
    owned_count = 0
    conflicts = 0
    try:
        owned_count, conflicts = multi_seed_group_claims_bulk(
            MULTI_ACCOUNT_DB,
            account_key=ACCOUNT_KEY,
            self_id=int(SELF_USER_ID or 0),
            groups=seed_rows,
            status="active",
        )
    except Exception as exc:
        log.warning("full inventory claim seed failed | account=%s | %s: %s", ACCOUNT_KEY, type(exc).__name__, exc)
    owner_map = _shared_group_claim_owner_map(item["group_id"] for item in group_rows)
    now = datetime.now(timezone.utc).isoformat()
    created = 0
    updated = 0
    with db_connect() as con:
        for item in group_rows:
            gid = int(item["group_id"] or 0)
            if gid <= 0:
                continue
            owner = owner_map.get(gid, ACCOUNT_KEY)
            if owner and owner != ACCOUNT_KEY:
                continue
            existed = con.execute("SELECT 1 FROM installations WHERE group_id=?", (gid,)).fetchone() is not None
            con.execute(
                """
                INSERT OR IGNORE INTO installations(
                    group_id, group_title, owner_user_id, owner_username,
                    owner_access_hash, invite_hash, install_source,
                    default_locks_json, installed_at, native_owner_user_id,
                    native_owner_username, native_owner_access_hash, owner_mode
                ) VALUES (?, ?, 0, '', 0, '', ?, '[]', ?, 0, '', 0, 'executive')
                """,
                (gid, str(item.get("group_title") or ""), f"full-dialog-sync:{ACCOUNT_KEY}", now),
            )
            con.execute(
                "UPDATE installations SET group_title=CASE WHEN ?!='' THEN ? ELSE group_title END WHERE group_id=?",
                (str(item.get("group_title") or ""), str(item.get("group_title") or ""), gid),
            )
            _group_lifecycle_upsert_in_connection(
                con, gid, str(item.get("group_title") or ""),
                str(item.get("peer_kind") or "channel"),
                int(item.get("group_access_hash") or 0), now=now,
            )
            if existed:
                updated += 1
            else:
                created += 1
        con.commit()
    return {"owned": int(owned_count), "conflicts": int(conflicts), "created": int(created), "updated": int(updated)}


def _try_acquire_full_inventory_lock() -> Optional[Any]:
    """Cross-process lock so main/acc2/acc3 never paginate dialogs together."""
    FULL_DIALOG_INVENTORY_LOCK_PATH.parent.mkdir(parents=True, exist_ok=True)
    handle = open(FULL_DIALOG_INVENTORY_LOCK_PATH, "a+", encoding="utf-8")
    try:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except BlockingIOError:
        handle.close()
        return None
    handle.seek(0)
    handle.truncate()
    handle.write(f"{ACCOUNT_KEY} {os.getpid()} {datetime.now(timezone.utc).isoformat()}\n")
    handle.flush()
    return handle


def _release_full_inventory_lock(handle: Optional[Any]) -> None:
    if handle is None:
        return
    try:
        fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    finally:
        try:
            handle.close()
        except Exception:
            pass


async def _full_inventory_low_priority_checkpoint(dialogs_seen: int) -> None:
    """Stop inventory while a PM/command is hot or the transport is crowded."""
    paused_logged = False
    while True:
        priority_hot = _priority_traffic_is_hot(FULL_DIALOG_INVENTORY_PRIORITY_QUIET_SECONDS)
        pending = _transport_pending_request_count(client)
        if not priority_hot and pending < FULL_DIALOG_INVENTORY_PENDING_SOFT:
            break
        if not paused_logged:
            log.info(
                "full dialog inventory PAUSE | account=%s dialogs=%s priority=%s pending=%s",
                ACCOUNT_KEY, int(dialogs_seen), int(priority_hot), int(pending),
            )
            paused_logged = True
        await asyncio.sleep(0.20)
    await asyncio.sleep(FULL_DIALOG_INVENTORY_PAGE_PAUSE_SECONDS)


def _is_private_not_found_error(exc: BaseException) -> bool:
    text = f"{type(exc).__name__}: {exc}".upper()
    return "RPCERROR 404" in text and "NOT_FOUND" in text


def _private_not_found_cooldown_active(user_id: Optional[int]) -> bool:
    if user_id is None or int(user_id) <= 0:
        return False
    uid = int(user_id)
    until = float(_private_not_found_until.get(uid, 0.0) or 0.0)
    if until <= time.monotonic():
        _private_not_found_until.pop(uid, None)
        return False
    return True


def _mark_private_not_found_cooldown(user_id: Optional[int]) -> None:
    if user_id is None or int(user_id) <= 0:
        return
    _private_not_found_until[int(user_id)] = time.monotonic() + PRIVATE_NOT_FOUND_COOLDOWN_SECONDS


def _raw_dialog_peer_id(peer: Any) -> Optional[int]:
    try:
        return int(utils.get_peer_id(peer))
    except Exception:
        for attr in ("user_id", "chat_id", "channel_id", "id"):
            value = safe_int(getattr(peer, attr, None))
            if value is not None:
                return int(value)
    return None


def _raw_dialog_message_key(peer: Any, message_id: Any) -> Tuple[Optional[int], int]:
    return _raw_dialog_peer_id(peer), int(safe_int(message_id) or 0)


async def iter_dialogs_exhaustive_raw(reason: str = "inventory"):
    """Yield every real dialog using explicit raw pagination.

    SPlusthon 1.1.4's high-level iterator stops when the server response is not
    ``messages.DialogsSlice`` even if a full 100-dialog page was returned. Some
    Soroush accounts therefore stop around 200 dialogs. This paginator ignores
    that response-class shortcut and advances with offset_id/date/peer until a
    short page or a repeated cursor proves the folder is exhausted.

    Folder 0 (normal) and folder 1 (archive) are scanned separately, then peers
    are de-duplicated. If raw GetDialogs is unavailable, the high-level iterator
    remains as a compatibility fallback.
    """
    page_size = 100
    yielded_peer_ids: set[int] = set()
    raw_succeeded = False
    for folder_id in (0, 1):
        offset_date = None
        offset_id = 0
        offset_peer: Any = types.InputPeerEmpty()
        exclude_pinned = False
        page_no = 0
        folder_dialogs = 0
        folder_new = 0
        seen_cursors: set[Tuple[int, int, int]] = set()
        while True:
            request = functions.messages.GetDialogsRequest(
                offset_date=offset_date,
                offset_id=int(offset_id),
                offset_peer=offset_peer,
                limit=page_size,
                hash=0,
                exclude_pinned=exclude_pinned,
                folder_id=folder_id,
            )
            try:
                response = await asyncio.wait_for(client(request), timeout=35.0)
                raw_succeeded = True
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                log.warning(
                    "raw exhaustive dialog page failed | account=%s reason=%s folder=%s page=%s offset_id=%s | %s: %s",
                    ACCOUNT_KEY, reason, folder_id, page_no + 1, offset_id,
                    type(exc).__name__, exc,
                )
                break

            page_no += 1
            dialogs = list(getattr(response, "dialogs", None) or [])
            users = list(getattr(response, "users", None) or [])
            chats = list(getattr(response, "chats", None) or [])
            raw_messages = list(getattr(response, "messages", None) or [])
            folder_dialogs += len(dialogs)

            entities: Dict[int, Any] = {}
            for entity in users + chats:
                if type(entity).__name__ in {"UserEmpty", "ChatEmpty"}:
                    continue
                peer_id = _raw_dialog_peer_id(entity)
                if peer_id is not None:
                    entities[int(peer_id)] = entity

            messages: Dict[Tuple[Optional[int], int], Any] = {}
            for message in raw_messages:
                key = _raw_dialog_message_key(getattr(message, "peer_id", None), getattr(message, "id", 0))
                messages[key] = message

            page_new = 0
            for raw_dialog in dialogs:
                peer_id = _raw_dialog_peer_id(getattr(raw_dialog, "peer", None))
                if peer_id is None:
                    continue
                entity = entities.get(int(peer_id))
                if entity is None:
                    continue
                if int(peer_id) in yielded_peer_ids:
                    continue
                yielded_peer_ids.add(int(peer_id))
                page_new += 1
                folder_new += 1
                yield SimpleNamespace(
                    entity=entity,
                    title=str(getattr(entity, "title", None) or getattr(entity, "first_name", None) or ""),
                )

            log.info(
                "raw exhaustive dialog page | account=%s reason=%s folder=%s page=%s returned=%s new=%s unique_total=%s response=%s",
                ACCOUNT_KEY, reason, folder_id, page_no, len(dialogs), page_new,
                len(yielded_peer_ids), type(response).__name__,
            )

            if len(dialogs) < page_size:
                break

            last_dialog = None
            last_entity = None
            last_message = None
            for raw_dialog in reversed(dialogs):
                peer_id = _raw_dialog_peer_id(getattr(raw_dialog, "peer", None))
                if peer_id is None:
                    continue
                entity = entities.get(int(peer_id))
                message = messages.get(
                    _raw_dialog_message_key(
                        getattr(raw_dialog, "peer", None),
                        getattr(raw_dialog, "top_message", 0),
                    )
                )
                if entity is not None and message is not None:
                    last_dialog, last_entity, last_message = raw_dialog, entity, message
                    break

            if last_dialog is None or last_entity is None or last_message is None:
                log.warning(
                    "raw exhaustive dialog pagination stop: no cursor | account=%s reason=%s folder=%s page=%s returned=%s",
                    ACCOUNT_KEY, reason, folder_id, page_no, len(dialogs),
                )
                break

            next_offset_id = int(safe_int(getattr(last_message, "id", None)) or 0)
            next_date = getattr(last_message, "date", None)
            next_peer_id = int(_raw_dialog_peer_id(getattr(last_dialog, "peer", None)) or 0)
            next_ts = int(next_date.timestamp()) if getattr(next_date, "timestamp", None) else 0
            cursor = (next_offset_id, next_ts, next_peer_id)
            if next_offset_id <= 0 or cursor in seen_cursors:
                log.warning(
                    "raw exhaustive dialog pagination stop: repeated cursor | account=%s reason=%s folder=%s page=%s cursor=%s",
                    ACCOUNT_KEY, reason, folder_id, page_no, cursor,
                )
                break
            seen_cursors.add(cursor)
            offset_id = next_offset_id
            offset_date = next_date
            try:
                offset_peer = utils.get_input_peer(last_entity)
            except Exception:
                try:
                    offset_peer = await client.get_input_entity(last_entity)
                except Exception:
                    log.warning(
                        "raw exhaustive dialog pagination stop: input peer unavailable | account=%s reason=%s folder=%s page=%s peer=%s",
                        ACCOUNT_KEY, reason, folder_id, page_no, next_peer_id,
                    )
                    break
            exclude_pinned = True
            await asyncio.sleep(0)

        log.info(
            "raw exhaustive dialog folder PASS | account=%s reason=%s folder=%s pages=%s returned=%s new=%s unique_total=%s",
            ACCOUNT_KEY, reason, folder_id, page_no, folder_dialogs, folder_new,
            len(yielded_peer_ids),
        )

    if raw_succeeded:
        return

    log.warning(
        "raw exhaustive dialog fallback -> iter_dialogs | account=%s reason=%s",
        ACCOUNT_KEY, reason,
    )
    async for dialog in client.iter_dialogs(limit=None):
        entity = getattr(dialog, "entity", None)
        peer_id = _raw_dialog_peer_id(entity)
        if peer_id is None or int(peer_id) in yielded_peer_ids:
            continue
        yielded_peer_ids.add(int(peer_id))
        yield dialog


async def full_dialog_inventory_sync(reason: str = "periodic") -> Dict[str, int]:
    """Scan every open/archived dialog for this account with no fixed cap."""
    stats = {
        "dialogs": 0, "groups_seen": 0, "groups_created": 0,
        "groups_updated": 0, "group_conflicts": 0,
        "private_seen": 0, "private_registered": 0,
        "private_coordination": 0, "private_bot_skipped": 0,
    }
    groups: Dict[int, Dict[str, Any]] = {}
    coordination_ids = coordination_private_user_ids()
    known_private = set()
    try:
        with db_connect() as con:
            known_private = {int(row[0]) for row in con.execute("SELECT user_id FROM private_contacts WHERE user_id>0").fetchall()}
    except Exception:
        pass

    log.info("full dialog inventory START | account=%s reason=%s cap=none", ACCOUNT_KEY, reason)
    async for dialog in iter_dialogs_exhaustive_raw(f"full-inventory:{reason}"):
        stats["dialogs"] += 1
        entity = getattr(dialog, "entity", None)
        if is_group_entity(entity) and not bool(getattr(entity, "broadcast", False)):
            gid = safe_int(getattr(entity, "id", None))
            if gid is not None and int(gid) > 0:
                stats["groups_seen"] += 1
                groups[int(gid)] = {
                    "group_id": int(gid),
                    "group_title": str(getattr(entity, "title", None) or getattr(dialog, "title", None) or ""),
                    "peer_kind": "chat" if isinstance(entity, types.Chat) else "channel",
                    "group_access_hash": int(safe_int(getattr(entity, "access_hash", None)) or 0),
                    "public_username": str(getattr(entity, "username", None) or "").strip().lstrip("@"),
                }
        elif isinstance(entity, types.User):
            uid = safe_int(getattr(entity, "id", None))
            if uid is not None and int(uid) > 0 and int(uid) not in SYSTEM_USER_IDS and int(uid) != int(SELF_USER_ID or 0):
                stats["private_seen"] += 1
                if bool(getattr(entity, "bot", False)) or bool(getattr(entity, "deleted", False)):
                    stats["private_bot_skipped"] += 1
                elif FULL_DIALOG_INVENTORY_REGISTER_ALL_PRIVATE or int(uid) in coordination_ids or int(uid) in known_private:
                    try:
                        target = utils.get_input_peer(entity)
                    except Exception:
                        target = entity
                    register_private_contact(
                        int(uid), 0, target,
                        source="coordination" if int(uid) in coordination_ids else "dialog-inventory",
                    )
                    stats["private_registered"] += 1
                    if int(uid) in coordination_ids:
                        stats["private_coordination"] += 1
        if stats["dialogs"] % FULL_DIALOG_INVENTORY_PAGE_SIZE_HINT == 0:
            log.info(
                "full dialog inventory progress | account=%s dialogs=%s groups=%s private=%s",
                ACCOUNT_KEY, stats["dialogs"], stats["groups_seen"], stats["private_seen"],
            )
            await _full_inventory_low_priority_checkpoint(stats["dialogs"])

    # Durable coordination requesters are part of the requested PV inventory even
    # if their dialog was not yielded in this pass (for example after archiving).
    for uid in coordination_ids:
        register_private_contact(int(uid), 0, None, source="coordination")

    persisted = await asyncio.to_thread(_persist_full_dialog_groups, list(groups.values()))
    stats["groups_created"] = int(persisted.get("created") or 0)
    stats["groups_updated"] = int(persisted.get("updated") or 0)
    stats["group_conflicts"] = int(persisted.get("conflicts") or 0)
    log.info(
        "full dialog inventory PASS | account=%s reason=%s dialogs=%s groups_seen=%s created=%s updated=%s conflicts=%s private_seen=%s private_registered=%s coordination_private=%s private_bot_skipped=%s",
        ACCOUNT_KEY, reason, stats["dialogs"], stats["groups_seen"], stats["groups_created"],
        stats["groups_updated"], stats["group_conflicts"], stats["private_seen"],
        stats["private_registered"], stats["private_coordination"], stats["private_bot_skipped"],
    )
    return stats


def request_full_inventory_sync_all() -> List[str]:
    requested: List[str] = []
    FULL_DIALOG_INVENTORY_REQUEST_DIR.mkdir(parents=True, exist_ok=True)
    for row in multi_account_rows():
        if not bool(int(row["enabled"] or 0)):
            continue
        key = str(row["account_key"] or "").strip().lower()
        if not key:
            continue
        path = FULL_DIALOG_INVENTORY_REQUEST_DIR / f"{key}.request"
        path.write_text(datetime.now(timezone.utc).isoformat(), encoding="utf-8")
        requested.append(key)
    return requested


async def full_dialog_inventory_worker() -> None:
    if not FULL_DIALOG_INVENTORY_ENABLED:
        return
    start_delay = float(FULL_DIALOG_INVENTORY_START_DELAYS.get(ACCOUNT_KEY, 90.0))
    await asyncio.sleep(start_delay)
    request_path = FULL_DIALOG_INVENTORY_REQUEST_DIR / f"{ACCOUNT_KEY}.request"
    next_periodic = 0.0
    while True:
        try:
            now = time.monotonic()
            requested = request_path.exists()
            if requested or now >= next_periodic:
                reason = "panel-request" if requested else "startup/periodic"
                try:
                    request_path.unlink(missing_ok=True)
                except Exception:
                    pass
                lock_handle = None
                while lock_handle is None:
                    if _priority_traffic_is_hot(FULL_DIALOG_INVENTORY_PRIORITY_QUIET_SECONDS):
                        await asyncio.sleep(1.0)
                        continue
                    lock_handle = _try_acquire_full_inventory_lock()
                    if lock_handle is None:
                        await asyncio.sleep(3.0)
                try:
                    await _full_inventory_low_priority_checkpoint(0)
                    await full_dialog_inventory_sync(reason)
                finally:
                    _release_full_inventory_lock(lock_handle)
                next_periodic = time.monotonic() + FULL_DIALOG_INVENTORY_INTERVAL_SECONDS
            await asyncio.sleep(FULL_DIALOG_INVENTORY_REQUEST_POLL_SECONDS)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.warning("full dialog inventory retry | account=%s | %s: %s", ACCOUNT_KEY, type(exc).__name__, exc)
            next_periodic = time.monotonic() + 300.0
            await asyncio.sleep(15.0)


async def campaign_live_dialog_targets(scope: str, job_id: int) -> List[Tuple[str, Dict[str, Any]]]:
    """Build standard-campaign targets from the account's live dialog list.

    60.96.27 replaces the high-level dialog iterator with raw exhaustive pagination. A user-
    triggered campaign no longer waits behind the very conservative periodic
    inventory lock/pending threshold. Every account can scan its own Session in
    parallel. Foreground/private traffic still wins, and a hard transport ceiling
    prevents the scan from piling onto an already saturated connection.
    """
    wanted = str(scope or "groups").strip().lower()
    want_groups = wanted in {"groups", "both"}
    want_private = wanted in {"private", "both"}
    disabled_private: set[int] = set()
    if want_private:
        try:
            with db_connect() as con:
                disabled_private = {
                    int(row[0]) for row in con.execute(
                        "SELECT user_id FROM private_contacts WHERE user_id>0 AND can_broadcast=0"
                    ).fetchall()
                }
        except Exception:
            disabled_private = set()

    groups: Dict[int, Dict[str, Any]] = {}
    privates: Dict[int, Dict[str, Any]] = {}
    dialogs_seen = 0
    multi_update_job(
        MULTI_ACCOUNT_DB, int(job_id), status="scanning",
        group_targets=0, private_targets=0, total_targets=0,
        attempted=0, success_count=0, failure_count=0, skipped_count=0,
    )
    log.info(
        "campaign live dialog scan START | account=%s job=%s scope=%s cap=none parallel=1 pending_hard=%s",
        ACCOUNT_KEY, int(job_id), wanted, CAMPAIGN_SCAN_PENDING_HARD,
    )
    try:
        async for dialog in iter_dialogs_exhaustive_raw(f"campaign:{job_id}"):
            dialogs_seen += 1
            entity = getattr(dialog, "entity", None)
            if want_groups and is_group_entity(entity) and not bool(getattr(entity, "broadcast", False)):
                gid = safe_int(getattr(entity, "id", None))
                if gid is not None and int(gid) > 0:
                    groups[int(gid)] = {
                        "group_id": int(gid),
                        "group_title": str(getattr(entity, "title", None) or getattr(dialog, "title", None) or ""),
                        "peer_kind": "chat" if isinstance(entity, types.Chat) else "channel",
                        "group_access_hash": int(safe_int(getattr(entity, "access_hash", None)) or 0),
                        "last_activity_at": "",
                        "public_username": str(getattr(entity, "username", None) or "").strip().lstrip("@"),
                    }
            elif want_private and isinstance(entity, types.User):
                uid = safe_int(getattr(entity, "id", None))
                if (
                    uid is not None and int(uid) > 0
                    and int(uid) not in SYSTEM_USER_IDS
                    and int(uid) != int(SELF_USER_ID or 0)
                    and int(uid) not in disabled_private
                    and not bool(getattr(entity, "bot", False))
                    and not bool(getattr(entity, "deleted", False))
                ):
                    access_hash = int(safe_int(getattr(entity, "access_hash", None)) or 0)
                    privates[int(uid)] = {
                        "user_id": int(uid),
                        "access_hash": access_hash,
                        "last_seen_at": "",
                        "success_count": 0,
                        "failure_count": 0,
                    }
                    try:
                        target = utils.get_input_peer(entity)
                    except Exception:
                        target = entity
                    register_private_contact(int(uid), 0, target, source="campaign-live-dialog")

            if dialogs_seen % FULL_DIALOG_INVENTORY_PAGE_SIZE_HINT == 0:
                multi_update_job(
                    MULTI_ACCOUNT_DB, int(job_id),
                    group_targets=len(groups), private_targets=len(privates),
                    total_targets=len(groups) + len(privates),
                )
                log.info(
                    "campaign live dialog scan progress | account=%s job=%s dialogs=%s groups=%s private=%s pending=%s",
                    ACCOUNT_KEY, int(job_id), dialogs_seen, len(groups), len(privates),
                    _transport_pending_count(client),
                )
                # Explicit admin campaign scan gets bounded fairness: live
                # PM/commands receive a grace window but cannot stall scanning
                # forever on a continuously busy network.
                while not await _wait_campaign_transport_slot(
                    CAMPAIGN_SCAN_PENDING_HARD, max_wait=CAMPAIGN_FOREGROUND_GRACE_SECONDS,
                ):
                    current = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
                    if current is None or bool(int(current["stop_requested"] or 0)):
                        raise CampaignStopRequested()
                    await asyncio.sleep(0.05)
                if CAMPAIGN_SCAN_PAGE_PAUSE_SECONDS > 0:
                    await asyncio.sleep(CAMPAIGN_SCAN_PAGE_PAUSE_SECONDS)
                else:
                    await asyncio.sleep(0)

        if groups:
            await asyncio.to_thread(_persist_full_dialog_groups, list(groups.values()))
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id),
            group_targets=len(groups), private_targets=len(privates),
            total_targets=len(groups) + len(privates),
        )
        log.info(
            "campaign live dialog scan PASS | account=%s job=%s dialogs=%s groups=%s private=%s pending=%s",
            ACCOUNT_KEY, int(job_id), dialogs_seen, len(groups), len(privates),
            _transport_pending_count(client),
        )
    except CampaignStopRequested:
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status="stopped",
            group_targets=len(groups), private_targets=len(privates),
            total_targets=len(groups) + len(privates),
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        raise

    result: List[Tuple[str, Dict[str, Any]]] = []
    if want_groups:
        result.extend(("group", row) for row in groups.values())
    if want_private:
        result.extend(("private", row) for row in privates.values())
    return result


def _campaign_media_send_kwargs(content_type: str, text: str) -> Dict[str, Any]:
    kwargs: Dict[str, Any] = {"parse_mode": None}
    if text:
        kwargs["caption"] = text
    if content_type == "voice":
        kwargs["voice_note"] = True
    elif content_type == "video":
        kwargs["supports_streaming"] = True
    elif content_type == "photo":
        kwargs["force_document"] = False
    return kwargs


def _campaign_reusable_media(result: Any) -> Any:
    if result is None:
        return None
    for attr in ("photo", "document"):
        value = getattr(result, attr, None)
        if value is not None:
            return value
    media = getattr(result, "media", None)
    if media is not None:
        for attr in ("photo", "document"):
            value = getattr(media, attr, None)
            if value is not None:
                return value
    return None


def _campaign_media_permission_rejected(exc: BaseException, content_type: str) -> bool:
    text = f"{type(exc).__name__}: {exc}".upper()
    common = (
        "CHATSENDMEDIAFORBIDDEN", "CHAT_SEND_MEDIA_FORBIDDEN",
        "MEDIA FORBIDDEN", "CANNOT SEND MEDIA", "CAN'T SEND MEDIA",
    )
    if any(token in text for token in common):
        return True
    specific = {
        "voice": ("CHATSENDVOICESFORBIDDEN", "CANNOT SEND VOICES", "CAN'T SEND VOICES"),
        "photo": ("CHATSENDPHOTOSFORBIDDEN", "CANNOT SEND PHOTOS", "CAN'T SEND PHOTOS"),
        "video": ("CHATSENDVIDEOSFORBIDDEN", "CANNOT SEND VIDEOS", "CAN'T SEND VIDEOS"),
        "document": ("CHATSENDDOCSFORBIDDEN", "CANNOT SEND DOC", "CAN'T SEND DOC"),
    }
    return any(token in text for token in specific.get(str(content_type), ()))


def _campaign_sendmedia_transient(exc: BaseException) -> bool:
    text = f"{type(exc).__name__}: {exc}".upper()
    return any(token in text for token in (
        "INTERNAL_SERVER_ERROR", "RPCERROR 500", "TIMEOUTERROR",
        "TIMED OUT", "INCOMPLETEREADERROR",
    ))


async def _campaign_send_uploaded_media(
    target: Any,
    uploaded: Any,
    kwargs: Dict[str, Any],
    content_type: str,
) -> Any:
    try:
        return await asyncio.wait_for(
            client.send_file(target, uploaded, **kwargs),
            timeout=BROADCAST_SEND_TIMEOUT_SECONDS,
        )
    except Exception as exc:
        if _is_group_inaccessible_error(exc) or _campaign_media_permission_rejected(exc, content_type):
            raise
        if not _campaign_sendmedia_transient(exc):
            raise
        await asyncio.sleep(0.35)
        return await asyncio.wait_for(
            client.send_file(target, uploaded, **kwargs),
            timeout=BROADCAST_SEND_TIMEOUT_SECONDS,
        )


async def _campaign_prepare_media_once(path: Path) -> Any:
    try:
        uploaded = await asyncio.wait_for(
            _zivo_upload_one_file(path),
            timeout=DEDICATED_UPLOAD_TIMEOUT_SECONDS,
        )
        log.info(
            "campaign media preupload PASS | file=%s bytes=%s",
            path.name, path.stat().st_size,
        )
        return uploaded
    except Exception as exc:
        log.warning(
            "campaign media preupload unavailable; per-target upload enabled | file=%s | %s: %s",
            path.name, type(exc).__name__, exc,
        )
        return None


async def _campaign_send_local_media(
    target: Any,
    path: Path,
    kwargs: Dict[str, Any],
    content_type: str,
) -> Any:
    # Local campaign files always use the dedicated upload lane first. Sending a
    # filesystem path through the realtime client makes SPlusthon issue
    # SaveFilePart on the connection server, which Soroush rejects with RPC 422.
    try:
        uploaded = await asyncio.wait_for(
            _zivo_upload_one_file(path),
            timeout=DEDICATED_UPLOAD_TIMEOUT_SECONDS,
        )
        return await _campaign_send_uploaded_media(target, uploaded, kwargs, content_type)
    except Exception as upload_error:
        if _is_group_inaccessible_error(upload_error) or _campaign_media_permission_rejected(upload_error, content_type):
            raise
        raise RuntimeError(
            f"CAMPAIGN_MEDIA_SEND_FAILED upload={type(upload_error).__name__}:{upload_error}"
        ) from upload_error


def _campaign_plain_text_forbidden(exc: BaseException) -> bool:
    detail = f"{type(exc).__name__}: {exc}".upper()
    return any(token in detail for token in (
        "CHATSENDPLAINFORBIDDEN",
        "CHAT_SEND_PLAIN_FORBIDDEN",
        "YOU CANNOT SEND PLAIN RESULTS",
        "YOU CANNOT SEND PLAIN",
    ))


async def _campaign_send_group_text(target: Any, text: str) -> Any:
    """Send campaign text to legacy groups without misclassifying them as gone.

    Some healthy Soroush groups reject an empty formatting-entity list with
    ChatSendPlainForbidden but accept the same text with one harmless blockquote
    entity. Group command replies already use this compatibility path; campaign
    sends must do the same and must never prune the group for a formatting-only
    rejection.
    """
    try:
        return await client.send_message(
            target, text, parse_mode=None, formatting_entities=[], link_preview=False
        )
    except Exception as exc:
        if not _campaign_plain_text_forbidden(exc):
            raise
        entities = [types.MessageEntityBlockquote(offset=0, length=utf16_len(text))]
        result = await client.send_message(
            target, text, parse_mode=None,
            formatting_entities=entities, link_preview=False,
        )
        log.info("campaign group rich-text fallback PASS | account=%s", ACCOUNT_KEY)
        return result


async def broadcast_send_target(
    kind: str,
    row: sqlite3.Row,
    content_type: str,
    text: str,
    media_path: str,
    prepared_media: Any = None,
) -> Any:
    if kind == "group":
        target = await resolve_group_lifecycle_target(row)
        if target is None:
            raise RuntimeError("GROUP_TARGET_UNRESOLVED")
    else:
        uid = int(row["user_id"])
        access_hash = int(row["access_hash"] or 0)
        target = types.InputPeerUser(uid, access_hash) if access_hash else await resolve_private_target(None, uid)
        if target is None:
            raise RuntimeError("PRIVATE_TARGET_UNRESOLVED")

    if content_type == "text":
        if kind == "private":
            return await send_private(target, text, verify_delivery=False)
        return await _campaign_send_group_text(target, text)

    path = Path(media_path)
    if not path.is_file():
        raise RuntimeError("CAMPAIGN_MEDIA_MISSING")
    kwargs = _campaign_media_send_kwargs(content_type, text)

    if prepared_media is not None:
        try:
            return await _campaign_send_uploaded_media(
                target, prepared_media, kwargs, content_type
            )
        except Exception as exc:
            if _is_group_inaccessible_error(exc):
                raise
            if _campaign_media_permission_rejected(exc, content_type):
                # A hard peer permission will not change after re-uploading the
                # same bytes. Skip immediately so campaigns can reach eligible
                # groups instead of spending ~10-50s re-uploading per blocked peer.
                log.info(
                    "campaign media permission skip; no reupload | type=%s | %s: %s",
                    content_type, type(exc).__name__, exc,
                )
                raise
            # The prepared InputFile can expire or a transient SendMedia call can
            # fail. Only these cases fall back to a fresh local upload.
            log.info(
                "campaign prepared media failed; local reupload | %s: %s",
                type(exc).__name__, exc,
            )

    return await _campaign_send_local_media(target, path, kwargs, content_type)


def campaign_progress_text(row: sqlite3.Row) -> str:
    total = int(row["total_planned"] or 0)
    attempted = int(row["attempted"] or 0)
    success = int(row["success_count"] or 0)
    failed = int(row["failure_count"] or 0)
    remaining = max(0, total - attempted)
    status_map = {"queued": "🟡 صف", "running": "🟢 در حال ارسال", "stopping": "🟠 در حال توقف", "stopped": "⛔ متوقف", "done": "✅ تمام شد", "failed": "❌ خطا"}
    return (
        f"📢 کمپین #{int(row['campaign_id'])}\n\n"
        f"وضعیت: {status_map.get(str(row['status']), str(row['status']))}\n"
        f"🔁 دور: {int(row['current_round'] or 0)}/{int(row['repeat_count'] or 1)}\n"
        f"📨 برنامه‌ریزی: {total}\n"
        f"✅ موفق: {success}\n"
        f"❌ ناموفق: {failed}\n"
        f"⏳ باقی‌مانده: {remaining}"
    )


async def run_telegram_campaign(campaign_id: int) -> None:
    stop_flag = _tg_campaign_stop_flags.setdefault(int(campaign_id), asyncio.Event())
    row = campaign_row(campaign_id)
    if row is None:
        return
    update_campaign_progress(
        campaign_id, status="running", started_at=datetime.now(timezone.utc).isoformat()
    )
    attempted = success = failed = 0
    last_progress = 0.0
    last_db_progress = 0.0
    scope = str(row["target_scope"])
    content_type = str(row["content_type"])
    text = str(row["content_text"] or "")
    media_path = str(row["media_path"] or "")
    prepared_media: Any = None
    repeats = max(1, int(row["repeat_count"] or 1))
    interval_seconds = max(0, int(row["interval_seconds"] or 0))
    chat_id = int(row["telegram_chat_id"] or TELEGRAM_ADMIN_ID)
    progress_message_id = int(row["telegram_message_id"] or 0)

    try:
        if content_type != "text":
            path = Path(media_path)
            if not media_path or not path.is_file():
                raise RuntimeError("CAMPAIGN_MEDIA_MISSING")
            prepared_media = await _campaign_prepare_media_once(path)

        for round_index in range(1, repeats + 1):
            if stop_flag.is_set():
                break
            update_campaign_progress(campaign_id, current_round=round_index)
            targets: List[Tuple[str, sqlite3.Row]] = []
            if scope in {"groups", "both"}:
                targets.extend(("group", item) for item in telegram_group_targets())
            if scope in {"private", "both"}:
                targets.extend(("private", item) for item in telegram_private_targets())

            for kind, target_row in targets:
                if stop_flag.is_set():
                    break
                while not await _wait_transport_background_slot(
                    soft_limit=FOREGROUND_BACKGROUND_PENDING_SOFT,
                    max_wait=1.0,
                ):
                    if stop_flag.is_set():
                        break
                    await asyncio.sleep(0.10)
                if stop_flag.is_set():
                    break

                target_id = int(
                    target_row["group_id"] if kind == "group" else target_row["user_id"]
                )
                try:
                    result = await asyncio.wait_for(
                        broadcast_send_target(
                            kind, target_row, content_type, text, media_path,
                            prepared_media=prepared_media,
                        ),
                        timeout=(
                            CAMPAIGN_MEDIA_TARGET_TIMEOUT_SECONDS
                            if content_type != "text"
                            else BROADCAST_SEND_TIMEOUT_SECONDS
                        ),
                    )
                    success += 1
                    if kind == "private":
                        mark_private_campaign_success(target_id)
                    if content_type != "text":
                        log.debug(
                            "campaign media target PASS | campaign=%s target=%s preupload=%s",
                            campaign_id, target_id, prepared_media is not None,
                        )
                except Exception as exc:
                    failed += 1
                    record_campaign_failure(campaign_id, kind, target_id, exc)
                    if kind == "group" and _is_group_inaccessible_error(exc):
                        try:
                            remove_installation_after_departure(target_id)
                            log.info(
                                "broadcast pruned inaccessible group | group=%s",
                                target_id,
                            )
                        except Exception:
                            log.exception(
                                "broadcast inaccessible-group prune failed | group=%s",
                                target_id,
                            )

                attempted += 1
                now = time.monotonic()
                if attempted % 10 == 0 or now - last_db_progress >= 1.0:
                    update_campaign_progress(
                        campaign_id, attempted=attempted, success_count=success, failure_count=failed
                    )
                    last_db_progress = now

                if progress_message_id and now - last_progress >= 2.0:
                    current = campaign_row(campaign_id)
                    if current is not None:
                        await tg_edit_text(
                            chat_id,
                            progress_message_id,
                            campaign_progress_text(current),
                            {"inline_keyboard": [
                                [tg_button("⛔ توقف کمپین", f"z:stop:{campaign_id}", "danger")],
                                [tg_button("🏠 پنل", "z:home", "primary")],
                            ]},
                        )
                    last_progress = now

                await asyncio.sleep(TELEGRAM_BROADCAST_DELAY_SECONDS)

            if stop_flag.is_set():
                break
            if round_index < repeats and interval_seconds > 0:
                slept = 0
                while slept < interval_seconds and not stop_flag.is_set():
                    chunk = min(5, interval_seconds - slept)
                    await asyncio.sleep(chunk)
                    slept += chunk

        final_status = "stopped" if stop_flag.is_set() else "done"
        update_campaign_progress(
            campaign_id,
            status=final_status,
            attempted=attempted,
            success_count=success,
            failure_count=failed,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
    except asyncio.CancelledError:
        update_campaign_progress(
            campaign_id, status="stopped", finished_at=datetime.now(timezone.utc).isoformat()
        )
        raise
    except Exception:
        log.exception("telegram campaign failed | campaign=%s", campaign_id)
        update_campaign_progress(
            campaign_id, status="failed", finished_at=datetime.now(timezone.utc).isoformat()
        )
    finally:
        final = campaign_row(campaign_id)
        if final is not None and progress_message_id:
            try:
                await tg_edit_text(
                    chat_id,
                    progress_message_id,
                    campaign_progress_text(final),
                    {"inline_keyboard": [[tg_button("🏠 بازگشت به پنل", "z:home", "success")]]},
                )
            except Exception as exc:
                log.debug("telegram final progress edit skipped | %s: %s", type(exc).__name__, exc)
        _tg_campaign_tasks.pop(int(campaign_id), None)
        _tg_campaign_stop_flags.pop(int(campaign_id), None)



def _campaign_result_message_id(result: Any) -> int:
    if result is None:
        return 0
    if isinstance(result, (list, tuple)):
        for item in result:
            mid = safe_int(getattr(item, "id", None))
            if mid:
                return int(mid)
        return 0
    mid = safe_int(getattr(result, "id", None))
    return int(mid or 0)


def target_campaign_batch_size(remaining_members: int) -> int:
    remaining = max(0, int(remaining_members))
    if remaining > 500:
        return 100
    if remaining > 200:
        return 50
    if remaining > 50:
        return 20
    if remaining > 20:
        return 10
    if remaining > 5:
        return 5
    return 1


def _extract_splus_url(value: str) -> str:
    raw = str(value or "").strip()
    match = re.search(r"https?://(?:www\.)?(?:web\.)?splus\.ir/[^\s\]\)]+", raw, flags=re.IGNORECASE)
    if match:
        return match.group(0).rstrip(".,،؛")
    return raw


async def measure_target_group_members(target_link: str) -> Tuple[Optional[int], int, str]:
    value = _extract_splus_url(target_link)
    invite_match = GROUP_LINK_RE.match(value)
    if invite_match:
        invite_hash = str(invite_match.group(1) or "").strip()
        try:
            preview = await asyncio.wait_for(client(CheckChatInviteRequest(invite_hash)), timeout=8.0)
            count = safe_int(getattr(preview, "participants_count", None))
            chat = getattr(preview, "chat", None)
            gid = int(safe_int(getattr(chat, "id", None)) or 0)
            if count is None and chat is not None and is_group_entity(chat):
                meta = await get_group_metadata(chat, preview)
                count = safe_int(meta.get("member_count"))
                gid = int(meta.get("id") or gid or 0)
            if count is None:
                return None, gid, "INVITE_MEMBER_COUNT_UNAVAILABLE"
            return int(count), gid, "invite"
        except Exception as exc:
            return None, 0, f"{type(exc).__name__}: {exc}"[:300]

    public_match = PUBLIC_GROUP_LINK_RE.match(value)
    username = ""
    if public_match:
        username = str(public_match.group(1) or "").strip().lstrip("@")
    else:
        m = PUBLIC_GROUP_USERNAME_RE.match(value)
        if m:
            username = str(m.group(1) or "").strip().lstrip("@")
    if username:
        try:
            group = await asyncio.wait_for(resolve_public_group(username), timeout=8.0)
            if bool(getattr(group, "broadcast", False)) or not is_group_entity(group):
                return None, int(safe_int(getattr(group, "id", None)) or 0), "TARGET_NOT_GROUP"
            meta = await asyncio.wait_for(get_group_metadata(group), timeout=10.0)
            count = safe_int(meta.get("member_count"))
            if count is None:
                return None, int(meta.get("id") or 0), "PUBLIC_MEMBER_COUNT_UNAVAILABLE"
            return int(count), int(meta.get("id") or 0), "public"
        except Exception as exc:
            return None, 0, f"{type(exc).__name__}: {exc}"[:300]

    normalized = normalize_moderation_digits(value).strip()
    if normalized.isdigit():
        gid = int(normalized)
        row = next((r for r in telegram_group_targets() if int(r["group_id"]) == gid), None)
        if row is None:
            return None, gid, "TARGET_GROUP_NOT_INSTALLED"
        target = await resolve_group_lifecycle_target(row)
        if target is None:
            return None, gid, "TARGET_GROUP_UNRESOLVED"
        try:
            entity = await asyncio.wait_for(client.get_entity(target), timeout=6.0)
        except Exception:
            entity = target
        meta = await get_group_metadata(entity)
        count = safe_int(meta.get("member_count"))
        return (int(count), gid, "id") if count is not None else (None, gid, "ID_MEMBER_COUNT_UNAVAILABLE")

    return None, 0, "INVALID_TARGET_GROUP_LINK"


async def cleanup_target_campaign_banners(job_id: int) -> Tuple[int, int]:
    rows = [
        row for row in multi_campaign_deliveries(MULTI_ACCOUNT_DB, int(job_id))
        if str(row["status"] or "") in {"sent", "delete_failed", "failed"}
    ]
    if not rows:
        return 0, 0
    target_rows = {int(r["group_id"]): r for r in telegram_group_targets()}
    deleted = failed = 0
    # The global delete lane is serial; do not wake several campaign retries
    # together after a FloodWait. Foreground commands keep transport priority.
    sem = asyncio.Semaphore(1)
    unavailable_groups: set[int] = set()

    async def remove_one(delivery: sqlite3.Row) -> bool:
        async with sem:
            gid = int(delivery["target_group_id"] or 0)
            mid = int(delivery["sent_message_id"] or 0)
            target_row = target_rows.get(gid)
            if gid in unavailable_groups:
                multi_update_campaign_delivery(
                    MULTI_ACCOUNT_DB, int(delivery["delivery_id"]), status="delete_failed",
                    last_error="TARGET_GROUP_UNAVAILABLE_CACHED",
                )
                return False
            if mid <= 0:
                multi_update_campaign_delivery(
                    MULTI_ACCOUNT_DB, int(delivery["delivery_id"]), status="delete_failed",
                    last_error="MESSAGE_ID_MISSING",
                )
                return False
            if campaign_delete_circuit_is_open():
                multi_update_campaign_delivery(
                    MULTI_ACCOUNT_DB, int(delivery["delivery_id"]), status="delete_failed",
                    last_error="CAMPAIGN_DELETE_CIRCUIT_HELD",
                )
                return False
            if not await _wait_transport_background_slot(
                soft_limit=FOREGROUND_BACKGROUND_PENDING_SOFT,
                max_wait=1.0,
            ):
                multi_update_campaign_delivery(
                    MULTI_ACCOUNT_DB, int(delivery["delivery_id"]), status="delete_failed",
                    last_error="LIVE_TRAFFIC_DEFERRED",
                )
                return False
            target = await resolve_group_lifecycle_target(target_row) if target_row is not None else None
            if target is None:
                try:
                    target = await asyncio.wait_for(client.get_input_entity(gid), timeout=8.0)
                except Exception:
                    target = None
            if target is None:
                unavailable_groups.add(gid)
                multi_update_campaign_delivery(
                    MULTI_ACCOUNT_DB, int(delivery["delivery_id"]), status="delete_failed",
                    last_error="TARGET_UNRESOLVED",
                )
                return False
            last_error = ""
            for attempt in range(1, 5):
                try:
                    await governed_delete_messages(
                        target,
                        int(mid),
                        timeout=15.0,
                        lane="campaign-cleanup",
                    )
                    await asyncio.sleep(0.08)
                    check = await asyncio.wait_for(client.get_messages(target, ids=[mid]), timeout=10.0)
                    live_items = check if isinstance(check, (list, tuple)) else [check]
                    if any(
                        item is not None and type(item).__name__ != "MessageEmpty"
                        and safe_int(getattr(item, "id", None)) == mid
                        for item in live_items
                    ):
                        raise RuntimeError("BANNER_DELETE_NOT_CONFIRMED")
                    multi_update_campaign_delivery(
                        MULTI_ACCOUNT_DB, int(delivery["delivery_id"]), status="deleted", last_error="",
                    )
                    return True
                except Exception as exc:
                    last_error = f"{type(exc).__name__}: {exc}"[:400]
                    if arm_campaign_delete_circuit(exc):
                        break
                    if _is_group_inaccessible_error(exc):
                        unavailable_groups.add(gid)
                        break
                    if attempt < 4:
                        await asyncio.sleep(min(2.0, 0.25 * (2 ** (attempt - 1))))
            multi_update_campaign_delivery(
                MULTI_ACCOUNT_DB, int(delivery["delivery_id"]), status="delete_failed", last_error=last_error,
            )
            return False

    for offset in range(0, len(rows), 20):
        results = await asyncio.gather(*(remove_one(row) for row in rows[offset:offset + 20]))
        deleted += sum(1 for ok in results if ok)
        failed += sum(1 for ok in results if not ok)
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), deleted_banner_count=deleted,
            cleanup_failure_count=failed,
        )
        await asyncio.sleep(0.15)
    return deleted, failed


async def run_target_growth_campaign_job(job_id: int, row: sqlite3.Row) -> None:
    batch_id = str(row["batch_id"] or "")
    target_link = str(row["target_group_link"] or "").strip()
    target_goal = int(row["target_member_count"] or 0)
    content_type = str(row["content_type"] or "text")
    text = str(row["content_text"] or "")
    media_path = str(row["media_path"] or "")
    attempted = int(row["attempted"] or 0)
    success = int(row["success_count"] or 0)
    failed = int(row["failure_count"] or 0)
    sent_count = int(row["sent_banner_count"] or 0)
    prepared_media: Any = None

    if not target_link or target_goal <= 0:
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status="failed",
            last_error="TARGET_CAMPAIGN_CONFIGURATION_INVALID",
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        return

    current_count, target_gid, source = await measure_target_group_members(target_link)
    if current_count is None:
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status="paused_measurement",
            measurement_error=str(source), last_error=str(source),
            target_group_id=int(target_gid or 0), current_member_count=-1,
        )
        return

    baseline = int(row["baseline_member_count"] or -1)
    if baseline < 0:
        baseline = int(current_count)
    multi_update_job(
        MULTI_ACCOUNT_DB, int(job_id), status="running",
        started_at=str(row["started_at"] or datetime.now(timezone.utc).isoformat()),
        target_group_id=int(target_gid or 0), baseline_member_count=baseline,
        current_member_count=int(current_count), measurement_error="",
    )

    if int(current_count) >= target_goal:
        if batch_id:
            multi_signal_target_batch_reached(
                MULTI_ACCOUNT_DB, batch_id=batch_id, source_job_id=int(job_id),
                current_member_count=int(current_count),
            )
        multi_update_job(MULTI_ACCOUNT_DB, int(job_id), status="cleanup", current_batch_size=0)
        deleted, cleanup_failed = await cleanup_target_campaign_banners(int(job_id))
        final_status = "target_reached" if cleanup_failed == 0 else "target_reached_cleanup_partial"
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status=final_status,
            current_member_count=int(current_count), deleted_banner_count=deleted,
            cleanup_failure_count=cleanup_failed,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        return

    if content_type != "text":
        path = Path(media_path)
        if not media_path or not path.is_file():
            multi_update_job(MULTI_ACCOUNT_DB, int(job_id), status="failed", last_error="CAMPAIGN_MEDIA_MISSING")
            return
        prepared_media = await _campaign_prepare_media_once(path)

    existing_deliveries = multi_campaign_deliveries(MULTI_ACCOUNT_DB, int(job_id))
    already_sent_groups = {
        int(d["target_group_id"] or 0) for d in existing_deliveries
        if str(d["status"] or "") in {"sent", "deleted"} and int(d["target_group_id"] or 0) > 0
    }
    targets = [
        r for r in telegram_group_targets()
        if int(r["group_id"]) != int(target_gid or 0) and int(r["group_id"]) not in already_sent_groups
    ]
    random.shuffle(targets)
    multi_update_job(MULTI_ACCOUNT_DB, int(job_id), total_targets=len(targets), total_planned=len(targets))
    cursor = 0

    while cursor < len(targets) and int(current_count) < target_goal:
        state = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
        if state is None:
            return
        if bool(int(state["stop_requested"] or 0)):
            if str(state["last_error"] or "") == "TARGET_REACHED_BY_BATCH":
                current_count = max(target_goal, int(state["current_member_count"] or target_goal))
                break
            multi_update_job(
                MULTI_ACCOUNT_DB, int(job_id), status="stopped", attempted=attempted,
                success_count=success, failure_count=failed, sent_banner_count=sent_count,
                finished_at=datetime.now(timezone.utc).isoformat(),
            )
            return
        if not multi_account_runtime_enabled():
            multi_update_job(MULTI_ACCOUNT_DB, int(job_id), status="stopped", last_error="ACCOUNT_DISABLED")
            return

        remaining_members = max(1, target_goal - int(current_count))
        batch_size = min(target_campaign_batch_size(remaining_members), len(targets) - cursor)
        batch = targets[cursor:cursor + batch_size]
        cursor += len(batch)
        multi_update_job(MULTI_ACCOUNT_DB, int(job_id), current_batch_size=len(batch))

        batch_target_reached = False
        for target_row in batch:
            live_state = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
            if (
                live_state is not None
                and bool(int(live_state["stop_requested"] or 0))
                and str(live_state["last_error"] or "") == "TARGET_REACHED_BY_BATCH"
            ):
                current_count = max(target_goal, int(live_state["current_member_count"] or target_goal))
                batch_target_reached = True
                break
            while not await _wait_transport_background_slot(
                soft_limit=FOREGROUND_BACKGROUND_PENDING_SOFT,
                max_wait=1.0,
            ):
                live_state = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
                if live_state is None:
                    return
                if bool(int(live_state["stop_requested"] or 0)):
                    if str(live_state["last_error"] or "") == "TARGET_REACHED_BY_BATCH":
                        current_count = max(target_goal, int(live_state["current_member_count"] or target_goal))
                        batch_target_reached = True
                        break
                    multi_update_job(
                        MULTI_ACCOUNT_DB, int(job_id), status="stopped", attempted=attempted,
                        success_count=success, failure_count=failed, sent_banner_count=sent_count,
                        finished_at=datetime.now(timezone.utc).isoformat(),
                    )
                    return
                await asyncio.sleep(0.10)
            if batch_target_reached:
                break
            gid = int(target_row["group_id"])
            try:
                result = await asyncio.wait_for(
                    broadcast_send_target(
                        "group", target_row, content_type, text, media_path,
                        prepared_media=prepared_media,
                    ),
                    timeout=(CAMPAIGN_MEDIA_TARGET_TIMEOUT_SECONDS if content_type != "text" else BROADCAST_SEND_TIMEOUT_SECONDS),
                )
                mid = _campaign_result_message_id(result)
                success += 1
                if mid > 0:
                    multi_record_campaign_delivery(
                        MULTI_ACCOUNT_DB, job_id=int(job_id), account_key=ACCOUNT_KEY,
                        target_group_id=gid, sent_message_id=mid,
                    )
                    sent_count += 1
            except Exception as exc:
                failed += 1
                detail = f"{type(exc).__name__}: {exc}"[:500]
                multi_update_job(MULTI_ACCOUNT_DB, int(job_id), last_error=detail)
                if _is_group_inaccessible_error(exc):
                    try:
                        remove_installation_after_departure(gid)
                    except Exception:
                        pass
            attempted += 1
            if attempted % 5 == 0:
                multi_update_job(
                    MULTI_ACCOUNT_DB, int(job_id), attempted=attempted,
                    success_count=success, failure_count=failed, sent_banner_count=sent_count,
                )
            await asyncio.sleep(TELEGRAM_BROADCAST_DELAY_SECONDS)

        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), attempted=attempted, success_count=success,
            failure_count=failed, sent_banner_count=sent_count,
        )
        if batch_target_reached:
            break
        await asyncio.sleep(TARGET_CAMPAIGN_MEASURE_DELAY_SECONDS)
        measured, measured_gid, measurement_source = await measure_target_group_members(target_link)
        if measured is None:
            multi_update_job(
                MULTI_ACCOUNT_DB, int(job_id), status="paused_measurement",
                measurement_error=str(measurement_source), last_error=str(measurement_source),
                current_member_count=int(current_count), target_group_id=int(measured_gid or target_gid or 0),
            )
            return
        current_count = int(measured)
        if measured_gid:
            target_gid = int(measured_gid)
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), current_member_count=int(current_count),
            target_group_id=int(target_gid or 0), measurement_error="",
        )

    if int(current_count) >= target_goal:
        if batch_id:
            multi_signal_target_batch_reached(
                MULTI_ACCOUNT_DB, batch_id=batch_id, source_job_id=int(job_id),
                current_member_count=int(current_count),
            )
        multi_update_job(MULTI_ACCOUNT_DB, int(job_id), status="cleanup", current_batch_size=0)
        deleted, cleanup_failed = await cleanup_target_campaign_banners(int(job_id))
        final_status = "target_reached" if cleanup_failed == 0 else "target_reached_cleanup_partial"
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status=final_status,
            attempted=attempted, success_count=success, failure_count=failed,
            sent_banner_count=sent_count, current_member_count=int(current_count),
            deleted_banner_count=deleted, cleanup_failure_count=cleanup_failed,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
    else:
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status="target_not_reached",
            attempted=attempted, success_count=success, failure_count=failed,
            sent_banner_count=sent_count, current_member_count=int(current_count),
            current_batch_size=0, finished_at=datetime.now(timezone.utc).isoformat(),
        )


async def run_multi_account_campaign_job(job_id: int) -> None:
    row = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
    if row is None:
        return
    if str(row["account_key"]) != ACCOUNT_KEY:
        return
    if str(row["campaign_mode"] or "standard") == "target_growth":
        await run_target_growth_campaign_job(int(job_id), row)
        return

    scope = str(row["target_scope"] or "groups")
    content_type = str(row["content_type"] or "text")
    text = str(row["content_text"] or "")
    media_path = str(row["media_path"] or "")
    repeats = max(1, int(row["repeat_count"] or 1))
    interval_seconds = max(0, int(row["interval_seconds"] or 0))
    attempted = success = failed = skipped = 0
    prepared_media: Any = None
    batch_id = str(row["batch_id"] or f"job-{int(job_id)}")
    owned_targets: set[Tuple[str, int]] = set()
    skipped_duplicate_targets: set[Tuple[str, int]] = set()
    send_started = time.monotonic()

    try:
        if content_type != "text":
            path = Path(media_path)
            if not media_path or not path.is_file():
                raise RuntimeError("CAMPAIGN_MEDIA_MISSING")
            prepared_media = await _campaign_prepare_media_once(path)

        targets: List[Tuple[str, Any]] = list(
            await campaign_live_dialog_targets(scope, int(job_id))
        )
        current = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
        if current is None or bool(int(current["stop_requested"] or 0)):
            multi_update_job(
                MULTI_ACCOUNT_DB, int(job_id), status="stopped",
                finished_at=datetime.now(timezone.utc).isoformat(),
            )
            return

        group_targets = sum(1 for kind, _ in targets if kind == "group")
        private_targets = sum(1 for kind, _ in targets if kind == "private")
        total_targets = len(targets)
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id),
            group_targets=group_targets, private_targets=private_targets,
            total_targets=total_targets, total_planned=total_targets * repeats,
            status="running",
        )
        log.info(
            "multi-account campaign send START | account=%s job=%s scope=%s groups=%s private=%s total=%s repeats=%s pace=%.3fs pending=%s",
            ACCOUNT_KEY, int(job_id), scope, group_targets, private_targets,
            total_targets, repeats, CAMPAIGN_SEND_RPC_MIN_INTERVAL_SECONDS,
            _transport_pending_request_count(client),
        )
        send_started = time.monotonic()

        for round_index in range(1, repeats + 1):
            multi_update_job(MULTI_ACCOUNT_DB, int(job_id), current_round=round_index)
            for kind, target_row in targets:
                current = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
                if current is None or bool(int(current["stop_requested"] or 0)):
                    multi_update_job(
                        MULTI_ACCOUNT_DB, int(job_id), status="stopped",
                        attempted=attempted, success_count=success,
                        failure_count=failed, skipped_count=skipped,
                        finished_at=datetime.now(timezone.utc).isoformat(),
                    )
                    return
                if not multi_account_runtime_enabled():
                    multi_update_job(
                        MULTI_ACCOUNT_DB, int(job_id), status="stopped",
                        attempted=attempted, success_count=success,
                        failure_count=failed, skipped_count=skipped,
                        last_error="ACCOUNT_DISABLED",
                        finished_at=datetime.now(timezone.utc).isoformat(),
                    )
                    return

                while not await _wait_campaign_transport_slot(
                    CAMPAIGN_SEND_PENDING_HARD, max_wait=0.35,
                ):
                    current = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
                    if current is None or bool(int(current["stop_requested"] or 0)):
                        multi_update_job(
                            MULTI_ACCOUNT_DB, int(job_id), status="stopped",
                            attempted=attempted, success_count=success,
                            failure_count=failed, skipped_count=skipped,
                            finished_at=datetime.now(timezone.utc).isoformat(),
                        )
                        return
                    await asyncio.sleep(0.05)

                target_id = int(target_row["group_id"] if kind == "group" else target_row["user_id"])
                target_key = (str(kind), int(target_id))
                if target_key in skipped_duplicate_targets:
                    attempted += 1
                    skipped += 1
                    if attempted % 10 == 0:
                        multi_update_job(
                            MULTI_ACCOUNT_DB, int(job_id), attempted=attempted,
                            success_count=success, failure_count=failed,
                            skipped_count=skipped,
                        )
                    continue

                if target_key not in owned_targets:
                    owns_target = await asyncio.to_thread(
                        multi_claim_campaign_target,
                        MULTI_ACCOUNT_DB,
                        batch_id=batch_id, target_kind=str(kind), target_id=int(target_id),
                        account_key=ACCOUNT_KEY, job_id=int(job_id),
                    )
                    if not owns_target:
                        skipped_duplicate_targets.add(target_key)
                        attempted += 1
                        skipped += 1
                        if attempted % 10 == 0:
                            multi_update_job(
                                MULTI_ACCOUNT_DB, int(job_id), attempted=attempted,
                                success_count=success, failure_count=failed,
                                skipped_count=skipped,
                            )
                        continue
                    owned_targets.add(target_key)

                campaign_token = _campaign_send_context.set(True)
                try:
                    await asyncio.wait_for(
                        broadcast_send_target(
                            kind, target_row, content_type, text, media_path,
                            prepared_media=prepared_media,
                        ),
                        timeout=(
                            CAMPAIGN_MEDIA_TARGET_TIMEOUT_SECONDS
                            if content_type != "text"
                            else BROADCAST_SEND_TIMEOUT_SECONDS
                        ),
                    )
                    success += 1
                    if kind == "private":
                        mark_private_campaign_success(target_id)
                    if content_type != "text":
                        log.info(
                            "multi-account campaign media PASS | account=%s job=%s type=%s target=%s:%s preupload=%s",
                            ACCOUNT_KEY, job_id, content_type, kind, target_id, prepared_media is not None,
                        )
                except Exception as exc:
                    failed += 1
                    detail = f"{type(exc).__name__}: {exc}"[:500]
                    log.warning(
                        "multi-account campaign target failed | account=%s job=%s type=%s target=%s:%s | %s",
                        ACCOUNT_KEY, job_id, content_type, kind, target_id, detail,
                    )
                    try:
                        multi_update_job(MULTI_ACCOUNT_DB, int(job_id), last_error=detail)
                    except Exception:
                        pass
                    if kind == "private":
                        try:
                            with db_connect() as con:
                                con.execute(
                                    "UPDATE private_contacts SET failure_count=failure_count+1, last_error=? WHERE user_id=?",
                                    (detail[:300], target_id),
                                )
                                con.commit()
                        except Exception:
                            pass
                    hard_unreachable = (
                        (kind == "group" and _is_group_inaccessible_error(exc))
                        or (kind == "private" and (
                            _is_private_not_found_error(exc)
                            or "PRIVATE_TARGET_UNRESOLVED" in detail
                        ))
                    )
                    if hard_unreachable:
                        try:
                            await asyncio.to_thread(
                                multi_release_campaign_target_claim,
                                MULTI_ACCOUNT_DB,
                                batch_id=batch_id, target_kind=str(kind),
                                target_id=int(target_id), job_id=int(job_id),
                            )
                            owned_targets.discard(target_key)
                        except Exception:
                            pass
                    if kind == "group" and _is_group_inaccessible_error(exc):
                        try:
                            remove_installation_after_departure(target_id)
                        except Exception:
                            pass
                finally:
                    _campaign_send_context.reset(campaign_token)

                attempted += 1
                if attempted % 10 == 0 or attempted == total_targets * round_index:
                    multi_update_job(
                        MULTI_ACCOUNT_DB, int(job_id), attempted=attempted,
                        success_count=success, failure_count=failed,
                        skipped_count=skipped,
                    )
                if attempted % 25 == 0:
                    elapsed = max(0.001, time.monotonic() - send_started)
                    log.info(
                        "multi-account campaign progress | account=%s job=%s processed=%s success=%s failed=%s skipped=%s speed=%.2f/s pending=%s",
                        ACCOUNT_KEY, int(job_id), attempted, success, failed, skipped,
                        float(success) / elapsed, _transport_pending_request_count(client),
                    )
                if CAMPAIGN_INTER_TARGET_DELAY_SECONDS > 0:
                    await asyncio.sleep(CAMPAIGN_INTER_TARGET_DELAY_SECONDS)
                else:
                    await asyncio.sleep(0)

            if round_index < repeats and interval_seconds > 0:
                slept = 0
                while slept < interval_seconds:
                    current = multi_get_job(MULTI_ACCOUNT_DB, int(job_id))
                    if current is None or bool(int(current["stop_requested"] or 0)):
                        multi_update_job(
                            MULTI_ACCOUNT_DB, int(job_id), status="stopped",
                            attempted=attempted, success_count=success,
                            failure_count=failed, skipped_count=skipped,
                            finished_at=datetime.now(timezone.utc).isoformat(),
                        )
                        return
                    chunk = min(5, interval_seconds - slept)
                    await asyncio.sleep(chunk)
                    slept += chunk

        final_status = "failed" if content_type != "text" and attempted > 0 and success == 0 else "done"
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status=final_status,
            attempted=attempted, success_count=success,
            failure_count=failed, skipped_count=skipped,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        elapsed = max(0.001, time.monotonic() - send_started)
        log.info(
            "multi-account campaign DONE | account=%s job=%s processed=%s success=%s failed=%s skipped=%s speed=%.2f/s",
            ACCOUNT_KEY, int(job_id), attempted, success, failed, skipped,
            float(success) / elapsed,
        )
    except CampaignStopRequested:
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status="stopped",
            attempted=attempted, success_count=success,
            failure_count=failed, skipped_count=skipped,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        return
    except asyncio.CancelledError:
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status="stopped",
            attempted=attempted, success_count=success,
            failure_count=failed, skipped_count=skipped,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        raise
    except Exception as exc:
        log.exception("multi-account campaign failed | account=%s job=%s", ACCOUNT_KEY, job_id)
        multi_update_job(
            MULTI_ACCOUNT_DB, int(job_id), status="failed",
            attempted=attempted, success_count=success,
            failure_count=failed, skipped_count=skipped,
            last_error=f"{type(exc).__name__}: {exc}"[:500],
            finished_at=datetime.now(timezone.utc).isoformat(),
        )


async def retry_partial_target_campaign_cleanup() -> bool:
    now = time.monotonic()
    for row in multi_recent_jobs(MULTI_ACCOUNT_DB, 50):
        if str(row["account_key"]) != ACCOUNT_KEY:
            continue
        if str(row["status"] or "") != "target_reached_cleanup_partial":
            continue
        job_id = int(row["job_id"])
        if now < float(_target_cleanup_retry_after.get(job_id, 0.0) or 0.0):
            continue
        _target_cleanup_retry_after[job_id] = now + max(
            TARGET_CLEANUP_RETRY_MIN_SECONDS,
            campaign_delete_circuit_remaining(now),
        )
        multi_update_job(MULTI_ACCOUNT_DB, job_id, status="cleanup")
        _deleted_now, failed = await cleanup_target_campaign_banners(job_id)
        deliveries = multi_campaign_deliveries(MULTI_ACCOUNT_DB, job_id)
        deleted_total = sum(1 for item in deliveries if str(item["status"] or "") == "deleted")
        final_status = "target_reached" if failed == 0 else "target_reached_cleanup_partial"
        multi_update_job(
            MULTI_ACCOUNT_DB, job_id, status=final_status,
            deleted_banner_count=deleted_total, cleanup_failure_count=failed,
            finished_at=datetime.now(timezone.utc).isoformat(),
        )
        if failed == 0:
            _target_cleanup_retry_after.pop(job_id, None)
        return True
    return False


async def multi_account_campaign_worker() -> None:
    log.info(
        "multi account campaign worker READY | account=%s claim=immediate fairness=bounded idle_poll=%.2fs",
        ACCOUNT_KEY, CAMPAIGN_WORKER_IDLE_POLL_SECONDS,
    )
    while True:
        try:
            if not multi_account_runtime_enabled():
                await asyncio.sleep(1.0)
                continue
            # 60.96.28: claim explicit admin jobs immediately. Transport/foreground
            # fairness is enforced per scan page/send RPC, not before the DB claim;
            # this makes Telegram progress leave "queued" promptly even on a
            # permanently busy group network.
            row = multi_claim_next_job(MULTI_ACCOUNT_DB, ACCOUNT_KEY)
            if row is None:
                if (
                    not _routine_background_quiet_period_active()
                    and await retry_partial_target_campaign_cleanup()
                ):
                    await asyncio.sleep(0.2)
                    continue
                await asyncio.sleep(CAMPAIGN_WORKER_IDLE_POLL_SECONDS)
                continue
            log.info(
                "multi account campaign CLAIM | account=%s job=%s batch=%s mode=%s",
                ACCOUNT_KEY, int(row["job_id"]), str(row["batch_id"] or ""),
                str(row["campaign_mode"] or "standard"),
            )
            if (
                str(row["last_error"] or "") == "PROCESS_RECOVERY_REQUEUE"
                and _routine_background_quiet_period_active()
            ):
                multi_update_job(
                    MULTI_ACCOUNT_DB, int(row["job_id"]), status="queued", started_at="",
                )
                await asyncio.sleep(0.8)
                continue
            await run_multi_account_campaign_job(int(row["job_id"]))
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.warning("multi account campaign worker retry | account=%s | %s: %s", ACCOUNT_KEY, type(exc).__name__, exc)
            await asyncio.sleep(2.0)


async def multi_account_heartbeat_worker() -> None:
    while True:
        try:
            groups, privates = multi_account_local_counts()
            connected_attr = getattr(client, "is_connected", True)
            try:
                connected = bool(connected_attr() if callable(connected_attr) else connected_attr)
            except Exception:
                connected = True
            status = "online" if connected and multi_account_runtime_enabled() else ("disabled" if not multi_account_runtime_enabled() else "configured")
            multi_update_heartbeat(
                MULTI_ACCOUNT_DB, account_key=ACCOUNT_KEY, status=status,
                self_id=int(getattr(client, "_self_id", None) or SELF_USER_ID or 0),
                groups_count=groups, private_count=privates, last_error="",
            )
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.debug("multi account heartbeat skipped | %s: %s", type(exc).__name__, exc)
        await asyncio.sleep(10.0)


