def _multi_campaign_batch_progress_text(batch_id: str) -> Tuple[str, Dict[str, Any], bool]:
    rows = list(multi_batch_jobs(MULTI_ACCOUNT_DB, str(batch_id)))
    if not rows:
        return (
            "❌ کمپین پیدا نشد.",
            {"inline_keyboard": [[tg_button("🏠 پنل", "z:home", "primary")]]},
            True,
        )

    labels = {str(r["account_key"]): str(r["label"]) for r in multi_account_rows()}
    statuses = [str(r["status"] or "queued") for r in rows]
    terminal_statuses = {
        "done", "failed", "stopped", "target_reached", "target_not_reached",
        "target_reached_cleanup_partial",
    }
    terminal = all(status in terminal_statuses for status in statuses)
    scanning = any(status == "scanning" for status in statuses)
    running = any(status == "running" for status in statuses)
    queued = any(status == "queued" for status in statuses)

    group_targets = sum(int(r["group_targets"] or 0) for r in rows)
    private_targets = sum(int(r["private_targets"] or 0) for r in rows)
    total_planned = sum(int(r["total_planned"] or 0) for r in rows)
    attempted = sum(int(r["attempted"] or 0) for r in rows)
    success = sum(int(r["success_count"] or 0) for r in rows)
    failed = sum(int(r["failure_count"] or 0) for r in rows)
    skipped = sum(int(r["skipped_count"] or 0) for r in rows)
    remaining = max(0, total_planned - attempted)

    started_candidates: List[datetime] = []
    for r in rows:
        raw = str(r["started_at"] or "").strip()
        if not raw:
            continue
        try:
            started_candidates.append(datetime.fromisoformat(raw.replace("Z", "+00:00")))
        except Exception:
            pass
    elapsed = 0.0
    if started_candidates:
        earliest = min(started_candidates)
        if earliest.tzinfo is None:
            earliest = earliest.replace(tzinfo=timezone.utc)
        elapsed = max(0.0, (datetime.now(timezone.utc) - earliest.astimezone(timezone.utc)).total_seconds())
    speed = (float(success) / elapsed) if elapsed > 0 else 0.0

    if terminal:
        phase = "✅ تمام شد" if all(s == "done" for s in statuses) else "🏁 پایان کمپین"
    elif running:
        phase = "🚀 در حال ارسال"
    elif scanning:
        phase = "🔎 در حال شناسایی گروه و پیوی"
    elif queued:
        phase = "⏳ در صف شروع"
    else:
        phase = "⚙️ در حال پردازش"

    lines = [
        "📣 وضعیت زنده تبلیغات",
        "",
        f"وضعیت: {phase}",
        f"👥 گروه پیدا شده: {group_targets:,}",
        f"👤 پیوی پیدا شده: {private_targets:,}",
    ]
    if total_planned > 0:
        lines.extend([
            f"📦 کل مقصدهای Session: {total_planned:,}",
            f"📨 بررسی‌شده: {attempted:,}",
            f"✅ ارسال موفق: {success:,}",
            f"❌ ناموفق: {failed:,}",
            f"♻️ تکراری بین اکانت‌ها: {skipped:,}",
            f"⏳ باقی‌مانده: {remaining:,}",
            f"⚡ سرعت واقعی: {speed:.1f} پیام/ثانیه",
        ])
    else:
        lines.append("⏳ بعد از پایان Live Scan، تعداد نهایی مقصدها همین‌جا نمایش داده می‌شود.")

    lines.extend(["", "🤖 وضعیت اکانت‌ها:"])
    status_label = {
        "queued": "صف", "scanning": "اسکن", "running": "ارسال",
        "done": "تمام", "failed": "خطا", "stopped": "متوقف",
    }
    for r in rows:
        account = str(r["account_key"])
        label = labels.get(account, account)
        job_total = int(r["total_planned"] or 0)
        job_attempted = int(r["attempted"] or 0)
        lines.append(
            f"• {label}: {status_label.get(str(r['status']), str(r['status']))} | "
            f"G {int(r['group_targets'] or 0):,} / P {int(r['private_targets'] or 0):,} | "
            f"✅{int(r['success_count'] or 0):,} ❌{int(r['failure_count'] or 0):,} "
            f"⏳{max(0, job_total-job_attempted):,}"
        )

    keyboard_rows: List[List[Dict[str, Any]]] = []
    if not terminal:
        for r in rows[:3]:
            if str(r["status"] or "") in {"queued", "scanning", "running", "cleanup", "paused_measurement"}:
                keyboard_rows.append([
                    tg_button(f"⛔ توقف #{int(r['job_id'])}", f"z:mstop:{int(r['job_id'])}", "danger")
                ])
    keyboard_rows.append([tg_button("🧾 کمپین‌ها", "z:campaigns", "primary"), tg_button("🏠 پنل", "z:home", "success")])
    return "\n".join(lines), {"inline_keyboard": keyboard_rows}, terminal


async def tg_multi_campaign_progress_monitor(batch_id: str, chat_id: int, message_id: int) -> None:
    key = str(batch_id)
    last_text = ""
    try:
        while True:
            text, keyboard, terminal = await asyncio.to_thread(
                _multi_campaign_batch_progress_text, key
            )
            if text != last_text:
                try:
                    await tg_edit_text(int(chat_id), int(message_id), text, keyboard)
                    last_text = text
                except Exception as exc:
                    log.warning(
                        "telegram live campaign progress edit skipped | batch=%s | %s: %s",
                        key, type(exc).__name__, exc,
                    )
            if terminal:
                return
            await asyncio.sleep(CAMPAIGN_PROGRESS_REFRESH_SECONDS)
    except asyncio.CancelledError:
        raise
    except Exception as exc:
        log.warning(
            "telegram live campaign progress monitor stopped | batch=%s | %s: %s",
            key, type(exc).__name__, exc,
        )
    finally:
        _tg_multi_campaign_progress_tasks.pop(key, None)


