async def handle_telegram_callback(callback: Dict[str, Any]) -> None:
    from_user = dict(callback.get("from") or {})
    if int(from_user.get("id") or 0) != TELEGRAM_ADMIN_ID:
        await tg_answer_callback(str(callback.get("id") or ""), "دسترسی ندارید")
        return
    message = dict(callback.get("message") or {})
    chat_id = int((message.get("chat") or {}).get("id") or TELEGRAM_ADMIN_ID)
    message_id = int(message.get("message_id") or 0)
    data = str(callback.get("data") or "")
    await tg_answer_callback(str(callback.get("id") or ""))

    if data == "z:home":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "idle"})
        await tg_show_home(chat_id, message_id)
        return
    if data == "z:premium":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_idle", "draft": {}})
        await tg_edit_text(chat_id, message_id, premium_admin_panel_text(), premium_admin_keyboard())
        return
    if data == "z:wallet":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_wallet_idle", "draft": {}})
        await tg_edit_text(chat_id, message_id, premium_wallet_panel_text(), premium_wallet_keyboard())
        return
    if data == "z:wallet:list":
        await tg_edit_text(
            chat_id, message_id, premium_wallet_accounts_text(),
            {"inline_keyboard": [[tg_button("💼 کیف پول", "z:wallet", "primary")], [tg_button("💎 پرمیوم", "z:premium", "primary")]]},
        )
        return
    if data in {"z:wallet:add", "z:wallet:minus", "z:wallet:lookup"}:
        mode = data.rsplit(":", 1)[1]
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_wallet_target", "draft": {"mode": mode}})
        await tg_edit_text(
            chat_id, message_id,
            "👤 آیدی عددی یا username کاربر سروش را بفرست.",
            {"inline_keyboard": [[tg_button("❌ لغو", "z:wallet", "danger")]]},
        )
        return
    if data == "z:wallet:confirm":
        draft = dict(_tg_admin_state.get("draft") or {})
        uid = int(draft.get("user_id") or 0)
        amount = int(draft.get("amount_rial") or 0)
        mode = str(draft.get("mode") or "")
        try:
            delta = amount if mode == "add" else -amount
            result = await asyncio.to_thread(
                premium.adjust_wallet, uid, delta,
                reason=str(draft.get("reason") or "telegram-admin-wallet"), source="telegram-admin",
                admin_id=TELEGRAM_ADMIN_ID, clamp_zero=False,
            )
            _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_wallet_idle", "draft": {}})
            await tg_edit_text(
                chat_id, message_id,
                "✅ کیف پول به‌روزرسانی شد.\n\n"
                f"کاربر: {uid}\n"
                f"تغییر واقعی: {int(result.get('actual_delta_rial') or 0):+,} ریال\n"
                f"موجودی قبلی: {premium.money_rial(result.get('balance_before_rial'))}\n"
                f"موجودی جدید: {premium.money_rial(result.get('balance_after_rial'))}",
                premium_wallet_keyboard(),
            )
        except Exception as exc:
            await tg_edit_text(chat_id, message_id, f"❌ تغییر کیف پول ناموفق بود.\n{type(exc).__name__}: {str(exc)[:180]}", premium_wallet_keyboard())
        return
    if data == "z:paycard":
        await tg_edit_text(chat_id, message_id, premium_card_panel_text(), premium_card_keyboard())
        return
    if data == "z:paycardnum":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_card_number", "draft": {}})
        await tg_edit_text(chat_id, message_id, "🔢 شماره کارت 16 رقمی را بفرست.\nفقط عدد؛ فاصله و خط تیره هم قابل قبول است.", {"inline_keyboard": [[tg_button("❌ لغو", "z:premium", "danger")]]})
        return
    if data == "z:paycardholder":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_card_holder", "draft": {}})
        await tg_edit_text(chat_id, message_id, "👤 نام صاحب کارت را دقیقاً همان‌طور که باید برای خریدار نمایش داده شود بفرست.", {"inline_keyboard": [[tg_button("❌ لغو", "z:premium", "danger")]]})
        return
    if data == "z:paycardtoggle":
        settings = premium.payment_settings()
        new_value = not bool(settings.get("card_enabled"))
        if new_value and not premium.normalize_card_number(settings.get("card_number")):
            await tg_answer_callback(str(callback.get("id") or ""), "اول شماره کارت را تنظیم کن")
        else:
            await asyncio.to_thread(premium.set_setting, "card_enabled", "1" if new_value else "0")
        await tg_edit_text(chat_id, message_id, premium_card_panel_text(), premium_card_keyboard())
        return
    if data == "z:payzibal":
        await tg_edit_text(chat_id, message_id, premium_zibal_panel_text(), premium_zibal_keyboard())
        return
    if data == "z:paymerchant":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_zibal_merchant", "draft": {}})
        await tg_edit_text(chat_id, message_id, "🔑 Merchant زیبال را بفرست.\nاین مقدار فقط داخل دیتابیس کنترل ZIVO ذخیره می‌شود.", {"inline_keyboard": [[tg_button("❌ لغو", "z:premium", "danger")]]})
        return
    if data == "z:paydomain":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_zibal_domain", "draft": {}})
        await tg_edit_text(
            chat_id, message_id,
            "🌐 فقط دامنه‌ای که به همین سرور وصل کردی بفرست.\nمثال:\npay.example.com\n\nZIVO خودش Callback را می‌سازد: \nhttps://pay.example.com/zivo/zibal/callback",
            {"inline_keyboard": [[tg_button("❌ لغو", "z:premium", "danger")]]},
        )
        return
    if data == "z:paycallback":
        _tg_admin_state.clear(); _tg_admin_state.update({"stage": "premium_zibal_callback", "draft": {}})
        await tg_edit_text(chat_id, message_id, "🔗 Callback عمومی زیبال را کامل بفرست.\nمثال:\nhttps://pay.example.com/zivo/zibal/callback", {"inline_keyboard": [[tg_button("❌ لغو", "z:premium", "danger")]]})
        return
    if data == "z:payzibaltoggle":
        settings = premium.payment_settings()
        new_value = not bool(settings.get("zibal_enabled"))
