async def transport_health_worker() -> None:
    """Circuit breaker for stuck SPlusthon pending-state/update streams."""
    global _transport_health_high_pending, _private_recovery_mode_until
    last_total_updates = -1
    stagnant_since = time.monotonic()
    await asyncio.sleep(TRANSPORT_HEALTH_INTERVAL_SECONDS)
    while True:
        try:
            now = time.monotonic()
            pruned_pending, pruned_queue = _prune_finished_transport_requests(client)
            pending = _transport_pending_request_count(client)
            if pruned_pending or pruned_queue:
                log.info(
                    "transport pending hygiene | pending_pruned=%s queue_pruned=%s remaining=%s",
                    pruned_pending, pruned_queue, pending,
                )
            total_updates = int(_perf_counters.get("private_updates", 0)) + int(_perf_counters.get("private_raw_updates", 0)) + int(_perf_counters.get("group_updates", 0))
            if total_updates != last_total_updates:
                last_total_updates = total_updates
                stagnant_since = now

            if pending >= TRANSPORT_PENDING_WARN:
                _transport_health_high_pending += 1
                if _transport_health_high_pending == 1 or _transport_health_high_pending % 3 == 0:
                    log.warning(
                        "transport pressure | pending=%s high_cycles=%s stagnant=%ss",
                        pending, _transport_health_high_pending, int(now - stagnant_since),
                    )
            else:
                _transport_health_high_pending = 0

            # A quiet account can legitimately sit around the warning floor while
            # background RPCs finish. Do not restart a healthy transport merely
            # because there were no inbound updates for 20 seconds.
            if transport_stuck_should_restart(
                pending,
                _transport_health_high_pending,
                now - stagnant_since,
            ):
                _private_recovery_mode_until = max(float(_private_recovery_mode_until or 0.0), now + 180.0)
                _perf_counters["transport_circuit_restarts"] += 1
                log.error(
                    "TRANSPORT HEALTH CIRCUIT | pending=%s high_cycles=%s stagnant=%ss | clean_restart=1",
                    pending, _transport_health_high_pending, int(now - stagnant_since),
                )
                await client.disconnect()
                await close_websocket_cache()
                return
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            log.warning("transport health check skipped | %s: %s", type(exc).__name__, exc)
        await asyncio.sleep(TRANSPORT_HEALTH_INTERVAL_SECONDS)


