async def close_websocket_cache() -> None:
    """
    Final-process cleanup for SPlusthon's aiohttp WebSocket transport.
    Close both the active and cached ClientSession references.
    """
    try:
        connection = getattr(getattr(client, "_sender", None), "_connection", None)
        if connection is None:
            return

        sessions = []
        for attr in ("_session", "_cached_session"):
            session = getattr(connection, attr, None)
            if session is not None and session not in sessions:
                sessions.append(session)

        for session in sessions:
            if not getattr(session, "closed", True):
                try:
                    await asyncio.wait_for(session.close(), timeout=5)
                except Exception as exc:
                    log.debug("aiohttp session cleanup failed: %s", exc)

        connection._session = None
        connection._cached_session = None
        connection._cached_session_key = None

    except Exception as exc:
        log.debug("websocket cache cleanup failed: %s", exc)


async def safe_session_start() -> None:
    """Connect using the existing session without ever entering interactive login.

    A real Soroush transport can briefly reject/fail GetState immediately after
    a deployment cutover or after three account services were stopped together.
    Older builds treated that single transient probe as fatal, which made systemd
    enter RestartSec and caused the installer to report SERVICE DID NOT START.

    Retry only the existing-session connect/GetState path.  We never call the
    high-level interactive ``start()`` method, SendCode or SignIn.
    """
    auth_key = getattr(getattr(client, "session", None), "auth_key", None)
    key_bytes = getattr(auth_key, "key", None)
    key_len = len(key_bytes) if key_bytes else 0
    log.info("session auth_key bytes=%s", key_len)
    if key_len == 0:
        raise RuntimeError("SESSION_AUTH_KEY_MISSING")

    max_attempts = max(1, min(8, int(os.getenv("ZIVO_SESSION_BOOT_ATTEMPTS", "5") or 5)))
    probe_timeout = max(5.0, min(30.0, float(os.getenv("ZIVO_SESSION_BOOT_PROBE_TIMEOUT", "15") or 15)))
    last_exc: Optional[BaseException] = None

    for attempt in range(1, max_attempts + 1):
        try:
            connected_attr = getattr(client, "is_connected", False)
            try:
                connected = bool(connected_attr() if callable(connected_attr) else connected_attr)
            except Exception:
                connected = False
            if not connected:
                await asyncio.wait_for(client.connect(), timeout=probe_timeout)

            state = await asyncio.wait_for(
                client(functions.updates.GetStateRequest()),
                timeout=probe_timeout,
            )
            client._authorized = True

            # Keep our known self id available without users.GetUsersRequest.
            try:
                if not getattr(client, "_self_id", None):
                    client._mb_entity_cache.set_self_user(SELF_USER_ID, False, 0)
            except Exception:
                pass

            log.info(
                "SESSION AUTH PASS | attempt=%s/%s pts=%s qts=%s seq=%s self_id=%s",
                attempt, max_attempts,
                getattr(state, "pts", "?"),
                getattr(state, "qts", "?"),
                getattr(state, "seq", "?"),
                getattr(client, "_self_id", None) or SELF_USER_ID,
            )
            return
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            last_exc = exc
            log.warning(
                "SESSION AUTH PROBE RETRY | attempt=%s/%s | %s: %s",
                attempt, max_attempts, type(exc).__name__, exc,
            )
            try:
                await client.disconnect()
            except Exception:
                pass
            try:
                await close_websocket_cache()
            except Exception:
                pass
            if attempt < max_attempts:
                await asyncio.sleep(min(8.0, 1.5 * attempt))

    raise RuntimeError(
        f"SESSION_AUTH_PROBE_FAILED_AFTER_RETRIES:{type(last_exc).__name__ if last_exc else 'Unknown'}:{last_exc}"
    ) from last_exc


def sync_local_social_private_starts() -> int:
    try:
        with db_connect() as con:
            rows = con.execute("SELECT user_id FROM private_contacts").fetchall()
        return social_games.mark_private_started_batch(
            (int(row["user_id"]) for row in rows), ACCOUNT_KEY
        )
    except Exception as exc:
        log.warning("social private-start migration skipped | %s: %s", type(exc).__name__, exc)
        return 0


async def social_notification_delivery_worker() -> None:
    while True:
        try:
            if not await _wait_transport_background_slot(
                soft_limit=FOREGROUND_BACKGROUND_PENDING_SOFT,
                max_wait=0.5,
            ):
                await asyncio.sleep(0.35)
                continue
            rows = await asyncio.to_thread(social_games.claim_notifications, ACCOUNT_KEY, 5)
            if not rows:
                await asyncio.sleep(2.0)
                continue
            for row in rows:
                notification_id = int(row.get("notification_id") or 0)
                user_id = int(row.get("user_id") or 0)
                try:
                    while not await _wait_transport_background_slot(
                        soft_limit=FOREGROUND_BACKGROUND_PENDING_SOFT,
                        max_wait=1.0,
                    ):
                        await asyncio.sleep(0.10)
                    target = await resolve_private_target(None, user_id)
                    if target is None:
                        raise RuntimeError("SOCIAL_PRIVATE_TARGET_UNAVAILABLE")
                    await send_private(target, str(row.get("text") or ""), verify_delivery=False)
                    await asyncio.to_thread(social_games.finish_notification, notification_id, True, "")
                    log.info("social notification sent | account=%s user=%s id=%s", ACCOUNT_KEY, user_id, notification_id)
                except Exception as exc:
                    await asyncio.to_thread(
                        social_games.finish_notification, notification_id, False,
                        f"{type(exc).__name__}: {exc}",
                    )
                    log.debug("social notification retry | account=%s user=%s id=%s | %s: %s", ACCOUNT_KEY, user_id, notification_id, type(exc).__name__, exc)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("social notification worker error | account=%s", ACCOUNT_KEY)
            await asyncio.sleep(3.0)


async def premium_group_notification_worker() -> None:
    """Deliver subscription activation notices from the shared premium DB.

    Every account sees the queue, but only the account with a local installation
    row for that group may claim/send the notice. This preserves one-account-per-
    group routing while allowing a purchase to originate from any ZIVO PM.
    """
    while True:
        try:
            rows = await asyncio.to_thread(premium.pending_group_notifications, 20)
            handled = False
            for row in rows:
                gid = int(row.get("group_id") or 0)
                nid = int(row.get("notification_id") or 0)
                if gid <= 0 or nid <= 0 or get_installation(gid) is None:
                    continue
                claimed = await asyncio.to_thread(premium.claim_group_notification, nid, ACCOUNT_KEY)
                if not claimed:
                    continue
                handled = True
                try:
                    with db_connect() as con:
                        life = con.execute(
                            "SELECT group_id,peer_kind,group_access_hash FROM group_lifecycle WHERE group_id=?",
                            (gid,),
                        ).fetchone()
                    if life is None:
                        life = {"group_id": gid, "peer_kind": "channel", "group_access_hash": 0}
                    target = await resolve_group_lifecycle_target(life)  # type: ignore[arg-type]
                    if target is None:
                        raise RuntimeError("PREMIUM_GROUP_TARGET_UNAVAILABLE")
                    await send_group_text(target, str(claimed.get("text") or ""))
                    await asyncio.to_thread(premium.finish_group_notification, nid, True, "")
                    log.info("premium group notice sent | account=%s group=%s notification=%s order=%s", ACCOUNT_KEY, gid, nid, int(claimed.get("order_id") or 0))
                except Exception as exc:
                    await asyncio.to_thread(premium.finish_group_notification, nid, False, f"{type(exc).__name__}: {exc}")
                    log.warning("premium group notice retry | account=%s group=%s notification=%s | %s: %s", ACCOUNT_KEY, gid, nid, type(exc).__name__, exc)
            await asyncio.sleep(0.8 if handled else 2.5)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("premium group notification worker error | account=%s", ACCOUNT_KEY)
            await asyncio.sleep(3.0)


async def social_pet_lifecycle_worker() -> None:
    while True:
        try:
            expired = await asyncio.to_thread(social_games.expire_hungry_pets, 200)
            if expired:
                log.info("social pet lifecycle | expired=%s", expired)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception("social pet lifecycle worker error")
        await asyncio.sleep(60.0)



def _ipc_join_row_payload(row: Any) -> Dict[str, Any]:
    if row is None:
        return {"ok": False, "status": "failed", "result_code": "JOB_MISSING", "error": "JOIN_JOB_MISSING"}
    return {
        "ok": str(row["status"] or "") == "done",
        "job_id": int(row["job_id"] or 0),
        "status": str(row["status"] or ""),
        "result_code": str(row["result_code"] or ""),
        "group_id": int(row["result_group_id"] or 0),
        "title": str(row["result_title"] or ""),
        "member_count": int(row["result_member_count"] or -1),
        "joined_now": bool(int(row["joined_now"] or 0)),
        "error": str(row["last_error"] or ""),
        "account_key": ACCOUNT_KEY,
        "account_label": ACCOUNT_LABEL,
    }


def _ipc_remote_row_payload(row: Any) -> Dict[str, Any]:
    if row is None:
        return {"ok": False, "status": "failed", "result_code": "JOB_MISSING", "error": "REMOTE_JOB_MISSING"}
    return {
        "ok": str(row["status"] or "") == "done",
        "job_id": int(row["job_id"] or 0),
        "status": str(row["status"] or ""),
        "result_code": str(row["result_code"] or ""),
        "result_text": str(row["result_text"] or ""),
        "error": str(row["last_error"] or ""),
        "account_key": ACCOUNT_KEY,
        "account_label": ACCOUNT_LABEL,
    }


def _ipc_joined_groups_for_requester(requester_user_id: int, owner_override: bool = False) -> List[Dict[str, Any]]:
    requester = int(requester_user_id or 0)
    if requester <= 0 and not owner_override:
        return []
    con = sqlite3.connect(MULTI_ACCOUNT_DB, timeout=10)
    con.row_factory = sqlite3.Row
    try:
        if owner_override:
            rows = con.execute(
                """
                SELECT job_id, requester_user_id, result_group_id, result_title,
                       result_member_count, result_code, finished_at
                FROM join_jobs
                WHERE target_account=? AND status='done' AND result_group_id>0
                  AND source_account IN ('official_bot','official_ipc','official_socket')
                ORDER BY job_id DESC LIMIT 500
                """,
                (ACCOUNT_KEY,),
            ).fetchall()
        else:
            rows = con.execute(
                """
                SELECT job_id, requester_user_id, result_group_id, result_title,
                       result_member_count, result_code, finished_at
                FROM join_jobs
                WHERE target_account=? AND requester_user_id=?
                  AND status='done' AND result_group_id>0
                  AND source_account IN ('official_bot','official_ipc','official_socket')
                ORDER BY job_id DESC LIMIT 200
                """,
                (ACCOUNT_KEY, requester),
            ).fetchall()
    finally:
        con.close()
    seen: set[int] = set()
    out: List[Dict[str, Any]] = []
    for row in rows:
        gid = int(row["result_group_id"] or 0)
        if gid <= 0 or gid in seen:
            continue
        seen.add(gid)
        installation = get_installation(gid)
        if installation is None:
            try:
                claim = multi_lookup_group_claim(MULTI_ACCOUNT_DB, group_id=gid)
            except Exception:
                claim = None
            if claim is not None and str(claim["account_key"] or "").strip().lower() != ACCOUNT_KEY:
                continue
        out.append({
            "group_id": gid,
            "title": str(row["result_title"] or (installation["group_title"] if installation is not None else "") or ""),
            "member_count": int(row["result_member_count"] or -1),
            "result_code": str(row["result_code"] or ""),
            "account_key": ACCOUNT_KEY,
            "account_label": ACCOUNT_LABEL,
        })
    return out



def _ipc_premium_order_for_user(order_ref: Any, user_id: int) -> Optional[Dict[str, Any]]:
    ref = str(order_ref or "").strip()
    order: Optional[Dict[str, Any]] = None
    if ref.isdigit():
        order = premium.get_order(int(ref))
    if order is None:
        order = premium.get_order_by_code(ref)
    if order is None or int(order.get("buyer_user_id") or 0) != int(user_id or 0):
        return None
    return order


def _ipc_premium_catalog() -> Dict[str, Any]:
    rows = [row for row in premium.all_prices() if int(row.get("enabled") or 0) and int(row.get("amount_rial") or 0) > 0]
    plans: List[Dict[str, Any]] = []
    for plan in (premium.PLAN_SILVER, premium.PLAN_GOLD, premium.PLAN_DIAMOND):
        items = []
        for row in rows:
            if str(row.get("plan") or "") != plan:
                continue
            days = int(row.get("duration_days") or 0)
            amount = int(row.get("amount_rial") or 0)
            items.append({
                "duration_days": days,
                "duration_label": premium.duration_label(days),
                "amount_rial": amount,
                "money_rial": premium.money_rial(amount),
                "money_toman": premium.money_toman(amount),
            })
        plans.append({"plan": plan, "label": premium.plan_label(plan), "prices": items})
    settings = premium.payment_settings()
    return {
        "plans": plans,
        "entitlements": {name: dict(values) for name, values in premium.PLAN_ENTITLEMENTS.items()},
        "payment": {
            "zibal_enabled": bool(settings.get("zibal_enabled") and settings.get("zibal_merchant") and settings.get("zibal_callback_url")),
            "card_enabled": bool(settings.get("card_enabled") and premium.normalize_card_number(settings.get("card_number"))),
            "card_number": premium.normalize_card_number(settings.get("card_number")),
            "card_holder": str(settings.get("card_holder") or ""),
        },
    }


def _ipc_requester_can_control_group(group_id: int, requester_user_id: int) -> bool:
    gid = int(group_id or 0); uid = int(requester_user_id or 0)
    if gid <= 0 or uid <= 0:
        return False
    if uid == int(GLOBAL_BOT_OWNER_ID):
        return True
    try:
        return base_bot_role(gid, uid) in {"مالک", "ادمین"}
    except Exception:
        return False


async def _ipc_requester_can_control_group_live(group: Any, group_id: int, requester_user_id: int) -> bool:
    if _ipc_requester_can_control_group(group_id, requester_user_id):
        return True
    if group is None or int(requester_user_id or 0) <= 0:
        return False
    try:
        user, source, _ = await _verified_requester_admin_from_group(group, int(requester_user_id), 0)
        if user is not None:
            log.info("official requester native access PASS | group=%s requester=%s source=%s", group_id, requester_user_id, source)
            return True
    except Exception as exc:
        log.info("official requester native access inconclusive | group=%s requester=%s | %s", group_id, requester_user_id, type(exc).__name__)
    return False


async def _ipc_inspect_group_link(payload: Dict[str, Any]) -> Dict[str, Any]:
    kind = str(payload.get("link_kind") or "").strip().lower()
    value = str(payload.get("link_value") or "").strip()
    requester = safe_int(payload.get("requester_user_id")) or 0
    if kind not in {"invite", "public"} or not value:
        return {"ok": False, "error": "IPC_INSPECT_REQUEST_INVALID", "account_key": ACCOUNT_KEY}
    try:
        if kind == "invite":
            preview = await asyncio.wait_for(check_invite(value), timeout=8.0)
            if invite_is_broadcast(preview):
                return {"ok": False, "error": "CHANNEL_LINK_NOT_ALLOWED", "account_key": ACCOUNT_KEY}
            group = getattr(preview, "chat", None) if isinstance(preview, types.ChatInviteAlready) else None
            if group is not None and bool(getattr(group, "broadcast", False)):
                return {"ok": False, "error": "CHANNEL_LINK_NOT_ALLOWED", "account_key": ACCOUNT_KEY}
            if group is not None and is_group_entity(group):
                meta = await get_group_metadata(group, preview)
            else:
                meta = {
                    "id": 0,
                    "title": str(getattr(preview, "title", None) or "بدون نام"),
                    "about": str(getattr(preview, "about", None) or "").strip(),
                    "member_count": safe_int(getattr(preview, "participants_count", None)),
                }
            gid = int(meta.get("id") or 0)
            already = isinstance(preview, types.ChatInviteAlready)
            return {
                "ok": True, "account_key": ACCOUNT_KEY, "link_kind": kind,
                "group_id": gid, "title": str(meta.get("title") or "بدون نام"),
                "about": str(meta.get("about") or ""), "member_count": meta.get("member_count"),
                "already_member": already,
                "requester_can_control": (await _ipc_requester_can_control_group_live(group, gid, requester)) if already and gid > 0 else False,
            }
        group = await asyncio.wait_for(resolve_public_group(value.lstrip("@")), timeout=8.0)
        if bool(getattr(group, "broadcast", False)) or not is_group_entity(group):
            return {"ok": False, "error": "CHANNEL_LINK_NOT_ALLOWED", "account_key": ACCOUNT_KEY}
        meta = await asyncio.wait_for(get_group_metadata(group), timeout=10.0)
        gid = int(meta.get("id") or 0)
        installation = get_installation(gid) if gid > 0 else None
        already = installation is not None
        return {
            "ok": True, "account_key": ACCOUNT_KEY, "link_kind": kind,
            "group_id": gid, "title": str(meta.get("title") or "بدون نام"),
            "about": str(meta.get("about") or ""), "member_count": meta.get("member_count"),
            "already_member": already,
            "requester_can_control": (await _ipc_requester_can_control_group_live(group, gid, requester)) if already and gid > 0 else False,
        }
    except (errors.InviteHashInvalidError, errors.InviteHashExpiredError):
        return {"ok": False, "error": "INVITE_INVALID_OR_EXPIRED", "account_key": ACCOUNT_KEY}
    except Exception as exc:
        return {"ok": False, "error": f"{type(exc).__name__}:{exc}"[:500], "account_key": ACCOUNT_KEY}


async def _ipc_premium_dispatch(payload: Dict[str, Any]) -> Dict[str, Any]:
    if not ACCOUNT_IS_CONTROLLER:
        return {"ok": False, "error": "PREMIUM_USE_CONTROLLER", "controller": "main", "account_key": ACCOUNT_KEY}
    action = str(payload.get("action") or "").strip().lower()
    user_id = safe_int(payload.get("requester_user_id")) or 0
    if user_id <= 0:
        return {"ok": False, "error": "PREMIUM_USER_INVALID", "account_key": ACCOUNT_KEY}

    def result_order(order: Dict[str, Any]) -> Dict[str, Any]:
        out = {"ok": True, "order": order, "wallet_balance": premium.wallet_balance(user_id), "payment": _ipc_premium_catalog()["payment"], "account_key": ACCOUNT_KEY}
        if str(order.get("order_kind") or "subscription") == "subscription" and int(order.get("group_id") or 0) > 0:
            out["subscription"] = premium.get_subscription(int(order.get("group_id") or 0), use_cache=False)
        return out

    if action == "catalog":
        result = _ipc_premium_catalog(); result.update({"ok": True, "wallet_balance": premium.wallet_balance(user_id), "account_key": ACCOUNT_KEY}); return result
    if action == "wallet_info":
        return {
            "ok": True,
            "wallet_balance": premium.wallet_balance(user_id),
            "ledger": premium.wallet_ledger(user_id, safe_int(payload.get("limit")) or 12),
            "account_key": ACCOUNT_KEY,
        }
    if action == "status":
        gid = safe_int(payload.get("group_id")) or 0
        if gid <= 0: return {"ok": False, "error": "PREMIUM_GROUP_INVALID", "account_key": ACCOUNT_KEY}
        state = premium.get_subscription(gid, use_cache=False)
        return {"ok": True, "group_id": gid, "subscription": state, "plan_label": premium.plan_label(state.get("plan")), "account_key": ACCOUNT_KEY}
    if action == "my_subscriptions":
        return {"ok": True, "subscriptions": premium.active_subscriptions_for_buyer(user_id, 30), "account_key": ACCOUNT_KEY}
    if action == "history":
        return {"ok": True, "orders": premium.orders_for_user(user_id, 30), "account_key": ACCOUNT_KEY}
    if action == "create_wallet_topup":
        try:
            order = premium.create_wallet_topup_order(user_id, safe_int(payload.get("amount_rial")) or 0)
        except ValueError as exc:
            return {"ok": False, "error": str(exc), "account_key": ACCOUNT_KEY}
        return result_order(order)
    if action == "create_order":
        gid = safe_int(payload.get("group_id")) or 0; title = str(payload.get("group_title") or f"گروه {gid}").strip()[:160]
        plan = premium.normalize_plan(payload.get("plan")); days = safe_int(payload.get("duration_days")) or 0
        if gid <= 0 or plan not in {premium.PLAN_SILVER,premium.PLAN_GOLD,premium.PLAN_DIAMOND} or days not in premium.DURATION_ORDER:
            return {"ok": False, "error": "PREMIUM_ORDER_INVALID", "account_key": ACCOUNT_KEY}
        try: order = premium.create_order(user_id, gid, title, plan, days)
        except ValueError as exc: return {"ok": False, "error": str(exc), "account_key": ACCOUNT_KEY}
        return result_order(order)
    if action == "create_meow_order":
        target = safe_int(payload.get("target_user_id")) or 0; amount = safe_int(payload.get("meow_amount")) or 0
        try: order = premium.create_meow_purchase_order(user_id, target, amount)
        except ValueError as exc: return {"ok": False, "error": str(exc), "account_key": ACCOUNT_KEY}
        out=result_order(order); out.update({"unit_price_rial": premium.MEOW_UNIT_PRICE_RIAL, "money_rial": premium.money_rial(order.get("amount_rial")), "money_toman": premium.money_toman(order.get("amount_rial"))}); return out
    if action == "create_meow_gift_order":
        amount = safe_int(payload.get("meow_amount")) or 0
        try: order = premium.create_meow_gift_order(user_id, amount)
        except ValueError as exc: return {"ok": False, "error": str(exc), "account_key": ACCOUNT_KEY}
        out=result_order(order); out.update({"unit_price_rial": premium.MEOW_UNIT_PRICE_RIAL, "money_rial": premium.money_rial(order.get("amount_rial")), "money_toman": premium.money_toman(order.get("amount_rial"))}); return out
    if action == "discount_set":
        if user_id != int(GLOBAL_BOT_OWNER_ID): return {"ok":False,"error":"FORBIDDEN","account_key":ACCOUNT_KEY}
        try: row=premium.set_discount_code(payload.get("code"),safe_int(payload.get("percent")) or 0)
        except ValueError as exc: return {"ok":False,"error":str(exc),"account_key":ACCOUNT_KEY}
        return {"ok":True,"discount":row,"account_key":ACCOUNT_KEY}
    if action == "discount_remove":
        if user_id != int(GLOBAL_BOT_OWNER_ID): return {"ok":False,"error":"FORBIDDEN","account_key":ACCOUNT_KEY}
        return {"ok":True,"removed":premium.remove_discount_code(payload.get("code")),"account_key":ACCOUNT_KEY}
    if action == "discount_list":
        if user_id != int(GLOBAL_BOT_OWNER_ID): return {"ok":False,"error":"FORBIDDEN","account_key":ACCOUNT_KEY}
        return {"ok":True,"discounts":premium.list_discount_codes(),"account_key":ACCOUNT_KEY}
    if action in {"order","wallet_pay","zibal","card","discount_apply","cancel","check_payment"}:
        order = _ipc_premium_order_for_user(payload.get("order_ref"), user_id)
        if order is None: return {"ok":False,"error":"PREMIUM_ORDER_NOT_FOUND","account_key":ACCOUNT_KEY}
        oid=int(order.get("order_id") or 0); status=str(order.get("status") or "")
        if action == "order": return result_order(order)
        if action == "discount_apply":
            try: updated=premium.apply_discount_code(oid,user_id,payload.get("code"))
            except ValueError as exc: return {"ok":False,"error":str(exc),"order":order,"account_key":ACCOUNT_KEY}
            return result_order(updated)
        if action == "cancel":
            try: updated=premium.cancel_order(oid,user_id)
            except ValueError as exc: return {"ok":False,"error":str(exc),"order":order,"account_key":ACCOUNT_KEY}
            out=result_order(updated); out["cancelled"]=True; return out
        if status == "activated":
            out=result_order(order); out["activated"]=True; return out
        if status in {"rejected","cancelled"}: return {"ok":False,"error":f"ORDER_{status.upper()}","order":order,"account_key":ACCOUNT_KEY}
        if action == "wallet_pay":
            try: activated=premium.pay_order_with_wallet(oid,user_id)
            except ValueError as exc: return {"ok":False,"error":str(exc),"wallet_balance":premium.wallet_balance(user_id),"order":order,"account_key":ACCOUNT_KEY}
            if str(activated.get("order_kind") or "subscription") == "subscription":
                await _premium_queue_activation_announcements(activated,notify_private=False)
            out=result_order(activated); out["activated"]=True; return out
        if action == "zibal":
            ok, result = await _zibal_request_for_order(order)
            if not ok: return {"ok":False,"error":str(result),"order":order,"account_key":ACCOUNT_KEY}
            out=result_order(premium.get_order(oid) or order); out["payment_url"]=str(result); return out
        if action == "card":
            settings=premium.payment_settings(); card=premium.normalize_card_number(settings.get("card_number"))
            if not settings.get("card_enabled") or not card: return {"ok":False,"error":"CARD_PAYMENT_DISABLED","order":order,"account_key":ACCOUNT_KEY}
            refreshed=premium.mark_card_waiting(oid)
            return {"ok":True,"manual_receipt_required":True,"order":refreshed,"card_number":card,"card_holder":str(settings.get("card_holder") or ""),"money_rial":premium.money_rial(refreshed.get("amount_rial")),"amount_rial":int(refreshed.get("amount_rial") or 0),"account_key":ACCOUNT_KEY}
        # manual Zibal verification
        track_id=int(order.get("zibal_track_id") or 0)
        if track_id<=0: return {"ok":True,"activated":False,"pending":True,"order":order,"message":"PAYMENT_NOT_STARTED","account_key":ACCOUNT_KEY}
        ok, verify, message = await _zibal_verify_track(track_id)
        premium.record_event(oid,"zibal_manual_check",track_id,verify or {"message":message})
        if not ok: return {"ok":True,"activated":False,"pending":True,"order":premium.get_order(oid) or order,"message":message,"account_key":ACCOUNT_KEY}
        verified_amount=int(verify.get("amount") or 0); expected=int(order.get("amount_rial") or 0)
        if verified_amount != expected:
            premium.update_order(oid,status="amount_mismatch",zibal_result=int(verify.get("result") or 0)); return {"ok":False,"error":"PAYMENT_AMOUNT_MISMATCH","order":order,"account_key":ACCOUNT_KEY}
        premium.update_order(oid,paid_at=str(verify.get("paidAt") or datetime.now(timezone.utc).isoformat()),gateway_ref_id=str(verify.get("refNumber") or verify.get("refId") or verify.get("cardNumber") or ""),zibal_result=int(verify.get("result") or 100))
        activated=premium.approve_order(oid,"zibal-manual-check")
        if str(activated.get("order_kind") or "subscription") == "subscription": await _premium_queue_activation_announcements(activated,notify_private=False)
        out=result_order(activated); out["activated"]=True; return out
    return {"ok":False,"error":"PREMIUM_ACTION_UNKNOWN","action":action,"account_key":ACCOUNT_KEY}


def _official_managed_group_row(requester: int, group_id: int) -> Optional[Dict[str, Any]]:
    for row in premium.official_managed_groups(int(requester), 500):
        if int(row.get("group_id") or 0) == int(group_id): return dict(row)
    return None


async def _ipc_group_locks_dispatch(payload: Dict[str, Any]) -> Dict[str, Any]:
    requester=safe_int(payload.get("requester_user_id")) or 0; gid=safe_int(payload.get("group_id")) or 0
    if requester<=0 or gid<=0: return {"ok":False,"error":"LOCK_REQUEST_INVALID","account_key":ACCOUNT_KEY}
    access=_official_managed_group_row(requester,gid)
    if access is None and requester != int(GLOBAL_BOT_OWNER_ID): return {"ok":False,"error":"GROUP_NOT_MANAGED_BY_USER","account_key":ACCOUNT_KEY}
    if access is not None and str(access.get("account_key") or "") not in {"",ACCOUNT_KEY} and requester != int(GLOBAL_BOT_OWNER_ID):
        return {"ok":False,"error":"LOCK_WRONG_ACCOUNT","expected_account":str(access.get("account_key") or ""),"account_key":ACCOUNT_KEY}
    action=str(payload.get("action") or "list").strip().lower(); lock_name=str(payload.get("lock_name") or "").strip()
    if action == "list":
        rows=group_lock_rows(gid); items=[]
        for name in LOCK_CATALOG:
            row=rows.get(name)
            if row is None: continue
            items.append({"name":name,"enabled":bool(int(row["enabled"] or 0)),"max_warnings":int(row["max_warnings"] or LOCK_DEFAULT_MAX_WARNINGS),"auto_ban":bool(int(row["auto_ban"] or 0)),"direct_action":str(row["direct_action"] or "warning"),"final_action":str(row["final_action"] or "")})
        plan=premium.plan_for_group(gid)
        return {"ok":True,"group_id":gid,"plan":plan,"advanced_allowed":premium.has_plan(gid,premium.PLAN_GOLD),"locks":items,"account_key":ACCOUNT_KEY}
    if lock_name not in LOCK_CATALOG: return {"ok":False,"error":"LOCK_NAME_INVALID","account_key":ACCOUNT_KEY}
    actor=requester
    if action == "toggle":
        row=group_lock_row(gid,lock_name); enabled=not bool(int(row["enabled"] or 0)) if row is not None else True
        updated=set_group_lock_enabled(gid,lock_name,enabled,actor); return {"ok":True,"lock":dict(updated),"account_key":ACCOUNT_KEY}
    if action in {"warning_delta","autoban_toggle"} and not premium.has_plan(gid,premium.PLAN_GOLD):
        return {"ok":False,"error":"GOLD_REQUIRED_FOR_PER_LOCK_PUNISHMENT","account_key":ACCOUNT_KEY}
    if action == "warning_delta":
        delta=safe_int(payload.get("delta")) or 0; row=group_lock_row(gid,lock_name); current=int(row["max_warnings"] or LOCK_DEFAULT_MAX_WARNINGS) if row is not None else LOCK_DEFAULT_MAX_WARNINGS
        updated=set_group_lock_max_warnings(gid,lock_name,max(1,min(20,current+delta)),actor); return {"ok":True,"lock":dict(updated),"account_key":ACCOUNT_KEY}
    if action == "autoban_toggle":
        row=group_lock_row(gid,lock_name); enabled=not bool(int(row["auto_ban"] or 0)) if row is not None else True
        updated=set_group_lock_auto_ban(gid,lock_name,enabled,actor); return {"ok":True,"lock":dict(updated),"account_key":ACCOUNT_KEY}
    return {"ok":False,"error":"LOCK_ACTION_INVALID","account_key":ACCOUNT_KEY}


async def _ipc_meow_commerce_dispatch(payload: Dict[str, Any]) -> Dict[str, Any]:
    if not ACCOUNT_IS_CONTROLLER: return {"ok":False,"error":"MEOW_USE_CONTROLLER","controller":"main","account_key":ACCOUNT_KEY}
    requester=safe_int(payload.get("requester_user_id")) or 0; action=str(payload.get("action") or "").strip().lower()
    if requester<=0: return {"ok":False,"error":"MEOW_USER_INVALID","account_key":ACCOUNT_KEY}
    try:
        if action == "balance": return {"ok":True,"balance":social_games.meow_balance(requester),"account_key":ACCOUNT_KEY}
        if action == "resolve_target":
            row=premium.official_find_user(payload.get("reference")); return {"ok":bool(row),"user":row,"error":"OFFICIAL_USER_NOT_STARTED" if row is None else "","account_key":ACCOUNT_KEY}
        if action == "transfer_prepare":
            target=safe_int(payload.get("target_user_id")) or 0
            if premium.official_find_user(target) is None: return {"ok":False,"error":"OFFICIAL_USER_NOT_STARTED","account_key":ACCOUNT_KEY}
            return {"ok":True,"transfer":social_games.prepare_transfer_official(requester,target,safe_int(payload.get("meow_amount")) or 0),"account_key":ACCOUNT_KEY}
        if action == "transfer_confirm": return {"ok":True,"transfer":social_games.confirm_transfer_official(requester),"account_key":ACCOUNT_KEY}
        if action == "transfer_cancel": return {"ok":True,"result_text":social_games.cancel_transfer(requester),"account_key":ACCOUNT_KEY}
        if action == "gift_info":
            row=premium.meow_gift_code_info(payload.get("code")); return {"ok":bool(row),"gift":row,"error":"MEOW_GIFT_CODE_NOT_FOUND" if row is None else "","account_key":ACCOUNT_KEY}
        if action == "gift_redeem": return {"ok":True,"gift":premium.redeem_meow_gift_code(payload.get("code"),requester),"account_key":ACCOUNT_KEY}
        if action == "notifications": return {"ok":True,"notifications":premium.pending_official_notifications(100),"account_key":ACCOUNT_KEY}
        if action == "notification_finish": premium.finish_official_notification(safe_int(payload.get("notification_id")) or 0,bool(payload.get("success"))); return {"ok":True,"account_key":ACCOUNT_KEY}
    except ValueError as exc: return {"ok":False,"error":str(exc),"account_key":ACCOUNT_KEY}
    return {"ok":False,"error":"MEOW_ACTION_INVALID","account_key":ACCOUNT_KEY}


async def _account_ipc_dispatch(payload: Dict[str, Any]) -> Dict[str, Any]:
    global _last_priority_event_at
    op = str(payload.get("op") or "").strip().lower()
    if op in {"ping", "status"}:
        return {
            "ok": True,
            "op": op,
            "account_key": ACCOUNT_KEY,
            "account_label": ACCOUNT_LABEL,
            "self_id": int(SELF_USER_ID or 0),
            "enabled": bool(multi_account_runtime_enabled(force_refresh=True)),
            "connected": bool(getattr(client, "is_connected", lambda: False)()),
            "groups_count": len(installed_group_ids()),
            "version": VERSION,
        }
    if op == "groups":
        requester = safe_int(payload.get("requester_user_id")) or 0
        owner_override = bool(payload.get("owner_override")) and requester == int(GLOBAL_BOT_OWNER_ID)
        return {"ok": True, "groups": _ipc_joined_groups_for_requester(requester, owner_override=owner_override)}
    if op == "set_enabled":
        requester = safe_int(payload.get("requester_user_id")) or 0
        if requester != int(GLOBAL_BOT_OWNER_ID):
            return {"ok": False, "error": "FORBIDDEN", "account_key": ACCOUNT_KEY}
        enabled = bool(payload.get("enabled"))
        multi_set_account_enabled(MULTI_ACCOUNT_DB, ACCOUNT_KEY, enabled)
        global _MULTI_ACCOUNT_ENABLED_CACHE_AT
        _MULTI_ACCOUNT_ENABLED_CACHE_AT = 0.0
        return {"ok": True, "account_key": ACCOUNT_KEY, "enabled": enabled}
    if op == "inspect_link":
        return await _ipc_inspect_group_link(payload)
    if op == "official_group_access":
        requester = safe_int(payload.get("requester_user_id")) or 0
        action = str(payload.get("action") or "list").strip().lower()
        if requester <= 0:
            return {"ok": False, "error": "OFFICIAL_GROUP_ACCESS_USER_INVALID", "account_key": ACCOUNT_KEY}
        if action == "list":
            return {"ok": True, "groups": premium.official_managed_groups(requester, 200), "account_key": ACCOUNT_KEY}
        if action == "add":
            gid = safe_int(payload.get("group_id")) or 0
            key = str(payload.get("account_key") or "").strip().lower()
            try:
                row = premium.official_add_managed_group(
                    requester, gid, key, str(payload.get("title") or ""),
                    safe_int(payload.get("member_count")) if payload.get("member_count") is not None else -1,
                )
            except ValueError as exc:
                return {"ok": False, "error": str(exc), "account_key": ACCOUNT_KEY}
            return {"ok": True, "group": row, "account_key": ACCOUNT_KEY}
        return {"ok": False, "error": "OFFICIAL_GROUP_ACCESS_ACTION_INVALID", "account_key": ACCOUNT_KEY}

    if op == "official_payment_admin":
        requester=safe_int(payload.get("requester_user_id")) or 0
        if requester != int(GLOBAL_BOT_OWNER_ID): return {"ok":False,"error":"FORBIDDEN","account_key":ACCOUNT_KEY}
        if not ACCOUNT_IS_CONTROLLER: return {"ok":False,"error":"ADMIN_USE_CONTROLLER","controller":"main","account_key":ACCOUNT_KEY}
        action=str(payload.get("action") or "list").strip().lower()
        try:
            if action=="list": return {"ok":True,"orders":premium.manual_orders(safe_int(payload.get("limit")) or 30,str(payload.get("status") or "")),"account_key":ACCOUNT_KEY}
            if action=="wallet_summary":
                state=premium.summary()
                return {"ok":True,"summary":state,"wallet_count":premium.wallet_account_count(),"account_key":ACCOUNT_KEY}
            if action=="wallet_list":
                limit=safe_int(payload.get("limit")) or 30; offset=max(0,safe_int(payload.get("offset")) or 0)
                return {"ok":True,"wallets":premium.wallet_accounts(limit,offset),"wallet_count":premium.wallet_account_count(),"offset":offset,"account_key":ACCOUNT_KEY}
            if action=="wallet_detail":
                row=premium.wallet_account_detail(payload.get("reference"),safe_int(payload.get("limit")) or 20)
                return {"ok":bool(row),"wallet":row,"error":"WALLET_USER_NOT_FOUND" if row is None else "","account_key":ACCOUNT_KEY}
            if action=="wallet_adjust":
                detail=premium.wallet_account_detail(payload.get("reference"),20)
                if detail is None: return {"ok":False,"error":"WALLET_USER_NOT_FOUND","account_key":ACCOUNT_KEY}
                delta=safe_int(payload.get("delta_rial")) or 0
                reason=str(payload.get("reason") or "").strip()
                if not reason: return {"ok":False,"error":"WALLET_REASON_REQUIRED","account_key":ACCOUNT_KEY}
                result=premium.adjust_wallet(int(detail.get("user_id") or 0),delta,reason=reason,source="soroush-admin",admin_id=requester,clamp_zero=False)
                return {"ok":True,"adjustment":result,"wallet":premium.wallet_account_detail(int(detail.get("user_id") or 0),20),"account_key":ACCOUNT_KEY}
            if action=="detail":
                row=premium.manual_order_detail(payload.get("order_ref")); return {"ok":bool(row),"order":row,"error":"ORDER_NOT_FOUND" if row is None else "","account_key":ACCOUNT_KEY}
            if action=="approve":
                row=premium.admin_approve_manual(safe_int(payload.get("order_id")) or 0,requester)
                buyer=int(row.get("buyer_user_id") or 0); code=str(row.get("order_code") or row.get("order_id") or ""); kind=str(row.get("order_kind") or "subscription")
                if kind=="subscription":
                    await _premium_queue_activation_announcements(row,notify_private=False)
                    notice=f"✅ پرداخت سفارش {code} تأیید شد.\n💎 پلن {str(row.get('plan') or '').upper()} برای «{str(row.get('group_title') or row.get('group_id') or '')}» فعال شد."
                elif kind=="meow_purchase":
                    notice=f"✅ پرداخت سفارش {code} تأیید شد.\n🐱 {int(row.get('meow_amount') or 0):,} Meow برای کاربر {int(row.get('target_user_id') or 0)} شارژ شد."
                elif kind=="meow_gift_code":
                    notice=f"✅ پرداخت سفارش {code} تأیید شد.\n🎁 کد هدیه: {str(row.get('gift_code') or '')}\n🐱 مقدار: {int(row.get('meow_amount') or 0):,} Meow"
                elif kind=="wallet_topup":
                    notice=(f"✅ پرداخت شارژ کیف پول {code} تأیید شد.\n"
                            f"➕ مبلغ شارژ: {int(row.get('amount_rial') or 0):,} ریال\n"
                            f"💰 موجودی جدید: {premium.wallet_balance(buyer):,} ریال")
                else:
                    notice=f"✅ پرداخت سفارش {code} تأیید شد و سفارش فعال شد."
                premium.queue_official_notice(buyer,int(row.get("order_id") or 0),"manual-payment-approved",notice)
                return {"ok":True,"order":row,"account_key":ACCOUNT_KEY}
            if action=="reject":
                row=premium.admin_reject_manual(safe_int(payload.get("order_id")) or 0,requester,str(payload.get("reason_code") or "other"),str(payload.get("reason_text") or ""))
                buyer=int(row.get("buyer_user_id") or 0); code=str(row.get("order_code") or row.get("order_id") or "")
                premium.queue_official_notice(buyer,int(row.get("order_id") or 0),"manual-payment-rejected",f"❌ پرداخت سفارش {code} رد شد.\nدلیل: {str(payload.get('reason_text') or payload.get('reason_code') or 'نامشخص')[:1200]}")
                return {"ok":True,"order":row,"account_key":ACCOUNT_KEY}
            if action=="reverse":
                await asyncio.to_thread(social_games.init_social_db)
                row=premium.admin_reverse_manual(safe_int(payload.get("order_id")) or 0,requester,str(payload.get("reason_code") or "admin-reversal"),str(payload.get("reason_text") or ""))
                buyer=int(row.get("buyer_user_id") or 0); code=str(row.get("order_code") or row.get("order_id") or "")
                premium.queue_official_notice(buyer,int(row.get("order_id") or 0),"manual-payment-reversed",f"↩️ تأیید سفارش {code} توسط مدیریت برگشت داده شد و سرویس/اعتبار مربوط به آن اصلاح شد.")
                return {"ok":True,"order":row,"account_key":ACCOUNT_KEY}
            if action=="receipt_submit":
                row=premium.manual_receipt_submit(safe_int(payload.get("order_id")) or 0,safe_int(payload.get("buyer_user_id")) or 0,str(payload.get("file_id") or ""),safe_int(payload.get("message_id")) or 0,str(payload.get("caption") or ""))
                return {"ok":True,"order":row,"account_key":ACCOUNT_KEY}
        except ValueError as exc: return {"ok":False,"error":str(exc),"account_key":ACCOUNT_KEY}
        return {"ok":False,"error":"OFFICIAL_PAYMENT_ADMIN_ACTION_INVALID","account_key":ACCOUNT_KEY}

    if op == "official_group_customization":
        requester=safe_int(payload.get("requester_user_id")) or 0; gid=safe_int(payload.get("group_id")) or 0
        if requester<=0 or gid<=0: return {"ok":False,"error":"CUSTOMIZATION_REQUEST_INVALID","account_key":ACCOUNT_KEY}
        access=_official_managed_group_row(requester,gid)
        if access is None and requester != int(GLOBAL_BOT_OWNER_ID): return {"ok":False,"error":"GROUP_NOT_MANAGED_BY_USER","account_key":ACCOUNT_KEY}
        action=str(payload.get("action") or "status").strip().lower(); plan=premium.plan_for_group(gid)
        if action.startswith("welcome_") and not premium.has_plan(gid,premium.PLAN_GOLD): return {"ok":False,"error":"GOLD_REQUIRED","account_key":ACCOUNT_KEY}
        if action.startswith("speaker_") and not premium.has_plan(gid,premium.PLAN_SILVER): return {"ok":False,"error":"SILVER_REQUIRED","account_key":ACCOUNT_KEY}
        try:
            if action=="welcome_status": return {"ok":True,"settings":get_welcome_settings(gid),"plan":plan,"account_key":ACCOUNT_KEY}
            if action=="welcome_text": return {"ok":True,"settings":upsert_welcome_settings(gid,requester,enabled=True,custom_text=str(payload.get("text") or "")[:3900]),"account_key":ACCOUNT_KEY}
            if action=="welcome_media_path":
                path=str(payload.get("path") or "").strip();
                if not path or not Path(path).is_file(): return {"ok":False,"error":"WELCOME_MEDIA_PATH_INVALID","account_key":ACCOUNT_KEY}
                return {"ok":True,"settings":upsert_welcome_settings(gid,requester,enabled=True,gif_local_path=path,gif_source_message_id=0,gif_fingerprint=f"official49:{Path(path).name}"),"account_key":ACCOUNT_KEY}
            if action=="welcome_media_remove": return {"ok":True,"settings":upsert_welcome_settings(gid,requester,gif_local_path="",gif_source_message_id=0,gif_fingerprint=""),"account_key":ACCOUNT_KEY}
            if action=="speaker_learn":
                existed,count=upsert_speaker_trigger(gid,requester,str(payload.get("trigger") or ""),str(payload.get("response") or "")); return {"ok":True,"existed":bool(existed),"count":int(count),"account_key":ACCOUNT_KEY}
            if action=="speaker_list": return {"ok":True,"items":[{"trigger":str(r["trigger_display"]),"response":str(r["response_text"])} for r in speaker_trigger_rows(gid)[:50]],"account_key":ACCOUNT_KEY}
            if action=="speaker_delete": return {"ok":True,"removed":delete_speaker_trigger(gid,str(payload.get("trigger") or "")),"account_key":ACCOUNT_KEY}
        except ValueError as exc: return {"ok":False,"error":str(exc),"account_key":ACCOUNT_KEY}
        except RuntimeError as exc: return {"ok":False,"error":str(exc),"account_key":ACCOUNT_KEY}
        return {"ok":False,"error":"CUSTOMIZATION_ACTION_INVALID","account_key":ACCOUNT_KEY}

    if op == "official_admin":
        requester = safe_int(payload.get("requester_user_id")) or 0
        action = str(payload.get("action") or "audience").strip().lower()
        if requester != int(GLOBAL_BOT_OWNER_ID):
            return {"ok": False, "error": "FORBIDDEN", "account_key": ACCOUNT_KEY}
        if not ACCOUNT_IS_CONTROLLER:
            return {"ok": False, "error": "ADMIN_USE_CONTROLLER", "controller": "main", "account_key": ACCOUNT_KEY}
        if action == "audience":
            accounts = []
            for row in multi_list_accounts(MULTI_ACCOUNT_DB):
                accounts.append({
                    "account_key": str(row["account_key"] or ""),
                    "enabled": bool(int(row["enabled"] or 0)),
                    "status": str(row["status"] or ""),
                    "private_count": int(row["private_count"] or 0),
                    "groups_count": int(row["groups_count"] or 0),
                    "last_heartbeat_at": str(row["last_heartbeat_at"] or ""),
                })
            network = telegram_network_inventory_counts()
            return {
                "ok": True, "official": premium.official_broadcast_counts(),
                "account_network": network, "accounts": accounts,
                "active_campaigns": int(multi_active_job_count(MULTI_ACCOUNT_DB)),
                "account_key": ACCOUNT_KEY,
            }
        if action == "official_users":
            return {"ok": True, "user_ids": premium.official_broadcast_user_ids(100000), "account_key": ACCOUNT_KEY}
        if action == "inventory_refresh":
            requested = request_full_inventory_sync_all()
            return {"ok": True, "requested_accounts": requested, "account_key": ACCOUNT_KEY}
        if action == "campaign_create":
            scope=str(payload.get("scope") or "private").strip().lower()
            if scope not in {"private","groups","both"}: return {"ok":False,"error":"CAMPAIGN_SCOPE_INVALID","account_key":ACCOUNT_KEY}
            available={str(r["account_key"] or "").strip().lower():r for r in multi_list_accounts(MULTI_ACCOUNT_DB) if bool(int(r["enabled"] or 0))}
            requested=payload.get("account_keys") or []
            if isinstance(requested,str): requested=[requested]
            keys=[str(k).strip().lower() for k in requested if str(k).strip().lower() in available] if requested else list(available)
            if not keys: return {"ok":False,"error":"NO_ENABLED_ACCOUNTS","account_key":ACCOUNT_KEY}
            content=dict(payload.get("content") or {}); ctype=str(content.get("type") or "text").strip().lower(); text=str(content.get("text") or "")[:3500]
            if ctype not in {"text","photo","video","voice","document"}: return {"ok":False,"error":"CAMPAIGN_CONTENT_INVALID","account_key":ACCOUNT_KEY}
            if ctype=="text" and not text.strip(): return {"ok":False,"error":"CAMPAIGN_TEXT_INVALID","account_key":ACCOUNT_KEY}
            if ctype!="text" and not Path(str(content.get("path") or "")).is_file(): return {"ok":False,"error":"CAMPAIGN_MEDIA_MISSING","account_key":ACCOUNT_KEY}
            multi_supersede_standard_jobs(MULTI_ACCOUNT_DB,keys,reason="SUPERSEDED_BY_OFFICIAL17_ADMIN")
            batch_id=f"official17-{int(time.time())}-{random.randint(1000,9999)}"
            job_ids=multi_create_campaign_jobs(MULTI_ACCOUNT_DB,batch_id=batch_id,account_keys=keys,scope=scope,content={"type":ctype,"text":text,"path":str(content.get("path") or "")},repeat_count=1,interval_seconds=0,campaign_mode="standard")
            return {"ok":True,"batch_id":batch_id,"job_ids":job_ids,"accounts":keys,"scope":scope,"content_type":ctype,"account_key":ACCOUNT_KEY}
        if action == "campaign_status":
            batch_id = str(payload.get("batch_id") or "").strip(); batch_ids=payload.get("batch_ids") or []
            rows=[]
            if isinstance(batch_ids,list) and batch_ids:
                for bid in batch_ids[:20]: rows.extend(multi_batch_jobs(MULTI_ACCOUNT_DB,str(bid)))
            elif batch_id: rows=multi_batch_jobs(MULTI_ACCOUNT_DB,batch_id)
            else: rows=multi_recent_jobs(MULTI_ACCOUNT_DB,20)
            return {"ok":True,"jobs":[dict(r) for r in rows],"account_key":ACCOUNT_KEY}
        if action == "campaign_stop":
            batch_id = str(payload.get("batch_id") or "").strip()
            rows = multi_batch_jobs(MULTI_ACCOUNT_DB, batch_id) if batch_id else []
            for row in rows:
                multi_request_job_stop(MULTI_ACCOUNT_DB, int(row["job_id"]))
            return {"ok": True, "stopped": len(rows), "account_key": ACCOUNT_KEY}
        return {"ok": False, "error": "OFFICIAL_ADMIN_ACTION_INVALID", "account_key": ACCOUNT_KEY}

    if op == "official_admin_user":
        requester = safe_int(payload.get("requester_user_id")) or 0
        action = str(payload.get("action") or "").strip().lower()
        if requester <= 0:
            return {"ok": False, "error": "OFFICIAL_USER_INVALID", "account_key": ACCOUNT_KEY}
        if action == "broadcast_off":
            return {"ok": True, "state": premium.official_set_broadcast_enabled(requester, False), "account_key": ACCOUNT_KEY}
        if action == "broadcast_on":
            return {"ok": True, "state": premium.official_set_broadcast_enabled(requester, True), "account_key": ACCOUNT_KEY}
        return {"ok": False, "error": "OFFICIAL_ADMIN_USER_ACTION_INVALID", "account_key": ACCOUNT_KEY}

    if op == "official_gate":
        requester = safe_int(payload.get("requester_user_id")) or 0
        action = str(payload.get("action") or "status").strip().lower()
        if requester <= 0:
            return {"ok": False, "error": "OFFICIAL_GATE_USER_INVALID", "account_key": ACCOUNT_KEY}
        if action == "status":
            state = premium.official_user_state(requester)
        elif action == "seen":
            state = premium.official_user_mark_seen(requester, username=payload.get("username"), first_name=payload.get("first_name"))
        elif action == "pass":
            state = premium.official_user_pass_gate(requester, username=payload.get("username"), first_name=payload.get("first_name"))
        else:
            return {"ok": False, "error": "OFFICIAL_GATE_ACTION_INVALID", "account_key": ACCOUNT_KEY}
        return {"ok": True, "state": state, "account_key": ACCOUNT_KEY}

    if op == "membership_check":
        requester = safe_int(payload.get("requester_user_id")) or 0
        if requester <= 0:
            return {"ok": False, "error": "MEMBERSHIP_REQUEST_INVALID", "account_key": ACCOUNT_KEY}
        allowed, missing, unknown = await check_required_membership(requester)
        return {"ok": True, "allowed": bool(allowed), "missing": list(missing), "unknown": list(unknown), "channels": list(REQUIRED_CHANNELS), "account_key": ACCOUNT_KEY}
    if op == "official_group_locks":
        return await _ipc_group_locks_dispatch(payload)
    if op == "meow_commerce":
        return await _ipc_meow_commerce_dispatch(payload)
    if op == "social":
        requester = safe_int(payload.get("requester_user_id")) or 0
        text = str(payload.get("command_text") or "").strip()
        if requester <= 0 or not text:
            return {"ok": False, "error": "SOCIAL_REQUEST_INVALID", "account_key": ACCOUNT_KEY}
        parsed = social_games.parse_social_command(text, user_id=requester)
        if parsed is None:
            return {"ok": False, "error": "SOCIAL_COMMAND_UNKNOWN", "account_key": ACCOUNT_KEY}
        premium_group_id = safe_int(payload.get("group_id")) or 0
        action = str(parsed.get("action") or "")
        if action == "meow_claim":
            luck = premium.meow_luck_multiplier(premium_group_id) if premium_group_id > 0 else 1.0
            result_text = social_games.claim_meow(requester, luck)
        elif action == "meow_profile": result_text = "ZIVO | دارایی من\n" + social_games.profile_section(requester)
        else:
            calls = {
                "pet_shop": (social_games.pet_shop_text, ()),
                "pet_buy": (social_games.buy_pet, (requester, str(parsed.get("spec") or ""), premium.pet_discount_percent(premium_group_id) if premium_group_id > 0 else 0)),
                "pet_status": (social_games.pet_status, (requester,)),
                "pet_name": (social_games.name_pet, (requester, str(parsed.get("name") or ""))),
                "pet_feed": (social_games.feed_pet, (requester,)),
                "pet_play": (social_games.play_with_pet, (requester,)),
                "pet_call": (social_games.pet_call, (requester, str(parsed.get("call") or "name"))),
                "house_shop": (social_games.house_shop_text, ()),
                "house_mine": (social_games.my_houses_text, (requester,)),
                "house_market": (social_games.house_marketplace_text, ()),
                "house_buy": (social_games.buy_house, (requester, str(parsed.get("spec") or ""))),
                "house_sell_instant": (social_games.instant_sell_house, (requester, int(parsed.get("ownership_id") or 0))),
                "house_list": (social_games.list_house, (requester, int(parsed.get("ownership_id") or 0), int(parsed.get("price") or 0))),
                "house_cancel_listing": (social_games.cancel_house_listing, (requester, int(parsed.get("listing_id") or 0))),
                "house_buy_listing": (social_games.buy_listed_house, (requester, int(parsed.get("listing_id") or 0))),
            }
            if action in calls:
                fn, args = calls[action]
                result_text = fn(*args)
            elif action in {"ttt_start","ttt_join","ttt_cancel","ttt_status","ttt_move","ship","wager_start","wager_accept","wager_cancel"}:
                result_text = "این فرمان گروهی است؛ گروه را در پنل انتخاب کن و از فرمان آزاد اجرا کن."
            else:
                result_text = "این بخش هنوز از مسیر خصوصی پنل پشتیبانی نمی‌شود."
        return {"ok": True, "result_text": str(result_text), "account_key": ACCOUNT_KEY}
    if op == "premium":
        return await _ipc_premium_dispatch(payload)
    if op == "join":
        if not multi_account_runtime_enabled(force_refresh=True):
            return {"ok": False, "status": "failed", "result_code": "ACCOUNT_DISABLED", "error": "ACCOUNT_DISABLED", "account_key": ACCOUNT_KEY}
        kind = str(payload.get("link_kind") or "").strip().lower()
        value = str(payload.get("link_value") or "").strip()
        requester = safe_int(payload.get("requester_user_id")) or 0
        source_message_id = safe_int(payload.get("source_message_id")) or 0
        if kind not in {"invite", "public"} or not value or requester <= 0:
            return {"ok": False, "status": "failed", "result_code": "BAD_REQUEST", "error": "IPC_JOIN_REQUEST_INVALID", "account_key": ACCOUNT_KEY}
        _last_priority_event_at = time.monotonic()
        job_id = multi_create_join_job(
            MULTI_ACCOUNT_DB,
            source_account="official_socket",
            target_account=ACCOUNT_KEY,
            requester_user_id=requester,
            source_message_id=source_message_id,
            link_kind=kind,
            link_value=value,
        )
        # This request runs in the same asyncio loop as the account worker. Mark
        # it running before the first await, so the background queue can never
        # claim the same job.
        multi_update_join_job(
            MULTI_ACCOUNT_DB, int(job_id), status="running",
            started_at=datetime.now(timezone.utc).isoformat(), last_error="",
        )
        started = time.monotonic()
        await run_multi_account_join_job(int(job_id))
        row = multi_get_join_job(MULTI_ACCOUNT_DB, int(job_id))
        result = _ipc_join_row_payload(row)
        result["requester_can_control"] = _ipc_requester_can_control_group(int(result.get("group_id") or 0), requester)
        result["elapsed_ms"] = round((time.monotonic() - started) * 1000.0, 1)
        log.info("official socket join result | account=%s job=%s code=%s elapsed_ms=%.1f", ACCOUNT_KEY, job_id, result.get("result_code"), result["elapsed_ms"])
        return result
    if op == "control_enqueue":
        requester = safe_int(payload.get("requester_user_id")) or 0
        gid = safe_int(payload.get("group_id")) or 0
        command = str(payload.get("command_text") or "").strip()
        target_user = safe_int(payload.get("target_user_id")) or 0
        target_message = safe_int(payload.get("target_message_id")) or 0
        if requester <= 0 or gid <= 0 or not command:
            return {"ok": False, "result_code": "BAD_REQUEST", "error": "IPC_CONTROL_REQUEST_INVALID", "account_key": ACCOUNT_KEY}
        _last_priority_event_at = time.monotonic()
        job_id = multi_create_remote_control_job(
            MULTI_ACCOUNT_DB, target_account=ACCOUNT_KEY, requester_user_id=requester,
            group_id=gid, command_text=command, target_user_id=target_user,
            target_message_id=target_message,
        )
        return {
            "ok": True, "status": "queued", "result_code": "QUEUED",
            "job_id": int(job_id), "account_key": ACCOUNT_KEY,
            "result_text": "فرمان در صف سریع ZIVO قرار گرفت.",
        }
    if op == "control_status":
        requester = safe_int(payload.get("requester_user_id")) or 0
        job_id = safe_int(payload.get("job_id")) or 0
        if requester <= 0 or job_id <= 0:
            return {"ok": False, "result_code": "BAD_REQUEST", "error": "IPC_CONTROL_STATUS_INVALID", "account_key": ACCOUNT_KEY}
        row = multi_get_remote_control_job(MULTI_ACCOUNT_DB, int(job_id))
        if row is None or int(row["requester_user_id"] or 0) != requester or str(row["target_account"] or "").strip().lower() != ACCOUNT_KEY:
            return {"ok": False, "result_code": "NOT_FOUND", "error": "CONTROL_JOB_NOT_FOUND", "account_key": ACCOUNT_KEY}
        result = _ipc_remote_row_payload(row)
        result["ok"] = str(row["status"] or "") in {"queued", "running", "done"}
        result["job_id"] = int(job_id)
        result["account_key"] = ACCOUNT_KEY
        return result
    if op == "control":
        requester = safe_int(payload.get("requester_user_id")) or 0
        gid = safe_int(payload.get("group_id")) or 0
        command = str(payload.get("command_text") or "").strip()
        target_user = safe_int(payload.get("target_user_id")) or 0
        target_message = safe_int(payload.get("target_message_id")) or 0
        if requester <= 0 or gid <= 0 or not command:
            return {"ok": False, "status": "failed", "result_code": "BAD_REQUEST", "error": "IPC_CONTROL_REQUEST_INVALID", "account_key": ACCOUNT_KEY}
        _last_priority_event_at = time.monotonic()
        job_id = multi_create_remote_control_job(
            MULTI_ACCOUNT_DB,
            target_account=ACCOUNT_KEY,
            requester_user_id=requester,
            group_id=gid,
            command_text=command,
            target_user_id=target_user,
            target_message_id=target_message,
        )
        multi_update_remote_control_job(
            MULTI_ACCOUNT_DB, int(job_id), status="running",
            started_at=datetime.now(timezone.utc).isoformat(), last_error="",
        )
        started = time.monotonic()
        await run_remote_control_job(int(job_id))
        row = multi_get_remote_control_job(MULTI_ACCOUNT_DB, int(job_id))
        # One activation requeue is possible. Resolve it synchronously for the
        # official panel instead of returning "queued" to the user.
        deadline = time.monotonic() + 12.0
        while row is not None and str(row["status"] or "") == "queued" and time.monotonic() < deadline:
            multi_update_remote_control_job(
                MULTI_ACCOUNT_DB, int(job_id), status="running",
                started_at=datetime.now(timezone.utc).isoformat(),
            )
            await run_remote_control_job(int(job_id))
            row = multi_get_remote_control_job(MULTI_ACCOUNT_DB, int(job_id))
            if row is not None and str(row["status"] or "") == "queued":
                await asyncio.sleep(0.25)
        result = _ipc_remote_row_payload(row)
        result["elapsed_ms"] = round((time.monotonic() - started) * 1000.0, 1)
        log.info("official socket control result | account=%s job=%s code=%s elapsed_ms=%.1f", ACCOUNT_KEY, job_id, result.get("result_code"), result["elapsed_ms"])
        return result
    return {"ok": False, "error": "IPC_OP_UNKNOWN", "op": op, "account_key": ACCOUNT_KEY}


async def _account_ipc_client(reader: asyncio.StreamReader, writer: asyncio.StreamWriter) -> None:
    peer = writer.get_extra_info("peername")
    try:
        raw = await asyncio.wait_for(reader.readline(), timeout=ACCOUNT_IPC_REQUEST_TIMEOUT)
        if not raw:
            return
        if len(raw) > ACCOUNT_IPC_MAX_FRAME_BYTES:
            raise ValueError("IPC_REQUEST_TOO_LARGE")
        payload = json.loads(raw.decode("utf-8"))
        if not isinstance(payload, dict):
            raise ValueError("IPC_REQUEST_INVALID")
        result = await asyncio.wait_for(_account_ipc_dispatch(payload), timeout=ACCOUNT_IPC_REQUEST_TIMEOUT)
    except asyncio.TimeoutError:
        result = {"ok": False, "error": "IPC_TIMEOUT", "account_key": ACCOUNT_KEY}
    except Exception as exc:
        log.warning("account IPC request failed | account=%s peer=%s | %s: %s", ACCOUNT_KEY, peer, type(exc).__name__, exc)
        result = {"ok": False, "error": f"{type(exc).__name__}: {exc}"[:500], "account_key": ACCOUNT_KEY}
    try:
        data = (json.dumps(result, ensure_ascii=False, separators=(",", ":")) + "\n").encode("utf-8")
        writer.write(data[:ACCOUNT_IPC_MAX_FRAME_BYTES])
        await writer.drain()
    finally:
        writer.close()
        try:
            await writer.wait_closed()
        except Exception:
            pass


async def start_account_ipc_server() -> Optional[asyncio.AbstractServer]:
    if not ACCOUNT_IPC_ENABLED:
        log.info("official IPC disabled | account=%s", ACCOUNT_KEY)
        return None
    ACCOUNT_IPC_DIR.mkdir(parents=True, exist_ok=True)
    try:
        ACCOUNT_IPC_DIR.chmod(0o700)
    except Exception:
        pass
    try:
        ACCOUNT_IPC_SOCKET.unlink(missing_ok=True)
    except Exception:
        pass
    server = await asyncio.start_unix_server(_account_ipc_client, path=str(ACCOUNT_IPC_SOCKET), backlog=32)
    try:
        ACCOUNT_IPC_SOCKET.chmod(0o600)
    except Exception:
        pass
    log.info("official IPC ready | account=%s socket=%s protocol=json-line direct-join+direct-control", ACCOUNT_KEY, ACCOUNT_IPC_SOCKET)
    return server



